pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" zone
    // (too small for the smallest plausible item) are heavily penalized.
    let min_item = 1.0f64;
    let dead_threshold = 20.0f64;
    if (post_residual as f64) > 0.0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that can still hold the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Lookahead won't fit here: penalize proportionally to waste.
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Reward using this bin when it's the last chance before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins early.
    score += open_bins_count as f64 * 1.2;

    // Slight preference for bins below mean residual (consolidate slack).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Late-stream tightening: accept looser fits as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: unusable gaps (< 10, or too small for
    // anything useful) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Penalize small-but-nonzero residuals that cannot fit the next item
    // (likely dead space) unless the next item fits elsewhere anyway.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let deadness = (next_item_size - post_residual) as f64;
        score += 1.5 * deadness;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the lookahead item.
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new bin is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (bin_capacity as f64 * 2.0);
    score += pressure * (10.0 + 40.0 * progress);

    // New-bin candidate: baseline slightly below mean residual so we only
    // open a new bin when existing bins are fragmented.
    if bin_residual == bin_capacity {
        score = mean_residual * 0.5 + 20.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // Opening a fresh bin is fine if the next item is large too.
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 500.0; // must open the first bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this placement sets up a perfect follow-up fit.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 800.0;
        } else if post >= nxt {
            // next item fits: mild reward proportional to how snug the chain is
            score -= 200.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item will NOT fit into leftover: penalize dead space
            score += 150.0 * (1.0 - post / bin_capacity as f64);
        }
    }

    // Compare against mean residual: leaving post_residual near the mean keeps
    // bins homogeneous; very small leftovers are wasted capacity.
    if post_residual > 0 {
        let mdiff = (post_residual as f64 - mean_residual).abs();
        score += 0.5 * mdiff;
        if (post_residual as f64) < mean_residual * 0.25 {
            score += 60.0; // small unusable sliver
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // (i.e., this is a fresh bin and existing bins are crowded).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (next_item_size > 0 && (post_residual as f64) >= next_item_size as f64);
        if poor_fit_elsewhere {
            score -= 250.0 + 100.0 * progress + 20.0 * crowd;
        } else {
            score += 400.0; // discourage opening new bins when decent fits exist
        }
    }

    // Late-stream consolidation: prefer tighter packing as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 10) are pure waste; penalize quadratically.
    if post_residual < 10 {
        score += 60.0 + (post_residual as f64) * (post_residual as f64) * 2.0;
    } else if post_residual < 20 {
        // Small gap zone: partially unusable, penalize proportionally.
        score += (20.0 - post_residual as f64) * 2.5;
    } else {
        // Usable residual: reward proportionally to how much of the bin was filled.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 25.0;
    }

    // Perfect or near-perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // and encourage consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 4.0 * (0.5 + progress);
    score += pressure;

    // New-bin candidate handling: attractive early or when no open bin has
    // a decent fit; unattractive when open bins are roomy.
    if bin_residual == bin_capacity {
        score = 15.0 + pressure;
        if mean_residual < 25.0 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, prefer closing out existing bins.
        score += progress * 12.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward
    // this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Mild preference toward bins below the mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    // Anything below 10 (minimum item size) is guaranteed dead space.
    if post_residual < 10 {
        score += 500.0;
    } else if post_residual <= 20 {
        // Small gaps are only useful for small items; penalize proportionally.
        score += (20.0 - post_residual as f64) * 8.0;
    }

    // Perfect fit reward: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Penalize leaving a gap that the lookahead item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 3.0;
    }

    // Reward placements where the next item fits snugly into the new residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size as u32) as f64;
        score -= 2.0 / (1.0 + snug);
    }

    // Open-bin pressure: discourage scattering across many open bins.
    score += open_bins_count as f64 * 2.5;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make it less attractive unless it enables a good pair.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if the next item pairs perfectly with the current one in a fresh bin,
        // opening a new bin is fine.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 60.0;
        }
    }

    // Progress-based adjustment: later in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Prefer bins below mean residual (tighter bins) for large fills.
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot fit even the smallest plausible item is "dead".
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 18.0;
    }

    // Reward very tight fits (best-fit amplification).
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> penalize spreading, encourage filling.
    let pressure = open_bins_count as f64 * 1.5;
    if bin_residual != bin_capacity {
        score += pressure;
    }

    // New-bin candidate: only attractive when item leaves a large, reusable gap
    // or when existing bins would create dead space.
    if bin_residual == bin_capacity {
        score += 25.0; // default mild penalty for opening a new bin
        if post_residual as f64 >= mean_residual + 30.0 {
            score -= 40.0; // large reusable gap justifies a fresh bin
        }
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would be blocked by a near-dead residual, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // Late in the stream, favor consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    // Mild preference for bins already below mean residual (fill emptier bins first).
    if bin_residual as f64 > mean_residual {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.35 * tightness * (bin_residual as f64);

    // Penalize dead space that cannot fit typical future items (dead zone below ~ item_size).
    if post_residual > 0 && post_residual < item_size {
        score += 6.0 * (item_size - post_residual) as f64;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize more if leftover is small (waste)
            score += 3.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer fuller bins when many bins are open (reduce fragmentation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * (open_bins_count as f64).sqrt() * 2.0;

    // Time horizon: early in stream, be more willing to open new bins for large items
    // (keep flexibility); late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (10.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64) - 4.0 * progress);

    // Prefer bins whose residual is near the mean (balanced packing) early on.
    score += 0.5 * ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64) * (1.0 - progress);

    // Slight penalty for opening new bins when many already open.
    score += new_bin * 0.15 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor small post_residual, superlinearly.
    let pr = post_residual as f64;
    score += (pr * pr) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class logic: classify residual into capacity-fraction bands.
    // Residuals that are "waste classes" (small unusable slivers) are penalized.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual > 0 {
        if post_residual < 10 {
            // Dead sliver: nearly unusable for typical items -> heavy penalty.
            score += 60.0;
        } else if post_residual < quarter {
            // Small class: only fits tiny items (1..=9 are rare-ish); mild penalty.
            score += 25.0;
        } else if post_residual < half {
            // Medium class: usable for many items; slight bonus.
            score -= 5.0;
        } else {
            // Large class: plenty of room left; bonus scaled to size.
            score -= 12.0;
        }
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // Extra reward if next item then leaves a good residual too.
        let next_post = post_residual - next_item_size;
        score -= (next_post as f64) / 10.0;
        if next_post == 0 {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: slight penalty for chaining badly.
        score += 8.0;
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // is large relative to residuals or existing bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 70.0;
        // Cheaper to open a new bin when many bins are already open and crowded.
        score -= (open_bins_count as f64) * 1.5;
        // If the item is large, a fresh bin is more attractive.
        score -= (item_size as f64) * 0.4;
        // If mean residual can't hold the item comfortably, new bin is fine.
        if (mean_residual < item_size as f64) {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Modulo harmonic touch: residuals congruent to typical item sizes (multiples of 5/10)
    // are more likely reusable; give a small discount.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: perfect match with next item is gold ---
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // exact match: strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // closeness to next item's size is rewarded proportionally
            score -= (30.0 / (1.0 + diff / 10.0)) * 0.5;
        }
        // penalize dead space that can't fit the next item at all
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // small leftover below typical minimum item size is dead space
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
    } else {
        // last item: prefer tightest fit
        score *= 1.5;
    }

    // --- relative-to-mean coupling ---
    // bins with residual below mean are "valuable" compact bins; using them
    // for a tight fit is good, but wasting them on a loose fit is bad.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    } else {
        score += (res - mean_residual) * 0.15;
    }

    // --- last-chance bin: if this is the only bin that fits, use it ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // --- new-bin candidate handling ---
    if bin_residual == bin_capacity {
        // opening a new bin is attractive when existing bins are fragmented
        // (high mean residual spread / many open bins) or the fit is loose.
        let fragmentation = (res / bin_capacity as f64) - (mean_residual / bin_capacity as f64);
        score -= 15.0 + open_bins_count as f64 * 1.5 + fragmentation * 20.0;
        // but discourage new bins early in the stream when consolidation is possible
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 12.0;
        // if next item fits perfectly in this fresh bin's residual (capacity), mild bonus
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // --- mild pressure against accumulating too many open bins ---
    score += open_bins_count as f64 * 0.4;

    // --- prefer bins whose residual is only slightly larger than the item ---
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward a residual that exactly fits the next item.
    let next = next_item_size as f64;
    if next > 0.0 {
        let diff = (post_residual as f64 - next).abs();
        score -= 300.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Exact 2-step match: chain placement, extremely desirable.
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Penalize residuals too small for the next item (dead space risk),
        // scaled by how close post_residual is to being useless.
        if (post_residual as u32) < next_item_size {
            score += 50.0 + 2.0 * (next - post_residual as f64);
        }
    }

    // Relative-to-mean coupling: bins with residuals near the mean are "normal";
    // leaving a post_residual far below mean wastes capacity relative to fleet.
    let cap = bin_capacity as f64;
    let mean_frac = (mean_residual / cap).clamp(0.0, 1.0);
    let post_frac = post_residual as f64 / cap;
    score += 40.0 * (mean_frac - post_frac).abs();

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Penalize tiny unusable residuals (fragmentation), non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Mild pressure toward consolidating into fewer bins early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (small, unusable gap)
    // is heavily penalized, since no future item (min size 1..10) can realistically use it.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if (post_residual as f64) <= dead_threshold {
        score -= 5.0; // mild bonus for filling down into the dead zone
    }

    // Penalize leaving a gap that barely misses fitting the next item (lookahead waste).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 + 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving a gap that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer packing into existing bins
    // rather than spreading; with few bins, spreading is cheaper.
    let pressure = open_bins_count as f64;
    score += pressure * 1.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when the current
    // bin would leave a large, awkward residual or when open-bin pressure is high.
    if bin_residual == bin_capacity {
        // Neutral baseline for a fresh bin: its residual is maximal.
        score = bin_capacity as f64 * 0.9;
        // Discourage opening new bins when existing bins fit decently.
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // Allow new bins when existing bins are nearly full on average.
        score -= mean_residual * 0.3;
        // Late in the stream, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Deviation from mean residual: prefer bins whose residual is below average
    // (they are the "fuller" bins), closing them out sooner.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the leftover space exactly
    // matches the next item, or when the next item can still fit.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            score -= 150.0 * (post_residual as f64 / next_item_size as f64).min(2.0);
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 60.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64 * 100.0;
        }
    }

    // Compare post_residual against mean residual: prefer keeping the
    // residual profile homogeneous (easy to fill later).
    let pr = post_residual as f64;
    score += 0.8 * (pr - mean_residual).abs();

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate: only attractive when existing fits are terrible
    // (large dead space) or the item nearly fills an empty bin.
    if bin_residual == bin_capacity {
        let waste_existing = if fitting_bins_count > 0 {
            (bin_capacity - item_size) as f64
        } else {
            0.0
        };
        let _ = waste_existing;
        let near_full = item_size as f64 >= 0.9 * bin_capacity as f64;
        if near_full {
            score -= 400.0;
        } else {
            score += 350.0 + 2.0 * (bin_capacity - item_size) as f64;
        }
    }

    // Mild early-stream bonus for consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * (1.0 - progress) * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let size_frac = item_size as f64 / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping.
    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // later in the stream, waste is penalized more aggressively.
    let prog_penalty = norm_pr * norm_pr * (0.5 + 2.0 * progress) * cap;
    score += prog_penalty;

    // Cubic dead-space term: small residuals that are hard to reuse later.
    let dead = if pr > 0.0 {
        let inv = cap / pr;
        cap * 0.5 / (inv * inv)
    } else {
        0.0
    };
    score -= dead * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor the only bin that fits, scaled by progress.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 40.0 * progress + 10.0 * size_frac;
    }

    // Prefer bins whose residual is below mean (filling fuller bins first),
    // with smooth interaction against progress.
    let mean_gap = (mean_residual - bin_residual as f64) / cap;
    score -= mean_gap * (10.0 + 30.0 * progress);

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this bin; otherwise slightly penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let tight = 1.0 - (pr - nx) / cap;
            score -= (8.0 + 20.0 * progress) * tight;
        } else {
            score += 3.0 + 6.0 * progress;
        }
    }

    // Mild penalty for spreading across many open bins early on.
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).recip();
        let badness = (mean_residual / cap) * 0.5 + (1.0 - size_frac) * 0.5;
        score = 20.0 + 60.0 * progress - scarcity * (30.0 + 50.0 * badness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible future item are pure waste -> heavy penalty.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.12);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 60.0 + (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits strongly (post_residual close to 0 is ideal).
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 70.0;
    }

    // Reward leaving room for the lookahead item when possible.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + post_residual as f64 - next_item_size as f64;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Pressure from number of open bins: with many bins open, prefer filling
    // existing ones rather than fragmenting capacity across more bins.
    score += (open_bins_count as f64).sqrt() * 3.0;

    // Prefer bins whose residual is below the mean (fill the emptier-tail bins
    // less; prioritize bins already tight) — mild mean-residual coupling.
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // New-bin candidate handling: only attractive when the item is large
    // relative to typical residuals or no good fit exists.
    if bin_residual == bin_capacity {
        let late = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * 0.5
            + post_residual as f64
            - item_size as f64 * 0.3
            + late * 20.0
            - (fitting_bins_count as f64) * 5.0;
        // If the item leaves a large awkward gap in any bin, new bin looks better.
        if post_residual > bin_capacity / 2 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition into capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small unusable leftovers (< 10 units dead space).
        if post_residual < 10 {
            score += 25.0;
        }
        // Reward leftovers in "reusable" harmonic bands: multiples of 10, 25, 50.
        if post_residual % 10 == 0 {
            score -= 12.0;
        }
        if post_residual % 25 == 0 {
            score -= 8.0;
        }
        if post_residual % 50 == 0 {
            score -= 6.0;
        }
        // Fraction-of-capacity classes: quarter, third, half bands.
        if pr >= c * 0.5 {
            score -= 15.0; // half-full bin remains useful
        } else if pr >= c * 0.33 {
            score -= 5.0;
        } else if pr >= c * 0.25 {
            score -= 0.0;
        } else {
            score += 10.0; // deep dead space
        }
    }

    // Lookahead coupling: does the next item fit the post residual exactly or well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / c);
        } else {
            score += 8.0; // next item won't chain here
        }
    } else {
        // Last item: prefer zero waste.
        score += pr * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are truly bad,
    // but relax as the stream progresses and many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 45.0 - 30.0 * progress;
        // If nothing fits well (large dead-space penalty would occur), opening is attractive:
        if post_residual != 0 && post_residual < 10 {
            score -= 40.0;
        }
    }

    // Congestion: many open bins -> prefer consolidating into existing bins.
    score += open_bins_count as f64 * 0.5 * (bin_residual != bin_capacity) as i32 as f64;

    // Mean-residual alignment: favor bins whose residual is near the mean (balanced packing).
    score -= (mean_residual - pr).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized,
    // with a cliff at 10 (the minimum item size under the original regime, kept as a
    // conservative dead-space threshold for the 1..100 interface).
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else {
        // Usable leftover: mild reward proportional to how well it could host mid-size items.
        score -= 0.15 * post_residual as f64;
    }

    // Reward tight fits relative to residual (low waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Open-bin pressure: when many bins are open, discourage spreading; encourage closing
    // bins by favoring placements that reduce per-bin residual toward zero.
    score += 2.0 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // big reward; if next item cannot use post_residual, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        } else {
            score -= 0.3 * (post_residual - next_item_size) as f64;
        }
    }

    // Mean-residual coupling: placing into a bin with above-mean residual is mildly good
    // (balances residuals), below-mean residual is mildly penalized.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive late in the stream or when the item
    // is huge relative to capacity and no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        score = 30.0 + 40.0 * progress - 30.0 * big_item;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64); // dead space in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 45.0 * (1.0 - (post_residual as f64) / 10.0) + 15.0;
    }

    // Medium gaps (11..=25) moderately penalized, scaled by how much of the bin is wasted.
    if post_residual > 10 && post_residual <= 25 {
        score += 12.0 * (post_residual as f64 / 25.0);
    }

    // Reward placements leaving gaps that likely fit the next item (lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the next item: mild penalty.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, consolidate; when few, allow spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // New-bin candidate: only attractive when current bin fit is bad (large post_residual
    // or dead-space penalty applied) or no fitting bins exist besides this one.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a fresh bin.
        let mut new_bin_score = 55.0 + 2.0 * open_bins_count as f64;
        // If the current bin would leave a big unusable remainder, opening new is better.
        if post_residual > 25 || (post_residual > 0 && post_residual <= 10) {
            new_bin_score -= 40.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score += 20.0; // staying is fine, make new bin less attractive
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 60.0;
        }
        score = new_bin_score;
    }

    // Mild tie-breaking toward bins whose residual deviates favorably from the mean.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Quadratic dead-space penalty, growing with stream progress
    let pr = post_residual as f64;
    score += 0.012 * pr * pr * (0.5 + progress);

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only if residual capacity is abundant and progress is low
    if bin_residual == bin_capacity {
        let newbin_bonus = 8.0 * (1.0 - progress) - 4.0 * progress * open_bins_count as f64;
        score += newbin_bonus;
        // If lookahead item is large, a fresh bin is more valuable
        if next_item_size > 0 {
            let n = next_item_size as f64;
            score -= 0.06 * n * (1.0 - progress);
        }
    }

    // Lookahead synergy: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + 0.03 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize residuals just below next item size (dead space risk)
        let gap = next_item_size as f64 - post_residual as f64;
        score += 0.05 * gap * gap;
    }

    // Mild penalty when bin residual deviates from mean residual (spread control)
    score += 0.02 * (bin_residual as f64 - mean_residual).abs();

    // Cubic coupling of fill fraction with progress
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 4.0 * fill * fill * fill * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/tight fits
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to smallest possible item
        score += (post_residual as f64 / 10.0).powi(2) * 0.5;
    }

    // 2-step lookahead: reward if next item fits perfectly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            score -= 300.0 * (1.0 - gap as f64 / 100.0);
        } else {
            // next item cannot fit: penalize proportionally to leftover
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score += post_residual as f64 * 3.0;
    }

    // Last-chance bin: favor using it when few alternatives fit
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Prefer bins with residual below mean residual (denser bins)
    score += (mean_residual - bin_residual as f64) * 1.5;

    // Mild preference for keeping fewer open bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (open_bins_count as f64).ln() * 10.0 * (1.0 - progress);

    // New-bin candidate: penalize slightly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 150.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead-space gaps harshly (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual is "compatible" with the lookahead item.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 25.0; // chain fit: next item exactly fills
        } else if gap > 0 && gap < 10 {
            score += 15.0; // leaves a new dead gap for next item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Pressure when too many bins are open: discourage spreading items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Prefer bins with residual close to mean (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: make it attractive only when current bin would leave bad gap.
    if bin_residual == bin_capacity {
        // Baseline for fresh bin: competitive unless existing bins fit well.
        score = 50.0 + (post_residual as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    // Define "unusable" as a gap smaller than the smallest plausible item (1..100 range -> gap < ~10
    // is nearly dead; gaps that cannot fit the next item are also dead if nothing else arrives).
    let gap = post_residual as f64;

    // Hard dead space: gap below minimum item size threshold.
    if post_residual < 10 {
        score += 60.0 * (10.0 - gap);
    }

    // Quasi-dead space: gap too small for the lookahead item when the next item is real.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 * (next_item_size as f64 - gap);
    }

    // Reward perfect / near-perfect fills strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Reward residual matching the next item (chain fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Tight fit reward: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bins pressure: when many bins are open, prefer consolidating into existing bins
    // (penalize the new-bin candidate more as open_bins_count grows).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty plus pressure; allow it only when it creates
        // a large usable residual and few alternatives exist.
        score += 30.0 + pressure;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open a new bin
        } else if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 1 {
            score -= 25.0; // opening a bin that can host the next item may be wise
        }
    } else {
        // Existing bin: slight reward when it is the last fitting bin (avoid opening new bins).
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Prefer bins with residuals close to the item (best-fit flavor).
        score += 0.1 * (bin_residual as f64 - item_size as f64).abs();
    }

    // Mild mean-residual coupling: bins far from the mean residual are slightly less preferred.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can never fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global pressure: many open bins -> consolidate; few -> allow spreading.
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
    score += 2.0 * pressure;

    // Prefer bins below mean residual (keeps large residuals available).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Time horizon: early stream -> be picky; late stream -> fill anything.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - fit_ratio);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when item is huge
        // or no open bin fits (fitting_bins_count==0 means only this call).
        let base = 60.0;
        let size_discount = (item_size as f64 / bin_capacity as f64) * 45.0;
        score = base - size_discount + post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 20 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (they are wasted capacity).
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    } else {
        // Mild reward for leaving a moderately useful gap.
        score -= 2.0;
    }

    // Perfect / near-perfect fits are excellent.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Tightness ratio: reward high fill fraction of the residual.
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= tightness * 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is highly desirable.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0;
    }

    // Open-bin pressure: discourage spreading across too many bins, but
    // encourage opening a new bin when open bins are already crowded.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // New-bin candidate handling: an empty bin should only win when the fit
    // into open bins would be poor (large dead space or many open bins).
    if bin_residual == bin_capacity {
        // Base handicap so good fits into open bins win first.
        score += 10.0;
        // But if open bins are numerous and fragmented, opening fresh is fine.
        score -= (open_bins_count as f64).min(20.0) * 0.8;
        if mean_residual < 25.0 {
            score -= 8.0; // existing bins are nearly full; new bin is attractive
        }
    }

    // Slight nudge toward bins below the mean residual (balancing usage).
    if (post_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            score -= 500.0; // perfect chain: item then next item fills bin exactly
        } else if post_residual >= next_item_size {
            let slack = pr - nxt;
            score -= 150.0 * (1.0 - slack / bin_capacity as f64); // prefer small slack after next item
        } else {
            // next item can't fit here; penalize dead space relative to next item
            score += 50.0 + 0.5 * (nxt - pr);
        }
        // coupling with mean residual: bins deviating above mean are less attractive
        score += 0.3 * (pr - mean_residual);
    } else {
        // last item: minimize waste
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate handling: only prefer fresh bin when existing fit is terrible
    if bin_residual == bin_capacity {
        score += 40.0 + 0.4 * post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Slight preference for compacting many bins early in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.1 * (1.0 - progress) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 60.0 / post_residual as f64;
    }

    // 2-step lookahead: reward bins whose post residual matches the next item well.
    if next_item_size > 0 {
        let diff = if post_residual as i64 - next_item_size as i64 >= 0 {
            (post_residual as i64 - next_item_size as i64) as f64
        } else {
            1000.0 // next item won't fit here; mild penalty for wasting residual
        };
        score += 0.35 * diff;
        if diff == 0.0 {
            score -= 120.0; // perfect chain: this bin then next item
        }
    } else {
        // Last item: closing bins tightly is all that matters.
        score -= 200.0;
    }

    // Penalize leaving dead space relative to mean residual.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < mean_residual * 0.5 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: make it attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 25.0; // fresh bin can chain large items
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Late in stream: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 30.0 * progress;
    }

    // Mild pressure to spread load when many bins are open.
    score += 0.01 * open_bins_count as f64 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover after that hypothetical placement
            score -= 200.0 - (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit: penalize leaving dead space
            score += 50.0;
        }
    }

    // Compare residual against mean residual across open bins
    score -= 2.0 * (bin_residual as f64 - mean_residual);

    // Last-chance bin bonus: only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening new bins when open bins fit well
    if bin_residual == bin_capacity {
        score += 100.0 + 0.5 * open_bins_count as f64;
    }

    // Slight preference to fill tighter bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * post_residual as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100)
    // are pure waste. Penalize gaps that are unusable for the known next item.
    if post_residual > 0 {
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 1000.0;
        }
        // Dead space: gap smaller than the smallest possible item (1) can't happen,
        // but gaps smaller than the next item are likely wasted.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 3.0;
        }
        // Harsh penalty for tiny unusable slivers (very likely dead space)
        if post_residual <= 10 {
            score += 40.0 + (10 - post_residual) as f64 * 5.0;
        }
    }

    // Reward tight fits (small post_residual relative to residual)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: discourage scattering across many bins when few bins fit
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 15.0; // last-chance / scarce fit: strongly prefer using this bin
    }
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit (i.e., this bin would be left with a bad gap)
    if bin_residual == bin_capacity {
        // Slight handicap so we prefer reusing bins with decent fits
        score += 30.0;
        // But if the item is large and fits almost perfectly in a fresh bin,
        // opening is fine (keep base low via post_residual already small).
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 20.0;
        }
        // Late in the stream, avoid opening extra bins unnecessarily
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mean residual coupling: when open bins are mostly empty, prefer filling them
    if bin_residual != bin_capacity && (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize any residual that is small but nonzero (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit: post_residual exactly matches the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the post-residual space (2-step chain placement).
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // Next item does NOT fit into this bin after placement: penalize,
    // scaled by how much the next item overshoots the residual.
    else if next_item_size > 0 {
        let overshoot = (next_item_size - post_residual) as f64;
        score += 10.0 + overshoot * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Compare residual against the mean residual across open bins:
    // prefer bins whose residual is below average (tighter bins get filled first).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: neutral baseline, slightly above well-matched open bins,
    // but attractive when the current item would leave a very poor fit elsewhere.
    if bin_residual == bin_capacity {
        score = 45.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Early in the stream, be slightly more willing to keep bins tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: leave exactly enough room for the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.9;
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize residuals too small for the next item (dead space).
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // Last item: prefer tightest fit.
        score += post_residual as f64 * 0.2;
    }

    // Penalize small unusable residuals relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive if all open bins fit poorly.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 1.0 };
        // Opening a new bin is penalized when open bins have plenty of room.
        score += 20.0 * open_pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (bin_capacity - next_item_size) as f64 * 0.1;
        }
    }

    // Mild preference for fuller bins relative to the mean residual.
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: early in the stream we can afford to open bins,
    // late in the stream we want to consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead: match next_item_size against post_residual ----
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain: next item exactly fills this bin.
            score -= 60.0 + 40.0 * progress;
        } else if next_item_size < post_residual {
            // Next item still fits; reward closeness to a perfect chain.
            let gap = (post_residual - next_item_size) as f64;
            let closeness = 1.0 - gap / bin_capacity as f64;
            score -= 25.0 * closeness * closeness;
        } else {
            // Next item cannot fit here: dead space after this placement.
            let dead = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.5 * dead;
        }
    }

    // ---- Relative residual coupling with mean_residual ----
    // A bin whose post-residual is far below the mean residual is "tight"
    // and should be preferred for dumping this item (reduces fragmentation).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // ---- Last-chance bonus: only one open bin can fit the item ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: opened only when open bins score worse
        // (i.e., when accepting here would create large dead space).
        score = 55.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can always chain the next item perfectly.
            score -= 15.0;
        }
    }

    // Penalize creating very small unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: favor bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward if the next item fits exactly-ish into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to leftover waste.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are mostly full
    // or the fit elsewhere would be very poor.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Early in stream: prefer keeping bins open; later: allow opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 18.0 * pressure - 8.0 * progress;
    } else {
        // Prefer filling bins that are already heavily loaded (reduce bin count).
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 5.0 * fullness;

        // If many bins are open, discourage spreading across too many.
        if open_bins_count > 4 {
            score += 0.5 * (open_bins_count as f64 - 4.0);
        }
    }

    // Slight preference for bins below mean residual (balance consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small for the smallest plausible item are pure waste.
    let dead_threshold = 8.0;
    if (post_residual as f64) < dead_threshold {
        score += 500.0 * (dead_threshold - post_residual as f64);
    }
    // Non-linear penalty for medium-small gaps (hard to fill later).
    if post_residual <= 15 {
        score += 60.0 * (1.0 - (post_residual as f64 / 15.0)).powi(2);
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= 40.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // --- Lookahead coupling ---
    // If the next item fits exactly into the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual - next_item_size <= 8 {
            score -= 150.0;
        }
    }
    // If next item cannot fit in post residual, mild penalty (chain break).
    if next_item_size > post_residual && next_item_size > 0 {
        score += 25.0;
    }

    // --- Last-chance bonus ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // --- Open-bins pressure ---
    // With many open bins, prefer filling existing ones over spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).powf(1.3) * (0.5 + 0.5 * progress);

    // --- Mean residual coupling ---
