        score -= 30.0 * (mean_residual - bin_res_f) / bin_capacity as f64;
    }

    // --- New-bin candidate handling ---
    // Only open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, modulated by how bad existing options are.
        score = 350.0 + mean_residual * 0.5;
        if fitting_bins_count == 0 {
            score -= 400.0; // must open
        }
        // Later in the stream, be more reluctant to open bins.
        score += 200.0 * progress;
