        if (item_size as f64) < 0.35 * bin_capacity as f64 && fitting_bins_count > 0 {
            score += 150.0;
        }
        // If next item is large and current bins are fragmented, opening may be wise.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 80.0;
        }
    }

    score
}

