        }
        // Never open a new bin when the item would leave big usable space elsewhere
        if bin_residual - item_size >= 20 && mean_residual > item_size as f64 {
            score += 20.0;
        }
    }

    // Late stream: tighten up, avoid leaving many small open bins
    score += 15.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;
    let is_new = (bin_residual == bin_capacity) as f64;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = progress * progress * (1.0 - progress) * (1.0 - progress);
    score -= 60.0 * poly * (1.0 - prn) * prn * 4.0;

    // Penalize mid-range residual (dead space), reward tight fits, modulated by progress
    let tightness = (prn * 2.0 - 1.0).powi(2);
    score += 25.0 * tightness * (0.5 + 0.5 * progress);

    // Late stream: prefer filling existing bins; penalize new bins more as progress grows
    score += is_new * (10.0 + 80.0 * progress * progress);

    // Last-chance bonus
    if fitting_bins_count == 1 && is_new == 0.0 {
        score -= 40.0;
    }

    // Lookahead: reward residual that can host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (pr >= nx) as f64;
        let slack = ((pr - nx) as f64).max(0.0) / cap;
        score -= fits_next * (15.0 + 20.0 * slack) * (1.0 - progress * 0.5);
        score += (1.0 - fits_next) * 10.0 * progress;
    }

    // Mild pressure to use bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * prn * 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.11;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item are pure waste -> heavy quadratic penalty.
    if post_residual < 10 {
        score += 120.0 + (post_residual as f64) * 8.0;
    } else if post_residual <= 20 {
        // Marginal gap: risky, penalize proportionally to unusability.
        score += 25.0 + (20.0 - post_residual as f64) * 2.5;
    } else {
        // Usable gap: reward large post_residual slightly (keeps future room).
        score -= (post_residual as f64) * 0.15;
    }

    // Tight fit reward: small post_residual relative to item size is good.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= tightness * 15.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless the fit is truly awful).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: mildly discourage opening a new bin when the item
    // fits well somewhere; encourage it when residual here would be dead space.
    if bin_residual == bin_capacity {
        score += 10.0;
        if post_residual < 10 {
            // Opening a fresh bin for this item is fine (item nearly fills it).
            score -= 30.0;
        }
    }

    // Open-bin pressure: more open bins -> penalize spreading, favor reuse.
    score += (open_bins_count as f64) * 1.5;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 15.0; // dead space can't host next item anyway
        }
    }

    // Late-stream consolidation: near the end, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;

    // Mild pull toward bins with residuals above mean (keeps balance).
    score += ((mean_residual - bin_residual as f64) * 0.05).max(-3.0).min(3.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual == next_item_size fills the bin exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual slightly below next item size is wasted (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward leaving enough room for the lookahead item (usable slack).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 / (1.0 + slack * 0.05);
    }

    // Penalize tiny unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fill: item exactly fills the bin.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean residual (compact packing).
    score += ((post_residual as f64) - mean_residual).max(0.0) * 0.3;

    // Slight preference against opening new bins when many bins are open.
    score += (open_bins_count as f64) * 0.2;

    // Late in the stream, be more aggressive at closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Primary: reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Lookahead: if the next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // reward proportional to how well the next item fills leftover space
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 18.0 * chain_fill;
        } else {
            // next item cannot use this residual: penalize large dead space
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 8.0 * waste * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer bins where the item fits relatively snugly anyway
        score += 2.0 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: an empty bin is attractive only when the item
    // is large (would leave little residual anyway) or existing residuals are
    // highly fragmented / mean residual is small.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // penalize opening a new bin by default...
        score += 12.0;
        // ...unless the item is huge (good use of fresh capacity)
        score -= 20.0 * item_frac * item_frac;
        // ...or existing bins are nearly full on average (little room anywhere)
        score -= 15.0 * (1.0 - fragmentation.min(1.0));
        // ...or very few bins are open early in the stream (cheap to open)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * (1.0 - progress) * (open_bins_count.min(8) as f64).recip();
    } else {
        // Existing bin: mildly prefer bins whose residual is close to the mean
        // (keeps bin states homogeneous, easier future packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Prefer using bins with more open competition to consolidate load.
        score += 0.5 * open_bins_count.min(10) as f64;
    }

    // Time horizon: late in the stream, prioritize minimizing residual waste
    // aggressively since fewer future items remain to fill gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // Exact-fit absolute bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress.
    // Early on (progress ~ 0): prefer tight fits strongly (penalize large residuals quadratically).
    // Late (progress ~ 1): residual matters more linearly, small residual slightly penalized
    // to avoid wasting bins on near-perfect fits when many bins remain open.
    let mut score = pr * (1.0 + 0.8 * progress * progress) - 60.0 * x * x * (1.0 - progress);

    // Smooth interaction: residual relative to mean residual of open bins.
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap * (0.5 + progress);

    // Last-chance bonus (smoothly gated): if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x * x);
    }

    // Lookahead coupling: if next item fits the post-residual, reward; penalize otherwise,
    // with strength decaying as stream progresses.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        let gap = (pr - nx).abs() / cap;
        score += (1.0 - fits_next) * 12.0 * (1.0 - progress) + fits_next * gap * 20.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins with large residual (fragmentation pressure),
    // smoothly scaled by progress.
    score += 0.02 * open_bins_count as f64 * x * progress;

    // New-bin candidate handling: empty bin gets a smooth penalty that shrinks with progress
    // and with how bad the best fit would be (many fitting bins => prefer existing bins).
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - progress) * (fitting_bins_count as f64).min(5.0) / 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the gap: post_residual bucketed by capacity fractions.
    let pr = post_residual as f64 / cap_f; // 0.0 .. 1.0
    let class = (pr * 8.0).floor() as i32; // 8 harmonic classes

    // Reward tight fits (low class = small dead space).
    match class {
        0 => score -= 40.0,
        1 => score -= 25.0,
        2 => score -= 12.0,
        3 => score -= 4.0,
        4 => score += 0.0,
        5 => score += 6.0,
        6 => score += 14.0,
        _ => score += 22.0,
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Modulo arithmetic on post_residual: gaps that are multiples of 5
    // pair well with typical item sizes; odd small gaps are dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 18.0;
        if post_residual % 2 == 1 {
            score += 10.0;
        }
    }

    // Lookahead harmony: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Bonus scaled by how nicely the pair fills the bin.
            let combo = (item_size + next_item_size) as f64 / cap_f;
            if combo > 0.95 {
                score -= 35.0;
            } else {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here after this placement: penalize
            // unless the leftover gap is tiny anyway.
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize so we prefer existing bins unless
    // every open bin is a poor fit (their scores will be higher).
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening bins is more acceptable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // If next item is huge, a fresh bin is valuable.
        if next_item_size >= 60 {
            score -= 15.0;
        }
    }

    // Mild pressure to consolidate: prefer bins below mean residual
    // (i.e., already partially filled).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Post-residual that can still fit the lookahead item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Residual dead even for the next item: mild penalty scaled by gap size.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Open-bin pressure: discourage proliferating bins unless the fit is good.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when this item would leave a bad gap
    // in every existing bin or few bins fit; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        let wasteful = post_residual as f64;
        score += 30.0                      // base cost of opening a bin
               + wasteful * 0.8
               + open_bins_count as f64 * 2.0;
        if fitting_bins_count >= 1 && post_residual >= 20 {
            score += 25.0;                 // existing bins can host decently
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is already small relative to the mean
    // (consolidate space rather than spreading it).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // Late in the stream, tighten up: dead space matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match of post_residual with next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect two-item closure: bin is exactly filled by the next item.
            score -= 1000.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: mild reward, tighter is better.
            score -= (post_residual - next_item_size) as f64 * 0.05;
        } else {
            // Next item won't fit: penalize leftover gap relative to how close we came.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * gap * 0.02;
        }
    }

    // Penalize creating small unusable dead space (< 10, minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it attractive only when no open bin offers a good fit
    // (i.e., best post_residual among open bins would be poor). Neutral base cost.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can trivially fit the next item too.
            score -= 20.0;
        }
        if fitting_bins_count <= 1 {
            score -= 100.0;
        }
    }

    // Late in the stream: consolidate, discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 30.0;
    } else {
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: bonus grows quadratically as post_residual -> 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize post-residuals that are too small to be useful later,
    // but only if they can't fit the lookahead item.
    if post_residual > 0 {
        let usable = (next_item_size > 0 && post_residual >= next_item_size)
            || post_residual >= 10;
        if !usable {
            score += 12.0;
        }
    }

    // Lookahead coupling: strongly favor bins whose post-residual exactly
    // accommodates the next item (perfect pairing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // partial reward for leaving room for the next item
        let room = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 8.0 * room;
    }

    // Last-chance bin: if this is the only fitting bin, heavily reward using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is penalized when any
    // open bin fits, but becomes attractive when the current bin leaves
    // awkward residue and the next item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = if post_residual > 0 {
            (post_residual as f64) < (next_item_size as f64) * 0.9 && post_residual < 10
        } else { false };
        // base penalty for bin proliferation
        score += 20.0 + 5.0 * (open_bins_count as f64).sqrt();
        // but discount it late in the stream or when placement elsewhere is awkward
        if awkward {
            score -= 35.0;
        }
        if next_item_size > 60 {
            score += 10.0; // large next item: prefer fresh bin now
        }
        let _ = progress;
    }

    // Global state: when mean residual across open bins is high, prefer
    // consolidating into existing bins (pack tight) rather than spreading.
    if bin_residual < bin_capacity {
        let gap = mean_residual - bin_residual as f64;
        if gap > 0.0 {
            score += 0.15 * gap; // this bin is emptier than average -> discourage
        } else {
            score -= 0.10 * (-gap); // fuller-than-average bin -> encourage
        }
    }

    // Mild time-horizon term: early in stream, be conservative (prefer tight
    // packing); late in stream, slightly prefer any fit to close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * tightness * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = x * (1.0 + progress * (1.0 - x)) * cap;

    // Non-linear tightness reward: strongly favor small post_residual
    score -= (1.0 - x) * (1.0 - x) * item_size as f64 * 0.5;

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dev = x * cap - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Last-chance bonus: only one fitting bin -> reward using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: penalize leaving residual that barely fails next item
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 && gap < 10.0 {
            score += (10.0 - gap) * 2.0;
        } else if gap >= 0.0 {
            score -= 3.0;
        }
    }

    // Early stream: mild preference to consolidate into fewer bins
    score += (1.0 - progress) * (open_bins_count as f64) * 0.5;

    // New-bin candidate: discourage unless residual is large
    if bin_residual == bin_capacity {
        score += 20.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small"
    // residue classes are more valuable to fill tightly.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction-of-capacity classes via integer division thresholds
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let sixteenth = bin_capacity / 16;

    // Reward (subtract) when post_residual lands in tight residue classes
    if post_residual <= sixteenth {
        score -= 12.0; // near-perfect fill
    } else if post_residual <= eighth {
        score -= 7.0;
    } else if post_residual <= quarter {
        score -= 3.0;
    } else {
        // large dead space penalty, modulated by modulo class
        let m = post_residual % 10;
        score += (m as f64) * 0.3; // penalize awkward non-multiples-of-10 leftovers
    }

    // Perfect fit: post_residual exactly divisible into expected item classes
    if post_residual == 0 {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0; // chains perfectly with lookahead
    } else if next_item_size > 0 && post_residual > next_item_size {
        // leftover can host the next item: reward proportionally
        score -= 4.0 + (next_item_size as f64 / cap_f) * 6.0;
        // extra reward if next item also leaves a tight class
        let nxt_post = post_residual - next_item_size;
        if nxt_post <= eighth {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // next item cannot fit here: penalize if this was a tight-fit opportunity wasted
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when item is large relative
    // to capacity and open bins have scattered residuals.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap_f;
        // base cost of opening a bin, discounted for large items
        score += 20.0 - fill_ratio * 18.0;
        if open_bins_count == 0 {
            score -= 30.0; // must open when nothing is open
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // new bin can host a chain
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 4.0;
    }

    // Coupling with mean residual: prefer bins close to the mean (balanced packing)
    score += ((pr - mean_residual) / cap_f).abs() * 2.0;

    // Mild preference for filling fuller bins overall
    score -= (bin_residual as f64 / cap_f) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A gap is "dead" if it cannot hold even the smallest plausible item (1..=10).
    let min_item = 10.0f64.min(item_size as f64);
    if (post_residual as f64) < min_item && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    }

    // Non-linear penalty on small-but-nonzero post residuals (0..20 dead zone).
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.5;
    }

    // Reward tight fits (post residual small relative to bin capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Open-bin pressure: with many open bins, discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if existing bins would leave bad dead space
        // or this is the last fitting bin situation is irrelevant for a new bin.
        score += pressure * 4.0;
        // Slight bonus early when few bins are open.
        score -= (10.0 - open_bins_count as f64).max(0.0) * 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && next_item_size > bin_residual {
        // next item won't fit anywhere here anyway; mild bonus for dumping big items together
        score -= 3.0;
    }

    // Mild preference toward bins with below-average residual (consolidate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: zero waste is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward residuals that exactly match the next item,
    // penalize residuals that are just barely too small (dead space).
    if next_item_size > 0 {
        let pr = post_residual as i64;
        let ni = next_item_size as i64;
        let diff = pr - ni;
        if diff == 0 {
            score -= 400.0; // perfect chain: next item fills this bin exactly
        } else if diff < 0 && diff >= -10 {
            score += (-(diff) as f64) * 25.0; // near-miss creates unusable sliver
        } else if diff > 0 && diff <= 10 {
            score -= 150.0 - (diff as f64) * 10.0; // next item still fits well
        }
    }

    // Compare against mean residual: placing into a bin with residual near
    // the mean keeps the bin profile balanced; extreme residuals are risky.
    score += ((post_residual as f64 - mean_residual).abs()) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 50.0; // empty bin is fine if next item also fits here
        }
    }

    // Slight preference for tighter bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small to hold even the smallest item.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Exact fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item nearly fits (within a small gap), mild reward.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // Many open bins: encourage filling existing ones rather than spreading.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 3.0 * open_pressure * tightness;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already well-packed — keep filling it.
    let residual_gap = mean_residual - bin_residual as f64;
    score -= 0.15 * residual_gap;

    // New-bin candidate: make an empty bin moderately attractive by default,
    // but discourage it when good fits exist among open bins.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, opening bins is cheap; early on, prefer reuse.
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post_residual, with non-linear sharpening.
    let mut score = norm_post * norm_post * (1.0 + 2.0 * norm_post);

    // Smooth stream-progress coupling: tighten packing as stream advances.
    let tighten = 0.5 + 1.5 * progress * progress;
    score *= tighten;

    // Dead-space penalty: residual too small to ever be useful (below min item size),
    // penalized smoothly via a smoothstep-like ramp around the minimum size.
    let min_item = 1.0f64;
    let unusable = (1.0 - (post / (min_item * 2.0)).min(1.0)).max(0.0);
    score += 3.0 * unusable * unusable * (1.0 + progress);

    // Perfect fit reward (smooth Gaussian-like bump at post_residual == 0).
    score -= 2.0 * (-norm_post * norm_post / 0.01).exp();

    // Lookahead coupling: reward if next item fits the post residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (post - nxt).abs() / cap;
        score -= 1.2 * (-fit_gap * fit_gap / 0.02).exp();
        // Penalize leaving residual slightly below next item (blocking dead space).
        let block = ((nxt - post) / cap).max(0.0);
        score += 1.5 * block * block;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.0 + 2.0 * progress;
    }

    // New-bin candidate: mildly penalize opening a new bin when the stream is
    // advanced (encourage filling existing bins), smoothed polynomially.
    if bin_residual == bin_capacity {
        score += 0.8 + 1.2 * progress * progress;
        // But if mean residual across open bins is low, opening is fine.
        score -= 0.6 * (mean_residual / cap).clamp(0.0, 1.0);
    }

    // Slight preference for bins with residual close to item size (tight fit),
    // smooth coupling of item_size and bin_residual.
    let tight = (bin_residual as f64 - item_size as f64) / cap;
    score += 0.5 * tight * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: classify post_residual by capacity fractions
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Dead-space penalty: leftover below the smallest item (<=10) is unusable
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly
        score -= 60.0;
    }

    // Modulo classes on post_residual: leftovers congruent to small multiples
    // of common item sizes pair better with future arrivals.
    let m = post_residual % 10;
    if m == 0 {
        score -= 12.0; // leftover on the 10-grid, highly reusable
    } else if m >= 8 {
        score += 8.0;  // awkward sliver class
    }

    // Integer-division thresholds: which harmonic band does the leftover live in?
    let band = post_residual / 25; // 0..3 quarters of capacity
    score -= match band {
        0 => 5.0,          // tiny leftover: bad (already penalized above)
        1 => 10.0,         // quarter-band: fits medium items
        2 => 14.0,         // half-band: very flexible
        _ => 6.0,          // nearly-empty bin
    };

    // Fraction-of-capacity coupling
    let frac = post_f / cap;
    score -= 25.0 * frac * frac; // prefer bins retaining large usable fractions

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0; // chain-friendly placement
            // exact harmonic match: next item lands on the 10-grid of leftover
            if post_residual % next_item_size.max(1) == 0 {
                score -= 10.0;
            }
        } else if next_item_size <= bin_residual {
            // next item fits only before placing current item -> wastes pairing
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it expensive unless the current bin would be left
    // with unusable dead space or the fit is very tight elsewhere.
    if bin_residual == bin_capacity {
        score += 55.0;
        // but if no open bin leaves a grid-aligned leftover, new bin is fine
        if post_residual % 10 == 0 && post_residual >= 20 {
            score -= 30.0;
        }
    }

    // Stream progression: late in the stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (post_f / cap);

    // Prefer tighter bins relative to the mean residual of open bins
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward filling large chunks of the bin (high fill ratio).
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidation into existing bins,
    // penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If next item is large and this placement leaves a gap it cannot use, penalize.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Late in stream: be more conservative, prefer tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual close to item (tight fit relative to mean).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

