    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Prefer tighter bins relative to mean residual (best-fit bias).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Mild bias toward new bins early in stream when open bins are crowded.
    if bin_residual == bin_capacity {
        score -= 5.0 + 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
