pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress~0): mild weight on residual; later: stronger.
    let pr = post_residual as f64;
    let norm = pr / cap; // in [0,1]
    let poly = norm * norm * (1.0 - progress) + norm * (0.5 + progress);
    score += poly * 20.0;

    // Reward tight fits: small post_residual strongly favored, amplified late.
    let tightness = 1.0 - norm;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Lookahead: if next item fits exactly or well into post_residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fill_next = (next_item_size as f64) / cap;
        let leftover_after_next = pr - next_item_size as f64;
        let nl = leftover_after_next / cap;
        // prefer residual that next item fills tightly
        score -= fill_next * (1.0 - nl) * (1.0 - nl) * 25.0;
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        // dead space for next item: penalize more as stream progresses
        score += (1.0 + progress) * 8.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0 + 40.0 * progress;
    }

    // New-bin candidate: neutral early, discouraged once many bins are open
    // or when open bins have small mean residual (good packing opportunities).
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress;
        score += (open_bins_count as f64).ln() * 5.0;
        score += (mean_residual / cap).max(0.0) * 10.0;
    }

    // Penalize residual far from typical small leftovers (dead space).
    let dev = (pr - mean_residual).abs();
    score += (dev / cap) * (dev / cap) * 15.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
