    // Small post_residual = tight fit -> reward strongly.
    let tight_class = post_residual / 10; // 0..=10 harmonic class
    score -= (10 - tight_class.min(10)) as f64 * 3.0;

    // Perfect-fit harmonic classes: residuals that are multiples of common item sizes
    // (small classes) are more reusable. Reward residuals divisible by 10 or 25.
    if post_residual % 10 == 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 {
        score -= 4.0;
    }

    // Dead-space penalty: post_residual below the minimum item size is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
