            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bonus: this is the only bin that fits -> avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets base cost of a fresh bin plus
    // mild attractiveness only when no good existing fit exists.
    if bin_residual == bin_capacity {
        score = 55.0; // cost of opening a new bin
        if fitting_bins_count == 0 {
