            }
        }
    }

    // Prefer bins whose residual is close to the mean (balance residuals) mildly.
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    // Mild preference for fewer open bins when many are open.
    if open_bins_count > 8 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
