    // New-bin candidate: only attractive when current bin fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual > 0 && post_residual < 10 { 70.0 } else { 0.0 };
        score += 35.0 - poor_fit + (post_residual as f64 - mean_residual).abs() * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose post_residual exactly
    // (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let next = next_item_size as f64;
        let diff = (post - next).abs();

        if diff == 0.0 {
            // Perfect match: next item fills this bin exactly.
            score -= 60.0;
        } else if next <= post {
            // Next item fits in the leftover: reward closeness to exact fill.
            score -= 40.0 * (1.0 - diff / post.max(1.0));
        } else {
            // Next item would NOT fit in the leftover: penalize by the gap,
            // scaled by how much dead space would be stranded.
            score += 0.5 * diff;
            // Extra penalty if the leftover is small and unusable.
            if post < 10.0 {
                score += 15.0;
            }
        }
    }

    // Prefer leaving residuals near the mean of open bins (balance pressure),
    // penalize creating residuals far below mean (fragmented dead space).
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score += 0.6 * (mean_residual - post_f);
    } else {
        score -= 0.2 * (post_f - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild bonus for tight fits overall (small post_residual is good packing),
    // but only when the lookahead doesn't contradict it.
    score -= 0.1 * (bin_capacity - post_residual) as f64;

    // Late in the stream, consolidate: prefer existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus progression-scaled penalty.
        score += 30.0 + 40.0 * progress;
        // Opening a new bin is more attractive if open bins are very full on average.
        if mean_residual < 15.0 {
            score -= 20.0;
        }
    } else {
        // Existing bins get a mild preference that grows with progress.
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: early on, tolerate larger residuals (keep bins flexible);
    // late in the stream, tighten aggressively toward full packing.
    let tightness = 0.5 + 1.5 * progress * progress;
    score += tightness * norm_pr * pr * 0.5;

    // Reward smooth fits where the next item likely fills the remaining gap
    if next_item_size > 0 {
        let gap_diff = (pr - next_item_size as f64).abs();
        score -= (1.0 - progress) * 12.0 / (1.0 + gap_diff * 0.1);
        // Perfect lookahead fit: strong reward
        if (next_item_size as f64 - pr).abs() < 1.0 {
            score -= 20.0;
        }
    }

    // Last-chance bin: avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize bins deviating from mean residual (keeps residual profile homogeneous)
    score += 0.15 * (mean_residual - pr).abs();

    // New-bin candidate: mild penalty so it's chosen only when open bins are hopeless
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual via integer division thresholds (capacity fractions)
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (post_residual * 4) / bin_capacity; // 0..3 harmonic class: [0,25),[25,50),[50,75),[75,100]
    match class {
        0 => score += 30.0,           // dead space: tiny residual almost unusable
        1 => score += 8.0,            // quarter-class: poor
        2 => score -= 4.0,            // half-class: decent
        _ => score -= 10.0,           // large residual: healthy bin
    }

    // Exact fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tightness reward: item fills a large fraction of the residual
    let fill = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill * fill;

    // Lookahead: does next item fit in post_residual? Harmonic pairing via modulo classes.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0; // chainable bin is valuable
            // modulo-10 pairing: next item lands on a friendly class boundary
            if (post_residual % 10) >= (next_item_size % 10) {
                score -= 5.0;
            }
        } else {
            // next item won't fit: penalize proportionally to how stranded post_residual is
            let gap = (next_item_size - post_residual) as f64;
            score += 0.4 * gap;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins are poor fits
    if bin_residual == bin_capacity {
        // neutral base; add pressure so it loses against decent fits
        score += c * 0.5;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // late in stream, fewer open bins -> opening is cheaper
        score -= 10.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    // Spread pressure: if this bin's residual is far from mean, mildly penalize
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1, but practically < 10) are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure for bin proliferation.
        score += 15.0 + 8.0 * pressure;
        // A new bin is attractive if the item barely fits anywhere else
        // (item is large relative to typical residual).
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
    } else {
        // Reward placing into bins with low residual (consolidate).
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Lookahead (k=2): if the next item exactly matches post_residual,
    // this placement sets up a perfect follow-up fit.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual cannot host the next item: mild penalty scaled
        // by how much space is stranded.
        score += 0.2 * post_residual as f64;
    }

    // Late in the stream, tighten up: waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness;

    // 2-step lookahead: reward if next item exactly fills post_residual,
    // penalize if post_residual is just barely too small for next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size < post_residual {
            let fit_ratio = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fit_ratio; // next item likely fits this bin's remainder
        } else {
            // post_residual too small for next item: dead-space penalty,
            // worse when the leftover is tiny (unusable).
            let waste = post_residual as f64 / next_item_size as f64;
            score += 8.0 * (1.0 - waste.min(1.0));
        }
    }

    // Compare post_residual against mean residual: leaving more than average
    // is wasteful; leaving less than average is efficient consolidation.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when existing bins fit well (post_residual small).
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of opening a bin
        score += 30.0;
        // allow new bin only if no open bin gives a near-perfect fit
        if post_residual == 0 || (next_item_size > 0 && next_item_size == post_residual) {
            score -= 45.0;
        }
        // late in stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer consolidating into few bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact fill is always ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness reward: fraction of the bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 60.0 * fill_frac;

    // Penalize leaving dead space that cannot plausibly fit a future item
    // (items are >= 1, but small residuals below typical sizes are wasteful).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward it;
    // if the next item would waste this residual, penalize slightly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0;
        } else {
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin offers a decent fit. Penalize the empty-bin candidate
    // proportionally to how many bins already fit the item, and to stream
    // progress (early on, consolidation matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 12.0 * fitting_bins_count as f64 + 30.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is below average (they are "nearly full"),
    // keeping large residuals available for large future items.
    let dev = mean_residual - bin_residual as f64;
    score -= 0.15 * dev;

    // Mild congestion term: when many bins are open, favor consolidating
    // into existing bins rather than spreading.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let mut score = post;

    // Fill-ratio (0 = tight fit, 1 = empty bin after placement)
    let fill = 1.0 - post / cap;

    // Smooth cubic reward for tight fits; amplified as the stream progresses
    score -= fill.powi(3) * cap * (0.35 + 0.45 * progress);

    // Last-chance bin: strongly favor using the final fitting bin
    if fitting_bins_count <= 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead coupling (k=2): reward residuals that can host the next item,
    // penalize residuals that strand it
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= post {
            // exact-ish match for next item gets extra smooth reward
            let match_closeness = 1.0 - ((post - n) / cap);
            score -= 6.0 + 10.0 * match_closeness * match_closeness;
        } else {
            score += (n - post).min(n) * 0.12;
        }
    }

    // New-bin candidate: smooth penalty, relaxed for large items and late stream
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        score += 18.0 - 12.0 * progress - 20.0 * item_frac * item_frac;
    }

    // Spread pressure: prefer bins whose residual deviates from the fleet mean
    // (concentrate waste into few bins rather than many)
    score += (mean_residual - post).abs() * 0.06 * (1.0 - progress);

    // Mild open-bin count coupling: with many open bins, prefer consuming
    // residual capacity (lower post_residual weighted by bin count)
    score += (open_bins_count.max(1) as f64).ln() * (post / cap) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic classes: capacity fractions of the post residual
    let frac = pr / cap; // fraction of capacity remaining
    score -= 30.0 * (1.0 - (2.0 * frac - 1.0).abs()); // reward post_residual near half-capacity

    // Integer-division thresholds on post_residual: dead-space classes
    if post_residual == 0 {
        score -= 100.0; // perfect fit
    } else if post_residual < 10 {
        score -= 40.0; // near-perfect, unusable sliver
    } else if post_residual <= 20 {
        score += 10.0; // small but potentially usable class
    } else if post_residual <= 35 {
        score += 18.0;
    } else {
        score += 25.0; // large leftover class
    }

    // Modulo arithmetic on post_residual relative to capacity quantum
    let q = post_residual % 25;
    score += 3.0 * (q as f64) / 25.0; // slight penalty for off-quantum residuals

    // Lookahead coupling: can next item fit in post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item divides the leftover nicely
            score -= 20.0;
            if post_residual % next_item_size.max(1) == 0 {
                score -= 15.0; // exact harmonic division
            }
        } else {
            score += 8.0; // leftover likely dead for next item
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score += 55.0 + 10.0 * (open_bins_count as f64).sqrt(); // prefer existing bins generally
        if next_item_size > 0 && next_item_size >= item_size && fitting_bins_count <= 2 {
            score -= 30.0; // pairing large items in fresh bins
        }
    }

    // Stream progression: later in stream, pack tighter
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * t * (1.0 - frac);

    // Mean residual coupling: penalize adding to bins already far from mean
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=10) are wasted;
    // penalize them heavily so near-perfect fits are strongly preferred.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (11.0 - post_residual as f64);
    }

    // Reward very tight fits (post_residual tiny relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // If the next item exactly fits the post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual - next_item_size <= 5 {
            score -= 20.0;
        }
    }
    // Penalize if post_residual is smaller than the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 12.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // and discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or early stream.
        score += 30.0 + 8.0 * pressure + 20.0 * (1.0 - progress);
        // But if no open bin fits well (this new-bin call coincides with high mean residual mismatch), soften.
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
    } else {
        // Existing bin: mild reward scaled by pressure to consolidate.
        score -= 2.0 * pressure;
        // Prefer bins whose residual is close to what we consume (avoid scattering).
        let scatter = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * scatter;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 + (bin_capacity as f64 - slack) * 0.5;
        if slack == 0.0 {
            score -= 200.0; // exact chain fit
        }
    } else if next_item_size > 0 {
        // next item cannot fit: dead space penalty scaled by gap
        let gap = (next_item_size - post_residual) as f64;
        score += gap * 0.8;
    }

    // Penalize small unusable residuals (below typical item sizes)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && (post_residual >= next_item_size || post_residual == 0);
        if good_fit_exists {
            score += 500.0; // discourage opening new bin when open bins fit well
        } else {
            score -= 20.0; // mild preference for fresh bin when fits are poor
        }
    }

    // Slight preference for filling nearly-full bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity as f64 - post_residual as f64) * 0.1 * progress;

    // Tie-break: prefer bins among many fitting bins (keep flexibility)
    score += fitting_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
