    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 4.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 3.0; // next item won't fit here; leftover likely wasted
        }
    }

    // Global state: when mean residual is high, prefer filling fat bins.
    score -= 0.05 * mean_residual * (1.0 - fill_ratio);

    // Mild diversity pressure: with many open bins, tighten selection.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth polynomial coupling: post_residual scaled by progress-dependent curvature
    let poly = 0.35 * progress * progress + 0.15 * progress + 0.5;
    score += poly * post * (1.0 - post / cap);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - post / cap) * (1.0 - post / cap) * (2.0 + 6.0 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * (0.5 + progress);
    }

    // Penalize opening a new bin when existing bins fit reasonably well
    let fit_gap = (bin_residual as f64 - item_size as f64).max(0.0);
    if bin_residual == bin_capacity {
        score += 3.0 + 8.0 * progress - 0.05 * fit_gap;
        if fitting_bins_count > 0 && post <= 15.0 {
            score += 20.0;
        }
    }

    // Dead-space penalty relative to mean residual
    score += 0.08 * (post - mean_residual).abs();

    // Lookahead coupling: penalize leaving residual that barely misses next item
    if next_item_size > 0 && post > 0 && post < next_item_size {
        score += 0.5 * (next_item_size as f64 - post) * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes over capacity fractions.
    // Residuals in [0,10] are "dead" (few items fit); residuals in [10,50] are semi-useful.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill: best possible outcome
    } else if pr < 10 {
        score += 25.0; // dead space, nearly unusable
    } else if pr < 25 {
        score += 8.0;  // awkward zone
    } else if pr < 50 {
        score -= 5.0;  // healthy residual
    } else {
        score += 4.0;  // large residual: bin was underfilled
    }

    // Harmonic coupling: does the lookahead item fit exactly / well into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == pr {
            score -= 45.0; // exact harmonic match next step
        } else if next_item_size < pr {
            let fill = nxt / pr as f64;
            if fill > 0.7 {
                score -= 20.0 * fill; // next item fills most of remaining space
            } else if fill < 0.25 {
                score += 10.0; // next item would leave another awkward gap
            }
        } else {
            // next item cannot fit here: residual must serve later items
            score += 6.0;
        }
        // Modulo-class harmony: residual divisible into chunks matching next item
        if pr % next_item_size.max(1) == 0 && pr > 0 {
            score -= 12.0;
        }
    } else {
        // last item: any residual is waste; prefer minimal
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): penalize mildly so we prefer good existing fits,
    // but allow opening when all open residuals are poor.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let mean_badness = (mean_residual / cap).clamp(0.0, 1.0);
        // Opening is more attractive when existing bins are fragmented (low mean residual)
        score += 18.0 - 15.0 * (1.0 - mean_badness) - open_pressure.min(10.0) * 1.2;
        // Late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Prefer tight fits overall: reward small bin_residual - item_size gap relative to capacity
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += 10.0 * tightness;

    // Many open bins: encourage closing them out (favor bins with small residual)
    score -= (open_bins_count as f64).min(20.0) * (cap - post_residual as f64) / cap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Coupling with open_bins_count pressure: prefer filling existing bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.5;

    // Reward using bins whose residual is close to the item (tight fit).
    let tightness = 1.0 - (post_residual as f64 / bin_residual.max(1) as f64);
    score -= tightness * 8.0;

    // Last-chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 4.0;
    }

    // Prefer bins with below-mean residual (consolidate space).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // New-bin candidate: make it attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual > 0 && (post_residual as f64) < dead_threshold { 20.0 } else { 0.0 };
        score += 10.0 - poor_fit + pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- Aggressive 2-step lookahead matching ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        // Perfect match: post_residual exactly fits the next item -> strong reward
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as u32 == next_item_size {
            score -= 45.0 + 10.0 * (1.0 - progress); // perfect 2-chain, more valuable early
        } else if diff <= 10.0 {
            score -= 18.0 * (1.0 - diff / 10.0);     // near-perfect chain
        } else if post_residual as u32 > next_item_size {
            // next item still fits, but leaves slack: mild reward scaled by tightness
            let tight = nxt / post_residual as f64;
            score -= 8.0 * tight;
        } else {
            // next item will NOT fit here: penalize proportional to wasted chain potential
            score += 6.0 + 0.15 * (nxt - post_residual as f64);
        }
    } else {
        // Last item: just minimize post residual (already the base), tiny bonus for tight fit
        score -= 2.0;
    }

    // ---- Relative to mean residual across open bins ----
    // Prefer bins with residual below the mean (they are "almost full", use them up)
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (res - mean_residual) / mean_residual;
        if rel < 0.0 {
            score += 0.5 * rel; // tighter than average: reward
        } else {
            score += 0.35 * rel; // looser than average: penalize
        }
    }

    // ---- Last-chance bin: if this is the only fitting bin, strongly favor using it ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin gives a good fit
        // (i.e., current best post_residual would leave large dead space) or bins are many/empty-ish
        let wasteful = res as f64 > 0.5 * bin_capacity as f64;
        if wasteful && fitting_bins_count > 0 {
            score -= 12.0; // prefer fresh bin over wasting big residual
        } else {
            score += 30.0 + 20.0 * (1.0 - progress); // keep filling open bins early on
        }
        // If many open bins with small residuals, discourage spreading
        if open_bins_count > 4 && mean_residual < 30.0 {
            score += 15.0;
        }
    }

    // ---- Dead-space shaping: non-linear penalty on unusable small leftovers ----
    if res > 0.0 && res < 10.0 {
        score -= 5.0; // tiny leftover is nearly perfect packing
    } else if res >= 10.0 && res < 20.0 && next_item_size > 0 && (next_item_size as f64) > res as f64 {
        score += 4.0; // leftover too small for the next item: dead space risk
    }

    // Slight late-stream tightening: as stream ends, prefer filling existing bins harder
    score += 3.0 * progress * (res / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = 1.0 - post / cap;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post == 0 { score -= 50.0; }
    else if post < 5 { score -= 25.0; }

    // Penalize small-but-nonzero dead space that nothing (>=10 historically) can use,
    // but soften since sizes 1..100 are possible.
    if post > 0 && post < item_size as f64 {
        score += 4.0 * (1.0 - post / cap);
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post - nxt).abs() < 0.5 {
            score -= 20.0;
        } else if nxt <= post {
            score -= 6.0 * (post - nxt) / cap;
        } else {
            // Next item won't fit here anyway; slight penalty for leaving mid-range gap.
            score += 2.0 * (post / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * fill_ratio;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all open bins.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; cheaper early when few bins are open.
        score = cap * 0.35 + 3.0 * (open_bins_count as f64).sqrt();
        // If many open bins have large residuals and none fit well, opening fresh is fine.
        if fitting_bins_count > 0 {
            // Only open a new bin if all existing fits leave big dead space.
            let best_possible = (bin_residual - item_size) as f64;
            if best_possible < 10.0 { score += 40.0; } // near-perfect fit exists elsewhere
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        if mean_residual > item_size as f64 { score += 8.0; }
    }

    // Mild preference for bins with residuals close to the item (harmonic fit).
    let diff = (bin_residual as f64 - item_size as f64) / cap;
    score += 5.0 * diff * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_frac = pr / cap;

    // Base: prefer small post residual, with non-linear sharpening.
    let mut score = pr * (1.0 + 0.8 * fit_frac * fit_frac);

    // Stream-progress coupling: early on, tolerate slack; later, penalize it harder.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * fit_frac * cap * 0.5;

    // Lookahead synergy: reward leaving room for the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let synergy = 1.0 - (gap / cap).min(1.0);
        score -= 6.0 * synergy * synergy;
        // Penalize if this bin is the only fit and next item likely needs space too.
        if fitting_bins_count == 1 {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    } else {
        // Mild penalty proportional to how many alternatives exist.
        score += (fitting_bins_count.min(8) as f64) * 0.4;
    }

    // Mean-residual coupling: if this bin is far from the mean, slight penalty
    // (encourages balanced residual distribution, smooth quadratic form).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev * cap * 0.1;

    // New-bin candidate handling: empty bin gets a moderate default score so
    // it only wins when open bins have genuinely bad fits.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress) - 2.0 * (1.0 - fit_frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: tighter fit wins
    score -= (item_size as f64 / bin_capacity as f64) * 40.0;

    // Harmonic classes of post_residual: residual classes mod 10
    // Class 0 (perfect fit) heavily rewarded; classes that leave "dead zones"
    // for typical item sizes penalized.
    let class = post_residual % 10;
    match class {
        0 => score -= 25.0,
        1 | 2 => score += 12.0,   // tiny slivers = dead space
        3 | 4 => score += 5.0,
        5 => score -= 8.0,        // half-slot, very reusable
        6 | 7 => score += 3.0,
        8 | 9 => score -= 4.0,
        _ => {}
    }

    // Integer-division thresholds on post_residual: coarse capacity fractions
    let q = post_residual / 25; // quarters of capacity
    score -= match q {
        0 => 15.0, // < 25 left: nearly dead bin
        1 => 0.0,
        2 => -6.0, // 25..49: good medium pocket
        3 => -10.0,
        _ => 0.0,
    };

    // Lookahead coupling: harmonic relation between post_residual and next item
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
            // exact modulo match: next item divides residual into nice class
            let rem = post_residual % next_item_size.max(1);
            if rem == 0 {
                score -= 20.0;
            } else if rem <= 2 {
                score += 6.0;
            }
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are mostly full
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - (mean_residual / bin_capacity as f64);
        let pressure = avg_fill * open_bins_count as f64 / (open_bins_count as f64 + 1.0);
        score = 60.0 - pressure * 55.0 - progress * 10.0;
        // discourage new bin if next item is small and could pair later
        if next_item_size > 0 && next_item_size <= 30 {
            score += 8.0;
        }
    }

    // Slight preference to consolidate across many open bins
    score += (open_bins_count as f64).ln() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps that likely nothing fits into are toxic.
    let dead_threshold = 10.0_f64.max(next_item_size as f64);
    if (post_residual as f64) < dead_threshold {
        // unusable sliver: heavy penalty proportional to wasted capacity
        score += (bin_capacity as f64) * 1.5;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // gap can still host the lookahead item: reward tight future fit
        let snug = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
        score -= 8.0 * snug;
    } else if next_item_size > 0 {
        // gap too small for the next item: mild dead-space penalty
        score += 6.0;
    }

    // Reward near-perfect packing (almost full bin).
    if post_residual == 0 {
        score -= 25.0;
    } else if (post_residual as f64) <= 0.05 * (bin_capacity as f64) {
        score -= 12.0;
    }

    // Prefer tight fits overall: penalize waste relative to item size.
    score += 3.0 * (post_residual as f64) / (item_size.max(1) as f64);

    // Open-bin pressure: discourage hoarding many open bins early, allow more later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.6 - 0.4 * progress);

    // Divergence from mean residual: keep residuals homogeneous for future fits.
    score += 0.3 * ((post_residual as f64) - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin fit is really bad.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fits the post-residual (perfect 2-step chain).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Penalize post-residuals that cannot accommodate the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward tight fits relative to the mean residual of open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(40.0) * 0.5;
    } else {
        score += (pr - mean_residual) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins exist and fit reasonably.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if open_bins_count > 0 && next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            // new bin is good if it enables a clean chain
            score -= 10.0;
        } else if fitting_bins_count > 0 {
            score += 40.0;
        }
    }

    // Slight preference for compacting late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size)
    let tight = post_residual as f64 / (item_size.max(1) as f64);
    score -= 40.0 * (-tight).exp();

    // Penalize dead space: residuals too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward heavily
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 70.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        } else {
            // next item won't fit here; slight penalty proportional to leftover
            score += 8.0 * (1.0 - (next_item_size - post_residual) as f64 / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Crowding control: many open bins -> prefer filling existing ones
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.5 * crowding * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, be picky (penalize mediocre fits); late, accept more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 12.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is close to mean residual (balance residuals)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = bin_capacity as f64 * 1.15;
        // Reduce the cost if the item is large relative to capacity (hard to place later)
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        // If this is the only fitting option (fitting_bins_count counts open bins only),
        // a new bin is effectively forced anyway
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in the stream, opening bins is less costly relative to fragmenting
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling: reward small post-residuals super-linearly.
    score -= 40.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_item;

    // Tight-fit bonus via smooth interaction of post_residual with item size.
    let tight = 1.0 - (norm_pr / (norm_item + 0.05)).min(1.0);
    score -= 25.0 * tight * tight;

    // Stream progress: later in stream, penalize residual waste more strongly.
    score += 30.0 * progress * norm_pr * norm_pr;

    // Lookahead coupling: if next item fits the post-residual smoothly, reward.
    if next_item_size > 0 {
        let gap = (norm_pr - norm_next).abs();
        score -= 20.0 * (1.0 - gap.min(1.0)) * (1.0 - progress);
        // Penalize if next item cannot fit any residual-like space.
        if norm_next > norm_pr {
            score += 15.0 * (norm_next - norm_pr);
        }
    }

    // Last-chance bonus: only fitting bin should be strongly favored.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins with large mean residual.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * (norm_pr - mean_residual / cap).abs();

    // New-bin candidate: make it attractive only when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let avg_waste = mean_residual / cap;
        score = cap * (0.6 + 0.4 * progress) - 20.0 * (1.0 - avg_waste.min(1.0));
        if norm_item > avg_waste.max(0.4) {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the dead space: waste is worse in certain modulo classes
    let pr = post_residual;
    if pr > 0 {
        // Small dead space (1..=10) is nearly unusable -> heavy penalty
        if pr <= 10 {
            score += 40.0;
        }
        // Dead space in awkward harmonic classes (prime-ish gaps) is penalized
        let cls = (pr % 12) as f64;
        score += 0.8 * cls;
        // Perfectly reusable residuals (multiples of common item sizes) rewarded
        if pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0 {
            score -= 6.0;
        }
        // Exact fill is ideal
        if pr == 0 {
            score -= 30.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: prefer leaving room for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else if post_residual > 0 {
            score += 5.0; // next item can't use the leftover
        }
    }

    // New-bin candidate handling: only open a new bin when current fit is bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline cost of opening a new bin
        score += 55.0;
        // But if existing bins would leave tiny dead space, new bin becomes attractive
        if item_size <= bin_residual && (bin_residual - item_size) <= 10 {
            score -= 60.0;
        }
        // Late in the stream, avoid accumulating many near-empty bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // If many bins are open already, prefer packing into them
        score += (open_bins_count as f64).min(20.0) * 0.5;
    }

    // Slight preference for fuller bins overall
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual gap is "dead" if it is too small for the smallest plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) * 8 {
        score += 40.0; // tiny unusable gap -> heavily penalize
    }

    // Non-linear penalty on small post-residuals (tight fits are good,
    // but near-zero leftovers that block future items are bad).
    if post_residual < item_size {
        score += (item_size - post_residual) as f64 * 0.35;
    }

    // Reward very tight fits (post_residual near zero but usable).
    if post_residual <= 3 {
        score -= 25.0;
    }

    // Open-bins pressure: discourage spreading across many bins
    // unless the fit is genuinely tight.
    let open_pressure = open_bins_count as f64 * 1.5;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is already "committed"; prefer filling it rather than leaving it.
    let residual_gap = mean_residual - post_residual as f64;
    if residual_gap > 0.0 {
        score -= residual_gap * 0.2;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item
    // would leave a large awkward gap in every existing bin, or lookahead
    // suggests a big next item needing fresh capacity.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is only chosen when genuinely better.
        score += 55.0;
        if next_item_size > 0 && next_item_size > post_residual + 20 {
            score -= 20.0; // lookahead: next item is big, fresh capacity helps
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no existing bin fits: must open new bin
        }
    }

    // Lookahead: reward leaving exactly enough room for the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 18.0; // perfect two-item sequence
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.25; // next item won't fit here
    }

    // Slight stream-progression tilt: later in the stream, be more conservative
    // about opening bins (closing out existing space matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (waste minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fills the post
    // residual, this placement chains perfectly — huge reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how tightly it packs.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 150.0 * tightness;
            // Extra reward if next item leaves a still-usable residual.
            let chain_residual = post_residual - next_item_size;
            if chain_residual >= 10 {
                score -= 40.0;
            }
        } else {
            // Next item does NOT fit after this placement: penalize,
            // scaled by how badly it misses (dead-space risk).
            let miss = (next_item_size - post_residual) as f64;
            score += 30.0 + 2.0 * miss;
        }
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving this bin far below average residual creates an outlier
    // sliver that is hard to reuse later.
    let pr = post_residual as f64;
    if pr < mean_residual * 0.5 {
        score += 25.0 * (mean_residual - pr) / bin_capacity as f64;
    } else if pr > mean_residual {
        // Keeping residual above average is mildly good (reusable space).
        score -= 10.0 * (pr - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when the item would leave a very tight
    // fit elsewhere — new bins are expensive early/mid stream.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * (1.0 - progress);
        // But if the item is large and no good fit exists, new bin is fine.
        if item_size >= 60 && fitting_bins_count <= 1 {
            score -= 100.0;
        }
    }

    // Mild preference for bins with larger residual when scores tie out:
    // keeps big holes available for big items.
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor small post-residual.
    score += (post_residual as f64 / cap).powi(3) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving dead space below the smallest plausible item (1..100 unknown, use item_size as proxy).
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64 / cap) * 15.0;
        } else {
            score += 8.0; // next item forced elsewhere
        }
        // Chain fit: residual fits next item AND next item's remainder stays usable
        if next_item_size <= post_residual && post_residual - next_item_size >= 10.min(next_item_size) {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless current bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap);
        // Penalize new bins more early on and when open bins still have room.
        score += 18.0 + 25.0 * (1.0 - progress) + (mean_residual / cap) * 20.0;
        // Allow new bin when very few fitting bins exist and mean residual is low.
        if fitting_bins_count <= 1 && mean_residual < cap * 0.25 {
            score -= 30.0;
        }
        // Late stream: consolidate instead of opening bins.
        if progress > 0.7 {
            score += 15.0;
        }
        let _ = crowd;
    }

    // Mild preference for filling bins that are already partially used (fragmentation control).
    if !is_new_bin {
        score -= (bin_residual as f64 / cap) * 3.0;
    }

    // Global pressure: many open bins -> favor packing into existing ones.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: when average slack is high, avoid creating more slack variance.
    if !is_new_bin {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev / cap * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Base: strongly prefer small post_residual (tight fits), with smooth
    // polynomial shaping that punishes both large residual and mid-range waste.
    let mut score = norm_post * norm_post * (2.0 + 1.5 * progress) + norm_post;

    // Smooth coupling: residual waste matters more as the stream progresses
    // (less opportunity to recover dead space later).
    score += 0.8 * norm_post * (1.0 - norm_post) * (1.0 + progress);

    // Lookahead: reward bins whose post_residual can host the next item,
    // penalize post_residual that is nearly-but-not-quite fitting it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 1.2 * (1.0 - slack * slack);
        } else {
            let gap = (nxt - post) / cap;
            score += 0.6 * gap * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 0.5 + 0.5 * progress;
    }

    // New-bin candidate (residual == capacity): penalize mildly so a new bin is
    // opened only when all existing fits are poor; penalty decays with progress.
    if bin_residual == bin_capacity {
        score += 1.5 + 0.8 * (1.0 - progress) + 0.002 * open_bins_count as f64;
    }

    // Diversification: when many bins are open, mildly discourage adding to
    // already-crowded state unless the fit is tight.
    score += 0.01 * open_bins_count as f64 * norm_post;

    // Mean-residual coupling: prefer bins below mean residual (tighter than average).
    score += 0.5 * (mean_residual - post) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in [1,9] is nearly unusable
    // (min item size 1, but small fragments waste capacity). Penalize small
    // nonzero residuals with a nonlinear ramp.
    if post_residual > 0 && post_residual <= 9 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Perfect fit: zero post residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Can the next item (lookahead k=2) fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Good: chain placement possible. Reward proportional to how snugly
            // the next item fits (small leftover after chaining).
            let chain_left = post_residual - next_item_size;
            score -= 25.0 + (chain_left as f64).min(20.0) * 1.5;
        } else {
            // Next item cannot follow: the residual becomes dead space unless
            // another future item fits. Penalize proportionally to waste.
            let waste = post_residual as f64;
            score += waste * 0.6;
            // Extra penalty if residual falls in a "harmonic dead zone":
            // too small for typical mid-size items (harmonic classes of
            // capacity: (0,10), [10,25), [25,50), [50,100]).
            if post_residual < 25 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: only this bin fits the item; strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: residual == capacity. Only prefer a fresh bin when
    // this bin would leave a very poor residual (large dead space).
    if bin_residual == bin_capacity {
        // Fresh bin baseline: score = capacity - item_size, i.e. post_residual.
        // Add mild bias so an existing bin wins unless fit is terrible.
        score += 30.0;
        // But if placing into any open bin would waste > 50% of the item's
        // complement, fresh bin becomes attractive: emulate via mean residual.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 45.0;
        }
    } else {
        // Existing bin: reward tightness of fit (item fills most of residual).
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= fill_ratio * 20.0;
    }

    // Harmonic class thresholds on post_residual via integer division:
    // residuals in [50,100) are half-bin class — still valuable, keep mild
    // reward; residuals in [25,50) quarter-bin class.
    let class = post_residual / 25; // 0,1,2,3,4
    score -= class as f64 * 4.0;

    // Prefer consolidating into fewer bins when many are open with slack.
    if open_bins_count > 4 && post_residual < 30 {
        score += 8.0;
    }

    // Early stream: be slightly greedy with tight fits to build dense bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if progress < 0.2 && post_residual <= 10 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A gap is "dead" if it is smaller than the smallest possible item (1),
    // but practically we penalize gaps that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        // Unusable sliver: heavy penalty proportional to its wastefulness
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual > 0 && post_residual < item_size.max(1) {
        // Gap smaller than current item: likely dead space
        score += 15.0;
    }

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, prefer packing into
    // existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it attractive only when the fit would be
    // excellent (fresh bin gives full capacity) but penalize it when open
    // bins exist that could absorb the item reasonably.
    if bin_residual == bin_capacity {
        // Fresh bin: residual after placement = capacity - item_size.
        // Reward a fresh bin if the item is large (would leave little dead space),
        // penalize if small item would waste most of the bin.
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 30.0 * waste_frac;
        score -= 5.0; // slight baseline bonus for flexibility of fresh space
        // Under high open-bin pressure, discourage opening yet another bin
        score += open_bins_count as f64 * 0.4;
    }

    // Lookahead: if the next item would fit into the post-residual, reward
    // leaving exactly that much room; otherwise penalize mismatched gaps.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Mild tie-break toward bins below mean residual (tighter bins get packed first)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual
    // matches the next item's size exactly or closely.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 >= nxt {
            // next item could also fit here: reward tight coupling
            score -= (30.0 * (1.0 - diff / 100.0)).max(0.0);
            if diff == 0.0 {
                score -= 150.0;
            }
        } else {
            // next item would NOT fit: penalize dead space relative to next size
            score += 0.5 * (nxt - post_residual as f64);
        }
    }

    // Compare post_residual against mean residual: leaving far less
    // than average residual is good (tight packing).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless post_residual is tiny/dead.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
        if post_residual > 0 && post_residual < 10 {
            score += 120.0; // tiny dead space, maybe prefer new bin
        }
    }

    // Penalize new-bin candidate slightly so we reuse bins unless clearly better
    if bin_residual == bin_capacity {
        score += 60.0;
        // But if lookahead shows next item is huge, fresh bin is attractive
        if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
            score -= 90.0;
        }
    }

    // Early in stream: be slightly more willing to open bins for flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post residual, the better.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.3;

    // Penalize large dead space that likely becomes unusable.
    if post_residual < 10 {
        score -= 25.0; // nearly perfect fill
    } else if post_residual > 60 {
        score += 15.0; // large leftover, low quality
    }

    // Lookahead: reward if next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let leftover_after_next = post_residual - next_item_size;
            score -= 12.0 + leftover_after_next as f64 * 0.2;
        } else {
            score += 6.0;
        }
    } else {
        // Last item: just minimize waste.
        score += post_residual as f64 * 0.1;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // When many bins are open, encourage consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
    score -= pressure * (0.5 + progress);

    // Prefer bins whose residual is close to the mean residual (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: only attractive when current fits are poor or
    // residuals are fragmented; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let poor_fits = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { 1.0 };
        let desperation = (fitting_bins_count as f64).min(3.0);
        score += 40.0 - 12.0 * desperation - poor_fits * 5.0 + progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic polynomial in normalized post residual, modulated by progress.
    let mut score = norm_pr * (1.0 + 0.8 * progress) + 1.5 * norm_pr * norm_pr * (1.0 - progress);

    // Smooth cubic interaction: tight fits rewarded more as stream progresses.
    score -= 2.0 * norm_item * (1.0 - norm_pr) * (0.5 + progress);

    // Penalize small-but-unusable dead space via smooth sigmoid-like term.
    let dead = norm_pr * (1.0 - norm_pr);
    score += 0.5 * (1.0 - 4.0 * dead) * norm_pr;

    // Last-chance bonus: strongly favor using the only fitting bin, scaled smoothly.
    let last_chance = 1.0 / (fitting_bins_count as f64);
    score -= 1.2 * last_chance * (1.0 - norm_pr);

    // Lookahead: if next item fits post residual exactly-ish, reward; smooth kernel.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let diff = (norm_pr - nx).abs();
        score -= 0.8 * (-6.0 * diff * diff) * (0.4 + 0.6 * progress);
    }

    // Mean residual coupling: prefer bins near the mean to keep balance, smooth.
    let mean_norm = mean_residual / cap;
    score += 0.3 * (norm_pr - mean_norm) * (norm_pr - mean_norm);

    // New-bin candidate: penalize opening a new bin unless post residual is large
    // relative to mean residual (smooth preference for consolidation late in stream).
    if bin_residual == bin_capacity {
        score = cap + 3.0 * (1.0 - progress) - 1.0 * mean_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes modulo 10
    let class = post_residual % 10;
    // Dead space penalty: residuals < 10 are nearly unusable for items >= 10
    if post_residual < 10 {
        score += 25.0;
    }

    // Reward exact fits strongly
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class reward: residuals divisible by 10 (multiples of capacity fraction)
    // are more likely to be filled by future items from a wide size distribution
    if class == 0 && post_residual > 0 {
        score -= 8.0;
    } else if class == 5 {
        // half-of-decade class: moderately useful
        score -= 3.0;
    } else if class >= 8 {
        // nearly-decade residuals: small bonus
        score -= 1.5;
    } else if class <= 2 && post_residual > 0 {
        // nearly-empty slivers: penalize slightly beyond raw residual
        score += 4.0;
    }

    // Integer division thresholds on post_residual: coarse capacity fractions
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.5 {
        score -= 5.0; // large leftover space is good
    } else if frac < 0.15 {
        score += 6.0; // small leftover is risky dead space
    }

    // Lookahead coupling: if next item fits the post residual exactly, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap < 10 {
            score -= 12.0;
        } else {
            score -= gap as f64 * 0.2;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size {
        // next item cannot use this residual: penalize proportional to waste
        score += (next_item_size - post_residual) as f64 * 0.1;
    }

    // Last-chance bin: strongly favor using the final fitting bin before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only prefer opening a new bin when current fit is very poor
    if bin_residual == bin_capacity {
        // neutral baseline; slight preference for keeping bins tight
        score = 100.0 - (item_size as f64 * 0.1);
        if post_residual < 25 {
            score += 20.0; // placing a big item alone leaves little room -> fine
        }
        if open_bins_count > 0 && mean_residual > item_size as f64 * 1.5 {
            score -= 15.0; // plenty of slack elsewhere; opening new bin less needed
        }
    }

    // Stream progression: late in stream, tighten up (avoid many half-empty bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // any plausible future item (<= 10, or < next_item_size) are "dead".
    if post_residual < 10 {
        score += 40.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Gap cannot host the lookahead item: strong penalty scaled by tightness
        score += 15.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward near-perfect fits (small but usable leftovers)
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Exact-fill bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, favor consolidating into
    // existing bins; with few bins, opening a new one is cheaper.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when open
    // bins are still relatively empty (mean residual high).
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3 + open_bins_count as f64 * 3.0;
    }

    // Prefer bins whose residual is already close to the item (tight fits)
    score += (bin_residual - item_size) as f64 * 0.1;

    // Late in the stream, tighten packing further (less room for slack)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_bonus = 40.0 - (post_residual as f64 - next_item_size as f64).abs() * 1.5;
        score -= match_bonus;
    } else if next_item_size > 0 {
        // Next item can't fit here after this placement: penalize dead space.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Penalize leaving large unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strong incentive to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        score += 20.0;
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            score -= 10.0; // fresh bin can host a clean pair
        }
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
