pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    let mut score = pr * (1.0 + 0.8 * prog_poly);

    // Reward tight fits with non-linear fill term
    score -= 30.0 * fill * fill * fill;

    // Penalize dead space relative to next item lookahead
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            score += 0.15 * gap * (1.0 + prog_poly);
        } else {
            score -= 10.0; // next item fits here too
        }
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 * fit_ratio;
    }

    // New-bin candidate: penalize mildly early, less late
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - prog_poly);
    }

    // Mean residual divergence penalty
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: prefer residuals that fall into
    // "usable" classes (large chunks divisible into common item sizes).
    let cap = bin_capacity as f64;

    // Class penalty based on post_residual modulo 10: residuals that are
    // multiples of 10 align with typical item granularities.
    let mod10 = post_residual % 10;
    score += mod10 as f64 * 0.8;

    // Integer-division threshold classes on post_residual.
    let cls = post_residual / 20; // 0..=5 harmonic class
    match cls {
        0 => score += 6.0,   // tiny dead space (<20) is nearly unusable
        1 => score += 2.0,   // 20..39 marginal
        2 => score -= 1.0,   // 40..59 decent
        3 => score -= 3.0,   // 60..79 good
        4 => score -= 4.0,   // 80..99 excellent
        _ => score -= 2.0,   // full bin (100)
    }

    // Reward tight fits: post_residual small relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= tightness * 12.0;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally, with a harmonic-class bonus when the
            // leftover after the next item is again a multiple of 10.
            let nxt_left = post_residual - next_item_size;
            score -= 4.0 * (next_item_size as f64) / cap;
            score -= (10 - (nxt_left % 10)) as f64 * 0.3;
        } else {
            // Next item won't fit here; penalize slightly more if this bin
            // would then be stranded with small residual.
            if post_residual < 20 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin starts from full residual;
    // only prefer it when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Penalize opening new bins early in the stream or when open bins exist.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 8.0 * (1.0 - progress);
        if open_bins_count > 0 {
            score += (open_bins_count as f64).sqrt() * 2.0;
        }
        // But if mean residual across open bins is tiny, new bin is fine.
        score -= (mean_residual / cap).max(0.0) * 10.0;
        // If next item is large, a fresh bin is attractive.
        score -= (next_item_size as f64) / cap * 6.0;
    }

    // Mild penalty for spreading across too many open bins.
    score += (open_bins_count as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residual gaps that are too small
    // to be useful for future items (sizes 1..=100, but typical items leave
    // gaps that can only host small items). A post_residual that is nonzero
    // but below the plausible minimum item size is pure dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Penalize "awkward" mid-range dead space that few item sizes can use:
    // gaps in (0, 30) are risky unless next item fits exactly.
    if post_residual > 0 && post_residual < 30 {
        let awkwardness = (30.0 - post_residual as f64) / 30.0;
        score += 25.0 * awkwardness;
        // Strong reward if the lookahead item exactly consumes the gap.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            // Lookahead cannot use this gap -> it is likely dead space.
            score += 15.0 * awkwardness;
        }
    }

    // Perfect fit is always excellent.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bonus: if this is the only bin that fits the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.5 * item_size as f64;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins (penalize new-bin candidate and low-fill bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when existing bins are nearly full
    // (high mean fill) or when no open bin fits well.
    if bin_residual == bin_capacity {
        let mean_fill = bin_capacity as f64 - mean_residual;
        let mean_fill_ratio = mean_fill / bin_capacity as f64;
        score += 45.0 * mean_fill_ratio; // high fill elsewhere -> new bin ok
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing else fits, must open new bin
        }
    }

    // Mild preference for bins whose residual is close to the item size
    // (tight fit reduces fragmentation).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness * tightness;

    // Coupling with mean residual: if this bin's residual deviates strongly
    // from the mean, slightly discourage (keeps residual distribution tidy).
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
