pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Lookahead: reward if next item exactly fills the remaining gap
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits: mild reward proportional to how snugly it fits after
            let after = post_residual - next_item_size;
            score -= 50.0 * (1.0 - after as f64 / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize
            score += 0.6 * (next_item_size - post_residual) as f64;
        }
    }

    // Last chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Penalize creating small unusable gaps (dead space below minimum item size 1..)
    // treat gaps < 10 as near-dead
    if post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    }

    // New bin candidate logic: only attractive if this bin would leave a large,
    // reusable residual and other bins are crowded (high mean residual usage)
    if bin_residual == bin_capacity {
        // baseline preference for new bin when open bins are tight
        let tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score -= 80.0 * tightness;
        // early in stream, new bins are cheap; later, discourage spreading
        score += 60.0 * progress;
        // if a perfect-ish fit exists elsewhere (post_residual small), this is penalized naturally
    }

    // Favor packing into bins whose residual is close to item (snug fit)
    let snug = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 30.0 * snug;

    // Mild preference to balance load across many open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    // Coupling: penalize if this bin's residual deviates strongly from mean residual
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual (tight fit), with quadratic sharpening
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth non-linear coupling of post_residual with stream progress:
    // late in the stream, waste matters more; early, flexibility matters.
    let coupling = pr_norm * (1.0 - progress) * (progress * 3.0);
    score += 20.0 * coupling * (pr_norm - 0.5).abs();

    // Penalize large post-residuals that no plausible next item can use
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).abs();
        score -= 8.0 * (1.0 - gap / cap).max(0.0) * (1.0 - pr_norm);
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild penalty for straying far from mean residual (keeps bin population homogeneous)
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    // Slight preference to consolidate into fewer bins as stream advances
    score += (pr_norm * (open_bins_count as f64).ln() * progress) * 3.0;

    // New-bin candidate: make it attractive only when no open bin fits well
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        score += 25.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is only "usable" if it can
    // hold plausible future items. Classify post_residual into residue classes
    // modulo 10 (smallest item granularity).
    let pr = post_residual;
    let class = pr / 10; // integer division threshold: 0..=10
    match class {
        0 => score -= 60.0,                    // 0..9: nearly dead, but tiny waste
        1 => score -= 40.0,                    // 10..19: can fit a min item
        2 => score -= 25.0,                    // 20..29
        3 => score -= 12.0,                    // 30..39
        4 => score -= 5.0,                     // 40..49
        5 => score -= 0.0,                     // 50..59: half-empty, mediocre
        6 => score += 8.0,                     // 60..69: dead space risk grows
        7 => score += 18.0,
        8 => score += 30.0,
        9 => score += 45.0,
        _ => {}                                // full bin leftover = new-bin-like
    }

    // Exact modulo arithmetic: post_residual exactly divisible by common item
    // sizes (10,20,25,50) means a future item can tile it perfectly.
    if pr > 0 {
        if pr % 10 == 0 { score -= 15.0; }
        if pr % 25 == 0 { score -= 10.0; }
        if pr % 50 == 0 { score -= 8.0; }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            // next item fits: penalize by leftover after next placement
            let after_next = pr - next_item_size;
            score += after_next as f64 * 0.3;
            // harmonic bonus if next tiles it exactly via division
            if pr % next_item_size.max(1) == 0 { score -= 20.0; }
        } else {
            // next item cannot use this residual: residual likely dead
            score += pr.min(next_item_size) as f64 * 0.15;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, force usage.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: keep it attractive only when current bin
    // would leave large dead space and next item is large.
    if bin_residual == bin_capacity {
        // neutral baseline; subtract if mean residual of open bins is large
        score -= mean_residual * 0.4;
        if next_item_size > 50 { score -= 30.0; }
    }

    // Mild global pressure: fewer open bins -> prefer filling existing ones.
    score += (open_bins_count as f64) * 0.5;

    // Stream progression: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (100.0 - post_residual as f64) * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead-space gaps (below smallest plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Harsher penalty for gaps that next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= (item_size as f64) * (1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0)) * 0.5;
    }

    // Open-bin pressure: fewer open bins is better; penalize spreading across many bins.
    score += (open_bins_count as f64) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: mildly penalize so we only open when open bins are bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Stream progression: late in the stream, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into post_residual (good lookahead match), reward closeness.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: penalize proportionally.
        let overflow = (next_item_size - post_residual) as f64;
        score += 0.3 * overflow;
    }

    // Penalize leaving residuals far below mean (fragmenting usable space).
    score += 0.4 * (mean_residual - post_residual as f64).abs();

    // Tight fits (small post_residual) are good; reward quadratic tightness.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 15.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Early stream: be more conservative about filling bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let bad_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual < next_item_size);
        if bad_fit {
            score -= 30.0;
        } else {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: small leftover relative to item size
    let tightness = post_residual as f64 / (item_size as f64 + 1.0);
    score -= 80.0 / (1.0 + tightness);

    // Penalize dead space that cannot fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny unusable sliver
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // penalize wasting space the known next item can't use
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Many open bins: prefer consolidating into existing bins
    score += open_bins_count as f64 * 2.0;

    // Deviation from mean residual: prefer bins whose residual is close to item need
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Time horizon: early in stream, be pickier about waste; late, just pack
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * (1.0 - progress);

    // New-bin candidate handling: empty bin gets large residual; penalize mildly
    // unless it's the only option (handled by last-chance logic above).
    if bin_residual == bin_capacity {
        score += 60.0;
        // Early in stream, opening fresh bins is cheaper long-term
        score -= 80.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalize quantities
    let pr = post_residual as f64 / cap;                 // post residual in [0,1)
    let ir = bin_residual as f64 / cap;                  // pre residual
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let next_r = if next_item_size > 0 { next_item_size as f64 / cap } else { 0.0 };

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) are worth more.
    let tightness = (1.0 - pr) * (1.0 - pr);             // quadratic tightness term
    score -= 8.0 * tightness * (0.5 + 0.5 * progress);

    // Penalize dead space that no plausible next item can use (smooth sigmoid-ish gate)
    let usable = 1.0 / (1.0 + (-(pr - next_r) * 12.0).exp());
    score += 4.0 * pr * (1.0 - usable);

    // Cubic reward for near-perfect fills, amplified late in stream
    score -= 6.0 * (1.0 - pr).powi(3) * (0.3 + 0.7 * progress);

    // Mild penalty when this bin's residual is far above the mean residual (fragmentation)
    score += 1.5 * (ir - mean_residual / cap).abs();

    // Last-chance bonus: only one bin can fit the item
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Discard spreading across many bins early: slight preference to consolidate
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    // Lookahead synergy: reward leaving a gap that fits the next item exactly-ish
    if next_item_size > 0 {
        let gap_err = (pr - next_r).abs();
        score -= 3.0 * (1.0 - gap_err).powi(2);
    }

    // New-bin candidate: neutral-to-slightly-high baseline so it wins only when
    // existing fits are poor; encourage opening fresh bins early in the stream.
    if bin_residual == bin_capacity {
        score += 2.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that form "nice" future
    // pairings (multiples of 10, 5, quarter/half capacity) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let mut bonus = 0.0;
        if pr % 10 == 0 { bonus += 6.0; }
        if pr % 5 == 0 { bonus += 2.0; }
        if pr * 4 == bin_capacity { bonus += 8.0; }   // exact quarter
        if pr * 2 == bin_capacity { bonus += 10.0; }  // exact half
        if pr % 20 == 0 { bonus += 4.0; }
        score -= bonus;

        // Dead-space penalty for tiny unusable slivers.
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0;
        }
        // Integer-division threshold classes: penalize awkward mid-range slivers.
        let q = pr / 10; // decade class of post residual
        if q == 1 { score += 4.0; } else if q == 3 { score += 2.0; }
    } else {
        // Perfect closure: strongly reward filling a bin exactly.
        score -= 30.0;
    }

    // Lookahead coupling: if next item divides the post residual evenly,
    // this bin is a perfect home for the future item too.
    if next_item_size > 0 && next_item_size <= pr {
        if pr % next_item_size == 0 {
            score -= 12.0;
        } else {
            let r = pr % next_item_size;
            score += r as f64 * 0.3; // penalize leftover after next item
        }
    } else if next_item_size > pr {
        // Next item won't fit here; slight penalty proportional to gap class.
        let gap = (next_item_size - pr) / 10;
        score += gap as f64 * 1.5;
    }

    // Last-chance bin before opening a new bin: strong reward to use it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count - 2) as f64 * 1.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or mean residual can't host the item well.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * 8.0;
        let poor_fit = (mean_residual - item_size as f64).abs();
        score = cap * 0.5 + crowded * 0.5 + poor_fit * 0.4
            - if fitting_bins_count <= 1 { 25.0 } else { 0.0 }
            - if next_item_size > 0 && next_item_size >= item_size { 5.0 } else { 0.0 };
    }

    // Stream progression: early on, be conservative about fragmenting bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (small residuals) are heavily penalized.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Dead space penalty grows steeply for tiny unusable gaps.
        if post_residual < 10 {
            score += 40.0 * (10.0 - pr) / 10.0;
        } else if post_residual < 20 {
            score += 15.0 * (20.0 - pr) / 10.0;
        }
    } else {
        // Perfect fill is strongly rewarded.
        score -= 60.0;
    }

    // Reward tight fits: post_residual small relative to item size.
    let tightness = pr / (item_size as f64).max(1.0);
    score += 10.0 * tightness;

    // Open-bin pressure: penalize placements into bins when many bins are open,
    // to encourage consolidation into fewer bins when possible.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if next item could use the post_residual, reward leaving it.
    if next_item_size > 0 && post_residual > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 12.0;
        } else {
            // Next item won't fit in the gap -> gap is likely dead space.
            score += 8.0;
        }
    }

    // New-bin candidate handling: mildly discourage opening a new bin unless
    // the fit into existing bins is bad.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Opening a new bin is more attractive early (more future items to fill it),
        // and when mean residual across open bins is small (poor existing fits).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: penalize tight-but-wasteful residuals less than large leftovers.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score += 0.35 * (1.0 - tightness) * (post_residual as f64);

    // 2-step lookahead: reward bins whose post_residual exactly accommodates the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chaining: residual consumed by next item
        } else if post_residual >= next_item_size {
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_slack / bin_capacity as f64); // near-exact chain
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 * (gap / next_item_size.max(1) as f64).min(1.0); // next item can't use this residual
        }
    }

    // Relative-to-mean residual coupling: prefer bins below mean residual (tighter bins).
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize leaving dead space that few future items could fill (small post_residual but nonzero).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Early in stream: allow opening new bins more freely to build a good bin portfolio.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let new_bin_penalty = 12.0 * (1.0 - progress);
        score = bin_capacity as f64 + new_bin_penalty
            - if next_item_size > 0 && next_item_size <= bin_capacity { 0.0 } else { 0.0 };
        // Opening a new bin is attractive only if no open bin chains well with the next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
        if open_bins_count == 0 {
            score -= 1000.0; // must open first bin
        }
    }

    // Late stream: consolidate; discourage new bins when open bins fit.
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.35 * tightness * (bin_residual as f64);

    // Penalize dead space that cannot fit typical future items (dead zone below ~ item_size).
    if post_residual > 0 && post_residual < item_size {
        score += 6.0 * (item_size - post_residual) as f64;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize more if leftover is small (waste)
            score += 3.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bonus: only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer fuller bins when many bins are open (reduce fragmentation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * (open_bins_count as f64).sqrt() * 2.0;

    // Time horizon: early in stream, be more willing to open new bins for large items
    // (keep flexibility); late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (10.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64) - 4.0 * progress);

    // Prefer bins whose residual is near the mean (balanced packing) early on.
    score += 0.5 * ((bin_residual as f64 - mean_residual).abs() / bin_capacity as f64) * (1.0 - progress);

    // Slight penalty for opening new bins when many already open.
    score += new_bin * 0.15 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;
    score += (x * x * (1.0 - progress) + x * x * x * progress) * cap * 0.5;
    score -= item_size as f64 * (1.0 + progress) * 0.3;
    score -= (fitting_bins_count as f64).ln().max(0.0) * 4.0;
    score += (open_bins_count as f64) * 0.5;
    score += (mean_residual - pr) * 0.2;
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let wasted = (pr - nxt).abs();
        score += wasted * 0.1;
        if nxt <= pr {
            score -= 8.0 * (1.0 - progress);
        }
    }
    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // New-bin candidate: penalize mildly unless residuals are large late in stream
    if bin_residual == bin_capacity {
        score += 10.0 - 6.0 * progress + 0.1 * open_bins_count as f64;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod 10 (capacity fractions).
    let r = post_residual % 10;
    // Penalize "dead" residues that are hard to fill later (1..9 small slivers).
    let dead_penalty = match r {
        0 => -6.0,                       // perfectly divisible residual is great
        1 | 2 | 8 | 9 => 4.0,            // awkward slivers
        _ => 1.0,
    };
    score += dead_penalty;

    // Integer-division thresholds: post_residual in [1..10] is near-dead space.
    if post_residual <= 10 {
        score += 12.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual <= 25 {
        score += 3.0;
    }

    // Reward tight fits: post_residual small fraction of capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    score -= 8.0 * (1.0 - frac).min(1.0) * (item_size as f64 / bin_capacity as f64);

    // Lookahead coupling: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // harmonic class: next item leaves another divisible residual
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 { score -= 6.0; }
            score -= 3.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; slightly penalize large leftovers
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits.
    if bin_residual == bin_capacity {
        if post_residual == bin_capacity {
            // empty-bin baseline; make it competitive but not dominant
            score = bin_capacity as f64 - 5.0
                - (mean_residual / bin_capacity as f64) * 10.0
                + (open_bins_count as f64 * 0.5);
        }
    }

    // Stream progression: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be
    // useful (unlikely to fit typical items). Treat small post_residual gaps
    // as wasted space and add a strong penalty.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 3.0;
    }

    // Perfect fit bonus: reward exact fills aggressively.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit bonus: reward leaving a residual that is small but still usable.
    if post_residual > 0 && (post_residual as f64) < (item_size as f64) * 0.25 {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading items across too many bins.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (balanced packing), penalize outliers.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.3;

    // Lookahead: if the next item fits well into the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack * 0.2;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item won't fit here: penalize slightly to prefer bins that
        // keep future options open.
        score += 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make opening a new bin costly unless the current item
    // is large and would leave a very awkward residual in existing bins.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 15.0;
        // But if the item is large relative to capacity, opening a new bin
        // may be preferable to fragmenting an existing one.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // If many bins are already open, opening a new one is less attractive.
        score += open_bins_count as f64 * 0.8;
    }

    // Stream progression: late in the stream, be more conservative about
    // leaving dead space (less time to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead matching
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            // Perfect chain: post_residual exactly matches next item
            let gap = post_residual as f64 - nxt;
            score -= 40.0 - gap.min(40.0); // best when gap == 0
        } else {
            // Next item won't fit here: penalize dead space relative to next item
            score += (nxt - post_residual as f64) * 0.6;
        }
    } else {
        // Last item: minimize post_residual aggressively
        score += 10.0;
    }

    // Compare against mean residual across open bins
    let pr = post_residual as f64;
    if pr < mean_residual * 0.5 {
        // Creating very tight bin below average: good packing, reward
        score -= 8.0;
    } else if pr > mean_residual * 1.5 && mean_residual > 0.0 {
        // Leaving much more space than average: mild penalty
        score += 4.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive if no good fit exists
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; penalize slightly so decent existing fits win,
        // but keep low enough to beat bins leaving unusable dead space
        score = bin_capacity as f64 * 0.5 + 15.0;
        if next_item_size > 0 {
            // An empty bin can fit any next item: small lookahead comfort
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            // If this is the only option, empty bin is fine
            score -= 20.0;
        }
    }

    // Progress-based mild preference to close out bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Slight penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth normalized post-residual (0 = perfect fill, 1 = empty bin)
    let x = (post / cap).clamp(0.0, 1.0);

    // Core non-linear polynomial coupling with stream progress:
    // later in the stream => more urgency to fill bins tightly (dead space costs more).
    let urgency = 0.5 + progress;
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep shape: punishes large residuals super-linearly
    let mut score = post * (0.6 + 0.8 * urgency * poly);

    // Reward near-perfect fits strongly (small post_residual gets extra subtraction).
    score -= (1.0 - x) * (1.0 - x) * 12.0;

    // Lookahead coupling: if the next item fits into the post-residual, reward this bin;
    // smooth interaction rather than hard threshold.
    if next_item_size > 0 {
        let nxt = (next_item_size as f64).min(cap);
        let fit_next = (post - nxt) / cap;
        if fit_next >= 0.0 {
            let tightness = 1.0 - fit_next;
            score -= 6.0 * tightness * tightness;
        } else {
            // next item won't fit: penalize leaving a gap that's too small to be useful
            let gap_useless = (nxt - post) / cap;
            score += 8.0 * gap_useless * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate handling: make an empty bin mildly unattractive unless
    // open bins are badly fragmented (high mean residual / large open count).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).max(0.0) * (open_bins_count as f64).sqrt();
        score += 10.0 - 14.0 * fragmentation - 8.0 * progress;
    }

    // Mild penalty for spreading across many open bins when this bin is much emptier than average.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (small post_residual).
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;

    // ---- Harmonic class of post_residual (mod 8) ----
    // Residuals divisible by 8 are "harmonic" slots: easy to fill later.
    let pr = post_residual;
    let class = pr % 8;
    let harmonic_bonus = match class {
        0 => 6.0,
        4 => 3.0,
        2 | 6 => 1.0,
        _ => 0.0,
    };
    score -= harmonic_bonus;

    // ---- Integer-division thresholds on post_residual ----
    // Dead space penalty grows super-linearly for tiny unusable residuals.
    if pr > 0 {
        if pr < 10 {
            // nearly-full bin: excellent, reward strongly
            score -= 8.0;
        } else if pr <= 25 {
            // awkward leftover zone: penalize
            score += (25 - pr) as f64 * 0.35;
        }
    } else {
        score -= 10.0; // perfect closure
    }

    // ---- Lookahead coupling: does next_item_size fit in post_residual? ----
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item can chain into this bin: strong reward,
            // scaled by how tight the chained fit is (harmonic pairing)
            let chain_tightness = 1.0 - (pr - next_item_size) as f64 / cap;
            score -= 5.0 + 4.0 * chain_tightness;
        } else {
            // next item will NOT fit here: mild penalty, worse for big overshoot
            let overshoot = (next_item_size - pr) as f64;
            score += overshoot * 0.08;
        }
    } else {
        // last item: just close bins tightly
        score -= 5.0;
    }

    // ---- Last-chance bin: if this is the only fitting bin, avoid opening a new one ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 7.0;
    }

    // ---- New-bin candidate handling (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
        // Default cost of opening a new bin; cheaper early in the stream
        // when few bins exist, or when open bins are already congested.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0));
        let new_bin_cost = 14.0 + 10.0 * progress - congestion.min(6.0);
        // A new bin is attractive only if the item is large relative to capacity
        // and would leave a very awkward residual elsewhere.
        let large_item = (item_size as f64 / cap) > 0.6;
        if large_item {
            score = new_bin_cost - 4.0;
        } else {
            score = new_bin_cost + (cap - item_size as f64) * 0.1;
        }
        // If many bins fit the item, discourage the fresh bin further.
        if fitting_bins_count > 2 {
            score += 6.0;
        }
    }

    // ---- Mean-residual context: prefer bins below mean residual (fill the emptier ones) ----
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // ---- Fractional capacity coupling: reward placements near half/full capacity marks ----
    let half_mark = bin_capacity / 2;
    if post_residual == half_mark {
        score -= 2.0;
    }
    if item_size == half_mark {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    let min_item = 1u32;
    if post_residual > 0 {
        // A residual gap that cannot fit even the smallest conceivable item is pure waste.
        // Penalize small post-residuals super-linearly (they are "dead space"),
        // while near-perfect fits (post_residual == 0) get a strong reward.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 6.0; // tiny gap = heavily penalized
        } else {
            // Larger residuals are still usable; mild penalty scaled by gap size.
            score += (post_residual as f64).powf(1.15) * 0.15;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward filling a bin that is the item's last chance before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bins pressure: when many bins are open, prefer compacting into existing bins
    // rather than spreading; penalize candidates that leave large residuals when open
    // bin count is high.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64) * 0.05;

    // Lookahead coupling: if the next item can exactly use the post residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            // residual can still host next item: mild reward
            score -= 5.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // residual is too small for the known next item: penalize as dead space
            score += 12.0;
        }
    } else {
        // Last item: finishing a bin tightly is ideal.
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Only prefer it when no open bin offers a decent fit, i.e. when its score
    // naturally loses to well-fitting bins but wins over badly-fitting ones.
    if bin_residual == bin_capacity {
        // Neutral base for empty bin: its post_residual is large (bin_capacity - item),
        // which via the residual penalty keeps it competitive only against poor fits.
        // Add small fixed cost to discourage opening bins unnecessarily.
        score += 8.0;
        // But if many bins are open and this bin would be nearly filled by the item,
        // opening a fresh bin may still be fine; slight relief.
        if item_size >= bin_capacity * 8 / 10 {
            score -= 15.0;
        }
    }

    // Stream progression: late in the stream, favor tighter packing (stronger
    // dead-space penalty) since fewer items remain to fill leftover gaps.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.10;

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "nearly full" bin — reward selecting it to consolidate.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 && bin_res_f < mean_residual {
        score -= (mean_residual - bin_res_f) * 0.08;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Post residual can still host next item: reward closeness to it.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack / 10.0);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead item: penalize proportionally.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.35 * waste;
    }

    // Prefer bins whose residual is already below the mean (tight bins first),
    // keeping large residuals available for larger future items.
    score += (post_residual as f64 - mean_residual) * 0.45;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current item leaves a very tight
    // fit in every open bin (i.e., item nearly fills a fresh bin) or no good fit.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 100.0 - 70.0 * tightness - 55.0 * pressure;
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 80.0; // fresh bin gives perfect lookahead fit
        }
    }

    // Late in the stream: consolidate aggressively, avoid leaving scraps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.25;

    // Mild penalty for leaving tiny unusable scraps (<10).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap;
    // reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * item_size as f64 * (0.5 + progress);
    // penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual) * (1.0 + progress);
    // lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score += 0.2 * (gap / cap) * cap;
        if pr >= nxt {
            score -= 0.5 * nxt * (1.0 - norm_pr);
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 2.0 * item_size as f64 * (1.0 - progress);
    }
    // slight penalty for opening a new bin when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 5.0 + 10.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls exactly on
    // common item-size classes (multiples of 10, and small classes 1..9) are
    // more reusable, so reward them (subtract), penalize odd dead space.
    let pr = post_residual;
    if pr > 0 {
        let cls = if pr % 10 == 0 {
            0.0 // perfect class: fits a whole decile item
        } else if pr <= 9 {
            -1.0 // tiny class: nearly perfect dead space is still dead
        } else {
            1.0 // awkward mid-class
        };
        score -= 12.0 * cls * 0.0; // placeholder no-op to keep structure
        score += match pr % 10 {
            0 => -14.0,
            1..=9 => 2.0 + (pr % 10) as f64 * 0.4,
            _ => 0.0,
        };
        // Exact division thresholds: post_residual divisible by next item
        if next_item_size > 0 && pr % next_item_size == 0 && pr > 0 {
            score -= 10.0;
        }
    }

    // Capacity fraction coupling: reward filling bins past half capacity.
    let fill = 1.0 - (post_residual as f64) / cap_f;
    if fill >= 0.5 {
        score -= 8.0 * (fill - 0.5);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a bin unless this bin's fit is bad
    // (large post_residual) or the item is huge relative to capacity.
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) / cap_f;
        score += 25.0;
        if bad_fit < 0.25 {
            score -= 20.0; // item nearly fills a fresh bin: opening is fine
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 6.0; // fresh bin wastes the lookahead pairing
        }
    }

    // Lookahead: if the next item fits the post_residual exactly, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 22.0;
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0; // lookahead can't use this bin's leftover anyway
    }

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (mean_residual / cap_f);

    // Tie-break: prefer bins with below-mean residual (tighter bins first).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (min item size 1 here, but tiny gaps still fragment space) get a
    // super-linear penalty. Gaps <= 5 are treated as near-dead.
    let pr = post_residual as f64;
    if post_residual <= 5 {
        score += 40.0 * (6.0 - pr);
    } else if post_residual <= 12 {
        score += 12.0 * (13.0 - pr);
    } else {
        // Reward moderately large usable residuals
        score -= 0.15 * pr;
    }

    // Perfect / near-perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    }

    // Tight fit relative to the bin residual: using most of the available
    // space is good (low waste fraction).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Open-bin pressure: discourage opening new bins when many bins exist;
    // encourage consolidation by penalizing selection less when open_bins_count is high.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * (1.0 - progress));

    // Mean-residual coupling: if this bin's residual is far below average,
    // it's a poor host; if above average, prefer it.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.25 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits in the post residual, reward; if it
    // almost fits (gap small), penalize wasted potential.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 18.0;
        } else if nxt - pr <= 10.0 {
            score += 8.0 * (nxt - pr);
        }
    }

    // New-bin candidate: opening a new bin is only attractive when existing
    // bins are very fragmented (high mean residual spread) or few bins fit.
    if bin_residual == bin_capacity {
        let base = 55.0 + 2.0 * open_bins_count as f64;
        let relief = if fitting_bins_count == 0 { 0.0 } else { 25.0 };
        score += base + relief - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly matches the
    // post-residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0;
        } else if next_item_size <= post_residual {
            // Next item fits here afterwards: mild reward proportional to tightness.
            let slack_after_next = post_residual - next_item_size;
            score -= 60.0 - slack_after_next as f64 * 0.5;
        } else {
            // Next item cannot use the leftover: penalize dead space.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare post-residual against mean residual: leaving less than average
    // residual is good (tight packing), leaving more is wasteful.
    score += (post_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it unattractive unless everything else is bad.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But late in the stream with many bins, a fresh bin may be cleaner.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.8 && post_residual as f64 > mean_residual + 40.0 {
            score -= 60.0;
        }
    }

    // Prefer reusing fewer bins when several fit.
    if open_bins_count > 0 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space after placement (hard to reuse later).
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.3) * 0.05;
    }
    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only bin that fits, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is only good when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Cost of a fresh bin grows with how many bins are already open (fragmentation).
        score += 25.0 + 2.0 * open_bins_count as f64;
        // If other bins fit and any has a decent fit, discourage the new bin.
        if fitting_bins_count > 0 {
            score += 35.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Lookahead: if the next item could use this bin's post-residual, reward the placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Good: leaves room for the upcoming item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // Bad: placing here destroys room needed by the next item.
            score += 15.0;
        }
    }

    // Global state coupling: if mean residual across open bins is high, prefer
    // filling the emptiest bins (score lower when this bin is emptier than average).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    // Mild preference for bins that are already partially filled (reduce bin count pressure).
    let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / (total_items as f64).max(1.0);

    // Tightness of the fit: fraction of the bin consumed by this item
    let fit_ratio = item_size as f64 / bin_capacity as f64;

    // Post-residual as a fraction of capacity (dead space proxy)
    let dead_frac = post_residual as f64 / bin_capacity as f64;

    // Smooth non-linear penalty on dead space, weighted by progress:
    // late in the stream, wasting space is increasingly costly
    let dead_penalty = dead_frac * dead_frac * (1.0 + 2.0 * progress);
    score += dead_penalty * 50.0;

    // Reward tight fits with a smooth quadratic bonus
    score -= fit_ratio * fit_ratio * 30.0;

    // Smooth coupling between post_residual and fit_ratio: a large residual
    // after a small item is doubly bad (interaction term)
    score += dead_frac * (1.0 - fit_ratio) * 20.0;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // New-bin candidate (empty bin): penalize mildly, more when many bins are open
    // and mean residual is large (existing space should be used first)
    if bin_residual == bin_capacity {
        let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        let mean_norm = (mean_residual / bin_capacity as f64).min(1.0);
        score += 25.0 + 45.0 * open_norm + 30.0 * mean_norm * (1.0 - progress);
    } else {
        // Reward using existing bins proportionally to how full they are
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 15.0 * fill * fill;
    }

    // Lookahead: penalize leaving a residual that is just barely too small
    // for the next item (smooth "near-miss" coupling)
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 0.0 && gap > -20.0 {
            score += (1.0 - (gap / -20.0)) * 15.0;
        } else if gap >= 0.0 && gap < 15.0 {
            // residual that exactly accommodates next item is great
            score -= (1.0 - gap / 15.0) * 12.0;
        }
    }

    // Mild smooth preference for consolidating into fewer bins late in stream
    score += (open_bins_count as f64).ln() * (1.0 + progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward near-exact fills.
    // post_residual in {0,1,2} is gold; small multiples of 5 or 10 are decent.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 3 {
        score -= 100.0;
    } else {
        let cls5 = post_residual % 5;
        let cls10 = post_residual % 10;
        if cls5 == 0 {
            score -= 8.0;
            if cls10 == 0 {
                score -= 8.0;
            }
        }
        // Penalize dead space that nothing (min size 1..100 range) can use.
        // Dead space grows quadratically with post_residual.
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
    }

    // Lookahead: if the next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        // Extra reward if next item exactly fills the remainder.
        if next_item_size == post_residual {
            score -= 60.0;
        }
        // Harmonic coupling: next item leaves a small residue class too.
        let nxt = post_residual - next_item_size;
        if nxt % 10 == 0 {
            score -= 15.0;
        }
    } else if next_item_size > post_residual {
        // This bin will likely be dead after this placement; penalize.
        score += 20.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Prefer denser bins: bins with residual well below mean are more packed,
    // placing into them consolidates waste.
    if bin_residual < bin_capacity {
        let diff = mean_residual - (bin_residual as f64);
        score -= diff * 0.5;
    }

    // New-bin candidate (empty bin): only attractive when open bins are poor fits
    // or many bins already open with large mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base penalty so new bins are opened only for good reason.
        score += 60.0;
        // If no open bin fits well (post_residual of this item in a fresh bin is
        // naturally bin_capacity - item_size; compare against fragmentation level).
        if open_bins_count > 0 && mean_residual < (item_size as f64) * 0.9 {
            score -= 30.0; // open bins are tight, opening new is fine
        }
        // Late in the stream, tolerate new bins slightly more.
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable" band (1..=item_size floor region)
    // are much worse than large residuals. Anything below the smallest plausible item is dead.
    if post_residual > 0 {
        let dead_threshold: f64 = 10.0;
        if (post_residual as f64) <= dead_threshold {
            score += 60.0; // pure dead space, unusable forever
        } else if post_residual < item_size {
            // gap too small for a repeat of this item size class: partial dead space
            score += 25.0 * (1.0 - (post_residual as f64) / (item_size as f64));
        }
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Reward tight fits generally: fraction of bin consumed by this placement
    let fill_fraction = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_fraction;

    // Reward bins whose residual was already small (consolidating fragmented bins)
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    score += 10.0 * residual_frac;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; penalize unless
    // this item would leave a large residual in every fitting bin anyway.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of a fresh bin, modulated by stream progress and open-bin pressure
        let mut new_bin_cost = 45.0 + 8.0 * open_pressure * (1.0 - progress);
        // If the item is large, a fresh bin is more attractive (it fills the new bin well)
        new_bin_cost -= 25.0 * fill_fraction;
        // If next item is small, leftover residual in a new bin is fine
        if next_item_size > 0 {
            let next_frac = next_item_size as f64 / bin_capacity as f64;
            new_bin_cost -= 15.0 * (1.0 - next_frac);
        }
        score += new_bin_cost;
    } else {
        // Mild reward for keeping existing bins busy instead of spawning new ones
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this residual; residual is more likely dead
        score += 8.0;
    }

    // Mean residual coupling: placing into a bin far below mean residual
    // (i.e., a bin with more space than average) is slightly preferable
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Open-bin pressure: with many open bins, favor filling existing ones harder
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer bins whose post_residual exactly matches next item (2-step lookahead).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 / (1.0 + diff);
        // Perfect 2-step fit bonus
        if post_residual == next_item_size {
            score -= 30.0;
        }
        // Penalize post_residual that is small but cannot fit the next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.6 * (post_residual as f64) * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
    } else {
        // Last item: just minimize waste
        score += 0.0;
    }

    // Compare post_residual relative to mean residual of open bins.
    // Leaving a residual below mean means we consumed the "fat" of the bin -> good.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        // new-bin candidate: base score is residual (=capacity); add pressure unless nothing fits well
        let tight_fit_exists = fitting_bins_count > 0 && (post_residual as f64) <= mean_residual;
        if tight_fit_exists {
            score += 15.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // new bin leaves room for next item
        }
    }

    // Slight preference for tighter bins overall (smaller residual before placement).
    score += 0.15 * (bin_residual as f64 - item_size as f64);

    // Late in stream: be more conservative, avoid creating tiny unusable residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (0.5 + progress);
    }

    // Many open bins: prefer consolidation into existing bins.
    score += 0.4 * open_bins_count as f64 * (if bin_residual == bin_capacity { 1.0 } else { 0.0 });

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: strongly discount small post_residual.
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 45.0 * tight * tight;

    // Penalize tiny but useless leftover slivers that likely become dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item can fit into the resulting residual,
    // this placement chains nicely; otherwise the residual is likely wasted.
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when existing residuals
    // are large (item would leave a big hole anyway) or many bins are open.
    if bin_residual == bin_capacity {
        let hole = post_residual as f64; // = cap - item_size for a fresh bin
        let global_pressure = mean_residual / cap;
        let time = step_index as f64 / (total_items.max(1) as f64);
        let reluctance = 40.0 * (1.0 - global_pressure) + 25.0 * time
            + 8.0 * (open_bins_count as f64).ln().max(0.0);
        score += reluctance - 0.5 * hole;
        // Fresh bin is great for big items (small hole) but wasteful for small ones.
        if item_size as f64 > 0.6 * cap {
            score -= 20.0;
        }
        if next_item_size > 0 && (hole as u64) < next_item_size as u64 && hole < 15.0 {
            score += 10.0; // fresh bin can't serve next item either
        }
    }

    // Mild diversity bonus: spreading load over open bins keeps flexibility
    // when mean residual is high, but concentrate when residuals are tight.
    if bin_residual != bin_capacity {
        let spread = (bin_residual as f64 - mean_residual).abs();
        score += 0.10 * spread;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: mild quadratic damping of residual (tolerate slack). Late: steep
    // quartic penalty on residual so tight fits dominate as the stream ends.
    let q = pr / cap;
    let poly = q * q * (1.0 - progress) + q.powi(4) * (1.0 + 3.0 * progress);
    score += poly * cap * 0.5;

    // Reward near-perfect fits via smooth residual sigmoid-like term.
    let tight = ((cap - pr) / cap - 0.98) * 50.0;
    score -= 4.0 / (1.0 + (-tight).exp());

    // Penalize bins whose residual deviates far from the mean residual
    // (keeps the fleet homogeneous and combinatorially manageable).
    let dev = (pr - mean_residual) / cap;
    score += 2.0 * dev * dev * cap * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward use.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward leaving a residual that fits the next item
    // smoothly (cosine kernel around exact fit), penalize otherwise.
    if next_item_size > 0 && next_item_size as f64 <= pr {
        let diff = pr - next_item_size as f64;
        score -= 3.0 * (1.0 + (std::f64::consts::PI * diff / cap).cos());
    } else if next_item_size as f64 > pr {
        score += 2.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    // Reward filling the new-bin candidate only when item is large.
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful slots"
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Class A: near-perfect fit (tiny residual) -> strong reward
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Integer-division harmonic classes on post_residual (mod buckets of 10)
    let class = post_residual / 10; // 0..=10
    match class {
        0 => score -= 15.0,               // 0-9: excellent fill
        1 => score -= 8.0,                // 10-19: good
        2 => score -= 3.0,                // 20-29: ok
        3 => score += 2.0,                // 30-39: mediocre
        4 => score += 6.0,                // 40-49: poor
        5 => score += 10.0,               // 50-59: half empty
        6 => score += 12.0,
        7 => score += 13.0,
        8 => score += 12.0,               // 80-89: still usable for small items
        9 => score += 8.0,
        _ => {}                            // full bin: base 0 residual already good
    }

    // Coupling with next item: does the leftover post_residual accommodate it?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // leftover is reusable by lookahead -> reward proportionally
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // dead space relative to lookahead -> penalize by gap size
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
            // extra penalty if gap is in an awkward harmonic band
            if gap > 20.0 && gap < 40.0 {
                score += 5.0;
            }
        }
        // modulo arithmetic: if next item and residual share harmonic class (mod 10)
        if next_item_size % 10 == post_residual % 10 && post_residual > 0 {
            score -= 4.0;
        }
        let _ = nxt;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits would leave large dead space
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin: slightly worse than a decent fit
        score = cap - item_size as f64; // residual of fresh bin = 100 - item
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative: must open
        }
        // prefer opening a new bin late in the stream when open bins are crowded
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < item_size as f64 * 1.2 {
            score -= 10.0;
        }
        if progress > 0.8 && open_bins_count > 4 {
            score += 5.0; // discourage bin sprawl late in stream
        }
    } else {
        // mild preference to keep using existing bins when mean residual is high
        if mean_residual > 0.5 * cap {
            score -= 3.0;
        }
    }

    // Tiny tie-breaker toward tighter bins
    score += (bin_residual as f64 - item_size as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual that cannot accommodate even the smallest plausible item (1)
    // is pure waste; residuals below ~10 are near-waste.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Tiny dead space: heavy penalty on top of the raw residual.
        score += (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits proportionally: smaller post_residual relative to capacity.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // this placement sets up a perfect chain — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item cannot use the residual: penalize large wasted gaps.
            score += post_residual as f64 * 0.2;
        }
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // bins with small residuals to close them out; when few bins are open,
    // spreading is cheaper so slightly favor new bins.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base attractiveness, moderated by how badly
        // existing bins fit (fitting_bins_count) and open-bin pressure.
        score = 55.0 + pressure * 3.0 - (fitting_bins_count as f64) * 4.0;
        // If the only fitting bin is this new one, opening is necessary.
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // Early in the stream, opening bins is cheap.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    } else {
        // Existing bin: bonus if it's the last chance to use it.
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Prefer bins whose residual is below mean (tighter bins) to close them.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
        // With many open bins, reward placements that reduce total residual variance
        // (i.e., drain nearly-full bins).
        score += (bin_residual as f64 - mean_residual).abs() * 0.05 * (pressure / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
