pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize high post_residual more strongly when it's small.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: if the next item can fit in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // next item fits here too but we'd waste; slight penalty for greedy waste
            score += 3.0;
        }
        // Penalize leaving residual just under the next item size (dead space trap)
        if post_residual > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Prefer filling bins with larger residuals when many bins are open (bin consolidation).
    if open_bins_count > 3 {
        let residual_gap = bin_residual as f64 - mean_residual;
        score -= residual_gap * 0.25;
    }

    // Early in stream: be selective, prefer near-exact fits; later: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0;
    score += (1.0 - progress) * post_residual as f64 * 0.1;

    // New-bin candidate: only attractive when no decent fit exists.
    if bin_residual == bin_capacity {
        let avg_needed = mean_residual.max(0.0);
        if fitting_bins_count == 0 {
            score -= 40.0; // must open new bin
        } else if fitting_bins_count == 1 {
            score += 10.0; // prefer using the single fitting bin
        } else {
            // open new bin if all existing fits would leave large dead space
            if post_residual as f64 > avg_needed * 0.9 && post_residual > 20 {
                score -= 5.0;
            } else {
                score += 8.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste minimization with non-linear (quadratic) penalty on residual.
    let mut score = pr * (1.0 + norm_pr);

    // Smooth progress coupling: later in the stream, prefer tighter packing.
    let tighten = 1.0 + 0.8 * progress * progress;
    score *= tighten;

    // Reward near-perfect fits with a smooth saturating term.
    let fit_quality = 1.0 - norm_pr;
    score -= 12.0 * fit_quality * fit_quality * fit_quality;

    // Penalize residuals that cannot accommodate the lookahead item (smooth coupling).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 8.0 * gap * gap;
        // Reward residual that exactly or nearly fits the next item.
        let next_fit = (pr - next_item_size as f64).abs() / cap;
        score -= 6.0 * (1.0 - next_fit.min(1.0));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize proportional to how many bins are already open,
    // smoothly decaying as stream progresses (consolidation incentive).
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // Allow opening new bins when mean residual across open bins is small.
        score -= (mean_residual / cap).min(1.0) * 10.0;
    } else {
        // Slight reward for bins with residual below the mean (above-average fill).
        let diff = (mean_residual - pr) / cap;
        score += 4.0 * diff.max(0.0);
    }

    // Small cubic regularization on normalized residual to break ties smoothly.
    score += 2.0 * norm_pr * norm_pr * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction bands.
    let cap = bin_capacity as f64;
    let half = cap / 2.0;
    let third = cap / 3.0;
    let quarter = cap / 4.0;
    let post = post_residual as f64;

    // Dead-space penalty: leftovers in awkward bands (just above a fraction) are hard to fill.
    if post > 0.0 {
        if post < 10.0 {
            score -= 8.0; // tiny sliver: effectively filled
        } else if post <= quarter {
            score -= 2.0;
        } else if post <= third {
            score += 3.0;
        } else if post <= half {
            score -= 1.0;
        } else {
            score += 5.0; // more than half wasted
        }
    }

    // Modulo-10 residue class of post_residual: multiples of 10 pair well with typical item sizes.
    let m = post_residual % 10;
    if m == 0 {
        score -= 3.0;
    } else if m >= 5 {
        score += 1.5;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot fit here; leftover is dead unless tiny
            if post_residual < 10 {
                score -= 2.0;
            } else {
                score += (next_item_size - post_residual).min(40) as f64 * 0.15;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it unattractive
    // unless no open bin is a decent fit or the fit is terrible.
    if bin_residual == bin_capacity {
        let waste = (cap - item_size as f64) / cap;
        score = cap - item_size as f64;
        // penalize opening new bins when good fits exist
        if fitting_bins_count > 0 {
            score += 20.0;
            if mean_residual >= item_size as f64 + 5.0 {
                score += 15.0;
            }
        }
        // late in the stream, prefer closing out open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0;
        if waste < 0.2 {
            score -= 10.0; // item nearly fills a fresh bin
        }
    }

    // Tight-fit bonus: leaving near-zero residual is ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Slight preference for bins below mean residual (consolidating emptier bins).
    if bin_residual < bin_capacity {
        score += (mean_residual - post).clamp(-10.0, 10.0) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that is too small to hold any plausible future item (<= 10)
    // is pure waste; penalize quadratically relative to capacity.
    if post_residual <= 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 15.0;
    } else if post_residual <= 40 {
        score += 5.0;
    }

    // Reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: when many bins are open,
    // prefer filling existing bins rather than spreading out.
    let open_pressure = open_bins_count as f64 * 0.5;
    if bin_residual != bin_capacity {
        score -= open_pressure;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.2;
    }

    // Prefer bins whose residual is close to the item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 10.0;

    // Progress bias: later in the stream, be slightly more conservative
    // about leaving small gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward post_residual that matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.9 * diff;

        // Perfect chaining: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 25.0;
        }

        // Penalize leaving a residual slightly larger than next item (dead space trap).
        if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score += 8.0;
        }
    }

    // Compare against mean residual: penalize creating residuals well below the mean
    // (fragmenting), reward keeping residuals near/above the mean.
    let res = post_residual as f64;
    if res < mean_residual {
        score += 0.6 * (mean_residual - res);
    } else {
        score -= 0.3 * (res - mean_residual);
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If no open bin fits, opening a new bin is necessary.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Penalize high bin occupancy pressure (many open bins) when wasting space.
    score += 0.15 * (open_bins_count as f64) * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), with mild squashing of extremes.
    let mut score = post + 0.35 * (post / cap) * (post / cap) * cap;

    // Reward near-perfect packing: small post_residual gets a bonus.
    if post_residual == 0 {
        score -= 12.0;
    } else if post_residual <= 5 {
        score -= 6.0;
    }

    // Penalize creating dead space that no plausible item (1..=100) can use well:
    // a residual just above a "hard" size is wasteful; residuals <= 10 are fine.
    let dead = if post_residual > 0 && post_residual < 10 {
        0.0
    } else {
        // residual in awkward mid-range is less attractive
        0.5 * ((post_residual as f64) / 10.0).min(3.0)
    };
    score += dead;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward scaled by how much slack remains after it
            let after_next = post_residual - next_item_size;
            score -= 5.0 - 0.05 * after_next as f64;
        } else {
            // next item would NOT fit here: mild penalty, stronger if residual is large
            score += 1.5 + 0.03 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Global state: with many open bins, prefer consolidating into existing ones
    // (penalize opening new bins when fragmentation already exists).
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / cap.max(1.0) + 1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost, modulated by fit quality and stream position.
        score += 6.0 + 0.10 * open_bins_count as f64;
        // Late in the stream, opening a fresh bin is more acceptable (less future to pack).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 4.0 * progress;
        // If item is large, a fresh bin is natural.
        score -= 0.04 * item_size as f64;
        // If next item is small, it can top off this new bin later: slight bonus.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 2.0;
        }
    } else {
        // Existing bin: reward keeping bins count low.
        score -= 1.0 + 0.02 * pressure.min(10.0);
    }

    // Tie-breaker: prefer bins whose residual is close to mean (balanced packing),
    // lightly favoring below-mean residuals to consolidate.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.8 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill = 1.0 - pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling: reward high fill with progress-dependent strength
    let fill2 = fill * fill;
    let fill3 = fill2 * fill;
    score -= (1.0 + 2.0 * progress) * (fill2 + 0.5 * fill3) * cap * 0.5;

    // Penalize small-but-not-tiny residuals (dead space), smoothly via quadratic bump
    let dead = (pr / cap - 0.15).powi(2);
    score += 30.0 * (-dead * 40.0).exp() * (1.0 - progress);

    // Lookahead: reward residual that can host next item, scaled by progress
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= (1.0 + progress) * (next_item_size as f64 / cap) * 20.0;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so opening is chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress - 5.0 * (mean_residual / cap);
    }

    // Late-stream consolidation: prefer tighter bins more strongly
    score -= progress * (mean_residual - pr) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual (mod-10 buckets; residual 0 is perfect fit)
    let r = post_residual;
    let class = (r % 10) as f64;
    if r == 0 {
        score -= 1000.0; // perfect fit, always prefer
    } else {
        // Penalize residuals that are awkward: small but nonzero dead space
        if r < 10 {
            score += (10 - r) as f64 * 2.0; // tiny dead space is wasted capacity
        } else {
            // Reward residuals that fall on "harmonic" sizes: multiples of 10 or 20
            if r % 20 == 0 {
                score -= 12.0;
            } else if r % 10 == 0 {
                score -= 6.0;
            } else {
                score += class * 0.5; // odd-class residuals less reusable
            }
        }
    }

    // Reward tight fits (small post_residual) proportionally
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 15.0;

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 {
                score -= 25.0;
            } else if slack < 10 {
                score += 8.0; // would create tiny dead space for next item
            } else {
                score -= (slack as f64).min(30.0) * 0.3;
            }
        } else {
            // next item won't fit here; mild penalty scaled by overshoot
            let over = (next_item_size - post_residual) as f64;
            score += (over % 20.0) * 0.4 + 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer filling existing bins when many are open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (open_bins_count as f64).sqrt() * 2.0 * (0.5 + progress);

    // New-bin candidate penalty: only open a new bin when current bin fit is bad
    if bin_residual == bin_capacity {
        score += 55.0 - (post_residual as f64) * 0.2;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 20.0; // big next item benefits from fresh bin
        }
    }

    // Deviation from mean residual: bins far below mean are close to full; prefer them
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    // A residual gap is "unusable" if it is smaller than the smallest plausible item (1..100 unknown,
    // but tiny gaps < ~15 are rarely fillable). Non-linear superlinear penalty.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 15.0 {
        score += (15.0 - gap) * (15.0 - gap) * 0.8;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit bonus: gap that could still hold a small item is fine
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= next_item_size as f64 * 0.3;
    } else if next_item_size > 0 {
        // next item cannot fit here after placement: penalize
        score += 10.0;
    }

    // Open bins pressure: discourage spreading across too many bins
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins with residual close to item size (best-fit coupling)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.1;

    // New-bin candidate: penalize mildly so it is chosen only when fits are poor,
    // but reduce penalty as stream progresses (late items may warrant new bins)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize dead space too small for next item (unusable gap).
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // Prefer bins with below-mean residual (tighter bins get used first).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly reward placing here to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize wasting a fresh empty bin on small items unless nothing fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight penalty for many open bins (encourage consolidation).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = if fitting_bins_count == 0 { 0.0 } else {
            (fitting_bins_count as f64).ln().max(1.0) * 12.0
        };
        // Penalize opening new bins early; relax late or when few bins fit.
        let horizon_penalty = 25.0 * (1.0 - progress).powi(2);
        return 60.0 + desperation + horizon_penalty
            - (next_item_size as f64 * 0.15);
    }

    // Tightness reward: favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 18.0; // near-perfect: dead space is minimal
    }

    // Penalize leaving awkward small residuals that few future items can use.
    if post_residual > 0 && post_residual < 20 {
        score += 12.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 22.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let chain_fit = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * chain_fit;
        } else {
            // Next item won't fit here; slight penalty for wasting capacity.
            score += 4.0;
        }
    } else {
        // Last item: maximize final packing density.
        score -= 15.0 * fill_ratio;
    }

    // Global state coupling: prefer bins below mean residual (balance load),
    // which preserves larger residuals elsewhere for larger future items.
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.08 * residual_gap;

    // Mild preference to fill already-open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    // Slight penalty per open bin to discourage bin sprawl.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let pr = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Cubic smoothness preference: strongly avoid large-but-not-usable residuals.
    score += 40.0 * pr * pr * pr * (1.0 - progress);

    // Tight fits rewarded more as the stream progresses.
    let tight = 1.0 - pr;
    score -= 25.0 * tight * tight * (0.5 + progress);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward residuals that can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 15.0 * (nxt / cap) * (1.0 + progress);
        } else {
            score += 10.0 * (1.0 - post as f64 / nxt) * (1.0 - progress);
        }
    }

    // Prefer filling bins when many are open; penalize spreading.
    score += 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (post_residual as f64 / cap);

    // New-bin candidate: keep it moderately attractive only for big items / late stream.
    if bin_residual == bin_capacity {
        score = cap - item_size as f64 + 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: classify post_residual into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Integer-division thresholds on post_residual: dead-space classes.
    // Class 0: post_residual in [0,10] -> near-perfect fit, heavily reward.
    if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    } else if post_residual <= 30 {
        score -= 8.0;
    } else if post_residual <= 50 {
        // mid-range: neutral-ish, slight penalty to spread fills
        score += 5.0;
    } else {
        // large leftover: penalize, bin stays flexible anyway
        score += 10.0;
    }

    // Modulo arithmetic on post_residual: residues that pair well with
    // common small items (10..20) get a bonus.
    let mod20 = post_residual % 20;
    if mod20 == 0 && post_residual > 0 {
        score -= 6.0; // divisible into 20-chunks
    } else if mod20 <= 5 {
        score -= 2.0;
    } else if mod20 >= 15 {
        score += 3.0;
    }

    // Lookahead coupling: reward leaving exactly next_item_size space.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let gap = pr - nx;
            if gap <= 5.0 {
                score -= 25.0; // perfect chain fit
            } else if gap <= 15.0 {
                score -= 10.0;
            } else {
                score -= gap * 0.05; // mild preference for tighter future fit
            }
        } else {
            // next item won't fit here; penalize proportionally to wasted lookahead
            score += (nx - pr) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // among many fitting bins, prefer the tightest (already via post_residual)
        score -= 2.0;
    }

    // New-bin candidate handling: only open a new bin when open bins are crowded.
    if bin_residual == bin_capacity {
        // Empty bin baseline: score = capacity, adjusted by stream pressure.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap
            + 15.0 * (1.0 - progress)          // early stream: new bins cheap
            - 5.0 * (open_bins_count as f64).ln().max(0.0)
            + (mean_residual - pr).abs() * 0.1;
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 12.0; // no open bin fits next item well -> new bin attractive
        }
        if fitting_bins_count == 1 {
            score += 50.0; // don't abandon the lone fitting bin
        }
    }

    // Progress-aware tightening: late in stream, squeeze harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item can use are poison.
    // Items can be as small as 1, but typical items are >= 10; treat gaps below a
    // usable threshold as pure waste and quadruple-penalize them.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else {
        // Prefer small-but-usable gaps, mildly.
        score += (post_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Reward bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (penalize the empty-bin candidate) and encourage consolidation.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    if bin_residual == bin_capacity {
        score += 25.0 + pressure * 30.0;
    } else {
        score -= pressure * 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward;
    // if next item cannot fit, penalize leaving this residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // residual too small for next item: dead space likelihood
            score += (post_residual as f64) * 0.5;
        } else {
            score -= (post_residual - next_item_size) as f64 * -0.3; // mild reward for good chaining
        }
    }

    // Mean-residual coupling: bins far below mean residual are underused; prefer
    // filling bins whose residual is near the mean to balance the pool.
    score += (mean_residual - post_residual as f64).abs() * 0.15;

    // Slight early-stream preference for packing into existing bins to build dense bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= (1.0 - progress) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fills the post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits here too: chain reward proportional to leftover
            let chain_left = post_residual - next_item_size;
            score -= 150.0 - (chain_left as f64) * 0.5;
        } else {
            // next item cannot use this bin's residual: penalize wasted space
            let waste = next_item_size - post_residual;
            score += (waste as f64) * 0.8;
        }
    }

    // Compare post_residual against mean residual: avoid making bin far tighter than average
    score += (mean_residual - post_residual as f64).abs() * 0.3;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible
    if bin_residual == bin_capacity {
        score += 120.0;
        // opening a new bin is fine if item is large and no tight fit exists
        if item_size >= bin_capacity * 3 / 4 && fitting_bins_count > 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 300.0; // fresh bin perfectly set up for next item
        }
    }

    // Small dead-space penalty: residuals of 1..9 are hard to use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Slight preference to fill bins with larger residual first
    score += (bin_residual as f64) * 0.05;

    // Progression: later in stream, be more conservative about opening bins
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += progress * 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Progress through stream: later stages prefer tighter packing (fewer open bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base preference: best-fit (small post_residual), with progressive sharpening.
    let tightness = 1.0 + 2.0 * progress;
    score *= tightness;

    // Penalize dead space that is too small to ever be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // post_residual can't hold next item: mild penalty proportional to wasted opportunity.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    // New bin candidate handling: only attractive when current fit is bad
    // (large dead space) or few fitting alternatives exist.
    if is_new_bin {
        // Baseline cost of opening a new bin, modulated by stream progress
        // and how many bins are already open.
        let open_cost = 30.0 + 40.0 * progress + open_bins_count as f64 * 2.0;
        score = open_cost + item_size as f64 * 0.5;

        // If existing fit is terrible (lots of dead space), opening new bin looks better.
        let dead = (bin_capacity - item_size) as f64;
        if dead > 50.0 {
            score -= (dead - 50.0) * 1.2;
        }
        // If many bins fit the item, discourage opening a new one.
        if fitting_bins_count > 2 {
            score += 50.0;
        }
        // Mean residual high => open bins have room; discourage new bin.
        score += mean_residual * 0.4;
    }

    // Prefer bins whose residual deviates favorably from the mean (above-mean
    // residual bins are "loose"; placing there consolidates space).
    if !is_new_bin {
        let dev = bin_residual as f64 - mean_residual;
        score -= dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: waste after placement, mildly compressed by progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Non-linear coupling: tight fits (small post_residual) rewarded increasingly
    let tight = (1.0 - norm_pr).powi(3);
    score -= 30.0 * tight * (0.5 + 0.5 * progress);

    // Penalize residuals that cannot fit the next item
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        let waste_frac = (next_item_size as f64 - pr) / cap;
        score += 25.0 * waste_frac * (1.0 + progress);
    }
    // Reward residuals that can still accommodate the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * (1.0 - norm_pr);
    }

    // Congestion: many open bins with high mean residual -> prefer consolidating
    let congestion = (open_bins_count as f64).ln1p() * (mean_residual / cap);
    score += 6.0 * congestion * (1.0 - progress);

    // New-bin candidate: penalize opening a bin when existing bins fit,
    // unless current bins are heavily fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap) * (open_bins_count as f64).ln1p();
        score += 15.0 - 18.0 * fragmentation;
    }

    // Smooth polynomial interaction between progress and residual
    score += 5.0 * progress * norm_pr * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits, with a non-linear quadratic penalty on waste.
    let waste = post_residual as f64;
    score += 0.35 * (waste * waste) / cap;

    // Harmonic class of the item: bucket by capacity fractions (eighths).
    let item_class = (item_size * 8 + bin_capacity - 1) / bin_capacity; // 1..8
    let residual_class = (post_residual * 8 + bin_capacity - 1) / bin_capacity;

    // Reward leaving residuals that match common "harmonic" slots: 50, 25, 20, 10.
    let harmonic_slots: [u32; 7] = [0, 10, 20, 25, 30, 40, 50];
    let mut harmonic_bonus = 0.0;
    for slot in harmonic_slots.iter() {
        if post_residual == *slot {
            harmonic_bonus += 14.0;
        } else if post_residual.abs_diff(*slot) <= 2 {
            harmonic_bonus += 6.0;
        }
    }
    score -= harmonic_bonus;

    // Modulo logic on post_residual: residuals divisible by 10 pair well with
    // typical item sizes; odd tiny residuals (< 10) are dead space.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // unusable sliver
    }

    // Integer-division threshold: post_residual / 10 as coarse grade.
    let grade = post_residual / 10;
    score -= grade as f64 * 0.8;

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and we expect future synergy.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins when decent fits exist.
        if fitting_bins_count > 0 {
            let best_possible = (bin_capacity - item_size) as f64;
            let openness = (post_residual as f64 / cap) - (best_possible / cap);
            score += 40.0 * openness.max(0.0);
            score += 10.0 * (fitting_bins_count as f64).ln().max(0.0);
        }
        // Early stream: slightly favor keeping options open.
        score -= 8.0 * (1.0 - progress) * (1.0 - progress);
        // If lookahead item is small, an empty bin keeps flexibility.
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 12.0;
        }
        // Never open a new bin for tiny items when any bin fits.
        if item_size <= 20 && fitting_bins_count > 0 {
            score += 60.0;
        }
        score += 5.0; // mild default conservatism
    }

    // Lookahead coupling: if the next item fits the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 18.0;
            score -= 0.15 * slack as f64;
            if post_residual % next_item_size.max(1) == 0 {
                score -= 6.0; // perfect harmonic division
            }
        } else {
            // Next item won't fit here: slight penalty proportional to overflow.
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: any bin that fits is fine, prefer emptiest.
        score -= 3.0;
    }

    // Crowd control: with many open bins, prefer filling existing ones tightly.
    score += 0.4 * (open_bins_count as f64).sqrt() * (post_residual as f64 / cap);

    // Mean-residual coupling: if this bin is far from the mean, nudge toward mean.
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    // Small jitter-free tiebreak on residual class parity.
    if residual_class % 2 == 0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for typical items are penalized heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += (open_bins_count as f64) * 0.8;

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // New bin candidate: penalize slightly so we prefer existing bins unless
    // they are all poor fits, but reduce penalty late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 - 10.0 * progress;
    }

    // Mean residual coupling: prefer bins whose residual is below average
    // (concentrating waste in fewer bins).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Strongly reward exact match, decay with distance.
        let match_reward = if diff == 0.0 {
            60.0
        } else if diff <= 10.0 {
            40.0 - 3.0 * diff
        } else {
            -0.5 * diff
        };
        score -= match_reward;

        // Penalize post_residual that is too small to ever fit typical items.
        if post_residual < 10 && post_residual > 0 {
            score += 15.0;
        }
    }

    // Relative fit quality against mean residual of open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let rel = post_residual as f64 - mean_residual;
    score += 0.3 * rel * (1.0 - progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly so we prefer reusing open bins,
    // unless the fit is truly bad (handled by match rewards above).
    if bin_residual == bin_capacity {
        score += 5.0 + 0.1 * open_bins_count as f64;
    }

    // Prefer tighter overall packing as stream progresses.
    score += 0.05 * (post_residual as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squaring post_residual penalizes wasted space superlinearly.
    let tightness = (post_residual as f64) / bin_capacity as f64;
    score += 18.0 * tightness * tightness;

    // Penalize very small post-residuals that no future item can use
    // (items are >= 1; dead space below the typical small-item size is waste).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slightly penalize hoarding capacity
            // that could have served the next item in another bin.
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Global state: when many bins are open with large mean residual,
    // prefer consolidating into existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let openness = (open_bins_count as f64).ln() / (1.0 + (open_bins_count as f64).ln());
    if bin_residual != bin_capacity {
        score -= 6.0 * openness * (mean_residual / bin_capacity as f64);
    } else {
        // New-bin candidate: base cost plus dynamic pressure.
        // Opening is penalized more when many bins are already open and
        // mean residual is high (poor consolidation so far).
        let mut open_cost = 22.0
            + 10.0 * openness
            + 8.0 * (mean_residual / bin_capacity as f64)
            + 5.0 * progress;
        // If no open bin fits (this call is the only candidate), opening is cheap.
        if fitting_bins_count == 0 {
            open_cost -= 25.0;
        }
        // If next item is large and this new bin would fit it too, opening now
        // is more attractive (pair two large items).
        if next_item_size > 0 && next_item_size <= post_residual {
            open_cost -= 15.0;
        }
        score = open_cost + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_frac = item_size as f64 / cap;

    // Base: prefer small post residual (tight fit)
    let mut score = pr;

    // Smooth polynomial coupling of tightness with stream progress:
    // later in the stream, tight fits matter more (dead space is costlier).
    let tightness = 1.0 - (pr / cap);
    let tightness_sq = tightness * tightness;
    score -= 12.0 * tightness_sq * (0.4 + 0.6 * progress);

    // Reward near-perfect fits extra (quartic term, smooth)
    score -= 8.0 * tightness_sq * tightness_sq;

    // Penalize residual that is small but awkward: post_residual just above
    // typical item sizes is dead space. Smooth logistic-ish penalty.
    let dead = (pr / cap - 0.05).tanh();
    score += 4.0 * dead * (1.0 - tightness);

    // Last chance bin: strong reward to use it instead of opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // spread load when many bins fit: mildly prefer bins with larger residual
        score -= 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Lookahead: if next item fits in post_residual, big reward (chaining)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let chain = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 10.0 * chain * (0.5 + 0.5 * progress);
    }

    // Early stream: mild preference to fill existing bins rather than spread
    score += 3.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // New-bin candidate: penalize opening a new bin unless residuals are large
    if bin_residual == bin_capacity {
        let avg_tight = 1.0 - mean_residual / cap;
        // if open bins are mostly full-ish, opening a new bin is fine; else penalize
        score += 10.0 * (1.0 - avg_tight) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residual mod capacity fraction classes
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity wasted
    let class = post_residual % 10; // modulo class on residual

    // Penalize residuals that are unusable dead space (too small for typical items)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead space is pure waste
    }

    // Reward exact harmonic fits (residual divisible by small divisors)
    if post_residual % 5 == 0 {
        score -= 4.0;
    }
    if post_residual % 25 == 0 {
        score -= 6.0;
    }

    // Coupling with lookahead: does post_residual fit next item exactly / well?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // perfect next fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap); // reward tight lookahead fit
            // harmonic class of slack
            if slack % 10 == 0 { score -= 3.0; }
        } else {
            // next item won't fit here; penalize based on how much is stranded
            score += 8.0 + 6.0 * frac;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        // opening a new bin is neutral baseline; discourage mildly if others fit
        if fitting_bins_count > 0 {
            score += 12.0 + 5.0 * frac;
        }
        // encourage new bin late in stream? keep neutral otherwise
    }

    // Tight-fit reward: item fills bin nearly completely
    let fill = item_size as f64 / bin_residual as f64;
    if fill > 0.9 {
        score -= 8.0;
    } else if fill > 0.75 {
        score -= 4.0;
    }

    // Progress modulation: as stream advances, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - frac);

    // Mean residual context: if open bins are already loose, penalize loose fits more
    if post_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    // Integer-division threshold on post_residual: half-capacity class
    if post_residual > bin_capacity / 2 {
        score += 2.0; // leaving more than half empty is wasteful
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Dead-space penalty: small leftover gaps are hard to reuse.
        // Items range 1..100, so gaps below ~10 are nearly unusable.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 6.0;
        } else if post_residual < 25 {
            score += (25 - post_residual) as f64 * 1.5;
        }
        // Lookahead: if the next item fits exactly into the leftover, reward it.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual {
            // leftover can't host the next item: mild penalty scaled by gap smallness
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // encourage consolidation when few are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.4 * (1.0 - progress);
    score -= open_bins_count as f64 * 0.1 * progress;

    // Prefer bins whose residual is tighter than average (better packing).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // New-bin candidate: baseline competitive score so it wins only when
    // existing fits are genuinely bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If nothing else fits, new bin is the only option anyway.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- Aggressive 2-step lookahead matching ---
    // Perfect match: the next item exactly fills the post-residual -> huge reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // Next item fits into the post-residual -> reward proportional to tightness.
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack_after_next / bin_capacity as f64);
    }
    // Next item does NOT fit after this placement -> penalize dead space creation,
    // scaled by how much residual would be wasted.
    else if next_item_size > post_residual && next_item_size > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 15.0 * waste;
    }

    // --- Tight fit reward relative to mean residual ---
    // Prefer bins whose post-residual is far below the mean residual (tight packing).
    let tightness = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score -= 10.0 * tightness;

    // Penalize bins that end with a small unusable sliver (1..10 units)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // --- Last-chance bin bonus ---
    // If this is the only bin that can fit the item, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive early (few open bins); cheap late.
        let open_penalty = 30.0 / (1.0 + open_bins_count as f64);
        score += open_penalty;
        // If no open bin fits, the new bin is the only option; make it attractive.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, avoid spreading across many bins.
        score += 10.0 * progress;
    }

    // Mild preference for bins that are already fairly full (small residual).
    score += 0.05 * (bin_residual as f64 / bin_capacity as f64) * -1.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (bin_capacity as f64) * 0.35;

    // Penalize dead space: residuals too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Prefer bins below mean residual (spread usage) when many bins are open.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.25;

    // Time horizon: early in stream, be conservative (favor new bins for big items);
    // late in stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if item_size > 50 && progress < 0.3 {
        score += 10.0;
    }
    if progress > 0.7 {
        score -= 5.0 * progress;
    }

    // Penalize opening new bins when several bins already fit the item.
    if bin_residual == bin_capacity {
        let newbin_penalty = 15.0 + 8.0 * (fitting_bins_count as f64) + 20.0 * (1.0 - progress);
        score += newbin_penalty;
    } else {
        // Slight bonus for using existing bins.
        score -= 3.0;
    }

    // Fragmentation guard: avoid leaving residual that pairs poorly with common sizes.
    if post_residual >= 10 && post_residual <= 20 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling: quadratic waste term growing with stream progress
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * cap * (0.5 + 1.5 * progress);

    // Reward tight fits (small post_residual) with a smooth exponential bonus
    score -= (1.0 - norm_pr).powi(4) * 8.0;

    // Lookahead: if next item fits exactly into post_residual, strongly reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack_gap = (pr - nx) / cap;
            score -= 10.0 * (1.0 - slack_gap).powi(3);
        } else {
            score += 2.0 * ((nx - pr) / cap);
        }
    }

    // Last chance bin: penalize opening a new bin when only this bin fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, less so late in the stream or when mean residual is low
    if bin_residual == bin_capacity {
        let mean_factor = (mean_residual / cap).clamp(0.0, 1.0);
        score += 12.0 - 6.0 * progress - 4.0 * (1.0 - mean_factor);
    } else {
        // Prefer bins with residual close to the mean (balance load) via smooth term
        let dev = (pr - mean_residual) / cap;
        score += dev * dev * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual into capacity fractions
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;

    // Dead space: unusable slivers (below typical min item size)
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 500.0;
    }

    // Penalize post_residual in "awkward" harmonic classes:
    // small non-zero residuals that few items can fill
    if post_residual > 0 && post_residual <= quarter {
        // awkward small leftover; worse the smaller it is relative to quarter
        score += (quarter as f64 - pr) * 2.0;
    } else if post_residual <= half {
        // medium leftover: mildly bad, reward slightly if next item can use it
        score += 10.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 25.0;
        }
    } else {
        // large leftover: good bin state
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual class
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0; // chain perfect fit
        } else if next_item_size <= post_residual {
            // reward proportional fit quality
            let fill = next_item_size as f64 / pr;
            score -= 40.0 * fill;
            // harmonic alignment: next item leaves another quarter-class residual
            let nr = post_residual - next_item_size;
            if nr == 0 || nr % quarter == 0 || nr % 10 == 0 {
                score -= 20.0;
            }
        } else {
            // next item won't fit here; penalize slightly less if residual is large
            score += (cap_f - pr) * 0.1;
        }
    }

    // Tightness reward: how well current item fills the bin
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 60.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: neutral baseline, opened only when fits are bad
    if bin_residual == bin_capacity {
        score = cap_f * 0.5 + 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
        // prefer new bin early when many bins already open and mean residual is low
        if open_bins_count > 3 && mean_residual < cap_f * 0.2 {
            score -= 30.0;
        }
    }

    // Progress modulation: later in stream, be more conservative with new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 40.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strong reward for leaving nothing behind.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead space penalty: residual smaller than the smallest plausible
        // future item (or the lookahead item) is nearly unusable.
        let min_useful = next_item_size.max(1);
        if (post_residual as u64) < (min_useful as u64) {
            score += 60.0 + 2.0 * (min_useful as f64 - post_residual as f64);
        }
        // Excessively large leftover also wastes capacity mildly.
        if post_residual > bin_capacity / 2 {
            score += 0.15 * (post_residual as f64 - bin_capacity as f64 / 2.0);
        }
    }

    // Lookahead coupling: reward bins whose post_residual exactly matches
    // the next item (a future perfect fit), penalize near-miss gaps.
    if next_item_size > 0 {
        let pr = post_residual as i64;
        let ni = next_item_size as i64;
        if pr == ni {
            score -= 300.0;
        } else if pr > ni && pr - ni <= 10 {
            score += 25.0; // leaves a tiny unusable sliver for the next item
        }
    }

    // Tight fit reward relative to current residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 80.0 * fill_ratio;

    // Open-bin pressure: with many open bins, avoid spreading; prefer
    // filling existing bins and only open new bins when fit is bad.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no good fit exists.
        if fitting_bins_count > 0 {
            score += 40.0 + 5.0 * pressure;
        } else {
            score -= 50.0;
        }
    } else {
        // Existing bin: slight reward to keep bin count low.
        score -= 0.5 * pressure;
        // Last-chance bin: strongly prefer using it over opening a new bin.
        if fitting_bins_count == 1 {
            score -= 120.0;
        }
    }

    // Mean-residual deviation: prefer bins whose residual is close to the
    // mean (balanced packing), penalize outliers slightly.
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    // Mild stream-progression urgency: later in the stream, waste less.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item exactly fits post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // next item fits too; reward tightness of the chain
            score -= 60.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize small dead space more than large
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 40.0;
            }
        }
    }

    // Relative tightness vs mean residual across open bins.
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = resid_f / mean_residual;
        score -= 30.0 * (rel - 1.0); // prefer bins tighter than average
    }

    // Prefer fuller bins (smaller residual before placement).
    score += 0.5 * resid_f;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let base_penalty = 250.0;
        // If next item is large and current item is small, new bin may be worthwhile.
        let lookahead_relief = if next_item_size > 0 {
            (next_item_size as f64 - item_size as f64).max(0.0) * 1.5
        } else {
            0.0
        };
        score += base_penalty - lookahead_relief;
        // Late in stream, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward low post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Dead space penalty: residuals that nothing (min size 1) could later
    // use well — penalize awkward mid-range leftovers.
    let dead = (post_residual as f64 / bin_capacity as f64).powi(3);
    score += dead * 30.0;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item can use this bin's post_residual, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to waste.
            score += 5.0;
        }
    }

    // Global state: many open bins with large mean residual -> prefer
    // consolidating into existing bins over opening new ones.
    let crowding = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when existing bins are roomy or few.
        score += 15.0 + crowding * 2.0;
        // But allow opening when all alternatives are poor fits.
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    } else {
        // Existing bin: reward more when bins are crowded.
        score -= crowding.min(10.0) * 1.5;
    }

    // Time horizon: early in stream, be slightly pickier (avoid fragmenting);
    // late in stream, accept placements more readily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * (1.0 - progress) - 0.10 * progress;

    // Avoid pathological negatives dominating: keep ordering sane.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Normalize post-residual
    let p = post / cap;

    // Non-linear polynomial coupling with stream progress
    let poly = p * p * (1.0 + 3.0 * progress) + p * (1.0 - progress);
    score += 40.0 * poly;

    // Reward tight fits (small post_residual) with smooth decay
    score -= 30.0 * (-p * 8.0).exp();

    // Lookahead coupling: reward residual that can host next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 15.0 * (-slack * 6.0).exp() * (1.0 - 0.5 * progress);
        } else {
            score += 8.0 * (1.0 - (post / nxt).min(1.0));
        }
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Penalize bins far below mean residual (fragmentation) smoothly
    score += 0.3 * (mean_residual - post).max(0.0);

    // Mild pressure to consolidate as many bins accumulate
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * p;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals that divide the capacity
    // cleanly (or are tiny) are "usable"; mid-range chunks are dead space.
    let pr = post_residual;
    let class_penalty: f64 = if pr == 0 {
        -30.0 // perfect fit
    } else if pr <= 10 {
        -12.0 // near-perfect, effectively sealed
    } else {
        // integer-division thresholds on post_residual
        let k = pr / 10; // harmonic decile class
        match k {
            1 => 2.0,   // 11..20: fits small items
            2 => 6.0,   // 21..30
            3 => 10.0,  // 31..40
            4 => 14.0,  // 41..50: worst dead zone
            5 => 12.0,
            6 => 9.0,
            7 => 7.0,
            8 => 5.0,
            9 => 3.0,
            _ => 0.0,   // 100: fresh bin baseline
        }
    };
    score += class_penalty;

    // Lookahead: reward if next item fits exactly into post_residual,
    // penalize if next item is stranded (too big for residual but exists).
    if next_item_size > 0 {
        let n = next_item_size;
        if n == pr {
            score -= 25.0; // perfect chained fit
        } else if n <= pr {
            score -= (pr - n) as f64 * 0.4; // next item fits reasonably
        } else if pr > 0 {
            score += (n - pr).min(40) as f64 * 0.5; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer filling bins whose residual is already below mean (tight bins first).
    let res_frac = bin_residual as f64 / cap;
    score += res_frac * 15.0;

    // Mild pressure to close bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    // New-bin candidate: keep it attractive unless an open bin gives a tight fit.
    if bin_residual == bin_capacity {
        score -= 8.0;
        score += open_bins_count as f64 * 0.5; // discourage hoarding many open bins
        if item_size as f64 / cap > 0.6 {
            score -= 6.0; // big items start fresh bins happily
        }
    }

    // Coupling: penalize leaving residual far from any plausible item size
    // (harmonic mismatch between post_residual and typical item granularity).
    let mismatch = ((pr as f64 / 10.0).round() * 10.0 - pr as f64).abs();
    score += mismatch * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 25.0;
    }

    // Reward tight fits: the smaller the post_residual, the better the fill.
    let tightness = 1.0 - (post_residual as f64 / cap);
    score -= tightness * 30.0;

    // Penalize residuals that cannot fit the lookahead item if they could
    // otherwise have been useful (dead space relative to next item).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // If this is the ONLY bin that can fit the item, strongly favor it
    // (last-chance placement avoids opening a new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; prefer filling
    // existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins pressure.
        score += 35.0 + pressure * 4.0;
        // But if no existing bin fits well (this call is for the empty bin,
        // fitting_bins_count counts fitting open bins), soften slightly.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Existing bin: mild reward scaled by pressure to keep bins consolidated.
        score -= pressure * 0.5;
    }

    // Slight preference for bins whose residual is near the mean (balance).
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: reward near-zero post residual strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small residuals are hard to use later; penalize dead space quadratically.
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
    }

    // 2-step lookahead: reward bins whose post_residual closely matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + gap);
        // Exact match for the next item is ideal.
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // Penalize leaving a residual that cannot fit the next item if it's tiny.
        if post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.5 {
            score += 15.0;
        }
    }

    // Compare against mean residual across open bins: prefer bins that tighten the mean.
    score += 2.0 * ((post_residual as f64) - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: prefer reusing open bins early; allow new bin when
    // existing fits are poor (handled by gap/penalty terms above).
    if bin_residual == bin_capacity {
        score += 40.0 + 5.0 * open_bins_count as f64;
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 50.0 * progress;
    }

    // Prefer filling bins that are already mostly full.
    score -= (item_size as f64) / (bin_residual as f64).max(1.0) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item leaves little waste.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can never be used by typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 30.0 * dead * dead * dead;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let waste_after_pair = post_residual - next_item_size;
            score -= 15.0 * (1.0 - waste_after_pair as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement; mild penalty.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Global state coupling: prefer filling bins with large residuals when many bins are open.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.05 * residual_gap * (open_bins_count as f64).sqrt();

    // Time horizon: early in the stream, be conservative about fragmenting bins;
    // late in the stream, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * fit_ratio;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin offers a decent fit (i.e., item barely fits anywhere).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9;
        // Make it competitive when the item is large relative to capacity
        // (hard to place later) or when open bins are all nearly full.
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let item_bulk = item_size as f64 / bin_capacity as f64;
        score -= 30.0 * item_bulk;
        score -= 20.0 * avg_fill * avg_fill;
        // If the next item is large, keeping a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 10.0;
        }
        // Late in the stream, avoid opening new bins (waste is locked in).
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, smoothed non-linearly
    let mut score = pr;

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, small residuals matter more (tight packing)
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * (0.5 * progress + 0.25);
    score += 40.0 * poly;

    // Perfect fit reward (smooth via product term)
    let perfect = if post_residual == 0 { 1.0 } else { 0.0 };
    score -= 25.0 * perfect * (1.0 + progress);

    // Penalize residual that cannot fit the lookahead item (dead space)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (nx - pr).max(0.0) / cap;
        score += 30.0 * gap * gap * (1.0 + 2.0 * progress);
        // Reward residual that exactly accommodates the next item
        let nx_fit = if pr >= nx && (pr - nx) <= 10.0 { 1.0 } else { 0.0 };
        score -= 15.0 * nx_fit * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Prefer bins with below-mean residual (concentrate space usage)
    score -= (mean_residual - pr) * 0.15;

    // Mild penalty for opening a new bin when many bins are open
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class: post_residual bucketed by integer division thresholds
    let class = post_residual / 10;
    score += match class {
        0 => -20.0,          // post_residual < 10: near-perfect
        1 => -5.0,           // 10..19
        2 | 3 => 5.0,        // 20..39: moderate dead space
        4 | 5 => 15.0,       // 40..59
        _ => 30.0,           // >=60: wasteful
    } as f64;

    // Lookahead: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain bonus, stronger when next item fills well
            let next_waste = post_residual - next_item_size;
            score -= 30.0 - (next_waste as f64) * 0.5;
        } else {
            // post_residual too small for next item: penalize more if it's a dead zone
            if post_residual < 10 {
                score += 40.0; // unusable sliver
            } else {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 60.0;
        // but if next item is large and this item is small, fresh bin is fine
        if next_item_size > 60 {
            score -= 30.0;
        }
    }

    // Prefer bins tighter than average (waste concentration)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Late in stream: close bins out, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead space is worse if it cannot host the next item.
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size && post_residual > 0 {
            score += 15.0;
        } else if post_residual as u32 >= next_item_size {
            score -= 10.0;
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spreading out.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins
    // would leave large dead space.
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
        if post_residual as i64 - item_size as i64 >= 0 {
            // empty bin leaves item_size free; neutral-ish, slight penalty
            score += item_size as f64 * 0.2;
        }
        // If no open bin fits well (this is the only "fitting" call context),
        // allow new bin when mean residual is small.
        if mean_residual < item_size as f64 {
            score -= 40.0;
        }
    }

    // Mild stream-progression adaptation: later in stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 60.0 + (post_residual - next_item_size) as f64 * -0.5;
            // exact match: next item perfectly consumes leftover
            if next_item_size == post_residual {
                score -= 200.0;
            }
        } else {
            // leftover too small for next item: penalize dead space, more if close to next size
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.8;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening a new bin unless no decent fit exists
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64) * 100.0;
        // new bin is attractive only for large items or when existing fits are poor
        if next_item_size > 0 && next_item_size <= post_residual && post_residual < bin_capacity {
            score += 50.0; // an existing bin fits next item too; prefer it
        }
        score += (100.0 - tightness) * 0.3;
        if fitting_bins_count > 1 {
            score += 120.0;
        }
    }

    // Early in stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize large unusable post-residual (dead space that few items can use).
    if post_residual > 0 {
        let usable = (post_residual as f64 / 100.0).sqrt();
        score += 10.0 * (1.0 - usable);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the new-bin candidate would be better).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily; if post_residual is too small for the next item, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let lookahead_tight = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * lookahead_tight;
        } else {
            let waste = post_residual as f64;
            score += 0.15 * waste;
        }
    }

    // Global state: many open bins with high mean residual -> prefer packing
    // into existing bins to consolidate; few open bins -> opening new bins is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = open_bins_count as f64 / (1.0 + mean_residual / 100.0);
    score += 0.02 * consolidation * (0.5 + progress);

    // New-bin candidate calibration: an empty bin gets a base cost that grows
    // with the number of open bins, so it's chosen only when fits are bad.
    if bin_residual == bin_capacity {
        score += 22.0 + 1.5 * open_bins_count as f64 * (0.3 + 0.7 * progress);
        // But if no existing bin fits well, allow opening: handled by others' scores.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Mild preference for bins with residual close to the item (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr + 12.0 * norm_pr * norm_pr - 4.0 * norm_pr;

    // Polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual); later, keep flexibility
    let coupling = norm_pr * (1.0 - progress) * (1.0 - progress)
                 - norm_pr * norm_pr * progress * (1.0 - progress);
    score += 40.0 * coupling;

    // Penalize residuals that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 8.0 + (nx - pr) * 0.5;
        } else {
            score -= 4.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (norm_pr - mean_residual / cap).abs();

    // New-bin candidate: penalize slightly so it is used only when fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes modulo capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: perfect fit -> strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Harmonic buckets: residual in [1..cap/4), [cap/4..cap/2), etc.
    let quarter = cap / 4.0;
    let half = cap / 2.0;
    if pr > half {
        score -= 8.0; // large residual remains, bin stays useful
    } else if pr > quarter {
        score += 3.0; // medium dead space
    } else {
        score += 10.0; // small residual is likely dead space
    }

    // Integer-division thresholds: residual in classes of 10
    let class = post_residual / 10;
    score += (class as f64) * (-1.5); // larger class (more room) slightly favored

    // Lookahead: does next item fit in post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // next item chains nicely; reward proportionally to snugness
        let snug = (post_residual - next_item_size) as f64;
        score -= 15.0 - snug * 0.3;
    } else if next_item_size > post_residual {
        // next item won't fit here; penalize mildly unless residual was tiny anyway
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening new bins when many open bins could fit
    if fitting_bins_count > 1 {
        score += 1.0;
    }

    // Progress-based tuning: early in stream, prefer tight packing into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0 - 1.0;

    // Mean residual coupling: if this bin's residual is far below mean, it's an outlier hole
    let diff = mean_residual - pr;
    if diff > 20.0 {
        score += 5.0;
    } else if diff < -20.0 {
        score -= 3.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 30.0 - (item_size as f64) * 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small gaps that likely cannot fit future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strong incentive to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from many open bins: prefer tightening existing bins.
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    } else if next_item_size > 0 && (post_residual as u32) > 0 {
        score += 8.0;
    }

    // New-bin candidate: make it unattractive unless it yields a tight future fit.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for minimal post_residual (tight fit).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Reward bins whose post_residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 / (1.0 + gap);
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Penalize leaving residuals too small for the next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += (post_residual as f64) * 0.5;
        }
    } else {
        // Last item: just minimize waste.
        score -= 10.0;
    }

    // Prefer bins with residual close to mean (balanced packing) when fit is loose.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless every open bin would leave large waste.
    if bin_residual == bin_capacity {
        let best_possible_waste = if next_item_size > 0 {
            (bin_capacity as f64 - item_size as f64 - next_item_size as f64).max(0.0)
        } else {
            (bin_capacity as f64 - item_size as f64).max(0.0)
        };
        // Open a new bin only if using an open bin would waste much more than this.
        score = (bin_capacity as f64 - item_size as f64) + 15.0 - best_possible_waste * 0.8;
        if open_bins_count == 0 {
            score -= 1000.0; // must open a bin
        }
    }

    // Slight pressure to fill bins as the stream progresses.
    score -= (step_index as f64 / total_items.max(1) as f64) * (bin_capacity as f64 - bin_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly prefer small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * tightness * (post_residual as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Penalize dead space too small for the smallest possible item.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.25 * next_item_size as f64;
        } else {
            // Wasted potential for the lookahead item.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global state: when many bins are open, prefer consolidating into fuller bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Mean residual coupling: penalize bins whose residual deviates badly from the mean.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early on, be more conservative about poor fits; later, accept tight fits aggressively.
    score *= 1.0 - 0.2 * progress;

    // New-bin candidate handling: opening a new bin is only attractive when this is
    // not a last-chance situation and the item is large (poor fit elsewhere is likely).
    if bin_residual == bin_capacity {
        let mut open_cost = 25.0;
        if fitting_bins_count == 0 {
            open_cost -= 30.0; // no existing bin fits: new bin is necessary
        } else if fitting_bins_count == 1 {
            open_cost += 30.0; // avoid abandoning a last-chance bin
        }
        if item_size >= 60 {
            open_cost -= 8.0; // large items pair well with fresh bins
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            open_cost -= 5.0; // lookahead can share the fresh bin
        }
        score = score.max(0.0) + open_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: large residuals are fine (bins stay flexible).
    // Late stream: penalize residual quadratically to force tight packing.
    let quad = norm_pr * norm_pr;
    score += progress * quad * cap * 0.9;
    score -= (1.0 - progress) * quad * cap * 0.15;

    // Smooth cubic term: small residuals are prized increasingly as stream advances.
    score -= progress * (1.0 - norm_pr) * (1.0 - norm_pr) * fit * 6.0;

    // Reward near-perfect fits (post_residual close to 0) with smooth falloff.
    let tight = 1.0 - norm_pr;
    score -= tight * tight * tight * 4.0;

    // Dead-space avoidance: residual too small to fit typical future items.
    let dead = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        gap * gap
    } else {
        0.0
    };
    score += dead * 8.0;
    // Bonus when this placement sets up the next item exactly.
    if next_item_size > 0 && pr >= next_item_size as f64 {
        let setup = 1.0 - (pr - next_item_size as f64) / cap;
        score -= setup * setup * 3.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Slight preference for bins with more alternatives (keeps options open).
        score += (fitting_bins_count as f64).ln() * 0.5;
    }

    // Prefer bins with residual below mean residual (tighter bins first),
    // smoothly scaled by open-bin pressure.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    let diff = (pr - mean_residual) / cap;
    score += diff * pressure * 1.5;

    // New-bin candidate: penalize mildly so it wins only for genuinely bad fits,
    // with penalty easing as the stream progresses.
    if bin_residual == bin_capacity {
        score += 6.0 - progress * 4.0 + pressure * 0.8;
    }

    // Mild smoothing noise-free coupling with item size (larger items want tighter bins).
    score -= fit * (1.0 - progress) * 1.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction slot it lands in.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Integer-division thresholds on post_residual (harmonic buckets of C/8).
    let bucket = post_residual / (bin_capacity / 8).max(1);
    let in_bucket = post_residual % (bin_capacity / 8).max(1);

    // Penalize residuals that fall in "dead zones" — too small for typical small items
    // (1..10 range) but not zero: unusable slack.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Harmonic reward: residual close to multiples of common item sizes (mod classes)
        let m = post_residual % 10;
        if m == 0 { score -= 8.0; }
        else if m >= 5 { score += m as f64 * 0.8; }
        else { score += m as f64 * 0.4; }
    }

    // Reward low buckets (tight packing), penalize high buckets mildly.
    score += bucket as f64 * 2.0;
    // Within-bucket granularity: finer fit preferred.
    score += in_bucket as f64 * 0.15;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_post = post_residual - next_item_size;
        if next_post == 0 { score -= 45.0; }
        else if next_post < 10 { score += 10.0; }
        else { score -= (next_post as f64).min(20.0) * 0.5; }
    } else if next_item_size > post_residual {
        // Next item won't fit here regardless; slight penalty if we leave large slack.
        score += frac * 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when no open bin fits well
    // or when open bins are very full already.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = mean_residual / bin_capacity as f64;
        // Base cost of a new bin.
        let mut new_bin_score = 55.0;
        // If mean residual across open bins is large, new bin is wasteful.
        new_bin_score += pressure * 40.0;
        // Early in stream, new bins are cheaper (room to plan).
        new_bin_score -= (1.0 - progress) * 15.0;
        // Many open bins: discourage adding more.
        new_bin_score += open_bins_count as f64 * 1.5;
        // If item is large and would leave tiny residual anywhere, new bin attractive.
        if item_size >= bin_capacity * 9 / 10 { new_bin_score -= 20.0; }
        score = new_bin_score + score * 0.05;
    }

    // Mild global pressure: prefer filling bins with low residuals when many bins open.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (min size 1, but practically < ~20) are waste.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 3.0; // unusable gap penalty
    } else if post_residual == 0 {
        score -= 15.0; // perfect fit: bin fully closed, strongly preferred
    }

    // Reward tight fits: item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Lookahead: if the next item can fit into the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If next item would leave another dead gap, penalize mildly.
    if next_item_size > 0 && post_residual > next_item_size {
        let nxt_gap = post_residual - next_item_size;
        if nxt_gap < 20 {
            score += (20.0 - nxt_gap as f64) * 1.5;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Open-bin pressure: discourage scattering across many open bins when
    // plenty of alternatives exist; encourages closing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.5 * (1.0 - progress * 0.5);

    // Compare against mean residual: bins with less residual than average
    // (i.e., fuller) are better targets.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate calibration: an empty bin has large residual; make it
    // attractive only when current bin would leave a bad gap.
    if bin_residual == bin_capacity {
        // neutral baseline; dead-space logic above dominates
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - 1.5 * slack; // perfect chain (slack 0) gets biggest bonus
    } else if next_item_size > 0 {
        // next item cannot chain here: penalize proportionally to wasted potential
        let gap = (next_item_size.saturating_sub(post_residual)) as f64;
        score += 0.8 * gap;
    }

    // Compare post_residual against mean residual: avoid creating outliers
    let pr = post_residual as f64;
    score += 0.5 * (pr - mean_residual).abs();

    // Penalize very small dead space (unusable slivers) more than large residuals
    if pr > 0.0 && pr < 10.0 {
        score += 25.0 * (10.0 - pr);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Early in stream: encourage keeping bins flexible (larger residuals)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 0.3 * pr;

    // New-bin candidate: mild penalty so it only wins when open bins are truly bad
    if bin_residual == bin_capacity {
        score += 30.0 + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less leftover relative to capacity is better.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 60.0 * fill_ratio;

    // Penalize small dead space that can't hold typical items (wasted residual).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // Extra reward for a "perfect pair": next item exactly consumes the residual.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else if post_residual > 0 {
            // Dead space for the next item: penalize proportionally.
            score += 5.0 + 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins exist and fit,
    // but relax the penalty late in the stream or when many bins are already open
    // with fragmented residuals (mean residual low relative to item size).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 20.0;
        if open_bins_count == 0 {
            new_bin_penalty = -50.0; // must open a bin
        } else if fitting_bins_count == 0 {
            new_bin_penalty = -10.0; // no alternative
        } else if mean_residual < item_size as f64 * 1.2 {
            // open bins are fragmented; a fresh bin may be better
            new_bin_penalty = -5.0;
        }
        if progress > 0.8 {
            new_bin_penalty += 10.0 * progress; // late stream: consolidate
        }
        score += new_bin_penalty;
    }

    // Mild preference for bins with residual far below mean (they are "specialized"
    // leftovers); using them keeps flexible large-residual bins free.
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Prefer using bins with lower residual overall (best-fit flavor) scaled by
    // number of competing bins.
    score += 0.05 * bin_residual as f64 / (fitting_bins_count.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let norm_item = item / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (0.5 + progress) + norm_pr * (1.0 - progress) * (1.0 - progress);
    score += 30.0 * poly;

    // Tight fits rewarded more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * (0.3 + 0.7 * progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.6 + 0.4 * progress);
        } else {
            score -= 6.0 * (1.0 - nx / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild penalty for spreading across many bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (mean_residual - pr).abs() / cap;

    // Small bias toward using nearly-full bins late in the stream
    score -= progress * 8.0 * (1.0 - norm_pr) * norm_item;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
