pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible future item are "dead" — penalize them hard.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.10);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 + 3.0 * (dead_threshold - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to the bin (small waste fraction).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * waste_frac * waste_frac;

    // Lookahead coupling: if the next item fits into post_residual, reward;
    // if not, penalize leaving a gap that blocks the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 8.0;
        }
    }

    // Last chance: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: opening a new bin wastes the residual of every open
    // bin. Make the empty-bin candidate attractive only when fits are poor and
    // open-bin count is low; otherwise penalize it.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64 / bin_capacity as f64) > 0.5;
        if poor_fit && (open_bins_count as f64) < 2.0 + 3.0 * (1.0 - progress) {
            score -= 30.0;
        } else {
            score += 35.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Open-bin pressure: discourage scattering across many open bins when the
    // mean residual is already fragmented.
    if open_bins_count > 2 {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 0.5 * open_bins_count as f64 + 0.2 * fragmentation;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward post_residual matching next_item_size exactly
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.9;
        // strong reward for exact chain (post_residual == next_item_size)
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // penalize dead space that cannot fit the next item
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.6 * (post_residual as f64) * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // last item: prefer tightest fit
        score += 0.0;
    }

    // relative-to-mean coupling: prefer bins whose residual deviates usefully
    let pr = post_residual as f64;
    let dev = pr - mean_residual;
    score += 0.15 * dev;

    // last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // penalize opening a new bin when open bins exist and item fits reasonably
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if open_bins_count > 0 {
            score += 30.0;
            // allow new bin only if no open bin leaves a good 2-step chain
            if next_item_size > 0 && post_residual as i64 == next_item_size as i64 {
                score -= 20.0;
            }
        } else {
            score -= 50.0; // must open first bin
        }
    }

    // mild tightness bonus: fraction of bin consumed
    score += 0.1 * (bin_capacity - post_residual) as f64 / bin_capacity as f64 * 10.0
          - 0.1 * (item_size as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), stronger when the bin is nearly full.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * fill_ratio * 8.0;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // tiny unusable sliver -> great placement
    } else if post_residual < item_size.max(1) {
        score -= 3.0;
    }

    // Lookahead: bonus if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for wasting residual
            score += 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Many open bins: encourage closing bins (higher fill) rather than spreading.
    let spread_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0));
    score += spread_pressure * 0.3;

    // Time horizon: early in the stream, be more willing to open new bins
    // (penalize cramming); later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer it early or when no open bin fits well.
        let openness = (1.0 - progress) * 6.0
            + if fitting_bins_count == 0 { 8.0 } else { 0.0 }
            + if post_residual == bin_capacity && next_item_size as f64 > bin_capacity as f64 * 0.5 { 2.0 } else { 0.0 };
        score = score * 0.5 + (bin_capacity as f64) * 0.5 - openness;
    } else {
        score -= progress * 5.0 * fill_ratio;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's
    // already "used up"; placing here preserves fat bins for future items.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: penalize post_residual more heavily as stream progresses
    let pr_norm = pr / cap;
    score += 40.0 * progress * pr_norm * pr_norm * cap * 0.1;

    // Reward tight fits via smooth interaction of item_size and residual
    let tight = 1.0 - (pr_norm * pr_norm);
    score -= 15.0 * tight * (item_size as f64 / cap);

    // Penalize new bins softly, more so early when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0 + 12.0 * (1.0 - progress);
    }

    // Last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let d = pr - next_item_size as f64;
        if d >= 0.0 {
            score -= 6.0 * (d / cap);
        } else {
            score += 3.0;
        }
    }

    // Mean residual coupling
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class logic: classify post_residual into residue classes of 10
    // (capacity fractions), since item sizes 1..100 make decade-aligned residuals
    // far more reusable than odd leftovers.
    let post = post_residual as u32;
    let residue = post % 10;
    if residue == 0 {
        score -= 12.0; // decade-aligned residual: excellent reuse potential
    } else if residue <= 3 {
        score += 6.0 + residue as f64; // tiny sliver: near-dead space
    } else if residue >= 7 {
        score -= 4.0; // close to next decade, still decent
    }

    // Integer-division thresholds on post_residual: coarse utility bands.
    let band = post / 25; // 0..4
    score -= band as f64 * 8.0; // larger usable space is better

    // Lookahead coupling: does this bin's post_residual fit the next item?
    if next_item_size > 0 {
        if post >= next_item_size {
            // Modular harmony between leftover and next item's decade class
            let next_res = next_item_size % 10;
            let harm = if (post % 10) == next_res % 10 { 10.0 } else { 5.0 };
            score -= harm + (post - next_item_size) as f64 * 0.3;
        } else {
            score += 5.0; // leftover unusable by the known next item
        }
    } else {
        // Last item: just minimize waste directly
        score += 0.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a fresh bin for a single item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize fragmenting when many bins are already open and mean residual
    // is small (stream nearing saturation): keep big residuals intact.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual < 25.0 && open_bins_count > 3 {
        score += (25.0 - mean_residual) * (0.5 + progress);
    }

    // Mild pressure against opening new bins early in the stream.
    if bin_residual == bin_capacity {
        score += 6.0 - 10.0 * progress; // cheap to open late, costly early
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // A perfect fit (post_residual == 0) is ideal: heavily reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        // Unusable tiny gap: dead space that likely can never host future items
        // (min item size is 1, but small gaps fragment capacity). Penalize hard.
        score += (10 - post_residual) as f64 * 6.0;
    } else if post_residual < 20 {
        // Moderately small gap: mild penalty, may still fit small items.
        score += (20 - post_residual) as f64 * 1.5;
    } else {
        // Large usable residual: reward keeping flexible space.
        score -= (post_residual as f64 - 20.0) * 0.15;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can still host the next item: reward proportionally.
            score -= 5.0 + (post_residual - next_item_size) as f64 * 0.1;
        } else {
            // Next item won't fit here: slight penalty for stranding space.
            score += 2.0;
        }
    }

    // --- Open bins pressure ---
    // Encourage consolidating into existing bins when many are open.
    score += open_bins_count as f64 * 0.8;

    // --- Mean residual coupling ---
    // Prefer bins whose residual deviates favorably from the mean:
    // tighter-than-average fit is good.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // --- Last-chance bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that fits; strongly prefer using it
        // over opening a new bin.
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Brand-new empty bin: only attractive if no good fit exists.
        // Penalize so tight fits into open bins win; the penalty shrinks
        // as the stream progresses (late items may warrant fresh bins).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward exact-ish match between post_residual and next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight coupling: perfect match strongly rewarded, mismatch penalized.
        score -= 8.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0) * 8.0;
        // Exact match bonus.
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Penalize leaving residual that next item cannot use but is large (dead space).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: minimize leftover aggressively.
        score += 0.3 * post_residual as f64;
    }

    // Relative-to-mean coupling: bins with residual far above mean are "loose" targets.
    let res = post_residual as f64;
    let dev = res - mean_residual;
    score += 0.15 * dev;

    // Penalize very small unusable residuals (dead space under typical min item size).
    if post_residual < 10 {
        score += 15.0 + post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: neutral baseline, penalized unless existing fits are poor.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when it would give a perfect fit for the item
        // and the next item, or when few bins fit the item.
        let perfect = item_size as f64 / bin_capacity as f64;
        score = 0.35 * bin_capacity as f64;
        score -= 25.0 * perfect;
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // As stream progresses, mildly discourage spreading across many bins.
        score += 5.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer filling fuller bins (best-fit flavor) among existing bins.
    score -= 0.1 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Mild penalty for accumulating too many open bins.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits in post_residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 * (next_item_size as f64 / 100.0);
        } else {
            // Penalize leaving residuals that are awkwardly sized (dead space
            // that likely can't fit typical items).
            let gap = next_item_size - post_residual;
            if gap < 15 {
                score += 8.0;
            }
        }
    }

    // Time horizon: early in stream, be conservative (prefer filling existing
    // bins); late in stream, allow new bins more freely.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, discount later.
        score += 15.0 * (1.0 - progress);
        // Penalize more when many bins are already open with slack.
        score += (open_bins_count as f64).sqrt() * 2.0;
        // If mean residual is large, opening a new bin is wasteful.
        score += mean_residual * 0.3;
    } else {
        // Existing bin with slack above mean: slightly less attractive.
        let resid_f = bin_residual as f64;
        if resid_f > mean_residual {
            score += (resid_f - mean_residual) * 0.2;
        } else {
            score -= (mean_residual - resid_f) * 0.1;
        }
    }

    // Balance number of open bins: with many open bins, prefer consolidation.
    if open_bins_count > 3 {
        score += 0.5 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let resid = bin_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Non-linear fill ratio coupling: reward high fill more strongly later in the stream.
    let fill = item / cap;
    score -= 12.0 * fill.powf(2.0) * (1.0 + progress);

    // Penalize dead space quadratically, scaled by progress (waste matters more late).
    let dead = post / cap;
    score += 20.0 * dead * dead * (0.5 + progress);

    // Perfect fit bonus: smooth exponential reward near zero residual.
    score -= 15.0 * (-post / 8.0).exp();

    // Prefer bins whose residual is close to item size (tight fit), smooth kernel.
    let tight = ((resid - item) / cap).powi(2);
    score += 8.0 * tight;

    // Lookahead: reward leaving room exactly matching the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt) / cap;
        score -= 10.0 * (-gap.abs() * 6.0).exp();
        score += 4.0 * gap.abs();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - progress * 0.5);
    }

    // Many open bins: mild penalty to favor consolidation into existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Mean residual coupling: bins below mean residual are better targets.
    score += 0.05 * (mean_residual - resid);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: items 1..100 split capacity into
    // natural "harmonic" segments. Residuals in {0} are perfect; small
    // residuals below the smallest item are dead space.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual < 10 {
        // dead space below any plausible item (interface: >=1 but tiny)
        score += 40.0;
    }

    // Integer-division harmonic classes of post_residual wrt capacity quarters
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter.max(1);
    score += class as f64 * 6.0;

    // Coupling with lookahead item: reward residuals that can host next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // exact modular harmony: post_residual is a multiple of next_item_size
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 30.0;
            } else {
                score -= 12.0;
            }
        } else {
            score += 15.0; // next item can't use this leftover
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Many open bins with slack: penalize spreading, reward consolidation
    if open_bins_count > 2 {
        score += (mean_residual - post_residual as f64).abs() * 0.3;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let tight_open = if fitting_bins_count > 0 { (fitting_bins_count - 1) as f64 } else { 0.0 };
        if tight_open <= 1.0 {
            score -= 20.0; // opening fresh is fine early / when nothing fits
        } else {
            score += 60.0; // prefer existing bins when alternatives exist
        }
    }

    // Progress-dependent tightening: later in stream, prefer exact fills
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item (1..=10) are pure waste.
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else if post_residual <= 10 {
        score += 25.0; // unusable dead space: heavy penalty
    } else if post_residual <= 20 {
        score += 8.0;  // only fits very small items: mild penalty
    } else {
        // Usable gap: reward larger remaining flexibility slightly sub-linearly.
        score -= 0.05 * (post_residual as f64).sqrt();
    }

    // Perfect-fit bonus scaled by stream position (tight packing matters more later).
    if post_residual == 0 {
        score -= 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 15.0;
        } else if gap <= 10 {
            score += 5.0;
        } else {
            score -= 2.0;
        }
    }
    // If next item cannot fit in this bin's post-residual, the gap is likely dead.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Open-bin pressure: prefer reusing bins when many are open; discourage
    // opening new bins when the fleet is already large.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count.
        score += 12.0 + 2.5 * open_bins_count as f64;
        // Allow opening a new bin if existing bins have poor fits (high mean residual spread)
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: new bin is fine
        }
        // Last-chance bin should strongly beat a new bin.
    } else if fitting_bins_count == 1 {
        score -= 20.0; // this is the only bin that fits: strong reward to use it
    }

    // Mild preference for bins below mean residual (keeps residuals balanced).
    score += 0.1 * ((post_residual as f64) - mean_residual).abs() * 0.0
        + 0.05 * (mean_residual - post_residual as f64);

    // Small tie-breaker noise-free deterministic nudge toward fuller bins.
    score += (bin_capacity - bin_residual) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect chain: next item exactly fills remaining space.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item fits: reward proportionally to tightness of the chain.
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // Next item does NOT fit: penalize dead space that blocks the lookahead item,
            // worse when the gap is small (wasted space with no utility).
            let gap = diff;
            score += 8.0 + 0.35 * gap.min(40.0) as f64;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.0;
    }

    // Penalize creating tiny unusable residuals (dead space < typical small item).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward filling bins tightly relative to the fleet mean residual.
    score -= 0.30 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline, only attractive when open bins are crowded.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.75 + 5.0 * (open_bins_count as f64).sqrt();
        // If no bin can fit the item, new bin is the only option.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item leaves little slack.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // small leftover is fine (nearly perfect packing)
    } else if post_residual >= 10 {
        // dead space that could hold a minimum item is worse if large
        score += 0.15 * (post_residual as f64 - 10.0);
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Last item: minimize waste aggressively.
        score += 2.0 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly and the stream is early (long horizon left).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; cheaper early, expensive late.
        let mut new_bin_cost = 45.0 + 60.0 * progress;
        // If many open bins with lots of slack, opening more is wasteful.
        new_bin_cost += 0.5 * open_bins_count as f64;
        // If mean residual across open bins is small, a fresh bin is more justified.
        new_bin_cost -= 0.3 * mean_residual;
        // If nothing else fits, this call is effectively the fallback.
        if fitting_bins_count == 0 {
            new_bin_cost -= 100.0;
        }
        // Large items prefer a fresh bin over fragmenting a partially used one.
        if item_size > bin_capacity / 2 {
            new_bin_cost -= 10.0;
        }
        score += new_bin_cost;
    } else {
        // Slight preference for bins with less residual relative to the fleet mean.
        score += 0.2 * (mean_residual - bin_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = fit * fit * (1.0 - progress) + fit * fit * fit * progress;
    let mut score = pr * (0.9 + 0.4 * progress) + 30.0 * poly;

    // Reward tight fits (small post_residual relative to capacity)
    score -= 25.0 * (1.0 - fit) * (1.0 - fit) * (item_size as f64 / cap);

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (next_item_size as f64 / cap)) * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Penalize opening a new bin when open bins fit well, more so early on
    if bin_residual == bin_capacity {
        score += 35.0 * (1.0 - progress) + 10.0 * (open_bins_count as f64 / (1.0 + open_bins_count as f64));
        // But allow new bin if all existing fits are terrible
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mean residual coupling: prefer bins near the mean residual (balanced packing)
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity-fraction buckets. Leftovers in the lowest classes (tight fits)
    // are rewarded; mid-range "dead zone" leftovers are penalized.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as i64; // 0..=7 harmonic class
    match class {
        0 => score -= 25.0,               // near-perfect fit
        1 => score -= 15.0,               // good fit
        2 => score += 5.0,                // awkward half-ish leftover
        3 => score += 10.0,               // dead-zone leftover
        4 => score += 6.0,
        5 => score -= 3.0,                // roomy but reusable
        6 => score -= 6.0,
        _ => score -= 8.0,                // nearly empty bin, very reusable
    }

    // Integer-division threshold: leftover divisible into plausible small
    // item chunks is more valuable than an odd remainder.
    let chunk = post_residual / 10;
    if chunk > 0 && post_residual % 10 == 0 {
        score -= 4.0;
    }
    // Odd, prime-ish leftovers are harder to fill exactly.
    if post_residual % 2 == 1 && post_residual > 1 {
        score += 2.0;
    }

    // Lookahead coupling: reward if the next item fits the post-residual
    // (chain packing), penalize near-misses.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 12.0 - (slack as f64 * 0.15).min(6.0);
        } else {
            let miss = next_item_size - post_residual;
            score += (miss as f64 * 0.1).min(8.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: only attractive when open bins are congested
    // (their mean residual is small) or many bins already exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let congestion = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 30.0 + congestion * 40.0 - progress * 10.0
              + (open_bins_count as f64 * 0.5).min(15.0);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item: fresh bin is useful
        }
    }

    // Mild global pressure to fill existing bins rather than spread out.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Prefer bins whose residual tightly matches the item (small slack ratio).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 25.0;

    // Lookahead: if next item fits the post residual, reward; if it leaves a gap just
    // below next_item_size, penalize creating a near-miss.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (1.5 + 2.0 * progress);

    // Deviation from mean residual: prefer bins below-average residual (denser bins).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // New-bin candidate calibration: an empty bin is only attractive when it beats
    // poor fits; give it a moderate base so only genuinely bad fits trigger opening.
    if bin_residual == bin_capacity {
        score += 35.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the leftover space exactly
    // matches the next item, or when the next item can still fit.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            score -= 150.0 * (post_residual as f64 / next_item_size as f64).min(2.0);
        } else {
            // Dead space the next item cannot use: penalize proportionally.
            score += 60.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64 * 100.0;
        }
    }

    // Compare post_residual against mean residual: prefer keeping the
    // residual profile homogeneous (easy to fill later).
    let pr = post_residual as f64;
    score += 0.8 * (pr - mean_residual).abs();

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 500.0;
    }

    // New-bin candidate: only attractive when existing fits are terrible
    // (large dead space) or the item nearly fills an empty bin.
    if bin_residual == bin_capacity {
        let waste_existing = if fitting_bins_count > 0 {
            (bin_capacity - item_size) as f64
        } else {
            0.0
        };
        let _ = waste_existing;
        let near_full = item_size as f64 >= 0.9 * bin_capacity as f64;
        if near_full {
            score -= 400.0;
        } else {
            score += 350.0 + 2.0 * (bin_capacity - item_size) as f64;
        }
    }

    // Mild early-stream bonus for consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * (1.0 - progress) * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward low post_residual non-linearly.
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else {
        let fill = item_size as f64 / bin_residual as f64;
        score -= 60.0 * fill * fill;
        // Dead-space penalty: small unusable leftovers are costly.
        if post_residual < 10 {
            score -= 25.0;
        } else if post_residual > 50 {
            score += (post_residual as f64 - 50.0) * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Lookahead: if next item fits in the post-residual, reward; else penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
            // Extra reward if next item exactly fills what remains.
            if next_item_size == post_residual {
                score -= 40.0;
            }
        } else {
            score += 10.0;
        }
    }

    // Time horizon: early in stream, be more willing to open/spread bins;
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress;

    // Global state: many open bins with high mean residual -> prefer filling
    // bins that are already relatively full (low residual vs mean).
    if open_bins_count > 1 {
        let rel = bin_residual as f64 / mean_residual.max(1.0);
        if rel < 1.0 {
            score -= 12.0 * (1.0 - rel);
        } else {
            score += 8.0 * (rel - 1.0);
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening new bins mildly; the last-chance bonus elsewhere
        // and tight-fit rewards on existing bins should usually dominate.
        score += 30.0 + 2.0 * open_bins_count as f64;
        // But if item is large, a fresh bin is fine (avoids fragmentation).
        if item_size >= 60 {
            score -= 25.0;
        }
        // Late in stream, strongly discourage new bins.
        score += 40.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Quadratic penalty for awkward residuals: dead space near mid-range is worst
    let mid = 0.5;
    let awkward = (norm_pr - mid) * (norm_pr - mid);
    score += 12.0 * awkward * (1.0 - progress);

    // Late in the stream, penalize residuals that cannot hold the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr >= nxt) as i32 as f64;
        let slack = ((pr - nxt).abs()) / cap;
        // reward fitting next item smoothly, stronger late
        score -= 15.0 * fits_next * (0.3 + 0.7 * progress) * (1.0 - slack * slack);
        // penalize near-miss residuals that almost fit next item
        let near_miss = if pr < nxt { (nxt - pr) / nxt } else { 0.0 };
        score += 8.0 * near_miss * near_miss * progress;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Many open bins: encourage consolidation by penalizing high residual spread
    let spread = (mean_residual - pr).abs() / cap;
    score += 5.0 * spread * spread * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // Smooth coupling of item fill ratio with progress
    let fill = item_size as f64 / cap;
    score -= 6.0 * fill * fill * (1.0 - progress);

    // New-bin candidate handling: penalize opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        let tight = (mean_residual / cap).max(0.0);
        score += 20.0 * (1.0 - tight) * (0.5 + 0.5 * progress);
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 and mod 25
    let r10 = (post_residual % 10) as f64;
    let r25 = (post_residual % 25) as f64;
    let q25 = (post_residual / 25) as f64;

    // Penalize awkward residues (dead space far from a harmonic class boundary)
    score += 0.6 * r10 + 0.3 * r25;

    // Reward post_residuals that are clean multiples of common size classes
    if post_residual % 10 == 0 { score -= 4.0; }
    if post_residual % 25 == 0 { score -= 3.0; }
    if post_residual % 20 == 0 { score -= 2.0; }

    // Coupling with lookahead item: perfect next-fit is golden
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward closeness of fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
            // harmonic match of leftover after hypothetical next placement
            let pr2 = post_residual - next_item_size;
            if pr2 % 10 == 0 { score -= 3.0; }
            if pr2 % 25 == 0 { score -= 2.5; }
        } else {
            // next item will NOT fit here: penalize small unusable leftovers
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
            if post_residual < 10 { score += 12.0; } // tiny dead space
        }
    }

    // Integer-division thresholds on post_residual quarters
    let quarter = (4 * post_residual) / bin_capacity;
    match quarter {
        0 => score += 5.0,   // nearly full bin: very good (small residual)
        1 => score -= 2.0,
        2 => score += 0.0,
        _ => score += 1.5,   // large residual: less attractive
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when current residuals are bad
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let badness = (mean_residual - post_residual as f64).abs();
        // Prefer new bin if mean residual is large (open bins fragmented)
        score += 6.0 - 0.25 * badness - 0.05 * pressure;
        // Late in the stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If next item is small, a fresh bin wastes capacity
        if next_item_size > 0 && next_item_size <= 20 { score += 8.0; }
    }

    // Mild tie-break: prefer bins whose residual is below mean (tighter bins)
    score += 0.05 * (post_residual as f64 - mean_residual);

    // Small noise-free deterministic jitter via step parity for tie-breaking
    if step_index % 2 == 0 { score -= 0.01; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Semi-dead zone: gaps that only very large items could use are risky.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / item_size.max(1) as f64;
    score -= 8.0 / (1.0 + tightness);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here: residual likely becomes dead space.
            score += 6.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): penalize so it's chosen only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If nothing else fits well, opening fresh is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild preference to use bins with larger residuals early (keep small residuals pristine),
    // scaled by stream progression.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 - mean_residual) * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits, but reward tighter matches
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // dead space relative to lookahead item
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // last item: strongly prefer minimal post residual
        score += 10.0;
    }

    // Compare against mean residual: bins below mean residual are tighter -> prefer
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: only fitting bin -> strong incentive to use it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins fit reasonably well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 - 100.0 * progress;
        if fitting_bins_count > 0 {
            score += 100.0;
        }
        // new bin still attractive if next item is large and won't fit elsewhere
        if next_item_size > 60 && post_residual == bin_capacity {
            score -= 50.0;
        }
    }

    // Slight preference to fill emptier bins when many bins are open
    score += 0.1 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight-fit reward: strongly favor bins where item fills most of residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize large dead space relative to capacity.
    score += 0.35 * (post / cap) * (post / cap) * cap;

    // Lookahead: reward if next item fits into the post residual (chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 8.0 * (nxt / post.max(1.0));
        } else {
            // Penalize residuals that neither fit next item nor are tiny.
            let gap = (nxt - post) / cap;
            score += 6.0 * gap;
        }
    } else {
        // Last item: pure tightness.
        score -= 6.0 * fill_ratio;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else {
            (post as f64) // post == capacity here
        };
        let avg_fit_quality = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).abs() / cap
        } else { 1.0 };
        score = cap + 20.0 * avg_fit_quality + poor_fit * 0.1;
        // Early in stream, opening bins is cheap and useful for future flexibility.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score -= 10.0 * (1.0 - progress);
        // Many open bins with slack: prefer reusing.
        score += 2.0 * open_bins_count as f64;
    }

    // Mild preference for bins below mean residual (balance load).
    score -= 0.05 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping by stream progress.
    let poly = 1.0 + 0.6 * progress - 0.8 * progress * progress;
    let mut score = pr * poly;

    // Smooth coupling: penalize residual that is too small to be useful later.
    let useless = 1.0 - (norm_pr * 10.0).min(1.0);
    score += 40.0 * useless * useless * (0.5 + progress);

    // Tight fit reward (non-linear in fill ratio).
    let fill = 1.0 - norm_pr;
    score -= 30.0 * fill * fill * fill;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 - progress);
    }

    // Lookahead: penalize if the next item cannot use the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr as f64 {
            score += 15.0 * (nxt - pr) / cap;
        } else {
            score -= 10.0 * (pr - nxt) / cap;
        }
    }

    // Prefer bins with residual below mean (consolidate large residuals).
    score += (pr - mean_residual) * (0.3 + 0.4 * progress);

    // New-bin candidate: penalize opening a new bin, more so early on.
    if bin_residual == bin_capacity {
        score += 25.0 + 35.0 * (1.0 - progress) + open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into small
    // "dead zones" (1..=5, or exact multiples of 10) are near-perfect fills.
    let pr = post_residual;
    let harmonic_class = if pr == 0 { 0 } else if pr <= 5 { 1 } else if pr % 10 == 0 { 2 } else { 3 };
    match harmonic_class {
        0 => score -= 60.0,          // perfect fill
        1 => score -= 35.0,          // near-perfect dead space
        2 => score -= 15.0,          // residual divisible by 10: reusable by common sizes
        _ => {}
    }

    // Integer-division threshold: prefer residuals that can host a mid-size item later.
    if pr >= 40 {
        score -= 8.0 + (pr as f64) * 0.05;
    } else if pr < 10 {
        score += 5.0; // tiny unusable residue unless already rewarded above
    }

    // Tightness: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / cap;
    score -= fill_frac * 30.0;

    // Lookahead coupling: reward if next item exactly fits the post_residual,
    // penalize if next item needs more than post_residual (forcing another bin).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= 20.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only open a new bin when it looks genuinely useful.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer existing bins by default.
        score += 25.0;
        // But if no open bin can fit (this call is the only candidate) we must open.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
        // If the item is large relative to mean residual of open bins, a fresh bin
        // may be better than fragmenting.
        if (item_size as f64) > mean_residual * 0.85 && open_bins_count > 0 {
            score -= 20.0;
        }
        // Early in the stream, opening bins is cheap and builds diversity.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.15 {
            score -= 10.0;
        }
        // Perfect harmonic placement into a fresh bin (item size divides capacity).
        if bin_capacity % item_size == 0 {
            score -= 18.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space that cannot fit the next item is worse.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 2.5 * open_bins_count as f64 * (1.0 - tightness);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current bins have poor fits.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.15;
    }

    // Late-stream consolidation: prefer filling bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-match lookahead: strongly reward bins whose leftover fits the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here too: reward proportional to how tight it is.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leftover dead space that is too small to matter.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += (10.0 - dead) * 4.0;
            }
        }
    } else {
        // Last item: minimize leftover directly.
        score += 10.0;
    }

    // Compare residual against mean residual across open bins.
    score -= (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a new bin when decent fits exist; new-bin candidate has full residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size && fitting_bins_count > 0 {
            score += 15.0; // new bin pairs well with next item only if we don't waste an old bin
        }
    }

    // Mild preference for tighter fits overall.
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 35.0 * tightness * tightness;

    // Penalize dead space: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: penalize leaving a residual that cannot host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward leaving room exactly useful for the next item.
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Residual is wasted with respect to the next item.
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = (mean_residual - item_size as f64).abs();
        score = (bin_capacity as f64) - item_size as f64
            + 20.0
            - 0.5 * poor_fit_elsewhere
            - 2.0 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * progress;
    }

    // Mild pressure to fill bins that are already quite full.
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Slight preference for bins whose residual is close to the item (perfect-ish fit).
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 15.0 * gap * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - (post_residual as f64 / cap);

    // Smooth non-linear coupling: reward tight fits more as stream progresses
    score -= tightness * tightness * (cap * (0.5 + progress));

    // Reward if the next item can still fit into post_residual (smoothly)
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= post_residual as f64) as f64;
        score -= fits_next * (next_item_size as f64 * 0.6) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Mild penalty proportional to how far this bin's residual deviates from mean residual
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // New empty bin candidate: penalize mildly, more early, less late
    if bin_residual == bin_capacity {
        score += cap * (1.2 - 0.7 * progress);
    }

    // Small penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10.
    let residue = post_residual % 10;
    // Residue 0 (exact decade fill) is ideal — strong reward.
    if residue == 0 {
        score -= 25.0;
    } else {
        // Penalize awkward residues; small residues near 0 are more usable.
        score += (10 - residue) as f64 * 0.8;
    }

    // Integer-division thresholds on post_residual: dead-space bands.
    let band = post_residual / 10; // 0..=10
    match band {
        0 => score -= 15.0,            // nearly full: excellent
        1 => score -= 8.0,             // good
        2 | 3 => score += 2.0,         // mid: neutral-ish
        4 | 5 => score += 6.0,         // leaves awkward gap
        6 | 7 => score += 10.0,        // large gap: wasteful
        _ => score += 14.0,            // mostly empty placement
    }

    // Coupling: does post_residual fit the next item exactly / well?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 30.0;         // perfect two-item closure
            } else {
                score -= (20.0 * (1.0 - slack as f64 / bin_capacity as f64)).max(0.0);
            }
        } else {
            // next item cannot follow here; penalize proportionally to wasted potential
            score += 5.0 + (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }
    // Many fitting bins: mild penalty for spreading too thin? Prefer tighter bins via base term already.

    // New-bin candidate handling: only prefer fresh bin when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        // Fresh bin baseline: slightly above a well-fitting open bin, below a bad fit.
        score += 20.0 + pressure * 4.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 && item_size >= bin_capacity / 2 {
            score -= 10.0; // pair large+next in fresh bin
        }
    }

    // Mean-residual coupling: if open bins are already loose, discourage leaving another loose bin.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Progress-based mild tightening: later in stream, prefer fuller placements.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Reward tight fits (small but not dead residuals).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.3;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: more open bins -> discourage spreading, favor new-bin candidate less.
    score += open_bins_count as f64 * 0.5;

    // Mean residual coupling: if this bin's residual is far below mean, it is fragmented; penalize slightly.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score += (mean_residual - resid) * 0.15;
    }

    // New-bin candidate calibration: empty bin gets a moderate baseline so it is
    // chosen only when open bins would create dead space.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Near-perfect match: next item fits with small leftover
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 300.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item does NOT fit in this bin: penalize proportionally to how close we were
        let miss = (next_item_size - post_residual) as f64;
        score += 80.0 * (miss / bin_capacity as f64);
    }

    // Compare post_residual against mean residual: leaving more than average wastes space
    let mean_post = mean_residual - item_size as f64;
    if post_residual as f64 > mean_post {
        score += 0.5 * (post_residual as f64 - mean_post);
    } else {
        score -= 0.3 * (mean_post - post_residual as f64);
    }

    // Tight fit reward: post_residual is small dead space
    if post_residual < 10 {
        score -= 200.0;
    } else if post_residual < 20 {
        score -= 100.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // If open bins have lots of residual (fragmented), opening new bin is less bad
        score += 400.0 - 300.0 * fragmentation.min(1.0);
        // Early in stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 100.0 * (1.0 - progress);
    }

    // Slight preference for bins with less residual overall (best-fit bias)
    score += 0.2 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fit_ratio;

    // Penalize dead space non-linearly: residuals that can never be reused well.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * dead * dead;

    // Lookahead: reward bins whose leftover can host the next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 4.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot use this leftover: mild penalty scaled by gap.
        score += 0.05 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, push harder toward tight fits.
        score += 1.5 * (fitting_bins_count.min(10) as f64) * dead;
    }

    // New-bin candidate: only attractive when open bins are badly fragmented
    // (high mean residual relative to capacity) or item barely fits anywhere.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let tightness = 1.0 - fit_ratio;
        score += 10.0;                       // default cost of opening a bin
        score -= 8.0 * fragmentation;        // open bins full of dead space -> new bin ok
        score -= 4.0 * tightness * tightness; // large items prefer fresh bins
        score -= 2.0 * (open_bins_count.min(20) as f64).ln().max(0.0);
    }

    // Time horizon: early in stream, be conservative with new bins; later,
    // allow more aggressive consolidation of residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - dead);
    score += 2.0 * (1.0 - progress) * dead;

    // Prefer balancing residuals against the fleet mean.
    score += 0.3 * (post_residual as f64 - mean_residual).abs() / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // later in the stream, compact placements matter more.
    let norm_pr = pr / cap;
    score += 30.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits (small post_residual) with a smooth quadratic discount.
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Penalize bins with very low residual relative to mean residual (dead space).
    let dead = (mean_residual - pr).max(0.0) / cap;
    score += 10.0 * dead * dead;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            // smooth penalty growing with mismatch
            let miss = (nxt - pr) / cap;
            score += 8.0 * miss * miss;
        }
    }

    // New-bin candidate: penalize opening a bin, unless item is large and
    // current bins are crowded (smooth in item size and open-bin count).
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64) / (1.0 + open_bins_count as f64);
        let size_frac = item_size as f64 / cap;
        score += 10.0 - 6.0 * size_frac * (1.0 - crowd) - 5.0 * progress;
        // if no existing bin fits, new bin is necessary
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect closures (0) are ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: residuals too small for the smallest item are pure waste.
        if post_residual < 10 {
            score += 200.0;
        }
        // Modulo-class reward: residuals divisible into common fractions of capacity
        // are reusable "harmonic" slots (25, 50, 75, 20, 40, 60, 80).
        let harmonic = post_residual % 25 == 0 || post_residual % 20 == 0;
        if harmonic {
            score -= 60.0;
        }
        // Reward residuals that can host the lookahead item exactly or well.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 300.0;
            } else if post_residual >= next_item_size {
                let slack = post_residual - next_item_size;
                if slack % 25 == 0 || slack % 20 == 0 {
                    score -= 40.0;
                }
                if slack < 10 {
                    score += 80.0; // lookahead leaves near-dead space
                }
            } else {
                // lookahead cannot use this residual: slight penalty scaled by waste
                score += (next_item_size - post_residual) as f64 * 0.5;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin offers
    // a tight fit (post_residual small) and the mean residual is already large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight_exists = post_residual as f64 > (bin_capacity as f64 - mean_residual) * 0.5;
        if tight_exists || mean_residual < 20.0 {
            score += 500.0; // prefer an existing open bin
        } else {
            score += 100.0 * progress; // mild preference for new bin late in stream
        }
        // Never open a new bin when an existing bin closes perfectly.
        if post_residual == 0 {
            score += 1200.0;
        }
    }

    // Tie-break: prefer bins with residual close to the item (tight fit) via
    // integer-division threshold on bin_residual.
    let ratio_class = bin_residual / item_size.max(1);
    if ratio_class == 1 {
        score -= 30.0; // bin_residual < 2*item: very tight fit
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps below the minimum item size are pure waste.
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        // Non-linear penalty: small unusable gaps hurt quadratically.
        if post_residual < 10 {
            score += 40.0 * (1.0 - dead) * (1.0 - dead);
        } else {
            score -= 2.0 * dead * dead * (bin_capacity as f64);
        }
    } else {
        // Perfect fit is heavily rewarded.
        score -= 25.0;
    }

    // Tight fit reward relative to item size.
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 10.0 * tightness;

    // Pressure from open bin count: prefer filling existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.15 + 0.35 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * ((next_item_size as f64) / (post_residual.max(1) as f64));
        } else {
            // Next item won't fit here anyway; penalize leaving moderately sized gaps.
            score += 3.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below mean (more filled).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // New-bin candidate: penalize opening a new bin unless it's early or current bins are poor fits.
    if bin_residual == bin_capacity {
        let new_bin_base = 20.0 + 30.0 * progress + (open_bins_count as f64) * 0.8;
        // If item is large, a fresh bin is more acceptable.
        let large_item_bonus = if item_size >= 50 { -10.0 } else { 0.0 };
        score += new_bin_base + large_item_bonus;
        if fitting_bins_count <= 1 {
            score -= 15.0; // no real alternative, new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
