    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Many open bins: prefer consolidating into fuller bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins whose residual deviates favorably from mean residual
    let res = bin_residual as f64;
    score += 0.15 * (res - mean_residual);

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if the item is large, a fresh bin may be good
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // Late in the stream, prefer closing out with new bins less
        if progress > 0.8 {
            score += 10.0 * progress;
        }
    }

    score
