pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter/half classes mod capacity
    let item_class = item_size % 25; // harmonic residue class (C/4 = 25)
    let next_class = if next_item_size == 0 { 0 } else { next_item_size % 25 };

    // Reward near-perfect fills: post_residual small but nonzero is golden
    if post_residual > 0 && post_residual <= 10 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize dead space that no future harmonic class can fill:
    // dead space is "usable" if it is >= smallest plausible item (1..=25 class)
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 25.0 {
        // only next_class-sized items could fit; reward if next item matches
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        } else {
            score += 12.0;
        }
    }

    // Harmonic complement: if next item exactly complements this bin, strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // Partial complement within a quarter class
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 12 {
            score -= 10.0;
        }
    }

    // Integer-division thresholds on post_residual (quarter bands)
    let band = post_residual / 25; // 0..4
    score += match band {
        0 => -4.0,              // 0..24 residual: tight fill, good
        1 => 2.0,
        2 => 5.0,
        3 => 8.0,
        _ => 0.0,
    };

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits (tie-break)
        score += (post_residual as f64) * 0.15;
    }

    // New-bin candidate: only attractive when residual structure is bad
    if bin_residual == bin_capacity {
        // opening fresh is good if current bin would leave large odd dead space
        // and many bins are already open (fragmentation)
        let frag = open_bins_count as f64 / (total_items.max(1) as f64);
        if post_residual < 20 && next_item_size > post_residual {
            score -= 8.0 + 20.0 * frag;
        } else {
            score += 30.0; // default: prefer filling existing bins
        }
    }

    // Mean-residual coupling: if this bin is much tighter than average, favor it
    score -= (mean_residual - post_residual as f64) * 0.2;

    // Progress-scaled exploitation: late in stream, avoid waste more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += dead * (0.3 + 0.4 * progress);

    // Small harmonic tie-break on item class parity to diversify placements
    if item_class % 2 == 0 {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // Gaps below 10 (minimum item size under original regime) are pure waste;
    // under the 1..100 regime, treat gaps < 8 as dead space with escalating penalty.
    if post_residual < 8 {
        score += 40.0; // paradoxically large penalty: a tiny gap means near-perfect fit is wasted by penalty? No —
        // actually reward near-perfect fits: a small post_residual is GOOD, so reward instead.
    }
    // Correcting: small post_residual is desirable. Reward exact/near fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

