    if post_residual > 15 && post_residual < 30 {
        score += 12.0;
    }

    // Open-bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // Brand-new bin candidate: penalize proportionally to open bin pressure.
        score += 15.0 + 3.0 * open_bins_count as f64;
        // But if this bin is the last chance and fit is poor, new bin may be better:
        if fitting_bins_count == 1 && post_residual > 40 {
            score -= 20.0;
        }
    } else {
        // Last-chance bonus: using the only fitting bin avoids a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Mild stream-progression term: later in stream, prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.05;

    // Mean residual coupling: if this bin is far below mean residual, its space is scarce — prefer using it.
    score -= (mean_residual - post_residual as f64) * 0.10;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

