    // Compare against mean residual: prefer bins whose post residual is below average
    // (tight packing), penalize bins that stay far above average.
    score += 0.15 * (post_residual as f64 - mean_residual).max(-40.0).min(40.0);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets base cost so it's only chosen
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 15.0;
        // early in stream, opening bins is fine; late in stream, discourage
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 20.0 * progress;
        }
        // if next item is large and current item small, new bin may be good
        if next_item_size > 0 && next_item_size > item_size + 20 {
            score -= 25.0;
        }
    }

    // Prefer filling larger-residual bins with large items (avoid fragmenting tight bins)
    if item_size >= 50 {
        score -= 0.1 * (bin_residual as f64 - item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squashed post-residual counts less.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 20.0;

    // Penalize leaving dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
