    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer opening a new bin when existing fits are poor
    // (large post_residual waste) or when the item is large and residuals are fragmented.
    if bin_residual == bin_capacity {
