        let waste_pressure = (post_residual as f64) / 10.0 + fragmentation * 10.0;
        // Baseline competitiveness: new bin is attractive unless an open bin fits very tightly.
        score = 60.0 + waste_pressure;
        if item_size >= 50 && fragmentation > 0.5 {
            score -= 15.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        score -= open_bins_count as f64 * 1.5;
    }

    // Mild preference for filling bins with larger residuals when many bins are open.
    score += (bin_residual as f64 - mean_residual) * 0.05;

