}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual

    // Base: prefer small post residual, with smooth non-linear shaping
    let mut score = post * (1.0 + 0.8 * pr * pr);

    // Non-linear coupling of post residual with stream progress:
    // early on, tolerate larger residuals; later, penalize them more (tight packing).
    let progress_coupling = (0.5 * progress - 0.25) * (pr * (1.0 - pr)) * cap;
    score += 4.0 * progress_coupling;

    // Smooth interaction: post residual vs mean residual of open bins.
    // A bin much tighter than the mean is valuable to fill now.
    let mr = mean_residual / cap;
    score += 3.0 * (mr - pr) * (mr - pr) * cap * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let snug = 1.0 - ((post - nxt) / cap);
            score -= 6.0 * snug * snug;
        } else {
            score += 2.0 * ((nxt - post) / cap);
        }
    }

    // Slight penalty for spreading across many bins when residuals are large.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress) * (1.0 - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes (0..=15) are near-perfect; heavily reward them.
    let residue_class = post_residual % 25;
    match residue_class {
        0 => score -= 30.0,                 // exact / quarter-class fit
        1..=5 => score -= 18.0,             // near-perfect dead space
        6..=10 => score -= 8.0,             // decent
        11..=15 => score -= 2.0,            // marginal
        16..=20 => score += 6.0,            // wasteful class
        _ => score += 12.0,                 // large unusable chunk (21..=24)
    }

    // Integer-division thresholds on post_residual relative to capacity.
    let q = post_residual / 10; // decades of leftover
    score -= (10 - q.min(10)) as f64 * 1.5; // tighter decade => lower score

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement is harmonically aligned.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mild reward, scaled by how close.
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - gap / 50.0).max(0.0);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize large stranded space.
        score += (post_residual as f64).min(next_item_size as f64) * 0.15;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: only attractive when the current item is
    // large and no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin.
        score += 55.0;
        if item_size >= 60 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // forced to open anyway
        }
        // If mean residual across open bins is large, opening is wasteful.
        score += (mean_residual / 10.0).min(20.0);
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Prefer fuller bins overall: small residual relative to mean is good.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Crowding pressure: with many open bins, be greedy about filling them.
    if open_bins_count > 3 {
        score -= open_bins_count as f64 * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
