    }

    // Open-bin pressure: discourage spreading across many bins early.
    score += open_bins_count as f64 * 1.2;

    // Slight preference for bins below mean residual (consolidate slack).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Late-stream tightening: accept looser fits as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
