        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this placement sets up a perfect follow-up fit.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 800.0;
        } else if post >= nxt {
            // next item fits: mild reward proportional to how snug the chain is
            score -= 200.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item will NOT fit into leftover: penalize dead space
            score += 150.0 * (1.0 - post / bin_capacity as f64);
        }
    }

    // Compare against mean residual: leaving post_residual near the mean keeps
    // bins homogeneous; very small leftovers are wasted capacity.
    if post_residual > 0 {
        let mdiff = (post_residual as f64 - mean_residual).abs();
        score += 0.5 * mdiff;
        if (post_residual as f64) < mean_residual * 0.25 {
            score += 60.0; // small unusable sliver
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // (i.e., this is a fresh bin and existing bins are crowded).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (next_item_size > 0 && (post_residual as f64) >= next_item_size as f64);
        if poor_fit_elsewhere {
            score -= 250.0 + 100.0 * progress + 20.0 * crowd;
        } else {
            score += 400.0; // discourage opening new bins when decent fits exist
        }
    }

    // Late-stream consolidation: prefer tighter packing as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that nothing can use (min item ~1, but typical items larger).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0; // hard-to-fill gap
    }

    // Lookahead coupling: if next item fits into post_residual, big bonus.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 20.0 + 0.3 * next_item_size as f64;
        } else if (bin_residual as u32) < next_item_size {
            // next item won't fit here even without current item; mild penalty
            score += 5.0;
        }
        // Perfect chain: post_residual == next_item_size exactly
        if post_residual as u32 == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this bin.
    if bin_residual == bin_capacity {
        // Prefer new bin only when existing bins fit poorly or are scarce.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = mean_residual * (open_bins_count as f64).sqrt();
        score += 35.0 + 0.5 * waste - 20.0 * progress;
        // If item is huge and no open bin would leave a good residual, new bin ok.
        if item_size as f64 > 0.7 * bin_capacity as f64 && mean_residual < 15.0 {
            score -= 30.0;
        }
    } else {
        // Favor filling bins with larger residuals first (keep tight bins for small items).
        score += 0.1 * (bin_capacity as f64 - bin_residual as f64);
    }

    // Time horizon: early in the stream, be conservative (keep residuals flexible);
    // late in the stream, pack greedily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fit_ratio);

    // Many open bins: encourage consolidation into existing bins.
    score += 0.15 * open_bins_count as f64 * fit_ratio;

    // Deviation from mean residual: prefer bins whose residual is close to item needs.
    let target = item_size as f64;
    let dev = (bin_residual as f64 - target) / bin_capacity as f64;
    score += 12.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear (quadratic/cubic) coupling.
    let mut score = pr + 30.0 * norm_pr * norm_pr + 60.0 * norm_pr * norm_pr * norm_pr;

    // Stream-progress coupling: later in the stream, dead space hurts more.
    score += 40.0 * progress * norm_pr * norm_pr;

    // Perfect fit reward (smooth, non-piecewise).
    let perfect = (pr as f64).exp() / (1.0 + (pr as f64).exp());
    score -= 15.0 * (1.0 - perfect);

    // Lookahead: if next item exactly fits the post residual, strongly reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (-gap / 10.0).exp();
        // Penalize leaving a residual only slightly larger than the next item (dead space risk).
        score += 6.0 * (-(post_residual as f64 - next_item_size as f64).abs() / 4.0).exp()
            * (post_residual as f64 - next_item_size as f64).signum();
    } else {
        // Last item: waste matters most.
        score += 10.0 * norm_pr;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty when bin residual deviates from mean residual (balance spreading).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline, penalized when good fits exist elsewhere.
    if bin_residual == bin_capacity {
        score = cap * (1.0 + progress) + 0.05 * open_bins_count as f64;
        if next_item_size > 0 {
            // Opening a new bin is attractive if the next item is large.
            score -= (next_item_size as f64 / cap) * 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 classify dead space quality.
    let residue_class = post_residual % 10;
    // Classes 0 (perfect) .. 9 (worst): penalize awkward residues.
    let awkward = if residue_class == 0 { 0.0 }
        else if residue_class <= 2 { 2.0 }
        else if residue_class <= 5 { 5.0 }
        else { 9.0 };
    score += awkward;

    // Integer-division tier of post_residual: coarse dead-space bands.
    let tier = post_residual / 25; // 0..4
    score += tier as f64 * 6.0;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic compatibility: next item's residue class complements ours.
            let combo = (post_residual % 10) + (next_item_size % 10);
            let harmony = if combo % 10 == 0 { 12.0 } else { 4.0 };
            score -= harmony + (next_item_size as f64 / 10.0);
        } else {
            // Next item cannot follow here: penalize proportionally to waste.
            score += 8.0 + (next_item_size as f64 - post_residual as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: discourage fragmenting further; few bins: consolidation is fine.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += pressure * 3.0;

    // Mean residual context: if this bin is far below mean residual, it's already
    // fragmented; prefer bins closer to the mean (tight packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.1;

    // New-bin candidate: score it so it wins only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, modulated by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 + 25.0 * progress;
        // If current item is large relative to capacity, a fresh bin is fine.
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // If next item is huge, a fresh bin leaves room for it.
        if next_item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot fit even the smallest plausible item is "dead".
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 18.0;
    }

    // Reward very tight fits (best-fit amplification).
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> penalize spreading, encourage filling.
    let pressure = open_bins_count as f64 * 1.5;
    if bin_residual != bin_capacity {
        score += pressure;
    }

    // New-bin candidate: only attractive when item leaves a large, reusable gap
    // or when existing bins would create dead space.
    if bin_residual == bin_capacity {
        score += 25.0; // default mild penalty for opening a new bin
        if post_residual as f64 >= mean_residual + 30.0 {
            score -= 40.0; // large reusable gap justifies a fresh bin
        }
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would be blocked by a near-dead residual, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // Late in the stream, favor consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    // Mild preference for bins already below mean residual (fill emptier bins first).
    if bin_residual as f64 > mean_residual {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Two-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post residual exactly matches next item -> big reward.
            let chain_gap = (post_residual - next_item_size) as f64;
            score -= 40.0 + 30.0 * (1.0 - chain_gap / bin_capacity as f64);
        } else {
            // Dead space that next item cannot use: penalize proportionally.
            let dead = (post_residual as f64) / bin_capacity as f64;
            score += 25.0 * dead * dead;
        }
        // Bonus if this bin AND the next item both fit snugly (item + next ≈ capacity).
        let chain_sum = item_size as f64 + next_item_size as f64;
        if chain_sum <= bin_capacity as f64 {
            let snug = 1.0 - (bin_capacity as f64 - chain_sum) / bin_capacity as f64;
            score -= 15.0 * snug * snug;
        }
    } else {
        // Last item: just minimize waste.
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward tight fits of the current item relative to the bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Penalize creating tiny unusable residuals (< 10, min item size) heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 35.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect closure
    }

    // Compare against mean residual: prefer bins below mean residual (denser bins).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): only attractive when no open bin fits well
    // or post_residual would be large dead space; otherwise push it to be chosen rarely.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        // Opening a new bin is good if it would be nearly filled by item + next item.
        if next_item_size > 0 && (item_size as f64 + next_item_size as f64) >= bin_capacity as f64 {
            score -= 20.0;
        } else {
            score += 45.0 + 0.5 * waste;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // Many open bins with slack: discourage opening yet another bin.
        score += 2.0 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of this placement.
    let fill = item_size as f64 / cap;
    score -= 2.0 * fill * (bin_residual as f64);

    // Penalize dead space: small post_residual is good, but extremely tiny
    // leftovers (<10) are nearly unusable, so reward them extra.
    if post_residual > 0 {
        if post_residual < 10 {
            score -= 8.0; // near-perfect packing
        } else {
            // Larger leftover than the smallest possible item is wasteful.
            score += 0.05 * (post_residual as f64).sqrt();
        }
    } else {
        score -= 12.0; // exact fit is ideal
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves further slack: mild reward scaled by fit quality.
            let slack_after = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack_after / cap);
        } else {
            // Next item won't fit here; penalize leaving a gap smaller than next item.
            score += 0.15 * ((post_residual as f64) - (next_item_size as f64)).abs();
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Global state: when many open bins exist with large mean residual,
    // discourage opening new bins (favor consolidation into open bins).
    if bin_residual < bin_capacity {
        score -= 0.05 * mean_residual;
        score -= 0.3 * open_bins_count as f64;
    } else {
        // New-bin candidate: only attractive when open bins are mostly full.
        let open_pressure = mean_residual / cap;
        score += 20.0 * (1.0 - open_pressure);
        // Early in the stream, opening bins is cheaper (future items can fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Time-horizon coupling: late in the stream, prioritize finishing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = post;

    // Quadratic dead-space penalty, amplified as stream progresses
    score += 40.0 * norm_post * norm_post * (0.5 + progress);

    // Cubic coupling: strongly punish mid-range wasted space
    score += 25.0 * norm_post * norm_post * norm_post;

    // Reward tight fits (small post residual) more over time
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (10.0 + 30.0 * progress);

    // Interaction: item size vs remaining capacity
    score += 15.0 * norm_item * norm_post;

    // Last-chance bin: strong bonus if this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt) / cap;
            score -= 30.0 * (1.0 - gap * gap);
        } else {
            score += 10.0 * ((nxt - post) / cap);
        }
    }

    // Prefer bins with residuals near the mean (balance open bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.5 * (1.0 - (1.0 - norm_post).abs());

    // New-bin candidate: penalize opening a new bin unless post residual is large
    if bin_residual == bin_capacity {
        score += 25.0 + 40.0 * (1.0 - progress) - 20.0 * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but with a twist:
    // dead space below the smallest plausible item (~10) is pure waste.
    let dead = if post_residual < 10 { (10 - post_residual) as f64 } else { 0.0 };
    score += 6.0 * dead;

    // Harmonic class of post_residual modulo capacity fractions.
    // Residuals in [1..9] are near-useless; residuals that are multiples
    // of common item sizes (10, 20, 25, 50) are attractive.
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect fill
    } else if pr <= 9 {
        score += 30.0; // dead-space band penalty
    } else {
        // reward divisibility (harmonic alignment) of the leftover space
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 || pr % 50 == 0 { score -= 5.0; }
        // penalize awkward odd classes (prime-ish leftovers)
        if pr % 10 != 0 && pr % 5 != 0 { score += 6.0; }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if it nearly fits (off by <=3), also good.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr && pr - next_item_size <= 3 {
            score -= 8.0;
        } else if next_item_size > pr && next_item_size - pr <= 3 {
            score += 5.0; // next item just misses this bin
        }
        // modulo-class harmony between leftover and next item
        if next_item_size <= pr && (pr % 10) >= (next_item_size % 10) {
            score -= 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit would be terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
        if post_residual <= 5 { score -= 8.0; } // still worth it for tight fit
    }

    // New-bin candidate: only attractive when item is large relative to
    // residual structure or all fits are bad. Penalize opening new bins
    // mildly, more so when many bins are already open.
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / (bin_capacity as f64);
        score = 55.0 - 30.0 * pressure;
        if fitting_bins_count == 0 { score -= 40.0; }
        if open_bins_count > 8 { score += 6.0 * ((open_bins_count as f64) / 10.0); }
        // early stream: fresh bins cheap; late stream: consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild consolidation bias: prefer bins below mean residual (tighter bins)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard penalty for small unusable dead space (post_residual in (0, 10))
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Moderate penalty for gaps that only fit tiny items (10..20)
    else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward perfect and near-perfect fits
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += 0.35 * open_bins_count as f64;

    // Dead-space coupling with mean residual: prefer bins tighter than average
    score += 0.5 * (mean_residual - post_residual as f64);

    // Lookahead: if the next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item cannot fit and post_residual is small, mild penalty
    else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // New-bin candidate: make it unattractive unless few bins are open early in stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // next item fits too: mild reward proportional to tightness
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize small dead space
            score += 30.0 * next_item_size as f64 / 100.0;
        }
    }

    // Penalize dead space that is too small for typical items (below min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong preference to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is very poor
    if bin_residual == bin_capacity {
        score += 250.0;
        // but if next item is large and nothing fits well, new bin is attractive
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
    }

    // Late in stream: prefer compacting into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual == 0 is perfect.
    score -= (bin_capacity as f64 - post_residual as f64).powf(1.5) * 0.05;

    // Penalize dead space that no plausible item can fill.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item {
            score += 50.0;
        }
        // Lookahead: if next item fits exactly into post_residual, reward strongly.
        if next_item_size > 0 && next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else if next_item_size > post_residual {
            // Next item cannot use this bin; penalize proportionally to wasted space.
            score += 5.0 + (post_residual as f64 / bin_capacity as f64) * 10.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate logic: only attractive when current fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early stream: opening bins is cheap; late stream: prefer filling existing.
        let new_bin_bonus = 15.0 * (1.0 - progress) - 10.0 * progress;
        // If the item would leave a very tight residual elsewhere, new bin is fine.
        let tightness = post_residual as f64 / bin_capacity as f64;
        score += new_bin_bonus + tightness * 8.0;
        // If many bins open and mean residual high, discourage yet another bin.
        score += open_bins_count as f64 * 0.5 + mean_residual * 0.05;
    } else {
        // Favor bins with residual close to item (minimal waste ratio).
        let waste_ratio = post_residual as f64 / bin_residual.max(1) as f64;
        score += waste_ratio * 6.0;
        // Slight preference for bins below mean residual (balance loads).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Global load pressure: many open bins -> prioritize consolidation.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling: small residuals penalized more as stream progresses
    let tight = (1.0 - pr_norm).powi(3);
    score += 60.0 * tight * (0.3 + progress);

    // Quadratic post-residual coupling with progress
    score += 0.4 * pr_norm * pr_norm * cap * (1.0 - progress);

    // Dead-space term: residuals too small for typical future items
    let dead = (pr_norm * (1.0 - pr_norm)).powi(2);
    score -= 25.0 * dead * progress;

    // Last-chance bin bonus (avoid opening new bin)
    if fitting_bins_count == 1 {
        score -= 45.0 * (0.5 + progress);
    }

    // Prefer bins whose residual is close to mean residual (balance)
    let dev = (pr - mean_residual) / cap;
    score += 12.0 * dev * dev * cap;

    // Lookahead: reward if next item fits post-residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let slack = (pr - ns) / cap;
            score -= 20.0 * (1.0 - slack) * (0.4 + 0.6 * progress);
        } else {
            score += 15.0 * ((ns - pr) / cap);
        }
    }

    // New-bin candidate: prefer opening new bin early, or when fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = (pr_norm - 0.0).max(0.0);
        score = 55.0 + 60.0 * (1.0 - progress) - 30.0 * (1.0 - tight);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (small multiples of common item sizes) are rewarded.
    let cap = bin_capacity as f64;

    // Reward tight fits (small post_residual) super-linearly.
    if post_residual == 0 {
        score -= 25.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    }

    // Modulo logic: post_residual divisible by common small sizes (10, 20, 25)
    // is "reusable" dead space; penalize odd/awkward residues.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 3.0;
        } else if pr % 5 == 0 {
            score -= 1.0;
        } else {
            score += 2.5; // awkward residue
        }
    }

    // Lookahead harmonic coupling: if next item exactly fills this bin's
    // post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr && (pr - next_item_size) % 10 == 0 {
            score -= 8.0;
        } else if next_item_size > pr {
            score += 1.0; // next item can't use this leftover anyway
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.05 * open_bins_count as f64;
    } else {
        // Prefer fullest bins (harmonic fraction of capacity used).
        let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
        score -= 10.0 * fill_frac;
    }

    // Late in stream, be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // Prefer bins below mean residual (keeps residual spread tight).
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Strict dead-space avoidance: gaps that are too small for any future item
    // (items >= 1, but realistically small gaps < ~10 are near-dead) are heavily penalized.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post) * 4.0;
    }
    // Gaps too small for the lookahead item are risky if it's a last-chance bin.
    let next = next_item_size as f64;
    if next > 0.0 && post > 0.0 && post < next {
        score += (next - post) * 1.5;
    }

    // Reward tight fits (item consumes most of the residual).
    let fill_ratio = item / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    // Perfect fit bonus.
    if post == 0.0 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins
    // over opening new ones; make the empty-bin candidate less attractive.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        score += 10.0 + pressure * 2.0;
    } else {
        score -= pressure * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Mild alignment with mean residual: prefer bins whose residual is below
    // average (they are the "fuller" ones, consolidating space).
    score += (mean_residual - post) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item,
    // scaled by how snugly the next item would fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 35.0 - slack * 0.35; // tight follow-up fit rewarded, loose fit less so
        if slack == 0.0 {
            score -= 25.0; // chain of perfect fits
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space penalty: residual too small for the next item.
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score += waste_ratio * 45.0;
    }

    // Compare post_residual against mean residual: prefer bins that end below average
    // (concentrating waste into fewer bins).
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        score += 40.0 + crowding * 5.0 - progress * 10.0;
        // Allow a new bin if the item is large and no tight fit exists elsewhere.
        if item_size >= bin_capacity * 3 / 4 && fitting_bins_count <= 2 {
            score -= 35.0;
        }
    }

    // Mild preference for filling fuller bins first.
    score += (1.0 - bin_residual as f64 / bin_capacity as f64) * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Tightness: fraction of bin filled by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill * fill;

    // Penalize large dead space relative to typical future item sizes.
    score += 0.35 * post_residual as f64 * (1.0 - fill);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // Mild reward when several bins compete; keep selection discriminative.
        score += 2.0 * fitting_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 30.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here anyway; slight penalty for wasting space.
            score += 5.0;
        }
    }

    // Time horizon: early in the stream, be conservative (favor filling existing bins);
    // late in the stream, prioritize tight fits even more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.25 * progress;

    // Global state: many open bins with high mean residual -> discourage spreading.
    if open_bins_count > 2 {
        let spread = (mean_residual - post_residual as f64).abs();
        score += 0.10 * spread;
        score += 0.5 * open_bins_count as f64;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted early in the stream.
        let discount = 1.0 - 0.4 * (1.0 - progress);
        score += 150.0 * discount;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin anyway
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 25.0; // roomy bin useful for upcoming large item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;
    let dead = pr / cap;

    // Base: prefer low post-residual, with non-linear polynomial coupling to stream progress.
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Penalize unusable dead space quadratically; dead space matters more later in the stream.
    score += 30.0 * dead * dead * (0.5 + progress);

    // Reward tight fits (high fill ratio) with smooth saturation.
    score -= 12.0 * fit_ratio * fit_ratio * (1.0 - fit_ratio + 0.25);

    // Lookahead coupling: if next item fits the post residual, reward; else penalize smoothly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fits_next = if pr >= n { 1.0 } else { 0.0 };
        let gap = (n - pr).abs() / cap;
        score -= 8.0 * fits_next * (1.0 - gap);
        score += 6.0 * (1.0 - fits_next) * gap * gap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild pressure against accumulating many open bins with scattered residuals.
    score += 0.15 * (open_bins_count as f64).powi(2) * dead * progress;

    // Align with mean residual state: bins far below mean residual are attractive targets.
    score -= 0.05 * (mean_residual - pr) * (mean_residual - pr).signum();

    // New-bin candidate: empty bin gets a smooth penalty so it only wins when fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * (1.0 - progress) - 15.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which quarter / eighth of capacity it lands in.
    let quarter = bin_capacity / 4;               // 25
    let eighth = bin_capacity / 8;                // 12
    let class = post_residual / quarter;          // 0..4 harmonic class

    // Reward tight fits: lower post_residual classes are better.
    score -= match class {
        0 => 18.0,                       // nearly perfect fit
        1 => 8.0,                        // good fit
        2 => 0.0,                        // neutral
        _ => 6.0,                        // wasteful large residual
    };

    // Exact-fill bonus (dead space zero is ideal).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty for residuals too small to ever be useful:
    // residuals in (0, 10) can only fit tiny items -> strongly penalize.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Modulo arithmetic on post_residual: residuals congruent to small multiples
    // of the eighth are "reusable" classes (likely to fit future items).
    let m = post_residual % eighth;
    if post_residual > 0 && m >= 0 && m <= 2 {
        score -= 5.0;                    // near-multiple residual: reusable
    } else if m >= eighth - 3 {
        score += 4.0;                    // awkward residual class
    }

    // Lookahead coupling: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;               // perfect chain
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 10.0 - (slack as f64).min(10.0); // next item fits: reward
        } else {
            // Next item does not fit here; penalize proportionally to waste.
            score += 6.0;
        }
        // Harmonic division threshold: next_item_size / post_residual integer part
        let div = next_item_size / (post_residual.max(1));
        if div == 0 {
            score -= 3.0;                // next item smaller than residual
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a mild baseline so it wins only
    // when open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Spread-awareness: if this bin is far from the mean residual, it's an outlier;
    // prefer bins that bring residuals toward balance.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild penalty for too many open bins: consolidation pressure.
    score += 0.3 * open_bins_count as f64;

    // Small tie-break on larger items going into larger-residual bins.
    score += 0.02 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small leftover gaps that are
    // hard to fill later (below the smallest plausible item size ~10).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space penalty
    }

    // Reward exact / near-exact fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins rather than spawning new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.4 * (0.5 + 0.5 * progress);

    // Pull toward the mean residual: prefer bins that are neither
    // outliers (nearly empty) nor almost full unless fit is tight.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 20.0; // would create dead space after next item
        }
    }

    // New-bin candidate: neutral-ish baseline so it's chosen only when
    // open bins offer poor fits (their scores get penalties above).
    if bin_residual == bin_capacity {
        score = post_residual as f64 + 10.0 + 0.5 * open_bins_count as f64;
        // Make new bin attractive if all fits are bad (dead-space prone).
        if post_residual == bin_capacity - item_size && (bin_capacity - item_size) < 10 {
            score -= 20.0;
        }
        return score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: strongly reward when the next item
    // exactly matches the post_residual (chained perfect fit).
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as u32) == next_item_size {
            score -= 500.0;
        } else {
            // Penalize post_residuals that are too small for the next item
            // (dead space for the lookahead) but reward close-but-larger gaps.
            let gap = (post_residual as f64 - next).abs();
            score += 0.5 * gap;
            if post_residual < next_item_size {
                score += 80.0; // next item cannot use this bin's leftover
            }
        }
    }

    // Reward bins tighter than the mean residual (best-fit flavor),
    // penalize bins with excessive leftover relative to mean.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (large dead space).
    if fitting_bins_count == 1 {
        score -= 60.0;
        score += 0.4 * post_residual as f64; // still discourage big leftovers
    }

    // New-bin candidate: penalize opening a new bin when a decent fit exists,
    // but allow it when the best fit would leave a huge dead space.
    if bin_residual == bin_capacity {
        score += 120.0;
        score -= 0.2 * mean_residual;
    }

    // Early in the stream: allow more bins to be opened to keep flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * (1.0 - progress);

    // Mild penalty for many open bins (consolidation pressure).
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space that can't fit typical small items.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small but usable sliver is fine
    } else if post_residual >= 10 && post_residual < 20 {
        score += 0.0;
    } else if post_residual >= 20 && post_residual < 35 {
        score += 6.0; // awkward mid gap
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Prefer filling existing bins over opening new ones as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or early in stream.
        score += 15.0 + 10.0 * (1.0 - progress) + (open_bins_count as f64).sqrt() * 2.0;
        // But if existing fit is terrible and next item is large, allow new bin.
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size / 2 {
            score -= 10.0;
        }
    } else {
        score -= 2.0 * progress * (mean_residual / bin_capacity as f64);
    }

    // Global state: many open bins with high mean residual -> encourage consolidating into existing bins.
    if open_bins_count > 3 && mean_residual > 30.0 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild preference for bins with residual close to item_size (near-exact fit).
    let gap = (bin_residual as i64 - item_size as i64).abs() as f64;
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = pr / cap; // normalized post residual
    let mut score = pr as f64;
    // smooth non-linear coupling of post residual with stream progress
    score += 12.0 * x * x * (1.0 - progress) * progress;
    score -= 8.0 * x * x * x * progress;
    // penalize tight fits slightly more early, less late (dead space risk)
    score += 6.0 * (1.0 - x) * (1.0 - x) * (0.3 + 0.7 * progress);
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // lookahead: reward residual that can fit next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 5.0 * (pr - nx) / cap;
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }
    // prefer bins below mean residual (balance)
    score += 0.5 * (mean_residual - pr) / cap;
    // new-bin candidate: mild penalty so open bins preferred unless very poor fit
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in low-divisibility classes
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;
    let small = post_residual.min(bin_capacity - post_residual) as i64;
    // gcd-style harmonic measure via Euclid on (post_residual, capacity)
    let mut a = post_residual.max(1);
    let mut b = bin_capacity;
    while b != 0 { let t = a % b; a = b; b = t; }
    let g = a as f64;
    let harmonicity = g / (post_residual as f64).max(1.0); // high when post_residual divides capacity well
    score -= 12.0 * harmonicity;

    // Penalize small unusable dead space strongly (non-linear)
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Next-item lookahead: harmonic class of (post_residual mod next_item_size)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fits_next = post_residual >= next_item_size;
        if fits_next {
            // reward if post_residual is a near multiple of next_item_size (chain packing)
            let rem = (pr % next_item_size as i64) as f64;
            score -= 20.0 * (1.0 - rem / n);
            // reward leaving room exactly for next item
            if post_residual == next_item_size {
                score -= 150.0;
            }
            // reward post_residual - next_item_size being small (tight chain)
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / cap as f64);
        } else {
            // next item cannot fit here: penalize proportional to gap
            score += 8.0 + 0.5 * (next_item_size - post_residual) as f64;
        }
        // integer division threshold: post_residual / next_item_size classes
        let k = pr / next_item_size.max(1) as i64;
        if k >= 2 {
            score -= 10.0 * (k as f64).min(4.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when current item is huge relative to mean residual
    let is_new = bin_residual == bin_capacity;
    if is_new {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = (mean_residual < item_size as f64 * 1.1) as i32 as f64;
        score = cap as f64 - 180.0 * tight - 60.0 * progress + (bin_capacity - item_size) as f64 * 0.3;
        // discourage hoarding new bins when many are open
        score += open_bins_count as f64 * 4.0;
        if post_residual == 0 { score -= 400.0; } // exact fit in fresh bin
    }

    // Mild preference for tighter existing fits overall
    score += 0.05 * (bin_residual as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the smallest plausible item (1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Harsh penalty for medium-small gaps that are hard to fill (10..=20)
    if post_residual >= 10 && post_residual <= 20 {
        score += 25.0;
    }

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item exactly
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance pressure: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: discourage opening new bins when many bins are open
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Mild preference for tighter bins relative to mean residual
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Progression: slightly stronger dead-space aversion late in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight by item size so big items
    // consuming residual are rewarded more.
    score += 0.35 * item_size as f64;

    // Aggressive 2-step lookahead: reward when next item exactly matches
    // the post residual (perfect chaining).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 2.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Penalize if next item cannot fit in the post residual (chain broken).
        if post_residual < next_item_size {
            score += 0.5 * next_item_size as f64;
        }
    }

    // Relative to mean residual: avoid bins far from the average state
    // unless it's a tight fit.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // New-bin candidate: penalize opening a new bin, especially late in the stream,
    // unless the item is huge and would leave a very small residual elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste_elsewhere = (bin_residual - item_size) as f64;
        let mut new_bin_score = 20.0 + 30.0 * progress;
        if waste_elsewhere < 10.0 {
            new_bin_score -= 15.0; // huge item: new bin is fine
        }
        score += new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post residual that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly in post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item won't fit here: penalize leaving medium gaps
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global pressure: many open bins with large mean residual -> prefer consolidating
    // into bins below mean residual (filling emptier bins less, tighter bins more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.15 * residual_gap * (0.5 + progress);

    // Late in the stream, be more conservative: avoid opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus scaling with how well existing bins fit.
        let mut new_bin_cost = 45.0;
        if fitting_bins_count == 0 {
            new_bin_cost -= 50.0; // no alternative, must open
        }
        new_bin_cost -= 20.0 * progress; // cheaper to open later? no: penalize more early
        score += new_bin_cost;
    }

    // Prefer bins whose residual is close to item size (best-fit flavor).
    score += 0.05 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    let mut score = post;

    // smooth polynomial coupling of post_residual with progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = post * (1.0 + 0.9 * p2 + 0.6 * p3);
    score += 0.25 * coupling;

    // reward tight fits, more strongly late in the stream
    let tight = (cap - post) / cap;
    score -= 12.0 * tight * (0.5 + progress);

    // lookahead: penalize post_residual that can't fit next item
    if nxt > 0.0 {
        let gap = (post - nxt).abs();
        score += 0.15 * gap * (1.0 + progress);
        if post >= nxt && nxt > 0.0 {
            score -= 3.0 * (nxt / cap) * (1.0 - progress);
        }
    }

    // dead-space penalty grows with progress
    score += 0.05 * post * post / cap * (0.3 + p2);

    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 + progress);
    }

    // mild penalty relative to mean residual to spread load
    score += 0.1 * (mean_residual - post).abs() * (1.0 - progress);

    // discourage opening new bins when many are open and progress is low
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits and small remainders are prized.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Modulo-10 classes: remainders that pair with common item sizes (10,20,...) are reusable.
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 40.0;
    } else if mod10 == 5 {
        score -= 15.0;
    } else {
        score += (mod10 as f64) * 2.0;
    }

    // Integer-division thresholds: how many "typical" small items (size 10) still fit.
    let fits_small = post_residual / 10;
    score -= fits_small as f64 * 6.0;

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 80.0 - gap.min(80) as f64;
        } else {
            // next item cannot fit here; penalize wasting residual it can't use
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Dead-space penalty: residuals below the minimum useful size (10) are dead.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bins early (more future to amortize), penalize when good fits exist.
        let good_fit_exists = post_residual as f64 <= mean_residual && fitting_bins_count > 0;
        score += if good_fit_exists { 150.0 } else { -80.0 * (1.0 - progress) };
        score += open_bins_count as f64 * 4.0;
    } else {
        // Mild preference for tighter bins relative to the mean residual.
        score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;
    }

    // Large items deserve tight packing now.
    if item_size > 60 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (< 10) are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual == 0 {
        // Perfect fill is ideal.
        score -= 40.0;
    }

    // Reward tight fits (waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferation of many open bins.
    score += 2.0 * open_bins_count as f64;

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    if next_item_size > post_residual && next_item_size > 0 {
        // Post residual can't host next item: mild penalty scaled by gap.
        score += 0.2 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64)).abs().min(20.0);
    }

    // New-bin candidate: make it attractive only when existing fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 0 && post_residual < 10;
        if poor_fit || fit_ratio < 0.5 {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    // Late in the stream: consolidate, avoid leaving scattered small gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Slight preference for bins below mean residual (balance residuals).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: prefer tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward if next item fits into post_residual (chain packing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // dead space that next item cannot use
            score += 0.15 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Relative to mean residual: avoid bins much emptier than average (waste)
    score += 0.4 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last chance bin before opening a new bin: strongly favor
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // fresh bin still useful for next item chain
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on leftover space
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 60.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        // Dead space too small for any item (min size 1, but small chunks are weak)
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 150.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item can still fit here; mildly reward
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // placing here makes bin useless for the next item; penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Penalize placing into bins with large residuals when many alternatives exist
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.2;
    }

    // Time horizon: early in stream, be picky (save space); late, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 40.0;

    // Many open bins: encourage closing them out (prefer fuller bins)
    score += open_bins_count as f64 * (bin_capacity - bin_residual) as f64 * 0.005;

    // New-bin candidate handling: only attractive when item is large relative to
    // typical residuals or existing fits are poor
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Opening a new bin is good for big items when mean residual is low
        let pressure = mean_residual / bin_capacity as f64;
        score = 100.0 + (1.0 - item_frac) * 150.0 - pressure * 80.0 + progress * 30.0;
        if fitting_bins_count == 1 {
            score += 250.0; // don't open a new bin when a last-chance bin exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let mut score = pr as f64;
    // Smooth polynomial coupling of post_residual with stream progress
    let poly = 1.0 + 0.8 * progress - 1.6 * progress * progress + 1.8 * progress * progress * progress;
    score += 40.0 * norm_post * norm_post * poly;
    // Reward tight fits more strongly as stream progresses
    score -= 25.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + progress);
    // Penalize dead space relative to mean residual (non-linear)
    let dead = (pr - mean_residual).max(0.0) / cap;
    score += 30.0 * dead * dead;
    // Lookahead: reward if next item fits smoothly into resulting post_residual
    if next_item_size > 0 {
        let nx = (next_item_size as f64).min(cap);
        let gap = (pr - nx).abs() / cap;
        score -= 20.0 * (1.0 - gap) * (1.0 - gap) * (1.0 - progress);
        score += 15.0 * gap * gap * (0.5 + progress);
    }
    // Last-chance bonus: smooth sigmoid-like weight on fitting_bins_count
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0) * (fitting_bins_count as f64 - 1.0));
    score -= 35.0 * last_chance * (0.4 + progress);
    // Mild penalty for bin proliferation
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);
    // New-bin candidate: penalize unless residual waste would be large elsewhere
    if bin_residual == bin_capacity {
        score += 10.0 - 20.0 * norm_post * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) should be preferred.
    let cap = bin_capacity as f64;

    // Reward small post_residual (tight fit).
    score -= (1.0 - post_residual as f64 / cap) * 8.0;

    // Harmonic bonus: post_residual divisible by common size classes (10,20,25,50).
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 2.5; }
        if post_residual % 20 == 0 { score -= 2.0; }
        if post_residual % 50 == 0 { score -= 3.5; }
    } else {
        // Perfect fill is ideal.
        score -= 15.0;
    }

    // Penalize dead space: post_residual too small for any plausible item (1..100 range,
    // min item is small, but very tiny leftovers under ~10 are near-dead).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 10.0;
        } else if next_item_size <= post_residual {
            // Harmonic class of (post_residual - next_item_size)
            let r = post_residual - next_item_size;
            if r % 10 == 0 { score -= 4.0; }
            if r % 25 == 0 { score -= 2.0; }
            score -= 1.5; // next item fits: keep this bin attractive
        } else {
            // Next item won't fit here: mild penalty, this bin becomes dead-end-ish.
            score += 2.0;
        }
    } else {
        // Last item: prefer zero-waste.
        score -= post_residual as f64 * 0.1;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // When many bins are open, prefer consolidating into tightest fits;
    // when few are open, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
    score += open_pressure * 0.15 * (1.0 - progress);

    // New-bin candidate (empty bin): penalize slightly so we only open new bins
    // when existing fits are genuinely poor.
    if bin_residual == bin_capacity {
        score += 5.0 + mean_residual * 0.02;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin.
        score -= 60.0;
    }

    // Non-linear penalty on post_residual relative to capacity: prefer bins
    // that are filled to a high fraction, but only when the leftover is large
    // enough to remain usable.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * frac * frac;

    // Reward using bins that are already quite full (residual close to item).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> favor existing bins, discourage new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and mean residual.
        score += 25.0 + pressure;
        if mean_residual > item_size as f64 {
            score += 15.0; // existing slack exists; don't open a new bin
        }
    } else {
        score -= pressure * 0.2;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // Post residual too small for next item but still usable generally: mild penalty.
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.04;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual too small to hold typical future items.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 {
        score += 12.0 * (1.0 - t);
    } else if post_residual <= 20 {
        score -= 4.0 * (1.0 - t);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, bonus.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        score -= 8.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && (post_residual as u32) > 0 {
        // Penalize blocking the next item slightly, scaled by how close it is.
        let gap = (next_item_size as i64 - post_residual as i64).abs() as f64;
        score += 0.08 * gap;
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins.
    let pressure = mean_residual / bin_capacity as f64;
    score -= 6.0 * pressure * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate handling: empty bin gets a baseline penalty unless current bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = pressure * (open_bins_count as f64).sqrt();
        score += 20.0 - 14.0 * fragmentation.min(1.2);
        // Late in stream, opening a fresh bin for large items is fine.
        score -= 6.0 * t;
    }

    // Mild preference for bins whose residual is close to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.03 * dev;

    // Slight time decay of tightness reward to stay adaptive across the stream.
    score *= 1.0 - 0.05 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * pr_norm) - 0.35 * progress * pr_norm * (1.0 - pr_norm) * cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 + 0.8 * progress) * 8.0;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + progress);
        } else {
            score -= 0.25 * progress;
        }
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Mild pressure from many open bins
    score += 0.15 * open_bins_count as f64 * pr_norm;

    // Deviation from mean residual: prefer bins near the mean (balanced usage)
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline, slightly high so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += cap * (0.9 + 0.3 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit residue classes are golden.
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0; // perfect fit, always reward strongly
    } else {
        // Modulo-10 class: residues near 0 are more reusable for items 1..100.
        let m10 = pr % 10;
        let class_bonus: f64 = match m10 {
            0 => 40.0,
            1 | 9 => 25.0,
            2 | 8 => 15.0,
            3 | 7 => 8.0,
            _ => 0.0,
        };
        score -= class_bonus;

        // Small post_residual is dead space: penalize tiny nonzero leftovers.
        if pr < 10 {
            score += (10 - pr) as f64 * 6.0;
        }
    }

    // Integer-division thresholds: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Lookahead fits: reward, more so for large next items (tight pairing).
            let fit_ratio = next_item_size as f64 / pr as f64;
            score -= 30.0 + 60.0 * fit_ratio;
            // Harmonic pairing: next item exactly consumes remaining space
            if next_item_size == pr {
                score -= 250.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to wasted pairing chance.
            score += (next_item_size - pr) as f64 * 0.8;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 220.0;
    }

    // Prefer filling bins that are already well loaded (low residual relative to capacity).
    let load_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 80.0 * load_frac;

    // Harmonic capacity-fraction classes: bins whose residual matches common item
    // sizes (10..80 in steps of 5) are more likely to be closed cleanly.
    let res = bin_residual;
    if res >= 10 && res <= 80 && res % 5 == 0 {
        score -= 12.0;
    }

    // Mild penalty for opening new bins when many bins are already open and
    // stream is late (consolidation pressure grows over time).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (60.0 + 120.0 * progress + 15.0 * open_bins_count as f64);

    // Deviation from mean residual: prefer bins below average residual (fuller bins).
    score -= (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit
    // typical items (below the minimum item size) are pure waste.
    if post_residual < 10 {
        score += 60.0; // unusable sliver -> heavily penalize
    } else if post_residual <= 20 {
        // small gap: only useful if the lookahead item can use it
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 25.0; // lookahead fits exactly into this gap
        } else {
            score += 15.0;
        }
    } else {
        // larger gap: reward proportionally to how well next item fits
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 12.0;
        }
    }

    // Reward tight packing: fraction of bin filled by this item
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_frac;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out.
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += 3.0 * open_pressure;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins
    // have poor fits (high mean residual relative to item).
    if bin_residual == bin_capacity {
        let spread_need = (mean_residual - item_size as f64).abs();
        score += 30.0 - 0.3 * spread_need;
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Slight preference for bins whose residual is close to item size
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post-residual,
    // this is a perfect chain placement — reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 10 {
            score -= 150.0;
        }
        // Penalize leaving a residual that is almost-but-not-quite the next item
        // (dead space trap).
        if next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 60.0;
        }
    }

    // Compare against mean residual: bins with less residual than average are
    // "tighter" — placing there consolidates waste.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.5;
    } else {
        score += (res - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin when existing bins could fit reasonably well.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if the item is large relative to capacity and next item is also large,
        // a fresh bin is fine (pairing large items together).
        if item_size >= 50 && next_item_size >= 50 {
            score -= 100.0;
        }
    }

    // Late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted space quadratically relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Lookahead: reward bins whose post-residual can host the next item (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_tightness = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 25.0 * (1.0 - chain_tightness);
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Next item fits this bin only before we consume space — slight penalty for blocking.
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global pressure: when few fitting bins exist, avoid opening new bins unnecessarily.
    if fitting_bins_count <= 2 && bin_residual < bin_capacity {
        score -= 10.0 / fitting_bins_count as f64;
    }

    // Mean residual coupling: bins far below mean residual are "fresher";
    // prefer filling stale (low-residual) bins to consolidate.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Time horizon: early in the stream, be more liberal with opening bins
    // (keep flexibility); late in the stream, pack densely into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if it offers room for lookahead chains
        // or the item is large and no good fit exists.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 8.0 * (1.0 - progress);
        } else {
            score += 15.0 + 20.0 * progress;
        }
        // Penalize new bins when many bins are already open (consolidation pressure).
        score += 0.5 * open_bins_count as f64;
    }

    // Small residual dead-space penalty: residuals below typical item sizes are useless.
    if post_residual < 10 {
        score -= 12.0; // perfect fill is excellent
    } else if post_residual < 20 {
        score += 8.0; // awkward sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space quadratically (dead space grows costly).
    let mut score = norm_pr * norm_pr * 120.0 + norm_pr * 20.0;

    // Smooth non-linear coupling with stream progress: waste is penalized
    // more aggressively later in the stream (consolidation pressure).
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward near-perfect fits (small post_residual) super-linearly.
    if norm_pr < 0.15 {
        score -= (0.15 - norm_pr) * (0.15 - norm_pr) * 150.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + 40.0 * progress;
    }

    // Many fitting bins: this bin is not scarce; slight penalty to prefer tighter alternatives.
    if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead: if the next item could use this bin's post_residual, reward leaving useful space.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr as f64 {
            // Next item fits exactly into the resulting space -> smooth reward.
            let gap = (pr - ns) as f64 / cap;
            score -= 30.0 * (-gap * 20.0);
        } else {
            // Post-residual too small for next item: penalize proportionally to uselessness.
            let useless = (ns - pr as f64) / cap;
            score += 25.0 * useless * useless;
        }
    }

    // Interaction with mean residual: prefer bins whose residual deviates from
    // the mean in a way that reduces dispersion (balance-seeking term).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity && bin_residual == post_residual + item_size;
    if is_new_bin {
        // Penalize opening a new bin; overcome it only if the best existing fit is terrible.
        score += 45.0 + 30.0 * progress;
        // But if this bin is the ONLY fitting option, the last-chance reward above
        // on real bins dominates; soften new-bin penalty when many bins are open.
        score -= 10.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: divide capacity into 5 fractions
    let class = (post_residual * 5) / bin_capacity; // 0..4
    let class_bonus = match class {
        0 => 0.0,               // perfect fit class
        1 => -6.0,              // small residue, good
        2 => 2.0,               // medium residue
        3 => 5.0,               // large-ish residue
        _ => 8.0,               // nearly empty bin used wastefully
    };
    score -= class_bonus;

    // Dead-space penalty: residue that no typical item (>=1) can pair with
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward tight fits strongly
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // reward proportionally how well next item fills the residue
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * fill;
    } else if next_item_size > post_residual && post_residual > 0 {
        // residue too small for next item: penalize proportional dead space
        score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly unless all open bins are poor fits
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_open_fill = 1.0 - mean_residual / cap;
        // open new bin when existing bins are well packed or few fit
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            (fitting_bins_count as f64).ln() * 4.0
        };
        score += 25.0 + pressure - 10.0 * avg_open_fill - 5.0 * progress;
    }

    // Modulo harmonic coupling: residue near multiples of common item sizes
    let m = post_residual % 20;
    if m == 0 && post_residual > 0 {
        score -= 4.0; // residue divisible into typical chunks
    } else if m >= 17 {
        score += 3.0; // awkward residue just above a chunk boundary
    }

    // Prefer filling bins with high residual when many bins are open (consolidation)
    score += (open_bins_count as f64).sqrt() * (post_residual as f64 / cap) * 3.0;

    // Slight preference for bins below mean residual (balance packing)
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: a leftover gap that the next item cannot use
    // is wasted capacity. Penalize it proportionally to how "unusable" it is.
    if next_item_size > 0 && post_residual > 0 {
        if (post_residual as u64) < (next_item_size as u64) {
            // Gap too small for the next item: strong penalty, worse when very small.
            let gap = post_residual as f64;
            score += (1.0 - gap / (next_item_size as f64)) * 40.0;
        } else {
            // Gap usable by next item: reward leaving exactly the right space.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / (bin_capacity as f64)).min(1.0);
        }
    }

    // Reward tight fits (small absolute post residual) super-linearly.
    let pr = post_residual as f64;
    score -= ((bin_capacity as f64 - pr) / bin_capacity as f64).powi(3) * 25.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (which increases open_bins_count).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many
    // are already open; encourage consolidation instead.
    score += (open_bins_count as f64) * 1.5;

    // Mild global pressure: if mean residual across open bins is high, prefer
    // filling existing bins rather than spreading.
    score += mean_residual * 0.15;

    // Slight late-stream tightening: as the stream progresses, be more
    // conservative about dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr * 0.3 * progress;

    // New-bin candidate (bin_residual == bin_capacity): apply a fixed opening
    // cost so it is only chosen when all fits are genuinely terrible.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Strong reward if the next item exactly fills the post-residual (2-step lookahead)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item uses the leftover
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill_ratio;
        } else {
            // next item cannot fit here; penalize leaving a gap next item could waste
            let gap = next_item_size - post_residual;
            score += 0.15 * gap as f64;
        }
        // Bonus if post_residual can hold next item AND another open bin also fits next item
        if next_item_size <= post_residual && next_item_size <= mean_residual as u32 {
            score -= 3.0;
        }
    } else {
        // Last item: minimize waste entirely
        score = post_residual as f64 * 2.0;
    }

    // Penalize creating dead space that is too small for typical items (1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Last-chance bin: strong incentive to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible
    if bin_residual == bin_capacity {
        score += 12.0 + 0.05 * open_bins_count as f64;
        // but if lookahead chains well into a fresh bin, soften
        if next_item_size > 0 && next_item_size as f64 >= post_residual as f64 {
            score -= 6.0;
        }
    }

    // Prefer bins below mean residual (consolidating emptier bins) mildly
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Late in stream: be greedier about tight fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize small-but-unusable dead space (< 10) harder than exact fits.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            // exact chain fit bonus
            if post_residual == next_item_size {
                score -= 12.0;
            }
        } else if next_item_size > post_residual && post_residual > 0 {
            // next item won't fit here: penalize leaving awkward gap
            score += 6.0 * (next_item_size as f64 - post_residual as f64).min(20.0) / 20.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Many open bins: discourage spreading, prefer consolidation.
    score += 0.35 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins that reduce dispersion.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Time horizon: late in the stream, be more conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    // New-bin candidate: penalize unless current bin fits are all poor.
    if bin_residual == bin_capacity {
        let poor_fits = fitting_bins_count == 0
            || (fitting_bins_count == 1 && post_residual > 0 && post_residual < 15);
        score = if poor_fits { 5.0 } else { score + 45.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Base: prefer tight fits (small post_residual), with quadratic shaping.
    let mut score = pr + (pr / cap) * (pr / cap) * 30.0;

    // Smooth non-linear coupling with stream progress: early on, tolerate slack
    // (future items can fill it); late, penalize residual more aggressively.
    let progress_coupling = pr * (0.5 + 1.5 * progress * progress);
    score += progress_coupling;

    // Dead-space penalty: residuals too small for the smallest plausible item.
    let dead = if (post_residual as f64) < mean_residual * 0.5 { 1.0 } else { 0.0 };
    score += dead * pr * 0.5;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 - pr).max(0.0) / cap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 20.0 * (1.0 - pr / cap);
    }

    // Mild penalty for proliferating open bins relative to stream progress.
    score += open_bins_count as f64 * progress * 0.5;

    // New-bin candidate: make it attractive only for large items / bad fits.
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress - item_size as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) and near-perfect fits
    // (small residues divisible by common item sizes) are highly desirable.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit: best possible outcome
    } else {
        // Penalize dead space non-linearly; small residues are fine.
        let dead = pr as f64;
        score += 0.5 * (dead / 10.0).powi(2);
        // Reward residues that are "harmonic": divisible by small item sizes
        // (likely future item magnitudes), making the space reusable.
        let harmonic = [10u32, 20, 25, 50]
            .iter()
            .any(|&d| pr % d == 0);
        if harmonic {
            score -= 30.0;
        }
        // Very small unusable residues (1..=9) are dead space: penalize hard.
        if pr < 10 {
            score += 60.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when the item is large relative to
    // capacity or no good fit exists; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Large items early, or many already-open bins: prefer new bin.
        if fill_frac > 0.5 {
            score -= 80.0 * fill_frac;
        } else {
            score += 120.0 - 100.0 * fill_frac;
        }
        if open_bins_count > 8 {
            score -= 40.0;
        }
        if progress > 0.9 {
            score -= 20.0;
        }
        // Lookahead: if next item is small, an open bin with room is better.
        if next_item_size > 0 && next_item_size <= 20 {
            score += 50.0;
        }
    }

    // Lookahead synergy: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            // Next item won't fit here: mild penalty proportional to gap.
            score += 10.0;
        }
    }

    // Prefer bins with residual below mean (tighter bins) to consolidate.
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for bins whose residual is an exact multiple class
    // of the item size (harmonic packing).
    if bin_residual % item_size.max(1) == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    let min_item = 1u32;
    let dead_threshold = 12u32; // gaps below typical minimum item size are dead
    if post_residual > 0 && post_residual < dead_threshold {
        score += 200.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 150.0;
    }

    // Reward tight fits generally (low post_residual relative to item size).
    let tightness = item_size as f64 / (item_size + post_residual).max(1) as f64;
    score -= 40.0 * tightness;

    // Lookahead coupling: if next item fits in the resulting gap, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5 * next_item_size as f64;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Gap too small for the next item: mild extra penalty.
        score += 15.0;
    }

    // Open-bin pressure: prefer reusing bins when many are open.
    score += 0.8 * open_bins_count as f64;
    // Mean-residual coupling: penalize bins far from the mean residual (avoid fragmentation).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate handling: penalize opening a new bin when existing bins fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Only open a new bin if all fits would be terrible (huge dead space).
            score += 120.0;
        } else {
            score -= 50.0; // no alternative: new bin is fine
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Slight stream-progression tilt: tighten behavior over time.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when the next item fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can be placed here: strong reward, scaled by how well it fills.
            let fill_next = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill_next;
        } else {
            // Post residual is dead space for the next item: penalize proportionally.
            score += 0.6 * post_residual as f64;
        }
    }

    // Compare post_residual against mean residual: avoid leaving bins far below average.
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins are poor fits.
    if bin_residual == bin_capacity {
        score += 55.0;
        // If lookahead says next item pairs well with a fresh bin, soften penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    // Late in the stream: prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 35.0 * tightness * tightness;

    // Penalize dead space: residuals too small for any plausible future item
    // (items can be as small as 1, but small slivers are still wasteful).
    if post_residual > 0 && post_residual < 12 {
        score += 28.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 45.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: penalize placing here if the next item could also have used
    // this residual, unless the fit is very tight anyway.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits in leftover space: mildly good, keep residual usable.
            score -= 8.0;
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // We consumed residual the next item needed; penalize proportionally.
            score += 12.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
    }

    // Fragmentation pressure: penalize leaving residual far from mean residual
    // when bin is an outlier (encourage balancing residuals across bins).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: late in the stream, prefer tighter packing (consolidate),
    // early on allow opening bins more freely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 6.0;

    // New-bin candidate handling: empty bin gets a moderate baseline so it only
    // wins when all open bins are poor fits.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Late in the stream, opening new bins is more acceptable (avoid
        // cramming into bad fits when plenty of stream remains).
        score -= 20.0 * progress;
        // If many bins are open, slightly discourage yet another one.
        score += 0.4 * open_bins_count as f64;
        // If the next item is large and this item is small, reserving a fresh
        // bin may be wasteful; penalize.
        if next_item_size > item_size + 30 {
            score += 10.0;
        }
    }

    // Mild penalty for very full bins being over-favored when many bins open
    // (encourage spreading when open_bins_count is high and residual large).
    if open_bins_count > 6 && post_residual > 60 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Smooth polynomial coupling of post_residual with progress
    let pn = pr / cap;
    let poly = pn * pn * (1.0 + progress) + pn * (1.0 - progress);

    let mut score = pr + 12.0 * poly;

    // Reward tight fits: subtract more as post_residual shrinks
    score -= (1.0 - pn).powf(2.0) * 20.0;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0 * (1.0 - progress);
    }

    // Lookahead: reward residual that can still hold the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (next_item_size as f64) / cap) * (0.5 + 0.5 * progress);
    } else if next_item_size > 0 {
        // penalize residuals too small for the next item (dead space risk)
        score += 6.0 * (pr / cap) * (1.0 - progress);
    }

    // New-bin candidate: penalize opening bins early, allow later when residuals are fragmented
    if is_new_bin {
        score += 18.0 * (1.0 - progress) + 4.0 * open_bins_count as f64;
        if mean_residual > 0.0 {
            score -= 10.0 * (mean_residual / cap).min(1.0) * progress;
        }
    }

    // Mild preference for bins below mean residual (balance fragmentation)
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near multiples of small
    // sizes are "reusable" dead space; odd, prime-ish residues are waste.
    let r = post_residual;
    let class_bonus: f64 = if r == 0 {
        -40.0 // perfect closure — heavily reward
    } else if r % 10 == 0 {
        -18.0
    } else if r % 5 == 0 {
        -10.0
    } else if r % 2 == 0 {
        -4.0
    } else {
        6.0 // odd residue: harder to fill later
    };
    score += class_bonus;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this bin is a perfect two-step chain — reward strongly.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 35.0;
        } else if next_item_size < r {
            let frac = next_item_size as f64 / r as f64;
            // reward high fill fraction of the remaining space
            score -= 15.0 * frac * frac;
            // harmonic check: does the chain continue? (r - next) still usable
            let r2 = r - next_item_size;
            if r2 % 10 == 0 { score -= 8.0; }
            else if r2 % 5 == 0 { score -= 4.0; }
            else if r2 % 2 == 1 { score += 5.0; }
        } else {
            // next item cannot use this bin's remainder: mild penalty scaled
            // by how much dead space we'd strand
            score += 0.05 * r as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize new-bin competition).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has no stranded space, but
    // opening bins is costly when many are already open with room.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.75
            + 2.0 * open_bins_count as f64
            + 10.0 * (step_index as f64 / (total_items.max(1) as f64));
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // a fresh bin always fits the next item too; slightly soften
            score -= 5.0;
        }
        if fitting_bins_count <= 1 {
            // no real alternative — new bin is fine
            score -= 25.0;
        }
    }

    // Tight fits (small post_residual relative to item) are excellent:
    score -= 12.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Prefer bins already below mean residual fill (balance avoidance of
    // many half-empty bins): penalize picking bins with residual far above mean.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.03 * dev;
    } else {
        score += 0.015 * dev; // slight reward for tighter-than-average bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (items >= 1, but small gaps < 10 are near-worthless)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps in the "awkward" band 10..30 are hard to fill; penalize softly.
    if post_residual >= 10 && post_residual < 30 {
        score += 6.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio;

    // Open-bins pressure: with many open bins, prefer packing into existing
    // bins (penalize new-bin candidate which has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But if no open bin fits well (post_residual of others is large),
        // the base comparison still allows opening a new bin.
        // Slight reward early in the stream to allow bin creation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item can exactly use this bin's post_residual,
    // reward keeping that gap.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    // If next item cannot fit into post_residual but could fit elsewhere,
    // mild penalty for leaving a gap the next item can't use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 3.0;
    }

    // Prefer bins with residuals close to the mean (balance load) mildly.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits; dead space below half capacity is heavily penalized.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly consumes post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / 100.0); // next item still fits: mild reward
        } else {
            // next item won't fit here; penalize proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.3 * over;
        }
    } else {
        // Last item: strongly prefer exact/near-exact closure.
        score += 5.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" —
    // filling them is good; bins far above mean waste capacity if left with dead space.
    let res = post_residual as f64;
    if res > mean_residual + 15.0 {
        score += 0.25 * (res - mean_residual);
    } else if res < mean_residual - 15.0 {
        score -= 0.15 * (mean_residual - res);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let open_bins_pressure = 10.0 * open_bins_count as f64;
        let bad_fit_exists = fitting_bins_count > 0 && (post_residual as f64) < 0.5 * mean_residual;
        if bad_fit_exists {
            score -= 30.0; // open fresh bin instead of wrecking an open one
        } else {
            score += open_bins_pressure; // prefer reusing open bins
        }
    }

    // Slight stream-progression term: early on, be conservative about dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (post_residual as f64) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty (dead space is superlinear in cost)
    let waste = post_residual as f64;
    score += 0.8 * waste * waste / bin_capacity as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 0.5 * next_item_size as f64;
        // Extra reward if next item exactly fills remaining space
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creating space too small for the next item: penalize dead space
        score += 0.6 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer fuller bins relative to the fleet mean residual
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Time horizon: late in the stream, consolidate aggressively (avoid opening new bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when open bins exist
        score += 20.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        // Existing bins get progressively more attractive late in the stream
        score -= 10.0 * progress;
    }

    // Slight preference for bins with larger residuals when many bins are open (balance load)
    score += 0.05 * (open_bins_count as f64) * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: prefer tight fits (low post_residual), with smooth non-linear shaping.
    let mut score = pr;

    // Non-linear waste penalty: dead space grows quadratically for small residuals.
    score += 8.0 * fit_norm * fit_norm * (1.0 - fit_norm);

    // Stream-progress coupling: later in the stream, small residuals matter more
    // (fewer future chances to fill them), so penalize residual more as t -> 1.
    let late = progress * progress;
    score += 20.0 * late * fit_norm;

    // Lookahead coupling: reward if next item can fill this bin's post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            score -= 15.0 * (1.0 - gap / cap);
        } else {
            // Next item can't use leftover: penalize proportionally to mismatch.
            score += 6.0 * ((nxt - pr) / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, mild penalty for wasting space in any one.
        score += 3.0 * ((fitting_bins_count as f64).ln()) * fit_norm;
    }

    // Prefer bins with below-mean residual (filling emptier bins first keeps
    // tight bins available); smooth coupling with mean_residual.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * (0.5 + late);

    // New-bin candidate: make it mildly unattractive unless open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 10.0 + 2.0 * crowding - 30.0 * late * fit_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let quarter = bin_capacity / 4;
    let class = (post_residual / quarter) as f64;
    let rem = (post_residual % quarter) as f64;

    // Reward post-residuals that fall into "usable" harmonic classes
    // class 0: perfectly full (best), class 3: large residual (still flexible)
    match post_residual / quarter {
        0 => { score -= 25.0; }                      // near-perfect fit
        1 => { score -= 8.0 + 0.3 * rem; }           // good fit
        2 => { score += 0.1 * rem; }                 // neutral
        _ => { score += 2.0; }                       // wasteful large leftover
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        // harmonic match: next item aligns with residual class boundary
        if (post_residual - next_item_size) % quarter == 0 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // dead space for the known next item: penalize
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += 0.25 * (mean_residual - bin_residual as f64).max(-20.0).min(20.0);

    // Early stream: be conservative, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    // New-bin candidate: penalize mildly unless current residual is unusable
    if bin_residual == bin_capacity {
        let threshold = 2 * quarter + quarter / 2;
        if post_residual >= threshold {
            score += 30.0; // keep existing bins in play
        } else {
            score += 8.0;
        }
    }

    // Small tie-breaker on open bin count to discourage bin proliferation
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (items >= 1, but tiny gaps < 10 are effectively unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64; // small gaps: worst kind of waste
    }

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward filling most of the bin (post_residual small relative to capacity).
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tight fits;
    // few open bins -> tolerate opening/using bins more freely.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 2.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0; // next item still fits: keep this bin attractive
    } else if next_item_size > post_residual && post_residual < 10 {
        score += 25.0; // dead space AND next item can't use it
    }

    // New-bin candidate handling: empty bin gets neutral base plus slight
    // exploration bonus early, penalty late when consolidation matters.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = (bin_capacity as f64) + 10.0 - 15.0 * progress;
        if fitting_bins_count <= 1 {
            score -= 20.0; // no real alternative: opening a new bin is fine
        }
        if open_bins_count > 20 {
            score += 25.0 * (open_bins_count as f64 / 100.0); // too many bins: discourage
        }
    }

    // Mild stream-progress tightening: later in the stream, waste hurts more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post residual relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: if the next item exactly matches the post residual,
    // strongly reward this placement (perfect chain fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // If next item fits in post residual, mildly reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // If post residual is dead space (next item can't fit and it's small),
    // penalize creating unusable slivers.
    else if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: placing into a bin with residual below mean
    // concentrates filling and keeps larger residuals available.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 5.0;
    }

    // Last chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and no good fit exists (aggressive consolidation).
    if bin_residual == bin_capacity {
        score += 40.0;
        // Allow new bin for large items late in the stream when few bins fit.
        if item_size >= 60 && fitting_bins_count <= 2 {
            score -= 35.0;
        }
    }

    // Slight stream-progression bias: be more conservative early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit is heavily favored.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 30.0;
    }

    // Penalize dead space that no plausible future item can use.
    let t = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 * (1.0 - t);
    }

    // Lookahead coupling: if the next item fits the post-residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.3 * (next_item_size as f64);
    }
    // If post-residual is nonzero but too small for the next item, penalize a bit.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Contextual adjustment via mean residual: prefer bins close to the mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Late in the stream, consolidate: prefer already-open bins over opening new ones.
    score += 10.0 * t;

    // New-bin candidate: make it attractive only when no open bin is a decent fit
    // or when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let fullness = 1.0 - (mean_residual / bin_capacity as f64);
        score = 45.0 - 30.0 * scarcity - 25.0 * fullness - 20.0 * t;
        // Opening a new bin is good if the item + next item pair would fit together.
        if next_item_size > 0 && (item_size + next_item_size) <= bin_capacity {
            score -= 12.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress, smooth in [0,1]
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prog_sq = progress * progress;

    // Tightness of fit: fraction of bin consumed by this item
    let fill_frac = item_size as f64 / cap;
    let post_frac = post_residual as f64 / cap;

    // Reward tight fits: smooth quadratic coupling of fill with progress
    score -= 30.0 * fill_frac * fill_frac * (0.6 + 0.8 * prog_sq);

    // Penalize large dead space non-linearly (cubic in post_residual fraction)
    score += 12.0 * post_frac * post_frac * post_frac * cap * (0.5 + progress);

    // Lookahead coupling: reward leaving space the next item can use
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_frac = next_item_size as f64 / cap;
        let usable = post_residual as f64 - next_item_size as f64;
        score -= 8.0 * next_frac * (1.0 + usable / cap);
    } else if next_item_size > 0 {
        // Next item cannot fit in the leftover: penalize
        score += 6.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * fill_frac;
    }

    // New-bin candidate: accept it when open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + open_bins_count as f64);
        let mean_tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score -= 25.0 * crowding * (0.5 + mean_tight) * (0.7 + 0.5 * prog_sq);
        // Penalize opening new bins early in the stream
        score += 20.0 * (1.0 - prog_sq);
    }

    // Mild penalty when many bins fit the item (prefer tightest; base post_residual handles that,
    // but add smooth diversity pressure scaled by mean residual)
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Harmonic class of post_residual: residue modulo capacity/10 (10-unit classes)
    let class_size = (bin_capacity / 10).max(1); // = 10
    let class = post_residual % class_size;
    // Penalize post_residuals that sit in "dead" classes (too small for typical items 1..100
    // but not zero). Zero residual is perfect; tiny nonzero residual is waste.
    if post_residual == 0 {
        score -= 25.0; // perfect closure bonus
    } else if class < 5 {
        // small sliver: nearly unusable dead space
        score += 12.0 + (5 - class) as f64 * 2.0;
    } else {
        // mid/large classes: mild reward proportional to how much future items could use
        score -= (class as f64) * 0.15;
    }

    // Integer-division thresholds: can next_item_size fit into post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // lookahead fit: reward, scaled by how snugly it would fit
            let post2 = post_residual - next_item_size;
            score -= 8.0 + (post2 as f64).min(20.0) * 0.3;
            // harmonic coupling: both residues in same modulo class -> chain-friendly
            if post2 % class_size == 0 {
                score -= 4.0;
            }
        } else {
            // lookahead cannot follow: penalize proportional to overflow gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // neutral-ish base; penalize so it's chosen only when open bins score badly
        score += 30.0;
        // early in stream, opening bins is cheap; later, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // if many bins already open and mean residual large, discourage new bin
        score += (open_bins_count as f64).sqrt() * 2.0;
        score += (mean_residual - item_size as f64).max(0.0) * 0.1;
    }

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Fraction-of-capacity harmonic: reward filling to common fractions (1/2, 3/4, 7/8)
    let frac_num = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    let harmonics = [0.5f64, 0.75, 0.875, 1.0];
    for h in harmonics.iter() {
        let d = (frac_num - h).abs();
        if d < 0.05 {
            score -= 6.0 * (1.0 - d / 0.05);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in a "dead zone" (small, unusable gap)
    // is heavily penalized, since no future item (min size 1..10) can realistically use it.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if (post_residual as f64) <= dead_threshold {
        score -= 5.0; // mild bonus for filling down into the dead zone
    }

    // Penalize leaving a gap that barely misses fitting the next item (lookahead waste).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 + 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving a gap that exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer packing into existing bins
    // rather than spreading; with few bins, spreading is cheaper.
    let pressure = open_bins_count as f64;
    score += pressure * 1.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when the current
    // bin would leave a large, awkward residual or when open-bin pressure is high.
    if bin_residual == bin_capacity {
        // Neutral baseline for a fresh bin: its residual is maximal.
        score = bin_capacity as f64 * 0.9;
        // Discourage opening new bins when existing bins fit decently.
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // Allow new bins when existing bins are nearly full on average.
        score -= mean_residual * 0.3;
        // Late in the stream, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Deviation from mean residual: prefer bins whose residual is below average
    // (they are the "fuller" bins), closing them out sooner.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (bin_capacity as f64);

    // Perfect match: item exactly fills bin
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if next item exactly fills the post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect chain match
        } else if next_item_size < post_residual {
            // next item fits: reward proportionally to how well it fills leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // next item cannot fit here: penalize wasted capacity that blocks the chain
            score += 10.0 + 0.3 * (post_residual as f64);
        }
    }

    // Compare against mean residual: placing in a bin with residual far below mean
    // preserves large-residual bins for larger future items
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New empty bin candidate: penalize unless current bins fit poorly
    if bin_residual == bin_capacity {
        // opening a new bin is attractive when few bins fit or item is large
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score -= 15.0 * pressure;
        score += 30.0 * (1.0 - pressure);
        // lookahead: if next item is big, a fresh bin may be valuable
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items as f64;
    score += 8.0 * progress * (open_bins_count as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: later in the stream -> tighter packing matters more.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual is good, especially late in stream.
    score -= (bin_capacity as f64 - post_residual as f64) * (0.5 + 0.5 * t);

    // Penalize dead space that cannot fit the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin stays useful for the next item: reward.
            score -= 8.0 + 0.1 * (next_item_size as f64);
        } else {
            // Dead space relative to the next item: penalize proportionally.
            score += 6.0 + 0.15 * (post_residual as f64) * (0.5 + t);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * t;
    }

    // New-bin candidate handling: penalize opening a new bin unless the fit
    // elsewhere is hopeless (item barely fits any open bin) or stream is early
    // and mean residual is already low.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for wasting a fresh bin.
        let mut new_bin_penalty = 30.0 + 25.0 * t;
        // If many bins already open and mean residual is large, opening a new
        // bin is wasteful; scale penalty with mean residual.
        new_bin_penalty += 0.2 * mean_residual;
        // If few bins fit the item, opening a new bin is more acceptable.
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 35.0;
        }
        // Perfect-fit incentive: item exactly fills the new bin.
        if item_size == bin_capacity {
            new_bin_penalty -= 100.0;
        }
        score += new_bin_penalty.max(0.0);
    } else {
        // Existing bin: small bonus for using already-opened capacity.
        score -= 3.0 + 0.05 * open_bins_count as f64;
        // Exact fit is perfect.
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Mild coupling: prefer bins whose residual deviates from the mean in a
    // "complementary" way (filling larger-residual bins keeps many small bins alive).
    score -= 0.1 * (bin_residual as f64 - mean_residual) * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0, 1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: post_residual penalized more heavily as stream progresses
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    score += 6.0 * (norm_pr * norm_pr) * (0.5 + progress) * cap * 0.1;

    // Reward tight fits (small post_residual) with a smooth cubic bonus
    score -= 4.0 * (1.0 - norm_pr).powi(3);

    // Penalize when post_residual cannot fit the lookahead item (dead space)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 3.0 * (ns - pr) / cap * (1.0 + progress);
        } else {
            // Smooth reward when lookahead fits: smaller leftover gap favored
            score -= 2.0 * (1.0 - ((pr - ns) / cap)) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress);
        score -= 4.0;
    }

    // Slight penalty when many bins are open and this placement wastes space
    let waste_factor = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += waste_factor * norm_pr * 3.0;

    // Coupling with mean residual: prefer bins deviating below mean residual (tighter bins)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * (0.5 + 0.5 * progress);

    // New-bin candidate: make it moderately attractive only when residuals are tight
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / cap).min(1.0);
        score = cap * 0.9 - 10.0 * avg_tightness * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into capacity-fraction buckets.
    // Small post_residual = tight fit -> reward strongly.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class boundaries at capacity fractions: 0, 10, 20, 50 (i.e. 0%, 10%, 20%, 50% of C)
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= bin_capacity / 10 {
        score -= 35.0; // near-perfect: tiny dead space
    } else if post_residual <= bin_capacity / 5 {
        score -= 18.0; // moderate fit
    } else if post_residual <= bin_capacity / 2 {
        score -= 5.0; // half-full leftover, still usable
    } else {
        score += 10.0; // large dead space penalty
    }

    // Harmonic residue classes: reward post_residual divisible by common item sizes
    // (10, 20, 25, 50) so future items of standard sizes can fill it exactly.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 6.0;
            if post_residual % 50 == 0 { score -= 6.0; }
        }
        if post_residual % 25 == 0 { score -= 4.0; }
    }

    // Lookahead: does the next item fit exactly or well into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // exact chain fit
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= bin_capacity / 10 {
                score -= 15.0; // next item nearly fills leftover
            } else {
                score -= 5.0; // next item at least fits
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty proportional to overshoot
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // or many bins are already open with high mean residual (fragmentation).
    if bin_residual == bin_capacity {
        score += 30.0; // base cost of opening a new bin
        // Opening a new bin is more attractive late in the stream when open bins are fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        if mean_residual > cap * 0.5 && open_bins_count > 2 {
            score -= 20.0; // open bins are fragmented; fresh bin may be better
        }
    } else {
        // Slight preference for fuller bins among open bins (best-fit reinforcement)
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Penalize spreading across many open bins when mean residual is low (good packing)
    if mean_residual < cap * 0.2 && bin_residual < bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 5.0 {
            score -= 35.0;
        } else {
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: this residual is likely dead space.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer reusing existing ones,
    // penalize opening a fresh bin.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * (open_bins_count as f64).sqrt();
    }

    // Slight preference for bins tighter than average (better consolidation).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late in the stream: be more conservative, avoid fragmenting residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 0.5 {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if post_residual >= next_item_size {
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize proportional to wasted gap
            score += 10.0 + diff * 0.5;
        }
    } else {
        // last item: just minimize leftover
        score += 5.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New empty bin candidate: penalize unless nothing decent fits elsewhere
    if bin_residual == bin_capacity {
        score += 25.0;
        // opening a new bin is fine if the next item is large and current fit is bad
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Prefer filling bins as stream progresses (consolidation)
    if open_bins_count > 0 {
        score -= 2.0 * (1.0 - step_index as f64 / total_items.max(1) as f64) * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    }

    // Reward bins that can also host the lookahead item (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Perfect chain: both current and next item exactly consumed.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_capacity {
        // If leaving a gap that nothing small can use, penalize mildly.
        let gap_useless = post_residual > 0 && post_residual < next_item_size.min(10);
        if gap_useless {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Penalize spreading across many bins when mean residual is already large.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when the item is large relative
        // to typical residuals, or early stream with few bins.
        let item_frac = item_size as f64 / bin_capacity as f64;
        let residual_pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let new_bin_bonus = 20.0 * item_frac + 25.0 * (1.0 - residual_pressure) + 10.0 * (1.0 - progress);
        score -= new_bin_bonus;
        // Never open a new bin for a tiny item late in the stream.
        if item_size <= 20 && progress > 0.3 {
            score += 15.0;
        }
    } else {
        // Existing bin: mild bonus for keeping bins consolidated.
        score -= (bin_residual as f64 - mean_residual) * 0.15;
        // Late stream: consolidate harder to close out bins.
        score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Slight preference for bins with larger residual (big holes absorb big items).
    score -= (bin_residual as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit = (pr / cap).clamp(0.0, 1.0);

    // Base: penalize post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * fit * fit) * (1.0 + 0.5 * progress);

    // Reward tight fits via cubic interaction with stream progress
    let tightness = 1.0 - fit;
    score -= item_size as f64 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that is too small for typical future items
    let dead = (pr / cap).powi(3);
    score += 20.0 * dead * (1.0 - progress);

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: slightly penalize opening a new bin early,
    // reward it late when residuals are fragmented
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) - 5.0 * progress * (fitting_bins_count as f64).sqrt();
    }

    // Lookahead coupling: if next item fits the post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - pr / cap);
    }

    // Mean residual drift penalty: discourage bins far from mean residual
    let dev = (pr - mean_residual).abs() / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" residue classes (multiples of small sizes) are favored.
    let post = post_residual;
    if post > 0 {
        let class = match post % 10 {
            0 => -12.0, // perfectly divisible leftover, highly reusable
            5 => -6.0,  // half-decade leftover
            2 | 4 | 6 | 8 => -2.0, // even leftovers pair well
            _ => 4.0,   // odd prime-ish leftovers are dead space
        };
        score += class;

        // Integer-division thresholds: leftover that can host common small
        // items (>=10) is valuable; leftover < 10 is pure dead space.
        if post < 10 {
            score += 15.0; // unusable dead space penalty
        } else {
            // how many "slots" of the next item fit in the leftover
            if next_item_size > 0 {
                let slots = post / next_item_size;
                score -= (slots.min(4) as f64) * 5.0;
                // exact fit for the lookahead item is a jackpot
                if next_item_size <= post && post % next_item_size == 0 {
                    score -= 8.0;
                }
            }
        }
    } else {
        // Perfect closure of the bin: strongly rewarded.
        score -= 25.0;
    }

    // Capacity-fraction coupling: prefer filling bins past the 50% and 75%
    // marks (item_size relative to capacity).
    let fill_frac = item_size as f64 / bin_capacity as f64;
    if fill_frac > 0.75 {
        score -= 10.0;
    } else if fill_frac > 0.5 {
        score -= 5.0;
    } else if fill_frac < 0.25 {
        score += 4.0; // dumping tiny items into big-residual bins is wasteful
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 14.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the
    // fit into existing bins would be poor.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 0.6;
        if crowded || fitting_bins_count == 0 {
            score -= 18.0;
        } else {
            score += 20.0; // keep using open bins when they fit well
        }
    }

    // Stream progression: early on, be picky about tight fits; later, be
    // more permissive to close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post as f64) * 0.15;

    // Slight preference for bins below mean residual (balancing leftovers).
    score += ((bin_residual as f64 - mean_residual) * 0.05).clamp(-5.0, 5.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    let post = post_residual as f64;
    if post > 0.0 && post < 10.0 {
        // Tiny sliver left behind: heavily penalize (dead space).
        score += 40.0 * (10.0 - post) / 10.0;
    }

    // Reward near-perfect fits (post_residual close to 0 but not a tiny sliver).
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    } else if post >= 10.0 {
        // Usable residual: reward proportionally to tightness of fit.
        score -= 12.0 * (1.0 - post / bin_capacity as f64);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit in this residual: the residual may become dead space.
        score += 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage opening a new one.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bin count and
        // to how much residual space already exists across open bins.
        score += 35.0 + pressure * 3.0 + mean_residual * 0.4;
    } else {
        // Mild bonus for using existing bins when they are plentiful.
        score -= pressure * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post-residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 60.0;
        } else {
            score += gap * 0.5;
        }
        // If next item fits in the post residual, mild bonus scaled by tightness.
        if post_residual >= next_item_size {
            score -= (next_item_size as f64 / bin_capacity as f64) * 20.0;
        }
    }

    // Penalize dead space: post_residual too small for any future item (min size 1, but
    // treat tiny residuals relative to typical item scale).
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (best-fit style), penalize loose bins.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Early in the stream, be more willing to spread items (open bins for future flexibility).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, or when open bins are few and item is large.
        let early_bonus = (1.0 - progress) * 15.0;
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 20.0;
        score -= early_bonus + large_item_bonus;
        // Penalize opening a new bin late in the stream when many bins are open.
        score += (open_bins_count as f64) * 2.0 * progress;
    }

    // Mild penalty for wasting a very large bin residual on a small item.
    if (post_residual as f64) > bin_capacity as f64 * 0.6 && (item_size as f64) < bin_capacity as f64 * 0.3 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong subtraction for zero waste.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        // Tightness reward: quadratic bonus for small post residuals.
        let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 120.0 * tight * tight;

        // Dead-space penalty: residuals too small for the smallest plausible item (<=10)
        // are unusable; penalize proportionally.
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0 * (1.0 - post_residual as f64 / 20.0);
        }

        // Lookahead coupling: reward if next item can fit in post_residual (chaining),
        // penalize if next item is large and would be stranded.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if (next_item_size as u32) <= post_residual {
                // next item chains perfectly: extra reward scaled by how well it fills
                let chain_waste = post_residual as f64 - nxt;
                score -= 45.0 * (1.0 - chain_waste / bin_capacity as f64);
            } else {
                // next item cannot use this residual: mild penalty grows with residual size
                score += 0.15 * (post_residual as f64 - nxt).max(0.0);
            }
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // rather than fragmenting or opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // Many options: prefer the tightest fit; add mild penalty to spread attention
        // so relative ordering of post_residual dominates.
        score += 5.0;
    }

    // New-bin candidate arbitration: an empty bin has full residual. Make opening a
    // new bin attractive only when no open bin fits well (post_residual large) or
    // when the item is huge relative to capacity.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin, discounted early in the stream and when
        // few bins are open; increased late when consolidation matters.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 30.0 + 50.0 * progress;
        if open_bins_count == 0 {
            open_cost -= 40.0; // must open a bin anyway
        }
        // If item is large, new bin gives a clean fit; discount cost.
        open_cost -= 25.0 * fill_ratio;
        // If mean residual across open bins is small, open bins are nearly full:
        // opening new is natural.
        open_cost -= 10.0 * (mean_residual / bin_capacity as f64).min(1.0);
        score += open_cost;
    }

    // Global fragmentation guard: penalize placements that leave residual close to
    // the mean residual (creates many similar medium holes) — encourage diversity.
    if post_residual > 0 {
        let diff = (post_residual as f64 - mean_residual).abs();
        score += 8.0 * (1.0 - (diff / bin_capacity as f64).min(1.0));
    }

    // Time-horizon modulation: early in stream, be conservative (keep residuals
    // flexible/large); late in stream, prioritize filling bins to zero.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let post_norm = post / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping
    let mut score = post + 12.0 * post_norm * post_norm * cap;

    // Polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap (many items remain to fill gaps);
    // late, waste is costly, so amplify quadratic penalty as progress -> 1.
    let progress_coupling = 1.0 + 3.0 * progress * progress + 2.0 * progress * post_norm;
    score *= progress_coupling;

    // Reward bins whose post-residual can host the lookahead item (smooth term)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (post - nxt).abs();
        score -= 8.0 * (1.0 - fit_gap / cap).max(0.0) * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - post_norm);
    }

    // Mild pressure toward reusing bins when many are open
    score += 0.5 * open_bins_count as f64 * post_norm;

    // Penalize bins far from mean residual (fragmentation avoidance), smooth form
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: reward post_residuals divisible by common size classes (10s, 5s, 2s)
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 2.5;
    } else if post_residual % 2 == 0 {
        score -= 0.5;
    } else {
        score += 3.0; // odd dead space is hard to fill
    }

    // Integer-division thresholds: post_residual in [0,10] is near-perfect fill
    let q = post_residual / 10;
    score -= match q {
        0 => 8.0,
        1 => 4.0,
        2 => 2.0,
        3 => 1.0,
        _ => 0.0,
    };

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // harmonic class of leftover after next item
        let post2 = post_residual - next_item_size;
        if post2 % 10 == 0 {
            score -= 5.0;
        } else if post2 % 5 == 0 {
            score -= 1.5;
        }
        score += post2 as f64 * 0.05;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus penalty that shrinks when mean residual is high (many fragmented bins)
        score += 12.0 + mean_residual * 0.15;
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            score -= 4.0; // next item won't fit here anyway; new bin less harmful
        }
    }

    // Slight preference for tighter bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (bin_residual as f64 / bin_capacity as f64) * progress * 4.0;
    score -= (open_bins_count as f64).sqrt() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 80.0; // perfect fill
    }

    // Favor bins whose post_residual can host the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (the empty-bin candidate gets penalized when open_bins_count is high).
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins tighter than the mean residual (well-utilized bins).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual >= next_item_size {
            // next item fits, but penalize leftover after that hypothetical placement
            score -= 200.0 - (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit: penalize leaving dead space
            score += 50.0;
        }
    }

    // Compare residual against mean residual across open bins
    score -= 2.0 * (bin_residual as f64 - mean_residual);

    // Last-chance bin bonus: only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening new bins when open bins fit well
    if bin_residual == bin_capacity {
        score += 100.0 + 0.5 * open_bins_count as f64;
    }

    // Slight preference to fill tighter bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * post_residual as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual is good, but dead space below
    // typical item sizes is worse. Penalize unusable slivers.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize post-residuals that are too small to hold any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; mild penalty proportional to waste
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Prefer fullest bins (best-fit style): compare residual to mean residual.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // When many bins are open, favor consolidation into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += 3.0 * pressure;

    // New-bin candidate: penalize opening a new bin unless current residuals
    // are all poorly matched to the item.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_capacity as f64) - (mean_residual.max(0.0));
        // If mean residual is large, existing bins likely fine: discourage new bin.
        score += 45.0 - 0.3 * mean_residual;
        // Early in stream, opening bins is cheaper; late, expensive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
        // If item is large, a fresh bin is more attractive.
        score -= 0.1 * item_size as f64;
        let _ = poor_fit;
    }

    // Slight preference for bins whose residual matches item size closely
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;

    // Base: quadratic penalty on wasted residual, weighted by stream progress
    let mut score = pr_norm * pr_norm * (1.0 + 2.0 * progress) * cap;

    // Cubic coupling: small residuals late in the stream are heavily penalized
    score += 0.5 * pr_norm.powi(3) * cap * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item size)
    let tightness = it / br.max(1.0);
    score -= 20.0 * tightness * (1.0 + progress);

    // Last-chance bonus: only one bin fits -> strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Prefer bins whose residual is close to the item (best-fit flavor)
    let gap = (br - it).abs();
    score += 0.3 * gap;

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (nx / cap);
        } else {
            score += 6.0 * (nx / cap) * (1.0 - pr / nx.max(1.0));
        }
    }

    // Mild preference for consolidating into fewer bins when many are open
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // Deviation from mean residual: prefer atypical bins (keeps diversity)
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline, penalized when any open bin fits well
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.4 * (1.0 - progress)) + 0.05 * open_bins_count as f64;
        if fitting_bins_count >= 1 {
            score += 10.0 * (1.0 + progress);
        }
        if next_item_size > 0 && next_item_size as f64 <= cap {
            score -= 4.0 * (next_item_size as f64 / cap);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect-fit reward: post residual in {0, 5, 10} (harmonic divisors of 100).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0 - pr * 1.5;
    }

    // Dead-space penalty: residual that no plausible item (1..=100) can use well.
    // Residual classes: r in (0,10) is near-dead; r in [10,20] marginal.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 7.0 - pr * 0.2;
    }

    // Modulo-20 harmonic band: residual divisible by 20 pairs well with common item sizes.
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chain perfect fit
        } else if next_item_size <= post_residual {
            // reward proportional to how tightly next item fills remaining space
            let tight = 1.0 - ((post_residual - next_item_size) as f64) / cap;
            score -= 8.0 + 22.0 * tight;
        } else {
            // next item won't fit: penalize large leftover that will strand
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post residual would be terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual < 5 && post_residual > 0 {
            score += 10.0; // but not if it creates a tiny dead sliver
        }
    }

    // New-bin candidate handling: empty bin gets a mild baseline so it only wins
    // when open bins score poorly (large dead space).
    if bin_residual == bin_capacity {
        score = cap * 0.45 - (next_item_size as f64) * 0.1;
        if fitting_bins_count == 0 {
            score -= 20.0; // nothing fits anywhere: must open
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - pr / cap);

    // Mean-residual context: if open bins are generally full, opening new is fine;
    // if mean residual is high, penalize spreading.
    score += (mean_residual - pr).max(-30.0).min(30.0) * 0.15;

    // Tight fit reward relative to item size (best-fit flavor with harmonic scaling).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Integer-division threshold: post_residual >= 50 keeps bin viable for future items.
    if post_residual >= 50 {
        score -= 5.0;
    } else if post_residual >= 30 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in [1, 12] are "unusable" gaps.
    if post_residual >= 1 && post_residual <= 12 {
        score += 40.0 - 2.5 * post_residual as f64; // worst at post_residual == 1
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 3 {
        score -= 18.0;
    } else if post_residual <= 8 {
        score -= 8.0;
    }

    // Last chance: if this is the only bin that can fit the item, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // penalize the new-bin candidate (bin_residual == bin_capacity) when others exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + 8.0 * (open_bins_count as f64).sqrt() + 15.0 * progress;
    } else {
        // Favor bins whose residual is close to what we fill.
        score -= 6.0 * (1.0 - (bin_residual as f64 - item_size as f64).abs() / bin_capacity as f64);
    }

    // Lookahead: if the next item fits the post-residual exactly, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 4 {
            score -= 12.0;
        } else if slack <= 12 {
            score -= 5.0;
        }
    }
    // If next item would be blocked by a tiny leftover, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Mild preference for bins below mean residual (tighter bins get filled first).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Near-perfect match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward closeness: slack 0 best, decaying reward.
        score -= 120.0 / (1.0 + slack * 0.25);
    }
    // Penalize post_residual too small for the next item (dead space that can't be used next step).
    if next_item_size > 0 && post_residual < next_item_size {
        let unusable = (next_item_size - post_residual) as f64;
        score += 0.6 * unusable;
    }

    // Reward tight fits relative to mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.5;
    } else {
        score += (pr - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.5;

    // Late in the stream, tighten up: penalize large post_residual more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * progress * 0.4;

    // New-bin candidate: prefer it only when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        score += 60.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual approaches 0.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space: residuals too small for the smallest plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / 100.0);
        } else {
            // Post-residual cannot host next item: penalize proportionally to waste.
            score += 8.0 * (1.0 - (post_residual as f64 / bin_residual.max(1) as f64));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer fuller bins relative to the fleet's mean residual.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Time horizon: later in the stream, consolidate aggressively into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    } else {
        // New-bin candidate: penalize opening new bins unless it's early or item is huge.
        score += 5.0 + 60.0 * progress - 20.0 * (item_size as f64 / bin_capacity as f64);
        // Open a fresh bin if item is large and would leave a tiny residual anywhere.
        if item_size >= 80 {
            score -= 15.0;
        }
    }

    // Many open bins: discourage spreading, favor filling existing ones.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let norm_post = post / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer minimal post residual, scaled non-linearly (quadratic waste penalty)
    let mut score = norm_post * (1.0 + 2.0 * norm_post * norm_post);

    // Smooth coupling: waste is more costly later in the stream
    score += 1.5 * norm_post * (0.5 + progress);

    // Reward bins whose residual is close to the item (tight fit) via smooth kernel
    let tightness = 1.0 - (norm_post / (norm_post + 0.15));
    score -= 1.2 * tightness * (0.5 + norm_item);

    // Lookahead: bonus if next item fits the post-residual well (smooth match kernel)
    if next_item_size > 0 && next_item_size <= post_residual as u32 {
        let gap = (post - norm_next * cap) / cap;
        score -= 1.0 * (1.0 - gap) * norm_next;
    } else if next_item_size > post_residual as u32 {
        // penalize leaving a residual that no plausibly-sized item can use
        score += 0.6 * norm_post * (1.0 - progress);
    }

    // Last-chance bonus: only this bin fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // Penalize opening a new bin when open bins could fit, more so late in stream
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 2.5 + 2.0 * progress + 0.05 * open_bins_count as f64;
        } else {
            score += 0.5 * progress;
        }
    }

    // Mild preference for bins below mean residual (consolidating fuller bins)
    score += 0.3 * ((mean_residual - post) / cap).clamp(-1.0, 1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity fractions (0..10 buckets). Small leftover = good fit.
    let post_class = (post_residual * 10) / bin_capacity; // 0..10
    match post_class {
        0 => score -= 60.0,          // perfect fit
        1 => score -= 40.0,          // excellent
        2 => score -= 25.0,
        3 => score -= 12.0,
        4 => score -= 4.0,
        5 => score += 6.0,           // half-empty: mediocre
        6 => score += 14.0,
        7 => score += 24.0,
        8 => score += 36.0,
        _ => score += 50.0,          // nearly untouched bin: wasteful
    }

    // Modular dead-space analysis: post_residual mod 10 — small remainders
    // are hard to fill with typical item granularities.
    let m = post_residual % 10;
    if m == 0 {
        score -= 8.0;
    } else if m >= 7 {
        score += m as f64 * 1.5;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward strongly; if the next item would be blocked, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 - slack.min(30) as f64 * 0.5;
        } else {
            // next item cannot fit here: leftover is dead weight
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(6.0);
    }

    // New-bin candidate handling: an untouched bin has huge residual,
    // which the base score already penalizes; add a mild exploration
    // bonus only when open bins are badly fragmented (high mean residual
    // and many open bins) so we don't drown in unusable bins.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap;
        let pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
        score = post_residual as f64 - fragmentation * 12.0 - pressure * 5.0;
    }

    // Slight preference to fill older/crowded states as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (they are wasted capacity).
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    } else {
        // Mild reward for leaving a moderately useful gap.
        score -= 2.0;
    }

    // Perfect / near-perfect fits are excellent.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Tightness ratio: reward high fill fraction of the residual.
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= tightness * 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement is highly desirable.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0;
    }

    // Open-bin pressure: discourage spreading across too many bins, but
    // encourage opening a new bin when open bins are already crowded.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // New-bin candidate handling: an empty bin should only win when the fit
    // into open bins would be poor (large dead space or many open bins).
    if bin_residual == bin_capacity {
        // Base handicap so good fits into open bins win first.
        score += 10.0;
        // But if open bins are numerous and fragmented, opening fresh is fine.
        score -= (open_bins_count as f64).min(20.0) * 0.8;
        if mean_residual < 25.0 {
            score -= 8.0; // existing bins are nearly full; new bin is attractive
        }
    }

    // Slight nudge toward bins below the mean residual (balancing usage).
    if (post_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // --- 2-step lookahead: reward when next item exactly fills post_residual ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0 + 30.0 * progress; // perfect chain: item + next item fill bin
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after the lookahead item (dead space creation)
            score += slack * (0.35 + 0.4 * progress);
            if slack < 10.0 {
                score -= 12.0; // near-perfect chain still valuable
            }
        } else {
            // next item cannot follow into this bin; mild penalty scaled by overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    } else {
        // last item of the stream: pure tightness
        score -= 5.0;
    }

    // --- Relative tightness vs mean residual of open bins ---
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (pr - mean_residual) / mean_residual;
        score += 8.0 * rel; // prefer bins ending below-average residual
    }

    // --- Last-chance bonus: only bin that fits -> avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Attractive if no good fit exists among open bins (post_residual would be huge elsewhere)
        // or if the item + next item would pair poorly everywhere.
        let tight_fit_exists = fitting_bins_count > 0 && (mean_residual as u32) < item_size + 15;
        if tight_fit_exists {
            score += 30.0; // discourage wasting a fresh bin
        } else {
            score -= 10.0; // opening fresh bin is reasonable
        }
        // Early stream: fresh bins slightly cheaper to open (future flexibility)
        score -= 15.0 * (1.0 - progress);
        // If lookahead pairs perfectly with a fresh bin (item + next <= capacity)
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // --- Fragmentation penalty: tiny unfillable leftovers ---
    if pr > 0 && pr < 10 {
        score += 6.0;
    }

    // Mild penalty for spreading across many bins when alternatives exist
    if open_bins_count > 3 && bin_residual < bin_capacity {
        score += 0.5 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core best-fit shaping: reward tight fits nonlinearly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 4.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Lookahead: if the next item fits exactly into this bin's post-residual,
    // strongly favor this bin (chains two items perfectly).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover: mild penalty scaled by waste.
            score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive when the stream
    // is early or when open bins are still roomy.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, modulated by global roominess and phase.
        score += 20.0 + 10.0 * (1.0 - progress);
        if mean_residual > item_size as f64 {
            score += 6.0 * (mean_residual - item_size as f64) / bin_capacity as f64;
        }
        if fitting_bins_count == 0 {
            // Nothing fits anywhere: new bin is legitimate, soften penalty.
            score -= 35.0;
        }
    }

    // Crowd control: many open bins with low mean residual -> consolidate.
    if open_bins_count > 4 {
        let consolidation = (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
        score += 4.0 * consolidation * (1.0 - fit_ratio);
    }

    // Late-stream tightening: waste matters more near the end.
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (low post_residual);
    // later, tolerate residual more to keep flexibility.
    let tightness = norm_pr * norm_pr * (1.0 - progress) * 140.0;
    let flexibility = norm_pr * progress * 40.0;
    score += tightness - flexibility;

    // Lookahead: reward residual that can host the next item (smooth quadratic fit term).
    if next_item_size > 0 {
        let diff = pr - next_item_size as f64;
        let fit_quality = 1.0 - (diff / cap) * (diff / cap);
        score -= 55.0 * fit_quality.max(0.0) * (1.0 - 0.5 * progress);
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 90.0 * (1.0 - norm_pr * norm_pr);
    }

    // Penalize deviating far from mean residual (balance bin usage smoothly).
    score += 0.25 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Mild penalty for leaving awkward mid-range residuals (smooth bump).
    let bump = norm_pr * (1.0 - norm_pr);
    score += 25.0 * bump * bump * 4.0 * (0.5 + 0.5 * progress);

    // New-bin candidate: make it less attractive unless residuals are badly fragmented.
    if bin_residual == bin_capacity {
        score += 35.0 + 60.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into "usable"
    // classes (multiples of common item sizes) are favored.
    let pr = post_residual as u32;
    let mut class_bonus = 0.0f64;
    if pr == 0 {
        class_bonus -= 60.0; // perfect closure
    } else if pr <= 10 {
        class_bonus -= 25.0; // small dead space, nearly full
    } else {
        // usable-class check: residual divisible by small common sizes
        let usable = pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0;
        if usable {
            class_bonus -= 15.0;
        } else {
            class_bonus += (pr % 10) as f64 * 1.5; // awkward remainder penalty
        }
        // harmonic bucket via integer division thresholds
        let bucket = pr / 15; // 0..6 classes
        class_bonus -= (6 - bucket.min(6)) as f64 * 3.0;
    }
    score += class_bonus;

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            // next fits: penalize leftover of next placement harmonically
            let nxt_left = pr - next_item_size;
            score -= 10.0;
            score += (nxt_left % 10) as f64 * 0.8;
        } else {
            // next cannot use this residual: penalize proportionally
            let gap = next_item_size - pr;
            score += (gap as f64).min(60.0) * 0.35;
        }
    } else {
        // last item: prefer tightest fit strongly
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets baseline; discourage it when
    // decent fits exist, encourage when current fit is bad.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
        if fitting_bins_count == 1 {
            score += 40.0; // don't abandon the only fitting bin
        }
    }

    // Progress-aware dead-space scaling: later in stream, residual waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64) * progress * 0.25;

    // Mean-residual coupling: if this bin is far below mean residual, it is
    // relatively full -> favor it.
    score += (mean_residual - post_residual as f64).max(-50.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100 range,
    // but penalize hard below a conservative min-item threshold) are wasted.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 500.0 * (dead_threshold - post_residual as f64);
    }

    // Soft dead-zone: small-but-usable gaps are risky; penalize quadratically.
    if post_residual > 0 && post_residual <= 30 {
        score += 0.08 * (30.0 - post_residual as f64) * (30.0 - post_residual as f64);
    }

    // Reward tight fits (small post_residual relative to item size).
    let fit_ratio = post_residual as f64 / item_size.max(1) as f64;
    score -= 40.0 * (1.0 - fit_ratio.min(1.0));

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.3 * next_item_size as f64;
    }
    // If next item almost fits, mild penalty for blocking it.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && next_item_size - post_residual <= 15 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // penalize opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins fit or residuals are fragmented.
        let pressure = open_bins_count as f64 * 12.0;
        score += pressure;
        // Allow new bin when existing residuals are large/fragmented and next item is big.
        if next_item_size > 60 && mean_residual > 50.0 {
            score -= 30.0;
        }
    } else {
        score -= 5.0; // mild preference for reusing open bins
    }

    // Progress-based caution: early in stream, keep bins flexible (avoid tiny residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.15 * post_residual as f64;

    // Slight nudge toward bins with residuals near this item (best-fit flavor).
    score += 0.1 * (bin_residual as f64 - item_size as f64 - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect match with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // exact fit for the next item
        } else if post_residual >= next_item_size {
            score -= (10.0 * next_item_size as f64) / diff.max(1.0);
        } else {
            // next item cannot fit here; penalize more for larger leftover
            score += 5.0 + diff * 0.3;
        }
    }

    // Penalize dead space relative to mean residual of open bins.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += (pr - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - pr) * 0.2;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 40.0 - 30.0 * pressure + 2.0 * open_bins_count as f64;
    }

    // Slight preference to fill bins tighter as stream progresses.
    score -= (step_index as f64 / total_items.max(1) as f64) * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 25.0;

    // Penalize large dead space relative to smallest plausible item
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.4) * 0.05;
    }

    // Lookahead: reward bins whose post_residual can host the next item exactly-ish
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 - slack * 0.25;
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: later in stream, prefer filling existing bins aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0 * (1.0 - fit_ratio);

    // Global state: many open bins -> discourage new bins, encourage consolidation
    let mean_res = mean_residual;
    if bin_residual as f64 > mean_res {
        score += (bin_residual as f64 - mean_res) * 0.12;
    } else {
        score -= (mean_res - bin_residual as f64) * 0.12;
    }

    // New-bin candidate: penalize unless open bins are quite full or item is huge
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_res / bin_capacity as f64;
        let threshold = 0.55 + 0.3 * (item_size as f64 / 100.0);
        if avg_fill < threshold {
            score += 30.0 + 20.0 * (threshold - avg_fill);
        } else {
            score -= 5.0;
        }
    }

    // Slight penalty on very fragmented bins
    if post_residual < 10 && post_residual > 0 {
        score -= 4.0; // nearly perfect closure
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear waste penalty: dead space grows quadratically, worse later in stream
    let norm_waste = pr / cap;
    score += 40.0 * norm_waste * norm_waste * (0.5 + progress);

    // Reward tight fits: small post_residual relative to item size
    let tightness = 1.0 - (pr / (item_size as f64 + pr));
    score -= 25.0 * tightness * tightness;

    // Lookahead: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_next = 1.0 - (gap / cap).min(1.0);
        score -= 18.0 * fit_next * fit_next;
        // Penalize leaving residual too small for next item (dead space)
        if pr < next_item_size as f64 {
            score += 10.0 * (1.0 - pr / next_item_size.max(1) as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 - 0.5 * progress);
    }

    // Coupling with mean residual: prefer bins deviating from mean when mean is large
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev.abs() * (1.0 - progress);

    // New-bin candidate handling: empty bin gets baseline competing score
    if bin_residual == bin_capacity {
        score = 55.0 + 30.0 * progress - 12.0 * (fitting_bins_count as f64).recip();
        if fitting_bins_count == 1 {
            score += 40.0; // never open new bin when only one open bin fits
        }
    }

    // Mild preference to fill existing bins when many are open
    score -= 5.0 * (open_bins_count as f64).ln().max(0.0) * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 act as "dead space classes"
    let post = post_residual;
    let class = post % 10;
    // Residues near 0 are excellent (bin nearly full); residues 1..9 are dead space of varying quality
    let class_penalty = match class {
        0 => -6.0,
        1 | 2 => 3.0,       // tiny unusable slivers
        3 | 4 | 5 | 6 | 7 => 1.5, // mid slivers
        _ => 0.5,
    };
    score += class_penalty;

    // Integer-division thresholds: how many items of typical size (~ mean residual scale) fit after
    let fits_after = if post > 0 { post / 10 } else { 0 };
    score -= (fits_after as f64) * 0.8;

    // Lookahead harmony: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 12.0; // perfect harmonic continuation
        } else if next_item_size < post {
            let gap = post - next_item_size;
            // reward small gaps (near-perfect two-item packing), modulo-graded
            let gclass = gap % 10;
            let bonus = if gclass == 0 { 8.0 } else if gclass <= 3 { 4.0 } else { 1.5 };
            score -= bonus * (next_item_size as f64 / 100.0 + 0.5);
        } else {
            // next item cannot use this residual at all -> penalize proportionally
            score += (next_item_size - post) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 9.0;
    }

    // New-bin candidate handling: only open a new bin when current residual is truly bad
    if bin_residual == bin_capacity {
        // Empty bin baseline: slightly worse than a good fit, better than a terrible fit
        score = (bin_capacity - post) as f64; // = 0 for empty bin
        score += 4.0; // mild preference for reusing open bins
        if fitting_bins_count == 0 {
            score -= 20.0; // nothing else fits, must open
        }
        if next_item_size >= bin_capacity {
            score -= 5.0;
        }
    } else {
        // Tight-fit reward: item fills most of the residual
        let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
        if fill_ratio > 0.9 {
            score -= 10.0;
        } else if fill_ratio > 0.7 {
            score -= 5.0;
        }
        // Penalize leaving residual far from any harmonic class multiple of common sizes
        if post > 0 && post < 10 {
            score += 4.0; // small stranded residual
        }
    }

    // Progress coupling: later in the stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;
    // Mean residual deviation: prefer bins whose residual is near the mean (keeps bin profile uniform)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item.max(10) {
            score += 500.0;
        }
        // Dead space relative to capacity: small post residuals that can't fit
        // typical items (<=10) are wasted; weight non-linearly.
        let dead = (post_residual as f64) / (bin_capacity as f64);
        if post_residual < 10 {
            score += 300.0 * (1.0 - dead);
        } else if post_residual < 20 {
            score += 40.0 * dead;
        }
    } else {
        // Perfect fit is highly desirable.
        score -= 200.0;
    }

    // Reward tight fits: the smaller post_residual relative to bin_residual,
    // the better the fill ratio.
    let fill = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 50.0 * fill;

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin candidate).
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        score += 80.0 + pressure;
    } else {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    // (leaves useful space for the next item).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0;
    }
    // If next item would be blocked by the post residual, slight penalty.
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 15.0;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (keeps bin states homogeneous), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
