pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward very tight fits (low dead space) more aggressively.
    let tightness = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small residual waste that next item can still use is fine; large unusable
    // residual (below min item size 1 threshold ~ next_item_size) is dead space.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            // residual too small for the lookahead item -> penalize.
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        } else if next_item_size <= post_residual {
            // residual can host the next item -> reward keeping this bin viable.
            score -= 6.0;
        }
    }

    // Last-chance bin: only fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many open bins: encourage consolidation into existing bins over new ones.
    if bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // New-bin candidate: penalize unless item is large relative to capacity
        // or existing bins are mostly full (mean_residual low).
        score += 15.0;
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        score += 0.4 * mean_residual;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Mild preference for bins below mean residual (balancing leftovers).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;

    // Core: waste grows super-linearly with post_residual
    let mut score = pr * (1.0 + 0.9 * pr / cap) / (1.0 + fit_ratio);

    // Smooth interaction of waste with stream progress: late in stream, waste matters more
    score *= 1.0 + 0.6 * progress * (pr / cap);

    // Reward tight fits: penalize (subtract) when post_residual is small relative to capacity
    let tightness = 1.0 - pr / cap;
    score -= 8.0 * tightness * tightness * (1.0 + 0.5 * progress);

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        if pr >= next_item_size as f64 {
            score -= 10.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
        } else {
            score += 0.02 * gap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0 * (1.0 + progress);
    }

    // Discard near-empty bins when many bins are open (consolidation pressure)
    let res_norm = bin_residual as f64 / cap;
    score += 1.5 * open_bins_count as f64 * (1.0 - res_norm) * (1.0 - res_norm) / (1.0 + open_bins_count as f64);

    // Mild pull toward bins with residual close to mean residual (balance)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate handling: empty bin should only win when fits are bad
    if bin_residual == bin_capacity {
        score = 30.0 + 20.0 * (1.0 - progress) - 4.0 * fit_ratio;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes over small divisors.
    let pr = post_residual;
    let m4 = (pr % 4) as f64;
    let m8 = (pr % 8) as f64;
    let m10 = (pr % 10) as f64;
    // Residuals near multiples of 10 are "harmonic" — more likely to be filled
    // by future items from typical size lattices. Reward proximity to 0 mod 10.
    let harm = (10 - m10) / 10.0; // 1.0 when pr % 10 == 0
    score -= 6.0 * harm;

    // Dead-space penalty: small but nonzero residuals are worst.
    if pr > 0 && pr < 10 {
        score += 25.0;
    } else if pr < 20 {
        score += 8.0 * (1.0 - pr as f64 / 20.0);
    }

    // Perfect fit is ideal.
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let nrem = pr - next_item_size;
            // reward only if the chain leaves harmonic residue again
            if nrem % 10 == 0 {
                score -= 15.0;
            }
            score += (nrem % 8) as f64 * 0.5;
        } else {
            // next item does not fit here: slight penalty scaled by overshoot class
            score += ((next_item_size - pr) % 20) as f64 * 0.3;
        }
    }

    // Integer-division threshold on post_residual: bins with residual in
    // [10, 30] band are prime targets for medium items.
    let band = pr / 10; // 0..10
    match band {
        1 | 2 | 3 => score -= 10.0,
        4 => score -= 4.0,
        7 | 8 => score -= 2.0, // near-empty bins, keep flexible
        _ => {}
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when existing bins
    // would leave very poor fits, or stream is early with few bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = if pr >= bin_residual {
            0.0
        } else {
            (bin_residual - pr) as f64
        };
        // base cost of a fresh bin, discounted early in the stream
        let fresh_cost = 40.0 * (1.0 - 0.5 * (1.0 - progress));
        score = fresh_cost + poor_fit * 0.2 - (open_bins_count as f64) * 0.1;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    // Mild tie-breaker toward bins with below-average residual (fill fuller bins first).
    score += ((bin_residual as f64) - mean_residual).clamp(-30.0, 30.0) * 0.15;

    // Tiny harmonic jitter from m4/m8 to break ties deterministically.
    score += m4 * 0.05 + m8 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    // Anything below 10 (minimum item size) is guaranteed dead space.
    if post_residual < 10 {
        score += 500.0;
    } else if post_residual <= 20 {
        // Small gaps are only useful for small items; penalize proportionally.
        score += (20.0 - post_residual as f64) * 8.0;
    }

    // Perfect fit reward: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Penalize leaving a gap that the lookahead item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 3.0;
    }

    // Reward placements where the next item fits snugly into the new residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size as u32) as f64;
        score -= 2.0 / (1.0 + snug);
    }

    // Open-bin pressure: discourage scattering across many open bins.
    score += open_bins_count as f64 * 2.5;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: make it less attractive unless it enables a good pair.
    if bin_residual == bin_capacity {
        score += 40.0;
        // But if the next item pairs perfectly with the current one in a fresh bin,
        // opening a new bin is fine.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 60.0;
        }
    }

    // Progress-based adjustment: later in the stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Prefer bins below mean residual (tighter bins) for large fills.
    if (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-exact fits (low post residual).
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 15 {
        score -= 20.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = (post_residual - next_item_size) as f64;
        if chain_waste <= 5.0 {
            score -= 35.0; // perfect 2-item chain
        } else {
            score -= 15.0 - chain_waste * 0.3; // partial chain bonus
        }
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize proportionally to leftover size.
        score += (next_item_size as f64) * 0.25;
    }

    // Penalize creating dead space below the minimum item size (1..100 unknown; use item_size as proxy floor).
    if post_residual > 0 && post_residual < item_size.min(10) {
        score += 25.0;
    }

    // Compare residual against mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it neutral-high so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
        // If next item is large, a fresh bin may be attractive for sequencing.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
    }

    // Late in stream: prefer tightening existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: favor bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize creating dead space that no typical item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward if the next item fits exactly-ish into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to leftover waste.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when open bins are mostly full
    // or the fit elsewhere would be very poor.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Early in stream: prefer keeping bins open; later: allow opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 18.0 * pressure - 8.0 * progress;
    } else {
        // Prefer filling bins that are already heavily loaded (reduce bin count).
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 5.0 * fullness;

        // If many bins are open, discourage spreading across too many.
        if open_bins_count > 4 {
            score += 0.5 * (open_bins_count as f64 - 4.0);
        }
    }

    // Slight preference for bins below mean residual (balance consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual (0..1)

    // Base: prefer tight fits (small post residual), with non-linear penalty growth
    let mut score = post + 30.0 * pr * pr * cap;

    // Non-linear coupling of post residual with stream progress:
    // early on, tolerate loose fits; late, demand tight packing more strongly
    let tightness = 1.0 + 2.0 * progress * progress;
    score *= tightness;

    // Smooth interaction: dead-space risk grows with progress and residual
    let dead = pr * pr * pr * (0.5 + progress) * 40.0;
    score += dead;

    // Last-chance bonus: strongly favor the only fitting bin, smoothly scaled
    if fitting_bins_count == 1 {
        score -= 60.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate handling: prefer opening a new bin when open bins are full-ish
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score = cap * (1.1 + progress) - 25.0 * mean_norm * mean_norm;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Slight preference for bins whose residual is above mean (keep balanced spread)
        score += 5.0 * ((bin_residual as f64 - mean_residual) / cap);
    }

    // Lookahead: if next item fits the post residual, reward this placement smoothly
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let fit_ratio = next_item_size as f64 / post;
        score -= 20.0 * fit_ratio * (1.0 - fit_ratio) * 4.0 * (0.5 + progress);
    } else if next_item_size > 0 {
        // next item cannot use the leftover: mild penalty coupled with residual size
        score += 10.0 * pr * (0.3 + 0.7 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space via capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    if post_residual == 0 {
        score -= 50.0; // perfect fit
    } else {
        let frac = post_f / cap_f;
        // Dead space thresholds: residual <=10 can be filled by smallest items,
        // <=25 by half the distribution; larger chunks are "harmonically useful".
        if post_residual <= 10 {
            score -= 12.0; // small dead space is acceptable
        } else if post_residual <= 25 {
            score -= 4.0;
        } else if post_residual <= 50 {
            score += 6.0; // awkward mid-class gap
        } else {
            score += 2.0; // large residual still reusable
        }
        // Modulo-style coupling: penalize residual that cannot host next item.
        if next_item_size > 0 {
            if next_item_size > post_residual {
                // next item cannot use this bin's leftover: penalize more when
                // post_residual is in an unusable band (not tiny, not large).
                if post_residual > 10 && post_residual < 40 {
                    score += 8.0;
                }
            } else {
                // next item fits exactly or nearly: reward
                let gap = post_residual - next_item_size;
                if gap == 0 {
                    score -= 25.0;
                } else if gap <= 10 {
                    score -= 10.0;
                } else {
                    score -= 3.0;
                }
            }
        }
        // integer-division harmonic classes of post_residual by 10
        let class = post_residual / 10;
        score += (class as f64) * 1.5 * frac;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad dead space
    // or no open bin fits well.
    if bin_residual == bin_capacity {
        // neutral baseline; discourage when a decent fit exists elsewhere
        if fitting_bins_count > 0 && post_residual >= 0 {
            // compare against mean residual: if some open bin is roomy, prefer it
            if mean_residual > (item_size as f64) * 1.5 {
                score += 15.0;
            } else {
                score += 3.0;
            }
        }
        // early in stream, opening bins is cheap-ish; late, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 5.0 - 5.0 * progress;
        // avoid hoarding many open bins
        score += (open_bins_count as f64) * 0.5;
    } else {
        // using existing bins reduces bin count pressure
        score -= (open_bins_count as f64).min(10.0) * 0.3;
        // favor placing into bins whose residual deviates below mean (tighter bins)
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small residuals that most items can't use
    if post_residual > 0 {
        let dead_threshold = 20.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 3.0;
        }
    } else {
        // Perfect fill reward
        score -= 25.0;
    }

    // Tight fit reward: item almost fills the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 15.0 * fill_ratio;
    }

    // Open bins pressure: discourage spreading across many bins when few items processed
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    // Mean residual coupling: prefer bins with residual close to mean (balanced usage)
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would be blocked by leaving this gap, mild penalty
    if next_item_size > post_residual && next_item_size > 0 && post_residual < next_item_size.min(20) {
        score += 5.0;
    }

    // New bin candidate: penalize slightly unless current bin would leave big dead space
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits the post residual exactly
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item fits, but penalize leftover after that
            score -= 100.0 - (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here; penalize large dead space
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize new-bin opening unless existing fit is very poor
    if bin_residual == bin_capacity {
        score += 120.0 - (bin_capacity - post_residual) as f64;
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Late in stream, be more conservative about wasted space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
