pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer filling bins tightly (penalize large residuals quadratically);
    // later, tolerate larger residuals since streams long-term favor balance.
    let poly = pr * pr / (cap * cap) * (1.0 - progress);
    score += 2.0 * poly;

    // Smooth cubic interaction: penalize residual that is too small to be useful
    // (dead space), scaled smoothly by progress.
    let dead = (1.0 - pr / cap).powi(3) * (pr / cap);
    score += 6.0 * dead * (0.5 + progress);

    // Reward tight fits: smooth exponential reward near zero post-residual.
    score -= 10.0 * (-pr / (0.25 * cap)).exp();

    // Last-chance bonus: strongly favor this bin if it is the only fitting one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Lookahead coupling: if next item fits the post-residual exactly or well,
    // reward; if post-residual is smaller than next item but nonzero, penalize.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let gap = (pr - ni) / cap;
            score -= 4.0 * (-gap * 8.0).exp();
        } else {
            score += 2.0 * ((ni - pr) / cap);
        }
    }

    // Mean-residual deviation: penalize bins far above the mean residual
    // (keeps residual distribution balanced) with smooth quadratic term.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Mild new-bin discouragement unless residual is genuinely large.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - (pr / cap)) * (0.6 + 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: strongly penalize unless existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut nb = 55.0 + 0.15 * open_bins_count as f64;
        if fitting_bins_count == 0 { nb -= 70.0; }          // no alternative: open
        if fitting_bins_count == 1 { nb -= 15.0; }          // last-chance bin exists
        if post_residual >= 10 && post_residual <= 30 { nb -= 5.0; } // roomy new bin
        if next_item_size > 0 && next_item_size >= post_residual { nb += 8.0; }
        nb *= 1.0 - 0.15 * progress;
        score += nb;
        return score;
    }

    // Harmonic class reward: post_residual landing on "nice" reusable classes
    let pr = post_residual;
    let class = pr % 10;
    let mut bonus = 0.0;
    if class == 0 { bonus += 12.0; }            // exact decade residual: highly reusable
    if pr % 20 == 0 { bonus += 6.0; }
    if pr % 5 == 0 { bonus += 3.0; }            // multiple of 5
    if class == 1 || class == 9 { bonus -= 4.0; } // awkward off-by-one dead space
    if class == 2 || class == 8 { bonus -= 2.0; }
    if pr < 10 { bonus -= 10.0; }               // tiny residual = near-wasted bin
    score -= bonus;

    // Perfect fit reward
    if post_residual == 0 { score -= 40.0; }

    // Lookahead: reward if next item fits post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 0.03 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Tightness reward: prefer bins where item fills a large fraction
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 8.0 * fill_frac;

    // Prefer bins with residual below mean (compact bins)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Early stream: be greedy with tight fits; later: conserve bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress) * (1.0 - fill_frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are unusable dead space.
    let tiny_gap = post_residual > 0 && post_residual < 10;
    if tiny_gap {
        score += 40.0 + 6.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Larger usable gaps: mild quadratic penalty above linear baseline.
        score += 0.08 * post_residual as f64 * post_residual as f64 / bin_capacity as f64;
    }

    // Reward bins whose gap still fits the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // gap likely wasted for next item too
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage opening another.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure proportional to open bins.
        score += 15.0 + 3.5 * open_bins_count as f64 + 10.0 * progress;
        // If no existing bin fits well, allow new bin occasionally.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Slight preference for filling bins with larger residuals when many bins open.
        score -= 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Mean-residual coupling: prefer bins deviating from mean residual downward
    // (consolidate space into emptier bins).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs()) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, but with diminishing returns.
    score = score.powf(1.25);

    // 2-step lookahead: reward post_residual that matches next item size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        // Perfect lookahead fit: strong bonus.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // If next item cannot fit here anyway, mild penalty for blocking nothing.
        if next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Penalize creating dead space that nothing typical can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable fragment
    }

    // Compare against mean residual: prefer bins whose residual deviates downward.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are tight.
    if bin_residual == bin_capacity {
        score = 100.0 + 0.3 * mean_residual;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin still offers lookahead room
        }
        // If many bins are open with slack, avoid opening another.
        if mean_residual > 40.0 {
            score += 30.0;
        }
    }

    // Late in the stream, consolidation matters more.
    let progress = step_index as f64 / total_items as f64;
    score -= 15.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item also fits in the post-residual, this bin
    // is doubly valuable; if the next item would NOT fit anywhere else,
    // saving space for it matters more.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 8.0;
        } else {
            // Wasted space the next item can't use: mild penalty.
            score += 0.05 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize the brand-new empty bin candidate unless the item is large
    // relative to capacity or few bins fit the item (fragmentation risk).
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        score += 25.0 - 20.0 * large_item;
        if fitting_bins_count <= 1 {
            score -= 22.0; // no real alternative anyway
        }
    }

    // Global state: many open bins with high mean residual -> encourage
    // consolidation into existing bins rather than opening new ones.
    if open_bins_count > 2 {
        score += 0.02 * (mean_residual - post_residual as f64);
    }

    // Early in the stream, be slightly more willing to keep bins flexible
    // (avoid tiny residuals); late in the stream, just fill anything.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.03 * (post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_pr = pr / cap;

    // Base: post-residual with smooth non-linear shaping (dead space penalty grows super-linearly)
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Polynomial coupling of residual with stream progress:
    // early on, large residuals are fine (bins can still fill); late, small residuals are precious
    let coupling = norm_pr * (1.0 - progress) - norm_pr * norm_pr * progress;
    score += 25.0 * coupling;

    // Tight fit reward: smooth function of post_residual relative to next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let tight = 1.0 / (1.0 + gap * gap / 50.0);
        score -= 12.0 * tight * (1.0 - 0.5 * progress);
    }

    // Last-chance bin bonus (only fitting bin): smooth urgency
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Penalize opening new bins when many are open with usable residual
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 10.0 + 5.0 * (open_f / (open_f + 5.0)) * (1.0 - progress);
        // but allow new bin when mean residual is small (bins nearly full)
        score -= 15.0 * (mean_residual / cap).min(1.0);
    }

    // Mild preference for fuller bins relative to mean residual
    score -= 3.0 * (mean_residual - pr) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space value depends on which
    // capacity fraction band the leftover falls into.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;
    let tenth = bin_capacity / 10;

    // Classify post_residual into harmonic bands via integer division thresholds.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, huge reward
    } else if post_residual < tenth {
        score -= 25.0; // near-perfect, tiny sliver
    } else if post_residual <= fifth {
        score += 5.0; // awkward small gap
    } else if post_residual <= quarter {
        score -= 10.0; // gap that fits mid-size future items
    } else if post_residual < bin_capacity / 2 {
        score += 3.0;
    } else {
        score -= 8.0; // large residual stays flexible
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.5; // tighter next-fit is better
        if post_residual == next_item_size {
            score -= 20.0; // chain of perfect fits
        }
    }
    // Penalize if next item just misses the post residual (dead space trap).
    if next_item_size > post_residual && next_item_size <= bin_residual {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 1.0 };
        score = 0.35 * cap + 20.0 * fragmentation - 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
    } else {
        // Mild preference for fuller bins among open ones.
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
        // Prefer bins whose residual deviates favorably from the mean (less fragmented).
        let dev = pr - mean_residual;
        score += 0.08 * dev;
    }

    // Modulo-flavored harmonic nudge: residuals divisible by 10 align with
    // typical item sizes, keeping future packing cleaner.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: the smaller the post_residual relative to item size, the better.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead-space penalty: post_residual too small to be useful for typical items.
    // A residual below the minimum item size (1) is impossible here, but residuals
    // below a useful threshold are dead space. Estimate useful threshold from
    // lookahead and stream statistics.
    let min_useful = if next_item_size > 0 { next_item_size.min(30) } else { 10 };
    if post_residual > 0 && (post_residual as f64) < min_useful as f64 {
        score += 25.0 * (1.0 - post_residual as f64 / min_useful as f64);
    }

    // Penalize leaving a gap that exactly misses the next item by a little (near-miss).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }
    // Reward reserving space for the next item when it fits snugly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading; when few are
    // open, encourage filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + progress * 20.0);
    score += pressure * 2.0;

    // New-bin candidate handling: an empty bin has huge residual; make it moderately
    // attractive only when no good fit exists (large mean residual waste elsewhere).
    if bin_residual == bin_capacity {
        let waste = (mean_residual - post_residual as f64).max(0.0);
        score += 10.0;               // base cost of opening a new bin
        score -= waste.min(40.0);    // discount if existing bins are wasteful
        if fitting_bins_count == 0 {
            score -= 50.0;           // must open a new bin
        }
    } else {
        // Prefer bins with residuals close to item size (minimize leftover).
        let gap = (bin_residual as f64 - item_size as f64).max(0.0);
        score += 0.5 * gap / bin_capacity as f64;
        // Favor bins below mean residual (they are the emptiest-relative waste).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit lookahead: strongly reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to how tight the two-step packing is
            let slack_after_next = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack_after_next / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize leftover dead space more aggressively
            score += 0.35 * post_residual as f64;
        }
    }

    // Relative-to-mean coupling: prefer bins whose residual is below average (tighter bins)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Penalize creating large unusable gaps (dead space below typical item sizes)
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // tiny sliver is fine (near-perfect fit)
    } else if post_residual > 0 && post_residual < 20 {
        score += 8.0; // small awkward gap
    }

    // New-bin candidate: only attractive when no open bin gives a good fit
    if bin_residual == bin_capacity {
        score += 30.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin accommodates lookahead too
        }
    }

    // Early in stream: be slightly more willing to open bins to build diversity
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus as post_residual shrinks.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * (1.0 - tight) * (1.0 - tight);

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 14.0 * (1.0 - slack / (bin_capacity as f64));
        } else if post_residual > 0 {
            // Penalize dead space the next item cannot use.
            score += 6.0 + 0.25 * post_residual as f64;
        }
    } else {
        // Last item: pure tightness, dead space no longer matters.
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // Many open bins with high mean residual: prefer reusing large-residual bins.
    if open_bins_count > 2 {
        score += 0.10 * (post_residual as f64 - mean_residual);
    }

    // Early in the stream: keep bins flexible; late: just minimize waste.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no good reuse exists.
    if bin_residual == bin_capacity {
        let reuse_pressure = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        score += 30.0 * (1.0 - reuse_pressure);
        if fitting_bins_count == 0 { score -= 40.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: wasted space, mildly super-linear to penalize large dead space.
    let mut score = pr + 30.0 * norm_pr * norm_pr * cap;

    // Stream progress coupling: later in the stream, residual waste matters more.
    let prog_coupling = progress * pr * (1.0 - progress) * 4.0;
    score += prog_coupling;

    // Tight fit reward: subtract when post_residual is small relative to capacity.
    score -= 40.0 * (1.0 - norm_pr).powi(3);

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fits_next = if pr >= n { 1.0 } else { 0.0 };
        let gap = (pr - n).abs() / cap;
        score -= 25.0 * fits_next * (1.0 - gap).powi(2);
        score += 10.0 * (1.0 - fits_next) * norm_pr;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Mean residual context: prefer bins deviating favorably from mean residual.
    score += 0.3 * (pr - mean_residual);

    // Many open bins: encourage consolidation by penalizing placements that
    // leave large residuals when bins are plentiful.
    score += (open_bins_count as f64).ln().max(0.0) * 5.0 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals that are multiples of common small item sizes are more reusable.
    let post = post_residual;
    let harmonic_bonus: f64 = if post == 0 {
        -60.0 // perfect fit: strongly reward
    } else if post < 10 {
        90.0 // dead space below min item size: heavily penalize
    } else {
        // Reward residuals that align with harmonic classes (multiples of 10/20/25)
        let mut hb = 0.0;
        if post % 10 == 0 { hb -= 12.0; }
        if post % 20 == 0 { hb -= 6.0; }
        if post % 25 == 0 { hb -= 5.0; }
        // Integer-division threshold: residual bucket by quarters of capacity
        let quarter = bin_capacity / 4;
        if post <= quarter { hb += 15.0; } // small leftover, risky
        else if post > 2 * quarter { hb -= 10.0; } // large leftover, flexible
        hb
    };
    score += harmonic_bonus;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize mildly so we prefer reusing bins,
    // but allow opening a new bin when the item barely fits an open bin
    // and would strand lots of dead space.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 20.0 * tightness;
        if post_residual < 10 && item_size >= 90 {
            score -= 25.0; // near-full item into fresh bin is fine
        }
    }

    // Lookahead coupling: if next item fits into the post residual,
    // reward this placement (enables pairing).
    if next_item_size > 0 {
        if next_item_size <= post {
            score -= 18.0;
            // extra reward for exact harmonic pairing
            if post - next_item_size < 10 {
                score -= 10.0;
            }
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Stream progression: later in the stream, be more conservative with
    // dead space (fewer chances to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post < 10 {
        score += 40.0 * progress;
    }

    // Mean residual coupling: when open bins already have lots of slack,
    // discourage creating more slack; when mean residual is low, encourage
    // filling bins tightly.
    score += (post as f64 - mean_residual) * 0.35;

    // Many open bins: prefer consolidation into existing bins.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (post as f64 / 10.0).min(3.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to be useful later are heavily penalized.
    // Assume typical items >= 10; gaps < 10 are pure waste, gaps < 20 are risky.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 + (20 - post_residual) as f64;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward tight fits relative to bin residual (high fill ratio of the gap being used).
    if bin_residual > 0 {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 15.0 * fill_ratio;
    }

    // Lookahead: if next item fits exactly in the post-residual, strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // post-residual can't fit next item: mild penalty scaled by gap size.
        score += 0.15 * (post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // the new-bin candidate has bin_residual == bin_capacity, so add a penalty there.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Slight reward for consolidating into already-open bins as they fill.
        score -= 3.0 * (1.0 - (bin_residual as f64 / bin_capacity as f64));
    }

    // Early in stream, be more willing to open bins (spread items); late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is close to the item (minimize leftover mismatch).
    let mismatch = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * mismatch;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight against mean residual pressure.
    score -= (mean_residual - post_residual as f64) * 0.25;

    if next_item_size > 0 {
        // Perfect 2-step match: this bin's post-residual exactly fits the next item.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits here: reward proportional closeness of match.
            let gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize dead space, worse when post_residual is tiny.
            let dead = post_residual as f64;
            score += 10.0 + 0.5 * (bin_capacity as f64 - dead - next_item_size as f64).max(0.0);
            if post_residual < 10 {
                score += 15.0; // nearly unusable sliver
            }
        }
    } else {
        // Last item: just minimize waste.
        score += post_residual as f64 * 0.1;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent existing fits exist.
    if bin_residual == bin_capacity {
        score += 25.0 + mean_residual * 0.3;
        if post_residual == next_item_size {
            score -= 60.0; // fresh bin enabling perfect next-item fit is fine
        }
    }

    // Late in stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty for post_residual.
    score += 0.15 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Penalize if post residual is small but nonzero and next item can't use it (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Compare against mean residual: bins below mean residual are more "committed"; prefer filling them.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Prefer reusing nearly-full bins over sparse ones when many bins are open.
    score += (open_bins_count as f64).sqrt() * 0.5 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless it's genuinely attractive
    // (late in stream, or no good fits / large item).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 30.0;
        if fitting_bins_count == 0 {
            new_bin_penalty = 0.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_penalty += 20.0; // fresh bin can host the next item too
        }
        if item_size >= 70 {
            new_bin_penalty -= 15.0; // large items pair well with fresh bins
        }
        if progress > 0.8 && post_residual as f64 / bin_capacity as f64 > 0.4 {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty;
    }

    // Mild penalty for leaving residuals in the awkward 20..40 dead zone.
    if post_residual >= 20 && post_residual <= 40 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post residual)
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: mild preference for leaving moderately usable space.
    // Late stream: strongly penalize wasted residual (dead space).
    let tightness = norm_pr * norm_pr * (3.0 - 2.0 * norm_pr); // smoothstep of residual
    score += tightness * (1.0 + 2.0 * progress) * 20.0;

    // Reward near-perfect fits super-linearly, amplified by progress
    let perfect = 1.0 - (pr / cap).powf(4.0);
    score -= perfect * perfect * 15.0 * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward residual that can still hold the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 8.0 * (1.0 - slack * slack);
        } else {
            // residual too small for next item: penalize dead space smoothly
            score += 10.0 * ((nxt - pr) / nxt);
        }
    }

    // Slight preference for bins tighter than the mean residual (fragmentation control)
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Mild penalty when many bins are open: consolidate load
    score += open_bins_count as f64 * 0.3;

    // Smooth progress-scaled bonus for using nearly-full bins
    let fill = 1.0 - norm_pr;
    score -= fill * fill * fill * 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Residuals divisible by 10 are classic-friendly; small odd residuals are dead space.
    let pr = post_residual;
    let class_penalty = if pr == 0 {
        -30.0 // perfect fit, best possible
    } else if pr % 10 == 0 {
        -8.0 // round residual, highly reusable
    } else if pr < 10 {
        25.0 // dead space below min item size
    } else if pr % 2 == 1 {
        6.0 // odd residuals slightly less flexible
    } else {
        0.0
    };
    score += class_penalty;

    // Integer-division threshold: residuals in [next_item_size, next_item_size+20)
    // are "one more item" classes; reward if next item fits exactly into class.
    if next_item_size > 0 {
        let ni = next_item_size;
        if ni <= pr {
            let fit_quality = (pr - ni) as f64;
            // lookahead fit: reward small gap, penalize large gap
            score -= 12.0 * (1.0 - fit_quality / cap);
            if pr % ni == 0 {
                score -= 6.0; // harmonic divisibility: residual is a multiple of next item
            }
        } else {
            // next item cannot follow here: mild penalty, stronger if residual is tiny
            if pr < ni {
                score += 4.0 * (ni - pr).min(20) as f64 / 20.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer opening new bins early in the stream or when
    // open bins are already tight (mean residual low).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tightness = 1.0 - (mean_residual / cap);
        let new_bin_bonus = 15.0 * (1.0 - progress) + 20.0 * tightness;
        score -= new_bin_bonus;
        // but discourage new bins when an existing bin would end near-empty anyway
        if pr <= 10 && open_bins_count > 0 && mean_residual < 25.0 {
            score += 18.0;
        }
    }

    // Fractional capacity coupling: penalize wasting more than half the bin.
    let waste_frac = post_residual as f64 / cap;
    if waste_frac > 0.5 {
        score += 10.0 * (waste_frac - 0.5);
    }

    // Many open bins: prefer consolidating into fuller bins (low residual).
    if open_bins_count > 3 {
        score += 0.15 * (open_bins_count as f64) * (bin_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1) are
    // impossible, but small residuals that no plausible future item can use are
    // dead space. Penalize gaps in the "unusable band" (post_residual < 10 and
    // post_residual > 0) very strongly; zero residual is perfect.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fill reward
    }

    // Penalize moderate dead space proportionally to how far it is from
    // typical item sizes (10..80): gaps just below a common size are wasteful.
    if post_residual >= 10 {
        let gap = post_residual as f64;
        // dead-space curvature: quadratic penalty for large leftover gaps
        score += 0.004 * gap * gap;
    }

    // Tight fit reward: the smaller the wasted fraction, the better.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Open bins pressure: discourage scattering across many bins when few bins
    // are open; encourage using existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).powf(1.3) * (1.0 - 0.5 * progress) * 0.35;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 35.0;
        } else {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        }
    }
    // Penalize if next item cannot fit in the post_residual (dead space for lookahead)
    if next_item_size > post_residual && post_residual > 0 {
        score += 12.0;
    }

    // New-bin candidate: only attractive when current bins are badly fragmented
    // (mean residual low relative to item) or no bin fits well.
    if bin_residual == bin_capacity {
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64);
        score -= 10.0 + 30.0 * fragmentation;
        // late in stream, opening bins is fine; early, prefer consolidation
        score += 15.0 * (1.0 - progress);
    }

    // Mean residual alignment: prefer bins whose residual is close to item size.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
