pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual is already the base).
    let tightness = (post_residual as f64) / (bin_residual.max(1) as f64);
    score += 10.0 * tightness;

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Dead-space penalty: residual left that is too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: penalize placements that block the next item from fitting here.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
        // Reward if the next item fits perfectly into the post-residual.
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit = (post_residual as f64) > 0.5 * (bin_capacity as f64);
        // Cost of a new bin decreases late in the stream; increases with open bins.
        score += 45.0 + 3.0 * open_bins_count as f64 - 20.0 * progress;
        if fit_pressure > 0.0 { score -= 80.0; }
        if poor_fit && fit_pressure == 0.0 { score += 25.0; }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // new bin can serve the next item too
        }
    }

    // Mild preference for bins below mean residual (balance the load).
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear interaction: residual cost modulated by stream progress
    let poly = norm_pr * (1.0 + 0.8 * progress) - 0.4 * norm_pr * norm_pr;
    score += 30.0 * poly;

    // Reward tight fits, smoothly scaled by progress
    let tightness = 1.0 - norm_pr;
    score -= (item_size as f64 / cap) * (10.0 + 20.0 * progress) * tightness;

    // Penalize dead space relative to mean residual
    score += 0.3 * (pr - mean_residual);

    // Lookahead: reward leaving space for next item (smoothly)
    if next_item_size > 0 {
        let diff = pr - next_item_size as f64;
        if diff >= 0.0 {
            score -= 8.0 * (diff / cap).min(1.0);
        } else {
            score += 2.0 * (-diff / cap);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer reusing existing bins when many are open
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (1.0 - tightness);

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 25.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // Penalize very small post_residuals that are still unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny slivers are nearly dead space
    }

    // Harmonic class: reward post_residuals in "useful" residue classes
    // Residues that pair well with common item sizes (multiples of 10, 5)
    let pr = post_residual as i64;
    if pr % 10 == 0 {
        score -= 6.0; // perfectly divisible residual
    } else if pr % 5 == 0 {
        score -= 3.0;
    } else {
        score += 2.0; // odd residues less reusable
    }

    // Integer-division threshold: post_residual in [1..=9] is dead space
    let dead_class = pr / 10; // 0 => dead space class (post_residual 0..9)
    if dead_class == 0 && pr > 0 {
        score += 10.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 5.0 {
                score -= 12.0; // near-perfect chain
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; penalize more if post_residual is small
            if post_residual < 20 {
                score += 5.0;
            }
        }
    }

    // Last-chance bonus: only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default
    if bin_residual == bin_capacity {
        // Prefer opening a new bin only when existing fits are bad
        // (high post_residual waste elsewhere or few fitting bins)
        score = 45.0
            - (fitting_bins_count as f64) * 2.0
            + (post_residual as f64) * 0.1;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 3.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64) * 0.05;

    // Slight phase adjustment: early on, be pickier about tight fits
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - phase);

    // Tie-break toward bins below mean residual (consolidate small leftovers)
    if (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a realistic item are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 + 0.3 * slack;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the leftover: leftover is likely dead space.
        score += 8.0 + 0.2 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Penalize the brand-new empty bin candidate unless current bins are
    // fragmented (mean residual low relative to what a fresh bin offers).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation < 0.25 {
            score -= 10.0;
        } else {
            score += 15.0 + 30.0 * fragmentation;
        }
    }

    // Slight preference for tighter existing bins (smaller residual before).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward leaving almost nothing behind.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 400.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post_residual, this placement chains perfectly -> big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 3 {
            score -= 250.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 80.0;
        } else if post_residual < next_item_size {
            // Dead space relative to the lookahead item: penalize proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.6 * dead;
        }
    }

    // Reward bins that are already relatively full (small residual before placement)
    // to consolidate waste into few bins rather than spreading it.
    let fullness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * fullness;

    // Compare post_residual against mean residual: leaving less than average
    // leftover is good (tighter packing than the fleet average).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= 30 {
        score -= 200.0;
    }

    // Penalize creating large unusable gaps that few future items (10..100) can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0; // tiny sliver is dead space
    }

    // Early in the stream, be slightly more willing to open bins with room;
    // late in the stream, squeeze into existing bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * (1.0 - progress) * (post_residual as f64) / (bin_capacity as f64);

    // Many open bins: discourage spreading; prefer tight fits even more.
    if open_bins_count > 8 {
        score += 0.3 * (open_bins_count as f64 - 8.0);
    }

    // New-bin candidate: opening a fresh bin is only attractive when the item
    // is large relative to capacity (poor fit elsewhere likely) or no tight fit exists.
    if bin_residual == bin_capacity {
        score += 60.0;
        if item_size >= 70 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: reward if next item fits into post-residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space that next item cannot use
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize creating small unusable residuals (below minimum plausible item size)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate: mildly discourage unless current fits are poor
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count <= 1 {
            score -= 35.0; // opening a new bin is fine when alternatives are bad
        }
    }

    // Tightness coupling: reward high fill ratio of this bin
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    // Global state: many open bins -> prefer filling existing ones
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: later in stream, waste matters more
    let t = step_index as f64 / total_items.max(1) as f64;
    score += t * 0.1 * post_residual as f64;

    // Mean residual coupling: if open bins are already full-ish, keep them tight
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    let mut score = pr;

    // Tight-fit reward: smooth quadratic coupling of post_residual with item size
    let fit_quality = 1.0 - pr / cap;
    score -= fit_quality * fit_quality * (item_size as f64) * 0.6;

    // Lookahead coupling: reward if next item fits into post_residual (smooth Gaussian-like)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        let match_term = (-diff * diff / (2.0 * 25.0 * 25.0)).exp();
        score -= match_term * nx * 0.5;
        // Penalize post_residuals just below next item (near-miss dead space)
        if diff < 0.0 {
            score += (-diff) * 0.15 * (1.0 - progress);
        }
    }

    // Last-chance bonus: this is the only fitting bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0 + 20.0 * (1.0 - progress);
    }

    // Stream-progress coupling: later in stream, prefer filling existing bins (penalize new bins)
    let progress_coupling = progress * progress * 40.0;
    if is_new_bin {
        score += 10.0 + progress_coupling + 5.0 * (open_bins_count as f64).sqrt();
    } else {
        // Mild preference for bins with residual below mean (consolidate small leftovers)
        score += (pr - mean_residual) * 0.05 * progress;
    }

    // Smooth non-linear dead-space penalty: exponential growth for tiny residuals
    score += 15.0 * (-pr / 10.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exact fill is perfect.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: classify by integer division thresholds.
    let r = post_residual;
    let class = r / 10; // 0..=10 harmonic class
    // Small residuals are valuable if reusable; large residuals are dead space.
    // Penalize dead space in mid classes unless next item fits.
    let next_fits = next_item_size > 0 && next_item_size <= r;
    let next_fits_current = next_item_size > 0 && next_item_size <= item_size.max(1) && next_item_size <= r;

    // Reward if the lookahead item fits into post_residual (chain packing).
    if next_fits {
        let slack = (r - next_item_size) as f64;
        score -= 60.0 - 0.5 * slack;
    } else if next_item_size > 0 {
        // Lookahead can't use this residual: penalize residual that is dead weight.
        score += (r as f64) * 0.6;
    }

    // Modulo-arithmetic penalty: residuals that are "awkward" (not multiples of 5
    // and not >= 50 usable chunks) get a bump.
    if r % 5 != 0 && r < 50 {
        score += 8.0;
    }

    // Class-based dead-space penalty: class 1..3 (10..39 residual) is the worst
    // zone — too small for most items, too big to ignore.
    if (1..=3).contains(&class) && !next_fits {
        score += 25.0;
    }
    // Class 0 (residual < 10) is nearly perfect fill.
    if class == 0 {
        score -= 20.0;
    }
    // Large residual (>= 50) is still flexible.
    if r >= 50 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current bin's post-fit residual would be very tight (good) — otherwise the
    // empty-bin candidate should be penalized so we reuse open bins.
    if bin_residual == bin_capacity {
        // Empty bin: base score is full capacity residual; add pressure to prefer
        // existing bins unless existing fits are very poor.
        score += 30.0;
        // If many bins are open, discourage opening another.
        score += open_bins_count as f64 * 2.0;
        // Early in stream, a fresh bin is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 20.0;
    } else {
        // Existing bin: reward reuse, scaled by how much residual we consume.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score -= fill_frac * 15.0;
        // Prefer bins below mean residual (tighter bins absorb items better).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Small overall preference for bins whose residual is close to item size.
    let diff = (bin_residual as i64 - item_size as i64).abs() as f64;
    score -= 10.0 / (1.0 + diff * 0.1);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
