}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small dead space).
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 8 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // can exactly or nearly host the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap == 0 {
            score -= 55.0; // perfect 2-step chain
        } else if (gap as f64) <= 5.0 {
            score -= 30.0;
        } else if (gap as f64) <= 15.0 {
            score -= 12.0;
        } else {
            // next item cannot fit: dead-space penalty scaled by gap
            score += (gap as f64 - 15.0).min(40.0) * 0.4;
        }
        // If next item fits in post_residual, mildly prefer larger left-over
        // flexibility relative to mean residual of open bins.
        if (next_item_size as f64) <= post_residual as f64 {
            score -= 8.0;
        }
    } else {
        // Last item: pure best-fit behavior.
        score -= 20.0;
    }

    // Relative-to-mean-residual coupling: bins tighter than average are
    // more valuable to fill now.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Penalize new-bin candidate (residual == capacity) mildly, but less
    // so when many bins are open and fragmented, or item is huge.
    if bin_residual == bin_capacity {
        let fragmentation = open_bins_count as f64 / (open_bins_count as f64 + 3.0);
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 35.0 - 20.0 * fragmentation - 15.0 * big_item;
    }

    // Late in stream: consolidate harder (prefer filling existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: small post residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 30.0;

    // Lookahead: penalize leaving residual that cannot fit next item,
    // reward leaving residual that exactly fits next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 / (1.0 + gap);
        } else {
            // dead space for the next item
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize many open bins with high mean residual (fragmentation pressure)
    score += open_bins_count as f64 * 2.0;
    score += mean_residual * 0.1;

    // Progress-dependent behavior: early on, encourage consolidation;
    // late in stream, prefer tightest fit even more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * 3.0;
        if fitting_bins_count == 0 {
            score -= 300.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: penalize post residual, modulated smoothly by stream progress.
    let mut score = pr * (0.6 + 0.8 * progress * progress);

    // Non-linear coupling: quadratic dead-space penalty grows late in the stream.
    score += cap * 0.5 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Reward tight fits (small post residual) with a smooth cubic bonus.
    let tightness = 1.0 - norm_pr;
    score -= 15.0 * tightness * tightness * tightness;

    // Last-chance bin: reward strongly if only one bin fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: reward if next item fits well in the resulting residual.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (pr - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty scaled by wasted potential.
        score += 4.0 * (next_item_size as f64 - pr) / cap;
    }

    // Prefer spreading load when many bins are open; penalize crowding.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Mean-residual coupling: bins far from mean residual get smoothed penalty.
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin, more so early.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: residuals divisible by large
    // divisors of capacity are more reusable (e.g. 0, 25, 50, 20, 10).
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -60.0 // perfect close
    } else if pr % 50 == 0 {
        -25.0
    } else if pr % 25 == 0 {
        -18.0
    } else if pr % 20 == 0 {
        -15.0
    } else if pr % 10 == 0 {
        -10.0
    } else if pr % 5 == 0 {
        -5.0
    } else {
        0.0
    };
    score += class_bonus;

    // Lookahead: if next item exactly fills post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 70.0;
        } else if next_item_size <= pr {
            // next item fits: mild reward scaled by fill fraction of remaining
            let fill = next_item_size as f64 / pr as f64;
            score -= 15.0 * fill;
        } else {
            // next item won't fit here: penalize small dead residuals more
            let waste = (pr as f64 / cap).min(1.0);
            score += 10.0 * waste;
            // harmonic coupling: penalize if next item's class clashes with pr
            if next_item_size % 10 != 0 && pr % 10 != 0 {
                score += 6.0;
            }
        }
    }

    // Tightness reward: fraction of bin used by this item.
    let tight = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tight;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 2 {
        score += 4.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // this fit would leave a large awkward residual and mean residual is low.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = (pr as f64 > 0.0 && pr < 10) || (pr > 0 && pr % 10 != 0 && pr < 20);
        let pressure = mean_residual < item_size as f64;
        if progress > 0.25 && (awkward || pressure) && fitting_bins_count <= 2 {
            score -= 45.0; // prefer a fresh bin over a poor fit
        } else {
            score += 25.0; // keep using open bins otherwise
        }
    }

    // Mild penalty for leaving residual below the smallest item class.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Penalize many open bins with high mean residual (fragmentation signal).
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (1..=9) are almost unusable
    // for items >= 10 in classic streams; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        // Moderate dead space: mildly penalized, scaled by how "wasteful" it is.
        score += 0.35 * (post_residual as f64 - 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // bins rather than spreading; penalize placements leaving large residuals
    // proportionally to open_bins_count.
    score += 0.08 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's post-residual diverges from the mean,
    // prefer bringing residuals closer together (harmonized closing potential).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead (k=2): if the next item fits exactly into the post-residual,
    // this placement is excellent; if the next item would NOT fit in the
    // post-residual, the leftover is dead space for the near future — penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += 0.4 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when the item is large or no good existing fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened for large items.
        score += 55.0 - 40.0 * fill_ratio;
        // If many open bins already, opening yet another is worse.
        score += 2.0 * (open_bins_count as f64);
        // If other bins fit, discourage the new bin more strongly.
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly fills the post residual,
    // this placement is ideal — reward heavily.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score -= 200.0 / (1.0 + diff as f64);
        // Penalize post residual that is just barely too small for next item
        if post_residual < next_item_size && post_residual > 0 {
            score += 30.0 + (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: bins already tight are better targets
    // for large items; loose bins better for small items.
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.5 * mean_gap;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it costly unless current bins are all poor fits
    // (large item relative to residuals). Base penalty keeps open bins preferred.
    if bin_residual == bin_capacity {
        score += 120.0;
        // If item is large and mean residual is small, opening a new bin is wise.
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 180.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }
    }

    // Slight preference for tighter bins overall.
    score += 0.1 * (bin_capacity - bin_residual) as f64 * -1.0;

    // Late-stream consolidation bias: fewer open bins is better near the end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual (lower score = better).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness;

    // Penalize dead space: post-residual that is small but unusable relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: if the next item exactly fits the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            // Post-residual can still host next item: mild reward, scaled by how snugly.
            score -= 2.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // Post-residual cannot fit next item: penalize proportional to wasted potential.
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 12.0;
        // Cheaper to open new bins early in the stream (long horizon ahead).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If many open bins with high mean residual, opening new bins is wasteful.
        score += 0.05 * open_bins_count as f64 + 0.1 * mean_residual;
        // If next item is large, a fresh bin offers flexibility.
        if next_item_size > 50 {
            score -= 5.0;
        }
    }

    // Prefer filling bins that are already relatively full (reduce bin count pressure).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 4.0 * fill_ratio;

    // Mild penalty for many open bins when this bin's fit is mediocre.
    if open_bins_count > 5 && post_residual > item_size {
        score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, softly normalized by capacity
    let mut score = pr;

    // Non-linear polynomial coupling of residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += 12.0 * pr_norm * pr_norm * (0.5 + progress);
    score -= 8.0 * pr_norm * (1.0 - progress) * (1.0 - progress);
    score += 6.0 * prog3 * pr_norm * pr_norm * pr_norm;

    // Penalize dead space relative to mean residual (smooth interaction)
    let mean_norm = mean_residual / cap;
    score += 5.0 * (pr_norm - mean_norm) * (pr_norm - mean_norm) * (1.0 - progress);

    // Lookahead: reward if next item fits in post residual (smooth quadratic)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = pr - nxt;
        if fit_gap >= 0.0 {
            score -= 10.0 * (fit_gap / cap) * (1.0 + progress);
        } else {
            score += 4.0 * ((-fit_gap) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for too many open bins late in stream
    score += 0.5 * open_bins_count as f64 * prog2;

    // Reward tight fits (small post residual) with smooth saturating term
    score -= 20.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue classes modulo 10 / 20
    let class = post_residual % 20;
    let small_class = post_residual % 10;
    // Penalize awkward residual classes (dead space far from reusable sizes)
    score += match class {
        0 => -6.0,
        1..=5 => 2.0,
        6..=9 => 4.0,
        10 => -3.0,
        _ => 3.0,
    };
    if small_class == 0 { score -= 2.0; }

    // Exact/tight fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead: does next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else {
            score += 3.0;
            // next item would fit a fresh bin exactly
            if next_item_size == bin_capacity {
                score += 4.0;
            }
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = if next_item_size > 0 { (post_residual as f64) < next_item_size as f64 } else { false };
        score = cap * 0.9 + 10.0 * progress;
        if poor_fits { score -= 15.0; }
        if fitting_bins_count <= 1 { score += 30.0; }
    }

    // Prefer filling bins far below mean residual (balance toward tighter bins)
    score -= 0.05 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Pressure term: more open bins -> stronger urge to consolidate into existing bins
    let pressure = open_bins_count as f64;

    // Perfect fit: heavily reward zero waste, scaled by open-bin pressure
    if post_residual == 0 {
        score -= 30.0 + pressure * 2.0;
    }

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item are "dead". Penalize proportionally to how
    // close to zero they are, amplified when many bins are already open.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * (2.0 + pressure * 0.4);
    }

    // Lookahead coupling: if this placement leaves room for the next item,
    // reward it; if it strands a gap smaller than the next item, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 6.0 + pressure * 0.2;
        }
    }

    // Brand-new empty bin candidate: opening a bin is costly, especially
    // when many bins are already open. Make the empty bin less attractive.
    if bin_residual == bin_capacity {
        score += 12.0 + pressure * 1.5;
    }

    // Last-chance bin: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mild stream-progression term: slightly favor tighter fits later on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 1000.0; // perfect chain: item + next item fill bin exactly
        } else {
            // penalize based on mismatch between leftover and next item
            score += (diff as f64).powi(2) * 0.05;
            // small bonus if next item still fits in leftover
            if next_item_size <= post_residual {
                score -= 5.0;
            } else {
                // leftover too small for next item: dead space penalty
                score += (post_residual as f64) * 0.3;
            }
        }
    }

    // Reward tight fits relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Penalize creating small unusable residuals (below minimum plausible item size ~1)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny dead space is nearly useless
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current open bins are crowded
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 40.0;
        // but if open bins have low mean residual (little space left), new bin is good
        score -= (mean_residual / bin_capacity as f64) * 60.0;
        // if no existing bin fits (this is the only "fitting" candidate), open new bin
        if fitting_bins_count <= 1 {
            score -= 100.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Slight preference to keep residuals near the mean (balance across bins)
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            // residual becomes waste relative to lookahead
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        } else {
            // residual can host next item: reward proportionally
            let usable = (post_residual - next_item_size) as f64;
            score -= 0.25 * usable.min(20.0);
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // (large post_residual in existing bins) or many bins are already open.
    if bin_residual == bin_capacity {
        let pressure = (post_residual as f64) / (bin_capacity as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins mildly; relax penalty late in the stream or when open bins are crowded.
        score += 18.0 - 10.0 * progress - (open_bins_count as f64).min(10.0) * 0.5;
        // If this fresh bin would give a great post-residual for the next item, reduce penalty.
        if next_item_size > 0 {
            let gap = (bin_capacity - next_item_size) as f64;
            if gap.abs() < 5.0 {
                score -= 6.0;
            }
        }
        let _ = pressure;
    }

    // Prefer bins below the mean residual (fill emptier bins first when similar).
    let res = bin_residual as f64;
    if res > mean_residual {
        score += 0.15 * (res - mean_residual);
    } else {
        score -= 0.10 * (mean_residual - res);
    }

    // Slight preference for larger residuals early (keep small residual bins for small items).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.2 * (1.0 - progress) * (res / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear penalty for large dead space, scaled by stream progress
    let norm_pr = pr / cap;
    score += 8.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits (low post residual) more strongly early on
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when many open bins exist
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * (open_bins_count as f64).sqrt() + 15.0 * (1.0 - progress);
    }

    // Lookahead coupling: favor residual that still fits the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 5.0 * (ni / cap) * (1.0 - (pr - ni) / cap).abs();
        } else {
            score += 3.0 * (ni - pr) / cap;
        }
    }

    // Mean residual alignment: prefer bins whose residual is near the mean
    score += 1.5 * (pr - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod capacity fractions
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Penalize residuals in "dead zones": too small for typical items (1..100 unknown,
    // assume small items >= 10 likely) but nonzero. Harmonic class via integer division.
    let class = post_residual / 10; // 0..10 classes
    match class {
        0 => score += 40.0,                      // near-perfect fill, excellent
        1 => score -= 6.0,                       // 10-19 residual: usable by small items
        2 => score -= 10.0,                      // 20-29: sweet spot
        3 => score -= 12.0,                      // 30-39: very flexible
        4 => score -= 9.0,
        5 => score -= 6.0,
        6 => score -= 3.0,
        7 => score -= 1.0,
        8 => score += 4.0,                       // 80-89: mostly wasted
        9 => score += 8.0,
        _ => {}
    }

    // Modulo-25 harmonic band: residuals near multiples of 25 pair well with common sizes
    let m = post_residual % 25;
    if m == 0 { score -= 8.0; }
    else if m <= 5 { score -= 3.0; }
    else if m >= 20 { score -= 2.0; }

    // Lookahead: reward if next item fits exactly or well in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect pair
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize large leftover less if bin almost full anyway
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: only prefer fresh bin when current fit is terrible
    if bin_residual == bin_capacity {
        // fresh bin: baseline attractive unless an open bin gives a tight fit
        score = 55.0 + item_size as f64 * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits, must open
        }
    } else if fitting_bins_count == 1 {
        // avoid opening new bin when this is the only fitting one
        score -= 10.0;
    }

    // Tightness reward: exact or near-exact fit
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Mild pressure to consolidate when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * (1.0 - frac) * 2.0;

    // Late-stream: encourage tighter packing as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (100.0 - pr) * 0.05;

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    // Define "unusable" as a gap smaller than the smallest plausible item (1..100 range -> gap < ~10
    // is nearly dead; gaps that cannot fit the next item are also dead if nothing else arrives).
    let gap = post_residual as f64;

    // Hard dead space: gap below minimum item size threshold.
    if post_residual < 10 {
        score += 60.0 * (10.0 - gap);
    }

    // Quasi-dead space: gap too small for the lookahead item when the next item is real.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 * (next_item_size as f64 - gap);
    }

    // Reward perfect / near-perfect fills strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Reward residual matching the next item (chain fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Tight fit reward: item consumes most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Open-bins pressure: when many bins are open, prefer consolidating into existing bins
    // (penalize the new-bin candidate more as open_bins_count grows).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty plus pressure; allow it only when it creates
        // a large usable residual and few alternatives exist.
        score += 30.0 + pressure;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: must open a new bin
        } else if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 1 {
            score -= 25.0; // opening a bin that can host the next item may be wise
        }
    } else {
        // Existing bin: slight reward when it is the last fitting bin (avoid opening new bins).
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Prefer bins with residuals close to the item (best-fit flavor).
        score += 0.1 * (bin_residual as f64 - item_size as f64).abs();
    }

    // Mild mean-residual coupling: bins far from the mean residual are slightly less preferred.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item
    if next_item_size > 0 {
        let post = post_residual as f64;
        let next = next_item_size as f64;
        let diff = (post - next).abs();

        // Perfect fit for the next item: strong reward
        if diff < 0.5 {
            score -= 60.0;
        } else if diff < 5.0 {
            score -= 40.0 - diff * 4.0;
        } else if next > post {
            // next item cannot fit here: penalize proportionally to wasted potential
            score += (next - post).min(50.0) * 0.8;
        } else {
            // next item fits but poorly: mild penalty on leftover after next placement
            let after_next = post - next;
            score += after_next * 0.3;
        }
    }

    // Reward bins tighter than the mean residual (good packing), penalize loose bins
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating small unusable dead space (1..10) that nothing may fill
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Perfect closure: zero residual is ideal
    if post_residual == 0 {
        score -= 50.0;
    }

    // New-bin candidate: keep it neutral-ish; only prefer it when current bin would
    // leave a large, unusable residual and the item is large
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.7 * bin_capacity as f64;
        let bad_fit = (post_residual as f64) > 0.0 && (post_residual as f64) < 10.0;
        if large_item || bad_fit {
            score -= 15.0;
        } else {
            score += 10.0;
        }
    }

    // Slight early-stream preference to consolidate into fewer bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but super-tight fits get a bonus.
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if post_residual < 10 {
        score -= 12.0; // near-perfect, dead space unlikely usable
    } else if tightness < 0.2 {
        score -= 5.0;
    }

    // Penalize leaving residuals that nothing typical can use (small dead zones).
    if post_residual > 0 && post_residual < 10 {
        score += 0.0; // already rewarded; dead space <10 is nearly unusable
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.0; // moderately awkward residual
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chaining placements).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits but not perfectly: mild reward proportional to fit quality
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 8.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this residual: penalize leaving mid-range dead space
        if post_residual < 25 {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Penalize opening a new bin mildly, more so when many bins are already open
    // (consolidation pressure) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 15.0 + 4.0 * open_pressure + 10.0 * progress;
        // But if the item is large and mean residual across open bins is small,
        // a new bin may genuinely be needed — soften the penalty.
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 18.0;
        }
    }

    // Global state coupling: prefer bins whose residual is close to the mean
    // residual (keeps open bin residuals uniform, easier for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for bins with larger residual when item is small
    // (save tight bins for larger items), scaled by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if item_size <= 30 {
        score += (1.0 - progress) * 0.10 * (bin_capacity - bin_residual) as f64;
    }

    // Time horizon: late in the stream, prioritize exact/near-exact fills even more.
    if progress > 0.8 {
        if post_residual <= 15 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
