        // Base penalty for opening a new bin.
        score += 12.0 + 0.5 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (future items can fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        // If the item is large relative to capacity, a fresh bin is more attractive.
        score -= 0.05 * item_size as f64;
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size > 50 {
            score -= 6.0;
        }
    }

    // Late-stream urgency: waste less as the stream ends.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on wasted space (post residual)
    let mut score = pr * (1.0 + norm_pr);

    // Smooth non-linear coupling of post-residual with stream progress:
    // late in the stream, tight fits matter more (dead space is unrecoverable)
    let progress_coupling = (norm_pr * norm_pr) * (1.0 - progress) + (norm_pr * norm_pr * norm_pr) * progress;
    score += 40.0 * progress_coupling;

    // Reward near-perfect fits with a smooth saturating term
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness;

    // Lookahead: if the next item fits the post-residual, reward this placement smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs();
        let fit_quality = 1.0 - (fit_gap / cap).min(1.0);
        score -= 30.0 * fit_quality * fit_quality * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * (1.0 - progress);
    }

    // Penalize spreading load thin when many bins are open and mean residual is high
    let mean_norm = mean_residual / cap;
    score += 10.0 * mean_norm * (open_bins_count as f64).sqrt() * 0.1;

    // New-bin candidate handling: empty bin gets a mild penalty that decays
    // with progress and shrinks when its residual is the only large one
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 15.0 * (1.0 - progress) + 5.0 * openness;
        // late stream: opening fresh bins is relatively cheaper
        score -= 20.0 * progress * progress;
    }

    // Small smooth tie-breaker coupling bin fill level with progress
    score -= 5.0 * (1.0 - (bin_residual as f64 / cap)) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the residual after placement ---
    // Classify post_residual into capacity-fraction classes (0, <=25, <=50, <=100)
    let cap_f = bin_capacity as f64;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;

    // Dead-space penalty grows non-linearly once residual falls into a
    // "useless" harmonic class (too small for typical future items).
    if post > 0 && post < 10 {
        score += 40.0; // unusable sliver
    } else if post < quarter {
        score += 8.0 + 0.15 * (quarter - post) as f64;
    } else if post < half {
        score -= 3.0; // sweet spot: half-ish residual is reusable
    } else {
        score -= 1.0; // large residual: fine but wasteful now
    }

    // Perfect fit reward: post_residual is an exact fraction of capacity
    if post == 0 {
        score -= 60.0;
    } else if bin_capacity % post == 0 && post <= half {
        score -= 20.0; // harmonic divisor of capacity (e.g. 50, 25, 20, 10)
    }

    // Modulo-class coupling with the lookahead item (k=2).
    if next_item_size > 0 {
        if next_item_size <= post {
            // Next item fits exactly or with harmonic residue
            let r2 = post - next_item_size;
            if r2 == 0 {
                score -= 35.0;
            } else if r2 < 10 {
                score -= 12.0;
            } else if bin_capacity % r2 == 0 {
                score -= 10.0;
            }
        } else {
            // Next item will NOT fit here: penalize more when this bin
            // would otherwise be the only fitting one (last-chance trap).
            score += 6.0 + 0.1 * next_item_size as f64;
        }
        // Integer-division threshold: item + next in same capacity quarter
        if (item_size / quarter.max(1)) == (next_item_size / quarter.max(1)) && next_item_size <= post {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // Base cost of opening a new bin, softened when many bins are open
        // or stream is early (exploration phase).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut open_cost = 30.0 + 10.0 * (1.0 - progress);
        if open_bins_count > 8 {
            open_cost -= 8.0;
        }
        if mean_residual < item_size as f64 {
            open_cost -= 10.0; // open bins are all tight; new bin is good
        }
        score += open_cost;
    }

    // Mild preference for tighter bins overall (best-fit flavor)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (non-linear quadratic dead-space tax).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual >= 10 && post_residual <= 30 {
        // Usable gap: mild reward proportional to how well the next item could use it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual {
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / 10.0;
        }
    }

    // Open-bins pressure: prefer consolidating into few bins, but relax late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 - 0.5 * progress);

    // Deviation from mean residual: reward bins tighter than average (good packing).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (empty bin has huge residual; make it mediocre by default).
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * -0.5 + post_residual as f64 * 0.2;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near match: next item fits with small slack left.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 20.0;
    }
    // Penalize leftovers that the next item cannot use at all (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize residual far below the mean residual (wasting a fuller bin's potential? no:
    // favor bins with residual close to item usage; penalize bins much larger than mean).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let base = 25.0 + 0.6 * item_size as f64;
        score += if next_item_size > 0 && item_size >= next_item_size { base - 15.0 } else { base };
        // discourage new bins when many bins already open
        score += open_bins_count as f64 * 0.5;
    }

    // Late in the stream, tighten packing (prefer tight fits).
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * post_residual as f64 * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Penalize small dead space that nothing can fill later
        let t = step_index as f64 / total_items.max(1) as f64;
        let min_useful = 1.0f64;
        if (post_residual as f64) < min_useful.max(10.0 * (1.0 - t)) {
            score += 20.0 * (1.0 - t);
        }
        // Reward tight fits relative to capacity
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if the next item fits the post-residual exactly, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size > post_residual {
            // next item won't fit here; slight penalty for wasting space next item can't use
            score += 5.0;
        } else {
            // next item still fits, but leaves more fragmentation
            score += 0.1 * (post_residual - next_item_size) as f64;
        }
    }

    // New-bin candidate handling: discourage opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        // Base penalty for opening a new bin
        score += 25.0;
        // If many bins fit the item, strongly discourage new bin
        if fitting_bins_count > 1 {
            score += 30.0;
        }
        // If this is the only fitting bin (last chance), a new bin is acceptable
        score -= 40.0 * scarcity;
        // Late in the stream, prefer closing out existing bins
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * t;
        // If mean residual across open bins is small, opening new bin is more justified
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer filling bins that are already mostly full
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Mild penalty for spreading across too many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap; // in [0,1]
    let t = progress;
    // smooth polynomial interaction: dead-space penalty grows with progress
    score += 18.0 * norm_pr * norm_pr * (0.35 + 0.65 * t * t);

    // Perfect-fit reward (smooth, polynomial in post_residual)
    score -= 14.0 * (1.0 - norm_pr).powi(2) * (1.0 + 0.5 * t);

    // Tight-fit bonus: reward small but nonzero residuals, penalize mid-range waste
    let mid = 1.0 - 4.0 * (norm_pr - 0.5).powi(2); // peaks at pr = cap/2
    score += 6.0 * mid * (1.0 - t);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 8.0 * t;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns).abs();
        if ns <= pr {
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            score += 3.0 * (ns - pr) / cap;
        }
    }

    // Mean residual coupling: penalize bins far from the fleet mean (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.04 * dev * dev / (1.0 + t);

    // New-bin candidate: penalize opening a new bin early, less so late
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - t) + 4.0 / (1.0 + open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "clean" is the leftover space
    // modulo common item-size classes (10, 20, 25, 50 are natural divisors of C=100).
    let pr = post_residual as u32;
    let harmonic_bonus = if pr == 0 {
        60.0 // perfect fit
    } else if pr % 50 == 0 {
        40.0
    } else if pr % 25 == 0 {
        30.0
    } else if pr % 20 == 0 {
        25.0
    } else if pr % 10 == 0 {
        18.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Dead-space penalty: residuals that are too small for any item (1..=100,
    // practically >= 10) are wasted; penalize small nonzero residuals strongly.
    if pr > 0 && pr < 10 {
        score += 35.0;
    }

    // Nonlinear coupling: residual relative to capacity fraction classes.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * (frac * std::f64::consts::PI).sin().abs(); // mild shaping

    // Lookahead harmony: does next item fit the post residual (harmonic pairing)?
    if next_item_size > 0 && next_item_size <= pr {
        // reward, scaled by how exactly next item divides the remaining space
        let nxt = next_item_size as u32;
        let leftover = pr - nxt;
        let pair_bonus = if leftover == 0 {
            45.0
        } else if leftover % 10 == 0 {
            25.0
        } else if leftover < 10 {
            -20.0 // creates dead space, penalize
        } else {
            8.0
        };
        score -= pair_bonus;
    } else if next_item_size > pr && pr > 0 {
        // next item cannot use this residual at all: mild penalty
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are crowded
    // or the fit is bad. New bin has bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / 8.0;
        let fit_quality = (bin_residual - item_size.min(bin_residual)) as f64 / bin_capacity as f64;
        // base penalty so we prefer existing bins; reduced if bins are crowded
        // or if this bin would leave a very poor residual (bad fit).
        score += 55.0 - 8.0 * crowding - 30.0 * (1.0 - fit_quality) * progress;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (tighter bins first, classic best-fit flavor).
    score += 0.35 * (mean_residual - post_residual as f64).abs();

    // Slight preference for tighter bins overall.
    score -= 0.10 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer filling the bin as much as possible.
    let mut score = post;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (small, below the minimum plausible item size) are heavily penalized.
    // A gap that is too small for anything is worse than a gap that is zero.
    if post > 0.0 && post < 10.0 {
        score += 25.0 * (10.0 - post) / 10.0;
    }

    // Penalize mid-range dead space quadratically: a residual of 30 wastes
    // more than twice what 15 does, since fewer future items can use it.
    if post >= 10.0 && post <= 40.0 {
        let t = post / 40.0;
        score += 8.0 * t * t;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward when post_residual matches the next item size (lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 6.0; // next item fits, leaving near-dead space
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0; // dead space relative to lookahead
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> consolidate; few bins -> spreading
    // is cheap, so prefer tight fits only.
    let pressure = (open_bins_count as f64 / (1.0 + total_items as f64 / 10.0)).min(1.5);
    score += 3.0 * pressure * (post / cap);

    // New-bin candidate (empty bin): only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && (post <= 15.0 || post_residual == 0);
        // Wait: for the empty bin, post_residual == bin_capacity - item_size.
        // Evaluate the empty bin's own post-residual quality.
        let empty_post = post;
        let empty_penalty = if empty_post < 20.0 { 12.0 } else { 0.0 };
        score += 10.0 + empty_penalty;
        if good_fit_exists {
            score += 20.0; // discourage opening when an open bin fits tightly
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-match bonus: next item fits with little waste left over
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 / (1.0 + slack);
    }
    // Penalize post_residual too small for the next item (dead space)
    if next_item_size > 0 && post_residual < next_item_size {
        let deficit = (next_item_size - post_residual) as f64;
        score += 3.0 * deficit;
    }
    // Penalize small unusable leftovers (wasted dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }
    // New-bin candidate handling: only attractive when current bin fit is poor
    if bin_residual == bin_capacity {
        // base penalty so open bins with decent fit win
        score += 150.0;
        // but if no open bin fits well (large mean residual waste), new bin is fine
        let waste = mean_residual - item_size as f64;
        if waste > 30.0 {
            score -= 120.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        // if next item is huge, opening fresh bin leaves better structure
        if next_item_size >= 60 {
            score -= 60.0;
        }
    }
    // Prefer tighter bins relative to mean residual
    score -= 0.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can fill.
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 0.35 * (dead / 10.0).powi(2) * (dead / 40.0).min(3.0);
    }

    // Lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 14.0 / (1.0 + slack / 12.0);
        } else {
            // Next item cannot land here; mild penalty proportional to gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.06 * gap;
        }
    } else {
        // Last item: just minimize waste.
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when
    // existing bins would leave large unusable residuals, or bins are scarce.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 22.0;
        // Cheaper to open early in the stream or when few bins are open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 14.0 * (1.0 - progress);
        score -= 2.0 * (open_bins_count.min(10) as f64);
        // If open bins are fragmented (high mean residual spread vs item), new bin helps.
        let frag = mean_residual - item_size as f64;
        if frag > 15.0 {
            score -= 8.0;
        }
        // Never open a new bin when a near-perfect fit exists elsewhere is handled
        // implicitly: empty bin gets post_residual = 100 - item, high base score.
    } else {
        // Reward using existing bins, more so when many are open.
        score -= 1.5 * (open_bins_count.min(8) as f64) as f64;
    }

    // Slight preference for bins whose residual was already small (compact bins).
    let pre_tight = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 4.0 * pre_tight;

    // Mild noise-free tie-break on bin index proxy via mean residual alignment.
    score += 0.02 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // tight fits (small post_residual) become more valuable as the stream advances.
    let tightness = (1.0 - norm_post).powi(3);
    score -= 18.0 * tightness * (0.3 + 0.7 * progress);

    // Penalize residual exactly equal to next item's fit potential mismatch,
    // smoothly weighted by lookahead size relative to capacity.
    let look = next_item_size as f64 / cap;
    if next_item_size > 0 {
        let waste = (pr - next_item_size as f64).abs();
        score += 6.0 * waste * (1.0 - look) * (0.5 + 0.5 * progress);
        // Reward if next item fits perfectly in post residual
        let perfect = ((pr - next_item_size as f64) / cap).abs();
        score -= 10.0 * (-8.0 * perfect).exp() * (0.4 + 0.6 * progress);
    }

    // Last-chance bonus: strongly favor this bin when it is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_post * 0.5);
    }

    // Mild penalty for scattering across many open bins, smoothed.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * norm_post;

    // Penalize post_residual that is small but unusable (dead space),
    // with a smooth quadratic valley around mid-range residuals.
    let valley = (norm_post - 0.25).powi(2);
    score += 5.0 * valley * (1.0 - progress);

    // Deviation from mean residual: prefer bins below mean residual (fuller bins).
    score += 0.15 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins partitioned into capacity-fraction classes.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap_f; // 0..1

    // Reward tight fits strongly (post_residual near 0 or exactly fitting classes).
    if post_residual == 0 {
        score -= 100.0; // perfect fill
    } else {
        // Penalize post_residual that cannot accommodate any plausible item (dead space).
        // Harmonic class thresholds: quarters of capacity.
        if pr < 10.0 {
            score -= 40.0; // tiny dead space, effectively sealed bin
        } else if pr < 25.0 {
            score -= 10.0;
        } else if pr < 50.0 {
            score += 5.0;
        } else {
            score += 15.0; // leaving large residual is wasteful
        }

        // Modulo-style harmonic bonus: residuals divisible into nice classes (e.g., multiples of 5 or 10)
        if post_residual % 10 == 0 {
            score -= 6.0;
        } else if post_residual % 5 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead: if next item fits in post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward if next item exactly consumes residual class
        if next_item_size == post_residual {
            score -= 25.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty proportional to mismatch
        score += (next_item_size as f64 - pr).min(30.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current residuals are all poor.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - frac * cap_f).abs();
        // Open new bin if mean residual is small (existing bins are tight)
        score = cap_f - mean_residual * 0.8;
        if post_residual == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (bin_capacity - next_item_size) as f64 * 0.1;
        }
        let _ = mean_gap;
    }

    // Mild stream-progression coupling: later in stream, prefer consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 4.0;

    // Prefer spreading across few bins when many open.
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (<= 10) are pure waste; penalize quadratically.
    if post_residual < 10 {
        score += 60.0 + (post_residual as f64) * (post_residual as f64) * 2.0;
    } else if post_residual < 20 {
        // Small gap zone: partially unusable, penalize proportionally.
        score += (20.0 - post_residual as f64) * 2.5;
    } else {
        // Usable residual: reward proportionally to how much of the bin was filled.
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= fill_ratio * 25.0;
    }

    // Perfect or near-perfect fit bonus.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // and encourage consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * 4.0 * (0.5 + progress);
    score += pressure;

    // New-bin candidate handling: attractive early or when no open bin has
    // a decent fit; unattractive when open bins are roomy.
    if bin_residual == bin_capacity {
        score = 15.0 + pressure;
        if mean_residual < 25.0 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, prefer closing out existing bins.
        score += progress * 12.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward
    // this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    }
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Mild preference toward bins below the mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins where the item exactly fills the residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0; // near-perfect fit leaves almost no dead space
    }

    // 2-step lookahead: reward when next_item_size fits exactly into post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let diff = post_residual as f64 - next;
            if diff == 0.0 {
                score -= 500.0; // next item will exactly fill this bin
            } else if diff < 10.0 {
                score -= 150.0; // chain of near-perfect fits
            } else {
                // mild reward proportional to how well the pair packs
                score -= (bin_capacity as f64 - diff) / bin_capacity as f64 * 30.0;
            }
        } else {
            // next item cannot fit here: penalize proportionally to the shortfall
            let shortfall = next - post_residual as f64;
            score += shortfall * 0.5;
        }
    }

    // Compare against mean residual: bins already below average residual are
    // "tighter" and better candidates for tight packing.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate (empty bin): penalize so it's only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 60.0;
        // late in the stream, opening new bins is even less desirable
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 40.0;
        }
    }

    // Mild penalty for leaving large unusable gaps relative to the minimum item size.
    if post_residual > 0 && post_residual < item_size {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness of fit: reward bins where the item fills a large fraction of residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill * fill;

    // Penalize large dead space relative to capacity, nonlinearly.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * dead * dead;

    // Lookahead: if next item fits exactly in post_residual, strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            // reward proportionally to how well next item fits leftover
            let nf = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 20.0 * nf;
        } else {
            // next item cannot use leftover; penalize large leftovers
            score += 10.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless it enables a great fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If item is huge relative to capacity, a fresh bin is more attractive.
        score -= 0.2 * item_size as f64;
        // Later in the stream, prefer consolidating into existing bins.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 * t;
        // Many open bins with small mean residual: discourage new bins.
        if mean_residual < 30.0 && open_bins_count > 2 {
            score += 15.0;
        }
    }

    // Global state coupling: prefer bins whose residual deviates from the mean
    // in a way that reduces variance (place into tighter-than-average bins).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Mild preference for fewer open bins overall.
    score += 0.05 * open_bins_count as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post-residual (prefer tight fits)
    let mut score = pr;

    // Smooth non-linear penalty for large residuals (dead space), amplified with progress
    score += 30.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward high fill ratio (small post residual) with a smooth cubic term
    score -= 20.0 * (1.0 - norm_pr).powi(3);

    // Coupling: post residual vs next item size — reward residuals close to next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = (pr - nx) / cap;
        score += 15.0 * diff * diff;
        // Smooth bonus if next item fits exactly-ish
        score -= 10.0 * (-8.0 * diff * diff);
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_item);
    }

    // Penalize bins whose residual deviates from mean residual (keep balance)
    score += 5.0 * ((pr - mean_residual) / cap).abs();

    // Mild new-bin avoidance as stream progresses and many bins are open
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over

    // Penalize large leftover space that is still "unusable" for typical items.
    // Harmonic classes: k = floor(10 * frac) gives deciles of capacity.
    let class = (frac * 10.0).floor() as i32;
    match class {
        0 => score -= 8.0,          // near-perfect fit (residual < 10%)
        1 => score -= 3.0,          // good fit
        2 => score -= 1.0,
        3 => score += 2.0,
        4 => score += 5.0,          // mid-range dead space worst
        5 => score += 5.0,
        6 => score += 3.0,
        7 => score += 1.0,
        8 => score -= 2.0,          // mostly empty bin: fine, flexible
        _ => score -= 4.0,          // brand-new or nearly empty bin
    }

    // Modulo arithmetic on post_residual: residuals divisible by small harmonics (10, 20, 25)
    // are more likely to be exactly filled by future items drawn from common size classes.
    if post_residual % 10 == 0 { score -= 4.0; }
    if post_residual % 20 == 0 { score -= 2.0; }
    if post_residual % 25 == 0 { score -= 2.0; }
    // Odd/prime-ish leftovers are dead space magnets.
    if post_residual % 2 == 1 && post_residual < 20 { score += 4.0; }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 { score -= 10.0; }
            else if slack <= 25 { score -= 4.0; }
            else { score += 1.0; }
        } else {
            // next item won't fit here anyway; slight penalty for wasting the slot
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral baseline, slightly above good fits so we
    // only open a new bin when no open bin offers a decent harmonic class.
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= 60 {
            // big item coming: an empty bin is valuable insurance
            score -= 10.0;
        }
        return score;
    }

    // Tightness coupling: prefer bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.15;

    // Mean-residual coupling: if open bins are generally loose, avoid stuffing
    // this one into an awkward class; if tight overall, be greedy.
    if mean_residual < 15.0 && post_residual > 0 {
        score -= 3.0; // scarce space: use it
    } else if mean_residual > 50.0 && post_residual > 40 {
        score += 2.0; // plenty of room elsewhere; don't create mid-range dead space
    }

    // Late in the stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && post_residual < 15 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10, min item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium dead space (10..25) is hard to fill; penalize quadratically.
    if post_residual >= 10 && post_residual < 25 {
        let g = post_residual as f64;
        score += 0.35 * (25.0 - g) * (25.0 - g) / 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: reward if next item can use the leftover gap.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Extra reward for near-exact pair completion.
        if post_residual - next_item_size < 5 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap unusable by next item: penalize proportionally.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual coupling: if this bin is far below mean residual (very full bin),
    // it's precious; penalize dumping large items into it wastefully.
    if (bin_residual as f64) < mean_residual - 20.0 {
        score += 5.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 3.0;
        score = 100.0 + pressure - (fitting_bins_count as f64) * 0.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big next item: fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post residual) nonlinearly.
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly into post residual,
    // strongly favor this bin (chain of perfect fills).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            if gap == 0.0 {
                score -= 50.0;
            } else if gap <= 3.0 {
                score -= 25.0;
            } else if gap <= 8.0 {
                score -= 10.0;
            }
        } else {
            // Next item can't use leftover space at all: penalize dead space.
            score += gap * 0.5;
        }
    }

    // Compare against mean residual: bins tighter than average are worth filling.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.3;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize the brand-new empty bin candidate unless open bins are hopeless.
    if bin_residual == bin_capacity {
        let desperation = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs()
        } else {
            0.0
        };
        // Opening a new bin is only attractive late in the stream or when many bins exist.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 - 20.0 * progress - desperation * 0.4;
    }

    // Late-stream urgency: prefer closing bins tightly as the stream ends.
    if total_items > 0 && step_index + 2 >= total_items {
        score += post_residual as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    // Reward tight fits strongly (waste-aware).
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize large dead space after placement, especially if next item can't use it.
    let next_fits = next_item_size > 0 && next_item_size <= post_residual;
    if !next_fits && post_residual > 0 {
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 8.0 + 12.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);
    } else if next_fits {
        // Bonus when this placement sets up the next item nicely.
        score -= 6.0 + 4.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // Global pressure: many open bins -> consolidate into existing bins.
    score += 3.0 * (open_bins_count as f64).ln().max(0.0);

    // Compare against mean residual: bins with more room than average are better hosts.
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate logic: only attractive when item is large relative to
    // typical residual or existing fits are poor.
    if is_new_bin {
        let t = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size as f64 / bin_capacity as f64;
        // Base handicap so open bins win ties, reduced for large items / late stream.
        score += 30.0 - 25.0 * big_item - 10.0 * t;
        // If few bins can fit the item, new bin becomes more attractive.
        if fitting_bins_count <= 1 {
            score -= 15.0;
        }
        // If mean residual is small, open bins are crowded -> new bin helps.
        score -= 0.2 * mean_residual;
    } else {
        // Slight preference for bins with smaller residual (best-fit bias) beyond post_residual.
        score += 0.1 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early on: prefer tight fits (penalize large post_residual) mildly.
    // Later: dead space becomes costlier, so post_residual is weighted more.
    let w = 1.0 + 1.5 * progress * progress;
    score += w * post * (post / cap);

    // Reward near-perfect fits with a smooth quadratic bonus.
    let tightness = 1.0 - post / cap;
    score -= 8.0 * tightness * tightness * tightness;

    // Lookahead coupling: if next item fits the post-residual, reward smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (post - nxt).max(0.0);
        let compat = (1.0 - fits_next / cap).max(0.0);
        score -= 5.0 * compat * compat;
        // Penalize leaving residual just below next item size (smooth valley)
        let gap = nxt - post;
        if gap > 0.0 && gap <= 40.0 {
            let x = gap / 40.0;
            score += 6.0 * (1.0 - x) * (1.0 - x);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Mild diversification pressure when many bins are open.
    score += 0.05 * open_bins_count as f64 * progress;

    // Prefer bins whose residual is close to the item (smooth best-fit flavor).
    let fit_gap = (bin_residual as f64 - item_size as f64) / cap;
    score += 3.0 * fit_gap * fit_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // integer-division bands relative to capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residuals in awkward bands (just above small item
    // sizes) are hard to fill later. Bands via modulo arithmetic on capacity.
    let band = post_residual % (bin_capacity / 4); // 0..24 band index space
    let band_f = band as f64;
    // Penalize residuals that are "small but not tiny" (hard to reuse),
    // reward exact harmonic alignments (post_residual divisible by 25/50).
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else {
        if post_residual % 25 == 0 {
            score -= 8.0; // harmonic alignment with quarter-capacity
        }
        if post_residual % 10 == 0 {
            score -= 3.0; // alignment with min item size
        }
        if pr < 10.0 {
            score += 25.0; // unusable sliver below min item size
        } else if pr < 20.0 {
            score += 10.0 * (1.0 - pr / 20.0); // awkward small leftover
        }
        // mid-band dead space penalty, non-linear
        if band_f > 0.0 && post_residual < bin_capacity / 2 {
            score += 0.35 * band_f;
        }
    }

    // Lookahead coupling: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.10 * (post_residual - next_item_size) as f64;
        } else {
            score += 4.0; // cannot host lookahead item
        }
        // exact match with next item is a harmonic bonus
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer fuller bins overall (relative fullness coupling).
    score -= 0.15 * (cap - pr) * (cap - pr) / cap;

    // Early in the stream, keep options open: penalize near-empty re-use less
    // strongly so fragmentation is avoided later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.05 * mean_residual;

    // New-bin candidate: only attractive when existing residuals are hopeless
    // for the item + lookahead combination, or many bins are already open.
    if bin_residual == bin_capacity {
        let hopeless = mean_residual < item_size as f64 * 0.55
            && (next_item_size == 0 || mean_residual < (item_size + next_item_size) as f64);
        if hopeless && open_bins_count > 2 {
            score -= 20.0;
        } else {
            score += 45.0; // discourage opening new bins by default
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (<= 9) are pure waste; penalize heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to residual (best-fit flavor).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bins are crowded or
    // the fit here would be terrible; otherwise discourage spreading out.
    let is_new_bin = bin_residual == bin_capacity && item_size < bin_capacity;
    if is_new_bin {
        score += 45.0 * (1.0 - fit_ratio); // empty bin fit is trivially loose
        let pressure = open_bins_count as f64 / 8.0;
        score -= 30.0 * pressure.min(1.5);
        if mean_residual < item_size as f64 * 1.2 && mean_residual > 0.0 {
            score -= 20.0; // open bins are too full to be useful
        }
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
        } else {
            // next item cannot use this residual: penalize large leftover
            score += 8.0 * (post_residual as f64 / 100.0);
        }
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // fuller bins (larger item_size relative to capacity = fuller bin).
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill * (open_bins_count as f64).min(10.0) / 10.0;

    // Mild late-stream consolidation: as the stream progresses, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * post_residual as f64 / 100.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively.
    score -= (bin_capacity as f64 - post_residual as f64).max(0.0) * 0.05;

    // 2-step lookahead: if next item exactly fills the post residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        let next = next_item_size as f64;
        if (next - post_residual as f64).abs() < 1.0 {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits here too: mild reward proportional to how well it fills
            let fill = next / post_residual as f64;
            score -= 10.0 * fill;
        } else {
            // next item won't fit in the residual: penalize large leftover dead space
            score += 0.10 * post_residual as f64;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins below mean residual
    // (tighter bins), penalize dumping into already-loose bins.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize the empty new-bin candidate unless the item is large
    // or nothing sensible fits elsewhere: make new bins moderately unattractive.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if item is huge relative to capacity, opening fresh may be fine.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 10.0;
        }
        // As stream progresses, discourage opening more bins if many exist.
        if open_bins_count > 4 {
            score += 5.0;
        }
    }

    // Mild early-stream exploration bonus for new bins, decayed over time.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 2.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    let tight = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tight * tight * 40.0;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect fit: residual too small for any item
    }

    // Lookahead coupling: penalize leaving a residual that the next item
    // would exactly or nearly fill (wasting the pair opportunity), but
    // reward residuals that can absorb the next item too.
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 && gap < 10.0 {
            score -= 18.0; // this bin can also host the next item well
        } else if gap >= 0.0 {
            score -= 6.0;
        } else if post_residual as f64 > 0.0 && (next_item_size as f64 - post_residual as f64) <= 10.0 {
            score += 8.0; // residual just below next item size: dead space trap
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize bins far below mean residual when many bins are open
    // (fragmentation control): prefer bins already holding small residuals.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.35;

    // Late in the stream, prefer filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.5 && bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // New-bin candidate: only attractive when nothing fits well or many bins
    // are already heavily fragmented (high mean residual means little usable space).
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        let frag = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score = 55.0 - 35.0 * poor_fits - 20.0 * frag + 10.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin offers lookahead flexibility
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post_residual (favor tight fits).
    let mut score = norm_pr * norm_pr * 60.0 + norm_pr * 20.0;

    // Smooth polynomial coupling with stream progress: later in stream,
    // tighter packing matters more (dead space costs compound).
    let progress_coupling = (progress * progress * 30.0 + progress * 10.0);
    score += norm_pr * progress_coupling;

    // Reward bins whose post-residual is a "good" leftover: smooth reward
    // centered around residuals that could fit mid-size items, via a
    // non-linear bump on post_residual.
    let leftover_fit = (norm_pr - 0.25) * (norm_pr - 0.25);
    score -= (1.0 - leftover_fit * 4.0).max(0.0) * 8.0;

    // Lookahead: if next item fits in post_residual, reward strongly (smooth).
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / cap;
        let fits = ((norm_pr - next_norm) * 10.0).max(0.0);
        score -= (1.0 - fits.min(1.0)) * 15.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize scattering across many open bins when residuals are large.
    let mean_norm = mean_residual / cap;
    score += (open_bins_count as f64).ln() * mean_norm * 3.0;

    // New-bin candidate: mild penalty so we prefer existing bins unless
    // this bin's post-residual is very wasteful.
    if bin_residual == bin_capacity {
        score += 12.0 + progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the leftover space (modular buckets on capacity) ----
    // Class 0: post_residual is a "perfect" tiny leftover (< 10) -> almost no waste.
    // Class 1: mid-range leftovers (10..50) are the most dangerous dead space.
    // Class 2: large leftovers (>= 50) remain broadly reusable.
    let harmonic_class = if post_residual < 10 { 0 } else if post_residual < 50 { 1 } else { 2 };

    match harmonic_class {
        0 => score -= 12.0,                      // near-perfect packing, reward heavily
        1 => score += (50 - post_residual) as f64 * 0.25, // penalize awkward mid leftovers
        _ => {}
    }

    // ---- Lookahead coupling: does the leftover still fit the next item? ----
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover stays useful: reward proportional to the slack ratio
            let ratio = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * ratio;
        } else {
            // leftover is dead for the next item: penalize its full size
            score += post_residual as f64 * 0.6;
        }
        // harmonic pairing: post_residual % next_item_size near 0 means good chaining
        if next_item_size > 0 && post_residual % next_item_size.max(1) <= 2 {
            score -= 6.0;
        }
    } else {
        // last item: only absolute tightness matters
        score = post_residual as f64;
    }

    // ---- Integer-division threshold on post_residual quarters ----
    let quarter = post_residual / (bin_capacity / 4);
    score += quarter as f64 * 3.0; // slight bias toward fuller bins (smaller post_residual)

    // ---- Last-chance bin: if this is the only bin that fits, use it ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only for large items that would
        // wreck an open bin's residual, or when open bins are nearly full.
        let avg_fill_pressure = 1.0 - (mean_residual / bin_capacity as f64);
        let item_bulk = item_size as f64 / bin_capacity as f64;
        let mut new_bin_penalty = 25.0;
        new_bin_penalty -= item_bulk * 30.0;          // large items tolerate a fresh bin
        new_bin_penalty -= avg_fill_pressure * 10.0;  // crowded state favors new bins
        if next_item_size > 0 && item_size >= next_item_size {
            new_bin_penalty -= 4.0; // descending-ish order: safe to start fresh
        }
        score += new_bin_penalty.max(-5.0);
    }

    // ---- Stream progression: late in the stream, consolidate aggressively ----
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively.
    if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Penalize unusable small dead-space gaps (not zero, but too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual > 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward exact fit strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits into post_residual, bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones.
    let open_pressure = open_bins_count as f64 * 2.0;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // New bin candidate: penalize it moderately, unless current fit would leave large waste
    // or no bin fits well.
    if bin_residual == bin_capacity {
        let waste_if_here = post_residual as f64;
        let new_bin_penalty = 35.0 + open_bins_count as f64 * 1.5;
        // If placing here would waste a lot, new bin becomes attractive.
        score = new_bin_penalty - waste_if_here * 0.3;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Slight progression term: late in stream, be more conservative with dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.5;

    // Mean residual coupling: if open bins already have lots of space, avoid spreading.
    if mean_residual > 50.0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward when the next item exactly fills the post-residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain match
        } else if next_item_size <= post_residual {
            // partial fit: reward proportional to how well it fills
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill;
        } else {
            // next item cannot fit: dead-space penalty grows as post_residual shrinks
            let waste = (post_residual as f64) / (bin_capacity as f64);
            score += 30.0 * (1.0 - waste);
        }
    }

    // Penalize bins whose post-residual is below the smallest conceivable item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Relative-to-mean adjustment: prefer bins tighter than average
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Discourage opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64).sqrt() * 2.0;
        // but allow new bin if next item is large and current fits are poor
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 30.0;

    // Penalize dead space that is too small to be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item fits but leaves further slack; mild reward scaled by how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack * 0.15;
        } else {
            // next item cannot use this bin's remainder; penalize proportionally
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // later, prefer consolidation into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64) * 0.3;
    score -= progress * 6.0;

    // Global state coupling: many open bins with high mean residual -> prefer filling
    // bins below the mean residual (reducing fragmentation).
    if open_bins_count > 1 {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.12;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // or the bin is genuinely fresh and the item is large.
    if bin_residual == bin_capacity {
        score += 40.0;
        if item_size >= 60 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score += 10.0;
        }
    }

    // Slight penalty for very large post-residuals (wasteful placements).
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), smoothly scaled
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: tolerate larger residuals (bins will be reused later).
    // Late: penalize waste more aggressively.
    let poly = 1.0 + 0.8 * progress - 1.2 * progress * progress + 0.6 * progress * progress * progress;
    score += 30.0 * r_norm * r_norm * poly;

    // Reward nearly-full bins with a smooth quadratic bonus
    let tight = 1.0 - r_norm;
    score -= 25.0 * tight * tight * (1.0 + progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: penalize if the next item cannot use this bin's post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap < 0.0 {
            score += 15.0 * (-gap / cap);
        } else {
            score -= 10.0 * (gap / cap) * (1.0 - (gap / cap));
        }
    }

    // New-bin candidate handling: mildly penalize opening new bins while
    // open bins have slack, but allow it when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 40.0 - 5.0 * crowd.min(8.0);
        score += 20.0 * progress;
    }

    // Deviation from mean residual: prefer bins that reduce dispersion
    score += 5.0 * (pr as f64 - mean_residual).abs() / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect packing, strongest reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify the post_residual by its residue class
    // against common item sizes (capacity fractions / integer division bands).
    // Residuals that "pair well" with typical future items get rewarded.
    let cap_frac = bin_capacity / 4; // 25 for C=100
    let half = bin_capacity / 2;

    // Class A: post_residual is a multiple of small harmonic units (10, 20, 25, 50)
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 20 == 0 {
        score -= 4.0;
    }
    if post_residual == cap_frac || post_residual == 2 * cap_frac || post_residual == half {
        score -= 10.0; // clean harmonic residual, easy to fill later
    }

    // Class B: dead space — residual too small for the smallest plausible item (1..100 unknown,
    // but tiny residuals are nearly unusable). Penalize harshly via integer division thresholds.
    let dead_threshold = 12;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 60.0; // near-dead space
    }
    if post_residual > 0 && post_residual < 5 {
        score += 120.0; // effectively dead
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: next item exactly fills this bin too.
            if next_item_size == post_residual {
                score -= 400.0;
            } else {
                // Reward proportional to how well the next item divides the remaining space.
                let after2 = post_residual - next_item_size;
                if after2 % 10 == 0 {
                    score -= 15.0;
                }
                score -= 6.0;
            }
        } else {
            // Next item won't fit here; mildly penalize wasting a "good" residual.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer it only when open bins are crowded (high mean residual relative to item)
    // or late in the stream where many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < item_size as f64 * 1.2;
        if crowded {
            score -= 30.0; // open bins too full; new bin is fine
        } else {
            score += 90.0; // prefer reusing an existing bin with room
        }
        if progress > 0.8 && open_bins_count > 4 {
            score -= 10.0; // late stream: consolidation matters less
        }
    }

    // Tightness reward: prefer bins whose fill ratio after placement is high,
    // using a non-linear (quadratic) coupling on post_residual fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * frac * frac;

    // Slight preference for bins already below mean residual (balance spreading).
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest plausible item are wasted.
    let min_item = 1u32;
    if post_residual < min_item.max(1) + 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    }
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 1.5 * tightness * (item_size as f64);

    // Open-bin pressure: discourage spreading across many bins unless fit is excellent.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it rather than opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize unless the item is large relative to residual gap in open bins.
    if bin_residual == bin_capacity {
        let gap = mean_residual - item_size as f64;
        if gap > 20.0 {
            score -= 10.0; // open bins have plenty of slack anyway
        } else {
            score += 45.0; // prefer filling existing bins
        }
    }

    // Lookahead: favor bins whose leftover can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Mild preference for bins already below mean residual (consolidate slack).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.08;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins whose residual closely matches the item.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 45.0 * (1.0 - 4.0 * tightness).max(0.0) * (1.0 - 4.0 * tightness).max(0.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize dead space: small post-residual that can't hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits into this bin's post-residual,
    // reward the placement (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            // wasted sliver relative to next item
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
        // If next item is large, prefer keeping roomy bins for it: penalize
        // using a large-residual bin for a small item.
        if next_item_size as f64 > 0.6 * bin_capacity as f64 && bin_residual as f64 > next_item_size as f64 {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty so new bins aren't opened frivolously.
        score += 35.0;
        // Under pressure (low mean residual) or early stream, opening a bin is cheaper.
        score -= 30.0 * (1.0 - pressure).max(0.0) * (1.0 - progress * 0.5);
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size > item_size {
            score -= 10.0; // fresh bin helps fit the bigger next item
        }
    }

    // Many open bins: consolidate; prefer filling existing bins over spreading.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Prefer bins below mean residual (fill the emptier-but-usable bins) mildly.
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Time-horizon: late in the stream, prioritize minimizing leftover waste harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p = post_residual as f64 / bin_capacity as f64;
    let cap = bin_capacity as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = p * p * (1.0 + t) + p * t * t - p * (1.0 - t);
    score += 30.0 * poly;

    // Tight fit reward, smoothly modulated by progress
    let tight = 1.0 - (post_residual as f64 / cap);
    score -= 25.0 * tight.powi(3) * (0.5 + t);

    // Penalize dead space that cannot fit the next item (smooth quadratic)
    if next_item_size > 0 && post_residual > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).max(0.0) / cap;
        let wasted = (post_residual as f64).min(next_item_size as f64) / cap;
        score += 20.0 * gap * gap - 15.0 * wasted * (1.0 - t);
    }

    // Last-chance bonus with smooth saturation
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - t * 0.5);
    }

    // Crowd penalty: mildly discourage dumping into bins far from mean residual
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev * dev / (1.0 + open_bins_count as f64);

    // New-bin candidate: penalize slightly unless residuals of open bins are poor
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 8.0 - 20.0 * mean_norm * mean_norm * (0.5 + t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 define "usable" classes
    let post_class = post_residual % 10;
    let post_decile = post_residual / 10;

    // Reward residuals that fall into clean harmonic classes (multiples of 10, 25, 50)
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else {
        let clean = match post_class {
            0 => 12.0,
            5 => 6.0,
            2 | 8 => 3.0,
            _ => 0.0,
        };
        score -= clean;
        // Penalize awkward small dead space (1..9 residual) proportionally
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 2.0;
        }
    }

    // Fraction-of-capacity coupling: bins filled past 50% are valuable to keep filling
    let fill_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill_frac >= 0.5 {
        score -= 8.0 * fill_frac;
    } else {
        score += 4.0 * (0.5 - fill_frac);
    }

    // Lookahead coupling: does next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact or near-exact chain fit is highly desirable
            let chain_slack = post_residual - next_item_size;
            if chain_slack == 0 {
                score -= 45.0;
            } else if chain_slack < 10 {
                score -= 20.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: penalize more if this bin is nearly full anyway
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter fits among many candidates
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or residual is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        // default slight penalty; waived when open bins have poor residuals or stream is late
        score += 10.0 - 12.0 * progress - crowded.min(10.0);
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 15.0; // open bins are nearly dead; fresh bin is good
        }
    }

    // Mean-residual alignment: prefer bins whose residual tracks the fleet mean (keeps options open)
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // Late-stream tightening: as stream progresses, demand tighter packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Decile bonus: residual in the 10..=20 band is a classic "small item catcher"
    if post_decile == 1 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 40.0;
    } else {
        // Larger leftovers are less harmful, but still mildly penalized
        // if they fall below the smallest plausible item (dead space).
        if post_residual < 20 {
            score += 15.0 * (1.0 - post_residual as f64 / 20.0);
        }
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_frac;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // post_residual cannot host next item: mild penalty scaled by gap size
            score += 5.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Open-bin pressure: discourage spreading across many bins when few fit.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        // Last-chance bin: strongly favor using it over opening a new bin.
        score -= 25.0;
    }
    score += 0.6 * open_bins_count as f64 * (1.0 - fill_frac);

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean (below-mean residual = tighter bin, prefer it).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: empty bin gets a moderate baseline cost so
    // it only wins when open bins offer genuinely poor fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening new bins is cheaper than hoarding dead space.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: perfect match with next item is gold ---
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // exact match: strong reward
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            // closeness to next item's size is rewarded proportionally
            score -= (30.0 / (1.0 + diff / 10.0)) * 0.5;
        }
        // penalize dead space that can't fit the next item at all
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // small leftover below typical minimum item size is dead space
        if post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
    } else {
        // last item: prefer tightest fit
        score *= 1.5;
    }

    // --- relative-to-mean coupling ---
    // bins with residual below mean are "valuable" compact bins; using them
    // for a tight fit is good, but wasting them on a loose fit is bad.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.3;
    } else {
        score += (res - mean_residual) * 0.15;
    }

    // --- last-chance bin: if this is the only bin that fits, use it ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // --- new-bin candidate handling ---
    if bin_residual == bin_capacity {
        // opening a new bin is attractive when existing bins are fragmented
        // (high mean residual spread / many open bins) or the fit is loose.
        let fragmentation = (res / bin_capacity as f64) - (mean_residual / bin_capacity as f64);
        score -= 15.0 + open_bins_count as f64 * 1.5 + fragmentation * 20.0;
        // but discourage new bins early in the stream when consolidation is possible
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 12.0;
        // if next item fits perfectly in this fresh bin's residual (capacity), mild bonus
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // --- mild pressure against accumulating too many open bins ---
    score += open_bins_count as f64 * 0.4;

    // --- prefer bins whose residual is only slightly larger than the item ---
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squash the residual so small leftovers dominate.
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64).powi(2);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize new-bin candidate unless the item is large (best-fit-into-fresh-bin
    // is only attractive for bulky items or when nothing fits well).
    if bin_residual == bin_capacity {
        let bulk = item_size as f64 / bin_capacity as f64;
        score -= 25.0 * bulk; // large items justify a fresh bin
        score += 30.0 * (1.0 - bulk); // small items should use existing space
        // If many bins are already open, discourage spawning more.
        score += 2.0 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item would fit nicely in this bin's
    // post-residual, reward placing the current item here (pairing effect).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt {
            let slack = post - nxt;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: slightly penalize wasting large residuals.
            score += 5.0 * (post / bin_capacity as f64);
        }
    }

    // Global state coupling: if mean residual across open bins is large,
    // prefer consolidating into existing space (penalize new bin implicitly
    // via residual comparisons); if mean residual is small, tight fits matter more.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (mean_residual / bin_capacity as f64) * (1.0 - t);

    // Progress-based urgency: late in the stream, avoid leaving tiny fragments.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0 * (0.5 + t);
    }

    // Mild preference for fuller bins among candidates.
    score -= 0.05 * (bin_residual - post_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let r = bin_residual as f64;
    let it = item_size as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), non-linearly shaped
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Polynomial coupling of post_residual with stream progress:
    // late in stream, waste matters more (squash residuals harder)
    let progress_coupling = 1.0 + t * (1.0 - t) * 0.0 + t * t * 1.5;
    score *= progress_coupling;

    // Smooth interaction: small residuals relative to capacity are valuable late
    let fill_ratio = 1.0 - norm_pr;
    score -= 12.0 * fill_ratio * fill_ratio * (0.5 + t);

    // Reward using bins whose residual was large (consolidation), smooth cubic term
    let r_norm = r / cap;
    score -= 8.0 * r_norm * r_norm * r_norm;

    // Dead-space penalty: post residual too small to fit anything (below min item scale)
    let dead = (1.0 - pr / 10.0_f64.max(1.0)).max(0.0);
    score += 25.0 * dead * dead;

    // Last-chance bin bonus: if this is the only fitting bin, favor it strongly
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - t * 0.5);
    }

    // Lookahead: if next item fits exactly into post_residual, reward
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= 15.0 * (-diff / 20.0) * (1.0 + t);
        // penalize leaving a residual that just barely blocks the next item
        if next_item_size as f64 > pr {
            score += 5.0 * (1.0 - (next_item_size as f64 - pr) / cap);
        }
    }

    // Mean residual context: penalize adding to already-loose bins
    score += 4.0 * (r - mean_residual).max(0.0) / cap;

    // New-bin candidate: mildly discourage early opening, encourage late opening
    if bin_residual == bin_capacity {
        score += 18.0 - 14.0 * t;
        score += 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Tight-fit reward: subtract for small but usable post_residual.
    if post_residual > 0 {
        score -= 12.0 * (1.0 - (post_residual as f64) / cap).powi(3);
    } else {
        score -= 40.0; // perfect fill
    }

    // Dead-space penalty: post_residual too small for any item (min size 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic classes: reward residuals that are "friendly" multiples / classes.
    let pr = post_residual;
    if pr >= 10 {
        // residual divisible into common size classes (e.g., 10/20/25/50) is reusable
        if pr % 50 == 0 { score -= 8.0; }
        else if pr % 25 == 0 { score -= 5.0; }
        else if pr % 10 == 0 { score -= 3.0; }
        // integer-division threshold: large residual classes are more valuable
        let class = pr / 20; // 0..5
        score -= class as f64 * 2.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 10.0 + 0.05 * next_item_size as f64;
    } else if next_item_size > pr && pr > 0 {
        score += 4.0; // next item can't reuse this space
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-to-slightly-high unless open bins are congested.
    if bin_residual == bin_capacity {
        score += 15.0 - 0.5 * open_bins_count as f64;
        // prefer new bin early in stream when mean residual is low
        if mean_residual < 20.0 { score -= 10.0; }
    }

    // Slight preference for filling bins when many are open.
    score += 0.02 * open_bins_count as f64 * (1.0 - (post_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are waste.
    // Treat gap < ~12 as near-dead; penalize quadratically.
    if post_residual < 12 {
        score += (12 - post_residual) as f64 * 6.0;
    } else if post_residual > 0 && post_residual < item_size as u32 {
        // gap that next similar items likely can't use
        score += 4.0;
    }

    // Perfect fit bonus (subtraction rewards low score).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Tight fit reward: fraction of bin used.
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 12.0;

    // Lookahead: if the next item fits exactly in the post-residual, strong bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use the leftover -> dead space risk
        score += 6.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when open-bin
    // pressure is low or the item fits badly everywhere.
    if bin_residual == bin_capacity {
        // baseline for fresh bin: slightly above mid residuals
        score = cap * 0.5;
        // pressure: many open bins with small residuals -> prefer using them
        score += open_bins_count as f64 * 2.0;
        // if item is large relative to capacity, a fresh bin is fine
        score -= (item_size as f64 / cap) * 10.0;
        // early in the stream, opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
    } else {
        // open-bin pressure: with many open bins, prefer consolidating into
        // bins that already have large residuals (avoid spreading).
        if bin_residual as f64 > mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins where the item exactly fills the residual.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: quadratic in how small the leftover is relative to the
        // smallest possible item (1). Tiny leftovers are hard to reuse later.
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += (10.0 - dead) * (10.0 - dead) * 2.0;
        }
    }

    // 2-step lookahead: reward residuals that can host the next item exactly or well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < f64::EPSILON {
            score -= 500.0; // next item would perfectly fill this bin
        } else if post_residual as u32 >= next_item_size {
            // residual still usable by next item: mild reward proportional to tightness
            score -= 50.0 * (nxt / (post_residual as f64 + 1.0));
        } else {
            // next item cannot fit here: penalize, scaled by how far off we are
            score += 0.5 * (nxt - post_residual as f64);
        }
    }

    // Compare against mean residual: prefer bins tighter (smaller residual) than average.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin has maximal residual. Prefer filling
    // existing bins; only allow a new bin when existing placements would leave very
    // poor fits (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        // base handicap so open bins are usually preferred
        score += 30.0;
        // but if the best alternative would waste a lot of space, open a new bin:
        // (this is handled implicitly since poor fits get penalized above)
        if post_residual as f64 > 0.5 * bin_capacity as f64 && item_size > bin_capacity / 2 {
            score -= 60.0; // large item into fresh bin is fine
        }
    }

    // Slight progression awareness: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Next item fits here; mild reward scaled by how much room remains after.
            let second_post = post_residual as f64 - next_item_size as f64;
            score -= 60.0 - second_post * 0.8;
        } else {
            // Next item won't fit here; penalize small residuals that become dead space.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.3;

    // Deviation from mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only when alternatives are scarce or bad.
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let tight_others = (mean_residual - item_size as f64).max(0.0);
        let mut new_bin_score = 60.0 + pressure * 120.0 - tight_others * 0.4;
        // Late in the stream, avoid opening new bins slightly less aggressively.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score -= progress * 20.0;
        // If next item is large and no bin will hold both, new bin is fine.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            new_bin_score -= 50.0;
        }
        score += new_bin_score;
    }

    // Slight preference for fuller bins overall (smaller residual = better).
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post-residual with stream progress:
    // early on, waste is cheap (score ~ pr); late, waste is heavily penalized.
    let poly = pr_norm * pr_norm * (0.5 + 1.5 * progress) + pr_norm * progress * progress;
    score += 40.0 * poly;

    // Reward tight fits smoothly (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64 + 1.0);
    score -= 25.0 * tightness * (1.0 - pr_norm);

    // Last-chance bonus: only one fitting bin, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins below mean residual (balance) with smooth coupling.
    score += 0.05 * (mean_residual - bin_residual as f64) * (1.0 + progress);

    // Lookahead: if next item fits snugly in post_residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 * (1.0 - (pr - next_item_size as f64) / cap);
    }

    // Mild penalty for opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: bucket post_residual into capacity-fraction classes
    // (0..10, 10..25, 25..50, 50..100) and reward tight fits nonlinearly.
    let frac = post_residual as f64 / cap;
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 40.0; // near-perfect: tiny dead space
    } else if post_residual <= 25 {
        score -= 15.0;
    } else if post_residual <= 50 {
        score += 5.0;
    } else {
        score += 15.0; // large residual wasted on a big item
    }

    // Modulo classes: residuals divisible into small harmonics are reusable
    let m = post_residual % 10;
    if m == 0 {
        score -= 6.0;
    } else if m <= 3 {
        score -= 2.0;
    } else if m >= 7 {
        score += 3.0;
    }

    // Lookahead coupling: if the next item fits the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 4.0; // next item can't use this residual
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are crowded or this is a very poor fit elsewhere.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin: slightly worse than a decent fit
        score = cap * 0.55;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // early stream: prefer filling open bins; late: allow more bins
        score -= 20.0 * (1.0 - progress);
        if mean_residual < 20.0 {
            score -= 15.0; // open bins nearly full -> new bin reasonable
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits: must open
        }
        if next_item_size > 0 && next_item_size as f64 / cap > 0.6 {
            score -= 10.0; // big next item: keep a fresh bin available
        }
    }

    // Mild preference for bins with larger residuals (best-fit over best-fit)
    score -= 0.05 * bin_residual as f64;

    // Tie-break toward fewer open bins to encourage consolidation
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone: f64 = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 12.0;

    // Penalize bins whose residual is already small but not fully used.
    if bin_residual < item_size {
        score += 1000.0; // should not happen, safety
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidation into existing bins,
    // discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or mean residual is large.
        score += 15.0 + pressure * 4.0 + mean_residual * 0.3;
    } else {
        score -= pressure * 0.5;
    }

    // Lookahead coupling: if next item would fit into the post residual,
    // reward leaving a useful gap; otherwise penalize a gap sized just under next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && (next_item_size as i64 - post_residual as i64) <= 5 {
            score += 10.0; // tantalizing but unusable gap
        }
    }

    // Mild preference for bins with below-mean residual (pack fuller bins first).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match with next item size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: residual consumed exactly by next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits too; the closer the residual is to next item, the better.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 / (1.0 + slack / 10.0);
        } else {
            // Dead space relative to next item: penalize proportionally.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead;
        }

        // Extra coupling: if next item would also fit after a chain, small bonus.
        if post_residual >= next_item_size && post_residual - next_item_size >= 10 {
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Penalize leaving tiny unusable fragments (assuming min item size ~ small).
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    // Prefer filling bins below the mean residual (tighter bins).
    score += 0.25 * (mean_residual - post_residual as f64);

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: neutral-ish baseline; only attractive when current fit is terrible.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * mean_residual;
    }

    // Slight time-decay: early on, be a bit more exploratory with new bins.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for the smallest plausible next item.
    if post_residual < 10 {
        score += 25.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0 + 0.15 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 {
        // Reward bins that can also host the lookahead item (chaining).
        let leftover_after_next = post_residual - next_item_size;
        score -= 4.0 * (leftover_after_next as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else {
        // When many bins fit, prefer the one with the smallest residual (best-fit bias).
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is poor.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let crowd = open_bins_count as f64 / (1.0 + mean_residual.max(0.0) / bin_capacity as f64);
        let poor_fit = if post_residual < 10 { 1.0 } else { 0.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Bias toward opening fresh bins early and when the fit elsewhere is bad.
        score += 15.0 - 8.0 * poor_fit - 3.0 * (1.0 - progress) - crowd.min(6.0);
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 3.0; // room for a paired placement in the fresh bin
        }
    }

    // Mild global pressure: many open bins with large mean residual -> consolidate.
    if mean_residual > 0.5 * bin_capacity as f64 && open_bins_count > 2 {
        score -= 2.0;
    }

    // Time-horizon term: later in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Reward tight fits: quadratic decay of the fit quality bonus.
    let fit_quality = 1.0 - (pr / cap).powi(2);
    score -= 12.0 * fit_quality;

    // Lookahead: reward if next item can use the post-residual (smooth coupling).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = ((pr - nx) / cap).max(0.0);
        let slack = (pr - nx).max(0.0);
        // Exact next-item match is great; partial overlap decays smoothly.
        let match_term = 1.0 - (slack / cap).powi(2);
        score -= 6.0 * match_term * (1.0 - usable).min(1.0).max(0.0);
        // Penalize leaving a residual too small for the next item (dead space).
        let dead = if pr < nx { (nx - pr) / cap } else { 0.0 };
        score += 8.0 * dead * (1.0 - dead);
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Stream-progress coupling: as stream advances, prefer filling existing bins
    // over opening new ones; scale penalty on new bins smoothly.
    let is_new_bin = (bin_residual as u32 == bin_capacity) && post_residual == bin_residual - item_size;
    if is_new_bin {
        let openness = (open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0))).sqrt();
        score += 4.0 + 6.0 * progress * openness;
        // Discourage new bin when mean residual across open bins is large.
        score += 0.05 * mean_residual;
    }

    // Mild preference for bins whose residual is close to item (best-fit flavor),
    // smoothly via inverse of gap.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.02 * gap;

    // Slight penalty for very full bins early (keep flexibility), relaxing later.
    let fullness = 1.0 - pr / cap;
    score += 3.0 * fullness * fullness * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "useful" residue classes (small enough to be filled by typical items)
    // are preferred. Class 0 = perfect fit.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect / near-perfit fit bonus (strong subtraction).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Modulo-10 harmonic class: leftover divisible into decile classes.
    // Leftovers that are multiples of 10 are statistically easier to fill
    // exactly with items drawn from wide distributions.
    let mod10 = post_residual % 10;
    score -= match mod10 {
        0 => 40.0,
        5 => 15.0,
        _ => 0.0,
    };

    // Integer-division thresholds on post_residual: classify leftover into
    // capacity-fraction buckets. Small buckets (< 20) are dead space unless
    // near zero; large buckets are flexible.
    if post_residual < 20 {
        // dead-space penalty, scaled by how far from a fillable class
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Fraction-of-capacity coupling: leftover near capacity/2 is awkward
    // (neither small-item filler nor big-item swallower).
    let half = cap * 0.5;
    let dist_half = (pr - half).abs();
    score += 0.3 * dist_half;

    // Lookahead coupling: if the next item fits exactly into this bin's
    // post residual, strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // next item still fits afterwards: mild reward, better if
            // remaining-after-next is in a good harmonic class.
            let after_next = post_residual - next_item_size;
            score -= 30.0 + (after_next % 10 == 0) as i32 as f64 * 20.0;
            score -= 0.1 * after_next as f64;
        } else {
            // next item cannot use this leftover: penalize proportional to
            // the wasted potential.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.2 * gap;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has high post_residual.
    // Prefer it only when open bins are crowded (mean residual low) or
    // when the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 1.2;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if crowded {
            score -= 60.0; // opening fresh bin is fine
        } else {
            score += 50.0 + 30.0 * (1.0 - progress); // early on, prefer filling open bins
        }
        // Large items justify new bins more.
        score -= (item_size as f64 - cap * 0.5).max(0.0) * 0.5;
    }

    // Mild preference to spread load when many bins are open with high
    // mean residual: tight packing is still king, so keep small weight.
    score -= 0.05 * mean_residual * (open_bins_count as f64).ln().max(1.0) * 0.0;

    // Tie-break: prefer bins with residual close to item (best-fit core),
    // already largely captured, add small jitter-free refinement.
    score += 0.01 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 {
        let dead_threshold = 10.0f64;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
        // Penalize gaps that no plausible future item can use well
        if (post_residual as f64) < (next_item_size as f64) && next_item_size > 0 {
            score += 4.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 25.0;
    }

    // Reward tight fits relative to item size
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 10.0;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate score: base slightly above residual scale
        score = bin_capacity as f64 * 1.5
            + open_bins_count as f64 * 2.0
            + mean_residual * 0.5;
        // Allow opening a new bin when existing residuals are fragmented
        if mean_residual < item_size as f64 * 1.2 && fitting_bins_count > 0 {
            score -= 30.0 + progress * 20.0;
        }
    } else {
        score += open_bins_count as f64 * 0.3;
    }

    // Lookahead coupling: if next item fits in post-residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 12.0 + slack_after_next as f64 * 0.3;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot follow here; penalize proportionally
        score += 4.0 + (next_item_size - post_residual) as f64 * 0.05;
    }

    // Compare post_residual against mean residual: prefer bins ending near mean
    let mean_dev = (post_residual as f64 - mean_residual).abs();
    score += mean_dev * 0.15;

    // Penalize very small unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Slight preference for tight fits overall
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    // Early in stream: encourage consolidation into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    // New-bin candidate: only attractive when current bin would be a terrible fit
    if bin_residual == bin_capacity {
        score += 6.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact and near-exact fits (dead space elimination).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score -= (1.0 - tightness).powi(3) * 40.0;
        score += tightness * tightness * 30.0;
    }

    // Lookahead coupling: if the next item exactly fills the post-residual,
    // this placement is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= (1.0 - slack_after_next as f64 / bin_capacity as f64) * 25.0;
        } else {
            // Next item cannot use this residual: penalize wasted residual slightly.
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 + (1.0 - post_residual as f64 / bin_residual as f64) * 40.0;
    }

    // Prefer filling bins that are already relatively full (best-fit flavor),
    // scaled by how crowded the open-bin pool is.
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= fill_ratio * (10.0 + open_bins_count as f64).min(30.0);

    // If mean residual is high, we have slack elsewhere: tolerate worse fits here
    // and favor consolidation; if mean residual is low, be picky.
    score += (mean_residual - post_residual as f64) * 0.15;

    // Time horizon: early in the stream, be more willing to open/keep flexible bins;
    // late in the stream, squeeze everything tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);
    score -= progress * 12.0 * fill_ratio;

    // New-bin candidate handling: an empty bin is only attractive when no open bin
    // offers a decent fit; otherwise keep consolidating.
    if bin_residual == bin_capacity {
        let decent_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && mean_residual >= item_size as f64 * 1.1;
        if decent_fit_exists {
            score += 45.0 + mean_residual * 0.1;
        } else {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress
    let mut score = x * x * (1.0 + progress) + x * (1.0 - progress) * 0.5;

    // Reward tight fits (small post_residual) more strongly late in the stream
    score -= (1.0 - x).powi(3) * (0.5 + progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let usable = if pr as u32 >= next_item_size { 1.0 } else { 0.0 };
        score += (1.0 - usable) * nx * (1.0 + progress) * 2.0;
        // Reward leaving exactly enough room for the next item
        score -= usable * (1.0 - (pr - next_item_size as f64).abs() / cap) * 0.8;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening new bins
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5 * (1.0 - progress);
    }

    // New-bin candidate: prefer it early or when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0);
        score = 0.3 + fragmentation * (1.0 - progress) * 1.2 - progress * 0.4;
    }

    // Mild penalty for proliferating open bins
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: exact-fill classes are golden.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score -= 25.0; // near-perfect, dead space negligible
    } else {
        // modular structure: leftovers that are multiples of small units stay reusable
        if pr % 10 == 0 {
            score -= 12.0;
        }
        if pr % 5 == 0 {
            score -= 5.0;
        }
        // integer-division thresholds on post_residual
        let class = pr / 20; // 0..=4 harmonic bands
        score += class as f64 * 8.0;
    }

    // Reward tight fill fraction (capacity fractions)
    let fill = (bin_residual - pr) as f64 / cap;
    score -= fill * fill * 20.0;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits in post_residual, big bonus
    if next_item_size > 0 && next_item_size <= pr {
        score -= 18.0 + (next_item_size as f64 / cap) * 10.0;
    } else if next_item_size > pr {
        // leftover too small for next item: penalize proportionally to waste
        score += (pr as f64 / cap) * 10.0;
    }

    // Compare against mean residual across open bins: prefer bins below mean (consolidate waste)
    if (post_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Stream progression: late in stream, be greedier about tight fits
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 8.0 * fill;

    // Many open bins: encourage closing them out (prefer tighter fills more)
    if open_bins_count > 4 {
        score -= 0.5 * open_bins_count as f64 * fill;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit
    if bin_residual == bin_capacity {
        score += 45.0; // default penalty for opening a new bin
        if fitting_bins_count == 0 || (post_residual as f64) < mean_residual * 0.5 {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A residual gap is "dead" if it is smaller than the smallest plausible item (1..100 interface).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits: subtract proportional to how well the item fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening another.
    if bin_residual == bin_capacity {
        score += 20.0 + 4.0 * open_bins_count as f64;
    } else {
        score -= 2.0 * open_bins_count as f64;
    }

    // Lookahead coupling: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Early stream: be slightly more willing to open new bins (better long-run packing).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress);

    // Mean residual coupling: prefer bins far from the mean residual (restore balance).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Lookahead: reward bins whose post_residual can host the next item exactly well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here afterward: reward proportional to tightness of that follow-up fit.
            let follow_fit = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - follow_fit / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize leaving stranded space near next_item_size.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap.min(30.0);
        }
        // Exact chain match is a jackpot.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual sits near the mean (balanced packing),
    // penalize outliers that create fragmented dead space.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual >= item_size {
            0.0
        } else {
            0.0
        };
        // Baseline penalty so open bins with decent fits win; relax when many bins are open and fragmented.
        score = bin_capacity as f64 * 0.9 + poor_fit;
        if next_item_size > 0 && next_item_size >= item_size {
            // Room for the next item in a fresh bin: mild bonus.
            score -= 8.0;
        }
        // When stream is early, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted relative space nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize small dead space (unusable slivers) more than large residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Crowding: many open bins -> prefer filling existing bins over opening new.
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * crowding;

    // New-bin candidate handling: only attractive when fits are poor or bin count low.
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 && next_item_size <= 100 { 0.0 } else { 0.0 };
        let poor_fit = post_residual as f64 > 40.0 || next_item_size > post_residual;
        if poor_fit && step_index > 0 {
            score -= 10.0 + 20.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            score += 45.0 + best_possible;
        }
    }

    // Time horizon: late in stream, consolidate aggressively.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: prefer bins below mean residual (leave big gaps elsewhere).
    score += 0.15 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth polynomial coupling: reward tight fits non-linearly,
    // with the reward shape evolving smoothly over stream progress.
    let base = pr;
    let tightness_reward = -40.0 * (1.0 - x) * (1.0 - x) * (1.0 + 0.5 * progress);
    let dead_space_penalty = 8.0 * x * x * (1.0 - x) * (1.0 + progress);

    // Waste-weighted cubic term: penalize mid-size residuals more than extremes.
    let cubic = 6.0 * x * (1.0 - x) * (x - 0.5) * (x - 0.5);

    // Last-chance bonus: strongly favor using the only bin that fits.
    let last_chance = if fitting_bins_count == 1 { -25.0 } else { 0.0 };

    // Lookahead coupling: reward if next item fits into the post residual smoothly.
    let next_fits = if next_item_size > 0 && (next_item_size as f64) <= pr {
        -12.0 * (1.0 - (next_item_size as f64) / pr.max(1.0)) * (1.0 + 0.3 * progress)
    } else if next_item_size > 0 {
        5.0
    } else {
        0.0
    };

    // Congestion term: many open bins with high mean residual -> prefer filling existing bins.
    let congestion = if open_bins_count > 0 {
        -3.0 * (mean_residual / cap).min(1.0) * (open_bins_count as f64).ln().max(0.0)
    } else {
        0.0
    };

    // New-bin candidate: mildly penalize opening a new bin unless residuals are poor.
    let new_bin_bias = if bin_residual == bin_capacity {
        10.0 + 15.0 * (1.0 - (mean_residual / cap).min(1.0))
    } else {
        0.0
    };

    base + tightness_reward + dead_space_penalty + cubic + last_chance + next_fits + congestion + new_bin_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // --- Harmonic class logic on post_residual (integer division bands of 10) ---
    let class = post_residual / 10;
    match class {
        0 => score -= 6.0,                       // near-perfect fill: eliminate dead space
        1 => score -= 1.0,                       // small gap: usable only by tiny items, mildly good
        _ => score += (class as f64 - 1.0) * 0.6, // larger bands: progressively penalize slack
    }

    // Modulo-coupled penalty: residual mod 10 that no common item class absorbs
    let residue = post_residual % 10;
    if residue != 0 && class >= 2 {
        score += 0.4;
    }

    // --- Lookahead coupling with next item (k=2) ---
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            // this bin could also host the next item: strong reward
            score -= 3.0 + 0.05 * nx;
            // harmonic match: same residue class => likely chain of fits
            if (post_residual % 10) == (next_item_size % 10) {
                score -= 1.5;
            }
        } else {
            // next item won't fit here: dead space relative to lookahead
            score += (nx - pr) * 0.08;
        }
    }

    // --- Last-chance bonus: only open bin that fits the item ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 4.0;
    }

    // --- New-bin candidate handling ---
    if is_new_bin {
        // opening a new bin fragments capacity; make it costly so it wins
        // only when every existing fit would leave a poor residual
        score += 5.0 + 0.02 * open_bins_count as f64;
        // if open bins already carry plenty of slack, discourage a fresh bin
        score += mean_residual.max(0.0) * 0.05;
    } else {
        // concentrate waste: prefer bins already tighter than the mean
        if (bin_residual as f64) > mean_residual {
            score += 1.0;
        } else {
            score -= 0.5;
        }
    }

    // --- Mild stream-progression term: early on, be slightly more conservative
    //     about leaving large gaps (long horizon to exploit them later) ---
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += (1.0 - progress) * pr * 0.01;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // A residual below ~10 cannot fit any future item (min item size 1... but
    // small gaps waste capacity), so add a superlinear penalty for tiny gaps.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 25.0;
    }

    // Reward tight fits: exact or near-exact fills get strong discounts.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in the post_residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize if next item is slightly larger than post_residual (dead space ahead).
    if next_item_size > 0 && next_item_size > post_residual && (next_item_size as f64) < bin_residual as f64 {
        score += 10.0;
    }

    // Open-bins pressure: many open bins -> prefer consolidating into existing bins,
    // discourage opening new bins.
    let open_pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 40.0 + open_pressure;
    } else {
        // Reward using existing bins, scaled by how many are open.
        score -= open_pressure * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Early stream: keep bins open (fewer bins so far), mild bonus for reusing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= (1.0 - progress) * 5.0;
    }

    // Prefer bins with residuals close to item_size (good use of space).
    let waste_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += waste_ratio * 15.0;

    // Mean-residual coupling: if this bin's residual is far below mean, it's a
    // laggard bin - prefer filling it to consolidate.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.3;
    } else {
        score += (-diff) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 1-step lookahead match (post_residual == next_item_size)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward when the next item can still fit into post_residual
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (post_residual - next_item_size) as f64 * 0.3;
    }
    // Penalize dead space that the next item cannot use
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0 + (next_item_size - post_residual) as f64 * 0.2;
    }

    // Penalize small unusable residuals (dead space below minimum plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with residuals below mean (tight packing); penalize using roomy bins
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Mild pressure to keep number of open bins low early, allow more bins later
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.5 - 0.4 * progress);

    // New-bin candidate: neutral baseline, slightly discouraged unless residuals are tight
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space in
    // (0, 10) is unusable for typical items -> extra penalty.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // dead space penalty
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin
    // (chains well); if next item would fit better in a bin with more room,
    // mildly penalize wasting space here.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 6.0;
        } else if (bin_residual as f64) >= nxt && post_residual > 0 {
            // this placement destroys room needed by the next item
            score += (nxt - pr) * 0.5;
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item fits poorly everywhere else or open bins are nearly full.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 20.0; // must open a bin
        } else if fitting_bins_count == 1 {
            score += 15.0; // prefer the existing last-chance bin
        } else {
            score += 10.0 + 8.0 * (1.0 - fill); // prefer reusing well-fitting bins
        }
        // Early in the stream, having bins open is fine; later, avoid bin sprawl.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
        // Penalize opening new bins when mean residual across open bins is large.
        score += mean_residual * 0.15;
    }

    // Mild preference for bins with lower residual among comparable fits
    // (consolidation), scaled by number of open bins.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Slight pressure to keep number of open bins small.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual (tight fit), non-linearly.
    let mut score = post * (1.0 + 0.9 * norm_post * norm_post);

    // Stream-progress coupling: early on tolerate loose fits (keep bins flexible),
    // later become progressively stricter about dead space.
    let tightness = 0.5 + 2.5 * progress * progress;
    score += tightness * post * norm_post;

    // Penalize the brand-new empty bin candidate smoothly unless fits are scarce.
    let is_new_bin = (bin_residual == bin_capacity) as f64;
    let scarcity = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    let look = next_item_size as f64;
    let next_fits = (look > 0.0 && look <= post) as f64;
    let new_bin_penalty = is_new_bin * (12.0 + 30.0 * (1.0 - progress))
        - is_new_bin * scarcity * (20.0 + 40.0 * progress)
        - is_new_bin * next_fits * 8.0 * (1.0 - progress);
    score += new_bin_penalty;

    // Reward bins that can also host the lookahead item (chain fits), stronger mid/late stream.
    score -= next_fits * (1.0 - is_new_bin) * (6.0 + 14.0 * progress);

    // Reward last-chance bins (avoid opening a new bin when only this one fits).
    let last_chance = (fitting_bins_count == 1 && bin_residual != bin_capacity) as f64;
    score -= last_chance * (18.0 + 25.0 * progress);

    // Mild pressure toward consolidating into bins already below mean residual.
    let below_mean = (post > mean_residual) as f64;
    score += below_mean * 2.0 * (0.5 + progress);

    // Slight penalty when item leaves residual too small for typical future items.
    let dead = (post > 0.0 && post < 10.0) as f64;
    score += dead * (8.0 + 12.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create "dead-space classes".
    let residue_class = post_residual % 10;
    score += (residue_class as f64) * 0.35;

    // Perfect fit reward: post_residual in harmonic small classes.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Integer-division thresholds: bins whose residual stays in a "usable band"
    // (>= next_item_size) are favored.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Chain fit: next item also leaves a small remainder.
        let chain_post = post_residual - next_item_size;
        if chain_post % 10 == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Post residual too small for lookahead item: penalize dead space.
        score += 6.0 + (post_residual as f64) * 0.1;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin if current bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Penalize new bin mildly; reward when open bins are fragmented or many.
        score += 18.0 - fragmentation * 0.3 - (open_bins_count as f64) * 0.4 - progress * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 6.0; // fresh bin can host the next item cleanly
        }
    }

    // Prefer tighter bins overall (residual relative to capacity fractions).
    let frac = bin_residual as f64 / bin_capacity as f64;
    score += frac * 5.0;

    // Coupling: large items into high-residual bins.
    if item_size > bin_capacity / 2 && bin_residual > bin_capacity / 2 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 6.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - 0.5 * slack;
    }
    // Penalize if next item is slightly larger than post residual (near miss).
    if next_item_size > post_residual && next_item_size > 0 && next_item_size <= post_residual + 10 {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (3.0 + 4.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, unless it's genuinely the best option.
        score += 15.0 + pressure;
        // If mean residual across open bins is very tight, a new bin is fine.
        if mean_residual < 8.0 {
            score -= 20.0;
        }
    } else {
        // Favor filling existing bins, more so when mean residual is high.
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;
        score -= pressure * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)) * (1.0 - diff / (bin_capacity as f64));

        // Penalize leaving residuals slightly above next item (wasted dead space)
        if post_residual > next_item_size && post_residual < next_item_size + 10 {
            score += 25.0;
        }
    } else {
        // Last item: prefer minimal post residual
        score += 20.0;
    }

    // Reward near-full packing
    score -= 0.5 * (bin_capacity as f64 - post_residual as f64);

    // Penalize deviation from mean residual (avoid fragmenting the fleet)
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin bonus: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless current residuals are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let pressure = open_bins_count as f64 / (step_index.max(1) as f64 + 1.0);
        // Open new bin only when open bins are mostly full / few fitting options
        if fragmentation < 0.15 && fitting_bins_count <= 1 {
            score -= 30.0;
        } else {
            score += 40.0 + 20.0 * (1.0 - fragmentation);
        }
        let _ = pressure;
    }

    // Mild late-stream conservatism: keep residuals usable
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 500.0;
    } else {
        let pr = post_residual as f64;
        score += (pr * pr) / (bin_capacity as f64); // penalize dead space quadratically
    }

    // Reward filling bins with small residuals (close them out).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if post-residual is too small for the next item but nonzero, penalize.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) >= ni {
            score -= 25.0 * (ni / (post_residual as f64));
        } else if post_residual > 0 {
            score += 15.0 * (1.0 - (post_residual as f64) / ni);
        }
        // If next item fits perfectly in post residual, big bonus
        if post_residual as u32 == next_item_size {
            score -= 80.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity and existing bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        // Penalize new bins mildly by default; relax when bins are crowded/tight
        // and item is big (likely to leave unusable residue in a partial bin).
        let item_frac = item_size as f64 / bin_capacity as f64;
        let penalty = 70.0 - 50.0 * mean_tightness * item_frac - 20.0 * crowded * progress;
        score += penalty.max(5.0);
        // A fresh bin wastes capacity if item is small.
        score += 30.0 * (1.0 - item_frac);
    }

    // Global pressure: many open bins -> prefer consolidation into existing bins.
    if !is_new_bin {
        let pressure = (open_bins_count as f64).ln() + 1.0;
        score -= 5.0 * pressure * (1.0 - fill_ratio);
    }

    // Mild preference for bins below mean residual (balance residual spread).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.05 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let progress = progress.clamp(0.0, 1.0);

    // Smooth non-linear coupling: polynomial in progress weighting residual penalty.
    // Early in the stream, waste is cheap (many items remain to fill gaps);
    // late in the stream, every unit of residual matters more.
    let waste_weight = 0.5 + 1.5 * progress * progress; // quadratic ramp
    score *= waste_weight;

    // Perfect fit reward: smooth bell around zero post-residual.
    let pr = post_residual as f64;
    let fit_bonus = 12.0 * (-(pr * pr) / 180.0).exp();
    score -= fit_bonus;

    // Penalize residuals that are too small to ever fit another item (dead space),
    // with a smooth saturating term relative to capacity.
    let cap = bin_capacity as f64;
    let dead = (cap * 0.12 - pr).max(0.0);
    score += 6.0 * (dead / cap) * (1.0 + progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 8.0 * (-(gap * gap) / 400.0).exp();
        } else {
            // Smooth penalty for residuals slightly too small for next item.
            score += 2.0 * (gap.abs() / cap).min(1.0);
        }
    }

    // Mild pressure against accumulating too many open bins early.
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64);
    score += 3.0 * open_pressure * (1.0 - progress);

    // Tie-break toward bins with below-average residual (fill emptier bins later,
    // keep tight bins tight) — smooth interaction with mean residual.
    score += 0.05 * (mean_residual - pr);

    // New-bin candidate: make empty bin attractive only when item is large
    // relative to typical open-bin residuals, smoothly interpolated.
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / cap;
        score -= 4.0 * size_ratio * size_ratio * (1.0 + 2.0 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that combine well with
    // typical small items (multiples of 10, or small leftovers) are favored.
    let r = post_residual;
    let class_penalty = match r % 10 {
        0 => -6.0,
        1 | 2 | 3 => 4.0,
        4 | 5 | 6 => 1.0,
        _ => 2.5,
    };
    score += class_penalty;

    // Integer-division threshold: post_residual divisible into chunks usable
    // by next item is valuable.
    if next_item_size > 0 && next_item_size <= r {
        let fits_next = (r / next_item_size) as f64;
        score -= 4.0 + 2.0 * fits_next.min(3.0);
    } else if next_item_size > r && next_item_size > 0 {
        // next item cannot use this residual at all
        score += 3.0;
    }

    // Exact fit is perfect.
    if r == 0 {
        score -= 12.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if r > 0 && r < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or the
    // item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let crowded = mean_residual / bin_capacity as f64;
        let pressure = (open_bins_count as f64).sqrt() * 0.5;
        let lookahead_bonus = if next_item_size > 0 && next_item_size <= bin_capacity - item_size { 2.0 } else { 0.0 };
        score += 20.0 - 15.0 * crowded - pressure + lookahead_bonus;
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Fraction-of-capacity coupling: prefer bins whose fill fraction after
    // placement is near a harmonic multiple (1/2, 3/4, full).
    let fill = (bin_capacity - r) as f64 / bin_capacity as f64;
    let harmonic = (fill * 4.0).round() / 4.0;
    score -= 3.0 * (1.0 - (fill - harmonic).abs() * 4.0).max(0.0);

    // Mild stream-progress adaptation: later in the stream, tighten packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 2.0 * (1.0 - progress) * (r as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (1..=10) are almost unusable -> heavy penalty
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual > 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to residual)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last chance: only bin that fits -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a bin is expensive when few bins open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of a new bin, reduced late in the stream
        score += 90.0 - 40.0 * progress;
        // If many bins are open and fragmented, a fresh bin is more attractive
        score -= (open_bins_count as f64).min(20.0) * 1.5;
        // If the next item fits nicely in the fresh residual, encourage opening
        if next_item_size > 0 && next_item_size <= bin_capacity {
            let combo = item_size + next_item_size;
            if combo > bin_capacity {
                // pairing impossible elsewhere may favor new bin
                score -= 15.0;
            }
        }
        // Don't open a new bin when a near-perfect fit exists elsewhere
        if fitting_bins_count >= 1 && post_residual == 0 {
            score += 200.0;
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // next item fits: mild reward proportional to how well it fills the gap
        score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here: penalize leaving a gap that strands it
        if post_residual < 20 {
            score += 20.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones
    score += (open_bins_count as f64).min(30.0) * 0.8;

    // Prefer bins with below-average residual (more filled bins) slightly
    score += (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.84;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale post_residual by a convex factor.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 18.0 * tightness * tightness;

    // Exact or near-exact fill is highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 22.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Leftover unusable for the next item: mild penalty.
            score += 4.0;
        }
    }

    // Compare against global mean residual: prefer bins below mean residual
    // (denser bins), penalize dumping into very empty bins when alternatives exist.
    if (bin_residual as f64) > mean_residual + 15.0 && fitting_bins_count > 1 {
        score += 6.0;
    } else if (bin_residual as f64) <= mean_residual {
        score -= 3.0;
    }

    // Time horizon: early in the stream, keep bins flexible (slightly prefer
    // larger leftovers); late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 2.0 * tightness;
    score -= progress * 10.0 * tightness;

    // New-bin candidate: opening a bin is acceptable early or when the item
    // would leave a very poor fit elsewhere; otherwise discourage mildly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 12.0 };
        score += pressure + (1.0 - progress) * 4.0;
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 10.0;
        }
    }

    // Many open bins: encourage consolidation into fewer bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Non-linear reward for tight fits, modulated by progress
    let tightness = 1.0 - fit_norm; // 1 = perfect fit
    score -= 18.0 * tightness.powi(3) * (0.6 + 0.4 * progress);

    // Penalize awkward residuals near half capacity (dead space), smoothly
    let half = (fit_norm - 0.5).abs();
    score -= 6.0 * (1.0 - 4.0 * half * half).max(0.0) * (0.4 + 0.6 * progress);

    // Lookahead: reward residuals that can still host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as f64 >= nx {
            score -= 10.0 * (1.0 - nx / cap) * (1.0 - progress);
        } else {
            score += 5.0 * (nx - pr as f64) / cap * (1.0 - progress);
        }
    }

    // Last chance bin: strongly favor using it before opening new
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Mild pressure to consolidate when many bins are open
    score -= 3.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * tightness;

    // Slight preference for bins below mean residual (balancing)
    score += 0.05 * (pr as f64 - mean_residual);

    // New-bin candidate: neutral baseline with smooth penalty growing with progress
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * progress - 8.0 * (1.0 - fit_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Residuals that fall into "clean" harmonic
    // classes (multiples of common item sizes) are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fractional position of post_residual within the bin (0..1)
    let frac = pr / cap;

    // Harmonic class via integer division thresholds: which capacity-fraction
    // band does the post residual land in?
    let band = (post_residual / 10).min(9) as f64; // 0..9 decile class
    score -= band * 0.35; // larger residual classes are mildly favored

    // Modulo arithmetic: post_residual divisible by common item granularities
    // (10, 20, 25, 50) means future items can fill it exactly.
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual > 0 && post_residual % 25 == 0 { score -= 4.0; }
    if post_residual % 20 == 0 && post_residual > 0 { score -= 3.0; }
    if post_residual % 50 == 0 && post_residual > 0 { score -= 5.0; }

    // Penalize awkward dead space: small nonzero residuals that no item
    // (min size 1..100 unknown, but historically >= 10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // pure dead space
    } else if post_residual > 0 && post_residual < 20 {
        score += 8.0;
    }

    // Coupling with next item: exact fill of next item is golden.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            // next item still fits: reward proportional to how cleanly it fits
            let after_next = post_residual - next_item_size;
            if after_next % 10 == 0 { score -= 7.0; }
            score -= 4.0 * (next_item_size as f64 / cap);
        } else {
            // next item won't fit here; penalize more if this was the only fit
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // offer poor fits. Base penalty for opening a new bin, modulated by how
    // fragmented current bins are.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs();
        score += 22.0 + fragmentation * 0.15;
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 12.0;
    } else {
        // Favor bins whose residual is close to the item (tight fit)
        let tightness = (bin_residual as f64 - item_size as f64) / cap;
        score -= (1.0 - tightness) * 10.0;
    }

    // Mean-residual alignment: bins near the mean residual are "typical" and
    // slightly preferred, keeping a balanced portfolio of residuals.
    score -= 3.0 * (1.0 - (post_residual as f64 - mean_residual).abs() / cap).max(0.0);

    // Many open bins: encourage closing bins out (prefer fuller bins).
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * (post_residual as f64 / cap) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Zero residual is perfect packing: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits (post_residual small relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 15.0 * tightness;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    score += (open_bins_count as f64) * 0.8;

    // Prefer bins whose residual deviates below the mean (consolidate large gaps).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item cannot fit post_residual but could fit elsewhere, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // New-bin candidate: only attractive when existing fits are poor or none exist.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else {
            // Make new bin unattractive unless all open bins would leave big dead space.
            score += 20.0 + (open_bins_count as f64) * 0.5;
        }
    }

    // Early stream: slightly favor consolidation into fewer bins.
    if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.5 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: item + next item exactly fills the bin.
    if next_item_size > 0 {
        let two_step = post_residual as i64 - next_item_size as i64;
        if two_step == 0 {
            score -= 1000.0;
        } else if two_step > 0 {
            // Next item still fits after this placement: mild reward scaled by tightness.
            let tightness = 1.0 - (two_step as f64 / bin_capacity as f64);
            score -= 40.0 * tightness;
        } else {
            // Next item cannot use the leftover: penalize proportionally to wasted space.
            let waste = (-two_step) as f64;
            score += 0.8 * waste;
        }
    }

    // Penalize small dead residuals (< 10) that likely can never be used.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0 + (10 - post_residual) as f64;
    }

    // Last-chance bin: strong preference to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: keep it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score += 25.0 + 2.0 * pressure;
        // If the item is large and current bins are fragmented, new bin is decent.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 30.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    let avg = mean_residual.max(0.0);
    score += 0.3 * (post_residual as f64 - avg);

    // Late in the stream, tighten packing (avoid opening new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact/tight fits: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take it
    } else {
        let tightness = post_residual as f64 / bin_capacity as f64;
        score -= 60.0 * (1.0 - tightness * tightness);
    }

    // Penalize dead space that cannot hold the next item (lookahead).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Residual can host next item: mild bonus scaled by how well it fits.
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate handling: prefer opening a new bin when existing bins are
    // fragmented (mean residual low relative to item) or many bins already open.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; cheaper late in the stream and when open bins
        // are already numerous (keeps open-bin count bounded).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 55.0 - 20.0 * progress + 2.0 * open_bins_count as f64;
        // If lookahead item is large, a fresh bin is more valuable.
        if next_item_size > item_size {
            new_bin_cost -= 10.0;
        }
        // If mean residual across open bins is large, prefer reusing them.
        new_bin_cost += 0.4 * (mean_residual - item_size as f64).max(0.0);
        score = new_bin_cost;
    } else {
        // Mild preference for bins whose residual is close to the item (best-fit core),
        // and slight tie-break toward bins with residual near half capacity.
        let mid_dist = (bin_residual as f64 - bin_capacity as f64 * 0.5).abs();
        score += 0.05 * mid_dist;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64;
    let next = next_item_size as f64;
    let mean_r = mean_residual / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = (1.0 - t) * norm_pr * norm_pr + t * (1.0 - norm_pr) * (1.0 - norm_pr);
    score += 40.0 * poly * cap * 0.1;

    // Reward tight fits (small post_residual) more strongly later in stream
    score -= 25.0 * (1.0 - norm_pr).powi(3) * (0.5 + t);

    // Penalize dead space that cannot fit the next item
    if next > 0.0 {
        let waste = (pr - next).max(0.0);
        score += 0.35 * waste * (1.0 + (waste / cap).powi(2));
        // Reward residual that exactly accommodates lookahead
        if pr >= next && pr - next < item {
            score -= 12.0 * (1.0 - t);
        }
    }

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Coupling with mean residual: prefer bins deviating below mean (tighter bins)
    let dev = (mean_r - norm_pr).abs();
    score += 15.0 * dev * (1.0 - dev);

    // New-bin candidate: penalize opening a new bin unless current item is large
    if bin_residual == bin_capacity {
        score += 45.0 - 0.4 * item * (0.5 + t);
        score += 3.0 * open_bins_count as f64;
    }

    // Mild preference for fuller bins overall
    score -= 10.0 * (1.0 - bin_residual as f64 / cap) * (0.3 + 0.7 * t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity-eighth bands.
    let eighth = cap / 8.0;
    let band = (post_residual as f64 / eighth).floor() as i32; // 0..8
    let band_penalty = match band {
        0 => -40.0,                 // perfect fit: zero waste
        1 => -18.0,                 // tiny sliver, nearly perfect
        2 => 6.0,                   // dead space ~1/8
        3 => 14.0,
        4 => 18.0,                  // half-full: mediocre
        5 => 12.0,
        6 => 4.0,
        _ => -6.0,                  // mostly empty: fine to "waste" later
    };
    score += band_penalty;

    // Integer-division thresholds: post_residual divisible by small harmonic divisors
    // means future items (common sizes) can tile it exactly.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 10.0; }
        else if pr % 5 == 0 { score -= 5.0; }
        if pr % 25 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr < 10 { score += 25.0; } // unusable micro-sliver
    }

    // Lookahead coupling: does next item fit harmonically into post_residual?
    if next_item_size > 0 && (next_item_size as u32) <= pr {
        let nxt = next_item_size as f64;
        if pr % next_item_size == 0 {
            score -= 22.0; // exact tiling possible
        } else {
            let fill_frac = nxt / pr.max(1) as f64;
            score -= 14.0 * fill_frac; // partial harmony reward
        }
    } else if next_item_size > 0 {
        score += 8.0; // next item won't fit here: mild penalty
    }

    // Last-chance bonus: sole fitting bin should be strongly favored.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / cap;
        // Penalize opening new bins generally; relax late in stream or when
        // existing residuals are all small (bad hosts).
        score += 45.0 - 35.0 * (1.0 - crowding) - 20.0 * progress;
        if next_item_size > 0 && (next_item_size as u32) > mean_residual as u32 {
            score -= 15.0; // no open bin can host the next item either
        }
    } else {
        // Reward using bins whose residual deviates favorably from the mean
        // (consume outliers, keep a balanced pool).
        let dev = bin_residual as f64 - mean_residual;
        score -= 0.15 * dev;
    }

    // Slight pressure to consolidate when many bins are open.
    score -= 0.5 * open_bins_count as f64;

    // Modulo-class affinity between item and residual (harmonic pairing).
    if (item_size % 10) == (bin_residual % 10) && bin_residual != bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are wasted.
    if post_residual < 10 {
        score += 60.0; // unusable gap penalty
    }

    // Reward tight fits (post_residual small but usable).
    score -= 0.9 * (item_size as f64 / bin_capacity as f64) * 40.0;

    // Penalize residual far above mean (bin is unusually empty -> poor consolidation).
    if (post_residual as f64) > mean_residual {
        score += 0.35 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.20 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 6.0 * (open_bins_count as f64).sqrt() + 15.0 * progress;
        // Allow new bin only if no open bin gives a near-perfect fit.
        if post_residual == 0 || item_size >= 90 {
            score -= 40.0;
        }
    } else {
        // Slight preference for already-open bins over new-bin baseline.
        score -= 5.0;
    }

    // Lookahead coupling: prefer leaving space that can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < 10 {
            score += 10.0; // gap blocks next item
        }
        // Perfect pair fit: item + next item fills bin exactly.
        if item_size + next_item_size == bin_residual {
            score -= 30.0;
        }
    } else {
        // Last item: any residual is dead space; favor exact fills hard.
        score += 0.5 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / near matches of post_residual with the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let perfect = (post_residual as i64 == next_item_size as i64) as f64;
        score -= 60.0 * perfect;
        score -= 15.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Penalize leaving a gap that is too small for any plausible next item.
        if post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 12.0;
        }
    }

    // Relative-to-mean residual shaping: bins with residuals near the mean are
    // "normal" targets; extreme residuals are penalized.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.25 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny dead space (< 10) that is nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // New-bin candidate: make it mildly unattractive unless the stream is early
    // and open bins are crowded (encourages spreading early, packing later).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 8.0 - 6.0 * (1.0 - progress) - crowd.min(6.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional fill quality: reward high utilization of the bin.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill * fill;

    // Strong reward for near-perfect fits (small dead space).
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual,
    // this placement chains nicely; otherwise penalize residual sizes
    // that are too small for the next item (dead space).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 8.0;
        } else if post_residual > 0 {
            // residual too small for next item: penalize proportionally
            score += 0.15 * (nxt - post_residual as f64);
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine early (many items to come), but costly
        // late in the stream; also costly if open bins fit decently.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + 25.0 * progress;
        if fitting_bins_count >= 1 {
            score += 10.0 * (fitting_bins_count as f64).min(3.0);
        }
        // If next item is large, having a fresh bin may help.
        if next_item_size >= 60 {
            score -= 8.0;
        }
    }

    // Prefer bins below mean residual (consolidate emptier space? no —
    // prefer filling bins that are already small-residual to keep large
    // residuals available for big future items).
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 3.0;
        }
    }

    // Mild penalty for proliferating open bins when item fits existing ones.
    if bin_residual < bin_capacity && open_bins_count > 4 {
        score -= 0.5 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Quadratic dead-space penalty, growing with stream progress
    let pr = post_residual as f64;
    score += 0.012 * pr * pr * (0.5 + progress);

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: prefer it only if residual capacity is abundant and progress is low
    if bin_residual == bin_capacity {
        let newbin_bonus = 8.0 * (1.0 - progress) - 4.0 * progress * open_bins_count as f64;
        score += newbin_bonus;
        // If lookahead item is large, a fresh bin is more valuable
        if next_item_size > 0 {
            let n = next_item_size as f64;
            score -= 0.06 * n * (1.0 - progress);
        }
    }

    // Lookahead synergy: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + 0.03 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize residuals just below next item size (dead space risk)
        let gap = next_item_size as f64 - post_residual as f64;
        score += 0.05 * gap * gap;
    }

    // Mild penalty when bin residual deviates from mean residual (spread control)
    score += 0.02 * (bin_residual as f64 - mean_residual).abs();

    // Cubic coupling of fill fraction with progress
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 4.0 * fill * fill * fill * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "usable"
    // residue classes (small leftovers likely fillable by future items) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Exact-fit reward: zero dead space is always best.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Modulo-class bonus: leftover divisible into capacity fractions
    // (e.g. multiples of 10, 25, 50) are "harmonic" and reusable.
    let harmonic = |r: u32| -> f64 {
        let mut h = 0.0;
        if r % 10 == 0 { h += 6.0; }
        if r % 25 == 0 { h += 4.0; }
        if r % 50 == 0 { h += 3.0; }
        h
    };
    score -= harmonic(post_residual);

    // Integer-division threshold: leftover smaller than min plausible item
    // (dead space) is heavily penalized.
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Tightness reward: favor bins where the item fills a large fraction
    // of the residual (best-fit flavor with non-linear coupling).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Lookahead coupling: if the next item fits the post-residual exactly
    // or harmonically, strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
            score -= harmonic(post_residual - next_item_size);
        } else {
            // next item won't fit here; mild penalty proportional to overshoot class
            let over = (next_item_size - post_residual) as f64;
            score += 0.15 * over;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // current bins are crowded or the fit here is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / 10.0;
        // Base penalty so new bins are used only when justified.
        score += 35.0 + crowding * 2.0 - progress * 10.0;
        // If item is large relative to mean residual, opening a new bin may be wise.
        if (item_size as f64) > mean_residual + 15.0 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 8.0;
        }
    } else {
        // Slight preference for bins with residual close to item (best fit),
        // scaled by global mean residual for adaptivity.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any item are worthless.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual is well matched to the item (tight fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Lookahead: if next item fits in the post residual, this is a great chain.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 18.0;
    }
    // Penalize leaving a gap that only barely misses the next item (dead space risk).
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into existing bins
    // and discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (10.0 + progress * 20.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 12.0 + 6.0 * pressure;
    } else {
        score -= 4.0 * pressure.min(3.0);
    }

    // Mild attraction to bins with residuals near the item size (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact 2-chain fit
        } else if post_residual > next_item_size {
            // next item still fits after this placement: mild bonus,
            // stronger when the leftover gap is small.
            let gap = (post_residual - next_item_size) as f64;
            score -= (20.0 * (1.0 - gap / bin_capacity as f64)).max(0.0);
        } else {
            // next item cannot use the leftover: penalize dead space,
            // worse when the waste is tiny (nearly-exact-but-missed).
            let waste = (next_item_size - post_residual) as f64;
            score += 10.0 + 25.0 * (1.0 - waste / bin_capacity as f64);
        }
    }

    // Penalize leaving unusably small residuals (dead space trap).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Relative-to-mean residual shaping: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate logic: only attractive when current bin would leave
    // a large awkward residual or many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = post_residual as f64; // = capacity - item_size for new bin call
        if awkward < 35.0 {
            score -= 25.0 + 20.0 * progress; // small item: fresh bin is fine
        } else {
            score += 10.0 + 0.3 * open_bins_count as f64; // discourage spreading
        }
    }

    // Slight preference for filling fuller bins early in the stream.
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) more aggressively as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_capacity as f64 - post_residual as f64) * (0.5 + 0.8 * progress);

    // Penalize dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 6.0 * (next_item_size as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty if we leave awkward gap.
        if post_residual > 0 {
            score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
        }
    }

    // New empty bin candidate: penalize opening new bins when decent alternatives exist,
    // but allow it when open bins are fragmented (low mean residual relative to item).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let pressure = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).ln() };
        score += 55.0 - 30.0 * fragmentation - 10.0 * pressure + 20.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across too many open bins with high mean residual.
    score += 0.02 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Prefer bins whose residual is close to the item (perfect nesting).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score -= 15.0 * (1.0 - gap / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 12.0 * poly;

    // Reward tight fits, stronger later in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 25.0 * progress);

    // Penalize dead space near capacity residual (unusable leftovers)
    if norm_pr > 0.0 && norm_pr < 0.1 {
        score += 8.0 * (0.1 - norm_pr) * (1.0 + progress);
    }

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0 + 10.0 * progress;
    }

    // New-bin candidate: prefer it when open bins are fragmented
    if bin_residual == bin_capacity {
        let frag = (mean_residual / cap - norm_pr).abs();
        score += 4.0 - 3.0 * progress;
        score -= (open_bins_count as f64).ln() * 2.0 * frag;
    }

    // Lookahead coupling: favor leaving room for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 5.0 * (pr - ns) / cap * (0.5 + progress);
        } else {
            score += 4.0 * (ns - pr) / cap;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose residual lies in "usable" classes
    // (>= smallest plausible item) are more valuable than dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Integer-division threshold classes on post_residual
    let class = post_residual / 10; // coarse harmonic class
    match class {
        0 => score += 40.0,          // 0..9: dead space, very bad
        1 => score += 18.0,          // 10..19: only tiny items fit
        2 => score += 6.0,           // 20..29
        3 => score += 0.0,
        4 => score -= 4.0,           // 40..59 sweet zone
        5 => score -= 6.0,
        6 => score -= 5.0,
        _ => score += 2.0,           // >70: wasteful placement of a big item
    }

    // Modulo coupling: residuals that are multiples of 10 pair well with
    // typical item sizes drawn from decile classes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits, but check leftover after hypothetical next placement
            let post2 = post_residual - next_item_size;
            score -= 10.0 + (post2 as f64) * 0.3;
            if post2 % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: penalize slightly if we burn a large residual
            if post_residual > 50 {
                score += 8.0;
            }
        }
    }

    // Prefer filling bins whose residual deviates above the mean (consolidate).
    score += 0.4 * (post - mean_residual).max(-30.0).min(30.0);

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins unless their fit is bad; penalty shrinks late in stream
    // or when many bins are open.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 0.5 + progress * 10.0;
        score += 25.0 - pressure.min(22.0);
        // If item is large relative to capacity, opening fresh is fine
        if (item_size as f64) / cap > 0.7 {
            score -= 10.0;
        }
    }

    // Late-stream urgency: close out bins rather than spreading.
    score += 10.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit reward
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin when a reasonable fit
    // exists elsewhere; reward it when residuals are fragmented.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 20.0 + 0.8 * pressure;
        if post_residual as f64 > mean_residual + 30.0 {
            score -= 15.0; // item is large relative to open residuals -> new bin ok
        }
        if fragmentation < 5.0 && open_bins_count > 0 {
            score -= 10.0;
        }
    } else {
        // Mild pressure: many open bins -> prefer consolidating into them.
        score -= 0.15 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 20.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 8.0; // next item won't fit here anyway; dead space risk
    }

    // Late in the stream, be more conservative about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
