        }
    }

    // --- Relative-to-mean-residual coupling ---
    let dev = post_residual as f64 - mean_residual;
    // Favor bins whose post residual is below the mean (tight packing), mildly.
    score += 0.10 * dev;

    // --- Last-chance bonus: only this bin can fit the item ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost so it's chosen only when open bins pack poorly.
        score = bin_capacity as f64 - 5.0;
        // More attractive late in the stream or when open bins are fragmented.
        score -= 10.0 * progress;
        if open_bins_count > 0 {
