        }
        // If next item is large, a fresh bin is more attractive.
        score -= 0.10 * next_item_size as f64;
        // Never open a new bin when this is the only fitting bin elsewhere.
        if fitting_bins_count == 1 {
            score += 40.0;
        }
    }

    // Small tie-breaker: prefer tighter fits generally.
    score += 0.02 * (bin_residual - post_residual) as f64 * 0.0; // no-op guard
    score += 0.001 * post_residual as f64 * post_residual as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tight-fit preference: squared post-residual dominates.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead: reward if the next item can fit into the post-residual (chaining),
    // penalize if the post-residual is dead space the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.10 * (post_residual - next_item_size) as f64;
        } else {
            // Dead space relative to lookahead; worse the larger the gap.
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
        // Perfect chain: post_residual exactly matches next item.
        if post_residual == next_item_size {
            score -= 8.0;
        }
    } else {
        // Last item: minimize post-residual strongly.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many fitting bins: mild penalty for this bin relative to competition — prefer tighter ones
    // (already captured), but penalize spreading across bins when residuals are large on average.
    if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Global state coupling: if mean residual across open bins is high, prefer filling
    // existing bins over opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 0.05 * mean_residual * (0.5 + 0.5 * progress);

    // Penalize opening a new bin when good open bins exist, more so late in the stream.
    if bin_residual == bin_capacity {
        let new_bin_base = 25.0 + 20.0 * progress;
        // But if no open bin fits well (post_residual would be large elsewhere), allow it:
        score = new_bin_base + 0.2 * item_size as f64 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 40.0; // must open first bin
        }
        // Next item is large: a fresh bin can host it later, slight bonus.
        if next_item_size >= 50 {
            score -= 6.0;
        }
    }

    // Mild preference for bins whose residual was already fragmented (near-full bins).
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 4.0 * fill_ratio * fill_ratio;

    // Dynamic time horizon: early on, be more exploratory (slightly flatten differences);
    // late, be greedy via sharper residual penalty.
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: squared/quartic penalty on residual,
    // modulated by stream progress (later in stream => tighter packing).
    let prn = pr / cap; // normalized post-residual
    score += 30.0 * prn * prn * (0.5 + progress);

    // Reward near-perfect fits strongly (quartic term).
    score -= 40.0 * (1.0 - prn) * (1.0 - prn) * (1.0 - prn) * (1.0 - prn);

    // Lookahead: penalize residuals too small for next item (dead space),
    // reward residuals that can still host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            // dead space grows with progress
            score += 12.0 * prn * (0.4 + progress) * (1.0 - pr / nxt.max(1.0)).abs();
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - prn);
    }

    // New-bin candidate: penalize opening a bin mildly, more when many bins
    // are open and mean residual is high; relax late in the stream.
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score += 15.0 + 20.0 * mean_norm * (1.0 - progress) + 5.0 * (open_bins_count as f64).sqrt();
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.05 * (pr - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space quality by residue class.
    let post = post_residual as i64;
    let cap = bin_capacity as f64;

    // Small usable residuals are valuable; classify via integer division thresholds.
    if post == 0 {
        score -= 60.0; // perfect fill
    } else if post <= 10 {
        score -= 35.0; // near-perfect, practically dead but tiny
    } else if post <= 20 {
        score -= 12.0; // still usable for small items
    } else if post <= 30 {
        score += 6.0;  // awkward class
    } else {
        score += 0.0;
    }

    // Modulo harmonic classes on post_residual: residues near multiples of 10
    // pair well with typical item sizes; odd residues waste more.
    let r = post % 10;
    score -= (10 - r as i64).min(r) as f64 * 0.8;

    // Lookahead coupling: reward residuals that can host the next item.
    if next_item_size > 0 {
        if post >= next_item_size as i64 {
            score -= 18.0;
            // extra reward for exact class match (post % 25 bands)
            if post % 25 == next_item_size as i64 % 25 {
                score -= 6.0;
            }
        } else {
            // residual can't host next item: penalize proportionally to waste
            score += (next_item_size as f64 - post as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current item is huge
    // relative to open-bin residuals (keeps bins consolidated).
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).max(0.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 - 20.0 * pressure - 10.0 * progress;
        if item_size >= 60 { score -= 15.0; }
    }

    // Mild preference to fill emptier bins first when many bins are open.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Tightness reward: fraction of bin consumed by this item.
    score -= (item_size as f64 / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever fit the
    // minimum item (size 1..=10 worst case) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // "Awkward" gap: too small for typical mid-size items but nonzero.
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0 * (25 - post_residual) as f64 / 15.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    if item_size > 0 {
        score -= 25.0 * (item_size as f64 / bin_residual as f64);
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_tightness = next_item_size as f64 / post_residual as f64;
        score -= 18.0 * chain_tightness;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use this gap -> dead space for the next step.
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer reusing existing ones,
    // penalize opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 + 0.5 * progress);
    score += 0.4 * pressure;

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e., when mean residual is far below the item size.
    if bin_residual == bin_capacity {
        let desperation = (item_size as f64 - mean_residual).max(0.0) / bin_capacity as f64;
        score = 100.0 - 80.0 * desperation + 0.3 * open_bins_count as f64 * (1.0 - progress);
        if post_residual == 0 {
            score -= 20.0;
        }
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack
    else if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / 30.0).max(0.0);
    }
    // Next item does NOT fit here: penalize leaving space that blocks lookahead
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 15.0;
    }

    // Penalize small unusable dead space (nonlinear)
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        if dead < 0.10 {
            score += 20.0 * (0.10 - dead) / 0.10;
        }
    } else {
        // Perfect closure
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Prefer filling bins below current mean residual (tighter bins)
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in stream: be more conservative, favor new bins slightly less
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    // New empty bin candidate: neutral-ish baseline with mild penalty so it's
    // chosen only when open bins score poorly
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that is too small for any plausible item (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer opening a new bin only when fits are poor or
    // the lookahead item needs the saved space.
    if bin_residual == bin_capacity {
        let avg_fit = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        let poor_fit = (post_residual as f64) / (bin_capacity as f64); // = 1.0 for new bin
        let lookahead_pressure = (next_item_size as f64 / bin_capacity as f64).powi(2);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins early (keep bins tight), relax late in stream.
        score += 20.0 * (1.0 - 0.5 * progress) * (1.0 - lookahead_pressure)
            - 5.0 * avg_fit * poor_fit;
        // If many open bins with high mean residual, opening fresh is fine.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 3.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > post_residual && next_item_size <= bin_residual {
        // Next item would have fit here before we consumed space — mild penalty.
        score += 8.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
    }

    // Slight preference for filling bins with larger residual when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) / bin_capacity as f64;

    // Small tie-break toward bins whose residual is close to mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis
    let mut score = post + (post / cap) * post * 0.5;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Small dead-space reward: residual below smallest plausible item
    if post_residual < 10 {
        score -= 12.0 * (1.0 - post / 10.0);
    }

    // Penalize leaving large residual that likely becomes dead space,
    // especially late in the stream when fewer items remain to fill it.
    let large = (post / cap).powi(3);
    score += 20.0 * large * (0.4 + 0.6 * t);

    // Lookahead coupling: reward residuals that can host the next item smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (post >= nxt) as i32 as f64;
        // Smooth affinity: closeness of post_residual to next item
        let gap = (post - nxt).abs() / cap;
        score -= 8.0 * fits * (1.0 - gap).max(0.0);
        // Penalize residual just barely too small for next item (wasted opportunity)
        let barely_miss = ((nxt - post) / cap).max(0.0);
        score += 6.0 * (1.0 - (barely_miss * 10.0).min(1.0)) * (1.0 - fits);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else {
        // Mild competition penalty when many bins fit (prefer the tightest anyway)
        score += (fitting_bins_count.min(10) as f64) * 0.3;
    }

    // Prefer filling bins whose residual is below average (consolidate fullness)
    score += (mean_residual - post) * 0.05;

    // Early stream: mildly prefer spreading into fresh bins to build good structures
    score -= 5.0 * (1.0 - t) * (post / cap);

    // New-bin candidate handling: only attractive when item is large relative to
    // capacity or no good open fit exists (post_residual of empty bin == cap).
    if bin_residual == bin_capacity {
        let load_frac = item / cap;
        // Opening a new bin is good for large items, bad for small ones
        score = cap - post; // baseline = 0 for empty bin
        score += 25.0 * (1.0 - load_frac);
        score -= 10.0 * load_frac;
        // Late in stream, prefer existing bins more strongly
        score += 15.0 * t;
        if fitting_bins_count > 1 {
            score += 8.0;
        }
        if item as u32 >= 70 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: quantize post_residual into deciles of capacity.
    let post_frac = post_residual as f64 / cap;
    let class = (post_frac * 10.0).floor() as u32; // 0..9 harmonic decile

    // Reward small post_residual strongly (non-linearly): tight fits are precious.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else {
        // Superlinear penalty shaping on small leftovers, harmonic-decile modulation.
        let tightness = (1.0 - post_frac).powi(3);
        score -= 25.0 * tightness;
        // Dead-space trap: leftover too small for typical items (1..100 unknown, guard ~10).
        if post_residual < 10 {
            score += 18.0 * (10.0 - post_residual as f64);
        }
    }

    // Modulo-arithmetic coupling: leftover that is a clean divisor-friendly class
    // (divisible by common item sizes 10/20/25/50) is more reusable.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nxt_left = post_residual - next_item_size;
            score -= 12.0 * (1.0 - nxt_left as f64 / cap);
            if nxt_left == 0 { score -= 15.0; }
        } else {
            // Next item would NOT fit here: penalize leaving a bin that blocks the lookahead.
            score += 8.0 + 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has large residual; make it moderately
    // attractive only when current fit is poor, otherwise discourage wasting fresh bins.
    if bin_residual == bin_capacity {
        // Base preference against opening new bins while open bins exist.
        score += if open_bins_count > 0 { 10.0 } else { 0.0 };
        // If many open bins are already fragmented, a fresh bin is fine.
        if mean_residual < 0.25 * cap && open_bins_count > 2 {
            score -= 12.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild pressure to prefer bins whose residual deviates from the mean
    // (consolidate fragmented space into fewer bins).
    score += 0.05 * ((post_residual as f64 - mean_residual).abs());

    // Harmonic class bonus: bins whose post_residual lands in "useful" deciles
    // (>= 30% free) stay flexible for mid-size items.
    if class >= 3 {
        score -= 3.0 + class as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical
    // future items are "dead". Penalize them super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Coupling: residual relative to mean residual of open bins.
    // Prefer bins with less residual than average (tighter bins first),
    // but only when the fit is decent.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading;
    // when few are open, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only if this placement would leave a bad gap or the
    // item is large relative to the residual.
    if bin_residual == bin_capacity {
        let gap_penalty = if post_residual > 0 && post_residual < 10 { 90.0 } else { 0.0 };
        score = bin_capacity as f64 * 0.9 + gap_penalty - open_bins_count as f64 * 0.3;
        // Lookahead: if next item fits into the would-be post_residual,
        // keeping item in an open bin is better; penalize new bin less otherwise.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 25.0;
        }
    }

    // Lookahead bonus: if the next item exactly fits the post_residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 120.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item exactly fills the post residual (2-step lookahead match)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // perfect chain: item + next item fill bin
        } else if next_item_size as f64 <= post_residual as f64 {
            score -= 12.0 * (1.0 - diff / bin_capacity as f64); // next item fits, closer = better
        } else {
            score += 6.0; // next item won't fit here
        }
    } else {
        // Last item: prefer minimal post residual (tightest fit)
        score -= 8.0;
    }

    // Compare post residual against mean residual of open bins:
    // leaving less than average residual is good (tight packing)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (pr - mean_residual);
    }

    // Penalize large dead space that likely becomes unusable
    if pr > 0 && pr < 10 {
        score -= 10.0; // small unusable sliver is fine if bin nearly full
    } else if pr >= 10 && pr < item_size as f64 {
        score += 3.0; // dead space smaller than typical item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // is large relative to residuals of open bins (poor fit everywhere).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins are preferred unless they're poor fits
        score += 15.0;
        // If post residual in a fresh bin leaves lots of usable space and item is big, encourage
        if item_size >= 50 {
            score -= 10.0;
        }
        // If next item is large, a fresh bin gives flexibility
        if next_item_size >= 40 {
            score -= 8.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // Many open bins: opening another dilutes mean residual; discourage
        score += 0.5 * open_bins_count as f64;
    }

    // Mild tie-break: prefer bins with larger residual before placement (use emptier bins)
    score += 0.05 * (bin_residual as f64 - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: reward if the next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // chain perfect fit
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item fills the leftover
            let fill = (next_item_size as f64) / (post_residual as f64);
            score -= 40.0 * fill;
        } else {
            // next item won't fit here; penalize large dead space
            score += 10.0 * (post_residual as f64) / (bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless it's
    // genuinely attractive (e.g., few open bins or item is large)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let mut new_bin_penalty = 150.0;
        // large items are hard to place later; slightly favor fresh bins for them
        new_bin_penalty -= 40.0 * item_frac;
        // early in the stream, opening bins is cheaper (more future items to fill them)
        new_bin_penalty -= 60.0 * (1.0 - progress);
        // if open bins are fragmented (high mean residual), a new bin is more attractive
        new_bin_penalty -= 0.3 * mean_residual;
        score += new_bin_penalty.max(0.0);
    }

    // Mild penalty when many bins are open and this bin's residual is far above mean
    // (keeps residuals homogeneous so future items have more placement options)
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.15 * dev;
    }

    // Small time-horizon modulation: late in the stream, be greedier about tight fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Smooth non-linear coupling: residual penalty shaped by stream progress.
    // Late in the stream, tight fits matter more -> amplify small residuals.
    let norm_res = post_residual as f64 / bin_capacity as f64;
    let shape = 1.0 + 2.0 * progress * progress;
    score += shape * norm_res * norm_res * (bin_capacity as f64) * 0.5;

    // Reward filling the bin well, smoothly scaled by progress.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * fill * (10.0 + 15.0 * progress);

    // Lookahead: bonus if next item fits the post-residual.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 4.0 + 6.0 * progress;
    }
    // Penalize residual too small for the next item (dead space risk).
    if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
        score += 3.0 + 5.0 * progress;
    }

    // Last-chance bin: strongly favor using it over opening a new one.
    if fitting_bins_count == 1 {
        score -= 8.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    let mean_dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * mean_dev + 0.02 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: make empty bin unattractive unless residuals are hopeless.
    if bin_residual == bin_capacity {
        score += 6.0 + 12.0 * progress + 0.1 * open_bins_count as f64;
        // Allow opening when existing residuals are all very tight relative to item.
        if mean_residual < item_size as f64 * 0.6 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else {
        // Harmonic-class penalty: post residual bucketed by integer division
        let cls = post_residual / 10;
        score += cls as f64 * 3.0;
        // Fractional capacity coupling
        let frac = post_residual as f64 / cap;
        score += frac * 20.0;
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 15.0;
        } else if next_item_size == post_residual {
            score -= 40.0; // chain fit
        } else {
            score -= (next_item_size as f64) * 0.3;
        }
    }

    // Last-chance bonus: only this bin fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: prefer opening a new bin when open bins are cluttered
    if bin_residual == bin_capacity {
        // New bin baseline: neutral residual = 100; adjust with context
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 100.0 - 25.0 * progress;
        if fitting_bins_count == 0 { score -= 80.0; }
        if fitting_bins_count == 1 { score += 120.0; } // don't abandon the only fitting bin
        if open_bins_count as f64 * mean_residual > item_size as f64 * 2.0 { score += 10.0; }
    }

    // Mild preference to fill bins with low residual relative to mean
    score -= (mean_residual - bin_residual as f64) * 0.2;

    // Small penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fits are gold: subtract heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0 * (6.0 - post_residual as f64);
    }

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible next item (<= 12) are unusable -> heavy penalty.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 * (12.0 - post_residual as f64);
    }

    // Reward residuals that can still host a typical item (>= 30 usable).
    if post_residual >= 30 {
        score -= 10.0 + 0.05 * post_residual as f64;
    }

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Even better if it fills nearly perfectly.
        let pair_gap = post_residual as f64 - next_item_size as f64;
        if pair_gap < 12.0 {
            score -= 10.0 * (12.0 - pair_gap);
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // This bin will be dead after this placement for the lookahead item.
        score += 8.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidation into open bins
    // (penalize the new-bin candidate relatively).
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate handling: only attractive when open bins are few or
    // mean residual is large/fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        if open_bins_count > 0 && fragmentation < 0.35 {
            score -= 5.0 + 10.0 * progress; // open a fresh bin when open ones are junk
        } else {
            score += 40.0; // discourage spreading across many bins
        }
    }

    // Mild alignment with mean residual: prefer bins below mean (tighter bins).
    score += 0.1 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 30.0 / (post_residual as f64).sqrt();
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 250.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasted residual relative to next item.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average when they fit well.
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: acceptable only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 90.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Slight preference to fill older bins as the stream progresses.
    score += 0.02 * (open_bins_count as f64) * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: best-fit via post_residual, with mild convex penalty on tiny leftovers
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += (10.0 - dead) * 2.0; // hard-to-fill slivers are waste
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: reward if leftover can host the next item (chaining)
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 8.0 + 4.0 * (next_item_size as f64 / 100.0);
        } else if post_residual > 0 && next_item_size > post_residual {
            // leftover too small for next item: dead space risk
            score += 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when
    // open bins would leave bad leftovers or the item is large.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 > 0.7 * bin_capacity as f64;
        let poor_alternatives = fitting_bins_count == 0
            || (fitting_bins_count == 1 && (bin_residual - item_size) < next_item_size && next_item_size > 0);
        if big_item || poor_alternatives {
            score -= 5.0;
        } else {
            // discourage spreading across many bins when good fits exist
            score += 10.0 + 2.0 * open_bins_count as f64 * (1.0 - t * 0.5);
        }
    }

    // Global state coupling: when mean residual is high, prefer filling bins
    // with large residuals less aggressively (keep flexibility), otherwise
    // consolidate into tight bins.
    let mr = mean_residual / bin_capacity as f64;
    score += mr * (post_residual as f64 - bin_residual as f64).abs() * 0.5;

    // Late stream: tighten packing, punish any leftover more
    score *= 1.0 + 0.3 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual cost, damped by stream progress (waste matters more later)
    let mut score = pr * (0.6 + 0.8 * progress);

    // Non-linear polynomial coupling of post_residual with progress
    let q = norm_pr * norm_pr;
    let q3 = q * norm_pr;
    score += 40.0 * q * (1.0 - progress) - 30.0 * q3 * progress;

    // Tight fits are valuable: reward small post_residual non-linearly
    let tight = 1.0 - norm_pr;
    score -= 25.0 * tight * tight * tight * (0.5 + 0.5 * progress);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 15.0 * (1.0 - pr / nxt) * (0.4 + 0.6 * progress);
        } else {
            // reward leaving room exactly for the lookahead item
            let diff = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - diff).max(0.0) * (1.0 - diff);
        }
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 - 0.5 * progress);
    }

    // Mild penalty when many bins are open relative to progress (fragmentation)
    let frag = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += 4.0 * frag * frag * progress;

    // Deviation from mean residual: prefer bins near the mean to keep balance
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    // New-bin candidate: bias against opening fresh bins unless residual is large
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * (1.0 - progress) * (1.0 - norm_pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "useful" classes
    // (residuals that typical future items can still fill).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        let frac = pr as f64 / cap;
        // Dead-space penalty grows quadratically for small unusable residuals
        if pr < 10 {
            score += 25.0 * (10.0 - pr as f64);
        } else if pr <= 20 {
            // residuals 10..20 are highly reusable (small items)
            score -= 15.0 * frac;
        } else if pr <= 35 {
            score -= 8.0 * frac;
        }
        // Modulo class: residuals that are multiples of 10 pair well with
        // items in the 10..80 range; penalize odd/awkward classes mildly.
        let m = pr % 10;
        if m != 0 {
            score += 2.0 + 0.5 * m as f64;
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 50.0;
        } else if next_item_size < pr {
            score -= 10.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when this bin's residual is large
    // (item barely dents it) or when item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // neutral base; opening fresh is fine for tight items
        score = item_size as f64 * 0.5;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    } else {
        // prefer fuller bins (small residual before placement)
        score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Progress-based tie-break: later in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..15) are heavily penalized.
    if post_residual > 0 && post_residual < 15 {
        score += 40.0 * (1.0 - post_residual as f64 / 15.0);
    }
    // Medium dead space (15..30) mildly penalized.
    if post_residual >= 15 && post_residual < 30 {
        score += 8.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mild reward proportional to how well it fills.
        score -= 5.0 * (next_item_size as f64 / post_residual.max(1) as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this gap: penalize proportionally to gap size.
        score += 6.0 * (post_residual as f64 / 100.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (a new bin has bin_residual == bin_capacity, its post_residual is large,
    // so we add pressure that grows with open_bins_count for the fresh-bin call).
    if bin_residual == bin_capacity {
        score += 10.0 + 3.0 * open_bins_count as f64;
    } else {
        // Using an existing bin reduces fragmentation pressure slightly.
        score -= 2.0;
        // Prefer bins with below-average residual (tighter bins) to consolidate.
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Progress-based tightening: later in the stream, be more conservative with dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / 100.0) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: perfect fill with next item is ideal.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Penalize leftover space that cannot be exactly consumed by next item,
            // scaled by how close we came to a perfect match.
            score += 0.5 * slack + 10.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit in the leftover: dead space unless it's small.
            let dead = (next_item_size - post_residual) as f64;
            score += 2.0 * dead;
        }
    }

    // Reward leaving residuals close to the mean residual of open bins
    // (keeps residual distribution uniform, easier future packing).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 500.0;
    }

    // Mild penalty for spreading across too many bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.1 * open_bins_count as f64 * (1.0 - progress);

    // Prefer tighter bins (small residual before placement).
    score += 0.2 * (bin_residual - item_size) as f64;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 50.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits (small post_residual), with super-linear penalty on dead space.
    let frag = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * frag * frag;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last chance: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or when many bins are already open (consolidation pressure).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 30.0 + 2.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper; later, consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty += 40.0 * progress;
        // If the item fits poorly everywhere (large item, few fitting bins), soften penalty.
        if item_size > 50 && fitting_bins_count <= 2 {
            new_bin_penalty *= 0.5;
        }
        score += new_bin_penalty;
    }

    // Lookahead coupling: reward leaving residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Residual too small for next item: penalize proportionally to wasted potential.
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
        }
    }

    // Global state: when mean residual is high, prefer bins below mean (balance avoidance of fragmentation).
    if bin_residual as f64 > mean_residual && bin_residual != bin_capacity {
        score += 0.15 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Time horizon: late in the stream, tighten more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let mean_r = if mean_residual.is_finite() { mean_residual } else { 0.0 };

    // Base: post-residual (minimize wasted space)
    let mut score = r;

    // Non-linear polynomial coupling of residual with stream progress:
    // early on, tolerate larger residuals; late in the stream, penalize them harder.
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    let residual_weight = 0.6 + 1.4 * prog2 + 0.8 * prog3;
    score += residual_weight * (r / cap) * (r / cap) * cap * 0.5 - 0.5 * (r / cap) * cap;

    // Smooth quadratic coupling: fill factor of the bin (1 - r/cap) is rewarded
    // non-linearly — dense fills are exponentially more valuable as stream advances.
    let fill = 1.0 - r / cap;
    score -= (fill * fill) * (2.0 + 3.0 * prog2) * 10.0;

    // Coupling with mean residual: prefer bins whose residual is below mean
    // (compacting bins), penalize above-mean residuals, scaled by item size.
    let dev = (r - mean_r) / cap;
    score += dev * dev * 20.0 * (0.5 + fit_ratio);

    // Last-chance bonus: smooth logistic-like term when this is the only fitting bin.
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    let lc_smooth = last_chance / (1.0 + (r / cap) * (r / cap) * 4.0);
    score -= lc_smooth * 12.0;

    // Lookahead: non-linear penalty if post-residual can't fit next item but
    // another bin could; smooth interaction with progress.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let nxt_fits = if nxt <= r { 1.0 } else { 0.0 };
        let gap = ((nxt - r) / cap).max(0.0);
        score += (1.0 - nxt_fits) * gap * gap * (8.0 + 12.0 * progress) * (1.0 + fit_ratio);
        // Reward residual that exactly accommodates the next item (chaining).
        let near = 1.0 - ((r - nxt) / cap).abs();
        score -= nxt_fits * near.max(0.0) * near.max(0.0) * 6.0;
    }

    // Mild pressure against accumulating many open bins early (smooth in progress).
    score += (open_bins_count as f64) * (1.0 - progress) * 0.15;

    // New-bin candidate: penalize opening a fresh bin, more so mid/late stream,
    // unless the item is large relative to capacity (smooth term).
    let is_new = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += is_new * (5.0 + 10.0 * prog2) * (1.2 - fit_ratio);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity fractions (1/4, 1/3, 1/2 classes)
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;

    // Reward tight fits: exact or near-exact residual classes
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual < 10 {
        score -= 40.0;
    } else if post_residual < quarter {
        score -= 15.0;
    } else if post_residual < third {
        score -= 5.0;
    } else if post_residual < half {
        score += 5.0;
    }

    // Modulo-10 harmonic class of post_residual: dead space in [1..9] is valuable
    let pr_class = post_residual % 10;
    if pr_class == 0 {
        score -= 8.0; // residual aligned to small-item class
    } else if pr_class <= 3 {
        score -= 4.0;
    } else if pr_class >= 7 {
        score += 3.0; // awkward dead space
    }

    // Integer-division thresholds: post_residual buckets of size 10
    let bucket = post_residual / 10;
    score += bucket as f64 * 1.5;

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0; // keeps next item placeable in same bin
        } else if next_item_size <= post_residual + 5 {
            score += 2.0; // near miss, slight penalty
        }
        // Harmonic class match: next item belongs to same fraction class as residual
        let next_class = if next_item_size <= quarter { 0 } else if next_item_size <= third { 1 } else if next_item_size <= half { 2 } else { 3 };
        let res_class = if post_residual <= quarter { 0 } else if post_residual <= third { 1 } else if post_residual <= half { 2 } else { 3 };
        if next_class == res_class {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are terrible
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if all open bins fit poorly (many fitting bins with large mean residual), opening is fine
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (more filled)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Stream progression: late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.3;

    // Too many open bins: favor filling existing ones
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.8;
        if bin_residual < bin_capacity {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space: small post-residuals that no item (min size 1..=10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Moderate dead space penalty scaled by how much of the bin is wasted
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 40.0;

    // Prefer bins whose residual is close to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // If many bins can fit, mildly prefer not to fragment the emptiest bins
    if fitting_bins_count > 2 {
        score += (bin_residual as f64 - mean_residual).max(0.0) * 0.3;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 80.0 + open_bins_count as f64 * 10.0 + progress * 50.0;

    // New empty bin candidate: score = capacity residual + pressure
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    } else {
        // Existing bin gets a base discount for reusing space
        score -= 30.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        // next item won't fit here; slightly penalize leaving awkward gap
        score += (next_item_size as f64 - post_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 0.5 {
            score -= 60.0; // perfect fit for the next item
        } else if post_residual as f64 >= nxt {
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportional to wasted slack
            score += 10.0 + 0.5 * (nxt - post_residual as f64);
        }
        // Coupling: if post_residual fits next item AND leaves small dead space after that
        if post_residual as i64 - next_item_size as i64 >= 0 {
            let rem2 = post_residual as i64 - next_item_size as i64;
            score -= 15.0 * (1.0 - (rem2 as f64 / bin_capacity as f64));
        }
    } else {
        // Last item: just minimize residual
        score -= 20.0;
    }

    // Tight fits are good: small post_residual relative to mean residual favored
    score -= 8.0 * (mean_residual - post_residual as f64).max(0.0) / (bin_capacity as f64);
    score += 4.0 * (post_residual as f64 - mean_residual).max(0.0) / (bin_capacity as f64);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current item is large and no open bin fits well
    let is_new_bin = bin_residual == bin_capacity && bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score += 70.0 - 60.0 * pressure - 20.0 * big_item;
        // early stream: prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins to encourage filling
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score toward zero as post_residual -> 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        }
        // Penalize leaving a residual that nearly-but-not-quite fits the next item.
        else if post_residual >= next_item_size.saturating_sub(5) {
            score += 8.0;
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when open bins
    // are mostly full (mean residual low) or many bins already exist.
    if bin_residual == bin_capacity {
        let mean_r = if open_bins_count > 0 { mean_residual } else { 0.0 };
        // Default penalty for opening a new bin.
        score += 15.0;
        // If existing bins are nearly full, opening is fine.
        score -= (mean_r / bin_capacity as f64) * 30.0;
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many bins can fit the item, opening is wasteful.
        if fitting_bins_count > 2 {
            score += 10.0;
        }
    }

    // Mild preference for filling bins that are already heavily loaded.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill;

    // Encourage balance when many bins are open: avoid leaving one bin with huge
    // residual while others are full (spread load slightly).
    if open_bins_count > 3 && (bin_residual as f64) > mean_residual * 1.5 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fills (low post_residual) more strongly; later,
    // slightly tolerate larger residuals since future items are fewer.
    let tightness = post / cap;
    score += tightness * tightness * cap * (0.6 - 0.8 * progress).max(-0.4);

    // Dead-space penalty: residuals too small for typical items become waste.
    let dead = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += dead * (12.0 + 8.0 * (1.0 - progress));

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post_residual can still hold the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 6.0 + 4.0 * (1.0 - post / cap);
        } else if post > 0.0 {
            // penalize leaving a residual just barely below the next item size
            let gap = (nxt - post) / cap;
            score += gap * gap * 30.0;
        }
    }

    // New-bin candidate handling: opening a new bin is discouraged early,
    // but becomes attractive late or when the mean residual across open bins
    // is small (existing bins are nearly full).
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let pressure = (mean_residual / cap).max(0.0);
        let fit_exists = fitting_bins_count > 0;
        let mut penalty = 15.0 + 25.0 * (1.0 - progress);
        if fit_exists {
            penalty += 10.0 * (1.0 - pressure);
        }
        // Late stream with fragmented bins: allow opening fresh bins.
        if progress > 0.7 && pressure < 0.25 {
            penalty -= 20.0 * (progress - 0.7) / 0.3;
        }
        score += penalty;
    } else {
        // Mild reward for keeping bins consolidated when many bins are open.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into capacity-fraction bands.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Integer-division thresholds: post_residual bucketed by capacity / 4 classes.
    let class = post_residual / (bin_capacity / 4).max(1); // 0..4
    score += match class {
        0 => -6.0,  // near-perfect fit: strongly reward
        1 => -2.0,  // small leftover, still usable
        2 => 0.5,   // medium leftover
        3 => 1.5,   // large leftover
        _ => 2.5,   // bin was nearly empty already
    };

    // Modulo coupling: residuals divisible into next item's size are valuable.
    if next_item_size > 0 {
        let n = next_item_size as u32;
        if post_residual % n == 0 && post_residual >= n {
            score -= 3.0; // next item could exactly fill this bin
        }
        // Harmonic fraction: how well next item divides the leftover
        if post_residual >= n {
            let ratio = post / n as f64;
            score -= 1.5 * (1.0 - (ratio - ratio.floor()).abs() * 2.0).max(0.0);
        } else if n > post_residual {
            score += 0.5; // next item won't fit here; leftover riskier
        }
    }

    // Reward tight fits scaled by item size (large items deserve tight packing).
    let tightness = 1.0 - (post / cap);
    score -= 4.0 * tightness * (item_size as f64 / cap);

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Many open bins with high mean residual: prefer consolidation into fuller bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 4 && mean_residual > post + 10.0 {
        score += 2.0 * progress; // penalize spreading into emptier bins late in stream
    }

    // New-bin candidate: penalize opening a new bin unless this is a bad fit everywhere.
    if bin_residual == bin_capacity {
        let base_penalty = 12.0;
        let scarcity_bonus = if fitting_bins_count == 0 { 0.0 } else { 6.0 + 4.0 * (1.0 - post / cap) };
        score += base_penalty + scarcity_bonus - 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A residual that is too small for the smallest plausible item (1..100 unknown
    // distribution, so treat <= 10 as likely dead space) is heavily penalized.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    // Non-linear penalty: residuals just above the threshold are still risky.
    if post_residual > 0 && post_residual <= 20 {
        score += (20 - post_residual) as f64 * 3.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= (item_size as f64 / bin_residual as f64) * 15.0;

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Mild reward if next item can still fit; penalty proportional to leftover.
        score -= 5.0;
        let leftover_after_next = post_residual - next_item_size;
        if leftover_after_next < 10 {
            score += leftover_after_next as f64 * 4.0;
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; penalize leaving awkward gaps.
        score += post_residual as f64 * 0.5;
    }

    // New-bin candidate: make it moderately attractive only when open bins are
    // many or the fit would create dead space; otherwise keep it unattractive.
    if bin_residual == bin_capacity {
        let dead_space_risk = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
        let pressure = (open_bins_count as f64 / 8.0).min(1.0);
        score = score - 10.0 * pressure + 20.0 * (1.0 - pressure) + 30.0 * dead_space_risk * (1.0 - pressure);
        // Early in stream, fresh bins are cheap.
        score -= (1.0 - progress) * 8.0;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean
    // (keeps bin states homogeneous, easier future packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Stream progression (0.0 at start, ~1.0 at end).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate detection (brand-new empty bin).
    let is_new_bin = bin_residual == bin_capacity;

    // Mean-relative tightness: favor bins tighter than the current average,
    // preserving looser (larger-residual) bins for larger future items.
    score += 0.25 * ((bin_residual as f64 - mean_residual).max(0.0));

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post == 0.0 {
            // Perfect closure now: this bin is fully used, strongly favored.
            score -= 2.0 * cap;
        } else if nxt == post {
            // Aggressive 2-step match: next item exactly fills the leftover.
            // Two items, one bin: massive reward.
            score -= 1.5 * cap;
        } else if post > nxt {
            // Chainable leftover: next item also fits here. Reward scaled by
            // how snugly the next item fits (small leftover-after-next is best).
            score -= 0.5 * cap * (1.0 - (post - nxt) / cap);
        } else {
            // Dead space relative to the lookahead item. Penalize near-misses
            // hardest (leftover just below next_item_size is likely wasted);
            // weight fades as the stream progresses.
            let gap = nxt - post;
            score += 0.6 * cap * (1.0 - gap / nxt) * (1.0 - progress);
        }
    }

    // Last-chance bin (only open bin that can fit this item): reward using it
    // to avoid opening a new bin, scaled by fit quality and stream progress.
    if fitting_bins_count == 1 && !is_new_bin {
        let fit_quality = 1.0 - post / cap;
        score -= cap * (0.3 + 0.7 * fit_quality.max(0.0)) * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: penalize so it only wins when all open bins fit poorly
    // (its large base post-residual plus this penalty lose to any decent fit).
    // Penalty grows late in the stream, when minimizing bin count matters most.
    if is_new_bin {
        score += cap * (0.4 + 0.6 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squash the residual so near-perfect placements dominate.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 30.0;

    // Strong penalty if the leftover dead space is too small for any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize moderately sized waste less if it's large waste
            score += 4.0;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when open bins would waste a lot.
    if bin_residual == bin_capacity {
        score += 18.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no open bin fits -> must open new bin
        }
        // Opening new bins is cheaper early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing bins.
    if bin_residual != bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score -= pressure * 8.0;
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Slight bonus for bins that are already quite full (consolidation).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: post residual (waste minimization)
    let mut score = pr;

    // Non-linear polynomial coupling with stream progress:
    // early on, prefer tight fills less aggressively; late, penalize residual quadratically.
    let w = 1.0 + 2.0 * progress;
    score += w * norm_pr * norm_pr * cap * 0.5;

    // Smooth cubic interaction: residual^3 normalized, damped by progress
    score += (1.0 - progress) * norm_pr.powi(3) * cap * 0.25;

    // Reward near-perfect fits via smooth gaussian-like bump around small residual
    let tightness = (-norm_pr * norm_pr * 40.0).exp();
    score -= tightness * 30.0 * (0.5 + progress);

    // Penalize large leftover that could fit next item: encourage lookahead synergy
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            // good: next item can fit here
            let slack = (pr - nx) / cap;
            score -= 8.0 * (-slack * slack * 30.0).exp() * (1.0 - progress);
        } else {
            // bad: creates dead space relative to lookahead
            score += 6.0 * (nx - pr) / cap * (0.5 + progress);
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate handling: mildly penalize opening a new bin when
    // other bins fit, more so late in the stream.
    if bin_residual == bin_capacity {
        let open = open_bins_count as f64;
        score += 12.0 + 10.0 * progress + open * 0.5;
        // allow opening when item is large and current bins are crowded
        score -= it / cap * 10.0 * (mean_residual / cap);
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter bins)
    let dev = (pr - mean_residual) / cap;
    score += dev * 15.0;

    // Smooth item-size interaction: big items should prefer small residuals
    score += (it / cap) * norm_pr * 20.0 * (0.3 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by
    // capacity fractions and integer-division buckets.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity left over

    // Dead-space penalty grows super-linearly for small-but-nonzero leftovers.
    if post_residual > 0 && post_residual <= bin_capacity / 10 {
        score += (bin_capacity / 10 - post_residual) as f64 * 3.0;
    }

    // Harmonic bucket reward: leftovers in "useful" classes (>= half capacity,
    // or exact quarter classes) are worth keeping.
    let bucket = post_residual / (bin_capacity / 4).max(1); // 0..4
    match bucket {
        4 => score -= 20.0,             // near-empty bin, very reusable
        3 => score -= 12.0,             // > 75% free
        2 => score -= 6.0,              // half free
        1 => score -= 1.0,              // quarter free
        _ => {}                          // dead space, no reward
    }

    // Lookahead coupling: reward if next item fits exactly into the leftover
    // (perfect harmonic pairing), penalize if next item overshoots it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect pair
        } else if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            score -= 10.0 - waste as f64 * 0.15; // good but imperfect fit
        } else {
            score += (next_item_size - post_residual) as f64 * 0.05; // slight penalty
        }
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; prefer it
    // only when open bins are crowded (high mean residual pressure) or when
    // the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap;
        score -= pressure * 18.0; // crowded open bins -> new bin looks better
        score += (item_size as f64 / cap) * 8.0; // large items fine in fresh bins
        if open_bins_count == 0 {
            score -= 100.0; // must open the first bin
        }
    } else {
        // Favor bins whose residual is close to the item (tight fit).
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 5.0;
    }

    // Modulo arithmetic on post_residual: leftovers that are multiples of
    // common small item sizes (10, 20, 25) pair well with typical streams.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 25 == 0) {
        score -= 4.0;
    }

    // Mild stream-progression term: later in the stream, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += frac * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals that cannot fit the smallest
    // plausible next item (<= 10) are pure waste; penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10.0 - post) * 4.0;
    }

    // Penalize "awkward" gaps: too small for half a typical item but not tiny.
    if post_residual >= 10 && post_residual < 30 {
        score += 8.0 + 0.25 * (30.0 - post);
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = post - nx;
            score -= 12.0 - slack.min(20.0) * 0.3;
        } else {
            // Next item won't fit here: mild penalty proportional to gap.
            score += 2.0 + (nx - post).min(40.0) * 0.1;
        }
    }

    // Last-chance bin pressure: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins; few open bins -> new bins are cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual < bin_capacity {
        score -= pressure * 1.5;
    } else {
        // New-bin candidate: neutral baseline, adjusted by state.
        score += pressure * 2.0
            + (mean_residual - post).clamp(-20.0, 20.0) * 0.2
            + if fitting_bins_count == 0 { 0.0 } else { 3.0 };
    }

    // Early stream: slightly favor filling few bins deeply.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - t) * 1.0;

    // Tie-break toward bins with residual closest to the item (tight fit).
    score += ((bin_residual - item_size) as f64 - post) * 0.0; // no-op guard

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chaining
        } else if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it fills the leftover
            let fill = (next_item_size as f64) / (post_residual as f64);
            score -= 20.0 * fill;
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 8.0;
        }
    }

    // Compare post_residual against mean residual across open bins.
    if mean_residual > 0.0 {
        let ratio = (post_residual as f64) / mean_residual;
        if ratio < 0.5 {
            score -= 6.0; // leaves less waste than average
        } else if ratio > 1.5 {
            score += 5.0; // leaves much more waste than average
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mildly discourage opening a new bin unless it enables perfect chaining.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 45.0;
        } else {
            score += 10.0;
        }
    }

    // Early in the stream, allow more exploration of new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 {
        score -= 3.0 * (bin_residual == bin_capacity) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (small post-residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness;

    // Penalize wasted residual relative to the mean open-bin residual.
    let waste = (post_residual as f64) - mean_residual;
    score += 0.35 * waste;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Exact chain fit bonus.
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            // Penalize leaving a residual too small for the next item (dead space risk).
            score += 4.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins have poor residuals or the fit is bad.
    if bin_residual == bin_capacity {
        // Base mild preference against opening a new bin.
        score += 12.0;
        // But if residuals are large/wasted overall, opening is fine.
        score -= 0.25 * mean_residual;
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // If many bins already fit the item, definitely use an existing one.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Slight preference to fill bins that are already mostly full (consolidation).
    let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * fill * fill;

    // Mild pressure against too many open bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer small post-residual with smooth non-linear weighting.
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Stream-progress coupling: early on, waste matters less; later, tighten packing.
    let tightness = 1.0 + 1.5 * progress * progress;
    score *= tightness;

    // Dead-space penalty: residuals too small for typical items (<= ~20% capacity).
    let dead = ((20.0 - post).max(0.0) / 20.0).powi(3);
    score += 25.0 * dead * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward leaving space that can still host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= 10.0 * (1.0 - (post - nx) / cap);
        } else {
            score += 8.0 * (nx - post) / cap;
        }
    }

    // Mean-residual context: penalize deviating far from fleet average (fragmentation).
    let dev = (post - mean_residual).abs() / cap;
    score += 6.0 * dev * dev * (1.0 - progress);

    // Mild penalty for spreading across many bins when progress is low.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - progress);

    // New-bin candidate: slight default penalty so it's chosen only when open fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post-fit residual (capacity eighths) ----
    // Class 0: post_residual == 0 (perfect fill) -> strongly reward.
    // Class 1..3: tiny unusable remnants -> penalize (dead space).
    // Class 4..7: usable leftovers -> mild reward scaled by usability.
    let eighth = bin_capacity as f64 / 8.0;
    let class = (post_residual as f64 / eighth).floor() as i32;

    match class {
        0 => { score -= 60.0; }                       // perfect fill
        1 | 2 => { score += 45.0; }                   // sliver dead space
        3 => { score += 18.0; }                       // marginal remnant
        _ => { score -= 8.0 + 0.15 * post_residual as f64; } // roomy leftovers
    }

    // ---- Modulo arithmetic on post_residual ----
    // Residuals divisible by common small item sizes (10, 20, 25, 50) are
    // more likely to be exactly consumed later.
    let pr = post_residual;
    if pr > 0 {
        let mut harmonic_bonus = 0.0;
        if pr % 10 == 0 { harmonic_bonus += 6.0; }
        if pr % 20 == 0 { harmonic_bonus += 4.0; }
        if pr % 25 == 0 { harmonic_bonus += 4.0; }
        if pr % 50 == 0 { harmonic_bonus += 5.0; }
        score -= harmonic_bonus;
    }

    // ---- Lookahead coupling: does next item fit the post residual? ----
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: reward proportionally to how snugly next item lands.
            let slack = (post_residual - next_item_size) as f64;
            score -= 14.0 - 0.2 * slack.min(50.0);
        } else if post_residual > 0 && post_residual < next_item_size {
            // Residual is dead for the known next item: penalize.
            score += 10.0 + 0.1 * post_residual as f64;
        }
    } else {
        // Last item: prefer perfect fill above all.
        if post_residual == 0 { score -= 40.0; }
    }

    // ---- Last-chance bin: if this is the only fitting bin, avoid opening a new one ----
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Neutral-ish anchor: slightly above a decent fit, below a bad fit.
        // Encourage packing existing bins unless they'd create dead space.
        score = 55.0 + 0.05 * open_bins_count as f64;
        if next_item_size > 0 && bin_capacity >= next_item_size {
            score -= 6.0; // fresh bin can host the next item too
        }
        if step_index as f64 / total_items.max(1) as f64 > 0.9 {
            score += 10.0; // near stream end, avoid wasting fresh bins
        }
    }

    // ---- Mild consolidation pressure toward mean residual ----
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.03 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that no future item can use are heavily penalized.
    // Minimum item size is small (interface note: sizes 1..100), but tiny gaps are still
    // wasteful relative to capacity; treat gaps below a critical threshold as dead space.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 50.0;
    }

    // Perfect fit bonus: reward near-zero post residual strongly.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward tight fits proportionally: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 40.0;

    // Penalize large leftover gaps that are "awkward" (just above the smallest item,
    // i.e., likely to be stranded): gaps in [1, 15] get escalating penalty.
    if post_residual >= 1 && post_residual <= 15 {
        score += 30.0 - (post_residual as f64) * 1.5;
    }

    // Open bins pressure: prefer existing bins over opening new ones.
    score += open_bins_count as f64 * 3.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // rather than opening a new bin (avoids wasting this bin's remaining space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: make an empty bin less attractive unless the current
    // item fits poorly everywhere (large post_residual in existing bins).
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if the item is huge relative to mean residual, opening fresh is reasonable.
        if item_size as f64 > mean_residual + 10.0 {
            score -= 35.0;
        }
    }

    // Lookahead: if the next item could use the post residual, mild reward for leaving
    // a usable gap; if next item cannot fit in the gap, penalize slightly.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 10.0;
        } else {
            score += 8.0;
        }
    }

    // Mild stream progression term: late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: does next item fit in post_residual? Strong reward for chaining.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 60.0 + slack_after_next as f64 * 0.4;
            // Perfect 2-step chain
            if slack_after_next == 0 {
                score -= 150.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to wasted lookahead potential
            let overflow = next_item_size - post_residual;
            score += overflow as f64 * 0.5;
        }
    }

    // Compare post_residual against mean residual: keep residual distribution tight
    let mean_diff = post_residual as f64 - mean_residual;
    score += mean_diff.abs() * 0.15;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New empty bin candidate: penalize unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 120.0;
        // If next item is large and current fit is bad, opening a new bin is more attractive
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 40.0;
        }
        // Fewer open bins => cheaper to open new one
        score -= (open_bins_count as f64).sqrt() * 5.0;
    }

    // Progression: slightly tighten packing late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
