    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If next item would NOT fit in post_residual but would fit a fuller bin, mild penalty
    if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_residual {
        score += 10.0;
    }

    // Prefer filling bins with large residuals relative to mean (consolidate)
    if (bin_residual as f64) > mean_residual {
        score -= 8.0;
    } else {
        score += 8.0;
    }

    // Penalize opening new bins when many open bins could fit (fragmentation control)
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of opening a bin
        score += 20.0;
        // opening is attractive only if few fitting bins or item is huge
        if fitting_bins_count > 0 {
            score += 15.0 * (fitting_bins_count as f64);
        }
        if item_size > bin_capacity * 3 / 4 {
            score -= 25.0;
        }
        // early stream: allow more bins; late stream: discourage
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Reward using bins that are already fairly full (keep small residuals concentrated)
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 15.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual (tighter fit preferred)
    let mut score = pr;

    // Smooth polynomial coupling of residual with stream progress:
    // early on, tolerate larger residuals; later, penalize them strongly.
    let prog_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 40.0 * norm_pr * norm_pr * (0.5 + prog_poly);
    score -= 25.0 * norm_item * (1.0 - norm_pr) * (1.0 - prog_poly);

    // Non-linear dead-space penalty: residuals too small to be useful
    let dead = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        gap * gap
    } else {
        0.0
    };
    score += 30.0 * dead;

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild preference for bins below mean residual (balance spreading)
    score += 5.0 * ((pr - mean_residual) / cap).abs();

    // Slight preference for fewer open bins early (encourage filling)
    score -= 3.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress) * norm_item;

    // Reward perfect fits smoothly
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity fractions (1/4, 1/3, 1/2) and reward residues that align
    // with common item-size classes (multiples of 10, 25, 50).
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit is always excellent
    } else {
        // Dead-space penalty grows super-linearly for tiny unusable slivers.
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0; // sliver: nearly unusable
        }
        // Modulo-10 alignment: residuals divisible by 10 pair well with
        // item sizes drawn on a 10-grid.
        if pr % 10 == 0 {
            score -= 6.0;
        }
        if pr % 25 == 0 {
            score -= 3.0;
        }
        // Fractional capacity classes: residual near C/4, C/3, C/2 are
        // "harmonic" slots many item classes can still use.
        let frac = pr as f64 / cap;
        if (frac - 0.5).abs() < 0.05 { score -= 5.0; }
        if (frac - 1.0/3.0).abs() < 0.05 { score -= 3.0; }
        if (frac - 0.25).abs() < 0.05 { score -= 2.0; }
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward; if it cannot fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            score += 4.0;
        }
        // Harmonic pair check: item + next divisible into capacity cleanly
        if (item_size + next_item_size) % 50 == 0 && pr >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bonus: only one open bin fits, keep it alive.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening fresh is only attractive when
    // open bins are crowded or the fit here would be terrible.
    if bin_residual == bin_capacity {
        let tight = mean_residual / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = post_residual < 10;
        if tight < 0.35 || bad_fit {
            score -= 18.0 + 10.0 * (1.0 - tight) + 5.0 * progress;
        } else {
            score += 25.0; // prefer reusing reasonably-filled bins
        }
    } else {
        // Reward filling bins closer to full, scaled by how many bins fit.
        score -= (bin_residual - post_residual) as f64 * 0.1;
        if fitting_bins_count > 3 {
            score += 1.5; // plenty of alternatives, less urgency
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score -= open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit
    // typical future items are "dead space" -> heavy penalty.
    let dead_threshold: f64 = 10.0; // smallest useful gap
    if (post_residual as f64) < dead_threshold {
        score += 100.0 * (dead_threshold - post_residual as f64);
    }
    // Penalty if post_residual can't fit the lookahead item either.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
        // Extra penalty proportional to how much of the next item is wasted.
        score += 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward when post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 20.0 / (1.0 + tightness);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones.
    if bin_residual == bin_capacity {
        // Candidate for a brand-new bin: baseline plus pressure.
        score += 15.0 + 3.0 * open_bins_count as f64;
        // If a fitting bin exists elsewhere, new bin is less attractive.
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    } else {
        // Using an existing bin reduces open-bin pressure slightly.
        score -= 1.0 * open_bins_count as f64;
    }

    // Mean-residual coupling: prefer bins with residual close to mean
    // (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Early stream: be more willing to open bins (future flexibility);
    // late stream: consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize creating small unusable dead space (waste fragments).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits the post residual, punish otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            score += 8.0;
        }
        // Exact chain fit is very valuable.
        if next_item_size == post_residual {
            score -= 30.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins have poor fits.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 45.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 35.0 * (1.0 - progress);
        // If many open bins with high mean residual, prefer reusing them.
        score += 0.3 * mean_residual;
        // If the item is large, a fresh bin gives more flexibility.
        if item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild preference for bins below mean residual (balance load across bins).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight preference to keep few bins when many are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress.
    // Early on, prefer bins that leave flexible residual; later, prefer tight fills.
    let flexibility_bias = (1.0 - progress) * (norm_post - norm_post * norm_post) * 24.0;
    let tightness_bias = progress * (norm_post * norm_post) * 30.0;

    let mut score = post + flexibility_bias + tightness_bias;

    // Penalize residual far from mean (outlier dead space), smoothly.
    let dev = (post - mean_residual) / cap;
    score += dev * dev * 12.0;

    // Reward near-perfect fills smoothly (post_residual close to 0).
    score -= (1.0 - norm_post).powi(6) * 18.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 10.0 * (1.0 - slack * slack);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize creating residual too small for the next item (dead space).
        score += 8.0 * (next_item_size as f64 - post) / cap;
    }

    // Mild penalty for proliferating bins relative to stream length.
    score += open_bins_count as f64 * 0.35;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // 0..1 fraction of capacity wasted
    let class = (frac * 10.0).floor() as i32; // 10 harmonic classes of residual

    // Penalize mid-range residuals (hardest to fill later); reward near-zero or "perfect" small gaps.
    match class {
        0 => score -= 30.0,                       // perfect/tight fit
        1 => score -= 18.0,
        2 => score -= 8.0,
        3 => score += 6.0,                        // awkward dead zone
        4 => score += 12.0,
        5 => score += 15.0,
        6 => score += 10.0,
        7 => score += 4.0,
        8 => score -= 4.0,                        // large residual still useful
        _ => score -= 10.0,                       // mostly-empty bin: good
    }

    // Modulo-10 arithmetic on post_residual: gaps divisible by 10 align with item granularity.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let nfrac = (post_residual - next_item_size) as f64 / cap;
            score -= 12.0 * (1.0 - nfrac);
        } else {
            // next item cannot use this gap: penalize dead space proportionally
            score += 0.15 * frac * cap;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are badly fragmented.
    let avg_gap = mean_residual / (open_bins_count.max(1) as f64);
    if bin_residual == bin_capacity {
        // opening fresh bin is bad early / when existing bins have room
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + 60.0 * progress - 0.5 * avg_gap;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 0.1 * next_item_size as f64;
        }
    }

    // Mild pressure against accumulating many open bins with fragmented space.
    score += 0.05 * open_bins_count as f64 * frac;

    // Progress-based tightening: later in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * frac * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever hold a realistic
    // future item (<= 10) are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Residuals that can only fit the smallest items are near-dead space.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }
    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residual that can still accommodate the lookahead item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Post-residual too small for next item: mild dead-space penalty.
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin before opening a new one: strong reward if fit is decent.
    if fitting_bins_count == 1 && bin_residual != bin_capacity && post_residual < 10 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fit is bad (large dead space).
    if bin_residual == bin_capacity {
        score += 15.0;
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Slight preference for tight bins (low residual relative to mean).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, already handled by base score.

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        // Exact match gets the biggest bonus; larger gaps get proportionally less.
        score -= (bin_capacity as f64) * (1.0 - gap / (bin_capacity as f64)) * 0.9;
    }

    // Penalize leaving dead space that the next item cannot use at all.
    if next_item_size > 0 && post_residual < next_item_size {
        // Dead space penalty scaled by how close post_residual is to being usable.
        let waste_ratio = post_residual as f64 / (bin_capacity as f64);
        score += waste_ratio * 15.0;
    }

    // Compare post_residual relative to mean residual across open bins:
    // bins with below-average residual (tighter bins) are preferred to keep
    // large residual bins flexible for future big items.
    let mr = mean_residual.max(1.0);
    if (post_residual as f64) < mr {
        score -= (mr - post_residual as f64) * 0.5;
    } else {
        score += (post_residual as f64 - mr) * 0.25;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item is large
    // and would leave a very unusable residual in existing bins, or the stream is early
    // and there are few open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_penalty = 30.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        new_bin_penalty -= progress * 20.0;
        // If the item is big relative to capacity and would leave a tiny residual
        // anywhere else, a fresh bin is attractive: post_residual here = capacity - item.
        if (post_residual as f64) < 10.0 {
            new_bin_penalty -= 15.0;
        }
        // Lookahead: if next item is large and would not fit in typical residuals,
        // opening a fresh bin now is fine.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            new_bin_penalty -= 10.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but only if it stays "usable"
    // or is exactly consumed. Penalize dead space that no plausible item can use.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is excellent
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect fit
    } else {
        // dead-space penalty grows as residual becomes hard to fill
        let unusable = (post_residual as f64).min(80.0);
        score += 0.15 * unusable;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else {
        // mild penalty when many bins compete, to break ties toward tighter fits
        score += 0.5 * (fitting_bins_count as f64).min(10.0);
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward heavily; if next item cannot fit, mild penalty for wasting space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 8.0;
        }
    }

    // Global state: when mean residual is high, bins are loose; prefer
    // consolidating into fuller bins (post_residual small already handles that),
    // but add small pressure to keep open bin count low.
    score += 0.3 * (open_bins_count as f64).sqrt();

    // Time horizon: late in the stream, avoid opening new bins since
    // leftover capacity has less future value.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus late-stream penalty.
        score += 30.0 + 60.0 * progress;
        // Opening a new bin is fine if item is huge relative to capacity
        // (nothing else to lose) — reduce penalty for large items.
        score -= 0.2 * item_size as f64;
    } else {
        // Late stream: favor using existing bins more aggressively.
        score -= 10.0 * progress;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (it's one of the fullest), slightly prefer it to consolidate fullness.
    let diff = mean_residual - bin_residual as f64;
    score -= 0.2 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;
    // Smooth non-linear coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let progress_term = progress * progress * (1.0 - progress) * 4.0;
    score -= progress_term * pr * 0.5;
    // Reward tight fits more strongly as stream progresses
    let tightness = (bin_capacity as f64 - pr) / bin_capacity as f64;
    score -= tightness * tightness * (1.0 + 2.0 * progress);
    // Penalize dead space: quadratic in post_residual
    score += (pr / bin_capacity as f64).powi(2) * 10.0;
    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }
    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let match_bonus = if pr >= ns { 1.0 - ((pr - ns) / bin_capacity as f64).powi(2) } else { -1.0 };
        score -= match_bonus * (3.0 + 3.0 * progress);
    }
    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64 - 5.0 * progress;
    }
    // Slight attraction to bins below mean residual (consolidation)
    score += 0.05 * (mean_residual - bin_residual as f64);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by small classes are reusable.
    let pr = post_residual;
    if pr > 0 {
        // Penalize dead space that cannot host common small items (1..=10 classes).
        if pr < 10 {
            score += 60.0; // tiny unusable sliver
        } else {
            // Reward residuals matching harmonic classes (multiples of 10, 25, 50).
            if pr % 10 == 0 { score -= 12.0; }
            if pr % 25 == 0 { score -= 8.0; }
            if pr % 50 == 0 { score -= 6.0; }
            // Integer-division tier: large residuals are flexible.
            let tier = pr / 25; // 0..4
            score -= 5.0 * tier as f64;
        }
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 + 8.0 * (1.0 - slack / cap); // chainable placement
            if (pr - next_item_size) % 10 == 0 { score -= 5.0; }
        } else {
            score += 15.0; // breaks the chain
        }
    }

    // Last-chance bonus: only bin that fits item; avoid opening new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate logic: prefer it only when all fits are poor.
    if bin_residual == bin_capacity {
        // Opening a new bin: baseline cost plus per-open-bin overhead.
        score = 0.55 * cap + 3.0 * open_bins_count as f64;
        // Late in stream, opening new bins is less costly (fewer future pairings lost).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // If the item fits snugly nowhere else, opening is fine (handled by others' penalties).
        // Penalize opening when a perfect-ish fit exists among open bins.
        if fitting_bins_count >= 1 {
            score += 10.0;
        }
    } else {
        // Prefer tight fits: reward small post_residual relative to capacity.
        score -= 10.0 * (1.0 - post_residual as f64 / cap);
        // Slight preference for bins below mean residual (keeps balance).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        // Perfect fit celebration.
        if post_residual == 0 { score -= 40.0; }
    }

    // Mild stream-phase modulation: early on, be pickier about large residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;
    let open = open_bins_count as f64;
    let fit = fitting_bins_count as f64;
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };

    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post + 0.02 * open * (post / cap);

    if post_residual == 0 {
        score -= 15.0 + 5.0 * (1.0 - progress);
    } else if next > 0.0 && post < next {
        let gap = next - post;
        let severity = if post <= 0.20 * next {
            4.0
        } else if post <= 0.50 * next {
            2.5
        } else {
            1.2
        };

        score += 6.0 + severity * gap + 0.20 * next;

        if post <= 0.02 * cap {
            score += 5.0;
        }
    } else if next > 0.0 && post >= next {
        score -= 4.0 + 0.25 * next + 3.0 * (1.0 - post / cap);
    } else {
        score *= 0.05;
    }

    if is_new_bin {
        if fitting_bins_count > 0 {
            score += 12.0 + 0.45 * open + 0.25 * fit + 6.0 * progress;

            if next > 0.0 {
                if post >= next {
                    score -= 3.0;
                    if mean_residual < next {
                        score -= 4.0;
                    }
                }

                if mean_residual >= next {
                    score -= 3.0;
                } else {
                    score += 1.5;
                }
            }

            if item_size as f64 >= 0.70 * cap {
                score -= 1.5;
            }
        } else {
            score -= 4.0;
        }
    } else {
        score -= 0.18 * open;

        if fitting_bins_count == 1 {
            score -= 5.0 + 4.0 * (1.0 - progress);
        }

        if post_residual == 0 {
            score -= 1.0 + 0.10 * open;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer post_residual exactly matching the next item size (perfect 2-step fit)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / (bin_capacity as f64)) - 20.0 * (diff == 0.0) as f64;
        // Penalize post-residuals that are too small to fit the next item (dead space for lookahead)
        if (post_residual as u32) < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Reward tight fits relative to mean residual
    if (post_residual as f64) < mean_residual {
        score -= 0.3 * (mean_residual - post_residual as f64);
    } else {
        score += 0.2 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, use it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize tiny dead space that likely becomes unusable
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 10.0 + 0.1 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late-stream tightening: prefer fuller packing as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a strong discount.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can never fit a typical item again.
    if post_residual < 10 {
        score -= 25.0; // near-perfect fill, strongly reward
    } else if post_residual < 20 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if next item fills the bin almost exactly after this one.
        let two_step = post_residual - next_item_size;
        if two_step < 10 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual is dead space for the known next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // existing bin fits well. Penalize the fresh bin mildly by default.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // A new bin wastes capacity when many bins are already open with slack.
        score += 20.0 + 0.3 * open_bins_count as f64 * (1.0 - progress);
        // But if mean residual is small (bins are nearly full), a new bin is fine.
        score -= 0.5 * mean_residual;
        // If the item is large relative to capacity, new-bin penalty softens.
        score -= 0.1 * item_size as f64;
    }

    // Mild global pressure: as the stream progresses, encourage consolidating
    // into fewer bins by rewarding placements into already-open bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - fit_ratio);

    // Small penalty for leaving residual far from the mean (fragmentation).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post-residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score *= 1.0 - 0.35 * p2 - 0.15 * p3;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 18.0 * (0.5 + progress);

    // Penalize dead space: cubic in normalized post residual
    score += 30.0 * norm_pr * norm_pr * norm_pr;

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
    } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
        score += 6.0 * progress;
    }

    // Penalize deviation from mean residual (fragmentation pressure)
    score += 0.15 * (pr - mean_residual).abs();

    // New empty bin candidate: penalize, less so late in stream or when it's a perfect fit
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        let penalty = 40.0 * (1.0 - progress) + 5.0 * (1.0 + openness * 0.05);
        score += penalty - 10.0 * (1.0 - fit).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space classes via modulo
    let pr = post_residual;
    let class = pr % 10; // residue class mod 10
    // Penalize "awkward" residues that are hard to fill with typical items
    let awkward = match class {
        1 | 2 | 3 | 7 | 8 | 9 => 1.0,
        0 | 5 => -0.5,
        _ => 0.0,
    };
    score += awkward * (pr as f64).sqrt() * 1.5;

    // Integer-division thresholds: post_residual bucket by quarter capacity
    let quarter = (pr * 4) / bin_capacity.max(1);
    score += match quarter {
        0 => -6.0,           // very tight fit -> excellent
        1 => -2.0,
        2 => 2.0,
        _ => 5.0,            // wasteful
    };

    // Reward near-perfect fills
    if pr == 0 {
        score -= 25.0;
    } else if pr <= 3 {
        score -= 12.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (-slack / 10.0).exp();
        } else {
            // next item won't fit here; mildly penalize leaving large gaps
            score += (pr as f64) * 0.05;
        }
    }

    // New-bin candidate handling: only prefer fresh bin when it enables
    // a good harmonic placement or no open bin fits well.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        let mut nb = 18.0;
        // cheaper to open new bin early in stream / many open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb -= 8.0 * (1.0 - progress);
        nb -= (open_bins_count.min(20) as f64) * 0.4;
        // if next item is large, a fresh bin may be valuable
        if next_item_size >= bin_capacity / 2 {
            nb -= 6.0;
        }
        // if this bin would be the only fitting bin, opening new is wasteful
        if fitting_bins_count <= 1 {
            nb += 25.0;
        }
        // mean residual high -> open bins have room, discourage new bin
        nb += (mean_residual - cap_f * 0.3).max(0.0) * 0.15;
        score = score.max(0.0) + nb + 5.0;
    }

    // Slight tie-break toward fuller mean usage
    score += (mean_residual - post_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post residual
    // matches the next item size well (chain fit).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff <= 10.0 {
            // Post residual almost exactly fits next item: chain two items.
            score -= 300.0 - diff * 15.0;
        } else {
            score += diff * 0.8;
        }
        // If next item cannot fit after this placement, penalize dead space growth.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly discourage opening a new bin when only
    // this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in
    // the stream and when open bins exist with room.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 + 80.0 * (1.0 - progress) + (open_bins_count as f64) * 5.0;
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64) >= item_size as i64 {
            score -= 30.0; // new bin could still chain next item
        }
    }

    // Mild penalty for large open-bin count fragmentation.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 25.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (post_residual as f64) / (next_item_size as f64).max(1.0);
        }
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer fuller bins among many open bins
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio * (1.0 + open_bins_count as f64 / 20.0);

    // Time horizon: early on, be willing to open fresh bins; late, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    score += new_bin * (60.0 - 50.0 * progress);

    // If bin residual deviates strongly from mean, mild penalty for fragmentation
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - progress);

    // Discourage opening new bins when many bins already fit the item well
    if new_bin > 0.0 && fitting_bins_count > 2 {
        score += 10.0 * (fitting_bins_count as f64 - 2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let size_frac = item_size as f64 / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping.
    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // later in the stream, waste is penalized more aggressively.
    let prog_penalty = norm_pr * norm_pr * (0.5 + 2.0 * progress) * cap;
    score += prog_penalty;

    // Cubic dead-space term: small residuals that are hard to reuse later.
    let dead = if pr > 0.0 {
        let inv = cap / pr;
        cap * 0.5 / (inv * inv)
    } else {
        0.0
    };
    score -= dead * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly favor the only bin that fits, scaled by progress.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 40.0 * progress + 10.0 * size_frac;
    }

    // Prefer bins whose residual is below mean (filling fuller bins first),
    // with smooth interaction against progress.
    let mean_gap = (mean_residual - bin_residual as f64) / cap;
    score -= mean_gap * (10.0 + 30.0 * progress);

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this bin; otherwise slightly penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let tight = 1.0 - (pr - nx) / cap;
            score -= (8.0 + 20.0 * progress) * tight;
        } else {
            score += 3.0 + 6.0 * progress;
        }
    }

    // Mild penalty for spreading across many open bins early on.
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).recip();
        let badness = (mean_residual / cap) * 0.5 + (1.0 - size_frac) * 0.5;
        score = 20.0 + 60.0 * progress - scarcity * (30.0 + 50.0 * badness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a "usable"
    // residue class (multiples of 10) are rewarded; awkward leftovers penalized.
    let post = post_residual as i64;
    let cap = bin_capacity as f64;

    // Reward small post_residual (tight fit) nonlinearly.
    let tight = (1.0 - (post as f64) / cap).max(0.0);
    score -= 30.0 * tight * tight;

    // Harmonic class penalty: leftover mod 10 measures "dead space" granularity.
    let class = post % 10;
    if class == 0 {
        score -= 12.0; // perfectly divisible leftover: excellent
    } else if class <= 2 {
        score -= 4.0;
    } else if class >= 8 {
        score += 6.0; // nearly full leftover classes are odd dead space
    } else {
        score += (5 - class as i64).abs() as f64 * 2.0;
    }

    // Integer-division threshold: leftover that can still host the next item is gold.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            // Exact divisibility: next item will perfectly fill this bin.
            if post % (next_item_size as i64) == 0 && post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            score += 10.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // Many options: prefer tighter fills, mild penalty for waste.
        score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: only attractive when no open bin fits well or stream is young.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_open = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 20.0 };
        score += 15.0 + 40.0 * (1.0 - progress) - bad_open
            + (open_bins_count as f64) * 2.0
            - (mean_residual / cap) * 10.0;
    }

    // Penalize bins deviating from mean residual (prefer balanced exploitation).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1..10)
    // are unusable gaps; penalize them sharply, scaled by how dead they are.
    let dead = (post_residual as f64 - 10.0).max(0.0);
    if post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 8.0;
    } else {
        score -= dead * 0.6; // mild reward for leaving large usable residuals
    }

    // Perfect fit bonus: filling a bin exactly is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 4.0;
        // But allow new bins early in the stream when few bins exist.
        if open_bins_count < 3 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // creating a gap that blocks the known next item is bad
        score += 10.0;
    }

    // Mild preference for bins below mean residual (balance residual spread).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills (small post_residual is already the base score).

    // Aggressive 2-step lookahead: if the next item exactly fills post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // Next item fits in the remaining space: mild reward proportional
            // to how well it matches the post residual.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover space: penalize dead space,
            // more so when the leftover is small-but-unusable (worst case).
            let leftover = post_residual as f64;
            if leftover > 0.0 && leftover < next_item_size as f64 {
                score += 30.0 * (1.0 - leftover / bin_capacity as f64);
            }
        }
    } else {
        // Last item: prefer tightest fit, no lookahead concerns.
        score -= 20.0;
    }

    // Coupling with mean residual: bins with residual below the mean are
    // "dying" bins; using them consolidates space. Penalize placing into
    // bins whose residual is far above the mean (wasteful of large space).
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= (mean_residual - post_f).min(50.0) * 0.5;
    } else {
        score += (post_f - mean_residual).min(50.0) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Late in the stream, be more conservative about spreading across bins:
    // tighten preference for tight fits as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (1.0 - post_f / bin_capacity as f64);

    // Many open bins: prefer consolidation into existing (smaller-residual) bins.
    if open_bins_count > 2 {
        score += 0.15 * open_bins_count as f64 * (post_f / bin_capacity as f64);
    }

    // New-bin candidate: only open a new bin when the item is large relative
    // to capacity and no bin fits well (post residual here == capacity - item).
    if bin_residual == bin_capacity {
        // Base cost of a new bin; offset when item is big (new bin is efficient)
        let efficiency = item_size as f64 / bin_capacity as f64;
        score += 80.0 - 60.0 * efficiency;
        // If next item would fit in the fresh bin's residual, opening is fine.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: small post-residual is desirable.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Penalize large dead space, especially when it can't fit typical future items.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 10.0 {
        score += 15.0; // tiny unusable slivers are worse than moderate space
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += 5.0 * (next_item_size - post_residual) as f64 / item_size.max(1) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Tightness reward: prefer bins that are already well-filled.
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 8.0 * fill_ratio;

    // Global state: with many open bins, prefer consolidating into existing ones.
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean, it's a good compact target.
    let res_diff = mean_residual - bin_residual as f64;
    score += 0.05 * res_diff;

    // Time horizon: early in the stream, be more willing to open new bins (score new bins higher relative),
    // late in the stream, squeeze everything into open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses, so late items prefer old bins.
        score += 10.0 + 25.0 * progress;
        // But early on, opening a fresh bin is cheap and gives flexibility.
        if progress < 0.3 {
            score -= 8.0;
        }
        // Don't open a new bin if an existing bin would be nearly perfect.
        if post_residual <= 5 && fitting_bins_count >= 1 {
            score += 60.0;
        }
    } else if progress > 0.7 {
        score -= 5.0; // late stream: strong preference for existing bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic in normalized post_residual (tight fits favored)
    let mut score = 2.0 * norm_pr + 3.0 * norm_pr * norm_pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on tolerate larger residuals; late in stream punish them harder
    let coupling = norm_pr * (0.5 + 2.5 * progress * progress);
    score += coupling;

    // Interaction with mean residual: prefer bins below-average residual (tighter bins)
    let mean_norm = mean_residual / cap;
    score += 1.5 * (norm_pr - mean_norm).abs() * (1.0 - progress);

    // Last-chance bonus: strongly reward using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead: penalize leaving residual that cannot fit the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            // next item still fits here: reward
            score -= 1.0 * (ns / cap);
        } else if pr > 0.0 {
            // dead space for next item: penalize proportionally to waste
            score += 2.0 * (pr / cap) * (1.0 - pr / ns.max(1.0) as f64);
        }
    }

    // New-bin candidate: neutral-ish score so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score = 1.0 + 3.0 * norm_pr + 2.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins to encourage consolidation
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead-space classes by capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let fifth = bin_capacity / 5;

    // Penalize residuals that are hard to fill (small but nonzero)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < quarter {
        score += 15.0;
    }

    // Reward residuals that are multiples of common item classes (harmonic bins)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % fifth == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % quarter == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 25.0;
        } else {
            score -= (post_residual - next_item_size) as f64 * 0.5;
            if post_residual == next_item_size {
                score -= 40.0; // chain fit
            }
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer tight bins over loose ones
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= tightness * 20.0;

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 50.0;
        } else {
            score += 35.0 + (fitting_bins_count as f64) * 2.0;
        }
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Near-perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many bins open, prefer compacting into existing space.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 4.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Slightly prefer bins with above-average residual (they stay useful longer).
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate: only attractive when the item is large relative to
    // capacity and no existing bin would leave a tight, useless gap.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill >= 0.9 {
            score -= 30.0; // large item: fresh bin is fine
        } else {
            score += 20.0 + 40.0 * (1.0 - fill); // discourage wasting fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits: small post residual is already good (base term).
    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            // Perfect chaining: item + next item exactly fills the bin.
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item can chain into this bin; reward proportionally to tightness.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item cannot chain: penalize leaving dead space that likely
            // becomes unusable, scaled by how large the gap is.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize post_residual that is too small to hold any plausible item
    // (dead space), especially when it exceeds the minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Compare against mean residual: prefer bins that keep residuals balanced
    // but reward using bins with larger-than-mean residual (big bins absorb items).
    let cap = bin_capacity as f64;
    let rel = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * rel;

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Make it attractive only when the item is large relative to capacity or
    // no good chaining exists; otherwise slightly discourage bin proliferation.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        if item_size > 60 || next_item_size == 0 {
            score -= 8.0 * fill_ratio;
        } else {
            score += 12.0;
        }
    }

    // Late in the stream, tighten up: prefer compact placements to close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Lookahead: bonus if the next item can fit into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            // Penalize leaving residuals that no small next item can use.
            score += 6.0;
        }
        // Chain fit: next item leaves room for another mid-size item.
        if next_item_size > 0 && post_residual >= next_item_size {
            let chain = post_residual - next_item_size;
            if chain >= 10 {
                score -= 4.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize spreading across many open bins when residuals are high.
    if open_bins_count > 3 {
        let avg_pressure = mean_residual / (bin_capacity as f64);
        score += 5.0 * avg_pressure;
    }

    // New-bin candidate logic: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 45.0 + (open_bins_count as f64) * 2.0;
        // But if this bin is not a last chance and item leaves a large residual elsewhere,
        // opening fresh is less painful when the item is large.
        if item_size > 60 {
            score -= 20.0;
        }
        // Late in the stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.8 {
            score -= 10.0;
        }
        // If many bins fit the item, opening new is wasteful.
        if fitting_bins_count > 2 {
            score += 25.0;
        }
    }

    // Mild preference for filling bins that are already mostly full.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / (bin_capacity as f64);
    score -= 8.0 * fill_ratio;

    // Penalize creating residuals that are awkwardly small (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * (0.5 + 0.5 * progress);
    score += 12.0 * (poly - norm_post);

    // Tight fit reward: penalize large post_residual super-linearly
    score += 6.0 * norm_post * norm_post * (1.0 + progress);

    // Penalize opening a new bin when open bins could fit
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 15.0 + 10.0 * (1.0 - progress);
    }

    // Last-chance fitting: strongly favor using this bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && (next_item_size as f64) > post {
        score += 3.0 * ((next_item_size as f64 - post) / cap);
    }

    // Mean residual alignment: prefer bins close to mean residual
    let dev = (post - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well the leftover partitions the capacity.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Penalize residual classes that are "dead zones" (hard to fill later).
    // Classes: post_residual mod 10 and integer division thresholds.
    let class10 = post_residual % 10;
    let class20 = post_residual % 20;
    let div10 = post_residual / 10;

    // Small-but-not-tiny residuals are dead space; large residuals are valuable.
    if post_residual > 0 {
        score += 12.0 * (1.0 - frac);
        // Dead zone: residual in (0, 10) exclusive of perfect fills
        if class10 != 0 && post_residual < 25 {
            score += 15.0;
        }
        // Harmonic bonus: residual divisible by common item granularities
        if class10 == 0 { score -= 6.0; }
        if class20 == 0 { score -= 3.0; }
        // Mid-range residuals (30..50) pair well with many item sizes
        if (30..=50).contains(&post_residual) { score -= 8.0; }
        // Very large residual: near-empty bin, keep it flexible
        if post_residual >= 70 { score -= 5.0; }
        // div10 thresholds: reward fine-grained classes
        score -= 1.5 * (div10 as f64).min(6.0);
    } else {
        // Perfect fill: maximal reward
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item cannot use leftover: penalize proportional to waste
            score += (next_item_size - post_residual).min(50) as f64 * 0.2;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when alternatives are poor.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.1 * open_bins_count as f64;
        // Early in stream, new bins are cheap; later, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Prefer tighter bins overall (small residual before placement = good packing).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild preference for reducing open bin count pressure.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item can use are heavily penalized.
    // Smallest possible item is 1, so post_residual == 0 is perfect; tiny unusable gaps
    // (1..=5) are "dead" and get a large penalty.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 5 {
        score += 40.0; // dead space
    } else if post_residual <= 10 {
        score += 15.0; // near-dead space
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 25.0 * tightness;

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> favor consolidating into existing bins;
    // few open bins -> allow opening a new bin for good fits.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 8.0 * bin_pressure;

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive for large items that would leave dead space
        // elsewhere, but costly when open bins are few or the fit is tight elsewhere.
        let dead_space_elsewhere = if post_residual <= 5 { 1.0 } else { 0.0 };
        score -= 20.0 * dead_space_elsewhere;
        score += 10.0 + 5.0 * bin_pressure;
        // Don't open a new bin for a small item.
        if item_size < 40 {
            score += 30.0;
        }
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize if next item is large and this bin would be nearly full anyway.
    if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 5.0;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a "junk"
    // bin; prefer filling it rather than leaving it stranded.
    if (bin_residual as f64 - mean_residual).abs() < 5.0 {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/near-exact fits (post_residual small).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 24.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if the next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly consumes what remains.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 18.0 * (1.0 - chain_slack / (bin_capacity as f64));
            score -= 6.0; // bonus for any feasible lookahead fit
        } else {
            // Next item cannot follow here: penalize proportionally to the wasted gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.35 * gap;
        }
    }

    // Penalize leaving dead space below the minimum item size (unusable residual).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0 * (10 - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless residuals of open bins are poor.
    if bin_residual == bin_capacity {
        score += 10.0;
        score += 0.5 * (open_bins_count as f64);
        // If mean residual is large, open bins are healthy -> discourage new bin more.
        score += 0.25 * mean_residual;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    } else {
        // Mild preference for tighter existing bins relative to the mean residual.
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later
    // (items are 1..=100, so residual < smallest plausible gap is waste).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (chaining).
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 35.0;
        } else if (post_residual as u32) >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; mild penalty proportional to waste.
            score += 0.05 * (post_residual as f64);
        }
    }

    // Compare against mean residual: bins far below mean residual are
    // "sponge" bins; using them preserves larger residuals elsewhere.
    let residual_gap = mean_residual - (post_residual as f64);
    if residual_gap > 0.0 {
        score -= 0.15 * residual_gap;
    } else {
        score += 0.10 * (-residual_gap);
    }

    // Time horizon: late in the stream, consolidation matters more;
    // early on, spreading is safer.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score -= 20.0 * progress * tightness;

    // New-bin candidate: opening a new bin is only attractive when the item
    // is large and no existing bin is a good fit, or many bins are open
    // with fragmented residuals.
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64) * (mean_residual / (bin_capacity as f64));
        let large_item_bonus = if item_size > bin_capacity / 2 { 10.0 } else { 0.0 };
        score += 55.0 + fragmentation - large_item_bonus
            - (if fitting_bins_count <= 1 { 45.0 } else { 0.0 });
    }

    // Slight penalty for spreading across too many bins.
    score += 0.02 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: penalize waste, but with non-linear shaping (quartic smoothness)
    let mut score = x * x * x * (6.0 * x * x - 15.0 * x + 10.0) * cap
        + pr * (1.0 - 0.5 * x);

    // Stream-progress coupling: later in the stream, tolerate waste less (tighter packing)
    let tightness = 1.0 + 1.5 * progress * (1.0 - x);
    score *= tightness;

    // Interaction: post residual vs mean residual — reward bins near mean fill (harmonic placement)
    let dev = (pr as f64 - mean_residual).abs() / cap;
    score += 8.0 * dev * dev * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward leaving space that the next item could use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            // next item fits into post residual: reward, more if snug fit
            let snug = 1.0 - (pr as f64 - nx) / cap;
            score -= 6.0 + 10.0 * snug * snug;
        } else {
            // next item would not fit: penalize large leftover slightly
            score += 4.0 * (1.0 - x) * progress;
        }
    }

    // Mild penalty for proliferation of open bins when a tight fit exists elsewhere
    score += 0.3 * open_bins_count as f64 * x;

    // New-bin candidate handling: an empty bin is only attractive for large items
    // or when residual is small; otherwise penalize opening fresh capacity.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let waste_avoided = 1.0 - item_frac;
        score += 15.0 * waste_avoided * (0.5 + 0.5 * progress)
            - 5.0 * item_frac * item_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fraction classes
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize unusable small residuals harshly via integer division thresholds
    let cls = post_residual / 10; // classes 0..10
    match cls {
        0 => score += 40.0,          // dead space (<10)
        1 => score += 20.0,          // 10-19
        2 => score += 8.0,
        3 => score -= 4.0,           // 30-39: good mid fit
        4 => score -= 10.0,
        5 => score -= 12.0,          // 50-59 sweet spot
        6 => score -= 10.0,
        7 => score -= 4.0,
        8 => score += 2.0,
        9 => score += 8.0,
        _ => score += 6.0,           // nearly full leftover bin (new-bin case)
    }

    // Lookahead: reward residuals that can host the next item exactly-ish
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 5 {
            score -= 15.0; // perfect chain fit
        } else {
            score -= 5.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        score += 6.0; // next item won't fit here; chain breaks
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: make it moderately attractive only when mean residual is tight
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score -= 10.0 * pressure;
        score += 4.0; // slight default bias toward reusing open bins
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 8.0; // big next item: fresh bin is fine
        }
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (frac * 2.0 - 1.0).abs();

    // Prefer bins tighter than the mean (best-fit flavor)
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    // A gap is "dead" if it is smaller than the smallest plausible item (1) — but more
    // meaningfully, if no future item of typical size can use it. Penalize gaps < 20
    // super-linearly since they are likely wasted.
    if post_residual > 0 && post_residual < 20 {
        score += 30.0 * (1.0 - (post_residual as f64 / 20.0)).powf(2.0);
    }

    // Perfect fit reward: zero post residual is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit reward: post_residual small but nonzero and still usable.
    if post_residual >= 20 {
        score -= 5.0;
    }

    // Open bins pressure: penalize placements in already-open bins when too many are open,
    // encouraging consolidation; but reward using an existing bin to avoid opening new ones.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Last-chance bin: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: opening a new bin is only attractive if the item is large
    // relative to capacity or no bin fits well (post_residual here = capacity - item_size).
    if bin_residual == bin_capacity {
        // Penalize opening a new bin unless the item is big; large items pack better alone.
        score += 15.0 - 0.15 * (item_size as f64);
        // If many bins are open and fragmented, a new bin can be worthwhile.
        if mean_residual > 25.0 && open_bins_count > 2 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: if the next item would fit in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit in post residual but could fit elsewhere, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0;
    }

    // Slight preference for bins with residual close to mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / (bin_capacity as f64)).abs() * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness).powi(3);

    // 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_waste = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - chain_waste / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow in this bin: penalize dead space.
        score += 15.0;
    }

    // Compare post_residual against mean residual: prefer bins left closer to average.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer filling nearly-full bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Mild penalty for spreading across many bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that can never fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global pressure: many open bins -> consolidate; few -> allow spreading.
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
    score += 2.0 * pressure;

    // Prefer bins below mean residual (keeps large residuals available).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Time horizon: early stream -> be picky; late stream -> fill anything.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - fit_ratio);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when item is huge
        // or no open bin fits (fitting_bins_count==0 means only this call).
        let base = 60.0;
        let size_discount = (item_size as f64 / bin_capacity as f64) * 45.0;
        score = base - size_discount + post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 20 {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear waste penalty: dead space hurts more as stream progresses.
    let waste_curve = norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score += 40.0 * waste_curve;

    // Reward very tight fits (small post_residual) with a smooth dip.
    score -= 25.0 * (-pr / 12.0).exp() * (1.0 + progress);

    // Lookahead coupling: if next item fits the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (-slack / 20.0).exp();
    } else if next_item_size > 0 {
        // Next item cannot use leftover: mild penalty scaled by leftover size.
        score += 6.0 * norm_pr * (1.0 - progress);
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer opening a new bin only late in the stream
    // when existing residuals are already small; otherwise penalize opening.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 8.0);
        let mean_tight = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score = cap + 50.0 * (1.0 - progress) * (1.0 - mean_tight) - 60.0 * progress * open_pressure * mean_tight;
    }

    // Mild preference for bins tighter than average (smooth coupling).
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap).tanh();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: dead space classes mod capacity fractions
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward (post_residual == 0 is ideal)
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Class bins by unusable-space thresholds
        if post_residual < 10 {
            score -= 120.0; // tiny dead space, near-perfect packing
        } else if post_residual <= 20 {
            score -= 40.0;
        } else if post_residual <= 50 {
            score -= 10.0;
        }
        // Harmonic residue classes of post_residual mod 10: even residues pack better with typical item sizes
        let class = post_residual % 10;
        score -= match class {
            0 => 25.0,
            1 | 9 => 5.0,
            2 | 8 => 12.0,
            3 | 7 => 3.0,
            4 | 6 => 8.0,
            _ => 0.0,
        };
    }

    // Next-item lookahead: reward residuals that can host the next item exactly or closely
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 + 20.0 * (1.0 - slack / cap_f);
        if slack == 0.0 {
            score -= 60.0; // chains perfectly with next item
        }
    } else if next_item_size > 0 {
        // next item cannot fit here; penalize less if residual is small anyway
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate logic: only attractive when open bins are badly fragmented
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - pr) / cap_f; // >0 means open bins are fuller than empty
        // Prefer new bin when mean residual is small (poor fits) or early stream
        score += 15.0 + 30.0 * fragmentation.max(0.0) - 40.0 * (1.0 - progress);
        if mean_residual < 15.0 {
            score -= 35.0; // open bins nearly full -> open fresh bin
        }
        if item_size > 70 && mean_residual < item_size as f64 {
            score -= 25.0; // big item, no good home
        }
    }

    // Mild penalty proportional to how much of the bin the item wastes relative to capacity
    score += (item_size as f64 / cap_f) * 5.0;

    // Small-scale harmonic tiebreak on integer division thresholds
    score -= ((post_residual / 25) as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space penalty: small unusable gaps (below min item size) are the worst.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Mid-range awkward gaps: mildly penalize residuals that few future items can use.
    if post_residual >= 10 && post_residual < 35 {
        score += 0.35 * (35.0 - post_residual as f64);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap == 0.0 {
            score -= 120.0;
        } else if gap < 10.0 {
            score += 8.0 * gap;
        } else {
            score -= 10.0;
        }
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * pressure * (0.5 + progress);

    // New-bin candidate: make empty bin costly unless current bins are quite full.
    if bin_residual == bin_capacity {
        let mean_fill = mean_residual;
        if mean_fill < 30.0 {
            score += 500.0; // open bins are nearly empty; do not open another
        } else {
            score += 40.0 + 0.5 * (100.0 - mean_fill);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fills (post_residual small).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when post_residual can host next_item_size,
    // extra reward for a perfect match; penalize tight-but-not-fitting gaps.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 - slack.min(120.0);
        } else {
            // leftover too small for next item: dead-space penalty
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(60.0);
        }
    }

    // Compare against mean residual: prefer bins that stay near the mean
    // (balanced packing), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let tightness = fitting_bins_count == 0;
        let poor_fits = next_item_size > 0 && (post_residual as i64) < (next_item_size as i64);
        if item_size >= 50 && (tightness || poor_fits) {
            score -= 80.0;
        } else {
            score += 120.0; // prefer existing bins generally
        }
    }

    // Early in the stream, allow slightly more openness to spread items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0 - (post_residual as f64) * 1.5;
    } else {
        // Penalize dead space quadratically; small residuals (<15) are hard to reuse.
        let pr = post_residual as f64;
        score += 0.02 * pr * pr;
        if pr < 15.0 {
            score += 10.0 * (15.0 - pr);
        }
    }

    // Lookahead: if the next item fits the post-residual, this placement chains well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - 0.15 * slack;
        } else {
            // Next item won't fit here; mild penalty proportional to gap.
            score += 0.1 * ((next_item_size - post_residual) as f64);
        }
    } else {
        // Last item: closing bins fully is free, prefer tightest fit.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Many open bins with high mean residual => prefer consolidating into fuller bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * fill_ratio * (1.0 + 0.5 * progress);
    score += 0.02 * open_bins_count as f64;
    score -= 0.05 * mean_residual;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let desperate = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score += 10.0 + desperate - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear (quadratic) tightening
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth progress coupling: late in the stream, dead space is costlier
    let late = progress * progress;
    score += 25.0 * late * norm_pr * cap;

    // Interaction: post_residual vs mean_residual (avoid bins far from the mean)
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev * cap;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits the post-residual smoothly
    if next_item_size > 0 {
        let fits = (post_residual >= next_item_size) as i32 as f64;
        let tight = 1.0 - (next_item_size as f64 / cap);
        score -= 12.0 * fits * (0.5 + tight);
    } else if post_residual == 0 {
        score -= 10.0; // perfect fill at stream end
    }

    // Slight penalty for many open bins relative to progress (encourage consolidation early)
    let open_norm = open_bins_count as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * open_norm * cap * 0.1;

    // New-bin candidate: make empty bin moderately attractive only when it beats bad fits
    if bin_residual == bin_capacity {
        score += 5.0 + 60.0 * (1.0 - item_size as f64 / cap) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on "nice" modular
    // classes (multiples of 10, or small classes that pair with typical items) are favored.
    let pr = post_residual;
    let class = pr % 10;
    let class_bonus = match class {
        0 => 14.0,                       // perfectly harmonic leftover
        1..=5 => 3.0,                    // near-harmonic small dead space
        6..=9 => -2.0,                   // awkward class, slight penalty
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division threshold: post_residual / 10 quotient tiers.
    let tier = pr / 10;
    if tier == 0 {
        score += 6.0;                    // nearly-full bin: excellent, reward strongly
    } else if tier <= 2 {
        score -= 4.0;                    // small leftover likely reusable
    } else if tier <= 4 {
        score -= 1.0;
    } else {
        score += 2.0;                    // large leftover: wasteful unless new bin
    }

    // Coupling with next item: if the next item exactly fits the post residual
    // (harmonic match), strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size < pr && (pr % next_item_size == 0) {
            score -= 6.0;
        } else if next_item_size > pr {
            score += 5.0;                // next item won't fit here anyway
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = (open_bins_count as f64) / (1.0 + mean_residual / cap);
        let base = cap - 8.0;
        score = base - 10.0 * crowd - 6.0 * progress;
        // Harmonic check: opening a fresh bin is fine; slight tilt so it only wins
        // when open bins have bad fits (handled by the subtraction above).
        if item_size % 10 == 0 {
            score -= 1.0;                // round items pack cleanly anywhere
        }
    }

    // Mean-residual coupling: prefer bins deviating below the mean residual
    // (tighter bins get priority), scaled non-linearly.
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Mild saturation penalty for very loose fits.
    let fill = item_size as f64 / cap;
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are the worst outcome.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - 3.0 * post_residual as f64; // unusable sliver penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly reward closing the bin
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0; // moderate dead space
    }

    // Reward tight fits relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * (2.0 + 4.0 * progress);

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 12.0; // next item can't use the leftover
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Give it a mild penalty so good existing fits win,
    // but it stays attractive when open bins would waste lots of space.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Early in stream, new bins are cheap; late, avoid bin proliferation.
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward a perfect follow-up fit.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact match: bin will be perfectly filled next step
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover dead space after the lookahead placement
            score += 0.5 * slack;
            if slack < 10.0 {
                score -= 10.0; // near-match still good
            }
        } else {
            // next item cannot fit here; leftover is likely dead space
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap.min(30.0);
        }
    } else {
        // last item: prefer minimal post_residual
        score += 0.1 * post_residual as f64;
    }

    // Penalize bins deviating from mean residual (fragmentation control)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin unless current bins are genuinely bad fits
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score += pressure + 0.2 * (open_bins_count as f64);
    }

    // Late-stream consolidation: favor tighter fits as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.1 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

