    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else if (post_residual as u32) >= next_item_size / 2 {
            score += 4.0;
        }
        // If next item barely misses the post residual, penalize wasted opportunity.
        let miss = next_item_size as f64 - post_residual as f64;
        if miss > 0.0 && miss <= 8.0 {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // New-bin candidate handling: make empty bin attractive only when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Open new bin if mean residual of open bins is low (bad fits) or many bins already open.
        let bias = 6.0 + 10.0 * (1.0 - fragmentation / bin_capacity as f64) - 8.0 * progress;
        score = bin_capacity as f64 - bias;
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Mild penalty for creating many near-full bins when mean residual is high (imbalance).
    if (post_residual as f64) < mean_residual * 0.25 && open_bins_count > 2 {
        score += 3.0;
    }

    // Prefer packing into bins with residual close to item size (best-fit flavor).
    let closeness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * closeness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
