        1 => score -= 5.0,         // 10..19: usable for small items
        2..=4 => score -= 8.0,     // 20..49: flexible
        5..=7 => score -= 12.0,    // 50..79: very reusable
        _ => score -= 6.0,         // 80..99: large but item was small
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it moderately attractive only when fits are poor
    if bin_residual == bin_capacity {
        score = 55.0 + 0.1 * mean_residual;
        if next_item_size > 0 && next_item_size >= bin_residual {
