    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        score -= 8.0 * (1.0 - diff / cap).max(0.0) * (1.0 - progress);
    }

    // Mild tie-break toward already-open bins, scaled by mean residual deviation.
    let dev = (mean_residual - pr).abs() / cap;
    score += 2.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer bins with small leftover (best-fit core).
    let mut score = post;

    // Harmonic class of post_residual (decade classes): lower classes favored,
    // but the very bottom class (1..10) is dead space -> penalize hard.
    let class = post_residual / 10;
    score += class as f64 * 2.0;
    if post_residual > 0 && post_residual < 10 {
        score += 14.0; // unusable sliver
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit, huge reward
    }

    // Lookahead coupling: reward bins whose post_residual still fits next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 7.0;
            // extra reward if next item lands in the same harmonic class (tight chain)
            if (post_residual / 10) == (post_residual - next_item_size) / 10 {
                score -= 3.0;
            }
        } else {
            score += 4.0; // this bin becomes dead after placement
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 18.0;
    }

    // New-bin candidate: baseline cost of opening a fresh bin.
    if is_new_bin {
        score = post + 10.0;
        // Large items waste less in a fresh bin; small items should reuse open bins.
        if item > 0.6 * cap {
            score -= 8.0;
        }
        if item < 0.3 * cap {
            score += 12.0;
        }
        // If next item also large, opening now may be fine.
        if next_item_size > 60 {
            score -= 5.0;
        }
        // Many open bins with slack: don't open another.
        if mean_residual > item {
            score += 10.0;
        }
    }

    // Mild stream-phase drift: late in stream, consolidate more aggressively.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: small unusable gaps are the enemy.
    // Gaps below the smallest plausible item (1) don't matter; gaps of 1..30
    // are likely dead. Penalize super-linearly as gap shrinks into dead zone.
    let dead_zone: f64 = 30.0;
    let gap = post_residual as f64;
    if gap > 0.0 && gap < dead_zone {
        let deadness = (dead_zone - gap) / dead_zone; // 0..1
        score += 45.0 * deadness * deadness;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Exact-fit lookahead: if the next item exactly fills the post gap, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    }
    // If next item fits in the post gap, mild reward (keeps chain alive).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }
    // If next item would NOT fit in the post gap, the gap is likely terminal dead space.
    if next_item_size > post_residual {
        score += 12.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, opening a new bin is cheaper so treat candidates more equally.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure * (gap / bin_capacity as f64);

    // Mild tie-break: prefer bins whose residual is closest to the item
    // (tightest fit) beyond raw post_residual ordering.
    score += 0.05 * (bin_residual as f64 - item_size as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress factor: early in the stream we can afford to open bins,
    // late in the stream we want to consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead: match next_item_size against post_residual ----
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain: next item exactly fills this bin.
            score -= 60.0 + 40.0 * progress;
        } else if next_item_size < post_residual {
            // Next item still fits; reward closeness to a perfect chain.
            let gap = (post_residual - next_item_size) as f64;
            let closeness = 1.0 - gap / bin_capacity as f64;
            score -= 25.0 * closeness * closeness;
        } else {
            // Next item cannot fit here: dead space after this placement.
            let dead = (next_item_size - post_residual) as f64;
            score += 10.0 + 0.5 * dead;
        }
    }

    // ---- Relative residual coupling with mean_residual ----
    // A bin whose post-residual is far below the mean residual is "tight"
    // and should be preferred for dumping this item (reduces fragmentation).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // ---- Last-chance bonus: only one open bin can fit the item ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: opened only when open bins score worse
        // (i.e., when accepting here would create large dead space).
        score = 55.0 - 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can always chain the next item perfectly.
            score -= 15.0;
        }
    }

    // Penalize creating very small unusable residuals (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: heavily discount small post-residuals.
    let tight_fit = (post_residual as f64 / bin_capacity as f64).powi(4);
    score -= (1.0 - tight_fit) * 20.0;

    // Penalize post-residuals that are small enough to be dead space
    // (unusable for typical items) but large enough to waste capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (chaining placements).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            // next item fits but leaves more waste: mild bonus scaled by fit quality
            let next_waste = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - next_waste / bin_capacity as f64);
        } else {
            // next item cannot follow here: penalize proportionally to how close we were
            let miss = (next_item_size - post_residual) as f64;
            score += 5.0 + 10.0 * (1.0 - miss / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make opening a new bin only attractive when
    // the current item is large and no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened casually.
        score += 25.0;
        // If item is large relative to capacity, a fresh bin wastes less later.
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * large_item;
        // If the item fits poorly everywhere else (few fitting bins), encourage new bin.
        if fitting_bins_count <= 2 {
            score -= 15.0;
        }
        // If mean residual across open bins is small (bins are full), new bin is natural.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 10.0;
        // Early in the stream, allow more bins; late in the stream, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Prefer bins with larger residuals among open bins (use fullest bins first
        // is equivalent to minimizing post_residual, already captured; add slight
        // preference for bins below mean residual to balance load).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
        // Crowding: many open bins -> prefer existing bins more strongly.
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear coupling: residual squared scaled by progress
    score += (pr * pr / cap) * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (1.0 - pr / cap) * (1.0 - pr / cap) * (10.0 + 20.0 * progress);

    // Lookahead: bonus if next item fits into the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 + 6.0 * (1.0 - pr / cap) * progress;
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize bins far from mean residual (fragmentation pressure)
    score += 0.05 * ((pr - mean_residual) * (pr - mean_residual)) / cap;

    // Mild penalty for many open bins to encourage consolidation early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lands in a
    // "reusable" class (large enough for typical small items) are favored.
    let class = post_residual / 10; // integer division bucket 0..=10
    match class {
        0 => score -= 60.0,                 // near-perfect fit, minimal dead space
        1 => score -= 25.0,                 // very tight, likely unusable but tiny waste
        2 | 3 => score += 5.0,              // awkward mid-small gap: dead-space risk
        4 | 5 => score += 12.0,             // half-capacity gap: mediocre
        6 | 7 => score -= 8.0,              // large gap: still reusable for many sizes
        _ => score -= 4.0,                  // nearly empty bin
    }

    // Lookahead coupling: reward if the post residual exactly accommodates
    // the next item (harmonic chain), penalize near-miss dead space.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let deficit = (next_item_size - post_residual) as f64;
            score += 10.0 * (deficit / 100.0).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): only attractive when current fit is poor
    // or the item is large and no open bin is a good harmonic match.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let tightness = post_residual as f64 / bin_capacity as f64;
        // Empty bin leaves residual = C - item_size; good if item is large.
        score -= 20.0 * tightness;                    // large items like fresh bins
        score += 55.0 * (mean_residual / bin_capacity as f64); // if open bins have room, prefer them
        if fitting_bins_count > 0 {
            score += 25.0;                            // discourage skipping usable bins
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;                            // fresh bin can also host next item
        }
    }

    // Late-stream consolidation: fewer open bins preferred as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (open_bins_count as f64).sqrt();

    // Mild pull toward bins below mean residual (spread packing evenly).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that can no longer hold the smallest
    // plausible item (1..=100 range, so any gap >= 1 is usable, but tiny gaps
    // relative to typical arrivals are waste). Penalize unusable gaps hard.
    if post_residual > 0 {
        // Dead space = residual too small to fit the next item (or typical item).
        let threshold = if next_item_size > 0 { next_item_size } else { 10 };
        if (post_residual as f64) < threshold as f64 {
            // Unusable gap: heavy penalty proportional to wasted capacity.
            score += 60.0 + (post_residual as f64);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits generally: smaller post_residual already favored by base term,
    // add a quadratic sharpening to emphasize best-fit behavior.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained placement).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual can't host the next item: mild penalty unless it's dead space anyway.
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin, modulated by pressure.
        score += 30.0 + 5.0 * (open_bins_count as f64);
        // If no existing bin can fit (fitting_bins_count counts only open bins here),
        // the new bin must win; relax its penalty when item is large relative to capacity.
        if item_size as f64 > 0.5 * bin_capacity as f64 {
            score -= 45.0;
        }
        // Late in the stream, keep bins tighter.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild diversity pressure: prefer bins whose residual is below the mean
    // (consolidate fuller bins, leave large residuals open).
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 == next_item_size as i64 {
            score -= 300.0; // next item exactly fills this bin
        } else if next_item_size <= post_residual {
            score -= 150.0 - diff; // next item fits, closer match is better
        } else {
            score += 50.0 + diff * 0.5; // next item won't fit here; penalize
        }
    }

    // Penalize small dead space that likely becomes unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0 + (post_residual as f64).min(60.0);
    }

    // New-bin candidate handling: prefer keeping items in existing bins when the
    // fit is decent; make new bins unattractive unless all open fits are poor.
    if bin_residual == bin_capacity {
        // Empty bin: score = post_residual = capacity - item_size naturally.
        // Add a mild opening penalty that shrinks late in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
    } else {
        // Reward using bins with above-average residual (consume roomy bins first).
        if (bin_residual as f64) > mean_residual {
            score -= 15.0;
        } else {
            score += 10.0;
        }
        // Slight preference for tighter bins when many alternatives exist.
        if fitting_bins_count > 3 {
            score += post_residual as f64 * 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal waste (post_residual), with a superlinear penalty
    // on medium dead space that is unlikely to be filled later.
    let dead = post_residual as f64;
    if dead > 0.0 {
        score += 0.35 * (dead / 10.0).powf(1.6);
    }

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
        // Stronger when the stream is far along (fewer future items to fix things).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * progress;
    }

    // Lookahead: reward if the next item can also fit in the resulting residual
    // (chaining placements), penalize if next item is nearly the residual
    // but just misses it (creating a stranded gap).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let leftover_after_next = post_residual as i64 - next_item_size as i64;
            if leftover_after_next <= 5 {
                score -= 20.0; // near-perfect two-item chain
            } else {
                score -= 8.0;
            }
        } else {
            let miss = (next_item_size as f64 - post_residual as f64).min(30.0);
            score += 0.6 * miss; // residual likely stranded for the next item
        }
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Its raw post_residual is already large; add a mild exploration bonus early
    // in the stream (diversification) and a penalty late (consolidation).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        score += 40.0 * progress;
        // Opening a new bin is more attractive when few bins are open relative
        // to the mean residual being high (existing bins are fragmented).
        if mean_residual > 40.0 && open_bins_count > 1 {
            score -= 10.0;
        }
    } else {
        // Prefer bins whose residual deviates favorably from the mean:
        // filling below-average-residual bins concentrates waste.
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    // Mild global pressure: many open bins -> favor packing into existing ones.
    score += 0.8 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Reward tight fits: non-linear coupling of post_residual with progress.
    // Tight fits (small post_residual) get progressively more valuable as stream advances.
    let tightness = 1.0 - (pr / cap);
    score -= tightness.powf(2.0) * (30.0 + 40.0 * progress);

    // Penalize leaving awkward mid-range residuals (dead space that fits few items).
    // Residuals around 10-40 are awkward; smooth quadratic penalty centered there.
    let awkward_center = 25.0;
    let awkward = ((pr - awkward_center) / cap).powf(2.0);
    score += awkward * 25.0 * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else if fitting_bins_count > 1 {
        // Mild penalty when many bins compete: prefer spreading load carefully.
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Lookahead coupling: reward if next item fits the post_residual well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            // Next item fits exactly into leftover: reward proportionally to snugness.
            let snug = 1.0 - ((pr - nxt) / cap).abs();
            score -= snug * 20.0;
        } else {
            // Next item would not fit here: slight penalty proportional to overflow.
            score += ((nxt - pr) / cap) * 15.0;
        }
    }

    // Encourage consolidation when many bins are open: prefer fuller bins.
    let fullness = 1.0 - (bin_residual as f64 / cap);
    score -= fullness * fullness * (5.0 + 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)));

    // Mean-residual coupling: if this bin's residual is far below mean (it's an outlier
    // small-capacity bin), favor using it up to close it out.
    let bin_res = bin_residual as f64;
    if mean_residual > 0.0 {
        let outlier = ((bin_res - mean_residual) / cap).abs();
        if bin_res < mean_residual {
            score -= outlier * 12.0;
        } else {
            score += outlier * 6.0;
        }
    }

    // New-bin candidate handling: an empty bin has pr == cap, so tightness = 0 and
    // awkward penalty = ((100-25)/100)^2*25 ≈ 14. Add a mild opening cost that grows
    // with progress, so late in the stream we prefer filling existing bins.
    if bin_residual == bin_capacity {
        score += 8.0 + 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Harmonic classes on post_residual: dead space in low residue classes is bad
    let pr = post_residual;
    if pr > 0 {
        let cls = pr % 10; // residue class mod 10
        // small residues (1..=5) are nearly dead; penalize via class weight
        let class_weight: f64 = match cls {
            0 => -8.0,          // perfectly divisible residual is reusable
            1..=5 => 6.0,       // tiny slivers are dead space
            6..=9 => 2.0,       // moderate slivers
            _ => 0.0,
        };
        score += class_weight * (pr as f64 / 10.0).min(3.0);

        // integer division thresholds: post_residual in [50,100] means half-empty bin kept
        if pr >= 50 {
            score -= 4.0; // leaving a half-capacity residual is fine for future items
        } else if pr <= 10 && pr > 0 {
            score += 10.0; // near-dead bin
        }
    } else {
        score -= 12.0; // perfect closure
    }

    // Lookahead coupling: does next_item_size fit in post_residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // harmonic compatibility: gcd-like check via modulo
            let compat = (post_residual % next_item_size.max(1)) as f64;
            score -= 8.0 - compat * 0.3; // exact divisibility is best
        } else {
            score += 5.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: keep new bins slightly unattractive unless current bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // open new bin when existing residuals are small or item is large
        score += 6.0 + 20.0 * (1.0 - fragmentation) - 10.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 5.0; // large items like fresh bins
        }
        if post_residual > 0 && post_residual < 20 {
            score += 8.0; // would create sliver in fresh bin
        }
    }

    // Slight tie-break toward bins below mean residual (consolidating waste)
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 2.0;
    }

    // Stream-phase modulation: late in stream, prefer closing bins tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (post_residual == 0) as i32 as f64 * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        let unusable = post_residual < 10 || (next_item_size > 0 && (post_residual as u32) < next_item_size);
        if unusable {
            score += 25.0 + 0.5 * post_residual as f64;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward when this bin is the last chance to fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when open-bin pressure is low.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * (open_bins_count as f64).ln().max(0.0);
        // But new bin is attractive if the item would leave a bad gap elsewhere
        if post_residual >= 20 && post_residual <= 50 {
            score -= 20.0;
        }
    }

    // Prefer bins with residual close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;

    // Favor bins whose residual is below the mean (consolidate emptier space).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Lookahead: if next item fits the post residual, reward.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0 + 0.1 * (post_residual as f64 - next_item_size as f64);
    }

    // Open-bin pressure: mild penalty proportional to open bins when wasting space.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post residual is good, but reward disproportionately).
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * fit_quality * fit_quality;

    // Aggressive 2-step lookahead: strongly reward when the next item exactly
    // consumes the post residual, or fits tightly within it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            // Perfect chain: this placement enables a perfect next fit.
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use leftover space: penalize proportionally to waste.
            let waste = (next_item_size - post_residual as u32) as f64;
            score += 8.0 * (waste / bin_capacity as f64);
        }
        // Bonus when post residual sits in the "usable window" around next item size.
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 10.0 {
                score -= 6.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins
    // get filled), penalize dumping into already-loose bins.
    let bin_res = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = (bin_res - mean_residual) / mean_residual;
        score += 5.0 * rel;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a new bin when good open alternatives exist, unless nothing fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: must open new bin
        } else {
            // Only open a new bin if the item is huge and would leave a tiny
            // unusable sliver in every existing bin.
            let sliver = post_residual as f64;
            let bad_fit_everywhere = sliver < 10.0 && item_size > bin_capacity / 2;
            if bad_fit_everywhere {
                score -= 15.0;
            } else {
                score += 40.0 + 0.5 * open_bins_count as f64;
            }
        }
    }

    // Late-stream consolidation: as the stream ends, favor filling existing bins
    // tightly rather than spreading.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 10.0 * progress * fit_quality;
    }

    // Small penalty for creating dead space below the minimum item size.
    if post_residual > 0 && post_residual < 1 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead waste).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + (next_item_size - post_residual) as f64 * 0.5;
        } else {
            // Reward bins that can still host the upcoming item.
            score -= 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits very poorly
    // everywhere else (i.e., item is large relative to residuals).
    if bin_residual == bin_capacity {
        let spread = mean_residual - (bin_capacity as f64 - item_size as f64);
        // Open a new bin when existing residuals are small (poor fits) or late in stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_bias = 15.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
        score += 40.0 + open_bias - 0.3 * mean_residual.max(0.0);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can host next item too
        }
    }

    // Mild preference for bins below mean residual (balance load, keep big holes alive).
    let dev = mean_residual - bin_residual as f64;
    score += 0.08 * dev;

    // Penalize leaving exactly awkward slivers (unusable small remainders).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals; late, penalize them more strongly.
    let progress_coupling = norm_pr * (1.0 + 3.0 * progress * progress);
    score += 40.0 * progress_coupling * norm_pr;

    // Superlinear penalty for dead space that is too small to be useful later
    // (smoothly applied, no piecewise cutoffs).
    let deadness = 1.0 - (norm_pr * 4.0).min(1.0);
    score += 25.0 * deadness * deadness * norm_pr;

    // Reward bins whose residual matches the item well (quadratic fit term).
    let fit_quality = (bin_residual as f64 - item_size as f64) / cap;
    score -= 15.0 * (1.0 - fit_quality * fit_quality);

    // Lookahead: if next item could use the post-residual, reward this bin.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap >= 0.0 {
            score -= 10.0 * (1.0 - (gap / cap).min(1.0));
        } else {
            score += 8.0 * (-gap / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 + progress);
    }

    // Mildly discourage proliferating open bins when mean residual is high.
    score += (open_bins_count as f64).ln() * mean_residual * 0.02 * (1.0 - progress);

    // New-bin candidate: make empty bins attractive only when residuals are bad.
    if bin_residual == bin_capacity {
        score = pr + 20.0 + 60.0 * (1.0 - norm_pr.min(mean_residual / cap.max(1.0)));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits are golden
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Modulo-10 class: residuals that are multiples of 10 pair well with
    // common item sizes drawn from decade grids
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Next-item coupling: reward residuals that can host the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + (next_item_size as f64) * 0.1;
    }
    // Penalize residuals that can host the next item only awkwardly
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * 0.5 + mean_residual * 0.05;
        score += 120.0 - crowded.min(100.0);
        // Late in the stream, opening fresh bins is more acceptable
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 20.0;
    }

    // Mild pressure toward tighter bins as the stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_residual as f64 / bin_capacity as f64) * 10.0 * progress;

    // Mean-residual alignment: prefer bins near the mean (keeps residual spread compact)
    score += ((post_residual as f64 - mean_residual).abs()) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let threshold = 10u32; // smallest item size
    if post_residual > 0 && post_residual < threshold {
        score += 60.0 + (threshold - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fits (post_residual very small but nonzero handled above;
    // exact fill is ideal).
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Fractional fill tightness: tighter fit => lower score.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 15.0 * tightness * tightness;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else if gap < threshold {
            score += 10.0; // next item would leave dead space anyway; mild penalty
        } else {
            score -= 5.0;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins => discourage spreading, favor filling
    // existing bins (new-bin candidate has bin_residual == bin_capacity, so it
    // gets penalized here when open_bins_count is high).
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 2.5;
    } else {
        score += open_bins_count as f64 * 0.3;
    }

    // Mean-residual coupling: bins far below mean residual are "ragged";
    // prefer bins whose residual is close to the mean to keep bin states uniform.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    // Prefer bins that are already fairly full (small residual) when tie-breaking.
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chain placement possible: strong reward proportional to how snugly next item fits
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 40.0 + 0.5 * chain_waste;
        } else {
            // next item won't fit here; penalize leaving awkward residual slightly
            score += 5.0;
        }
        // If post_residual is too small for anything useful (below min item size), penalize dead space
        if post_residual < 1 {
            score += 100.0;
        }
        // Extra bonus if next item fills post_residual exactly or nearly
        if next_item_size == post_residual {
            score -= 60.0;
        }
    } else {
        // last item: just minimize waste
        score = post_residual as f64 * 2.0;
    }

    // Relative to mean residual: prefer bins with residual close to item needs
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless post_residual is huge relative to item
    if bin_residual == bin_capacity {
        // opening a new bin is fine if current item is large and lookahead is large too
        score = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
        // discourage opening new bins when many bins are open and stream is early
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that nothing can use (items >= 1, so post_residual 0 is perfect).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 8.0; // awkward gap
    } else if post_residual == 0 {
        score -= 40.0; // perfect closure
    }

    // Lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; slight penalty for wasting capacity
            score += 5.0;
        }
    } else {
        // Last item: prefer closing bins out completely.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as the stream matures or many bins are open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_cost = 60.0 - 15.0 * progress - (open_bins_count as f64).min(20.0);
        // If current bin leaves lots of dead space, new bin becomes attractive.
        score = open_cost + post_residual as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // new bin keeps clean space for next item
        }
    }

    // Global pressure: when mean residual is low, conserve remaining space carefully.
    score += 0.15 * mean_residual;

    // Mild preference to fill bins with lower residual first (compactness).
    score += 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * (1.0 + 0.8 * progress + 1.5 * progress * progress);
    let mut score = poly;

    // Penalize large waste quadratically as stream matures
    score += 0.6 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post_residual)
    score -= 2.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Lookahead: favor bins whose post_residual fits the next item
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 0.8 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 0.5 * (1.0 - norm_post);
    }

    // Mild preference for consolidating into fewer bins
    score += 0.02 * open_bins_count as f64 * norm_post;

    // New-bin candidate: penalize slightly unless current bin would leave bad residue
    if bin_residual == bin_capacity {
        score += 1.0 - 2.0 * (1.0 - norm_post);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but dead space below the minimum item size (assumed ~10)
    // is pure waste — penalize it quadratically.
    if post_residual < 10 {
        score -= 30.0 + (10 - post_residual) as f64 * 4.0;
    } else {
        // Waste proportional to unusability: post_residual that cannot host the lookahead item
        let progress = step_index as f64 / total_items.max(1) as f64;
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * (0.5 + 0.5 * progress);
        }
    }

    // Harmonic class logic: partition post_residual into capacity-fraction classes.
    // Residuals in [1/3, 1/2] of capacity are the most reusable "sweet spot";
    // tiny residuals (< 1/4) are dead space; large residuals are fine but less urgent.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    if pr >= c * 0.33 && pr <= c * 0.5 {
        score -= 8.0; // sweet-spot class
    } else if pr < c * 0.25 {
        score += 6.0; // near-dead class
    } else if pr > c * 0.75 {
        score += 2.0; // still mostly empty, low urgency
    }

    // Integer-division threshold: post_residual / 10 class
    let class = post_residual / 10;
    match class {
        0 => score -= 5.0,   // near-perfect fill
        1 | 2 => score -= 1.0,
        3 | 4 => score += 0.5,
        _ => {}
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current item is large relative to
    // capacity or no open bin fits well. Penalize default new-bin choice mildly.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > c * 0.7;
        if large_item || fitting_bins_count == 0 {
            score -= 3.0;
        } else {
            score += 10.0 + open_bins_count as f64 * 0.5;
        }
    }

    // Mild tie-break toward consolidating residuals: prefer bins with below-mean residual
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the minimum item size (1) are pure waste; residuals below a "usable
    // threshold" are heavily penalized as unusable gaps.
    let min_item = 1u32;
    if post_residual < min_item {
        // exact fit is perfect: reward it strongly
        score -= 60.0;
    } else if post_residual <= 10 {
        // small dead space that likely can never be filled
        score += 25.0;
    } else if post_residual <= 20 {
        score += 10.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // this bin can also host the next item: reward proportional fit
            let slack = post_residual - next_item_size;
            score -= 8.0 + (slack as f64).min(30.0) * 0.2;
        } else {
            // next item won't fit here: mild penalty scaled by how close we are
            let miss = next_item_size - post_residual;
            score += (miss as f64).min(40.0) * 0.3;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into
    // existing bins; a fresh empty bin (bin_residual == bin_capacity) is
    // penalized proportionally to how many bins are already open.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 3.0;
        // Opening a new bin is acceptable only when the current item is large
        // and no good fit exists; soften for big items.
        if item_size > 60 {
            score -= 20.0;
        }
    } else {
        // slight reward for using the fullest bins first (best-fit flavor)
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Mean-residual coupling: when mean residual across open bins is low,
    // bins are nearly full overall; encourage tightening placement further.
    score -= mean_residual * 0.03;

    // Stream progression: late in the stream, dead space matters more since
    // fewer opportunities remain to compensate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // Perfect lookahead fit: strong reward proportional to tightness.
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            // Extra bonus if next item exactly fills the bin afterwards.
            if gap < 1.0 {
                score -= 20.0;
            }
        } else {
            // Next item cannot use the residual: penalize dead space more harshly.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: simply prefer tightest fit (already via post_residual).
        score -= 5.0;
    }

    // Compare post_residual to mean residual: leaving much more than average
    // residual suggests this bin is a poor absorber of space.
    score += 0.15 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a brand-new bin when decent fits exist.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Late in the stream, opening new bins is even more wasteful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // But if next item is huge and this bin is empty, an empty bin is attractive.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 && next_item_size > item_size {
            score -= 30.0;
        }
    }

    // Mild penalty for very small residual waste (fragmentation shaping).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: penalize large post_residual with a superlinear term.
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powi(3) * bin_capacity as f64;

    // Reward using bins that are already fragmented (residual much below capacity).
    let frag = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 12.0 * frag * frag;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 8.0 + 0.15 * next_item_size as f64;
        } else {
            // Dead space if next item can't follow into this bin.
            score += 3.0 + 0.10 * (next_item_size as f64 - pr).min(50.0);
        }
    }

    // Global state: when many bins are open and mean residual is high, prefer
    // consolidating into existing bins over opening new ones.
    let mean_gap = (mean_residual - bin_residual as f64).abs();
    score += 0.05 * mean_gap;

    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, increasingly penalized later,
        // and penalized more when plenty of open bins exist.
        score += 15.0 + 45.0 * progress + 0.6 * open_bins_count as f64;
        // But if item is large relative to mean residual, new bin may be fine.
        score -= 0.08 * item_size as f64 * (1.0 - progress);
    }

    // Slight preference for filling nearly-full bins as stream progresses.
    score -= 10.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: post residual, smoothly warped by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * prn);

    // Non-linear polynomial coupling of post_residual with progress
    score += 12.0 * progress * prn * prn * (1.0 - prn);

    // Penalize large dead space late in the stream (cubic coupling)
    score += 20.0 * progress * progress * prn * prn * prn * cap;

    // Reward tight fits: low post residual gets a bonus
    score -= 15.0 * (1.0 - prn) * (1.0 - prn);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (1.0 - progress) * (1.0 - prn / cap.max(nxt));
        } else {
            score += 5.0 * prn * (nxt / cap);
        }
    }

    // Mild preference for consolidating into fewer bins when mean residual is high
    if bin_residual != bin_capacity {
        score -= 0.05 * mean_residual * (1.0 - progress);
        score += 0.02 * open_bins_count as f64;
    } else {
        // New-bin candidate: penalize mildly unless residual of open bins is poor
        score += 6.0 + 10.0 * progress - 0.03 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 measure "dead space quality".
    let pr = post_residual as i64;
    let class = pr % 10;

    // Penalize awkward small residues (dead space that likely never fits future items).
    if pr > 0 {
        match class {
            0 => score -= 18.0,           // perfectly divisible -> very reusable
            5 => score -= 9.0,            // half-class, moderately reusable
            2 | 4 | 6 | 8 => score -= 4.0, // even residues, mild bonus
            _ => score += 6.0,            // odd awkward residues -> penalty
        }
    }

    // Perfect fit is king.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains into this bin: strong reward, scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.15 * slack;
            // harmonic bonus if post_residual % next_item_size == 0 (exact chain)
            if next_item_size != 0 && post_residual % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this bin: penalize proportional to wasted opportunity
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 4.0 + 0.5 * gap; // near miss -> mild penalty
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: keep it available but only prefer it when
    // current fit is very poor (large post_residual) or item is tiny.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base new-bin cost, decaying slightly over the stream (keeps bins open longer early).
        let mut new_bin_score = 35.0 - 10.0 * progress;
        // If the item is small, opening fresh is cheap-ish; if huge, avoid fragmentation.
        new_bin_score += (item_size as f64) * 0.1;
        // If this bin would leave a horrible residue, new bin becomes attractive.
        if pr > 0 && pr < 10 && class != 0 && class != 5 {
            new_bin_score -= 20.0;
        }
        score = score.min(new_bin_score);
        // ensure empty-bin call competes fairly: use new_bin_score directly when better
        if new_bin_score < score {
            score = new_bin_score;
        }
        score = new_bin_score;
    }

    // Spread-aware tiebreak: prefer bins whose residual deviates favorably from mean.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Mild pressure to consolidate when many bins are open.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1..100 unknown, but small gaps < 20 are risky)
    // are heavily penalized; perfect or near-perfect fits rewarded.
    if post_residual == 0 {
        score -= 500.0; // perfect fill
    } else if post_residual < 10 {
        score -= 120.0; // nearly dead space but small
    } else if post_residual < 20 {
        score += 150.0; // classic dead zone: too small for most items
    } else if post_residual < 35 {
        score += 40.0; // moderate dead-space risk
    }

    // Reward tight fits relative to item size (waste ratio).
    let waste_ratio = post_residual as f64 / (bin_residual as f64 + 1.0);
    score -= 200.0 * (1.0 - waste_ratio);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when open bins would leave big
    // dead space or are crowded; otherwise penalize spreading bins.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / 20.0;
        score += 80.0 - 60.0 * pressure;
        // If next item is large and current item would leave a bad gap,
        // opening a fresh bin becomes more attractive.
        if next_item_size > 0 && post_residual < next_item_size as u32 {
            score -= 30.0;
        }
    }

    // Open-bin count pressure: discourage proliferating bins early,
    // encourage consolidation late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64) * (0.5 + 2.0 * progress);

    // Prefer bins whose residual deviates favorably from mean residual
    // (place into below-average-residual bins to consolidate fullness).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // Lookahead: if the resulting residual exactly fits the next item,
    // this is a chained perfect fit — reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0; // next item can't use this bin anyway
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score -= 30.0 / (1.0 + diff as f64);
        // Perfect fit for next item is heavily rewarded
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // If next item fits exactly with nothing left, near-perfect chain
        if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 10.0;
    }

    // Penalize dead space relative to mean residual of open bins
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.4;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Small bonus for using open bins vs opening new (new bin has residual == capacity)
    if bin_residual < bin_capacity {
        score -= 3.0;
    } else {
        // New-bin candidate: penalize slightly unless it's a great fit
        score += 5.0;
        if item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Progress-based tightening: later in stream, be greedier about tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post-residual relative to capacity is better.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 4.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 12.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Penalize leaving dead space that no future item (min size 1) could use poorly.
    if post_residual > 0 && post_residual < item_size {
        score += 2.0; // awkward sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0;
            // extra reward for near-exact chain fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 2.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 1.5; // next item won't fit here; slight penalty
        }
    }

    // New-bin candidate logic: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 10.0;
        // If many bins fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 6.0 * (fitting_bins_count as f64).ln();
        }
        // Early in stream, new bins are cheap (bins will be needed anyway).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
        // If mean residual is large, existing bins are wasteful anyway -> new bin ok.
        score -= 0.03 * mean_residual;
        // If lookahead item is huge and current item is small, better to combine later.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 4.0;
        }
    }

    // Crowd penalty: too many open bins with large residuals -> consolidate.
    if open_bins_count > 4 {
        let spread = (bin_residual as f64 - mean_residual).abs();
        score += 0.02 * spread * (open_bins_count as f64).ln();
    }

    // Time-horizon modulation: late in the stream, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.25 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x);
    score -= 24.0 * poly * (0.4 + progress);

    // Reward tight fits more as stream progresses (dead-space aversion grows)
    score -= (1.0 - x) * (1.0 - x) * 8.0 * progress;

    // Penalize residual that cannot fit the lookahead item (smooth soft penalty)
    if nxt > 0.0 {
        let gap = (nxt - pr).max(0.0) / cap;
        score += 6.0 * gap * gap * (0.5 + 0.5 * progress);
        // Bonus if residual still accommodates next item
        let fits_next = (pr - nxt).max(0.0) / cap;
        score -= 4.0 * fits_next * (1.0 - progress);
    }

    // Last-chance bonus: few fitting bins => favor using this bin
    if fitting_bins_count <= 1 {
        score -= 5.0 * (1.0 - x);
    }

    // Slight penalty for spreading across many open bins late in the stream
    score += (open_bins_count as f64).ln().max(0.0) * progress * 0.5;

    // Pull toward mean residual to balance bin loads (smooth coupling)
    score += ((mean_residual - pr) / cap).abs() * 2.0 * progress;

    // Penalize very small dead space (unusable slivers) via smooth term
    score += 10.0 * (-x * 8.0).exp() * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover is "usable"
    // (divisible-friendly chunks) get rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: residuals that are awkwardly small are worse.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic class: post_residual divisible by common item sizes (10,20,25,50)
    let harmonics: [u32; 6] = [10, 20, 25, 40, 50, 100];
    for h in harmonics {
        if post_residual >= h && post_residual % h == 0 {
            score -= 6.0 + (h as f64) * 0.1;
            break;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item cannot follow here; penalize mildly
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = 1.0 - post / cap;
    score -= fill_ratio * 10.0 * (open_bins_count as f64).ln().max(1.0);

    // New-bin candidate: only attractive when current bin would leave a
    // large awkward residual relative to mean residual of open bins.
    if bin_residual == bin_capacity {
        if post_residual > 40 && mean_residual > post {
            score -= 8.0;
        } else if post_residual <= 40 {
            score += 15.0;
        }
    }

    // Stream progression: late in stream, tighten up (avoid waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to hold the
    // smallest plausible item (>=1, but realistically items arrive >= 10
    // in classic streams; treat gaps < 10 as near-wasted) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        // Small but potentially usable gaps: moderate penalty scaled by gap size.
        score += (20.0 - post_residual as f64) * 1.5;
    } else {
        // Larger gaps are progressively less wasteful.
        score -= (post_residual as f64) * 0.1;
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance pressure: if this is the ONLY bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than opening new ones; the new-bin candidate (residual == capacity)
    // gets penalized proportionally to how many bins are already open.
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64) * 2.0;
    }

    // Coupling with mean residual: if this bin's post-fit residual is far below
    // the mean residual, it is a tight, efficient fit -> reward it.
    let tightness = mean_residual - post_residual as f64;
    if tightness > 0.0 {
        score -= tightness * 0.3;
    } else {
        score += (-tightness) * 0.15;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot fit here; slight penalty for leaving a gap that
        // blocks the known successor.
        score += 3.0;
    }

    // Stream progression: later in the stream, be more conservative about
    // opening new bins (sunk cost of open bins matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 2 {
        score -= 300.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 500.0;
        } else if diff <= 5 {
            score -= 150.0 / diff as f64;
        } else {
            score += diff as f64 * 0.5;
        }
        // Penalize leaving residual too small for the next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 80.0;
        }
    } else {
        // Last item: prefer tightest fit
        score += post_residual as f64 * 2.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 1.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 250.0;
        // But allow new bin if it could serve the next item perfectly
        if next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64) == post_residual as i64 && post_residual == 0 {
            score -= 400.0;
        }
    }

    // Early stream: be slightly conservative, keep bins balanced
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * post_residual as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize very small dead space that is hard to reuse later (< 12).
    if post_residual > 0 && post_residual < 12 {
        score += 18.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item could fit into the post residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        }
    }

    // Time horizon: early in stream, prefer spreading across bins (favor new bins
    // less, keep flexibility); late in stream, consolidate tightly.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= 15.0 * progress * tightness;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> discourage
    // opening new bins / encourage filling existing ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with open bins and mean residual.
        score += 20.0 + 3.0 * open_bins_count as f64 + 0.35 * mean_residual;
        // But late in stream, allow opening if item is large and won't fit well elsewhere.
        if item_size > 60 && progress > 0.7 {
            score -= 25.0;
        }
    } else {
        // Reward using bins whose residual deviates above mean (balance cleanup).
        let dev = bin_residual as f64 - mean_residual;
        score -= 0.10 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: waste after placement, damped non-linearly
    let mut score = pr * (1.0 + 0.35 * pr_norm * pr_norm);

    // Smooth polynomial coupling: tight fits are rewarded more as stream progresses
    let tight = 1.0 - pr_norm;
    score -= 18.0 * tight * tight * (0.4 + 0.6 * progress);

    // Reward filling a bin nearly exactly, scaled by item size
    score -= 6.0 * fit_ratio * fit_ratio * (1.0 - pr_norm);

    // Penalty if post residual is small but nonzero (dead space), smooth bump
    let dead = (1.0 - pr_norm) * pr_norm;
    score += 8.0 * dead * (1.0 - fit_ratio);

    // Last-chance bin: strong reward to use it rather than open new
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Many fitting bins: prefer bins with residual closest to item (best fit) via smooth term
    if fitting_bins_count > 1 {
        score += 3.0 * (pr_norm - mean_residual / cap).abs();
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let nxt = next_item_size as f64 / cap;
        score -= 10.0 * nxt * (1.0 - pr_norm);
    }

    // Mild penalty for opening a new bin early in the stream
    if bin_residual == bin_capacity {
        score += 4.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "usable"
    // residue classes (multiples of small denominators) are more valuable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward leaving residuals that are highly reusable (divisible by 10/20/25/50).
    let class_bonus: f64 = if post_residual == 0 {
        -60.0 // perfect fit, best possible outcome
    } else if post_residual % 50 == 0 {
        -35.0
    } else if post_residual % 25 == 0 {
        -25.0
    } else if post_residual % 20 == 0 {
        -20.0
    } else if post_residual % 10 == 0 {
        -12.0
    } else if post_residual % 5 == 0 {
        -6.0
    } else {
        8.0 // awkward dead space
    };
    score += class_bonus;

    // Integer-division threshold classes on post_residual size.
    let pr_class = post_residual / 10; // 0..10 coarse bucket
    score += match pr_class {
        0 => 0.0,          // tiny leftover, nearly full bin
        1 => -3.0,         // 10-19 leftover: good compact fill
        2 => -2.0,
        3 => 0.0,
        4 => 2.0,
        5 => 4.0,
        6 => 6.0,
        7 => 8.0,
        8 => 10.0,
        9 => 12.0,
        _ => 14.0,
    };

    // Lookahead coupling: harmonic class of next_item_size vs post_residual.
    if next_item_size > 0 {
        let fits_next = post_residual >= next_item_size;
        if fits_next {
            // Reward if next item would fit exactly or leave another good class.
            let next_post = post_residual - next_item_size;
            let chain_bonus: f64 = if next_post == 0 {
                -40.0
            } else if next_post % 10 == 0 {
                -18.0
            } else if next_post % 5 == 0 {
                -9.0
            } else if next_post < 10 {
                -4.0
            } else {
                2.0
            };
            score += chain_bonus;
        } else {
            // Next item cannot chain into this bin; penalize proportionally
            // to how far off modulo-10 alignment is.
            let misalign = (post_residual % 10) as f64;
            score += 4.0 + misalign * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // is large and no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        let tightness = (post_residual as f64) / cap; // 1 - item/cap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0; // default penalty for opening a new bin
        score -= tightness * 55.0; // large items justify new bins
        // Prefer new bins early when few bins are open; late stream, reuse.
        score -= (1.0 - progress) * 10.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0; // fresh bin can absorb the next item too
        }
    }

    // Mild diversity pressure: when mean residual is high, prefer filling
    // below-average-residual bins tighter (avoid fragmenting many half-bins).
    let rel = (bin_residual as f64) - mean_residual;
    score += rel * 0.15;

    // Small nudge toward bins whose residual mod capacity fraction is coarse.
    let frac = (bin_residual as f64) / cap;
    score += (frac * 4.0).floor() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Zero residual is a perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to the bin (waste ratio penalty).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 25.0;

    // Open-bins pressure: mildly discourage adding load to bins when many
    // bins are already open, to consolidate filling.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement (chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap < 10 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual cannot host the next item: penalize creating a dead gap.
        score += 8.0;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it
    // attractive only when current bin would leave a large useless residual
    // or the fit is poor.
    if bin_residual == bin_capacity {
        // Baseline attractiveness for a fresh bin, modulated by how bad the
        // best alternative would be (approximated via mean residual).
        score -= 5.0;
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
        // Late in the stream, prefer using existing open bins more.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight non-linearity.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64) * 0.5;

    // Aggressive 2-step lookahead: reward when the next item exactly fills the
    // post-residual (perfect chain), penalize when next item cannot fit here.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            let gap = post - nxt;
            // Perfect chaining: next item fills the leftover exactly.
            score -= (1.0 - gap / bin_capacity as f64) * 8.0;
        } else {
            // Next item would need another bin: penalize leaving big unusable gaps.
            score += (nxt - post) / bin_capacity as f64 * 6.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious
    // tight fits; using them for a loose fit is wasteful.
    let mean_gap = mean_residual - post_residual as f64;
    score += mean_gap * 0.15;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when the
    // item fits very poorly everywhere else. Make the empty bin moderately
    // attractive (its post_residual is large, so base score already penalizes
    // it); add a mild discount so it beats terrible fits but not decent ones.
    if bin_residual == bin_capacity {
        score -= 12.0;
        // Late in the stream, keep open-bin usage cheaper (avoid bin proliferation).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 4.0;
    }

    // Small pressure against accumulating many open bins with scattered space.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
