    // New-bin candidate: penalize mildly unless residuals are all poor
    if bin_residual == bin_capacity {
        let mean_fit_gap = (mean_residual - item_size as f64).abs();
        score += 5.0 - mean_fit_gap.min(5.0) + progress * 3.0;
    }

    // Mild coupling with mean residual: prefer bins whose placement moves residual toward mean
    let post_dev = (pr - mean_residual).abs();
    score += 0.3 * post_dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
