    // 2-step lookahead: reward a post_residual that exactly matches next item (perfect chain)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;
        if post_residual == next_item_size {
            score -= 25.0; // exact 2-step match: strongly favor
        }
        // penalize leaving a residual that next item cannot use at all
        if post_residual < next_item_size && post_residual > 0 {
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Perfect fit now
    if post_residual == 0 {
        score -= 20.0;
    }

    // Dead space penalty: small unusable residual relative to min item size
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer tighter-than-average bins (best-fit style)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Prefer high fill ratio early; late in stream, be slightly greedy on residual
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_capacity as f64 - bin_residual as f64) * 0.05 * (1.0 - progress);

    // New empty bin candidate: penalize mildly so it's chosen only for poor fits elsewhere
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling)
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0 + 0.25 * (post_residual as f64);
        } else if post_residual >= next_item_size && next_item_size > 0 {
            // reward bins that can also host the lookahead item
            score -= 3.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer fuller bins: deviation from mean residual
    let dev = bin_residual as f64 - mean_residual;
    score += 0.10 * dev;

    // Mild penalty for spreading across too many open bins when residuals are large
    if open_bins_count > 2 && bin_residual as f64 > mean_residual {
        score += 0.05 * (open_bins_count as f64).ln() * (bin_residual as f64 - mean_residual);
    }

    // Time-horizon modulation: early in the stream, be conservative (favor new bins less);
    // late in the stream, pack tighter to close bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress * tightness;
    score += 2.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it attractive only when the item fits poorly everywhere
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else if post_residual as f64 > 0.5 * bin_capacity as f64 && item_size < 40 {
            // small items into a fresh bin is wasteful unless nothing else fits
            score += 6.0;
        } else {
            score += 3.0;
        }
    }

    // Nonlinear penalty for very small post residuals that waste capacity
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    let mut score = r;

    // Reward tight fits: strongly prefer small post_residual, amplified over time
    score -= (1.0 - rn).powf(2.0) * 12.0 * (0.5 + progress);

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let gap = r - next_item_size as f64;
        if gap >= 0.0 {
            score -= 3.0 * (1.0 - gap / cap).powf(2.0);
        } else {
            score += 2.0 * (-gap / cap);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Slight penalty for leaving residuals near mean (wasted space duplication)
    score += 0.05 * (r - mean_residual).abs();

    // Smooth non-linear coupling: prefer using existing bins as stream progresses
    score += progress * (1.0 - rn) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual.
    score -= (bin_capacity as f64 - post_residual as f64).max(0.0) * 0.35;

    // Harmonic class of post_residual: residues near multiples of capacity/4
    // are "usable" leftover slots for future items (sizes 1..100).
    let quarter = bin_capacity / 4;
    let residue_class = (post_residual % quarter) as f64;
    let class_penalty = residue_class / quarter as f64; // 0..1
    score += class_penalty * 8.0;

    // Penalize dead space: post_residual too small for the smallest plausible item.
    if post_residual < 10 {
        score += 12.0;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // next item cannot use this bin's leftover: penalize wasted space proportionally
            score += (post_residual as f64) * 0.10;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the item
    // is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let big_item = (item_size as f64) / (bin_capacity as f64);
        score = bin_capacity as f64 * 0.55 - pressure * 30.0 - big_item * 25.0;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild preference for bins with below-mean residual (keep large holes available).
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (< 10, minimum item size)
    // are the worst outcome; penalize them very heavily.
    if post_residual < 10 {
        score += 500.0;
    } else if post_residual <= 20 {
        // Small gaps that only fit tiny items are also poor.
        score += 40.0;
    }

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: if this is the only bin that fits, using it avoids
    // opening a new bin — strong reward unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 15.0 * pressure * (1.0 - progress);

    // New-bin candidate: penalize mildly by default so we only open a new
    // bin when existing bins are genuinely poor fits (large mean residual
    // mismatch or the item barely fits nowhere well).
    if bin_residual == bin_capacity {
        score += 80.0;
        // But if the next item is large and current mean residuals are small,
        // opening a fresh bin preserves capacity for big items.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual + 20.0 {
            score -= 120.0;
        }
    }

    // Prefer bins whose residual is close to the item (minimize waste).
    score += 0.5 * ((bin_residual as f64) - (item_size as f64)).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: exact match of post_residual to next item is ideal.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: next item exactly fills this bin
        } else if post_residual > next_item_size {
            // next item fits; reward closeness of the leftover after that placement
            let second_left = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - second_left / bin_capacity as f64);
        } else {
            // next item won't fit: dead space penalty grows as post_residual approaches next size
            let gap = (next_item_size - post_residual) as f64;
            score += 8.0 + 12.0 * (1.0 - gap / bin_capacity as f64);
        }
    } else {
        // last item: just minimize waste
        score -= 10.0;
    }

    // Prefer bins whose residual is already below average (consolidate small leftovers)
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless item is large relative to capacity
    // or no good fit exists (post_residual would be small in an existing bin).
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin can chain with next item
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Late-stream pressure: consolidate more aggressively toward the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Base: prefer tight fits (low post_residual), with slight superlinearity
    score += 0.35 * (post / cap) * post;

    // Lookahead: if the next item can fit in the post residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // next item won't fit here: penalize leaving medium dead space
        score += 2.0 + 0.05 * post;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    } else if fitting_bins_count > 2 {
        // plenty of options: mild penalty to keep tightest-fit dominance sharp
        score += 1.5;
    }

    // New-bin candidate handling: only attractive if it promises a great future
    if bin_residual == bin_capacity {
        // perfect fit into empty bin is excellent
        if item_size == bin_capacity {
            score -= 100.0;
        } else if post < 10.0 {
            score -= 8.0; // near-perfect pack into fresh bin
        } else {
            // opening a new bin wastes capacity of existing bins; penalize
            score += 14.0 + 0.3 * open_bins_count as f64;
            // but if the item is large and no open bin fits well, soften
            if fitting_bins_count == 0 {
                score -= 20.0;
            }
        }
    }

    // Time horizon: early in stream, be conservative (favor new bins for flexibility);
    // late in stream, squeeze everything into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post / cap);

    // Global state coupling: high mean residual -> encourage consolidating into loose bins
    if mean_residual > post && bin_residual != bin_capacity {
        score -= 0.08 * (mean_residual - post);
    }

    // Penalize leaving residuals that are awkward (small but nonzero, e.g. 1..10)
    if post > 0.0 && post < 10.0 {
        score += 4.0 * (1.0 - post / 10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial coupling to stream progress.
    // Late in the stream, residual space is worth less (fewer future chances to fill it),
    // so we discount large post-residuals progressively.
    let progress_coupling = 1.0 - 0.6 * progress * progress;
    let mut score = pr * (0.5 + 0.5 * progress_coupling);

    // Smooth convex penalty on normalized residual: very large residuals are dead space,
    // very small ones are fine; quadratic term grows with progress.
    score += 40.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Reward tight fits: subtract a smooth bonus when post_residual is small.
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness * tightness * tightness;

    // Lookahead: if the next item fits in post_residual, reward this placement smoothly.
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64) <= pr;
        let proximity = 1.0 - ((pr - next_item_size as f64).abs() / cap).min(1.0);
        score -= 15.0 * proximity * if fits_next { 1.0 } else { 0.2 };
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mildly prefer bins whose residual deviates favorably from the mean residual,
    // encouraging consolidation of similar bins.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 10.0 * dev * (1.0 - progress);

    // Slight penalty when many bins are open (encourage closing bins out).
    score += 0.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes.
    let post = post_residual;
    let cls = match post {
        0 => 0.0,                       // perfect fit
        1..=5 => -3.0,                  // near-perfect
        6..=15 => 2.0,                  // mildly awkward
        16..=30 => 0.5,
        _ => 1.0,
    };
    score += cls;

    // Modulo arithmetic on post_residual: penalize residuals that are hard to fill
    // by common small item sizes (multiples of 10..20). Residuals divisible by
    // small sizes are more reusable.
    let divisibility_bonus = (2..=20u32)
        .filter(|&d| post % d == 0 && post > 0)
        .count() as f64;
    score -= 0.35 * divisibility_bonus;

    // Lookahead: does next_item_size fit in post_residual? Harmonic pairing reward.
    if next_item_size > 0 {
        if next_item_size <= post {
            score -= 4.0;
            // exact harmonic pairing (residual is a clean multiple of next size)
            if post % next_item_size == 0 {
                score -= 3.0;
            }
        } else {
            // next item won't fit here regardless; slight penalty if we waste space
            score += 0.5;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate (empty bin): penalize mildly; allow only when current
    // fit would create large dead space relative to mean residual.
    if bin_residual == bin_capacity {
        let dead = post as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let threshold = 12.0 + 20.0 * (1.0 - progress) + 0.3 * mean_residual;
        if dead > threshold {
            score -= 8.0; // open a new bin rather than fragment an old one
        } else {
            score += 10.0; // prefer existing bins for decent fits
        }
    }

    // Prefer tighter bins when many bins are open (consolidation pressure).
    score += 0.02 * open_bins_count as f64 * (post as f64 / cap_f);

    // Small reward for filling a large fraction of the bin.
    score -= 0.1 * (item_size as f64 / cap_f) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post-residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can also go here -> great chaining, strong reward
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 30.0 + 0.5 * chain_slack;
        } else {
            // Next item won't fit: dead-space penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap;
        }
    } else {
        // Last item: only current fit matters
        score -= 5.0;
    }

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize tiny unusable residuals (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than the mean
    score += (post_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a good fit
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 55.0;
        // Cheaper to open new bin late in stream with many open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
        // If next item is large and current item is large, fresh bin is useful
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 45.0;
        }
        // Discourage opening new bin when many bins fit the item
        score += 8.0 * fitting_bins_count as f64;
    }

    // Slight preference for fuller bins overall
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use:
    // dead space is post_residual if it's smaller than the smallest plausible item band.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted capacity
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin and leaving this residual stranded.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward for near-exact two-item packing.
            let combo_waste = post_residual - next_item_size;
            if combo_waste < 10 {
                score -= 8.0;
            }
        } else {
            // Post-residual too small for the next item: mild penalty proportional to stranded space.
            score += 0.15 * post_residual as f64;
        }
    }

    // Prefer fuller bins relative to the current mean residual across open bins.
    score += 0.10 * (bin_residual as f64 - mean_residual);

    // Early in the stream, be more willing to open new bins (explore); later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as the stream progresses,
        // but give a small early-phase discount to build a diverse pool.
        score += 20.0 * (0.3 + 0.7 * progress);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // new bin pairs well with a large follow-up item
        }
    }

    // When many bins are open, discourage spreading; consolidate into existing bins.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early in stream, waste is tolerable; late, tight fits matter more.
    let p = progress;
    let coupling = pr * (1.0 + p) * (pr / cap) * (0.5 + 0.5 * p);
    score += coupling;

    // Penalize large relative waste more than small waste (quadratic in normalized waste).
    let norm_waste = pr / cap;
    score += 40.0 * norm_waste * norm_waste * (0.3 + 0.7 * p);

    // Reward tight fits (small post_residual) increasingly as stream advances.
    score -= (1.0 - norm_waste) * (1.0 - norm_waste) * (10.0 + 20.0 * p);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 30.0 * p;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward; if it
    // cannot fit, mild penalty for consuming space needed later.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (n - pr).abs() < 0.5 {
            score -= 35.0;
        } else if n <= pr {
            score -= 12.0 * (1.0 - (pr - n) / cap);
        } else {
            score += 8.0 * ((n - pr) / cap);
        }
    }

    // New-bin candidate: neutralize its raw advantage; only attractive when
    // existing bins are badly fragmented (high mean residual) or item is large.
    if bin_residual == bin_capacity {
        let mean_frag = (mean_residual / cap).max(0.0);
        let item_rel = item_size as f64 / cap;
        score = cap as f64 * 0.9
            - 20.0 * mean_frag * mean_frag
            - 15.0 * item_rel * (0.5 + p)
            + 10.0 * (1.0 - p);
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        if fitting_bins_count == 1 {
            score += 20.0;
        }
    }

    // Mild diversity pressure: many open bins -> prefer consolidating into
    // below-average-residual bins.
    if open_bins_count > 1 {
        let dev = (mean_residual - bin_residual as f64) / cap;
        score += 6.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction bands.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let band = (pr / 10.0).floor(); // 0..10 harmonic class

    // Reward tight fits (small post_residual) extra.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score -= 4.0;
    } else {
        // Large dead space penalized superlinearly.
        score += 0.35 * (pr - 30.0);
    }

    // Modulo arithmetic on post_residual: residuals divisible by 10 pair well
    // with the 10..80 item grid; odd/awkward residuals are dead-space prone.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 5 != 0 {
        score += 3.0;
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 15.0;
            } else if slack <= 20 {
                score -= 6.0;
            } else {
                score += 0.15 * (slack as f64);
            }
        } else {
            // Next item cannot use this bin's remainder: penalize wasting space.
            score += 0.10 * (next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when item is large and nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_bonus = 18.0
            + 20.0 * (item_size as f64 / c)
            + 10.0 * progress
            - 0.5 * open_bins_count as f64;
        score -= new_bin_bonus;
        // A fresh bin is bad if an open bin would leave a tiny remainder.
        if bin_residual > item_size && (bin_residual - item_size) <= 15 && fitting_bins_count > 0 {
            score += 45.0;
        }
    }

    // Mean residual context: prefer bins below the mean residual (fill the fullest bins first).
    score += 0.20 * (mean_residual - pr);

    // Band-based harmonic tiebreaker: prefer mid-band usable residuals.
    score += 0.5 * (band - 4.0).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are nearly useless -> heavy penalty.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 - (post_residual as f64) / 11.0);
    }
    // Mid-range dead space (11..=25) also hard to fill with items >=10.
    if post_residual >= 11 && post_residual <= 25 {
        score += 12.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward bins whose residual tightly matches the item (tight fit indicator).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 15.0 * (1.0 - tightness).max(0.0) * (1.0 - tightness).max(0.0);

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }
    // Penalize leaving a gap that the next item cannot use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 0.4;

    // New-bin candidate: make it attractive only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 <= 10.0
            || (fitting_bins_count == 0)
            || (mean_residual < item_size as f64);
        if poor_fit {
            score -= 35.0;
        } else {
            // Opening a new bin while good fits exist is wasteful.
            score += 30.0 + mean_residual * 0.2;
        }
    }

    // Slight progression bias: as stream advances, favor consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - tightness.abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for wasted space: dead space quadratically penalized.
    let frag = (post_residual as f64 / bin_capacity as f64).powi(2);
    score += 40.0 * frag;

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item exactly fills this bin.
            let chain_gap = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - chain_gap / bin_capacity as f64);
            if chain_gap == 0.0 {
                score -= 50.0; // exact 2-item fill is ideal
            }
        } else {
            // Next item won't fit here: penalize proportionally to wasted lookahead.
            score += 15.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Prefer tight fits relative to mean residual across open bins.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;
    score -= 5.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly; escalate with how many bins are open
        // and how much slack already exists in the system.
        score += 35.0 + 2.0 * open_bins_count as f64 + mean_residual * 0.2;
        // Early in the stream, opening bins is cheaper (builds a pool).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin is a good long-term host.
        if next_item_size >= bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Slight preference for fuller bins overall (first-fit-decreasing flavor).
    score -= 10.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Penalize leaving dead space that no plausible future item can use.
    let t = step_index as f64 / (total_items.max(2) as f64);
    let dead_threshold = 10.0 + 20.0 * (1.0 - t);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 0.35 * (dead_threshold - post_residual as f64);
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual: slight penalty for squandering
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Global state: many open bins with high mean residual -> encourage consolidation
    // into existing bins rather than spreading; few bins -> be pickier about waste.
    if open_bins_count > 0 {
        let pressure = mean_residual / bin_capacity as f64;
        if pressure > 0.5 {
            score -= 5.0 * pressure;
        }
        if open_bins_count > 8 {
            score -= 0.5 * ((open_bins_count - 8) as f64).min(10.0);
        }
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        // Late in the stream, prefer reusing bins more strongly.
        score += 25.0 * t;
        // A new bin is fine if the item is large (little waste risk).
        if item_size >= 70 {
            score -= 20.0;
        }
    }

    // Mild preference for filling emptier bins when residuals are similar.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let t = pr / cap; // normalized post residual in [0,1]
    let g = progress;

    // Base: post residual, damped by a progress-dependent polynomial.
    let mut score = pr * (0.55 + 0.45 * (g * g));

    // Smooth interaction: prefer large post residual early, penalize small dead space late.
    score += 12.0 * (t * t - t) * (1.0 - 2.0 * g).abs();

    // Tight-fit reward via cubic coupling of item size and progress.
    let it = item_size as f64 / cap;
    score -= 8.0 * it * it * it * (1.0 - g);

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * g);
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let nt = next_item_size as f64 / cap;
        score -= 10.0 * nt * (1.0 - g * g);
    } else if next_item_size > 0 {
        score += 4.0 * g;
    }

    // Crowd-aware penalty: spread load when many bins are open.
    score += 0.6 * (open_bins_count as f64).ln().max(0.0) * (1.0 - t);

    // Mean-residual coupling: prefer bins near the mean residual (smooth quadratic).
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate: make it mildly attractive early, expensive late.
    if bin_residual == bin_capacity {
        score = 30.0 - 25.0 * g + 10.0 * g * g;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into modulo bands.
    let cap = bin_capacity as f64;
    let post = post_residual as u32;
    let frac = post as f64 / cap;

    // Perfect fits are heavily rewarded.
    if post == 0 {
        score -= 1000.0;
    }

    // Harmonic classes on post_residual: residuals that are multiples of common
    // item sizes (or near-divisors of capacity) are more likely reusable.
    let harmonic_bonus = |p: u32| -> f64 {
        let mut b = 0.0;
        for &m in &[10u32, 20, 25, 50] {
            if m != 0 && p % m == 0 && p > 0 {
                b += 15.0;
            }
        }
        // integer-division thresholds: which typical item classes fit the leftover
        for &s in &[10u32, 20, 30, 40, 50, 60, 70, 80] {
            if p >= s {
                b += 2.0;
            }
        }
        b
    };
    score -= harmonic_bonus(post);

    // Penalize tiny unusable dead space (0 < post < 10).
    if post > 0 && post < 10 {
        score += 40.0 * (1.0 - frac * 10.0);
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward strongly; if it cannot fit, penalize proportionally.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 300.0;
        } else if next_item_size <= post {
            score -= 25.0 + 0.5 * (post - next_item_size) as f64;
        } else {
            score += 10.0 + 0.3 * (next_item_size - post) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Prefer bins with residual below mean (tighter packing first).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no open bin is a good fit.
    if bin_residual == bin_capacity {
        let bad_open = if next_item_size > 0 && next_item_size > post { 1.0 } else { 0.0 };
        score = cap * (1.0 + 0.1 * (open_bins_count as f64).sqrt())
            - 80.0 * bad_open
            - if fitting_bins_count == 0 { 200.0 } else { 0.0 };
    }

    // Mild stream-progression pressure: later in stream, pack tighter.
    score -= 5.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero post_residual gaps are nearly unusable.
    if post_residual > 0 {
        let min_item = 1u32;
        if post_residual < min_item {
            score += 1000.0; // unreachable, defensive
        }
        // Penalize gaps too small for the lookahead item (dead space for k=2 lookahead)
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
        // Penalize very small gaps harshly (hard to ever fill)
        if post_residual <= 10 {
            score += 25.0;
        } else if post_residual <= 20 {
            score += 10.0;
        }
    } else {
        // Perfect fit: strong reward
        score -= 50.0;
    }

    // Exact-fit detection relative to typical item granularity
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into existing bins
    // rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += pressure * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Slightly prefer bins tighter than the mean (better packed bins)
    score += (mean_residual - bin_residual as f64) * 0.1;

    // New-bin candidate: make empty bins less attractive unless the item fits
    // very poorly everywhere (handled by last-chance bonus above).
    if bin_residual == bin_capacity {
        score += 60.0 + post_residual as f64 * 0.2;
        // Opening a new bin is reasonable for large items early on
        if item_size >= 50 && open_bins_count == 0 {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of next item into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward tight two-item packing (post_residual leaves small slack for next item)
            score -= 45.0 * (1.0 - slack / bin_capacity as f64);
            // Extra bonus if next item fills the bin almost exactly after placement
            if slack <= 5.0 {
                score -= 30.0;
            }
        } else {
            // Next item cannot fit here: penalize leaving awkward residuals
            let gap = (next_item_size - post_residual) as f64;
            if post_residual > 0 && gap <= 10.0 {
                score += 12.0; // near-miss dead space
            }
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average
    let dev = post_residual as f64 - mean_residual;
    score += 0.35 * dev;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating tiny unusable residuals (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Early stream: encourage opening bins to build flexibility slightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress); // new-bin candidate less attractive early
    }

    // Discourage scattering across many open bins
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items,
    // but only when it's nonzero (perfect fit should be heavily favored).
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 20.0; // unusable sliver
        } else {
            score += 0.05 * dead * dead / bin_capacity as f64;
        }
    } else {
        score -= 25.0; // perfect fit: strong reward
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this
    // placement (chaining); otherwise penalize slightly.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            let chain_fit = 1.0 - (post_residual - next_item_size as u32) as f64 / bin_capacity as f64;
            score -= 10.0 * chain_fit;
        } else {
            score += 3.0;
        }
    }

    // Time horizon: early in the stream, be more exploratory (favor new bins
    // less, encourage compacting); later, prefer using open bins to avoid
    // accumulating many partially-filled bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when many
        // bins are already open.
        score += 8.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
        // Allow new bin early if current item is large and mean residual is low.
        let mr = if mean_residual.is_finite() { mean_residual } else { 0.0 };
        if mr < item_size as f64 * 0.5 && progress < 0.5 {
            score -= 10.0;
        }
    } else {
        // Existing bin: mild reward for using open bins late in the stream.
        score -= 2.0 * progress;
    }

    // Global balance: prefer bins whose residual is below the mean (compacting
    // the emptiest bins first keeps fuller bins available for large items).
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_residual as f64 };
    if (bin_residual as f64) < mr {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Slight preference for filling bins with larger items.
    score -= 0.05 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Quadratic penalty on post_residual, scaled by stream progress:
    // late in the stream, large leftover space is more costly.
    let pr = post_residual as f64;
    score += 0.5 * pr * pr / bin_capacity as f64 * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth cubic term.
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= 8.0 * tightness * tightness * tightness;

    // Penalize bins whose residual deviates from the mean residual
    // (prefer balanced residual profiles), smoothly coupled.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev * dev / (bin_capacity as f64 * (1.0 + progress));

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits well in the resulting residual.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let waste = (pr - ni).abs();
        score += 0.3 * waste * progress;
        if ni <= pr && pr - ni < 10.0 {
            score -= 6.0;
        }
    }

    // Slight penalty when many bins are open (discourage fragmentation).
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is only "wasted" if it
    // cannot host any plausible future item. Class residual into capacity
    // fractions and modulo classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_frac = pr / cap; // fraction of capacity left over

    // Dead-space penalty grows super-linearly as residual fraction shrinks
    // toward the "unusable" zone (smaller than the smallest plausible item).
    if pr_frac > 0.0 {
        score += 30.0 / (pr_frac + 0.05);
    }

    // Harmonic class: post_residual buckets via integer division thresholds.
    // Residuals in [0..10) are near-perfect; [10..25) good; [25..50) mediocre;
    // >= 50 is a "half-empty" class which is actually desirable to preserve.
    let class = post_residual / 25; // 0,1,2,3+ harmonic classes
    match class {
        0 => score -= 20.0,                       // tight fit, great
        1 => score -= 8.0,                        // decent
        2 => score += 4.0,                        // mediocre
        _ => score -= 6.0,                        // half-empty: flexible
    }

    // Lookahead coupling: if the next item can exactly fill post_residual,
    // strongly reward; if next item barely fits, mildly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 / (gap + 1.0);
        } else {
            // next item cannot use this residual: penalize proportionally
            let over = (next_item_size - post_residual) as f64;
            score += (over / cap) * 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless all open bins would
    // leave terrible dead space. Compare item fit quality against mean residual.
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score = cap - item_size as f64 + 15.0;
        // allow opening a new bin if existing bins are very full on average
        score -= (mean_residual / cap) * 5.0;
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mild preference for fuller bins overall (low residual favored).
    score += (bin_residual as f64 / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (post_residual in the "dead zone" 1..=15)
    if post_residual > 0 && post_residual <= 15 {
        score += (16.0 - post_residual as f64) * 8.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Fit quality: reward tight fits relative to item size
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 20.0;

    // Open bins pressure: penalize placements that keep many bins open
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // dead space that even the next item can't use
    }

    // New bin candidate: opening a new bin is generally costly; make empty bin
    // score unattractive unless open bins are few or residual is very fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let base = bin_capacity as f64 - item_size as f64;
        // new bin becomes attractive only if many open bins with small residuals
        let fragmentation = (mean_residual - item_size as f64).abs();
        score = base + 40.0 - open_bins_count as f64 * 3.0 - fragmentation * 0.5 - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (low post_residual is good).
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else {
        // Penalize dead space nonlinearly: small leftovers (<10) are nearly useless.
        if post_residual < 10 {
            score += 25.0;
        }
        // Large leftover space is fine (room for future items).
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post_residual, strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item fits after this one: mild reward proportional to leftover
            let after_next = post_residual - next_item_size;
            if after_next < 10 {
                score -= 20.0; // chain leaves near-perfect fill
            } else {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here after placing current item: mild penalty.
            score += 6.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit flavor),
    // but relax when few fitting bins exist (last-chance bin).
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = residual_f / mean_residual;
        score += (rel - 1.0) * 10.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // heavily favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: make an empty bin attractive only when the
    // item is large relative to typical residuals or when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 1.0 };
        // Prefer new bin when open bins have little space left (crowded).
        let new_bin_bias = 15.0 * (1.0 - crowding) + 10.0 * (item_size as f64 / bin_capacity as f64);
        score -= new_bin_bias;
        // But if the item is small and bins are roomy, discourage opening a new bin.
        if item_size < 40 && crowding > 0.5 {
            score += 20.0;
        }
    }

    // Slight stream-progression term: later in the stream, favor consolidation
    // (tight fits) a bit more since fewer future items remain to fill gaps.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: small post_residual that can never host typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward strongly.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 18.0 * (next_item_size as f64) / (bin_capacity as f64);
        } else {
            score += 6.0;
        }
        // Perfect pair: item + next exactly fills residual.
        if (item_size + next_item_size) as f64 == bin_residual as f64 {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Global state: many open bins -> prefer filling existing ones.
    let pressure = (open_bins_count as f64) / (1.0 + (total_items as f64).sqrt());
    score += pressure * 2.5;

    // Mean residual deviation: prefer bins whose residual is below mean (more filled).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Time horizon: early in the stream, be pickier about poor fits (penalize waste);
    // late in the stream, just close out bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.3;

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual == bin_capacity as u32 { 0.0 } else { 0.0 };
        let _ = bad_fit;
        // Opening a new bin costs ~1 bin; only worth it if best existing post residual is large.
        score = 0.55 * (bin_capacity as f64) + 0.25 * mean_residual + pressure * 3.0;
        if fitting_bins_count <= 1 {
            score += 60.0; // never open new bin when it's the only fitting bin
        }
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 8.0; // slight bonus: new bin can host the pair
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual (tight fit), with non-linear sharpening
    let mut score = pr + (pr / cap).powi(3) * 60.0;

    // Penalize residuals that are too large relative to mean residual (wasteful use of this bin)
    let mean_pr = mean_residual - item_size as f64;
    let diff = pr - mean_pr;
    score += 0.08 * diff * diff / cap;

    // Reward using bins whose leftover matches the next item (lookahead synergy)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 25.0 * (1.0 - gap / cap).powi(2);
    } else {
        // End of stream: strongly prefer filling existing bins
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - progress);
    }

    // New-bin candidate: neutral-ish, penalized mildly so tight fits win,
    // but attractive late in the stream when open bins have poor fits
    if bin_residual == bin_capacity {
        score = pr + 15.0 + 20.0 * progress - 0.15 * mean_residual;
    }

    // Smooth stream-progress coupling: early on, keep bins flexible (larger residuals OK);
    // later, compact bins aggressively
    score -= (1.0 - progress) * (pr / cap) * 10.0;
    score += progress * (pr / cap).powi(2) * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose residual falls into
    // "small" classes (hard to reuse) should be penalized less if they are
    // nearly full, but penalized more if they leave awkward mid-range gaps.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class boundaries via integer division thresholds on post_residual.
    let class = post_residual / 10; // 0..10 harmonic class
    match class {
        0 => { score -= 40.0; }              // near-perfect fit, reward strongly
        1 => { score -= 25.0; }              // excellent fit
        2 => { score -= 12.0; }              // good fit
        3 | 4 => { score += 5.0; }           // awkward mid gap
        5 | 6 => { score += 12.0; }          // half-empty, mediocre
        _ => { score -= 3.0; }               // large residual still reusable
    }

    // Modulo coupling: residuals that are multiples of common item sizes
    // (10, 20, 25, 50) are more reusable; reward them.
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 25 == 0 { score -= 4.0; }
    if post_residual % 50 == 0 { score -= 4.0; }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 { score -= 12.0; } else { score += (slack as f64) * 0.15; }
        } else {
            // next item cannot fit here; slight penalty proportional to overflow
            score += ((next_item_size - post_residual) as f64) * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: opening a fresh bin should only win when all open
    // bins would leave bad residue. Penalize the empty bin moderately so that
    // decent fits in existing bins win, but a fresh bin beats terrible fits.
    if bin_residual == bin_capacity {
        score += 35.0;
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer filling bins that are already relatively full (low residual
    // relative to mean) to consolidate waste.
    if mean_residual > 0.0 {
        let ratio = post / cap;
        score += (mean_residual / cap) * 8.0 * (1.0 - ratio);
    }

    // Tie-break: prefer bins with more competition (spread usage evenly
    // among fitting bins when many are open).
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 12) are nearly worthless -> heavy penalty.
    if post_residual < 12 {
        score += 60.0;
    } else if post_residual < 25 {
        // "awkward gap" zone: penalize quadratically as it shrinks
        score += (25.0 - post_residual as f64) * 2.5;
    }

    // Reward tight fits (small waste relative to item size)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 30.0;

    // Last-chance pressure: if this is the only bin that fits, strongly
    // discourage opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating
    // into existing bins; with few bins, opening a new one is cheap.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: an empty bin has perfect flexibility,
    // but should only win when the fit into existing bins is bad.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Opening a new bin is more attractive early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // reward preserving this bin's state for it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // Penalize if placing here leaves a gap the next item just barely misses
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Prefer bins whose residual deviates below the mean (more "spent" bins)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fills (small post_residual is good).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    } else if post_residual < 20 {
        score -= 80.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 500.0; // perfect chain: next item fills this bin exactly
        } else if diff <= 10 {
            score -= 150.0;
        } else if diff <= 25 {
            score -= 40.0;
        } else {
            // Dead space penalty: post_residual that nothing can use.
            score += diff as f64 * 0.5;
        }

        // Penalize if placing here makes post_residual too small for the next item
        // while the bin residual could have held it now (bad sequencing).
        if next_item_size > post_residual && post_residual < 10 {
            score += 60.0;
        }
    }

    // Compare against mean residual: prefer bins that are "ahead" of the average fill
    // (i.e., tighter bins) to consolidate packing.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += (res - mean_residual) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New-bin candidate handling: only attractive when item fits poorly everywhere
    // (large post_residual waste avoided) or few fitting bins exist.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 45.0 + 30.0 * (1.0 - progress);

        // A new bin is good if the item would leave a perfect-ish residual here.
        let new_post = bin_capacity - item_size;
        if next_item_size > 0 {
            let d = (new_post as i64 - next_item_size as i64).unsigned_abs();
            if d == 0 { score -= 120.0; }
            else if d <= 10 { score -= 40.0; }
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // forced
        }
    }

    // Mild penalty for proliferating bins when many are already open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.02;

    // Penalize leaving dead space that can't fit typical items
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead: if next item fits into post_residual, reward this bin strongly
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 30.0 + next_item_size as f64 * 0.3;
        } else {
            score += (next_item_size as f64 - post_residual as f64) * 0.4;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins early, more when many bins fit
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut nb = 40.0 * (1.0 - progress) + open_bins_count as f64 * 2.0;
        if fitting_bins_count > 0 {
            nb += 60.0;
        }
        // allow new bin if current bins would leave huge waste
        if fitting_bins_count > 0 {
            let best_waste = (bin_residual as i64 - item_size as i64).unsigned_abs() as f64;
            if best_waste > 40.0 {
                nb -= 45.0;
            }
        }
        score += nb;
    }

    // Prefer filling bins below mean residual (balancing)
    score += (mean_residual - post_residual as f64) * 0.15;

    // Late in stream: be greedy about closing gaps
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.1;

    // Small penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 - norm_pr); // peaks at half-full bins
    score -= 20.0 * poly * (1.0 + progress);

    // Penalize tight fits less early, more late (dead space matters more as stream ends)
    score += progress * norm_pr * norm_pr * 15.0;

    // Reward using bins when few fitting bins exist (last-chance effect)
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 5.0;
    } else if next_item_size > 0 {
        score += 3.0 * (next_item_size as f64 - pr).max(0.0) / cap;
    }

    // Slight penalty when bin residual deviates from mean residual (smooth coupling)
    score += ((mean_residual - pr) / cap).powi(2) * 4.0;

    // Mild preference for existing bins over opening new ones, decaying with progress
    if bin_residual == bin_capacity {
        score += 2.0 + 4.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let post_mod = post_residual % 10;
    if post_mod == 0 {
        score -= 12.0; // residual is a harmonic multiple of 10: highly reusable
    } else if post_mod <= 2 {
        score += 8.0; // tiny sliver, near-dead space
    }

    // Integer-division thresholds: post_residual / 10 as a class index
    let class = post_residual / 10;
    score -= (class as f64) * 1.5; // coarser classes (larger usable space) favored

    // Next item lookahead: does this bin's post-residual form a good class with next item?
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 6.0;
        if gap % 10 == 0 {
            score -= 5.0; // next item leaves another harmonic residual
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0; // next item won't fit here anyway
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when no open bin has a tight fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 + 0.1 * (open_bins_count as f64);
        // opening fresh is good if current item is large relative to mean residual
        if (item_size as f64) > mean_residual + 10.0 {
            score -= 18.0;
        }
    }

    // Prefer bins tighter than the mean (best-fit flavor)
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.3;

    // Early stream: slightly prefer packing into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0;

    // Fraction-of-capacity coupling: reward filling > 50% of the bin
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    if fill_frac > 0.5 {
        score -= (fill_frac - 0.5) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = if bin_capacity == 0 { 1.0 } else { bin_capacity as f64 };
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    let progress = if total_items > 0 {
        ((step_index as f64) / (total_items as f64)).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let mean_frac = (mean_residual / cap).clamp(0.0, 1.0);
    let open_pressure = 0.20 * (open_bins_count.min(40) as f64);
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post;

    // Strongly reward placements that leave the bin full.
    let fill_after = ((cap - post) / cap).clamp(0.0, 1.0);
    score -= 8.0 * fill_after.powi(3);

    // Mild preference for bins that are already tighter than the current average.
    score += 0.03 * (residual - mean_residual).clamp(-cap, cap);

    // Exact fit is highly desirable.
    if post == 0.0 {
        score -= 12.0;
    }

    // Lookahead dead-space control.
    if next > 0.0 {
        if post > 0.0 && post < next {
            // The remaining gap cannot hold the next item: penalize this dead space.
            let missing = next - post;
            score += 14.0
                + 0.65 * next
                + 0.55 * missing
                + 6.0 * (missing / next) * (1.0 - progress);
        } else if post == next {
            // Perfect preparation for the next item.
            score -= 10.0 + 5.0 * (1.0 - progress);
        } else if post > next {
            // The next item can still fit here; reward residual sizes close to it.
            let closeness = 1.0 / (1.0 + (post - next) / (0.25 * cap));
            score -= 6.0 * closeness;
        }
    }

    // A current+next pair is urgent when the next item is at least as large as
    // the current one and both can share one fresh bin.
    let pair_urgent = next > 0.0 && next >= item && item + next <= cap;

    if is_new_bin {
        let mut new_bin_cost = 5.0 + open_pressure + 7.0 * mean_frac + 3.0 * progress;

        if fitting_bins_count == 0 {
            // No open bin can take the item.
            new_bin_cost -= 6.0;
        } else if fitting_bins_count == 1 {
            if pair_urgent {
                // Opening now can absorb the next item instead of opening later anyway.
                new_bin_cost += 1.0;
            } else {
                // Avoid bypassing the last fitting open bin unless the fit is truly bad.
                new_bin_cost += 35.0;
            }
        } else {
            // Many open bins can still take the item; opening a new bin is risky.
            new_bin_cost += 30.0 + 8.0 * (fitting_bins_count.saturating_sub(1).min(10) as f64);
        }

        score += new_bin_cost;
    } else if fitting_bins_count == 1 {
        if next > 0.0 && post < next && pair_urgent {
            // This bin is the last chance, but using it would block a feasible
            // current+next pairing in a new bin, so reduce the last-chance bonus.
            score -= 0.5;
        } else {
            // Last chance before opening a new bin.
            score -= 5.0 + 0.05 * (open_bins_count.min(20) as f64);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits exactly-ish after placement
            score -= 40.0 / (1.0 + diff);
        } else {
            // next item would not fit here: mild penalty proportional to waste
            score += 0.5 * diff;
        }
        // exact two-item fill
        if post_residual == next_item_size {
            score -= 300.0;
        }
    }

    // Penalize dead space below minimum item size (1..100 unknown dist, assume small floor)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New empty bin candidate: only attractive when open bins have poor residuals
    if bin_residual == bin_capacity {
        score += 150.0 + mean_residual * 0.5;
        // if current item is large relative to capacity, new bin is fine
        if item_size > bin_capacity / 2 {
            score -= 60.0;
        }
    } else {
        // Prefer bins tighter than average (best-fit-like against mean_residual)
        if (bin_residual as f64) < mean_residual {
            score -= 20.0;
        } else {
            score += 10.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * (item_size as f64 / bin_capacity as f64);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0 * (1.0 - post_residual as f64 / 30.0);
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to gap.
            score += 2.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer filling bins as completely as possible.
        score -= 12.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = if fitting_bins_count == 0 {
            20.0
        } else {
            (item_size as f64 / bin_residual as f64) * 10.0
        };
        // Open new bins more freely early, cautiously late.
        score = 30.0 + 20.0 * progress - poor_fit + 0.5 * open_bins_count as f64;
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidation.
    let pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln().max(1.0);
    score += 2.0 * pressure;

    // Prefer bins whose residual is close to the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, smoothed polynomial in normalized progress
    let mut score = pr * (1.0 + 0.5 * progress * (1.0 - progress));

    // Non-linear coupling: squared normalized post-residual penalizes dead space,
    // weighted by stream progress (dead space matters more later)
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Cubic term: mild reward for tight fits early, stronger later
    score -= 15.0 * (1.0 - norm_pr).powi(3) * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits in post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 5.0 * (nxt - pr) / cap;
        }
    }

    // Slight penalty for spreading across many open bins relative to mean residual
    score += 0.05 * (bin_residual as f64 - mean_residual) * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 10.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: classify into capacity-fraction buckets
    let cap = bin_capacity as f64;
    let item_class = (item_size as f64 / cap * 8.0).floor() as i64; // 0..=8 classes
    let next_class = (next_item_size as f64 / cap * 8.0).floor() as i64;

    // Reward tight fits: post_residual in low harmonic class (small dead space)
    let post_class = (post_residual as f64 / cap * 8.0).floor() as i64;
    score -= 6.0 * (8 - post_class) as f64 * (post_residual as f64 / cap);

    // Penalize leaving residuals that no typical next item can use.
    // Modulo-style dead-zone detection: residuals in (0,10) or (50,60) awkward bands
    let r = post_residual;
    if r > 0 && r < 10 { score += 15.0; }
    if r >= 10 && r < 20 { score += 4.0; }

    // Harmonic pairing: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack < 10 { score -= 12.0; } else { score -= 3.0; }
    }
    // If next item of same harmonic class as current, prefer pairing residuals of complementary class
    if next_item_size > 0 && next_class == item_class {
        score -= 2.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New empty bin candidate: penalize moderately; allow it only when item is large
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * (item_size as f64 / cap);
        if item_size > bin_capacity / 2 { score -= 10.0; }
    }

    // Prefer filling bins below mean residual (evening out residuals)
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Early stream: encourage opening bins for large items to build good structure
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 && item_size > bin_capacity / 2 {
        score -= 4.0;
    }

    // Integer-division threshold: post_residual divisible into two ~half slabs is reusable
    if r >= 40 && r % 2 == 0 && r / 2 >= 20 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for typical items are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // tiny sliver => wasted space
    } else if post_residual >= 10 && post_residual < 30 {
        // usable but risky gap: penalize proportionally to how "awkward" it is
        score += 0.6 * (30 - post_residual) as f64;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Perfect-fill bonus: item exactly consumes residual.
    if item_size == bin_residual {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, this placement is synergistic.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // extra reward if post-residual then becomes near-zero after next item
        let after_next = post_residual - next_item_size;
        if after_next == 0 {
            score -= 12.0;
        } else if after_next < 10 {
            score += 5.0; // leaves a dead sliver after next item
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use this gap: dead space likely
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening yet another bin.
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize so it only wins when fits are terrible
        score += 30.0 + 2.0 * open_bins_count as f64;
        // but if current bin would leave a dead sliver, opening a fresh bin becomes attractive
        if post_residual > 0 && post_residual < 10 {
            score -= 55.0;
        }
    } else {
        // mild pressure to prefer emptier bins when many are open
        score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Align with global mean residual: prefer bins whose residual is near the mean (balanced packing)
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post residual exactly (or nearly) matches the next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 - gap * 0.8; // perfect match gets biggest bonus
    }

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Prefer tighter fits relative to other bins' residuals.
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when open bins could still fit the item,
    // unless the fit is very tight.
    if bin_residual == bin_capacity {
        let tightness = (bin_capacity - item_size) as f64;
        let pressure = open_bins_count as f64 / (step_index as f64 + 1.0).max(1.0);
        score += 8.0 + tightness * 0.3 - pressure * 2.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // new bin is fine if it also serves the next item well
        }
    }

    // Late in the stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: prefer bins where the item nearly fills the residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize very small dead space that future items (>=1) may not use,
    // but only when it is truly awkward (nonzero, below typical small item size).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chaining
        } else if post_residual >= next_item_size {
            score -= 6.0; // next item still fits
        } else {
            score += 4.0; // next item won't fit here; bin will close, mild penalty
        }
    }

    // Last chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; scaled by how many bins already fit the item.
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 15.0 + 20.0 * poor_fit;
        // Late in the stream, opening new bins is riskier (fewer chances to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // If mean residual is large, prefer existing bins.
        score += mean_residual * 0.15;
    }

    // Mild penalty for spreading across many open bins when residuals are large.
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 0.5;
    }

    // Prefer bins whose residual is above the mean (keep flexibility for future items).
    let diff = (bin_residual as f64) - mean_residual;
    score += diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: minimize post residual, but with a non-linear twist:
    // very small post residuals are dead space -> penalize quadratically.
    let mut score = pr - 12.0 * (1.0 - pr_norm).powi(2) * cap * 0.15;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more; early, keep flexibility.
    let coupling = pr_norm.powi(2) * (1.0 - progress) * 20.0
                 - pr_norm * progress * 15.0;
    score += coupling;

    // Reward near-perfect fits smoothly via gaussian-like term.
    let tightness = (pr / cap - 0.05).abs();
    score -= 10.0 * (-tightness * tightness * 400.0).exp();

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Prefer bins already below mean residual (consolidation), smooth term.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Lookahead: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 {
        // smooth penalty if next item barely misses fitting
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 30.0 * (-gap * gap * 800.0).exp() * gap;
    }

    // Slight preference to keep fewer bins open early on.
    score += 0.02 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: residues near 0 are "clean" slots
    let r = (post_residual % 10) as f64;
    score += if post_residual == 0 {
        -50.0 // perfect fill, always best
    } else {
        // penalize residues far from 0 (awkward dead space), reward near-multiples
        (5.0 - r) * 0.8
    };

    // Integer-division thresholds: classify post_residual into usable size classes
    if post_residual >= 80 { score += 30.0; }        // huge leftover: wasted bin
    else if post_residual >= 50 { score += 6.0; }
    else if post_residual >= 30 { score -= 4.0; }    // sweet spot for mid items
    else if post_residual >= 10 { score -= 2.0; }
    else { score += 20.0; }                          // tiny dead space (<10 unusable)

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item's size class matches leftover class
            let class_match = (post_residual / 10) - (next_item_size / 10);
            score -= 8.0 + (class_match as f64) * 0.5;
        } else {
            // next item cannot use this bin's leftover: penalize by mismatch
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
        // modulo coupling between next item and post residual
        let m = (post_residual as u64 % (next_item_size.max(1) as u64)) as f64;
        score += m * 0.05;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when residuals everywhere are tight
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 12.0 - avg_tightness * 20.0 + (open_bins_count as f64) * 0.3;
    }

    // Late in stream: prefer consolidating into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small post_residuals (< 10) are unusable for any item
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize near-full but slightly-wasted bins more softly
    if post_residual >= 10 && post_residual <= 20 {
        score -= 8.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins pressure
        score += 30.0 + 2.0 * pressure;
    } else {
        // Existing bin gets a mild reward scaled by pressure
        score -= (pressure * 0.05).min(10.0);
    }

    // Lookahead coupling: favor bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Mean residual coupling: prefer bins deviating favorably from mean residual
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual, but avoid tiny useless slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // dead space penalty
    }

    // 2-step lookahead: reward when next item fits exactly into post residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            let slack = post - next;
            // Perfect 2-chain match: big reward.
            if slack == 0.0 {
                score -= 30.0;
            } else if slack < 10.0 {
                score -= 18.0 - slack * 0.8;
            } else {
                score -= 6.0;
            }
        } else {
            // Next item won't fit here: penalize proportionally to overflow.
            score += (next - post).min(50.0) * 0.35;
        }
        // If next item also can't fit anywhere else, better to keep residual large.
        if next > post && post < 10.0 {
            score += 10.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins),
    // unless it's the last chance bin.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += (res - mean_residual) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (next_item_size > 0 && post_residual < next_item_size && post_residual < 10);
        if poor_fit {
            score -= 20.0;
        } else {
            score += 15.0; // keep filling existing bins otherwise
        }
    }

    // Late in stream: consolidate harder, avoid new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 12.0;
    }

    // Many open bins: push toward consolidation.
    score += open_bins_count as f64 * 0.3 * (res / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual quadratically.
    let post = post_residual as f64;
    score -= (bin_capacity as f64 - post).powi(2) / bin_capacity as f64 * 0.5;

    // Lookahead coupling: if the next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to next item: penalize proportionally.
        let waste = (next_item_size - post_residual.min(next_item_size)) as f64;
        score += waste * 0.35;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Time horizon: early in stream, prefer opening bins / spreading; late, fill tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 6.0;

    // Global residual pressure: high mean residual across bins -> discourage adding
    // more residual to already-loose bins, encourage consolidating into tight ones.
    score += (mean_residual - post).max(0.0) * 0.12;
    score -= (post - mean_residual).max(0.0) * 0.05;

    // Bin count pressure: many open bins -> favor filling existing ones over new bins.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate handling: a fresh empty bin should only win when the item
    // is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let no_good_fit = fitting_bins_count <= 1;
        if no_good_fit && large_item > 0.6 {
            score -= 20.0; // open a new bin for big items with poor alternatives
        } else if no_good_fit && post_residual < 10 {
            score -= 8.0; // near-perfect fit nowhere else
        } else {
            score += 15.0 + progress * 10.0; // otherwise discourage new bins
        }
    }

    // Slight preference to keep residuals in "usable" ranges for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0; // tiny unusable slivers are waste
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: prefer tight fits (low post residual), with non-linear shaping.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Dead-space penalty: post-residuals below typical item size are wasted.
    let dead = (norm_pr - 0.5 * (norm_item + norm_next)).max(0.0);
    score += 60.0 * dead * dead;

    // Smooth stream-progress coupling: as the stream advances, tighten packing
    // more aggressively (discount tight fits later, penalize slack earlier).
    let coupling = 1.0 + 0.6 * progress * (1.0 - progress) * 4.0;
    score *= coupling;

    // Lookahead: reward residual that can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 6.0 * (norm_next / (norm_pr + 0.01)).min(1.0);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - norm_pr / norm_next.max(0.01)).max(0.0);
    }

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - progress);
    }

    // Mild preference for bins below mean residual (balance load smoothly).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: mildly penalize so it is chosen only when fits are poor,
    // with the penalty decaying as the stream progresses.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - 0.5 * progress) + 5.0 * norm_item * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: residual modulo small divisors ---
    // Residuals divisible by 10 (harmonic with the classic item grid) are reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0; // perfectly harmonic leftover, future items likely fit
        } else if pr % 5 == 0 {
            score -= 2.5;
        } else {
            score += 3.0; // off-grid dead space penalty
        }
        // Integer-division thresholds: tiny unusable slivers
        if pr < 10 {
            score += 25.0; // dead space: nothing can ever fit
        } else if pr < 20 {
            score += 8.0;
        }
        // Mod-3 / mod-7 coupling: residuals in awkward classes get penalized
        if pr % 7 == 0 && pr > 0 {
            score -= 1.5;
        }
        if pr % 3 == 1 && pr > 20 {
            score += 1.0;
        }
    } else {
        score -= 40.0; // perfect closure: reward heavily
    }

    // --- Lookahead harmonic match: can next_item_size exactly divide post_residual? ---
    if next_item_size > 0 && pr >= next_item_size {
        if pr % next_item_size == 0 {
            score -= 12.0; // next item closes this bin exactly
        } else if (pr - next_item_size) % 10 == 0 {
            score -= 5.0; // next item leaves harmonic residual
        } else {
            score += 2.0;
        }
    } else if next_item_size > 0 && pr < next_item_size {
        score += 4.0; // next item can't use this bin anyway
    }

    // --- Capacity fraction classes ---
    let fill = item_size as f64 / bin_capacity as f64;
    if fill > 0.5 {
        score -= 4.0; // large items: prefer placing them, frees small-residual bins
    } else if fill < 0.2 {
        score += 1.5; // tiny items into fresh space is wasteful
    }

    // --- Last-chance pressure ---
    if fitting_bins_count == 1 {
        score -= 15.0; // only this bin fits; strongly prefer using it
    } else if fitting_bins_count > 3 {
        score += 1.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive for large items or when
        // existing residuals are all in bad harmonic classes.
        score += 30.0 + (open_bins_count as f64) * 2.0;
        if item_size >= 50 {
            score -= 20.0; // big items fine in fresh bins
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 5.0;
        }
    }

    // --- Stream progression: late in the stream, consolidate aggressively ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever be
    // useful (below the minimum item size of 1, but practically below a
    // "usable gap" threshold) are heavily penalized.
    let usable_threshold = 12.0;
    if (post_residual as f64) < usable_threshold && post_residual > 0 {
        score += (usable_threshold - post_residual as f64) * 40.0;
    }

    // Perfect fit reward: leaving nothing behind is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Reward when this bin's residual closely matches the item (low waste).
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score += waste * 0.3;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Post residual can't hold the next item: mild penalty for
            // stranding space, stronger if it's a tiny dead gap.
            score += (post_residual as f64) * 0.2;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new
    // ones (make the new-bin candidate expensive) and encourage consolidation.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins count.
        score += 20.0 + open_bins_count as f64 * 3.0;
        // But if existing bins would leave large dead space, new bin becomes
        // attractive: compare against mean residual waste.
        let best_existing_waste = mean_residual - item_size as f64;
        if best_existing_waste > 25.0 {
            score -= best_existing_waste * 1.5;
        }
        // Never open a new bin when the item fits tightly elsewhere.
        if fill_ratio > 0.8 && fitting_bins_count > 0 {
            score += 100.0;
        }
    } else {
        // Existing bins get a bonus when many bins are open (consolidation).
        score -= open_bins_count as f64 * 1.5;
        // Prefer bins with below-average residual (tighter bins first).
        score += (bin_residual as f64 - mean_residual) * 0.4;
    }

    // Late-stream bias: as the stream progresses, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
