pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically (fragmentation).
    score += 0.08 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward tight fits (small post_residual) exponentially.
    score -= 6.0 * (-post_residual as f64 / 12.0).exp();

    // Lookahead: if next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 4.0;
            // Extra reward when post residual becomes exactly the next item size.
            if next_item_size == post_residual {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here: penalize leaving awkward leftovers.
            score += 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 3.0;
        // If many bins already fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 5.0 * fitting_bins_count as f64;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * progress;
        // If mean residual is high, existing bins have room; discourage new bin.
        score += 0.05 * mean_residual;
    } else {
        // Reward using bins whose residual is above average (balance load).
        if (bin_residual as f64) > mean_residual {
            score -= 1.5;
        }
        // Many open bins: encourage consolidation into existing bins.
        score -= 0.3 * open_bins_count as f64;
    }

    // Prefer placing into bins with residual close to item_size (near-perfect fit).
    let slack = (bin_residual as i64 - item_size as i64).abs() as f64;
    score += 0.02 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: penalize wasted space, with a non-linear (quadratic) coupling
    // that grows as the stream progresses (late waste is more costly).
    let mut score = post * (1.0 + progress * progress);

    // Reward tight fits: post_residual near zero is desirable, especially late.
    let tightness = 1.0 - post / cap;
    score -= item_size as f64 * tightness * (0.5 + progress);

    // Smooth dead-space penalty: residuals too small for any future item
    // (items >= 1, so any residual is usable; weight by mean residual context).
    let dead = (post - mean_residual).abs();
    score += 0.3 * dead * (1.0 - tightness);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0 + 25.0 * progress;
    }

    // New-bin candidate: make it attractive only when existing fits are poor.
    // Poor fit = post_residual large relative to capacity (bad compaction).
    if is_new_bin {
        // Base reluctance to open new bins, decaying with progress.
        score += 40.0 * (1.0 - 0.5 * progress);
        // But reward opening a fresh bin when the item is large and would
        // leave a very small residual elsewhere anyway.
        score -= 0.5 * item_size as f64 * (post / cap);
    }

    // Lookahead: if the next item exactly fits the post-residual, reward strongly.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 15.0 * (1.0 - gap / cap).max(0.0);
        // Penalize leaving residual that neither fits next item nor is large.
        if post > 0.0 && post < next_item_size as f64 {
            score += 8.0 * (1.0 - post / next_item_size as f64);
        }
    }

    // Mild penalty for scattering across many open bins.
    score += 0.5 * open_bins_count as f64 * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes reward "nice" residues.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Reward small post_residual (tight fit), strongly.
    score -= (cap - prf) / cap * 30.0;

    // Harmonic bonus: post_residual divisible by small integers yields
    // reusable space classes (e.g., residues in {0,10,20,25,50} pack well).
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 3.0; }
    } else {
        // Perfect closure: bin exactly filled.
        score -= 25.0;
    }

    // Dead-space penalty: tiny unusable residues (1..10) are wasted space.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size < pr {
            // Next item fits: the closer it fills, the better.
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
            // Harmonic class of the double residual after both items.
            let double_res = pr - next_item_size;
            if double_res % 10 == 0 { score -= 4.0; }
        } else {
            // Next item cannot use this bin's remainder: penalize large leftovers.
            score += prf / cap * 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make empty bins mildly unattractive unless
    // current bin is a really bad fit (large post_residual with no lookahead fit).
    if bin_residual == bin_capacity {
        let bad_fit = prf / cap > 0.5 && (next_item_size == 0 || next_item_size > pr);
        if bad_fit {
            score -= 10.0; // allow opening a fresh bin for a poor fit
        } else {
            score += 20.0; // discourage unnecessary bin proliferation
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.15;

    // Progress-aware tie-breaker: later in the stream, favor tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 2.0;

    // Mean-residual coupling: if this bin's residual is far below mean,
    // it is "dirtier" than average — slight penalty to prefer cleaner bins.
    score -= (mean_residual - prf) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

