    // Open-bins pressure: with many open bins, prefer consolidating into existing bins
    // (penalize opening new bins / spreading).
    let open_pressure = open_bins_count as f64 * 1.5;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

