    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item won't fit in the gap: penalize leaving stranded space.
        score += 6.0;
    }

    // Mean residual coupling: if this bin's post-residual is far below the mean,
    // it is being filled efficiently; reward that.
    score += (mean_residual - post_residual as f64) * -0.15;

    // New-bin candidate: make empty bins slightly less attractive unless current
    // residuals are poor fits (handled by penalties above).
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less post residual relative to capacity.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Aggressive 2-step lookahead: if next item exactly fits post_residual,
    // strongly reward this placement (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // Next item fits here too: reward proportionally to leftover after both.
            let two_step_left = post_residual - next_item_size;
            score -= 20.0 - 0.2 * two_step_left as f64;
        } else {
            // Next item does NOT fit this bin after placement: penalize
            // proportionally to the dead space created.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    } else {
        // Last item: simply prefer minimal post residual (already base score).
        score += 0.1 * post_residual as f64;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and would leave a very tight or very large residual elsewhere.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if next item is large and would chain well in a fresh bin, soften.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // Late in the stream, opening new bins is more acceptable.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Prefer keeping number of open bins low when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic reward for small post-residual
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty: residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: reward if next item fits in post-residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 14.0;
        } else if next_item_size > bin_residual {
            // next item won't fit here anyway; mild reward for using this bin now
            score -= 4.0;
        } else {
            score += 6.0;
        }
        // penalize leaving post_residual just below next item size (frustrating near-fit)
        if post_residual < next_item_size && next_item_size - post_residual <= 8 {
            score += 8.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer fuller bins relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Time horizon: early in stream, be more willing to open new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: competitive baseline, adjusted by progress and load
        score = 45.0 - 20.0 * progress + 0.15 * open_bins_count as f64;
        if item_size > 60 {
            score += 6.0; // big items prefer fresh bins early
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 4.0; // pairing opportunity with next item in fresh bin
        }
    } else {
        // late in stream, prefer packing into existing bins
        score += 8.0 * (1.0 - progress);
        // many open bins: encourage consolidation
        if open_bins_count > 4 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // Base: prefer small post residual, with smooth polynomial shaping
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Smooth coupling with stream progress: later in stream, penalize wasted space more
    score += 20.0 * norm_post * progress * (1.0 - progress + 0.25);

    // Interaction of post residual with mean residual across open bins
    score += 3.0 * (post - mean_residual).abs() / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize opening new bins when many bins are already open and item fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + 6.0 * (open_bins_count as f64).sqrt() * (1.0 - progress);
        // but reward new bin if item is large relative to residual pattern
        score -= 0.05 * item_size as f64 * progress;
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 4.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 2.0 * (nxt - post) / cap;
        }
    }

    // Reward tight fits via smooth cubic of post residual
    score -= (1.0 - norm_post).powi(3) * 2.0;

    // Mild penalty for many open bins (consolidation pressure), smoothed
    score += 0.02 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter-capacity bands (1..=25, 26..=50, 51..=75, 76..=100)
    let item_class = ((item_size as f64) / (bin_capacity as f64 / 4.0)).ceil() as u32;
    let post_class = ((post_residual as f64) / (bin_capacity as f64 / 4.0)).ceil() as u32;

    // Perfect fit: post_residual in {0, 10, 20, 25, 50} -> strong reward
    let perfect_set: [u32; 5] = [0, 10, 20, 25, 50];
    if perfect_set.contains(&post_residual) {
        score -= 12.0;
    }
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic pairing: post_residual + next_item_size == bin_capacity -> perfect lookahead fit
    if next_item_size > 0 && post_residual == bin_capacity - next_item_size.min(bin_capacity) {
        score -= 30.0;
    }
    // Lookahead fits exactly into post residual band
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_waste = post_residual - next_item_size;
        score -= pair_waste as f64 * 0.6;
        // harmonic classes match: item class pairs well with next class
        let next_class = ((next_item_size as f64) / (bin_capacity as f64 / 4.0)).ceil() as u32;
        if item_class + next_class == 3 || item_class == next_class {
            score -= 4.0;
        }
    } else if next_item_size > 0 {
        // next item cannot use the leftover: penalize dead space proportionally
        score += post_residual as f64 * 0.25;
    }

    // Integer-division thresholds on post_residual: residues that are hard to fill
    let hard_threshold = bin_capacity / 3; // 33: anything below can only take tiny items
    if post_residual > 0 && post_residual < hard_threshold {
        score += (hard_threshold - post_residual) as f64 * 0.35;
    }

    // Post class coupling: leaving a half-capacity residual is valuable
    if post_class == 2 {
        score -= 6.0;
    } else if post_class >= 3 {
        score -= 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean residual (good consolidation)
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Early stream: be more willing to open new bins for large items to keep options open
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus discount when item is large or stream is early
        score += 8.0;
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
        score -= (1.0 - progress) * 6.0;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Modulo tiebreak on post_residual: multiples of 10 are friendlier slots
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small for the known next item are also likely dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
        score -= 15.0 * tightness * tightness;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage scattering across many open bins,
    // but allow opening a fresh bin when residuals are already fragmented.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - 0.5 * progress);

    // New-bin candidate: only attractive if item fits badly everywhere
    // (large post_residual in this bin) or residuals are tiny/dead.
    if bin_residual == bin_capacity {
        // Baseline neutrality: slightly worse than a perfect fit,
        // better than any bin leaving a dead gap.
        score += 8.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        }
        // If mean residual across open bins is small, fresh capacity is valuable.
        if mean_residual < item_size as f64 * 1.5 {
            score -= 12.0;
        }
    }

    // Prefer bins whose residual is close to the item (best-fit core),
    // modulated by lookahead: if next item fits the post residual, bonus.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.3;
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base tightness: prefer bins that end up nearly full.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    score += 0.35 * (post / cap) * (post / cap) * cap; // convex penalty on large dead space

    // 2-step lookahead: reward if the NEXT item fits exactly into post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // perfect match strongly rewarded; decays with gap
            score -= 14.0 * (1.0 - gap / cap) * (1.0 - gap / cap);
            if gap == 0.0 {
                score -= 10.0; // exact two-item completion bonus
            }
        } else {
            // next item won't fit here: penalize wasted potential
            score += 6.0 * (nxt / cap);
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    let dev = (post - mean_residual) / cap;
    score += 5.0 * dev;

    // Last-chance bin before opening a new bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Late in the stream: consolidate harder, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses or many bins open.
        score += 8.0 + 20.0 * progress + 0.6 * open_bins_count as f64;
    } else {
        score -= 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio;

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // Extra reward if next item fills the bin completely afterwards
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else if post_residual < next_item_size {
            // Dead space risk: penalize small unusable leftovers
            if post_residual > 0 && post_residual < 10 {
                score += 12.0;
            }
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is costly; penalize unless current open bins are badly fragmented
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins early when existing bins are roomy
        score += 30.0 + 40.0 * fragmentation;
        // Late in the stream, new bins are relatively cheaper
        score -= 20.0 * progress;
        // If many bins already open and none fit well, allow new bin
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    } else {
        // Mild penalty for using very fragmented bins when alternatives may exist
        if fitting_bins_count > 2 && post_residual > 0 && post_residual < 5 {
            score += 8.0;
        }
        // Reward packing into bins that are already below mean residual
        // (consolidating waste into the emptier bins)
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    // Global load balancing: slightly discourage adding to bins when many are open
    score += 0.15 * open_bins_count as f64;

    // Progress-dependent dead-space aversion: late in stream, waste matters more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fills; late, tolerate larger residuals (new bins cheap).
    let phase = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    let tightness = (pr / cap) * (1.0 - phase);
    score += 18.0 * tightness * tightness * cap / 100.0;

    // Reward near-perfect fits with a smooth quadratic bonus.
    let fit_frac = pr / cap;
    score -= 12.0 * (1.0 - fit_frac) * (1.0 - fit_frac) * (1.0 - phase);

    // Penalize dead space relative to mean residual (smooth coupling).
    score += 0.35 * (pr - mean_residual).abs() * (0.5 + 0.5 * (1.0 - phase));

    // Last-chance bin: reward using it strongly.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * (1.0 - phase);
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - ((post_residual - next_item_size) as f64) / cap;
        score -= 6.0 * snug * snug;
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty for fragmenting space.
        score += 4.0 * (1.0 - phase) * (pr as f64 / cap);
    }

    // New empty bin candidate: penalize slightly early, more when open bins are tight.
    if bin_residual == bin_capacity {
        score += 3.0 + 10.0 * phase + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space classes
    let pr = post_residual;
    if pr > 0 {
        // small residuals (<10) are dead space given min item size 1..100 unknown; penalize tiny slivers
        if pr <= 5 {
            score += 25.0;
        }
        // residual exactly matching common item sizes is valuable
        let usable = (pr >= 10 && pr <= 100);
        if usable {
            score -= 15.0;
        }
        // modulo arithmetic: residuals divisible by common sizes (10,20,25,50) are reusable
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 25 == 0 { score -= 6.0; }
        if pr % 50 == 0 { score -= 5.0; }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size == pr {
        score -= 200.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        score -= 20.0 + (pr - next_item_size) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 40.0;
        // early in stream, allow new bins more readily for flexibility
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // if many open bins with low mean residual, prefer consolidation
        if mean_residual < 30.0 {
            score += 20.0;
        }
    }

    // Prefer filling bins with larger residual usage (tighter packing)
    score -= (bin_residual as f64 / cap) * 5.0;

    // Slight preference to keep number of open bins low late in stream
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item (<=9) are pure waste.
    if post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 18.0; // hard-to-fill gap
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Reward tight fits (small relative waste) with a nonlinear bonus.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * fill_ratio * fill_ratio;

    // Lookahead: if the next item fits exactly in the post residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0; // perfect chain: both items packed tightly
        } else if gap < 25 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // next item cannot use this residual; penalize proportionally to how stranded it is.
        score += 5.0 + 0.2 * post_residual as f64;
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Open-bin pressure: discourage spreading across too many bins unless fit is good.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress) * (post_residual as f64 / bin_capacity as f64);

    // Pull toward mean residual: prefer bins whose post-residual keeps the fleet balanced.
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline; only attractive when no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0; // fresh bin can absorb the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but weight by fill ratio
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 2.5 * fill * (bin_residual as f64);

    // 2-step lookahead: reward exact match between post_residual and next_item_size
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 18.0 * (-gap / 12.0).exp();          // strong bonus for near-perfect 2-chain
        if post_residual == next_item_size {
            score -= 25.0;                            // perfect chain: bin closes exactly
        }
        // penalize leaving space that neither fits next item nor is useful
        if post_residual > 0 && (post_residual as u32) < next_item_size.min(10) {
            score += 10.0;                            // tiny dead space
        }
    } else {
        // last item: just minimize post_residual
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        // but allow opening if no open bin fits well
        if fitting_bins_count == 1 && post_residual < 15 {
            score -= 40.0;
        }
    }

    // Discourage placements that create dead space relative to mean residual
    if (post_residual as f64) > mean_residual * 0.6 && post_residual > 0 {
        score += 6.0;
    }

    // Late in stream: be more frugal with open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) with a nonlinear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 + 0.35 * (post_residual as f64);
        } else if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_frac = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill_frac * (open_bins_count as f64).ln().max(1.0);

    // Global imbalance: penalize bins far from the mean residual.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev * dev / (mean_residual + 1.0);

    // Time horizon: early in the stream, be more willing to open fresh bins
    // (brand-new bin gets residual == capacity); later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, discounted early, penalized late.
        score = 55.0 - 25.0 * (1.0 - progress) + 20.0 * progress;
        if fitting_bins_count == 1 {
            score += 40.0; // don't open new bin when a last-chance bin exists
        }
    } else {
        // Late stream: extra reward for filling existing bins deeply.
        score -= 15.0 * progress * fill_frac;
    }

    // Small penalty for very small post residuals that are still unusable
    // (dead slivers below the minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (low post_residual), with quadratic dead-space penalty
    let mut score = post + 0.35 * (post / cap) * post;

    // Smooth non-linear coupling: dead space hurts more as the stream progresses
    let tightness = 1.0 - post / cap; // 0 = empty bin, 1 = perfect fit
    score -= 12.0 * tightness * tightness * (0.5 + 0.5 * progress);

    // Perfect-fit reward, stronger later in the stream
    if post_residual == 0 {
        score -= 25.0 + 15.0 * progress;
    }

    // Penalize bins whose residual is already small relative to mean (hoarding small space)
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64) / (mean_residual + 1.0);
        score += 0.8 * (rel - 1.0) * (rel - 1.0);
    }

    // Last-chance bin bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead: reward leaving room compatible with the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post >= n {
            score -= 6.0 * (1.0 - (post - n) / cap);
        } else {
            // post-residual can't hold next item: mild penalty, scaled by waste fraction
            score += 5.0 * (n - post) / cap;
        }
    }

    // New-bin candidate: neutral-ish baseline; discourage early, allow late or when open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score = 20.0 + 30.0 * (1.0 - progress) * (1.0 - crowd) - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify residual into
    // capacity-fraction buckets and reward/penalize per class.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // 0..1

    // Class index via integer division on post_residual (harmonic bands of 10)
    let band = post_residual / 10; // 0..10
    match band {
        0 => score -= 30.0,                 // perfect/very tight fit: excellent
        1 => score -= 18.0,                 // 10-19 leftover: still good
        2 => score -= 8.0,                  // 20-29: moderate
        3 | 4 => score -= 2.0,              // 30-49: neutral-ish
        5 | 6 => score += 6.0,              // 50-69: half-empty bin, poor use
        7 | 8 => score += 14.0,             // 70-89: bad
        _ => score += 22.0,                 // 90+: nearly empty, wasteful
    }

    // Dead-space penalty: residual too small for the smallest plausible item (<= 10)
    if post_residual < 10 {
        score -= 25.0; // sealed bin is fine — no dead space
    } else if post_residual < 20 && next_item_size > post_residual && next_item_size > 0 {
        score += 10.0; // likely dead space given lookahead
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // harmonic class match: next item's class aligns with residual band
            let next_band = next_item_size / 10;
            if next_band == band {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits badly everywhere else.
    if bin_residual == bin_capacity {
        // fresh bin: score is post_residual = capacity - item_size already;
        // add fixed opening cost, discounted late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * (1.0 - 0.5 * progress);
        // reward opening when item is large (harmonic high class)
        if item_size >= 70 {
            score -= 10.0;
        }
        // discourage opening when many bins open and mean residual is high
        if open_bins_count > 2 && mean_residual > item_size as f64 {
            score += 12.0;
        }
    } else {
        // mild reward for keeping bins consolidated when few bins are open
        if open_bins_count <= 2 {
            score -= 3.0;
        }
    }

    // Alignment bonus: item size in harmony with residual (same 10-band)
    let item_band = item_size / 10;
    let res_band = bin_residual / 10;
    if item_band == res_band {
        score -= 6.0;
    }

    // Fractional refinement: quadratic term pushing toward minimal fractional waste
    score += 20.0 * frac * frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable dead space (gaps too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Pressure from number of open bins: discourage proliferation of open bins,
    // but allow opening a fresh bin when existing residuals are fragmented.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open bin count.
        score = 55.0 + 2.0 * open_bins_count as f64;
        // Opening a new bin is attractive if mean residual is fragmented (low mean
        // means open bins have little useful space left).
        if mean_residual < item_size as f64 + 5.0 {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Slight penalty proportional to open bins when placing into existing bins
        // is fine (it reduces pressure to open more).
        score += 0.5 * open_bins_count as f64;
    }

    // Lookahead: if next item could exactly use the post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space for the known next item: penalize.
        score += 10.0;
    }

    // Deviation from mean residual: prefer bins that are either very full or
    // leave room consistent with the average (mild regularization).
    score += 0.1 * ((post_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly favor bins that become nearly full.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 30.0 * fill_ratio;
    } else if post_residual <= 10 {
        score -= 15.0 * fill_ratio;
    }

    // Dead-space penalty: residuals that are too small to fit typical items
    // (below the minimum plausible item size) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size well.
    if next_item_size > 0 {
        let diff = post_residual as i64 - next_item_size as i64;
        if diff == 0 {
            // Next item exactly fills this bin: excellent chaining.
            score -= 40.0;
        } else if diff > 0 {
            // Next item fits with leftover; penalize by leftover magnitude.
            score -= 25.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty scaled by mismatch.
            score += 5.0 + (diff.abs() as f64).min(30.0);
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that can fit the item,
    // use it rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.5 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is costly; make the
    // empty bin attractive only when current bins have poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base cost of opening a bin; shrinks slightly as stream progresses
        // (amortization) but grows with number of open bins.
        let open_cost = 60.0 + 2.0 * open_bins_count as f64 - 20.0 * progress;
        // If the item fits perfectly in a fresh bin and no open bin matches well,
        // the cost stands; otherwise this stays unattractive vs. good fits above.
        score = open_cost + item_size as f64 * 0.2;
        // Lookahead synergy: if next item also fits a fresh bin alongside this one,
        // opening a new bin becomes more attractive.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize creating dead space that is too small to be useful later
    // (items are >= 1, so residual 1..=3 is nearly unusable dead space).
    if post_residual >= 1 && post_residual <= 3 {
        score += 25.0;
    } else if post_residual > 0 && post_residual < item_size {
        // residual smaller than current item: hard to refill
        score += 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let best_possible = if fitting_bins_count > 0 { 0.0 } else { 0.0 };
        // Penalize opening a new bin; scale penalty with how many bins fit the item.
        let mut penalty = 20.0 + 8.0 * fitting_bins_count as f64;
        // If the best existing fit would leave a very small residual, discourage new bin more.
        if (post_residual as f64) < mean_residual * 0.5 {
            penalty += 15.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty *= (1.0 - 0.5 * progress);
        // If lookahead item is large, a fresh bin is more valuable.
        if next_item_size >= 60 {
            penalty -= 12.0;
        }
        let _ = best_possible;
        score += penalty;
    }

    // Lookahead coupling: if this placement leaves room exactly for (or compatible with)
    // the next item, reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0; // perfect lookahead match
        } else if post_residual >= next_item_size {
            score -= 8.0;  // next item still fits here
        } else {
            score += 3.0;  // next item won't fit in this bin
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidation
    // into existing bins rather than spreading.
    if !is_new_bin {
        let consolidation = (mean_residual - post_residual as f64).abs();
        score += 0.05 * consolidation;
        // Reward using bins whose residual is far above mean (cleanup of large holes).
        if (bin_residual as f64) > mean_residual + 5.0 {
            score -= 5.0;
        }
    }

    // Mild penalty proportional to number of open bins to discourage bin proliferation.
    score += 0.15 * open_bins_count as f64;

    // Late-stream urgency: near the end, avoid leaving many fragmented open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 && !is_new_bin {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: wasted space, weighted non-linearly by stream progress
    let mut score = pr * (0.5 + 0.8 * progress * progress);

    // Smooth quadratic penalty on small-but-nonzero residuals (dead space)
    score += 12.0 * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr) * cap * 0.1;

    // Reward tight fits (small post_residual) with smooth coupling to progress
    score -= 10.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr - nxt).max(0.0) / cap;
        score -= 8.0 * (1.0 - fits_next) * (1.0 - progress);
        // Penalize if next item barely misses
        if nxt > pr {
            score += 6.0 * ((nxt - pr) / cap) * (0.3 + 0.7 * progress);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Many open bins: discourage spreading; prefer fuller bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    // Mean residual coupling: penalize leaving residual far from mean (fragmentation)
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev * progress;

    // New-bin candidate: mild penalty so it loses to decent fits, wins over bad fits
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: class 0 (perfect fit) best,
    // small dead-space classes penalized progressively.
    let post = post_residual;
    let class = post % 10;
    let class_penalty = match class {
        0 => -12.0,
        1 => 14.0,
        2 => 11.0,
        3 => 8.0,
        4 => 5.0,
        5 => 2.5,
        6 => 1.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division threshold: leftovers that could host a small item
    // (>=10) are valuable; below 10 they are dead space.
    if post >= 10 {
        score -= (post / 10) as f64 * 2.0;
    } else {
        score += 6.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 20.0;
        } else if next_item_size <= post {
            // next fits but leaves another residue: mild reward scaled by fit quality
            let slack = (post - next_item_size) as f64;
            score -= 8.0 - slack * 0.4;
        } else {
            // next item cannot use this leftover: penalize proportionally
            let gap = (next_item_size - post) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer tight fits: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post as f64 / cap);
    score -= tightness * 10.0;

    // New-bin candidate: make empty bins attractive only when current bins
    // would leave large unusable residue; otherwise discourage spreading.
    if bin_residual == bin_capacity {
        if post_residual < 10 && item_size > 0 {
            // item nearly fills a fresh bin -> good
            score -= 5.0;
        } else {
            score += 18.0 + mean_residual * 0.2;
        }
    }

    // Late in the stream, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 2 {
        score += progress * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are almost unusable
    // (items are >= 1, but typical items are much larger), so penalize them hard.
    if post_residual > 0 && post_residual < 15 {
        score += (15 - post_residual) as f64 * 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward tight fits relative to the item size (low waste ratio).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage new bins and
    // favor consolidation into existing space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // New-bin candidate (empty bin): penalize unless the item fits badly
    // everywhere else (large dead space would be created in existing bins).
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.3;
        if post_residual + item_size > bin_residual {
            // unreachable, kept for safety
        }
        // If lookahead item is large and this bin stays fresh, slightly soften.
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 10.0;
        }
    }

    // If the next item would fit exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > post_residual {
        // Next item cannot use this bin's leftover: leftover likely dead space.
        score += (post_residual as f64) * 0.5;
    }

    // Slight preference for bins below mean residual (use laggard bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // 2-step lookahead: reward when next item fits into post_residual exactly / well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * next_fit; // next item fits here -> strong reward
            if next_item_size == post_residual {
                score -= 20.0; // perfect 2-step match
            }
        } else {
            // next item cannot use the leftover: penalize dead space proportionally
            score += (post_residual as f64 - (post_residual as f64 % 10.0)) * 0.3;
            score += 5.0;
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are bad;
    // relax penalty late in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 35.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Penalize dead space that no plausible future item can use.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (post_residual as f64);
    }

    // Lookahead: reward bins whose post-residual matches the next item well.
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if post_residual >= next_item_size {
            score -= (30.0 - gap * 0.6).max(0.0);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Tightness ratio: relative fill quality.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Prefer denser bins (small residual relative to mean) early/mid stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let density = (mean_residual - post_residual as f64) / (mean_residual + 1.0);
    score -= 20.0 * density * (1.0 - progress);

    // Late in the stream, be more aggressive about filling open bins.
    if progress > 0.7 {
        score -= 15.0 * tightness;
    }

    // New empty bin candidate: only attractive when existing bins fit poorly
    // or post_residual would be large dead space.
    if bin_residual == bin_capacity {
        score += 60.0;
        if post_residual as f64 >= mean_residual {
            score += 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild preference to spread across fewer bins when many are open.
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Reward tight fits: post_residual near zero strongly favored (smooth quadratic)
    score -= (1.0 - pr / cap).powi(3) * cap * 0.6;

    // Penalize dead space that next item cannot use (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap > 0.0 {
            score += gap.powi(2) / cap;
        } else {
            // next item fits perfectly: reward
            score -= (-gap / cap) * 12.0;
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild preference to fill bins with low residual relative to mean
    score += (mean_residual - pr) * 0.05;

    // New-bin candidate: smooth sigmoidal gating on stream progress and fit scarcity
    if bin_residual == bin_capacity {
        let scarcity = (fitting_bins_count as f64).recip();
        let w = 1.0 / (1.0 + (-6.0 * (progress - 0.5)).exp());
        score += pr * (0.4 + 0.6 * w) * scarcity;
        // discourage hoarding new bins late when mean residual is large
        score += mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Opening a new bin is generally discouraged; penalize so existing bins win on decent fits.
        score += 45.0;
        // But large items are worth starting a fresh bin for (avoids fragmenting a partially used bin).
        if item_size >= 50 {
            score -= 25.0 + 0.3 * (item_size - 50) as f64;
        }
        // If the lookahead item cannot fit in this fresh bin either, opening it is more attractive
        // since the residual would otherwise be dead space.
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 12.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    } else {
        // Reward tight packing: subtract proportional to how full the bin becomes.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.06;

        // Last-chance bin: strongly favor using it before opening a new one.
        if fitting_bins_count == 1 {
            score -= 18.0;
        }

        // Lookahead synergy: if next item fits into post_residual, this bin stays useful.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0 + 0.05 * next_item_size as f64;
        }

        // Harmonic dead-space classes: residual mod 10 measures unusable granularity.
        // Small nonzero remainders are the worst dead space; tiny residuals (<10) are nearly dead.
        let residue_class = (post_residual % 10) as f64;
        score += 0.4 * residue_class;
        if post_residual < 10 {
            score += 22.0;
        } else if post_residual < 20 {
            score += 6.0;
        }

        // If this bin's residual deviates badly from the mean residual pool, slight penalty.
        let dev = post_residual as f64 - mean_residual;
        score += 0.03 * dev.abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Penalize dead space below the smallest possible item (1..100 unknown, use small gap threshold).
    if post_residual > 0 && post_residual < item_size.min(next_item_size.max(1)) {
        score += 15.0;
    }

    // Open-bin pressure: prefer spreading into existing bins when many are open.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it over new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New bin candidate: make it mildly unattractive unless residual pressure is high.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 0.5;
        // But if next item is large and this item would leave a gap next_item can't use, allow new bin
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Lookahead coupling: reward leaving space exactly usable by next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Mean residual coupling: bins far below mean residual waste space.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/tight fits
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space relative to smallest possible item
        score += (post_residual as f64 / 10.0).powi(2) * 0.5;
    }

    // 2-step lookahead: reward if next item fits perfectly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 800.0;
        } else if post_residual > next_item_size {
            let gap = post_residual - next_item_size;
            score -= 300.0 * (1.0 - gap as f64 / 100.0);
        } else {
            // next item cannot fit: penalize proportionally to leftover
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score += post_residual as f64 * 3.0;
    }

    // Last-chance bin: favor using it when few alternatives fit
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Prefer bins with residual below mean residual (denser bins)
    score += (mean_residual - bin_residual as f64) * 1.5;

    // Mild preference for keeping fewer open bins early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (open_bins_count as f64).ln() * 10.0 * (1.0 - progress);

    // New-bin candidate: penalize slightly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 150.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but dampen dead-space penalty late in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 0.6 * tight * (1.0 - 0.5 * progress) * bin_capacity as f64;

    // Lookahead: reward residual that exactly fits next item (perfect pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual > next_item_size {
            // next item fits here later; mild bonus proportional to leftover after next
            let after_next = post_residual - next_item_size;
            score -= 15.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize large unusable gaps
            score += 0.3 * (post_residual as f64 - next_item_size as f64).abs();
        }
    } else {
        // last item: any bin works, prefer zero waste
        score += 0.1 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global pressure: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 && mean_residual > 0.0 {
        let spread = bin_residual as f64 - mean_residual;
        score += 0.15 * spread; // prefer bins below-average residual (fuller bins)
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: only attractive when current residual is a bad fit
    // for the item AND the lookahead, or stream is young.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > 0.45 * bin_capacity as f64
            && (next_item_size == 0 || next_item_size > post_residual);
        let base = 30.0 + 0.5 * post_residual as f64;
        score += if poor_fit && progress < 0.6 { -10.0 } else { base };
    }

    // Nonlinear coupling: quadratic penalty on medium dead space (10..30)
    if post_residual >= 10 && post_residual <= 30 {
        let mid = (post_residual as f64 - 20.0) / 10.0;
        score += 6.0 * (1.0 - mid * mid);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap;

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = post;
    score += 30.0 * x * x * cap;
    score -= 20.0 * x * x * x * cap;

    // Stream progress coupling: later in stream, penalize waste more strongly
    let prog_coupling = (0.5 + 1.5 * progress) * x * x * cap;
    score += prog_coupling;

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 12.0 * (1.0 - (post - nxt) / cap) * (0.5 + progress);
        } else {
            score += 8.0 * (nxt - post) / cap * cap;
        }
    }

    // Last chance bin: strongly favor using it before opening new bins
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate: mild penalty so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * (1.0 - progress);
    }

    // Mean residual context: penalize bins deviating from mean residual
    score += 0.3 * (post - mean_residual).abs();

    // Mild penalty for many open bins to discourage fragmentation
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer small post_residual (tight fit).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Harmonic class of post_residual: dead space that no future item (>=1)
    // can fill is fine only if tiny; penalize residuals in awkward classes.
    let pr = post_residual;
    // Residuals that are multiples of 25 are "friendly" (many item sizes fit).
    let friendly = (pr % 25 == 0) as f64;
    score -= 6.0 * friendly;

    // Penalize awkward residual classes (e.g., residual in 1..10 leaves dead space
    // since typical items are larger).
    if pr > 0 && pr < 10 {
        score += 18.0;
    }

    // Perfect fit bonus.
    if pr == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here; slight penalty proportional to gap.
            score += 0.05 * ((next_item_size - pr) as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current item is large relative to
    // capacity (fresh bin keeps flexibility) or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * large_item;
        // Penalize opening new bins when many bins already fit the item.
        score += 3.0 * (fitting_bins_count as f64);
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mean residual coupling: if this bin's residual is far above mean, it is
    // a "loose" bin; using it for a small item wastes its flexibility.
    let dev = bin_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.03 * dev;
    } else {
        score += 0.01 * dev;
    }

    // Harmonic threshold: integer-division classes of post_residual by 10.
    let class = pr / 10;
    score += 0.4 * (class as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit is highly rewarded.
        score -= 60.0;
    } else {
        // Larger leftover gaps: mild quadratic penalty scaled by residual size.
        score += 0.15 * (post_residual as f64).powi(2) / bin_capacity as f64;
    }

    // If the leftover gap can exactly fit the lookahead item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_fit = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap_fit / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the next item: penalize as dead space.
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bins pressure: when many bins are open, prefer consolidating into
    // existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
    score += 0.05 * pressure * (0.5 + progress);

    // New-bin candidate handling: only attractive when existing bins fit poorly
    // (large item, tight residuals elsewhere).
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer bins whose post-residual exactly matches the next item (2-step lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        // Reward a perfect chain: item then next_item fills the bin nearly exactly.
        score -= 30.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        if slack_after_next == 0 {
            score -= 25.0; // perfect two-item packing
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Next item cannot follow here; penalize dead space relative to next item.
        score += 8.0 + (next_item_size - post_residual) as f64 * 0.15;
    }

    // Prefer tight fits: small post-residual relative to mean residual.
    score -= (mean_residual - post_residual as f64).max(-20.0).min(20.0) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize leaving awkward residual slivers that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // New-bin candidate: only attractive early in the stream or when fit is very poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 + 20.0 * progress;
    }

    // Slight preference for using more-open-bins balance: avoid fragmenting many bins.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to smallest possible future item (1..100 interface).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: reward if the next item fits into the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size as f64 <= post_residual as f64 {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't chain here; penalize leaving medium-sized gaps.
            let gap = post_residual as f64;
            if gap > 0.0 && gap < next_item_size as f64 {
                score += 6.0 * (1.0 - gap / 100.0);
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.1 * (open_bins_count as f64);
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // existing residuals are small (poor fits everywhere) or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let desperation = (cap - mean_residual) / cap; // high when open bins are full
        let item_frac = item_size as f64 / cap;
        score = cap * (0.55 + 0.5 * item_frac)
            - 30.0 * desperation
            - 10.0 * (1.0 - progress)
            + 4.0 * (fitting_bins_count as f64);
        // A new bin is great for huge items that barely fit anywhere.
        if item_frac > 0.7 {
            score -= 20.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (perfect marriage),
        // and slightly prefer bins below mean residual (rebalancing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild time-horizon modulation: late in the stream, be greedier about
    // filling bins tightly since future compensation is less likely.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / cap);

    // Tie-break: prefer more crowded bins to consolidate and close bins.
    score += 0.3 * (open_bins_count as f64).recip() * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = post_norm * (1.0 + 0.8 * progress) - 2.2 * post_norm * post_norm * (1.0 - progress);

    // Penalize dead space that cannot fit the next item (smooth logistic gate)
    let next_norm = next_item_size as f64 / cap;
    let gate = if next_item_size > 0 {
        1.0 / (1.0 + (-12.0 * (post_norm - next_norm)).exp())
    } else {
        0.0
    };
    let dead_penalty = 6.0 * gate * post_norm * (1.0 - progress);

    // Reward tight fits: small post_residual relative to item size
    let tightness = -3.0 * item_norm * (1.0 - post_norm);

    // Last-chance bin bonus when few fitting bins
    let last_chance = if fitting_bins_count <= 1 { -4.0 } else { 0.0 };

    // Mild penalty for spreading across many bins, scaled by mean residual gap
    let spread = 0.15 * open_bins_count as f64 + 0.4 * (post_norm - mean_residual / cap).abs();

    poly + dead_penalty + tightness + last_chance + spread
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity-fraction buckets
    let item_class = item_size / 10;                 // 1..=10
    let next_class = next_item_size / 10;            // 0 if last item

    // Reward tight fits: small post_residual is good, especially when
    // post_residual falls below the smallest item class (dead space).
    if post_residual < 10 {
        score -= 15.0;                               // near-perfect packing
    } else if post_residual < 20 {
        score -= 8.0;
    } else if post_residual < 30 {
        score -= 3.0;
    } else {
        // Dead space penalty grows super-linearly for large leftovers
        score += (post_residual as f64 - 30.0) * 0.35;
    }

    // Harmonic coupling: reward when next item's class matches the
    // post-residual class (integer division thresholds), i.e. the leftover
    // is likely reusable by the lookahead item.
    if next_item_size > 0 {
        let post_class = post_residual / 10;
        if post_class >= next_class && next_item_size > 0 {
            score -= 6.0;
        } else if post_residual >= next_item_size {
            score -= 2.5;
        } else {
            score += 4.0;                            // leftover can't host next item
        }
        // Modulo arithmetic on combined footprint: penalize awkward remainders
        let combined = item_size + next_item_size;
        if combined % bin_capacity != 0 && combined > bin_capacity {
            score += 1.5;
        }
        if combined == bin_capacity {
            score -= 12.0;                           // perfect pair
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening fresh bins early is cheaper; later, prefer consolidation
        score += 25.0 + 30.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0;                           // must open a bin anyway
        }
        // Big items justify a fresh bin (less fragmentation risk)
        if item_class >= 7 {
            score -= 10.0;
        }
    }

    // Mild preference for bins with larger residuals when many bins are open
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count.min(20) as f64);

    // Tie-break toward bins below mean residual (consolidate fragmented space)
    if (bin_residual as f64) < mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for the smallest
    // possible item (1..100 interface => min size 1) are pure waste.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 45.0; // unusable sliver: heavy penalty
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Tightness reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits the post residual exactly, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 8.0; // next item won't use this gap
        }
    }

    // Open-bin pressure: discourage spreading across many bins early,
    // but relax late in the stream when consolidation matters less.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 - 0.4 * progress);

    // New-bin candidate: only attractive if no open bin is a decent fit,
    // i.e. when mean residual across open bins is small relative to item.
    if bin_residual == bin_capacity {
        let mean_ok = mean_residual >= item_size as f64 * 1.15;
        if mean_ok {
            score += 70.0; // an open bin fits comfortably: keep using it
        } else {
            score += 5.0; // fresh bin is nearly as good as forced placement
        }
    }

    // Slight preference for bins already below mean residual (balance).
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect lookahead match: strongly reward exact fit of the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item still fits comfortably after this placement.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item cannot use this bin's remainder: penalize creating dead space.
    else if next_item_size > 0 {
        let dead = (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64)).max(0.0);
        score += 0.8 * dead;
    }

    // Penalize residual far below the mean residual of open bins (wasting a rich bin).
    if (post_residual as f64) < mean_residual {
        score += 0.5 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: discourage unless the current bin is a bad host.
    if bin_residual == bin_capacity {
        let bad_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
        score -= 45.0 * bad_fit * (1.0 - last_chance);
        score += 15.0 * (1.0 - bad_fit);
    }

    // Mild late-stream tightening: prefer tight fits as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no future item (min size 1..10) can realistically use.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // nearly perfect fill, strongly favor
    } else if post_residual >= 10 && post_residual < 30 {
        // mid-range leftover: mildly penalize unless next item fits it
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 8.0;
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use leftover -> leftover likely wasted
        score += (post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_frac = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_frac * (open_bins_count as f64).ln().max(1.0) * 5.0;

    // Time horizon: early in stream, be picky (penalize loose fits);
    // late in stream, prioritize closing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.10;
    score -= progress * 4.0;

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin; make it unattractive unless
        // the item is large relative to capacity or mean residuals are low.
        let item_frac = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 * 0.55
            - item_frac * 30.0
            + (mean_residual / bin_capacity as f64) * 20.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin anyway
        }
    }

    // Mean-residual coupling: when average residual is high, avoid adding to it.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    let mut score = pr * (1.0 + 0.9 * progress * progress);

    // Penalize mid-range waste (dead space) via a smooth bump: (norm_pr - 0.5)^2 style coupling.
    let bump = (norm_pr - 0.5) * (norm_pr - 0.5);
    score += cap * bump * (0.5 + 0.8 * progress);

    // Reward tight fits (small post_residual) increasingly late in the stream.
    score -= (cap - pr) * 0.15 * progress * norm_pr;

    // Last-chance bonus: strongly favor using a bin when it is the only fitting one.
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward bins whose post_residual fits the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty when bin residual deviates from mean residual across open bins.
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Encourage consolidation when many bins are open.
    score += 0.3 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: smooth penalty unless current bins are nearly unusable.
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - mean_residual / cap;
        score += 30.0 - 25.0 * avg_tightness * avg_tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: perfect fits and residues that pair
    // with common item sizes (10..80 multiples / complements of 100) are gold.
    let pr = post_residual;

    // Perfect fit: huge reward.
    if pr == 0 {
        score -= 1000.0;
    }

    // Residue classes: small dead space is bad unless it exactly matches
    // a plausible next item. Reward residues in "harmonic" bands.
    let harmonic = match pr {
        0 => 3.0,
        1..=9 => -1.0,          // unusable sliver: penalize
        10..=19 => 1.0,         // fits smallest items
        20..=29 => 0.5,
        30..=49 => 0.8,         // sweet spot for mid items
        50..=69 => 0.4,
        70..=99 => -0.3,        // large residue: wasteful-ish but flexible
        _ => 0.0,
    };
    score -= harmonic * 10.0;

    // Modulo-10 harmonic bonus: residues divisible by 10 pair well with
    // integer item sizes drawn from 10..80 grids.
    if pr % 10 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 120.0;
        } else if next_item_size <= pr {
            // fits but not perfectly: mild reward scaled by tightness
            let tight = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - tight / 50.0).max(0.0);
        } else {
            // next item cannot use this residue: penalize large residues
            score += (next_item_size - pr) as f64 * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Early stream: be more willing to keep bins open (fewer bins matter later).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 8.0;

    // Prefer bins below mean residual (balance load, keep big holes open).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // New-bin candidate (empty bin): penalize so it is only chosen when
    // open bins have terrible residues; scale with number of open bins.
    if bin_residual == bin_capacity {
        score += 40.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any future item
    // (minimum item size ~1, but practically small gaps < ~10 are near-useless)
    // are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 5.0;
    }

    // Reward tight fits: post_residual close to 0 but usable.
    if post_residual == 0 {
        score -= 80.0; // perfect fit
    } else if post_residual <= 20 {
        score -= 25.0; // small usable gap is good
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling
    // existing bins (penalize the new-bin candidate implicitly via residual).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64) * 1.5 * (0.5 + progress);

    // New-bin candidate handling: only attractive when open bins are nearly full
    // on average (poor fits everywhere).
    if bin_residual == bin_capacity {
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        // If open bins are mostly full, opening a new bin is fine; otherwise penalize.
        if mean_tightness < 0.6 {
            score += 70.0 * (0.6 - mean_tightness) * 5.0;
        } else {
            score -= 10.0 * (mean_tightness - 0.6);
        }
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual > next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += 15.0; // next item won't fit -> dead space likely
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (fill emptier bins
    // less when mean residual is small — consolidate).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() <= 3.0 {
            score -= 40.0; // chain fit: next item exactly fills this bin
        } else if next <= post_residual as f64 {
            score -= 5.0;  // next item can also go here
            // bonus for tight chain
            let chain_left = post_residual as f64 - next;
            if chain_left <= 10.0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; penalize leaving awkward residual
            score += 8.0;
            if post_residual < 10 {
                score += 15.0; // dead space that likely can't fit future items (min size 1..100, small slivers)
            }
        }
    }

    // Compare residual against mean residual across open bins.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalty for wasting a large bin on a small item when many bins are open.
    let tightness = item_size as f64 / bin_residual as f64;
    if tightness < 0.3 {
        score += 10.0;
    }

    // Late in the stream, be more conservative: prefer closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful for future items
    // (items are 1..=100, so residual < ~10 is nearly dead).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 20.0 * next_fit;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Post-residual can't hold the next item anyway: mild penalty for wasting space.
        score += 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when the fit
    // in existing bins is poor. Penalize opening a new bin mildly, more so when
    // many bins are already open (consolidation pressure).
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if the current item is large relative to mean residual, opening
        // a fresh bin may be wise (avoid fragmenting well-packed bins).
        if item_size as f64 > mean_residual {
            score -= 30.0;
        }
    }

    // Time horizon: early in the stream, be more conservative (favor packing
    // into existing bins); later, allow more freedom.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    // Prefer bins whose residual is close to the mean (balanced packing),
    // slightly rewarding bins below mean residual (denser bins).
    score -= 3.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling: weight grows with progress^2 and post_residual^2
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;
    let coupling = progress * progress * norm_pr * norm_pr * 60.0;
    score += coupling;

    // Reward tight fits (small post_residual), more strongly late in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 40.0 * progress);

    // Penalize dead space that cannot fit the next item (smooth logistic gate)
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).max(0.0);
        let gate = 1.0 - 1.0 / (1.0 + (-gap as f64 / 8.0).exp());
        score -= gate * (next_item_size as f64 / bin_capacity as f64) * 25.0;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 * (0.5 + progress);
    }

    // Mild pressure toward consolidating into fewer bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Deviation from mean residual: prefer bins whose residual stays near the mean
    score += ((pr - mean_residual) / bin_capacity as f64).abs() * 8.0;

    // New-bin candidate: penalize slightly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 12.0 + 30.0 * progress * (1.0 - progress) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of 10, or small enough to matter) are rewarded.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap;

    // Integer-division threshold: leftover <= 10 is perfect closure.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual % 10 == 0 {
        score -= 8.0; // leftover is a "harmonic" multiple of 10 -> likely reusable
    }

    // Modulo coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward tight lookahead fit (small slack after hypothetical next item)
            let second_slack = post_residual - next_item_size;
            score -= (second_slack as f64) * 0.6;
            if second_slack == 0 {
                score -= 20.0;
            }
        } else {
            // leftover too small for next item: dead-space penalty scaled by how close it is
            let deadness = 1.0 - (next_item_size - post_residual) as f64 / cap;
            score += deadness * 6.0;
        }
    }

    // Penalize leaving a large fraction of capacity unused, superlinear.
    score += frac * frac * 30.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when open bins are crowded or
    // this is a fresh stream start; otherwise opening bins is wasteful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
        score = cap - 12.0 - progress * 5.0 - crowded.min(10.0);
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 10.0; // big item coming: fresh bin is valuable
        }
    }

    // Mean-residual steering: if average leftover across bins is already large,
    // discourage adding more slack to any bin.
    score += (mean_residual - post).max(0.0) * 0.15;

    // Mild preference to fill emptier bins first when many bins are open.
    score += (open_bins_count as f64) * (bin_residual as f64 / cap) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are nearly unusable
    // (min item size is 10 in the canonical stream); penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity (wasted fraction penalty).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Reward bins whose residual was already small (compacting full bins).
    let pre_frac = bin_residual as f64 / bin_capacity as f64;
    score -= 15.0 * pre_frac * pre_frac;

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else if post_residual > 0 {
            // next item cannot use the leftover: dead space likely
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, mild encouragement to fill existing bins.
    score += 1.5 * open_bins_count as f64 * waste_frac;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0 + 2.0 * open_bins_count as f64;
        // But if the item is large, a fresh bin gives a clean large residual.
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= 45.0 * large_item;
        // If the next item is also large, a fresh bin is even better.
        if next_item_size >= 50 {
            score -= 15.0;
        }
        // If this is the only fitting option anyway, drop the new-bin tax.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild stream-progression calibration: later in the stream, tighten up
    // (favor exact fits even more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - waste_frac);

    // Mean-residual coupling: if open bins are already quite full on average,
    // prefer bins close to that mean (keeps residuals uniform and usable).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + 20.0 * progress;
    }

    // If the next item also fits in the leftover, it's a good chain but not perfect.
    if next_item_size > 0 && next_item_size < post_residual {
        let slack = (post_residual - next_item_size) as f64;
        // Small slack after next placement is great; large slack is dead space.
        score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        score += 0.3 * slack;
    }

    // Penalize creating residual too small for typical future items (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Compare against mean residual: prefer bins with below-mean residual (tighter fill).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // New-bin candidate (empty bin): only attractive when few bins fit the item
    // or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 40.0;
        let scarcity = if fitting_bins_count == 0 { 50.0 } else { 10.0 / fitting_bins_count as f64 };
        score = 100.0 - large_item_bonus - scarcity + 0.2 * open_bins_count as f64;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post-residual strongly favored (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; penalize wasting residuals that could have held it.
        if bin_residual >= next_item_size {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && fitting_bins_count > 0 {
            // discourage opening a new bin when alternatives exist, unless residuals are fragmented
            let frag = mean_residual / bin_capacity as f64;
            score += 15.0 * (1.0 - frag);
        } else {
            score -= 20.0; // no alternative: open a bin
        }
    }

    // Global state coupling: many open bins -> prefer consolidating into existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.35 * (1.0 - progress);

    // Prefer bins below mean residual slightly (balance residuals for future flexibility).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Late in stream: be greedy, minimize post residual harder.
    score *= 1.0 + 0.5 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: penalize leftover residual, with smooth non-linear shaping
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Late in the stream, small residuals become dead space -> penalize more.
    let pr_norm = pr / cap;                       // 0..1 normalized post residual
    let poly = pr_norm * pr_norm * (1.0 - pr_norm); // bump peaking mid-residual
    score += 18.0 * poly * (0.35 + 0.65 * progress);

    // Reward tight fits: subtract sharply as post_residual approaches 0
    score -= 12.0 * (1.0 - pr_norm).powi(3) * (0.5 + 0.5 * progress);

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 && next_item_size as f64 <= pr {
        let fit_tightness = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 8.0 * fit_tightness * fit_tightness;
    }
    // Penalize if post_residual is small but next item cannot use it (dead space trap)
    if next_item_size > 0 && next_item_size as f64 > pr && pr > 0.0 {
        let unusable = (pr / next_item_size as f64).min(1.0);
        score += 6.0 * (1.0 - unusable) * (0.4 + 0.6 * progress);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild pressure to consolidate into existing bins when many are open
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // Prefer bins whose residual is close to the mean (balanced packing)
    score += 0.3 * (mean_residual - pr).abs();

    // New-bin candidate: make it slightly unattractive unless residuals are hopeless
    if bin_residual == bin_capacity {
        score += 4.0 + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot" of capacity it falls into
    let quarter = bin_capacity / 4; // 25
    let post_class = post_residual / quarter; // 0..4
    let next_class = next_item_size / quarter;

    // Reward exact harmonic matches: post_residual fits next item's class nicely
    if next_item_size > 0 && post_residual >= next_item_size {
        // next item fits after this one: strong reward, scaled by how snugly
        let snug = (post_residual - next_item_size) as f64;
        score -= 18.0 - snug * 0.12;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // dead space for the lookahead: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.35;
    }

    // Reward small post_residual (tight fit) with non-linear squash
    let tight = (post_residual as f64 / bin_capacity as f64).powi(3);
    score -= (1.0 - tight) * 6.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when open bins can fit, more so early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64 / (1.0 + mean_residual / 50.0)).sqrt();
        score += 20.0 + open_pressure * 10.0 * (1.0 - progress * 0.5);
    }

    // Harmonic class penalty: residuals in awkward classes (just above item sizes) get pushed
    let mod_pen = (post_residual % quarter) as f64;
    if post_residual > 0 {
        score += mod_pen * 0.05;
    }

    // Prefer bins whose residual is close to mean (keep balance)
    score += ((post_residual as f64 - mean_residual).abs()) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable dead space
    // (smallest item is >= 1, but tiny gaps below 10 rarely serve future items well).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Gaps that can still host the lookahead item are valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // This bin could take the next item but placing current item breaks that.
        score += 6.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading into new bins,
    // encourage filling existing ones; few open bins -> consolidation is cheap.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= open_pressure * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: penalize bins far below mean residual (wasteful picks
    // when tighter options exist), reward bins near/below mean (good fill targets).
    score += 0.5 * (mean_residual - post_residual as f64).abs() / bin_capacity as f64 * 10.0;

    // New-bin candidate: only attractive when no open bin fits well or open bins
    // are nearly full. Penalize opening a new bin by default.
    if bin_residual == bin_capacity {
        score += 20.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing else fits; new bin is necessary
        }
        if open_bins_count == 0 {
            score -= 30.0; // no bins at all
        }
        if mean_residual < 10.0 && open_bins_count > 0 {
            score -= 18.0; // existing bins nearly exhausted
        }
    }

    // Late in the stream, prefer closing bins tightly (less leftover waste overall).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly or near-exactly -> strong reward
            let slack = (post_residual - next_item_size) as f64;
            if slack == 0.0 {
                score -= 500.0;
            } else {
                score -= 60.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // next item won't fit here; penalize proportionally to leftover dead space
            score += 0.5 * post_residual as f64;
        }
    }

    // Compare against mean residual: bins with residual near mean are normal;
    // prefer bins whose residual is small (tight fit) relative to mean.
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = resid_f / mean_residual;
        if rel < 1.0 {
            score -= 20.0 * (1.0 - rel); // tighter-than-average bin favored
        } else {
            score += 10.0 * (rel - 1.0); // looser-than-average bin penalized
        }
    }

    // Last chance bin: avoid opening a new bin if this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // bin would leave very awkward dead space.
    if bin_residual == bin_capacity {
        // Empty bin baseline: slightly worse than a decent existing fit,
        // better than a terrible fit.
        score = bin_capacity as f64 + 25.0;
        if next_item_size > 0 && next_item_size >= item_size && next_item_size <= bin_capacity {
            score -= 10.0; // lookahead suggests sequential pairing in fresh bin
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        }
    }

    // Late in stream: be more conservative, prefer tightening existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage consolidation into existing bins
    if open_bins_count > 4 {
        score -= 5.0 * (open_bins_count.min(20) as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already good; amplify quadratic waste penalty.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * waste_frac * waste_frac;

    // Penalize bins whose residual is far from mean residual (fragmentation control).
    score += 0.35 * (bin_residual as f64 - mean_residual).abs();

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // reward leaving usable space for the next item
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // penalize leaving space too small for the next item (dead space risk)
            score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor when this is the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is costly when few bins are open
    // or when stream is near its end; encourage reuse then.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 20.0;
        // cheaper to open new bin early when many items remain to use it
        score -= 18.0 * (1.0 - progress);
        // discourage new bin if many open bins already (consolidation)
        score += 1.5 * open_bins_count as f64;
        // if no other bin fits (fitting_bins_count==1 means only the new bin), allow it
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // if next item is large, a fresh bin is valuable
        if next_item_size >= item_size && next_item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Mild bonus for filling bins with large residual (drain the fullest bins first)
    score -= 0.15 * bin_residual as f64;

    // Late in stream, prefer tighter packing; early, be more exploratory with residual spread
    score += 4.0 * progress * waste_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;
    // non-linear coupling: residual normalized, polynomial shaping by progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress);
    let mut score = base + 60.0 * poly;
    // reward tight fits (small post_residual) more strongly late in stream
    score -= (1.0 - norm_pr).powi(3) * (30.0 + 40.0 * progress);
    // lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 25.0 * (1.0 - slack).powi(2) * (0.5 + progress);
    } else if next_item_size > 0 {
        // penalize dead space unusable by next item
        score += 10.0 * norm_pr * (1.0 - progress);
    }
    // last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0 + 25.0 * progress;
    }
    // mild penalty when many bins open and this bin is wasteful
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;
    // deviation from mean residual: prefer bins near/below mean residual
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;
    // new-bin candidate handling: neutral baseline, opened only if it wins
    if bin_residual == bin_capacity {
        score = 55.0 + 20.0 * (1.0 - progress) - 10.0 * progress;
        if next_item_size > 0 && (next_item_size as f64) >= 0.9 * cap {
            score -= 15.0;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose residual lies in "small dead-space"
    // classes are penalized, since leftover slivers waste capacity.
    let dead_class = post_residual % 20; // coarse harmonic class
    score += (dead_class as f64) * 0.6;

    // Class bins by capacity fraction of used space
    let used_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    let frac_class = (used_frac * 4.0).floor() as i32; // quarters of capacity
    score -= frac_class as f64 * 4.0;

    // Integer division threshold: post_residual bucketed by 10s
    let bucket = post_residual / 10;
    score += bucket as f64 * 1.5;

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot fit here: penalize proportionally to overflow gap
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // modulo harmony between next item and post residual
        if post_residual > 0 && (next_item_size % post_residual.max(1) == 0 || post_residual % next_item_size.max(1) == 0) {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we prefer
    // reusing open bins unless the fit is truly poor.
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.2;
        // open a new bin early when many items remain and current bins are fragmented
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count > 0 && mean_residual < 30.0 {
            score -= 25.0 * (1.0 - progress);
        }
    }

    // Mean residual alignment: prefer bins close to the mean residual (balance)
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    // Tightness bonus: how well the item fills the bin
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, min item size) are pure waste.
    if post_residual < 10 {
        score -= 40.0; // perfect or near-perfect fill is excellent
    } else if post_residual <= 20 {
        // gap only usable by tiny items; mild penalty relative to baseline
        score += 6.0;
    } else if post_residual <= 30 {
        score += 2.0;
    }

    // Exact-fit reward scaled by item size (big items closed tightly are precious).
    if post_residual == 0 {
        score -= 25.0 + (item_size as f64) * 0.3;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next < 10 {
            score -= 18.0;
        } else if gap_after_next <= 20 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // dead space for the known next item: penalize proportionally
        score += (next_item_size as f64 - post_residual as f64) * 0.15;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: prefer reusing open bins unless the fit is terrible.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; rises with number of already open bins.
        score = 55.0 + (open_bins_count as f64) * 1.5;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
        score -= (1.0 - progress) * 10.0;
        // If current fit would leave a big dead gap and a fresh bin gives a clean start, allow opening.
        if post_residual > 50 && bin_residual != bin_capacity {
            // unreachable, kept for clarity
        }
        // Large items (>= 60) in a fresh bin leave roomy 40+ residual; slight discount.
        if item_size >= 60 {
            score -= 5.0;
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, consolidation is fine.
    if bin_residual != bin_capacity {
        score += (open_bins_count as f64) * 0.05;
    }

    // Prefer bins whose residual is close to the item (tight fit) beyond raw post_residual.
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.05;

    // Mean residual coupling: if this bin is far below mean residual (very full already),
    // it is a good closer; if far above, deprioritize.
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chain: strongly favor this bin.
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next item fits, penalize leftover dead space quadratically.
            let leftover = (post_residual - next_item_size) as f64;
            score -= 20.0 - 0.35 * leftover;
        } else {
            // Next item does not fit: penalize proportionally to the mismatch.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap;
        }
    } else {
        // Last item: pure tight-fit preference.
        score += 0.0;
    }

    // Relative-to-mean coupling: prefer bins with residuals near/below the mean
    // (keeps a balanced pool, avoids hoarding one huge bin).
    score += 0.30 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += 0.15 * open_bins_count as f64;

    // Progress-scaled tightness reward: later in the stream, prioritize tight fits more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: penalize opening a new bin unless current bin leaves bad residue.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But allow a new bin if the perfect lookahead chain exists from empty.
        if next_item_size > 0 && (next_item_size as i64 - post_residual as i64).abs() <= 2 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: relative waste penalty
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Penalize small post residuals that are dead space unless they are zero
    if post_residual > 0 {
        let pr = post_residual as f64;
        let dead = if pr < 10.0 { (10.0 - pr) * 3.0 } else { 0.0 };
        score += dead;
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fit bonus
    }

    // Lookahead: if next item fits in the post residual, reward this bin
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
            // extra reward if next item fills the bin completely after placement
            if next_item_size == post_residual {
                score -= 20.0;
            }
        } else {
            // next item won't fit here; penalize leaving very large residuals that still can't host it
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: make empty bins moderately attractive only when
    // open bins are crowded or the fit is poor elsewhere
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        // base penalty so new bins are chosen only when justified
        score += 45.0;
        // more open bins with low mean residual -> opening a new bin is reasonable
        score -= crowding * 2.0;
        // early in stream, new bins are cheaper
        score -= (1.0 - progress) * 15.0;
        // if next item is large, a fresh bin is more flexible
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Global state coupling: prefer bins whose residual deviates from the mean
    // (consolidate similar residuals, keep spread manageable)
    let dev = bin_residual as f64 - mean_residual;
    score += dev.abs() * 0.3;

    // Mild preference for using more-filled bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - bin_residual as f64 / bin_capacity as f64) * progress * 10.0;

    // Slight penalty for accumulating many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let item_f = item_size as f64;
    let next_f = next_item_size as f64;

    // Base: waste after placement, softly squashed (smooth non-linear coupling)
    let mut score = pr * (1.0 + 0.5 * (pr / cap).powi(2));

    // Non-linear polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) matter more.
    let tightness = 1.0 - (pr / cap).powi(3);
    score -= 8.0 * tightness * (0.3 + 0.7 * progress) * (1.0 + item_f / cap);

    // Reward bins whose post_residual can host the lookahead item (smooth gate)
    if next_f > 0.0 {
        let gap = (pr - next_f).abs();
        let fits = ((pr - next_f) / cap).max(0.0);
        score -= 6.0 * fits * (1.0 - (gap / cap).powi(2));
        // penalize post_residual slightly too small for next item (dead space)
        score += 3.0 * ((next_f - pr) / cap).max(0.0) * (1.0 + progress);
    }

    // Last-chance bonus: sole fitting bin gets strong preference
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 * (1.0 - (pr / cap).powi(2));
    }

    // Mild penalty for spreading across too many open bins late in stream
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * (0.5 + 0.5 * progress);

    // Prefer bins with residual near mean (balance residuals, smooth)
    score += 0.02 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline, penalize mildly so good fits win,
    // but allow it when open-bin fits are terrible.
    if bin_residual == bin_capacity {
        score += 4.0 + 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 create
    // "harmonic bands" of leftover space. Residues near 0 (multiples of
    // common item sizes) are more reusable, so reward them.
    let band = (post_residual % 10) as f64;
    let band_reward = if band == 0.0 {
        -12.0
    } else if band <= 3.0 {
        -6.0
    } else if band >= 7.0 {
        3.0
    } else {
        0.0
    };
    score += band_reward;

    // Integer-division threshold on post_residual: dead space smaller than
    // the minimum plausible item size is nearly worthless.
    if post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // Tight fit reward: post_residual close to zero means near-perfect packing.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Coupling with next item: if the next item fits exactly in the post
    // residual (harmonic match), strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 18.0;
        } else if post_residual < next_item_size && post_residual >= 10 {
            // residual too small for next item: mild penalty scaled by waste
            score += (post_residual as f64) * 0.4;
        }
        // modulo harmonic: next_item_size divides residual class
        if next_item_size <= post_residual && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // the current fit is poor.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > mean_residual.max(1.0);
        if poor_fit && progress > 0.2 {
            score -= 8.0;
        } else {
            score += 15.0; // prefer reusing open bins when fit is decent
        }
    }

    // Encourage filling bins with high residual relative to the mean
    // (balance: use the emptiest bins first to consolidate).
    let residual_gap = bin_residual as f64 - mean_residual;
    score += residual_gap * 0.15;

    // Late-stream pressure: consolidate more aggressively as stream ends.
    if progress > 0.8 && post_residual > 0 {
        score += (post_residual as f64) * (progress - 0.8) * 10.0;
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (or the lookahead item) are wasted space -> heavy penalty.
    let dead_threshold = 1u32; // smallest possible item size
    if post_residual >= dead_threshold {
        // Usable gap: reward proportionally to how well it can absorb future items
        score -= 6.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0; // gap can hold the lookahead item exactly
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size * 2 {
            score -= 4.0; // near-perfect slot for lookahead
        }
    } else {
        // Perfect fill or dead gap: perfect fill is great, dead gap is bad
        if post_residual == 0 {
            score -= 25.0; // perfect fit reward
        } else {
            score += 15.0; // unusable sliver
        }
    }

    // Penalize large leftover when item is small relative to residual (wasteful placement)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 10.0;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: attractive early or when open bins are tight/fragmented,
    // unattractive when few bins are open (consolidation pressure).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        score = 45.0 - progress * 15.0 - fragmentation * 20.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count <= 1 {
            score += 30.0; // don't open a bin when an existing bin is a last chance
        }
        if next_item_size > 0 && next_item_size <= item_size {
            score += 5.0; // lookahead pairs better into a fresh bin only if large
        }
    }

    // Open-bins pressure: many open bins -> favor filling existing ones
    score += open_bins_count as f64 * 0.3;

    // Slight preference for bins below mean residual (balance load)
    if bin_residual as f64 > mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect chain: item + next item fill bin
        } else if next_item_size <= post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // next item cannot follow into this bin: penalize large leftover space
            let dead = post_residual as f64;
            if dead > 0.0 && dead < next_item_size as f64 {
                score += 0.5 * (next_item_size as f64 - dead);
            }
        }
    }

    // Compare post_residual relative to mean residual across open bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev; // prefer bins leaving less-than-average residual (tighter fits)

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when open bins exist that fit well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 60.0 + 20.0 * progress;
        if open_bins_count > 0 && next_item_size > 0 && next_item_size <= post_residual {
            new_bin_score += 25.0; // an existing bin could chain the next item too
        }
        if fitting_bins_count > 0 {
            new_bin_score += 30.0;
        }
        score = new_bin_score.max(score + 10.0);
    }

    // Slight preference for filling bins that are already mostly full.
    let fill_frac = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize large dead space, especially if it can't fit the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += post_residual as f64 * 0.5;
    }
    // Reward residuals that can still hold the lookahead item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when the item fits poorly everywhere
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count <= 1 || (bin_residual - item_size) < 20;
        if poor_fit {
            score -= 10.0;
        } else {
            score += 40.0; // discourage opening new bins when a decent fit exists
        }
    }

    // Tight fit bonus relative to capacity
    let tightness = (item_size as f64) / (bin_residual as f64);
    score -= tightness * 20.0;

    // Time horizon: late in stream, consolidate more aggressively
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> encourage filling them
    if open_bins_count > 2 && mean_residual > 20.0 {
        score += (mean_residual - post_residual as f64).abs() * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64;

    // Base: leftover space (lower is better fit)
    let mut score = pr;

    // Smooth non-linear coupling: quadratic waste penalty scaled by stream progress.
    // Late in the stream, dead space is costlier.
    let waste = pr / cap;
    score += (waste * waste) * cap * (0.25 + 0.75 * progress);

    // Reward tight fits (fit_ratio near 1.0) with a smooth cubic term.
    score -= (fit_ratio * fit_ratio * fit_ratio) * cap * 0.35;

    // Penalize bins whose residual deviates far below the mean residual
    // (hoarding space in already-loose bins is wasteful).
    let dev = (mean_residual - pr) / cap;
    score += dev * dev * cap * 0.15;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= cap * 0.8;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if the next item is slightly larger than post-residual but fits elsewhere,
    // mild penalty for blocking it.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let gap = (pr - ni) / cap;
            score -= (1.0 - gap * gap) * 6.0;
        } else if ni > pr {
            score += ((ni - pr) / cap) * cap * 0.05;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when existing fits are very poor
    // (high waste) and many bins are already open.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)).sqrt();
        score += cap * (0.55 - 0.5 * progress) * openness;
    }

    // Small smooth jitter-free regularizer against zero-score ties.
    score += (pr as f64).sqrt() * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual buckets of size 10 (capacity fractions).
    let class = post_residual / 10;
    // Penalize residuals in "awkward" harmonic classes (1..3 => 10..39 leftover, hard to fill).
    match class {
        0 => score -= 25.0,                    // perfect fit
        1 | 2 => score += 18.0,                // dead space danger zone
        3 | 4 => score += 6.0,                 // moderately awkward
        5 | 6 => score -= 4.0,                 // half-bin-ish, still reusable
        _ => score -= 8.0,                     // large residual, very reusable
    }

    // Modulo coupling: does next item divide nicely into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        // Reward if next item fits with small leftover (harmonic match).
        if slack <= 5 {
            score -= 20.0;
        } else if slack <= 15 {
            score -= 8.0;
        }
        // Reward exact harmonic class match: both multiples of 10.
        if next_item_size % 10 == 0 && post_residual % 10 == 0 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual && post_residual < 10 {
        // Post-residual too small for anything: slight penalty unless near-perfect.
        score += 3.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: make empty bins attractive only when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // If mean residual across open bins is low (fragmented), prefer opening new bin.
        score -= fragmentation * 40.0;
        // Early in stream, new bins are cheap; late, avoid spreading.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    } else {
        // Reward filling existing bins proportionally to how full they get.
        let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
        score -= fill_ratio * 12.0;
    }

    // Penalize creating residual that no typical item (>=10) can use.
    if post_residual < 10 && post_residual > 0 {
        score += 22.0;
    }

    // Mild preference for keeping number of open bins stable.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..10 band)
    // can use are pure waste. Penalize tiny non-zero leftovers heavily.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward filling large fractions of the bin (waste-rate proxy).
    let fill = (item_size as f64) / (bin_capacity as f64);
    score -= fill * 20.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // leftover can't serve next item: mild penalty scaled by how big next item is
        score += (next_item_size as f64) * 0.05;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // make new bins expensive.
    if bin_residual == bin_capacity {
        score += 30.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= open_bins_count.min(10) as f64 * 0.5;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins),
    // i.e. placing into below-average-residual bins leaves the loose space elsewhere.
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (resid_f - mean_residual) * 0.3;
    }

    // Early in stream, be pickier about dead space (long horizon to regret it);
    // late in stream, just get items packed.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.5 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but not perfectly-full waste of open slots
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // 2-step lookahead: reward bins whose post_residual matches the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect two-item packing
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            // small gaps that still allow next item are good; penalize leftover after next item
            score -= 18.0 * (1.0 - gap / bin_capacity as f64);
            score += 0.25 * gap;
        } else {
            // next item cannot fit in this residual: dead-space risk
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Relative-to-mean-residual coupling: bins with residual near mean are flexible
    let mean_diff = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * mean_diff;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: neutral-ish score so it wins only when fits are terrible
    if bin_residual == bin_capacity {
        score = 55.0 + 0.30 * item_size as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 25.0; // opening a bin that can host the next item too
        }
        if fitting_bins_count == 0 {
            score -= 70.0; // no open bin fits: must open new bin
        }
    }

    // Slight preference to fill older/more crowded bins when many bins open
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Early stream: be more tolerant of loose fits to keep flexibility
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving awkward dead space (small post-residual that likely can't
    // host a future item, but not zero). Reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 15.0;
    } else if post_residual < 25 {
        score += 8.0; // mid dead-space zone is mildly wasteful
    }

    // Lookahead: reward if the next item fits into the resulting residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // extra reward for a good next-fit too
            let nr = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * nr;
        } else {
            // next item won't fit here; mildly penalize tight fits that block it
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if fit_ratio > 0.6 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: make an empty bin attractive only when the
    // current fit is poor or open-bin residuals are already fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Empty bin baseline: slightly worse than a decent existing fit.
        score += 10.0;
        // Early in the stream, keeping bins consolidated matters less; later,
        // avoid fragmenting: make new bins costlier as stream progresses.
        score += 20.0 * progress;
        // If many open bins already exist, discourage spreading further.
        score += 2.0 * open_bins_count as f64;
        // If mean residual is large (lots of slack around), prefer existing bins.
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
        // If nothing else fits well (post_residual of a fresh bin equals item slack),
        // this stays as fallback via the base score.
    }

    // Mild preference for filling bins with larger residuals when residuals are
    // homogeneous (keeps remaining bins uniform for future items).
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear reward for tight fits (small post_residual), stronger as stream progresses.
    let pr = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - pr) * (1.0 - pr) * 12.0 * (0.5 + progress);

    // Reward bins whose residual is close to item_size (perfect fit coupling).
    let gap = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= (-4.0 * gap * gap).exp() * 8.0;

    // Lookahead: if next item fits in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        let next_fits = (post_residual >= next_item_size) as i32 as f64;
        score -= next_fits * 6.0 * (1.0 - progress * 0.5);
        // Penalize leaving exactly-ish space that neither wastes nor helps.
        let nr = next_item_size as f64;
        if nr > 0.0 {
            let d = (post_residual as f64 - nr) / bin_capacity as f64;
            score += d.abs() * 4.0;
        }
    }

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New empty bin candidate: penalize mildly; allow only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowded = (mean_residual / bin_capacity as f64).max(0.0);
        let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (0.4 + 0.6 * progress);
        score += 25.0 - crowded * 30.0 * pressure;
    }

    // Penalize bins deviating from mean residual (prefer balanced residual pool).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).powi(2) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small unusable" classes (0..10) are nearly perfect fits -> reward heavily.
    let post = post_residual;
    let class = post / 10; // integer division threshold classes: 0..10
    match class {
        0 => score -= 25.0,                       // near-perfect fit
        1 => score -= 10.0,                       // good fit
        2 => score -= 4.0,                        // decent
        3 => score -= 1.0,
        _ => {}                                   // large leftover: neutral
    }

    // Modulo coupling: leftover compatible with next item size gets a bonus.
    if next_item_size > 0 {
        let gap = post as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 30.0; // next item fills this bin exactly: excellent
        } else if gap > 0 && (gap as u32) < 10 {
            score -= 12.0; // next item leaves near-perfect class
        } else if gap < 0 && ((-gap) as u32) <= 5 {
            score -= 6.0; // close miss, still attractive
        } else if gap > 0 {
            score -= 8.0 / (1.0 + (gap as f64).ln().max(0.0)); // decaying reward
        } else {
            score += 8.0; // next item cannot use this bin's leftover
        }
        // Harmonic residue: leftover % next_item_size small => splittable later
        if next_item_size > 0 && post >= next_item_size {
            let r = post % next_item_size;
            if r <= 2 { score -= 5.0; }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize creating dead space relative to mean residual of open bins.
    if post as f64 > mean_residual + 15.0 {
        score += (post as f64 - mean_residual) * 0.15;
    }

    // Late in stream: prefer tight packing, discourage new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few fitting bins or big item.
        score += 30.0 + 40.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else if progress > 0.7 {
        score -= 3.0; // consolidate into open bins late
    }

    // Mild preference for bins already well filled.
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold even the
    // smallest plausible item are wasted space. Penalize them heavily.
    let dead_zone = 10.0_f64.min(next_item_size as f64);
    if (post_residual as f64) < dead_zone && post_residual > 0 {
        score += (dead_zone - post_residual as f64) * 12.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Penalize leaving a gap that is just barely unusable for the next item
    // (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward keeping residual aligned with typical future needs.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; discourage opening new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to how many bins are open.
        score += 25.0 + open_bins_count as f64 * 6.0;
        // But if nothing else fits well (this is the only fitting option),
        // soften so a new bin is opened when necessary.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it before opening a new bin.
        score -= 20.0;
    }

    // Mild penalty if this bin's residual is far above the mean (it is a
    // "spare" bin better saved for awkward items).
    let dev = bin_residual as f64 - mean_residual;
    if dev > 20.0 {
        score += (dev - 20.0) * 0.3;
    }

    // Early in the stream, be slightly more willing to open bins for
    // flexibility; later, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (bin_residual == bin_capacity) as i32 as f64 * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual gets a strong discount.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // 2-step lookahead: if the next item exactly fills the post residual,
    // this is a perfect chain placement — reward heavily.
    if next_item_size > 0 && post_residual > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
        // Penalize if next item cannot fit in post residual (dead space ahead)
        if next_item_size > post_residual {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: bins with more free space than average
    // are better targets for large items; less free space for small items.
    let rel = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score -= 12.0 * rel * (item_size as f64 / bin_capacity as f64);

    // Penalize leaving large unusable gaps (>40) that few items can fill.
    if post_residual > 40 {
        score += 0.5 * (post_residual - 40) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when item is large and no tight fit exists.
    if bin_residual == bin_capacity {
        let large = (item_size as f64 / bin_capacity as f64) - 0.5;
        score += 18.0 - 40.0 * large.max(0.0);
        // Early in stream, be more willing to open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Mild pressure to keep open-bin count from exploding.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += 0.35 * (nxt - post_residual as f64);
        } else {
            // bonus if lookahead fits in the remaining space
            score -= 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: penalize mildly so it only wins when fits are bad,
    // but relax penalty late in the stream (less future to amortize).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 4.0 + 4.0 * (1.0 - progress);
    }

    // Prefer filling bins whose residual is below the mean (consolidate small gaps).
    if open_bins_count > 1 {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.08 * dev;
    }

    // Early stream: encourage keeping residuals large/flexible (soft penalty on tiny leftovers).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 10 {
        score += 3.0 * (1.0 - progress);
    }

    // Mild pressure against accumulating many open bins with large residuals.
    score += 0.02 * open_bins_count as f64 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual fraction
    let r = post / cap;

    // Base: prefer small post-residual (tight fit), non-linearly
    let mut score = post as f64;

    // Non-linear polynomial coupling of residual with stream progress:
    // early on, small residuals matter less; late, avoid dead space strongly
    let tightness = (1.0 - r) * (1.0 - r); // 0 = empty fill, 1 = perfect fit
    score -= 30.0 * tightness * (0.5 + progress);

    // Quadratic penalty on residual, modulated by progress (waste aversion grows)
    score += 0.15 * r * r * cap * (1.0 + progress);

    // Reward filling bins when many bins are open (consolidation pressure)
    let open_norm = (open_bins_count as f64).ln1p();
    score -= 8.0 * (item_size as f64 / cap) * (1.0 + 0.5 * open_norm / (open_norm + 5.0));

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let fit_next = if post >= nxt { 1.0 } else { 0.0 };
        // smooth sigmoid-like reward for ability to fit next item
        let s = 1.0 / (1.0 + (gap / cap).exp() * 10.0);
        score -= 12.0 * fit_next * s * (0.5 + progress);
        // penalize leaving exactly awkward gaps slightly larger than next item
        score += 5.0 * (r - nxt / cap).abs() * progress;
    }

    // Deviation from mean residual: prefer bins whose residual diverges less chaotically
    score += 0.05 * (post - mean_residual).abs() * (0.5 + 0.5 * progress);

    // New-bin candidate handling: empty bin gets moderate default score,
    // only chosen when no good fit exists (large residuals elsewhere)
    if bin_residual == bin_capacity {
        score = cap * 0.9 + 10.0 * (1.0 - progress) - 5.0 * (fitting_bins_count as f64).recip();
        if fitting_bins_count == 0 {
            score = 0.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the residual: integer division thresholds
    let post = post_residual as u32;
    let class = post / 10; // classes 0..10 of dead space
    // Penalize mid-size dead space (hardest to fill), reward near-full and exact fits
    let class_penalty = match class {
        0 => -8.0,                      // perfect fit
        1 => -4.0,                      // tiny leftover, likely fillable
        2 => -2.0,
        3 | 4 => 3.0,                   // awkward mid-range dead space
        5 | 6 => 2.0,
        7 | 8 => -1.0,                  // large residual still flexible
        _ => 0.0,
    };
    score += class_penalty;

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = (bin_residual - item_size) as f64; // = post_residual for new bin
        score = cap - 10.0; // baseline: worse than a good fit, better than terrible fit
        // Opening new bin is good if it can also host the next item well
        if next_item_size > 0 && next_item_size <= post {
            score -= 6.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        let _ = fit_quality;
    }

    // Lookahead: reward leaving room exactly for next item (harmonic coupling)
    if next_item_size > 0 {
        if post == next_item_size {
            score -= 10.0;
        } else if post > next_item_size && post - next_item_size <= 10 {
            score -= 5.0;
        } else if post < next_item_size && post > 0 {
            score += 2.0; // next item can't use this leftover
        }
    }

    // Many open bins: tighten, prefer filling existing ones
    if open_bins_count > 4 {
        score += 0.5 * (open_bins_count as f64 - 4.0);
    }

    // Deviation from mean residual: prefer bins below mean (tighter bins)
    score += 0.3 * ((post as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot hold the smallest
    // plausible item (<= 10) are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Tight-but-usable gaps are risky; mild penalty scaled by gap size.
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead (k=2): strongly favor bins whose post_residual exactly fits
    // the next item (two-item chain fill).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score += 15.0; // would create dead space after next item
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is truly terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity as f64 * 0.5 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones (penalize the new-bin candidate relatively more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // New-bin candidate (empty bin): discourage unless existing residuals are
    // fragmented (mean residual large relative to item) or bin is crowded.
    if bin_residual == bin_capacity {
        score += 35.0 + mean_residual * 0.2;
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 10.0;
        }
        // Early in the stream, opening bins is cheaper (future flexibility).
        score -= (1.0 - progress) * 20.0;
    } else {
        // Mild preference for tighter existing bins (best-fit flavor).
        score += (bin_residual as f64 - post_residual as f64) * 0.1;
    }

    // Coupling: when mean residual across bins is high, be pickier about
    // leaving large-ish gaps (they may be reusable elsewhere).
    if post_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual can still hold the next item: mild reward scaled by tightness
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize dead space relative to next item
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward tight fits (small post residual overall)
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Compare against mean residual: bins below mean residual are tighter, prefer them
    score += 0.3 * (mean_residual - post_residual as f64);

    // Penalize leaving very small unusable fragments
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size.min(10) {
        score += 10.0;
    }

    // New-bin candidate: only attractive when open bins are very tight
    if bin_residual == bin_capacity {
        let avg_tightness = mean_residual / bin_capacity as f64;
        score += 30.0 * (1.0 - avg_tightness);
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space that
    // cannot fit even the smallest item (1) is pure waste.
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect, dead space is tiny
    } else {
        // penalize large unusable gaps quadratically
        let gap = post_residual as f64;
        score += 0.08 * gap * gap / bin_capacity as f64;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use leftover; mild penalty scaled by mismatch
            let mismatch = (next_item_size - post_residual) as f64;
            score += 0.1 * mismatch;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin should only win when
    // existing bins are crowded or the fit is terrible.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; penalize opening bins when many are open
        // with slack available, reward when open bins are nearly full.
        score += 20.0
            + 0.5 * (open_bins_count as f64)
            - 0.3 * mean_residual
            + (step_index as f64 / total_items.max(1) as f64) * 10.0;
        // if no open bin fits well (large mean residual means slack exists),
        // opening may still be reasonable — soften penalty via mean_residual.
    } else {
        // Slight preference for bins with residual close to item size
        // (relative tightness), scaled by global slack context.
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 10.0 * tightness;
        // When mean residual across bins is high, encourage consolidation
        // into existing bins rather than spreading.
        score -= 0.05 * mean_residual;
    }

    // Time horizon: late in the stream, be more aggressive about filling
    // existing bins to avoid leftover fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual exceeds item size by a small margin
    // (best-fit style) with a non-linear nudge.
    let fit_margin = (bin_residual as i64 - item_size as i64) as f64;
    if fit_margin >= 0.0 {
        score -= 12.0 / (1.0 + fit_margin);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear coupling of post-residual with stream progress
    let curve = norm_pr * norm_pr * (1.0 + 3.0 * progress);
    score += curve * cap * 0.35;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 25.0 * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += (nx - pr) * (0.6 + 0.8 * progress);
        } else {
            // reward bins that can still host the next item
            score -= 6.0 * (1.0 - (nx / (pr + 1.0)));
        }
    }

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 + 40.0 * progress;
    }

    // Mild preference for bins below mean residual (fill emptier bins first)
    score -= 0.15 * (mean_residual - pr);

    // Slight penalty for many open bins to encourage consolidation
    score += 0.5 * (open_bins_count as f64);

    // New-bin candidate: prefer it only when it truly beats poor fits
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * progress + 0.2 * pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity divided into 5 bands.
    // Small residuals (0..10) are dead space -> penalize; mid residuals (>= next_item_size) are reusable -> reward.
    let band = post_residual / (bin_capacity / 5);
    score += (band as f64) * 6.0;

    // Perfect fit: post_residual below small-item floor is excellent.
    if post_residual < 8 {
        score -= 25.0;
    }

    // Lookahead: reward residuals that can host the next item, penalize near-misses.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else if post_residual > 0 && bin_residual >= next_item_size {
            // next item could go here only if we place current item elsewhere; slight penalty for blocking
            score += 4.0;
        }
        // Harmonic class match: residual leaves exactly a "class" chunk for next item
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 8 {
                score -= 10.0; // leaves near-dead space after next item too: great chain
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; rises with how many bins already fit the item.
        score = bin_capacity as f64 + 20.0 * (fitting_bins_count as f64);
        if open_bins_count == 0 {
            score -= 200.0; // must open first bin
        }
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 15.0; // pairing potential in a fresh bin
        }
    } else {
        // Prefer fuller bins: tie-break toward minimal post_residual relative to mean.
        score -= 0.5 * (mean_residual - post_residual as f64).max(0.0);
    }

    // Late-stream consolidation: favor filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Modulo harmonic: residuals that are multiples of common item sizes (10s) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space harshly (gaps too small for typical items)
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward using bins that are already fairly full (low residual)
    score += (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Pressure from number of open bins: prefer consolidating into existing bins
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Prefer bins below mean residual (fill emptier bins less, keep large gaps alive)
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // New-bin candidate: discourage opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * -0.3;
        // allow new bin early in stream when few bins are open
        if open_bins_count < 2 {
            score -= 12.0;
        }
        // if next item is large, a fresh bin is attractive
        if next_item_size > 50 {
            score -= 6.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect/near-perfect fits strongly
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * (1.0 - tightness * 4.0).max(-1.0) * (1.0 - tightness);

    // 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 35.0 * (1.0 - slack / 50.0).max(0.0); // good chained fit
        } else {
            // next item won't fit here; penalize wasted large residuals
            let waste = (next_item_size - post_residual) as f64;
            score += 0.25 * waste.min(40.0);
        }
    } else {
        // last item: minimize residual directly
        score += post_residual as f64;
    }

    // Relative to mean residual: prefer bins already tighter than average
    score += 0.5 * ((bin_residual as f64) - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit (post_residual large relative to capacity)
    if bin_residual == bin_capacity {
        // new bin baseline: residual after placement = capacity - item
        // penalize unless existing bins would leave big dead space
        let new_bin_post = post_residual as f64;
        score = new_bin_post + 55.0 * tightness + 10.0;
        if fitting_bins_count == 1 {
            // an open bin exists that fits; discourage new bin unless that bin is a bad fit
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size >= post_residual {
            score -= 10.0; // fresh bin can host next item too
        }
    }

    // Early stream: slightly favor consolidating into fewer bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64).sqrt() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that next item cannot use
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        } else {
            score -= 8.0 * (next_item_size as f64 / post_residual as f64).min(1.0);
        }
    }

    // Last-chance bin: strong reward to use it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Discard very small post residuals that waste capacity
    if post_residual < 10 {
        score -= 5.0; // near-perfect fill is actually good
    } else if post_residual > bin_capacity as f64 * 0.5 {
        score += 6.0; // keeping large residual is fine, mild penalty for wasteful low fill
    }

    // Time horizon: later in the stream, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: favor consolidation
    score += 2.0 * (open_bins_count as f64).sqrt() * (post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: bins below mean residual are already tight; prefer them
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Brand-new bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score += desperation + 10.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin can host next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post residual); later, dead space penalized more
    let poly = norm_post * norm_post * (1.0 + progress) + norm_post * progress * progress;
    score += 30.0 * poly;

    // Reward near-perfect fits with a smooth quartic term
    let fit = 1.0 - norm_post;
    score -= 40.0 * fit * fit * fit * fit;

    // Lookahead coupling: if next item fits the post residual, reward smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let slack = pr - ns;
        if slack >= 0.0 {
            let q = 1.0 - (slack / cap);
            score -= 15.0 * q * q;
        } else {
            let miss = (-slack / cap).min(1.0);
            score += 12.0 * miss * miss;
        }
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_post * norm_post);
    }

    // Mean residual interaction: penalize bins far from the mean (wasted spread)
    let dev = (pr - mean_residual).abs() / cap;
    score += 10.0 * dev * dev * (0.5 + progress);

    // New-bin candidate shaping: empty bin gets a mild penalty unless residuals are hopeless
    if bin_residual == bin_capacity {
        let hope = (mean_residual / cap).max(0.0).min(1.0);
        score += 5.0 + 20.0 * hope * hope;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "small residue" class (mod 10) are more likely to be filled exactly.
    let res_class = post_residual % 10;
    score -= 4.0 * (10 - res_class) as f64; // reward residues close to next multiple of 10

    // Perfect fit is golden.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight fit: leftover smaller than the smallest plausible item (~10).
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0;
    }

    // Penalize "awkward" dead space: residual in (10, 20) is hard to fill
    // with items drawn from 1..100 unknown distribution.
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Harmonic fraction coupling: how close post_residual is to a capacity
    // fraction (1/2, 1/3) — those leftovers pair well with mid-size items.
    let half = cap / 2.0;
    let third = cap / 3.0;
    let pr = post_residual as f64;
    score -= 3.0 * (1.0 - (pr - half).abs() / cap);
    score -= 2.0 * (1.0 - (pr - third).abs() / cap);

    // Lookahead: if next item fits exactly in post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here anyway; mild penalty for wasting space
            score += 2.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin is a decent fit, or the stream is early and bins are scarce.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of a fresh bin: its full residual.
        // Discourage early hoarding of bins; encourage when open bins are full-ish.
        let avg_fill = 1.0 - mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0; // inherent cost
        score -= 20.0 * avg_fill * (0.5 + progress); // open new bin when existing ones are loaded
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // If a big item just about fits an existing bin, prefer the existing bin.
        if item_size as f64 / cap > 0.6 && fitting_bins_count > 0 {
            score += 15.0;
        }
    } else {
        // Prefer packing into bins that are already below-average residual
        // (best-fit flavor with mean coupling).
        if (pr) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.5;
        }
        // Slight preference for bins that keep mean residual harmonic
        // (multiple of 5 classes align well with item sizes 10..80).
        if post_residual % 5 == 0 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // A post_residual below the minimum item size (1) can't happen, but gaps
    // too small for typical items are wasted. Use a quadratic-ish penalty on
    // small post_residual values that are still nonzero.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // Small nonzero gaps are the worst: they trap capacity.
        if post_residual < 10 {
            score += 60.0 * (10.0 - pr) / 10.0;
        } else if post_residual < 25 {
            score += 25.0 * (25.0 - pr) / 25.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward gaps that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // Bonus if it fits the next item snugly.
            let snug = (post_residual - next_item_size) as f64;
            if snug < 10.0 {
                score -= 10.0 * (10.0 - snug) / 10.0;
            }
        } else {
            // Gap can't fit next item: mild penalty, worse if gap is tiny.
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones
    // (penalize the new-bin option and discourage spreading).
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and remaining stream.
        let progress = step_index as f64 / (total_items.max(2) as f64);
        score += 20.0 + 10.0 * open_pressure + 25.0 * (1.0 - progress);
    } else {
        // Favor bins whose residual is below mean residual (i.e., fuller bins).
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Slight preference for tight fits generally.
    score += 0.1 * pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of next item into post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect follow-up fill
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // tighter follow-up fit is better
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow; penalize proportionally to wasted potential
            let miss = (next_item_size - post_residual) as f64;
            score += 0.35 * miss;
        }
    }

    // Relative residual vs mean residual: prefer bins tighter than average
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize leaving large unusable gaps (dead space below minimum item size 1..100 heuristic)
    if post_residual > 0 && next_item_size > post_residual {
        score += 0.1 * post_residual as f64;
    }

    // Late in stream: consolidate into open bins more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: prefer filling existing ones rather than spreading
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate should only win when current fit is terrible
    if bin_residual == bin_capacity {
        score += 55.0 + 0.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fill is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space that no future item (>=1) could use well.
        let frag = (post_residual as f64 / bin_capacity as f64).powi(2);
        score += 60.0 * frag;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - chain_fit / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize proportionally to wasted residual.
            score += 0.5 * post_residual as f64;
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing residuals are large
    // and the item is big (likely to leave a useful residual elsewhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_waste = mean_residual / open_bins_count.max(1) as f64;
        // Prefer new bin when open bins are fragmented and item is large.
        let open_penalty = (avg_waste / bin_capacity as f64) * 150.0;
        let big_item_bonus = (item_size as f64 / 100.0) * 80.0;
        let late_bonus = progress * 40.0;
        score += 30.0 - open_penalty - big_item_bonus - late_bonus;
        // Exact-fit guarantee for the new bin: never open a new bin for a tiny item.
        if item_size <= 25 {
            score += 400.0;
        }
    } else {
        // Mild preference for fuller bins among open bins (best-fit bias).
        score -= 0.3 * (bin_capacity - bin_residual) as f64;
    }

    // Global state coupling: many open bins -> consolidate; few open bins -> spreading is cheap.
    let crowd = (open_bins_count as f64).ln().max(0.0);
    score += crowd * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Small deterministic tie-breaker favoring earlier bins.
    score += (step_index % 7) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear penalty on wasted residual (quadratic coupling)
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Reward tight fits: post_residual near zero gets strong discount
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tight * tight * tight;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 30.0 * (1.0 - slack * slack);
        } else {
            // next item cannot use the leftover: mild penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 15.0 * gap;
        }
    }

    // Last chance: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: discourage opening new bins early / when mean residual is high
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * mean_residual / bin_capacity as f64 + 15.0 * progress;
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Smooth coupling with open bins count: many open bins -> prefer consolidating
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Progress-scaled residual preference: later in stream, tighter packing matters more
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into a
    // "usable" residue class (small or large enough to host common items)
    // are preferred. Class = post_residual mod 10 (item granularity floor).
    let pr = post_residual;
    let class = (pr % 10) as f64;
    // Penalize awkward leftovers: mid-range residues (3..7) are dead space.
    if pr > 0 && class >= 3.0 && class <= 7.0 {
        score += 6.0 - class.abs(4.0 - class);
        score += (8.0 - class) * 2.0;
    }
    // Reward harmonic alignment: post_residual divisible by common item sizes
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 4.0; }
        else if pr % 20 == 0 { score -= 10.0; }
        else if pr % 25 == 0 { score -= 6.0; }
    }

    // Perfect fit / near-perfect fit
    if pr == 0 { score -= 40.0; }
    else if pr <= 5 { score -= 25.0; }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly favor this bin (chained harmonic match).
    if next_item_size > 0 {
        if post_residual == next_item_size { score -= 30.0; }
        else if post_residual >= next_item_size && post_residual - next_item_size <= 5 {
            score -= 18.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // leftover can't host next item: mild penalty scaled by waste
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // integer-division threshold: post_residual / next_item_size
        if next_item_size > 0 && post_residual / next_item_size.max(1) >= 2 {
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Tightness reward: fraction of bin filled by this placement.
    let fill = item_size as f64 / cap;
    score -= fill * 10.0;

    // Prefer reusing bins with small mean residual (consolidate waste).
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    // New-bin candidate logic: brand-new empty bin should only win when
    // open bins are heavily fragmented (large mean residual) or item is big.
    if bin_residual == bin_capacity {
        // baseline score = full capacity residual; adjust
        score -= 5.0;
        if open_bins_count > 0 {
            // penalize new bin when existing bins fit well
            score += mean_residual * 0.10 + open_bins_count as f64 * 0.5;
            if item_size > 70 { score -= 15.0; } // big items: fresh bin ok
        } else {
            score -= 50.0; // first bin always
        }
    }

    // Late-stream consolidation: as stream progresses, favor closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (100.0 - post_residual as f64) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // minimum item size (1..=9, or smaller than the next item) are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer reuse;
    // few open bins -> allow opening a new bin when the fit is poor.
    let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * 30.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive if current fit is bad and next item
    // could pair better; otherwise penalize opening new bins.
    if bin_residual == bin_capacity {
        if post_residual > 0 && post_residual < 10 {
            score += 80.0; // never open a bin that creates dead space immediately
        } else {
            score += 15.0 + pressure;
            if next_item_size > 0 && next_item_size as f64 >= post_residual as f64 {
                score -= 20.0; // new bin sized well for the upcoming item
            }
        }
    }

    // Early in the stream, be more willing to start fresh bins for good fits.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 5.0 * (bin_residual == bin_capacity) as i32 as f64;

    // Slight nudge toward bins whose residual is closest to the item.
    score += 0.1 * ((bin_residual - item_size) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (post_residual close to 0).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual <= 10 {
        score -= 8.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // perfect chain match
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize wasted residual relative to next item size.
            let waste = (post_residual as f64 - next_item_size as f64).min(post_residual as f64);
            score += 0.5 * waste;
        }
    }

    // Compare residual to mean residual across open bins: prefer using bins with larger residual.
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor placing here to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize creating large unusable dead space (> 10) when item is small relative to bin.
    if post_residual > 10 && item_size < bin_residual / 2 {
        score += 3.0;
    }

    // Early in the stream, be slightly more willing to open new bins for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base high score, discounted for large items early on.
        score = bin_capacity as f64 - 0.5 * item_size as f64 - 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Tie-breaking: prefer bins with more residual used so far (denser bins).
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio;

    // Penalize creating awkward dead space: post_residual small but nonzero is fine,
    // very large post_residual means wasted space unless the bin was fresh.
    if post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 6.0 * waste * (1.0 - fit_ratio);
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            // Mild penalty if leftover is much larger than next item (fragmentation risk).
            let gap = post_residual - next_item_size;
            score += 0.05 * gap as f64;
        } else {
            // Next item won't fit here; slight penalty for blocking.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer using existing bins over opening new ones when many bins are open
    // and this bin's residual is below the mean (consolidation).
    let t = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual < bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0 * (1.0 - t);
        } else {
            score += 2.0 * (1.0 - t);
        }
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = 1.0 / (open_bins_count as f64 + 1.0);
        // Early in the stream or many open bins -> discourage new bins.
        score += 18.0 * (1.0 - pressure) * (0.5 + 0.5 * (1.0 - t));
        // But late in the stream, a fresh bin is less costly.
        score -= 5.0 * t;
    }

    // Slight preference for bins with residuals close to item size (harmonic fit).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.08 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;
    // smooth polynomial coupling of residual with stream progress
    let mut score = r * (1.0 + 0.5 * progress) - 20.0 * (rn * (1.0 - rn)) * (1.0 + progress);
    // penalize near-full dead space that wastes capacity
    if rn < 0.1 {
        score += 15.0 * (0.1 - rn);
    }
    // reward tight fits (small post residual) more strongly later in stream
    score -= (item_size as f64 / cap) * 10.0 * progress;
    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // lookahead: if next item fits in post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= r {
        score -= 8.0;
    }
    // mild penalty for opening new bins when many fit already
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (fitting_bins_count as f64);
    }
    score += 0.05 * (mean_residual - r);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into coarse bands
    // via integer division thresholds. Small post_residual = tight fit = reward.
    let pr = post_residual as f64;
    let tight_band = post_residual / 10; // 0..10 => class 0 (best), etc.
    score -= (10 - tight_band.min(10)) as f64 * 4.0;

    // Exact-fill bonus: post_residual == 0 is a perfect packing.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic pairing: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect lookahead pairing
        } else if next_item_size < post_residual {
            let next_left = post_residual - next_item_size;
            // reward small leftovers after the lookahead item
            let band = next_left / 10;
            score -= (10 - band.min(10)) as f64 * 2.5;
            // modulo harmonic: leftover divisible by common sizes is reusable
            if next_left % 10 == 0 || next_left % 20 == 0 || next_left % 25 == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot fit here: penalize by how much it overshoots
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Dead-space penalty: post_residual too small for the minimum item (1..100
    // interface; treat < 5 as near-dead but still usable) — scale with progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 5 {
        score += 15.0 * (0.5 + progress);
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin wastes its full capacity
    // unless current bins are crowded or the fit is poor.
    if bin_residual == bin_capacity {
        // base cost of a new bin
        score = cap * 0.6;
        // crowdedness: many open bins with large mean residual -> reuse is fine
        let crowded = (mean_residual / cap) * (open_bins_count as f64).sqrt();
        score -= crowded * 8.0;
        // late in stream, prefer consolidating into open bins
        score -= progress * 20.0;
        // if no open bin fits well (large item), new bin is more acceptable
        if item_size > 60 {
            score -= 15.0;
        }
    }

    // Fractional capacity coupling: reward placements leaving residuals in
    // "friendly" harmonic classes (multiples of 10, 25, 50 are composable).
    if post_residual % 10 == 0 { score -= 6.0; }
    if post_residual % 25 == 0 { score -= 4.0; }
    if post_residual % 50 == 0 { score -= 4.0; }

    // Mean-residual anchoring: keep global residual mass balanced.
    score += (pr - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals below the minimum item size
    // (1..=9 here, but generally small gaps) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 500.0;
    }

    // Penalize residuals that cannot fit the lookahead item but could have
    // fit it with a better choice elsewhere.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }
    // Reward residuals that exactly fit the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless the fit is terrible (creates dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
        if post_residual < 10 && post_residual > 0 {
            score += 300.0; // but not if it creates dead space
        }
    }

    // Open-bins pressure: many open bins -> prefer consolidating into them
    // rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // New-bin candidate: only attractive when existing residuals are poor
    // (high mean residual spread) or no open bin fits well.
    if bin_residual == bin_capacity {
        score = 60.0 + mean_residual * 0.3 + open_bins_count as f64 * 2.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can serve the lookahead too
        }
        if post_residual < 10 && post_residual > 0 {
            score += 400.0; // avoid fresh-bin dead space
        }
    }

    // Prefer bins whose residual is already tight (waste little extra room).
    score += (bin_residual as f64 - post_residual as f64) * 0.1;

    // Slight preference for bins below mean residual (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead k=2: reward exact/near matches of next_item_size into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 30.0; // perfect chaining: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            // next item fits; reward proportionally to how well it uses leftover
            let use_ratio = nxt / post_residual as f64;
            score -= 20.0 * use_ratio;
        } else {
            // next item won't fit here; penalize dead space scaled by gap
            let gap = (post_residual as f64 - nxt).abs();
            score += 0.5 * gap.min(40.0);
        }
    }

    // Relative-to-mean coupling: bins with residual far above mean are worse targets
    // unless post_residual is small (tight fit is good anyway).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        let dev = (pr - mean_residual) / mean_residual;
        if dev > 0.0 {
            score += 5.0 * dev.min(2.0);
        } else {
            score -= 2.0 * (-dev).min(2.0);
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize moderately so we prefer existing bins,
    // but allow opening when the fit into open bins would be very poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        // If item is large relative to capacity, opening fresh is less costly
        score -= (item_size as f64 / bin_capacity as f64) * 10.0;
        // If many bins are open with high mean residual, a fresh bin is more attractive
        if open_bins_count > 0 && mean_residual > 50.0 {
            score -= 8.0;
        }
    }

    // Tight fits into existing bins: reward small post_residual nonlinearly
    if pr > 0.0 {
        score -= 10.0 * (1.0 - pr / bin_capacity as f64).powi(4);
    } else {
        score -= 10.0; // perfect fill
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base fit quality: reward small post-residuals super-linearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += (pr / cap) * (pr / cap) * 40.0;

    // Perfect fit: overwhelmingly favored.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack * 0.05;
            if post_residual == next_item_size {
                score -= 60.0; // chain fill: residual consumed exactly by next item
            }
        } else {
            // Penalize dead space the next item cannot use.
            score += 8.0 + pr * 0.02;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly
    // or global residuals are already fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - pr).abs();
        let progress = step_index as f64 / total_items.max(1) as f64;
        let penalty = 60.0
            + open_bins_count as f64 * 3.0
            + fragmentation * 0.1
            + (1.0 - progress) * 20.0;
        score += penalty;
        // A fresh bin is worth it if the next item could pair with this one later
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Mild preference for bins below mean residual (keeps large residuals aggregated).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    // Late-stream tightening: become more selective as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr * 0.03 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap; // 0..1
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Early: prefer tight fits (penalize large residual); Late: prefer small post_residual too but less harshly.
    let coupling = norm_pr * norm_pr * (1.0 - 2.0 * progress + 3.0 * p2 - 2.0 * p3);
    score += 40.0 * coupling;

    // Reward filling bins nearly exactly, stronger late in the stream.
    let tightness = (cap - pr) / cap; // fraction filled after placement
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - 0.5 * progress);
    }

    // Penalize opening a new bin when open bins fit, scaled by how many fit and stream progress.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_pressure = (fitting_bins_count.max(1) as f64).recip();
        score += 20.0 * fit_pressure * (1.0 - 0.4 * progress);
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here; slight penalty proportional to wasted residual.
        score += 5.0 * norm_pr * (1.0 - progress);
    }

    // Mild penalty for deviating from mean residual across open bins (balance load).
    let dev = (pr - mean_residual).abs();
    score += 3.0 * (dev / cap) * (1.0 - progress);

    // Encourage consolidation when many bins are open.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that divide capacity evenly
    // (or fall into large "usable" classes) are valuable; tiny slivers are dead space.
    let class = post_residual / 10; // integer division thresholds: 0..=10
    match class {
        0 => score += 60.0,                       // 0..9: near-full bin, tiny dead space
        1 => score += 25.0,                       // 10..19: small but often unusable
        2 => score += 5.0,                        // 20..29: can host small items
        3 | 4 | 5 => score -= 10.0,               // 30..59: flexible mid-range residual
        6 | 7 => score -= 15.0,                   // 60..79: half-capacity-like, very reusable
        _ => score -= 8.0,                        // 80..99: large residual, item was tiny
    }

    // Exact divisor classes: post_residual that is a clean fraction of capacity
    // (0, 25, 50, 75) is harmonically ideal.
    if post_residual == 0 { score -= 40.0; }
    if post_residual % 25 == 0 && post_residual > 0 { score -= 20.0; }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 30.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item cannot follow here: penalize proportionally to how
            // much of the residual goes to waste relative to next item need.
            score += 0.25 * (next_item_size as f64 - post_residual as f64).min(40.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Penalize creating residuals below the typical minimum item size (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Waste relative to mean residual: placing into a bin far below the mean
    // residual fragments the fleet; prefer bins with larger residuals.
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Early in the stream, keep bins open and homogeneous (mild new-bin pull);
    // late in the stream, close out bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate calibration: an empty bin has post_residual == capacity;
    // make it attractive only when the fit elsewhere would be very poor.
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
    }

    // Slight preference for tighter fits overall.
    score += 0.1 * item_size as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest
    // future item (<= 10) are pure waste; make them very costly.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small gaps only usable by tiny items: strong penalty.
        score += 30.0;
    } else if post_residual <= 35 {
        score += 10.0;
    } else {
        // Larger residuals are useful space; reward them slightly.
        score -= 5.0;
    }

    // Tight-fit reward: exact or near-exact fills are ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual can't host the next item: mild penalty scaled by gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.3 * gap.min(30.0);
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are crowded
    // (high open_bins_count pressure or low mean residual).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        let crowded = (mean_residual / bin_capacity as f64) < 0.25;
        if crowded && pressure > 2.0 {
            score -= 15.0;
        } else {
            score += 25.0 + pressure * 2.0;
        }
    }

    // Open-bins pressure: mild penalty for using bins when many are open,
    // encouraging consolidation into fewer bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Late-stream tightening: as the stream progresses, be more tolerant
    // of imperfect fits (fewer chances to consolidate).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 60.0; // perfect next-item fill
        } else {
            // penalize mismatch scaled by deviation
            score += diff as f64 * 0.4;
            // bonus if next item still fits in residual
            if next_item_size <= post_residual {
                score -= 10.0;
            }
        }
    }

    // Penalize large dead space relative to mean residual
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += dead * 0.3;
    } else {
        score += dead * 0.1; // slightly reward tighter-than-average bins
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in stream: be conservative, prefer tight fits; later: prefer consolidation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    // Penalize opening new bins when open bins exist and fit is decent
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize small dead space left behind, but only if it can't host the lookahead item.
    let dead = post_residual as f64;
    let next_fits_here = next_item_size > 0 && next_item_size <= post_residual;
    if !next_fits_here {
        // Dead space scaled by how "orphaned" it is relative to typical residual.
        let orphan = dead / (mean_residual.max(1.0));
        score += 6.0 * orphan.min(3.0);
    } else {
        // Lookahead synergy: this bin can host the next item too — big reward.
        let chain_tightness = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 10.0 + 14.0 * chain_tightness;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 0.5 * (bin_residual as f64 - item_size as f64).min(20.0);
    }

    // New-bin candidate handling: opening a fresh bin is only attractive early in
    // the stream or when open bins are mostly full (low mean residual).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let fullness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        // Base cost of a new bin; discount when bins are nearly exhausted or stream is young.
        let new_bin_cost = 30.0 * (1.0 - 0.5 * fullness) + 15.0 * progress;
        score = new_bin_cost + dead as f64;
    } else {
        // Mild preference for concentrating items into fewer bins.
        score += (open_bins_count as f64).ln().max(0.0) * 0.8;
    }

    // Global residual alignment: prefer bins whose residual is close to the mean
    // (keeps a balanced portfolio of bin sizes for future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer leaving residuals that are multiples-friendly: tiny residuals (<10) are dead.
    if post_residual > 0 && post_residual < 10 && !next_fits_here {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x); // smooth bump peaking near x=0.5
    score -= 24.0 * poly * (0.5 + progress);

    // Penalize large wasted residual as stream progresses (dead space becomes costlier)
    score += 10.0 * x * x * progress;

    // Reward tight fits (small post residual)
    score -= 6.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (x - nx).abs();
        score -= 8.0 * (1.0 - gap.min(1.0)) * (1.0 - progress);
        score += 5.0 * if nx > x { 1.0 } else { 0.0 } * (nx - x);
    }

    // Mild pressure toward consolidating bins
    score += 0.05 * open_bins_count as f64 * x;

    // New-bin candidate: penalize slightly unless residual would be poorly used
    if bin_residual == bin_capacity {
        let waste = 1.0 - (item_size as f64 / cap);
        score += 12.0 * (1.0 - waste * waste) + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how well it aligns with common item sizes
    // Small post residuals that are "dead" (unusable for typical items) should be penalized.
    let dead_threshold = 10u32; // smallest possible item
    if post_residual < dead_threshold {
        score -= 60.0; // perfect fit, no waste at all -> strongly favored
    } else {
        // Penalize residuals that no realistic item can use
        let unusable = post_residual < 20 && post_residual >= dead_threshold;
        if unusable {
            score += 25.0;
        }
        // Harmonic divisibility: favor residuals divisible by small sizes (10, 20, 25, 50)
        let mut harmony = 0.0;
        if post_residual % 10 == 0 { harmony += 8.0; }
        if post_residual % 20 == 0 { harmony += 6.0; }
        if post_residual % 25 == 0 { harmony += 6.0; }
        if post_residual % 50 == 0 { harmony += 4.0; }
        score -= harmony;

        // Non-linear waste penalty: quadratic growth of dead-space risk
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);
    }

    // Lookahead coupling: if the next item fits exactly in the post residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how tightly the next item fits
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 * tightness;
        } else {
            // next item won't fit here; penalize proportionally to leftover
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Late in the stream, consolidation matters more: penalize spreading across many bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (open_bins_count as f64) * 1.5;

    // Prefer bins whose residual is already below the mean (tighter bins first)
    let dev = mean_residual - bin_residual as f64;
    score -= dev * 0.5;

    // New-bin candidate handling: empty bin should only win when no open bin is decent
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // cheaper to open a new bin when few bins are open or item is large
        score -= (item_size as f64) * 0.2;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
        // early stream: opening bins is fine
        score -= (1.0 - progress) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no realistic item can use
    // (small gaps) are heavily penalized.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else if post_residual < 20 { 0.6 } else { 0.0 };
        score += dead * 40.0;
    }

    // Reward tight fits (near-perfect packing).
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 30.0;

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer reusing existing bins,
    // discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (20.0 + 30.0 * progress);
    score += pressure * (if bin_residual == bin_capacity { 15.0 } else { 0.0 });

    // New-bin candidate: only attractive when existing residuals are poor
    // relative to the current item, or the fit here is very loose.
    if bin_residual == bin_capacity {
        let loose = (post_residual as f64) / bin_capacity as f64;
        score -= 10.0 * loose;
        // Lookahead: if next item is large and this bin would be left with
        // a tiny gap, opening fresh is fine.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 12.0;
        }
    } else {
        // Prefer bins whose residual matches the item well relative to the mean.
        let rel = (bin_residual as f64 - item_size as f64) / (mean_residual + 1.0);
        score -= 5.0 * rel.clamp(-2.0, 2.0);
    }

    // Lookahead synergy: if the post residual exactly accommodates the next item,
    // this is an excellent chained placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward when the leftover exactly matches the next item (2-step lookahead)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // leftover can still host the next item: mild reward proportional to slack
            score -= 30.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space, worse when very small
            let dead = post_residual as f64;
            score += 20.0 * (1.0 - dead / 100.0);
        }
    }

    // Compare post_residual against mean residual: prefer bins that stay near/below mean
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize wasting a large residual bin on a small item early in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    let waste = (bin_residual - item_size) as f64;
    score += 0.3 * waste * (1.0 - progress);

    // New-bin candidate handling: only attractive when no good existing option
    if bin_residual == bin_capacity {
        if fitting_bins_count > 1 {
            // existing bins available: make new bin unattractive
            score += 400.0;
        } else if next_item_size > 0 && post_residual < next_item_size {
            // last-chance bin exists but leaves unusable residue; new bin mildly better
            score -= 50.0;
        } else {
            score += 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual).
    if post_residual == 0 {
        score -= 100.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 40.0;
    } else {
        // Penalize large dead space, amplified by how big it is relative to capacity.
        score += (post_residual as f64 / bin_capacity as f64) * 30.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 25.0 - (slack as f64).min(25.0);
        if slack == 0 {
            score -= 35.0; // chain perfect fit
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot fit here: leftover space is likely dead.
        let waste = post_residual as f64;
        score += waste * 0.15;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * (open_bins_count as f64).min(20.0) * 1.5;

    // Encourage using bins whose residual is above the mean (top-up large leftovers).
    if (bin_residual as f64) > mean_residual + 1.0 {
        score -= 5.0;
    } else if (bin_residual as f64) < mean_residual - 1.0 {
        score += 5.0;
    }

    // New-bin candidate handling: only open a new bin if the item is large relative
    // to typical residuals or no good fit exists; otherwise penalize new bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_frac = item_size as f64 / bin_capacity as f64;
        // A new bin is attractive when the item is big and would leave small waste elsewhere.
        let new_bin_appeal = item_frac * 60.0 - (1.0 - item_frac) * 40.0;
        score += 60.0 - new_bin_appeal; // baseline penalty for opening a bin
        // Early in stream, opening new bins is cheaper; late, consolidate.
        score -= (1.0 - progress) * 10.0;
        // If the only fitting bin is this new-bin call itself, allow it.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // If next item is huge, a fresh bin is risky (wastes space).
        if next_item_size > bin_residual {
            score += 10.0;
        }
    }

    // Mild time-horizon modulation: as the stream progresses, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear coupling: dead-space penalty grows with stream progress
    let dead = pr / cap;
    score += 12.0 * dead * dead * (0.4 + 0.6 * progress);

    // Reward tight fits, stronger as stream progresses
    let tight = 1.0 - dead;
    score -= 10.0 * tight * tight * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: favor residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 4.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 3.0 * (nx - pr) / cap;
        }
    }

    // Penalize bins deviating from mean residual (keep residuals balanced)
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: mild penalty so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: perfect fill gets strong bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the residual: small residuals are "dead space".
    // Class by integer division of post_residual into capacity bands.
    let cap_f = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap_f; // capacity fraction remaining

    // Penalize residuals that are too small to be useful for typical items (1..=100).
    // Items <= post_residual could still fit; reward residuals that can host
    // plausible next items, penalize otherwise.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // residual can host the lookahead item: reward proportionally
            score -= (next_item_size as f64) * 1.5;
            // harmonic class: if post_residual is an exact multiple class match
            let class = post_residual / 25; // quarters of capacity (100/25=4 classes)
            let class_fill = (class as f64) * 25.0;
            if (pr - class_fill).abs() < 0.5 {
                score -= 20.0; // residual aligned to harmonic quarter boundary
            }
        } else {
            // residual cannot host next item: penalize dead space
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Modulo arithmetic: residuals that are multiples of small item granularities
    // are more reusable. Check divisibility by common size classes.
    let reusability = if post_residual % 10 == 0 {
        3.0
    } else if post_residual % 5 == 0 {
        1.5
    } else {
        0.0
    };
    score -= reusability;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // base penalty: opening new bin is costly
        score += 80.0;
        // but if open bins are fragmented (high mean residual spread) and item is large,
        // a fresh bin may be better. Escalate penalty when open bins are few.
        if open_bins_count > 0 {
            let fragmentation = (mean_residual - frac * cap_f).abs();
            score += open_bins_count as f64 * 2.0;
            score -= fragmentation * 0.3;
        }
        // large items relative to capacity prefer fresh bins
        if (item_size as f64) > 0.7 * cap_f {
            score -= 60.0;
        }
    }

    // Prefer filling bins with lower residual relative to mean (best-fit coupling)
    score += (mean_residual - pr) * 0.5;

    // Early in stream, be slightly conservative about tight fits leaving tiny residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    if pr > 0.0 && pr < 10.0 {
        // tiny dead space: penalize unless it's near end of stream where bins close anyway
        score += (10.0 - pr) * (2.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps too small for the next item are wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
    }

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 3.0;
        // But if residuals across bins are low, opening may be fine.
        score -= mean_residual * 0.5;
    } else {
        score += open_bins_count as f64 * 0.5;
    }

    // Late in stream: prefer compacting into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    } else {
        score += progress * 10.0;
    }

    // Penalize leaving a gap just above the next item size barely unusable.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 5 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size {
            // next item can still fit here afterwards; mild reward scaled by closeness
            let gap = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot fit in leftover; penalize proportionally to wasted space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    }

    // Compare residual against mean residual across open bins
    if post_residual as f64 > mean_residual {
        score += 0.3 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - post_residual as f64);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Penalize opening a new bin unless item is large or nothing fits well
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline cost, reward only if it enables tight future packing
        score = post_residual as f64 + 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 60.0;
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // no open bin fits: must open new bin
        }
    }

    // Small residual fragmentation penalty (dead space below min item size ~1)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Late in stream: prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: later in the stream, tighten up placements.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Perfect fit bonus: strong reward for near-zero post residual.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Penalize post-residuals that are dead space: too small for the
    // smallest plausible item (>=1, but typical items mid-sized).
    let dead_threshold = 9u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 2.5;
    }

    // Lookahead: reward if the next item fits in post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain bonus, stronger when the chained fit is tight.
            let chain_tightness = (post_residual - next_item_size) as f64;
            score -= 10.0 + 20.0 / (1.0 + chain_tightness);
        } else if next_item_size <= bin_residual {
            // Next item would have fit if we hadn't consumed space: mild penalty.
            score += 6.0;
        }
        // If next item is large, prefer conserving big-residual bins.
        if next_item_size > 60 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // More fitting bins: prefer the tightest (post_residual already does this),
        // slight extra pressure to differentiate.
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Global state coupling: if mean residual across open bins is high,
    // we have slack; encourage filling bins rather than opening new ones.
    let mean_resid_gap = mean_residual - post_residual as f64;
    score += mean_resid_gap * 0.15;

    // New-bin candidate handling: bin_residual == bin_capacity (empty bin).
    if bin_residual == bin_capacity {
        // Opening a new bin is penalized mildly; it should win only when
        // existing bins would create large dead space.
        let mut new_bin_score = post_residual as f64 + 18.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            new_bin_score -= 8.0; // fresh bin has room for lookahead too
        }
        // Late in the stream, opening new bins is more wasteful.
        new_bin_score += progress * 10.0;
        // If open bins are already crowded (low mean residual), a new bin is fine.
        if mean_residual < 30.0 {
            new_bin_score -= 10.0;
        }
        return new_bin_score;
    }

    // Time horizon: early on, be a bit exploratory (favor balanced fills);
    // late, strongly prefer tightest fits.
    score -= (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);
    score += progress * post_residual as f64 * 0.3;

    // Tie-breaker: prefer bins with lower residual pre-placement (fill fuller bins first).
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: early on, tolerate larger residuals (keep bins flexible);
    // later, penalize leftover dead space more strongly (quadratic ramp).
    let tightness = 0.5 + 1.5 * progress * progress;
    score *= tightness;

    // Lookahead coupling: reward residual that can host the next item (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let fit_slack = (pr - nxt) / cap;
            score -= 6.0 * (1.0 - fit_slack) * (1.0 - fit_slack) * (1.0 - 0.5 * progress);
        } else {
            // post-residual too small for next item: penalize proportionally to wasted fraction
            let waste = (nxt - pr) / cap;
            score += 4.0 * waste * waste;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 - 0.3 * progress);
    }

    // New-bin candidate handling: keep empty bin attractive early, discourage later
    if bin_residual == bin_capacity {
        score = cap * (1.2 - 0.7 * progress) + 2.0 * open_bins_count as f64 * (1.0 - progress);
    } else {
        // Mildly reward packing into bins with low mean residual (consolidation)
        score += 0.3 * (mean_residual - pr).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: classify leftover space by
    // integer division against common item-size bands (1..100 stream).
    // Classes: [1..9] tiny (dead), [10..24] small, [25..49] medium,
    // [50..74] large, [75..100] half-bin+ (very reusable).
    let class = post_residual / 25; // 0..4
    let class_bonus: f64 = match class {
        0 => -60.0,          // nearly dead space -> penalize less? no: penalize dead space
        1 => 20.0,           // small leftover, moderately wasteful
        2 => -15.0,          // medium leftover, still useful for small items
        3 => -35.0,          // large leftover, very reusable
        _ => -50.0,          // half-bin or more, excellent
    };
    score += class_bonus;

    // Penalize tiny unusable residuals (< 10) strongly — dead space.
    if post_residual < 10 {
        score += 40.0;
    }

    // Lookahead coupling: does next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits exactly-ish: reward tight chains.
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 90.0; // two-step perfect chain
            } else if slack < 10 {
                score -= 55.0; // chain leaves near-dead space, still good
            } else {
                score -= 25.0;
            }
        } else {
            // Next item won't fit here: mild penalty unless residual large.
            score += 10.0;
            if post_residual >= 50 {
                score -= 15.0; // big residual likely useful later anyway
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // New-bin candidate handling: empty bin should lose unless current bin
    // would be badly fragmented or mean residual is high (bins already roomy).
    if bin_residual == bin_capacity {
        // Fresh bin: neutral-ish baseline, adjusted by global context.
        score = bin_capacity as f64 * 0.5;
        if mean_residual > 45.0 {
            score -= 20.0; // existing bins roomy -> prefer them? actually new bin fine too
        }
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: a fresh bin is valuable
        }
    } else {
        // Occupied bin: prefer bins whose residual is below the mean (tight packing).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
        // Late in the stream, consolidate aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);
        // Modulo harmonic: reward residuals that are multiples of common sizes.
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual % 25 == 0 {
            score -= 6.0;
        }
    }

    // Many open bins: discourage spreading; favor filling existing ones.
    if open_bins_count > 8 {
        score += 5.0;
        if bin_residual != bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it is smaller than the minimum plausible item size
    // (assume items down to ~5 units) or too small for the lookahead item.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        // Perfect fit or near-perfect fit is excellent; but a tiny leftover
        // gap that is not a perfect fit is dead space.
        if post_residual > 0 {
            score -= 8.0; // reward filling almost everything
        } else {
            score -= 15.0; // perfect fit, best possible
        }
    } else {
        // Penalize gaps that cannot fit the next item (lookahead-aware dead space)
        if next_item_size > 0 && post_residual < next_item_size {
            score += 6.0 + 0.15 * (post_residual as f64);
        }
        // Reward moderate leftovers that can still host the next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    // Non-linear dead-space penalty: quadratic growth of waste for mid-size gaps
    let gap = post_residual as f64;
    if gap > 0.0 && gap < (bin_capacity as f64) * 0.35 {
        score += 0.05 * gap * gap / (1.0 + gap);
    }

    // Open bins pressure: discourage opening new bins when many are open
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin is costly; penalize proportionally to open bin count
        score += 10.0 + 2.5 * (open_bins_count as f64);
        // But if no open bin fits well (this is last chance), allow it
        if fitting_bins_count <= 1 {
            score -= 12.0;
        }
        // Late in stream, prefer closing out existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 5.0 * (1.0 - progress);
    } else {
        // Favor bins that are already substantially filled
        let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 4.0 * fill_ratio;
        // Last-chance bonus: if this is the only fitting bin, strongly favor it
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Slight preference for bins below mean residual (consolidate waste)
        score += 0.05 * ((bin_residual as f64) - mean_residual);
    }

    // Lookahead synergy: if next item exactly matches post_residual, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly or nearly
    // matches the next item size (chain-fitting), penalize otherwise.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 60.0; // perfect chain: next item exactly fills this bin
        } else if gap <= 5.0 {
            score -= 30.0 - 4.0 * gap;
        } else {
            score += gap * 0.8; // post_residual poorly matched to next item
        }
        // If next item cannot fit here anyway, mild penalty unless post_residual tiny
        if (next_item_size as i64) > post_residual as i64 && post_residual <= 10 {
            score -= 10.0; // dead space is small, acceptable
        }
    }

    // Relative to mean residual: prefer bins that are already low-residual (tight)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Penalize opening a brand-new bin when decent fits exist:
    // new bin has full residual; make it less attractive unless item is huge relative
    // to all residuals (handled by fitting_bins_count==0 naturally).
    if bin_residual == bin_capacity {
        score += 25.0;
        // but if next item is large and this bin stays fresh, slight relief
        if next_item_size as f64 > mean_residual {
            score -= 15.0;
        }
    }

    // Early stream: be more exploratory (allow new bins), late stream: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // Tight-fit reward: small post_residual generally good
    if post_residual <= 5 {
        score -= 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * (1.0 - fit_ratio) * 12.0;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable slivers are wasted capacity
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra bonus when next item exactly nests into the remainder.
            let gap = post_residual as f64 - next_item_size as f64;
            score -= (1.0 - gap / bin_capacity as f64) * 6.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance dynamics: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }
    // Many alternatives: mild penalty to encourage exploring better fits elsewhere.
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(4.0);
    }

    // Prefer filling bins that are already relatively full (residual below mean).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 1.5;
    }

    // Time horizon: early in the stream, be more willing to open fresh bins;
    // late in the stream, consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score -= 10.0 * (1.0 - progress);
        score += 8.0 * progress;
        // Opening a bin when few are open is fine; wasteful when many are open.
        score += 0.5 * open_bins_count as f64;
    } else {
        score -= 4.0 * progress;
    }

    // Mild penalty for very large wasted residual relative to capacity.
    score += fit_ratio * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nx = next_item_size as f64;

    // Smooth non-linear coupling: post_residual polynomial in progress
    let pr_norm = pr / cap;
    score += 2.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward bins whose residual matches the next item (smooth Gaussian-like term)
    if nx > 0.0 {
        let diff = (pr - nx) / cap;
        score -= 12.0 * (-25.0 * diff * diff);
    }

    // Last chance: strongly favor using this bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (1.0 + progress);
    }

    // Penalize opening a new bin when open bins are well-filled (smooth)
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= fill * fill * 3.0 * (mean_residual / cap);

    // New-bin candidate: penalize mildly, less so late in stream
    if bin_residual == bin_capacity {
        score += 6.0 - 3.0 * progress;
    }

    // Slight preference for bins below mean residual (consolidation)
    score += 0.05 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base best-fit: prefer tight fits (small post_residual), scaled.
    score += post_residual as f64 * 0.5;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class logic: classify post_residual into residue classes modulo 10.
    // Dead space that cannot hold the smallest item (size 1) is only post_residual == 0;
    // but small post_residual classes (1..9) are "near-dead" for typical items.
    let pr = post_residual as u32;
    let class = pr % 10;
    if pr > 0 && pr < 10 {
        // Near-dead space: penalize strongly (wasted capacity).
        score += 40.0 + (10 - pr) as f64 * 3.0;
    } else if class <= 2 && pr >= 10 {
        // Residual just above a decade boundary: still usable but awkward.
        score += class as f64 * 2.0;
    }

    // Integer-division thresholds: how many "typical" items still fit.
    // Half-full and above keep bins attractive; nearly-empty bins are precious.
    let fill = bin_capacity - bin_residual; // used space
    let fill_frac = fill as f64 / bin_capacity as f64;

    // Reward using bins that are already substantially filled (avoid bin sprawl).
    score -= fill_frac * 25.0;

    // Lookahead coupling: if next item fits in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 30.0;
        if slack % 10 == 0 {
            score -= 10.0; // leaves a clean harmonic boundary
        }
        if slack < 10 {
            score -= 5.0; // near-perfect two-item packing
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post residual cannot host next item: mild penalty scaled by mismatch.
        let gap = (next_item_size - post_residual) as f64;
        score += (gap / 20.0).min(15.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: empty bin should win only when no open bin
    // offers a good fit. Penalize the fresh bin moderately, more so when
    // many bins are open and mean residual is large.
    if bin_residual == bin_capacity {
        let base = 35.0;
        let sprawl = (open_bins_count as f64).ln().max(0.0) * 8.0;
        let waste = (mean_residual / bin_capacity as f64) * 30.0;
        score += base + sprawl + waste;
    } else {
        // Slight preference for bins whose residual is close to mean (balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += (dev / 50.0).min(10.0);
    }

    // Stream progression: early on, be more willing to open bins (explore);
    // later, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0 * fill_frac; // early: reward filling partially
    score += progress * (post_residual as f64 / 100.0) * 8.0; // late: penalize leftovers

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< min item size ~10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps too small to fit the lookahead item are likely dead space too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward perfect and near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Tightness ratio reward: the fuller the bin becomes, the better.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Open-bin pressure: discourage spreading across many bins when residuals are small.
    score += (open_bins_count as f64).ln().max(0.0) * 4.0;

    // Mean-residual coupling: if this bin's post-residual is far below the mean,
    // it consolidates waste; reward that.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: make empty bins attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win.
        score += 15.0;
        // But if this is the last fitting bin context or stream is early with few bins,
        // opening fresh can be fine.
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            // Large item pair: fresh bin preserves room for future items.
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative: new bin is mandatory anyway
        }
        // Late in the stream, avoid opening bins that will barely be used.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Lookahead synergy: if the next item exactly fills the post residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead: reward if next item exactly fills post_residual (2-step chain)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover after hypothetical next placement
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.5;
            score -= 100.0;
        } else {
            // next item does not fit here: penalize dead space relative to next item
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.3;
        }
    }

    // Tightness: favor small post_residual relative to capacity
    score += (post_residual as f64 / bin_capacity as f64) * 50.0;

    // Compare against mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * -0.5;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 200.0;
        // allow new bin if next item is large and would leave big dead space
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 50.0;
        }
    }

    // Late in stream: be more conservative, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 30.0 * (open_bins_count as f64 / (open_bins_count.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strong reward for tight fits (small post_residual) with non-linear emphasis.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Lookahead: reward if the next item fits into the post residual (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 + 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize leaving a residual too small to be useful for the next item.
            let waste = post_residual as f64;
            if waste > 0.0 {
                score += 6.0 * (waste / bin_capacity as f64);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive; penalize unless
    // the item fits very poorly in existing bins (large post_residual there).
    if bin_residual == bin_capacity {
        let base_cost = 45.0 - 20.0 * progress;
        // If many bins are open and mean residual is large, discourage new bins.
        let crowd = (open_bins_count as f64).ln_1p() * (mean_residual / bin_capacity as f64);
        score = base_cost + crowd * 10.0;
        // Late in the stream, new bins are relatively cheaper to open.
        if progress > 0.8 { score -= 10.0; }
    } else {
        // Mild penalty when many bins are already open (consolidate).
        score += 2.0 * (open_bins_count as f64).ln_1p();
    }

    // Prefer bins whose residual deviates favorably from the mean (balance-aware).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - progress) + x * progress * (1.0 - x);
    let mut score = pr - 18.0 * poly;

    // Reward tight fits, scaled by progress
    let tight = 1.0 - (pr / bin_residual.max(1) as f64);
    score -= 12.0 * tight * (0.5 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 + 8.0 * progress;
    }

    // Lookahead: penalize wasting space needed by next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr > 0.0 && nx > pr {
            score += 6.0 * (1.0 - pr / nx) * (1.0 - progress);
        } else if nx > 0.0 && pr >= nx {
            score -= 5.0 * (nx / cap) * (1.0 - x);
        }
    }

    // Mild penalty for proliferation of open bins
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual
    score += 0.1 * (pr - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit -> overwhelmingly favored
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity wasted

    // Penalize residual by fraction of capacity, quadratically for dead zones
    score += 40.0 * frac * frac;

    // Harmonic classes: residuals divisible by common item sizes are reusable
    let classes: [u32; 8] = [10, 20, 25, 50, 5, 40, 30, 100];
    let mut reusable = false;
    for c in classes.iter() {
        if *c != 0 && post_residual >= *c && post_residual % *c == 0 {
            reusable = true;
            break;
        }
    }
    if reusable {
        score -= 25.0;
    } else {
        score += 10.0;
    }

    // Integer division thresholds: post_residual bucketed by capacity / 8
    let bucket = post_residual / (bin_capacity / 8).max(1);
    score += bucket as f64 * 4.0;

    // Lookahead: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward chains, more if next item nearly fills the remainder
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - 0.2 * slack;
        } else {
            // remainder too small for next item -> dead space risk
            score += 20.0 + frac * 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is crowded
    if bin_residual == bin_capacity {
        // opening fresh bin wastes future flexibility; mild penalty
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        } else if mean_residual < item_size as f64 * 1.2 {
            score -= 20.0; // open bins nearly full anyway
        }
    }

    // Late in stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - frac);

    // Tie-break: prefer bins with residual close to mean (balance)
    score += (pr - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest conceivable item (1..100 domain, so anything < ~20 is nearly
    // dead) are heavily penalized, non-linearly.
    if post_residual > 0 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 6.0;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving a gap that the lookahead item can exactly use (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }
    // Penalize if post_residual cannot fit the next item but is still sizeable:
    // stranded space that the lookahead cannot use.
    if next_item_size > 0 && post_residual >= 1 && post_residual < next_item_size && post_residual < 40 {
        score += 8.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening another;
    // the new-bin candidate has bin_residual == bin_capacity, so this term
    // (via mean_residual comparison) applies mostly to existing bins.
    if bin_residual != bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= open_bins_count as f64 * 0.5 * (0.5 + progress);
        // Reward bins whose residual is close to the mean residual (keeps
        // bin residuals balanced so future fits remain possible).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.3;
    } else {
        // New-bin candidate: penalize more when many bins are already open,
        // less when few are open (early stream, consolidation phase).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + open_bins_count as f64 * 1.5 * (0.5 + progress);
    }

    // Mild preference for tighter fits overall (small post_residual relative
    // to the item size means high fill ratio).
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: heavily reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward when next item exactly fills the new residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // next item fits here afterward: mild reward proportional to how snug
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 - slack * 0.25;
        } else {
            // next item cannot use the residual: penalize dead space
            let dead = (next_item_size - post_residual) as f64;
            score += 8.0 + dead * 0.15;
        }
    }

    // Penalize residuals too small to ever be useful (below min item size 1..100 unknown, use item_size as proxy)
    if post_residual > 0 && post_residual < item_size.min(50) {
        score += 12.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Early in stream: be pickier about wasting space; late: consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * (post_residual as f64) * 0.1;
    score -= progress * 5.0;

    // New-bin candidate: only attractive when it truly beats packing into junk
    if bin_residual == bin_capacity {
        score += 18.0 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 10.0; // big next item: fresh bin has room value
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize (subtract) when post_residual is small.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 0.6 * tight * tight * (bin_capacity as f64);

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here; penalize leaving awkward residue.
            let dead = (post_residual as f64) / (next_item_size as f64);
            if post_residual < next_item_size && post_residual > 0 {
                score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
            }
            let _ = dead;
        }
    } else {
        // Last item: prefer minimal leftover.
        score -= 5.0 * tight;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Global pressure: many open bins with high mean residual -> avoid wasting space in fat bins.
    if open_bins_count > 1 {
        let fatness = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let bin_fatness = (bin_residual as f64 / bin_capacity as f64).clamp(0.0, 1.0);
        if bin_fatness > fatness {
            score += 2.0 * (bin_fatness - fatness) * (bin_capacity as f64);
        } else {
            score -= 1.5 * (fatness - bin_fatness) * (bin_capacity as f64);
        }
    }

    // Time horizon: early in stream, be more willing to open new bins (penalize cramming less);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 4.0 * tight;
    score += (1.0 - progress) * 1.5 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well or stream is early.
    if bin_residual == bin_capacity {
        let good_open = fitting_bins_count > 0 && (mean_residual / bin_capacity as f64) > 0.35;
        if good_open && progress > 0.15 {
            score += 15.0;
        } else {
            score += 2.0;
        }
    }

    // Mild penalty for very large unusable residue relative to smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score -= 18.0 * poly * (0.5 + progress);

    // Penalize large dead space late in the stream
    score += 12.0 * norm_pr * norm_pr * progress;

    // Reward tight fits (small post_residual relative to item)
    let tight = 1.0 - (pr / (item_size as f64 + 1.0));
    score -= 8.0 * tight.max(0.0) * (1.0 - progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 / cap) * norm_pr;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins near mean
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev;

    // New-bin candidate: keep it competitive only when nothing fits well
    if bin_residual == bin_capacity {
        score += 4.0 + 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "dead zones"
    // (small unusable slivers) are penalized; leftovers that could host typical
    // future items are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let cls = pr / 10; // integer division class, 0..10
        match cls {
            0 => score += 25.0,               // dead sliver 1..9
            1 => score += 8.0,                // 10..19 marginal
            2 | 3 => score -= 6.0,            // 20..39 sweet spot for mid items
            4 | 5 => score -= 10.0,           // 40..59 prime reusable space
            6 | 7 => score -= 4.0,            // 60..79 ok
            _ => score += 3.0,                // nearly empty bin: wasted capacity
        }
        // modulo-5 fine structure: exact multiples of 5 pair well with typical sizes
        if pr % 5 == 0 { score -= 2.0; }
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual,
    // penalize if next item barely misses (creates temptation then failure).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // perfect two-item chain
        } else if next_item_size <= pr {
            score -= 8.0;
        } else if pr > 0 && next_item_size - pr <= 5 {
            score += 12.0; // near-miss: this bin leaves a frustrating gap
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin gets a baseline that is competitive
    // only when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (item_size as f64) * 0.2;
        // late in the stream, prefer consolidation into open bins
        score += (step_index as f64 / total_items.max(1) as f64) * 20.0;
        // many open bins already: discourage proliferation
        score += open_bins_count as f64 * 1.5;
        return score;
    }

    // Tight-fit reward: filling a bin almost exactly is ideal.
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= fill * 12.0;

    // Prefer bins below mean residual (balance load) mildly.
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Progress pressure: as stream advances, favor tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for any plausible item are wasted.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item + 9.0 {
        score += 60.0; // unusable sliver
    }

    // Reward tight fits strongly.
    score -= 40.0 * (item_size as f64 / bin_capacity as f64);

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when current bin leaves a bad gap
    // and open-bin pressure is low.
    if bin_residual == bin_capacity {
        score = 20.0 + 3.0 * open_bins_count as f64;
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 && (post_residual as f64) < 10.0 {
        score += 15.0; // gap blocks the known next item
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins below mean residual (tighter bins).
    score += 0.3 * ((post_residual as f64) - mean_residual).abs().signum() * ((post_residual as f64) - mean_residual);

    // Late in the stream, avoid leaving any residual at all.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 30.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward exact match of the leftover
    // space with the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if diff == 0.0 {
            score -= 60.0; // perfect two-item chain fill
        } else if post_residual >= next_item_size {
            // leftover can host next item: reward closeness to exact match
            score -= 25.0 * (1.0 - diff / (bin_capacity as f64));
        } else {
            // leftover too small for next item: penalize dead space relative to gap
            score += 8.0 + diff * 0.15;
        }
    }

    // Penalize creating small unusable residuals (< 10, minimum item size),
    // unless the bin is almost perfectly filled.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Tight fits are good: reward small post_residual relative to capacity.
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are very fragmented
    // (high mean residual) or late in the stream with many bins open.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).max(0.0);
        score += 30.0 + fragmentation * 0.5;
        if mean_residual > 40.0 {
            score -= (mean_residual - 40.0) * 0.3; // allow opening when bins are wasteful
        }
    }

    // Mild preference to spread load when many bins are open.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: lower post_residual is already good, amplify it.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0; // unusable sliver
        } else {
            score += 4.0 * (1.0 - dead / bin_capacity as f64);
        }
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 8.0; // leftover likely wasted
        }
    } else {
        // Last item: strongly prefer closing bins.
        score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64).max(1.0);
    score += 0.05 * open_bins_count as f64 * (0.3 + progress);

    // Global residual pressure: if mean residual is large, prefer filling bins with big holes.
    score -= 0.3 * mean_residual * (1.0 - fit_ratio);

    // New-bin candidate handling: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 { (item_size + next_item_size) as f64 } else { item_size as f64 };
        if fitting_bins_count == 0 {
            score -= 60.0; // must open new bin anyway
        } else if pressure > 95.0 && mean_residual < pressure * 0.45 {
            score -= 25.0; // pair too big for fragmented bins
        } else {
            score += 45.0 + 10.0 * (1.0 - progress); // discourage premature opening
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth polynomial coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * (1.0 - pr_norm);
    score += 8.0 * poly;

    // Reward tight fits (small post residual) more strongly as stream advances
    score -= 6.0 * (1.0 - progress) * (1.0 - pr_norm).powi(2);

    // Penalize waste relative to mean residual of open bins (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let compat = 1.0 - ((pr - ni).abs() / cap).min(1.0);
        score -= 4.0 * compat * compat;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.3 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: integer division into bands.
    let band = post_residual / 10;
    match band {
        0 => score -= 30.0,                       // near-perfect fit (0..10 left)
        1 => score -= 12.0,                       // good fit
        2 => score += 4.0,                        // mediocre
        3 => score += 10.0,                       // poor
        4 => score += 16.0,                       // bad dead space
        _ => score += 22.0,                       // huge leftover
    }

    // Modulo-arithmetic coupling: residuals divisible by common small sizes are reusable.
    if post_residual > 0 {
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                score -= 8.0;
            }
        }
        // Harmonic penalty: prime-ish residuals are hard to fill later.
        if post_residual % 10 != 0 && post_residual % 5 != 0 {
            score += 6.0;
        }
    }

    // Lookahead: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;                        // perfect chain
        } else if next_item_size <= post_residual {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // next item won't fit here: penalize leaving harmonic-compatible space anyway
            if next_item_size % 10 == 0 && post_residual >= next_item_size / 2 {
                score += 3.0;
            }
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is wasteful unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 45.0;                            // default: prefer reusing open bins
        // But if no open bin fits well, allow a fresh bin.
        if post_residual > 40 {
            score -= 60.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Progression-aware tightness: early in stream, keep bins balanced; later, pack tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (mean_residual - post_residual as f64).abs() * (0.3 * (1.0 - progress));
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // Mild preference for fuller bins when many bins are open.
    score += open_bins_count as f64 * post_residual as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item (1)
    // are pure waste; gaps that can still hold plausible future items are OK.
    // Penalize "awkward" residuals sharply (tiny or odd-sized leftovers),
    // while rewarding near-perfect fits.
    let dead_zone_max = 12.0f64; // residuals <= this are hard to reuse
    if post_residual > 0 && (post_residual as f64) <= dead_zone_max {
        score += (dead_zone_max - post_residual as f64 + 1.0) * 6.0; // strong penalty
    }

    // Perfect / near-perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 8.0;
    }
    // Penalize creating a gap just barely too small for the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // and avoid opening new bins; scale with stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is truly terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: a fresh bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit badly
        // (large post_residual) or few bins are open.
        score += 15.0 + open_bins_count as f64 * 1.5 + progress * 20.0;
        // But allow opening when the item is huge relative to capacity
        // (it will fill a fresh bin well).
        if item_size as f64 >= 0.8 * bin_capacity as f64 {
            score -= 35.0;
        }
    }

    // Mild tie-breaker: prefer bins whose residual is close to the mean
    // (keeps residual distribution balanced).
    score -= 0.3 * (bin_residual as f64 - mean_residual).abs().max(0.0).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Leftover still usable by the next item: mild reward proportional to slack.
        score -= 4.0 + (post_residual - next_item_size) as f64 * 0.15;
    } else if next_item_size > 0 {
        // Dead space relative to next item: penalize the unusable gap.
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Reward tight fits relative to current item.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // Penalize bins with residuals far above the mean (wasteful large holes).
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidation, penalize spreading thin.
    score += open_bins_count as f64 * 0.3;

    // New-bin candidate: only attractive when the item barely fits nowhere well
    // (i.e., it's a poor fit into any residual). Make empty bin moderately costly.
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if next item is large and this item nearly empties the bin, allow it.
        if next_item_size > 0 && post_residual < 10 {
            score -= 20.0;
        }
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared residual penalty normalized.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio * bin_capacity as f64;

    // Strong reward for perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Lookahead: penalize if placing item leaves residual that next item could
    // have used better; reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0; // chain fit
        } else if next_item_size <= post_residual {
            // next item still fits after placement: mild reward
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit in leftover: penalize wasted residual
            score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Global state: with many open bins, prefer filling existing ones over new bins.
    let openness = open_bins_count as f64;
    score += 3.0 * openness * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below mean, it's a
    // "small hole" — using it now is efficient.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.5 * dev;
    } else {
        score += 0.3 * (-dev);
    }

    // New-bin candidate handling: empty bin should only win when current bin fits
    // are poor. Penalize new bin mildly, more so early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 60.0 * (1.0 - progress);
        // If item is large relative to capacity, opening a fresh bin is less bad.
        score -= 0.3 * item_size as f64;
        // If many bins already open and none fit well, new bin is acceptable.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Time horizon: late in stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to progress
    let mut score = r * (1.0 + 0.8 * progress * norm_r * (1.0 - norm_r) * 4.0);

    // Penalize large dead space quadratically, stronger late in stream
    score += norm_r * norm_r * cap * (0.5 + progress);

    // Reward tight fits (small post residual) with smooth decay
    score -= (1.0 - norm_r).powi(3) * 20.0 * (1.0 - progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward if next item fits smoothly into post residual
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if r >= n {
            let tight = 1.0 - ((r - n) / cap);
            score -= 12.0 * tight * tight;
        } else {
            score += 5.0 * (n - r) / cap;
        }
    }

    // Mild preference for balancing residuals across bins
    score += (r - mean_residual).abs() * 0.1;

    // Slight preference for keeping open bin count low early on
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Best-fit base: lower post residual is better (already in score).

    // Harmonic class of post_residual: residual in (0,10] is nearly dead space
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 15.0;
    } else if post_residual <= 30 {
        score += 5.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 500.0;
        } else if slack <= 10 {
            score -= 100.0;
        } else {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; penalize leaving large residuals that
        // fragment the bin relative to the upcoming demand
        let waste = post_residual as f64 / next_item_size as f64;
        score += 20.0 * (1.0 - 1.0 / (1.0 + waste));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more when many bins open
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        // But if current item is large and no good fit exists, new bin is fine
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Prefer bins below mean residual (fill emptier bins less, keep tight bins tight)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Progress-based mild pressure to close bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps below 10 (minimum item size) are pure waste; gaps that cannot fit
    // the next item are also likely waste.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // absolute dead space
        } else if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0; // gap unusable for lookahead item
        } else {
            score -= 10.0; // gap still usable: reward
        }
    } else {
        // Perfect fit: strongly reward closing the bin.
        score -= 60.0;
    }

    // Reward filling bins tightly (high fill ratio).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Open-bin pressure: prefer reusing bins when many are open,
    // but allow opening a new bin when few are open.
    score += 2.5 * open_bins_count as f64;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead coupling: if this bin's post-residual can hold the next item,
    // reward keeping that option alive.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Mean-residual coupling: bins deviating far below mean residual are
    // already tight; placing here keeps large residuals consolidated.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Early in the stream, be slightly more willing to open bins for
    // flexibility; late in the stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits snugly with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 / (1.0 + slack);
    }
    // Next item does NOT fit in the leftover: penalize dead space, worse for larger dead space.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Reward tight fits overall: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Penalize bins with residuals far above the mean residual (fragmented bins).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Late in the stream, consolidate: prefer filling existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when many bins open.
        score += 8.0 + 30.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        score -= 5.0 * progress;
    }

    // Slight preference for bins with smaller residuals when many bins are open.
    score += (open_bins_count as f64).sqrt() * (post_residual as f64 / bin_capacity as f64) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) more aggressively at small residuals.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that can never fit a typical item: residual below min item size.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 25 {
        score += 12.0;
    }

    // Lookahead: if next item fits exactly into the post residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Waste that cannot host the next item.
            score += 8.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64));
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Global state: many open bins with high mean residual -> prefer consolidation into existing bins.
    let mean_gap = mean_residual - bin_residual as f64;
    score += 0.35 * mean_gap;

    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 2.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Time horizon: early in the stream, be conservative (favor new bins for large items
    // to keep flexibility); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    score += (1.0 - progress) * 4.0 * (item_size as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when existing bins would leave very poor fits.
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        // Slight default penalty so we only open new bins when genuinely better.
        score += 6.0;
        if item_size >= 70 {
            score -= 10.0; // big items start fresh bins early for flexibility
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: penalize wasted post residual, smoothly coupled with progress
    let mut score = norm_pr * (1.0 + 2.0 * progress * norm_pr);

    // Reward tight fits: quadratic bonus when post_residual is small
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Interaction with mean residual: prefer bins whose residual deviates from mean
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 0.3 * dev * dev - 0.2 * dev * progress;

    // Last-chance bin: strong reward if this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 1.5 + progress;
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns > pr as f64 {
            score += 0.4 * (1.0 - pr / ns.max(1.0));
        } else {
            score -= 0.3 * (pr - ns) / cap;
        }
    }

    // New-bin candidate: mild penalty so open bins are preferred unless very poor fit
    if bin_residual == bin_capacity {
        score += 0.8 + 0.5 * (1.0 - fit);
    }

    // Smooth non-linear coupling term
    score += 0.25 * (norm_pr * progress).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class logic: partition residual space into classes by integer division.
    // Items whose size divides the residual nicely (post_residual % item_size small) are favored.
    let remainder_class = if item_size > 0 { post_residual % item_size } else { 0 };
    score += remainder_class as f64 * 3.0;

    // Capacity-fraction thresholds: penalize leaving residual in "dead zone" classes.
    // Residuals in (0,10] are nearly unusable dead space; residuals in (10,20] are risky.
    if post_residual > 0 && post_residual <= 10 {
        score += 15.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 6.0;
    } else if post_residual >= 40 && post_residual <= 60 {
        // Mid-range residual is a good "harmonic slot" for typical items
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual == next_item_size {
            score -= 60.0;
        } else {
            score -= 10.0;
            // harmonic check: does next item also divide post_residual?
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; this residual may become dead space
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when existing residuals are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 30.0;
        // Small items early: cheap to open new bin to preserve large residuals
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if item_size <= 25 {
            score -= 20.0 * (1.0 - progress);
        }
        // If mean residual across open bins is small, a new bin is attractive
        if mean_residual < 20.0 {
            score -= 25.0;
        }
        // If many bins already fit the item, opening new bin is wasteful
        if fitting_bins_count > 2 {
            score += 20.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.5;

    // Prefer filling larger residuals less aggressively when residual far exceeds item
    if bin_residual > item_size * 3 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: unusable gaps (< 10, or too small for
    // anything useful) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 200.0;
    }

    // Penalize small-but-nonzero residuals that cannot fit the next item
    // (likely dead space) unless the next item fits elsewhere anyway.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let deadness = (next_item_size - post_residual) as f64;
        score += 1.5 * deadness;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the lookahead item.
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new bin is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (bin_capacity as f64 * 2.0);
    score += pressure * (10.0 + 40.0 * progress);

    // New-bin candidate: baseline slightly below mean residual so we only
    // open a new bin when existing bins are fragmented.
    if bin_residual == bin_capacity {
        score = mean_residual * 0.5 + 20.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // Opening a fresh bin is fine if the next item is large too.
            score -= 10.0;
        }
        if open_bins_count == 0 {
            score -= 500.0; // must open the first bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight by stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.5 * progress * (bin_capacity as f64 - bin_residual as f64) * 0.01;

    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            // Perfect match for the next item: strongly reward.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits here: moderate reward proportional to tightness.
            let slack = post_residual as f64 - nxt;
            score -= 25.0 - 0.3 * slack;
        } else {
            // Dead space: next item cannot fit in the remainder. Penalize,
            // worse when the dead space is large relative to capacity.
            let dead = post_residual as f64;
            score += dead * (0.8 + 0.6 * progress);
        }

        // Coupling with mean residual: if this bin's post-residual deviates
        // far below the mean, we are creating an outlier fragment.
        let pr = post_residual as f64;
        if pr < mean_residual {
            score += 0.4 * (mean_residual - pr);
        } else {
            score -= 0.15 * (pr - mean_residual);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.85 {
        score -= 12.0 * (fit_ratio - 0.85) / 0.15;
    } else if fit_ratio < 0.4 {
        // Poor fit: penalize wasting a large bin on a small item.
        score += 6.0 * (0.4 - fit_ratio) / 0.4;
    }

    // Dead-space penalty: post_residual too small for the smallest plausible follow-up item.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += 3.0; // this placement strands the next item
        }
        // Exact chain fit bonus
        if post_residual == next_item_size {
            score -= 6.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: prefer opening a fresh bin when existing fits are loose,
    // or when many bins are open and mean residual is low (fragmentation).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // Open new bin if current fits are bad (post_residual large) or bins are fragmented.
        let penalty = 4.0 + 20.0 * (1.0 - fragmentation) + 6.0 * progress;
        score += penalty;
        // But avoid hoarding bins early when few bins exist.
        if open_bins_count < 3 {
            score += 15.0;
        }
    } else {
        // Mild bonus for using bins below the mean residual (consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Prefer bins with residual close to item_size overall (best-fit flavor with lookahead twist).
    let slack = (bin_residual as f64 - item_size as f64).abs();
    score += 0.02 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;
    let fit = fitting_bins_count as f64;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: prefer small post-residual (tight fit), with non-linear sharpening
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Smooth quadratic coupling of post_residual with stream progress:
    // later in the stream, waste matters more; early on, be more lenient.
    score += 30.0 * norm_post * norm_post * (progress * progress + 0.5 * progress);

    // Dead-space penalty: post_residual too small to be useful later is wasted.
    // Non-linear cubic falloff around the small-residual region.
    let dead = (1.0 - norm_post).max(0.0);
    score += 12.0 * norm_post * dead * dead;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // (avoid opening a new bin unnecessarily).
    if fitting_bins_count == 1 {
        score -= 40.0 + 25.0 * progress;
    } else {
        // More competing fitting bins -> mild penalty to prefer tightest fit anyway
        score += 2.0 * (fit - 1.0).min(5.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // few fitting bins exist or the item is large relative to capacity.
    let size_ratio = item_size as f64 / cap;
    let new_bin_penalty = is_new_bin * (45.0
        - 30.0 * size_ratio * size_ratio
        + 20.0 * (fit / (fit + 2.0)) * (1.0 - progress));
    score += new_bin_penalty;

    // Lookahead: if next item would fit nicely into post_residual, reward this bin.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            let snug = 1.0 - ((post - next) / cap).abs();
            score -= 15.0 * snug * snug * (0.5 + progress);
        } else {
            // next item cannot fit here; slight penalty proportional to gap
            score += 5.0 * ((next - post) / cap).min(1.0);
        }
    }

    // Mild tie-break via mean residual: prefer bins whose residual is below
    // average (consolidating waste), smooth interaction with progress.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress) + 4.0 * dev * progress;

    // Encourage using already-open bins as open_bins_count grows.
    score += 3.0 * (open_bins_count as f64).ln().max(0.0) * is_new_bin * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: reward near-exact fills
    let pr = post_residual;
    if pr == 0 {
        score -= 45.0; // perfect fill
    } else if pr <= 5 {
        score -= 28.0;
    } else if pr <= 12 {
        score -= 14.0;
    } else if pr <= 25 {
        score -= 4.0;
    }

    // Penalize tiny unusable dead space
    if pr > 0 && pr < 10 {
        score += 18.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let tight = item_size as f64 / cap;
        // Base penalty for opening a new bin
        score += 12.0 + 25.0 * (1.0 - tight);
        // Large items pair well with fresh bins (post_residual small)
        if item_size >= 60 { score -= 20.0; }
        else if item_size >= 40 { score -= 6.0; }
        // No open bin fits at all -> must open
        if fitting_bins_count == 0 { score -= 80.0; }
        // If many bins open but none fit, consolidation failed; fresh bin ok
        if open_bins_count >= 4 && fitting_bins_count == 0 { score -= 10.0; }
    }

    // Lookahead coupling (k=2): does next item mesh with post_residual?
    if next_item_size > 0 && pr > 0 {
        if next_item_size <= pr {
            let fill = next_item_size as f64 / pr as f64;
            score -= 10.0 * fill; // next item fits snugly here
        } else {
            let gap = (next_item_size - pr) as f64 / cap;
            score += 6.0 * gap; // next item would be stranded
        }
    }

    // Modulo-10 residue class texture on post_residual
    let m = (pr % 10) as f64;
    score += 2.5 * (m / 10.0 - 0.5);

    // Fragmentation pressure: many open bins with bloated mean residual
    let frag = (mean_residual / cap - 0.3).max(0.0);
    score += 0.06 * open_bins_count as f64 * frag;

    // Late-stream consolidation: prefer tightest bins near the end
    let t = step_index as f64 / total_items.max(1) as f64;
    if t > 0.75 {
        score -= 6.0 * t * (1.0 - pr as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (wasted space), while exact fits are rewarded.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    } else if pr < 10 {
        // Unusable dead space (below minimum item size): heavy penalty,
        // scaled by how close to zero it is.
        score += (10 - pr) as f64 * 8.0;
    } else if pr < 20 {
        // Marginal residual: only usable by small items; mild penalty.
        score += (20 - pr) as f64 * 1.5;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open,
    // but allow it when few bins are open (spread items early).
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        score += 5.0 + (open_bins_count as f64).sqrt() * 6.0;
        // If no open bin fits well (many dead-space candidates), new bin is fine.
        if fitting_bins_count == 0 {
            score -= 10.0;
        }
    } else {
        // Reward placing into existing bins, more so as bins accumulate.
        score -= (open_bins_count as f64).ln() * 3.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this placement (chain packing); otherwise slight penalty.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 6.0;
        } else {
            score += 2.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (consume the fuller, less useful bins first, keeping roomy bins open).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight late-stream tightening: as the stream progresses, prefer
    // tighter fits even more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += pr as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
