pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual preferred).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize very small dead space that future items (>=1) may or may not use:
    // prefer post_residual == 0 (perfect fit) heavily.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score += 8.0; // tiny unusable slivers are wasteful
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 4.0; // chain placement possible
        } else {
            score += 3.0; // next item can't use this bin
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current item fits poorly everywhere. Make the empty bin moderately
    // attractive but not dominant for good fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Early in stream: new bins are cheap; late: prefer filling existing bins.
        score += 6.0 * (1.0 - progress);
        // If many bins are open and mean residual is high, discourage new bins.
        score += 0.3 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
        // Large items justify fresh bins more.
        score -= (item_size as f64) * 0.05;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor),
    // scaled by global mean residual for context.
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * gap * (1.0 + mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let poly = norm_post * norm_post * (1.0 + progress) - norm_post * progress * (1.0 - progress);
    score += 40.0 * poly;

    // Penalize near-full bins less as stream progresses (pack tightly early)
    score -= 15.0 * (1.0 - norm_post) * (1.0 - progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 {
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            score += 6.0 * (-gap / bin_capacity as f64);
        }
    }

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: reward residuals that fall into
    // "usable" classes (multiples of common small item sizes), penalize dead space.
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Reward small post residuals (tight fit) with a quadratic bonus.
    score -= ((bin_capacity - post_residual) as f64 / cap).powi(2) * 40.0;

    // Harmonic class bonus: post_residual divisible by 10 or 25 is reusable.
    if pr == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if pr % 10 == 0 {
        score -= 12.0;
    } else if pr % 25 == 0 {
        score -= 10.0;
    } else if pr < 10 {
        score += 25.0; // dead space below min item size
    }

    // Integer-division threshold on next_item_size: if the next item fits in
    // the post residual, reward this bin (chaining placements).
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 18.0;
            // extra reward when next item exactly matches a harmonic class of pr
            if pr % next_item_size == 0 {
                score -= 8.0;
            }
        } else {
            score += 10.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals
    // are all too fragmented (mean residual low relative to item).
    if bin_residual == bin_capacity {
        score += 20.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual > item_size as f64 * 1.2 {
            score += 25.0 * (1.0 - progress); // early on, prefer using open bins
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // big next item may justify a fresh bin
        }
    }

    // Mild penalty for proliferating bins when mean residual is high.
    score += open_bins_count as f64 * 0.3;
    score += (mean_residual - post_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 - 3.0 * post_residual as f64;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Tightness reward: fraction of residual consumed by the item.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but discourage opening new bins even more when open bins fit well.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from existing open bins.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // If the next item could use this item's leftover, opening a new bin is worse.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 25.0;
        }
    } else {
        // Using an existing bin relieves open-bin pressure slightly.
        score -= 1.5 * open_bins_count.min(20) as f64;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    // Prefer bins whose residual is above the mean (keeps mean residual healthy).
    score += 0.3 * (mean_residual - post_residual as f64).max(-30.0).min(30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0 + 5.0 * (5 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // 2-step lookahead: if the next item fits into the post residual,
    // this bin remains efficient — reward it proportionally.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 40.0 - 2.0 * slack as f64;
            } else {
                score += 0.1 * slack as f64;
            }
        } else {
            // Next item cannot fit here; leftover may be dead weight.
            let leftover = post_residual as f64;
            if leftover < 10.0 {
                score += (10.0 - leftover) * 2.0;
            }
        }
    }

    // Compare against mean residual: prefer using bins with below-average
    // residual (tighter bins) to consolidate space.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.5 * (residual_f - mean_residual);
    }

    // Last chance bin: if this is the only open bin that fits, strongly
    // prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the item is
    // large and would leave awkward small residuals elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 60.0;
        // Large items with no good fit elsewhere benefit from a new bin.
        if item_size >= bin_capacity * 3 / 4 {
            new_bin_penalty -= 40.0;
        }
        // Early in the stream, opening bins is cheaper; later, consolidate.
        new_bin_penalty *= 1.0 - 0.3 * progress;
        // If many bins are open and mean residual is small, opening a new
        // bin is wasteful.
        if mean_residual < 15.0 && open_bins_count > 2 {
            new_bin_penalty += 30.0;
        }
        // If next item is small, a fresh big residual is fine.
        if next_item_size > 0 && next_item_size <= 20 {
            new_bin_penalty -= 15.0;
        }
        score += new_bin_penalty;
    }

    // Slight preference for bins whose fill ratio is already high.
    let fill_ratio = 1.0 - residual_f / bin_capacity as f64;
    score -= 5.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

