    // Lookahead: reward if the next item fits into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // Penalize leaving a residual that is useless for the next item.
            score += 6.0 * (1.0 - (post_residual as f64) / (next_item_size.max(1) as f64).min(1.0)).max(0.0);
        }
    }

    // Time-horizon scaling: early in the stream, be more conservative (penalize new bins less later).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, but less as stream progresses or when few bins fit.
        let new_bin_penalty = 45.0 - 25.0 * progress - 8.0 * (fitting_bins_count as f64);
        score += new_bin_penalty.max(2.0);
    }

    // Global state coupling: prefer filling bins when mean residual is high (many fragmented bins).
    score -= 0.05 * mean_residual * (1.0 - progress);
    // Slight penalty for spreading across many open bins early on.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

