        if nx > pr as f64 {
            let waste = (nx - pr as f64) / cap;
            score += 10.0 * waste * waste;
        } else {
            // Reward residual that perfectly accommodates the next item.
            let gap = (pr as f64 - nx) / cap;
            score -= 5.0 * (1.0 - gap * gap);
        }
    }

    // Mild penalty on opening new bins when many bins are already open.
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 6.0 + 0.15 * open_bins_count as f64;
    } else {
        score -= 2.0;
    }

    // Smooth stream-progress modulation: slight preference for consolidating early.
    score *= 1.0 - 0.1 * progress * (1.0 - progress) * 4.0;

    score
}

