    }

    // Mild preference for using bins with above-average residual (keep
    // low-residual bins as tight dead-space candidates).
    score -= 0.10 * (bin_residual as f64 - mean_residual);

    // Late in the stream, consolidate more aggressively (fewer new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, expensive later.
        score += 15.0 * progress;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 500.0; // next item fills this bin perfectly
        } else if diff <= 5.0 {
            score -= 200.0;
        } else if diff <= 15.0 {
            score -= 80.0;
        } else {
            // Penalize leaving large dead space the next item can't use.
            score += diff * 0.8;
        }
        // If next item cannot fit here at all, mild penalty for wasted lookahead.
        if next_item_size > post_residual {
            score += 30.0;
        }
    }

    // Relative to mean residual: prefer bins that are already below-average
    // residual (i.e., fuller bins) to consolidate waste.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.5;
    } else {
        score += (res - mean_residual) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // New-bin candidate handling: make opening a new bin costly unless
    // the current item is large relative to capacity (poor fit everywhere).
    if bin_residual == bin_capacity {
        // New bin starts with full residual; penalize so it's chosen only
        // when open bins are genuinely bad fits.
        score += 120.0;
        // Large items are better served by a fresh bin.
        if item_size > bin_capacity / 2 {
            score -= 150.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 60.0;
    }

    // Prefer placing into bins with small residual overall (fill-first bias).
    score += (bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // When many bins fit the item, penalize consuming a large residual
    // (keep big residual bins for harder future items).
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * (item_size as f64) * 0.3;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // next item would fit this bin only if we place current item elsewhere;
            // slight penalty for destroying that option.
            if bin_residual >= next_item_size && item_size + next_item_size > bin_residual {
                score += 8.0;
            }
        }
        // Reward leaving residual near next item size (chain packing).
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 10.0 / (1.0 + gap);
    }

    // New-bin candidate logic: opening a new bin is fine early or when item is large;
    // penalize opening new bins when existing bins have plenty of room.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + mean_residual * 0.5 - progress * 10.0;
        if item_size > 50 {
            score -= 15.0; // large items are hard to place later
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // new bin can host a pair
        }
    }

    // Global state coupling: when mean residual is high, prefer filling fuller bins.
    score += (mean_residual - post_residual as f64) * 0.2;

    // Mild time-horizon term: late in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr;

    // smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * 0.5;
    score += poly * cap * 0.35;

    // penalize small dead space (waste), reward tight fits
    if pr > 0.0 {
        let dead = (norm_pr * (1.0 - norm_item)).powi(2);
        score += dead * cap * 0.6;
    }

    // lookahead: favor bins leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx) / cap;
        if gap >= 0.0 {
            score -= gap * gap * cap * 0.25;
        } else {
            score += (-gap) * cap * 0.15;
        }
    }

    // last-chance bonus: only one fitting bin -> prefer using it over new bin
    if fitting_bins_count == 1 {
        score -= cap * 0.3 * (1.0 - progress);
    }

    // new-bin candidate: penalize mildly, more so late in the stream
    if bin_residual == bin_capacity {
        score += cap * (0.25 + 0.5 * progress);
    } else {
        // deviation from mean residual: prefer bins near average to balance load
        let dev = (pr - mean_residual) / cap;
        score += dev.abs() * cap * 0.1;
    }

    // mild open-bin pressure
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fraction.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity left over

    // Dead-space penalty: residuals that are too small to host typical items are bad.
    // Harmonic thresholds: 1/8, 1/4, 1/2 of capacity.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < cap / 8.0 {
        score += 45.0; // tiny dead space, nearly unusable
    } else if post_residual < cap / 4.0 {
        score += 18.0;
    } else if post_residual < cap / 2.0 {
        score -= 8.0; // half-class leftovers can host mid-size items
    } else {
        score -= 15.0; // large residual: bin stays useful
    }

    // Modulo arithmetic on post_residual: residuals matching common item-size classes
    // (multiples of 5 and 10) are more likely reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 10.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
            // integer-division class match: next item divides residual nicely
            if post_residual % next_item_size.max(1) == 0 {
                score -= 8.0;
            }
        } else {
            score += 6.0; // next item won't fit here; residual likely stranded
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post residual would be terrible dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual < cap / 8.0 && post_residual > 0 {
            score += 10.0; // still penalize extreme dead space a bit
        }
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it wins
    // only when all open bins would create bad fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening fresh bins is less useful; prefer filling.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer bins tighter than average (best-fit flavor with mean coupling).
    score += 0.35 * (bin_residual as f64 - mean_residual);

    // Slight preference for packing into existing bins as open-bin count grows.
    score += 1.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
