    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin (bin proliferation).
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But a fresh bin gives perfect residual == capacity - item; reward that.
        score -= 0.5 * post_residual as f64;
        // If the next item could combine with the post residual in this new bin,
        // opening a new bin is attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
        // If no open bin fits well (many fitting bins but bad fit), new bin less penalized.
        if post_residual < 10 {
            score -= 35.0;
        }
    } else {
        // Existing bin: penalize wasting capacity relative to mean residual.
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        // If next item fits exactly in the post residual, big reward.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 45.0;
        }
    }

    // Pressure from many open bins: prefer consolidating into existing bins.
    score += 0.05 * open_bins_count as f64;

    // Late in the stream, slightly prefer tight fits to close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

