    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when good fits exist, unless residual is tiny
    if bin_residual == bin_capacity {
        score += 80.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 40.0; // new bin useful if next item is big too
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (post_residual as f64);

    // Penalize creating dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable slivers are wasted capacity
    } else if post_residual >= 10 && post_residual <= 80 {
