            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are bad (large post_residual relative to item) or few bins fit.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score = (bin_capacity - item_size) as f64;
        // if many bins fit, prefer reusing an existing one
        if fitting_bins_count > 1 {
            score += 25.0;
        }
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // if mean residual across open bins can accommodate the item, discourage new bin
        if mean_residual >= item_size as f64 {
            score += 20.0;
        }
        // perfect-fit opportunity in an existing bin strongly discourages new bin
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 5.0;
        }
    }

    // Global state coupling: many open bins with high mean residual -> encourage
    // filling the emptiest-looking bins (post_residual relative to mean).
    if open_bins_count > 0 {
        let rel = (post_residual as f64) - mean_residual;
        score += 0.15 * rel;
    }

    // Mild time-horizon exploration: early stream slightly favors compact placements,
    // late stream favors any fit that avoids new bins (already covered above).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
