            score -= 100.0;
        }
        if progress > 0.9 && pressure > 0.4 {
            score -= 20.0;
        }
    }

    // Mild preference for tighter-than-average bins
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Prefer denser packing as stream progresses
    score -= 0.05 * (step_index as f64 / (total_items.max(1) as f64)) * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
