            score -= 150.0 * (1.0 - slack / bin_capacity as f64); // prefer small slack after next item
        } else {
            // next item can't fit here; penalize dead space relative to next item
            score += 50.0 + 0.5 * (nxt - pr);
        }
        // coupling with mean residual: bins deviating above mean are less attractive
        score += 0.3 * (pr - mean_residual);
    } else {
        // last item: minimize waste
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate handling: only prefer fresh bin when existing fit is terrible
    if bin_residual == bin_capacity {
        score += 40.0 + 0.4 * post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Slight preference for compacting many bins early in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.1 * (1.0 - progress) * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize wasted space nonlinearly (small post_residual is good).
    let frac_used = item_size as f64 / bin_residual as f64;
    score -= frac_used * frac_used * 30.0;

    // Perfect fit gets a big bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Lookahead: reward bins whose leftover can host the next item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that cannot host the next item: penalize proportionally.
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Discourage opening new bins when good open bins exist and load is spreadable.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer it only if mean residual across open bins is small
        // (open bins are nearly full) or many bins already exist late in the stream.
        let open_pressure = mean_residual / bin_capacity as f64;
        score += 60.0 - 80.0 * open_pressure - 10.0 * progress;
        // If the item fits poorly anywhere (large residual would remain), new bin is fine.
        if item_size >= bin_capacity - 10 {
            score -= 30.0;
        }
    } else {
        // Slight preference for bins with residuals near the mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Early in the stream, be more liberal with opening bins (exploration);
    // late, consolidate into existing bins.
    score += 5.0 * (1.0 - progress) * (bin_residual == bin_capacity) as i32 as f64;

    // Mild penalty for using bins when many are open (avoid bin explosion).
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post_residual (lower is better fit)
    let mut score = post;

    // Smooth polynomial coupling: post_residual weighted by stream progress.
    // Early on, prefer tight fits mildly; late in stream, penalize large residuals more strongly.
    let pw = post / cap;
    let coupling = pw * pw * (1.0 + 2.0 * progress) * cap * 0.5;
    score += coupling;

    // Reward using nearly-full bins: smooth cubic bonus for small post_residual
    let tightness = 1.0 - pw;
    score -= tightness * tightness * tightness * item_size as f64 * 0.3;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: penalize if post_residual can't fit next item
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size {
            score += next_item_size as f64 * 0.4 * (0.5 + progress);
        } else {
            score -= 3.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post) * 0.2;

    // Mild penalty for proliferating bins
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual space: classify by integer division bands.
    // Classes: [0..10) dead space, [10..30) small, [30..60) medium, [60..100) large.
    let class = post_residual / 10; // 0..=10 harmonic index
    let class_weight: f64 = match class {
        0 => 40.0,                       // dead space: almost unusable, heavy penalty
        1 => 6.0,                        // fits only tiny items
        2 => 2.0,                        // small
        3..=5 => 0.0,                    // medium: healthy residual
        _ => -3.0,                       // large residual is fine (near-empty bins)
    };
    score += class_weight;

    // Dead-space penalty scaled by how "wasted" the capacity fraction is.
    if post_residual < 10 {
        score += 60.0 * (1.0 - (item_size as f64) / (bin_capacity as f64));
    }

    // Lookahead harmony: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportionally to how snugly the next item nests.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
            score -= 18.0 * snug;
        } else {
            // Next item won't fit: penalize if this bin leaves an awkward gap.
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; make it
    // moderately attractive only when current bins would leave bad residuals.
    if bin_residual == bin_capacity {
        // Baseline neutral-ish score; discourage early-stream bin spawning.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 - 20.0 * progress;
        // If any open bin fits and this item would fit harmonically there,
        // make the new bin less attractive.
        if fitting_bins_count >= 1 && post_residual >= 10 {
            score += 15.0;
        }
        // Open new bins more readily when the fleet is congested with small residuals.
        if mean_residual < 25.0 && open_bins_count > 2 {
            score -= 12.0;
        }
    }

    // Mild congestion term: spreading across many bins is fine, but prefer
    // filling existing ones when the mean residual is already small.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Harmonic modulo coupling: residuals congruent to small mod-20 values
    // pair well with common item sizes; give a small structured reward.
    let m = post_residual % 20;
    if m == 0 {
        score -= 5.0;
    } else if m <= 5 && post_residual >= 10 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 100.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Dead space relative to the known next item.
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // favor filling existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.3 * (0.5 + progress);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when the current bin
        // would leave a large unusable gap or when many bins are open.
        score += 40.0 - (open_bins_count as f64).min(20.0);
        if post_residual as f64 > mean_residual {
            score -= 5.0;
        }
    } else {
        // Slight bonus for fitting into an already-open bin relative to mean.
        if (post_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits strongly.
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let match_quality = 1.0 - ((post_residual as f64 - nxt) / bin_capacity as f64);
            score -= 25.0 * match_quality.powi(2);
        } else if post_residual == 0 {
            // Perfectly closed bin: ideal.
            score -= 35.0;
        } else {
            // Dead space smaller than next item: penalize.
            score += 15.0 * (nxt - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Compare against mean residual: prefer bins that keep residuals balanced,
    // but allow concentrating waste in few bins.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin before opening a new bin: strong reward.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so it only wins when open bins are bad fits.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If the next item is large, opening a fresh bin now may be wise.
        if next_item_size > 50 && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Late in the stream, prefer closing bins tightly (fewer leftover fragments).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space nonlinearly (wasted capacity grows quadratically).
    let dead = post_residual as f64;
    score += 0.012 * dead * dead / bin_capacity as f64;

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            if slack_after_next <= 10 {
                score -= 18.0;
            } else {
                score -= 6.0 * (slack_after_next as f64 / bin_capacity as f64);
            }
        } else {
            // next item cannot follow here; mild penalty proportional to gap
            score += 4.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Time horizon: late in the stream, avoid opening new bins / hoarding residual.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 20.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Global state: many open bins -> prefer consolidation into fuller bins.
    let fullness = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= 10.0 * fullness * (open_bins_count as f64).ln().max(1.0);

    // Compare residual against mean residual: bins with residual below mean are more valuable.
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when current bin is a poor fit or nothing fits well.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_capacity - item_size) as f64;
        let pressure = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        score = 25.0 + 0.3 * poor_fit - 15.0 * pressure - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Normalized post-residual, polynomially coupled with stream progress
    let x = pr / cap;
    let p = x * x * (1.0 - progress) + x * (0.5 + 0.5 * progress);
    score += 12.0 * p * p;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 8.0 * (nx - pr) / cap;
        } else {
            score -= 4.0 * (pr - nx) / cap;
        }
    }

    // Reward tight fits, especially when this is the only fitting bin
    let tight = 1.0 - (pr / cap);
    score -= 6.0 * tight * tight * (fitting_bins_count as f64).recip().min(1.0);

    // Mild penalty for opening new bins as stream progresses
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into a
    // "dead zone" (small, hard-to-fill slivers) are penalized.
    let pr = post_residual as u32;
    let cap = bin_capacity as u32;

    // Perfect fit: reward strongly.
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Dead-space penalty: residual below the smallest item size is unusable.
        if pr < 10 {
            score += 60.0 * (10 - pr) as f64;
        }
        // Harmonic class via integer division: residuals in [10,25) are the
        // hardest to reuse (only tiny items fit) -> penalize; [50,100] are
        // flexible -> mild reward.
        let class = pr / 25; // 0..=4 harmonic class
        score += match class {
            0 => 25.0,  // 10..24: nearly dead
            1 => 10.0,  // 25..49: medium
            2 => -5.0,  // 50..74: good
            _ => -10.0, // 75..99: very reusable
        };
        // Fine-grained modulo structure: residuals divisible by 10 pair well
        // with typical item sizes.
        if pr % 10 == 0 {
            score -= 4.0;
        }
        if pr % 5 == 0 {
            score -= 2.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, reward heavily (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr && pr > 0 {
            score -= 300.0;
        } else if next_item_size <= pr {
            // Next item fits: residual class after the hypothetical pair.
            let pr2 = pr - next_item_size;
            if pr2 < 10 {
                score += 20.0; // would create dead space
            } else {
                score -= 10.0;
            }
        }
        // If next item is large and this bin would be emptied now, that's good.
        if next_item_size > pr {
            // Bin closes here; small positive residual wasted.
            score += 0.05 * pr as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && pr < 90 {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when the current item leaves a very poor residual in
    // every open bin — here we penalize the empty bin unless the item is
    // large relative to capacity.
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap as f64;
        // Large items (>70% of capacity) are fine in fresh bins; otherwise
        // discourage wasting a fresh bin.
        if frac <= 0.7 {
            score += 35.0 + 40.0 * (0.7 - frac);
        } else {
            score += 5.0;
        }
        // Early in the stream, opening bins is cheaper (more future items).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Mean-residual coupling: when open bins are on average loose, prefer
    // filling them rather than fragmenting.
    if bin_residual != bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.15 * dev;
    }

    // Slight preference to balance open bins count: many open bins with
    // slack favors consolidation.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead-space gaps harshly (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual is "compatible" with the lookahead item.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 25.0; // chain fit: next item exactly fills
        } else if gap > 0 && gap < 10 {
            score += 15.0; // leaves a new dead gap for next item
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Pressure when too many bins are open: discourage spreading items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.7 * progress);

    // Prefer bins with residual close to mean (balanced packing), penalize outliers.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: make it attractive only when current bin would leave bad gap.
    if bin_residual == bin_capacity {
        // Baseline for fresh bin: competitive unless existing bins fit well.
        score = 50.0 + (post_residual as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: after placing, residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect match (within small slack) still rewarded.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff <= 5 {
            score -= 25.0 - (diff as f64) * 3.0;
        }
        // Penalize dead space: residual too small for the next item (wasted gap).
        if post_residual < next_item_size && post_residual < 10 {
            score += 20.0;
        }
    }

    // Tight overall fit reward (small post residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Compare against mean residual: bins already fragmented are less precious.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space: post residual that can't fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: reward bins whose post_residual fits the next item well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; mild penalty scaled by how close we were
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes mean residual of open bins
    if bin_residual == bin_capacity {
        let waste = mean_residual * open_bins_count as f64;
        // prefer new bin only when open bins are crowded or fit is bad
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (mean_residual / bin_capacity as f64) - (item_size as f64 / bin_capacity as f64);
        if pressure < 0.15 {
            score -= waste * 0.05 + 10.0 * progress;
        } else {
            score += waste * 0.08 + 40.0;
        }
    }

    // Time horizon: early on, be conservative (keep bins flexible); late, pack aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Prefer filling bins when many bins are open (consolidation)
    score += open_bins_count as f64 * 0.3 * fit_ratio;

    // Slight preference for bins below mean residual (balance)
    score += 0.5 * (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress * (1.0 - progress);
    score += 30.0 * poly;

    // Reward tight fits more strongly as stream advances.
    let tightness = 1.0 - norm_pr;
    score -= 20.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that can't fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr > 0.0 && pr < nxt {
            score += 15.0 * (1.0 - pr / nxt) * (0.5 + progress);
        } else {
            score -= 8.0 * (pr / (pr + nxt)) * (1.0 - progress);
        }
    }

    // Last-chance bin bonus.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Slight preference to keep bins balanced relative to mean residual.
    score += 0.05 * (pr - mean_residual).abs();

    // Mild penalty for spreading across many open bins.
    score += 0.3 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: perfect-fit classes get strong rewards.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 10.0;
    } else {
        // modulo classes: residuals divisible by common small sizes are reusable
        if pr % 10 == 0 { score -= 12.0; }
        else if pr % 5 == 0 { score -= 6.0; }
        else if pr % 25 == 0 { score -= 9.0; }
        else if pr % 50 == 0 { score -= 15.0; }
        else { score += 4.0; } // awkward odd residual
    }

    // Dead-space penalty: residual too small for the smallest plausible item
    if pr > 0 && pr < 10 {
        score += 35.0;
    }

    // Lookahead coupling: reward if the next item exactly fits post-residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size < pr && pr - next_item_size <= 5 {
            score -= 30.0;
        } else if next_item_size > pr {
            // next item won't fit here; slight penalty for hoarding space
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: baseline score of a fresh bin; make it attractive only
    // when current bin would leave large waste or next item needs more space.
    if bin_residual == bin_capacity {
        score = cap * 0.5 - 10.0; // neutral-ish baseline
        if next_item_size > 0 && next_item_size > post_residual && post_residual < 20 {
            score -= 15.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer fuller bins (smaller residual before placement) mildly
    score += (bin_residual as f64) * 0.05;
    // Slight preference for bins below mean residual (tighter bins)
    score += 0.02 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for tiny unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Prefer bins whose residual was already tight (best-fit flavor).
    score += 0.15 * (bin_residual as f64 - post_residual as f64);

    // Penalize bins far from mean residual (outliers keep flexibility).
    score += 0.25 * ((bin_residual as f64 - mean_residual).abs());

    // Last fitting bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, avoid opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = 30.0 + 0.6 * open_bins_count as f64 + 20.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item won't fit here: mild penalty for stranding space
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer perfect or near-perfect fills.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can
    // exactly (or nearly) host the next item.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let exact = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 150.0 / (1.0 + exact);
        // Extra reward for a perfect 2-chain (item + next fills bin exactly).
        if post_residual == next_item_size {
            score -= 250.0;
        }
    } else if next_item_size > 0 {
        // Post-residual too small for the next item: penalize dead space
        // proportionally to how close it came (wasted potential).
        let gap = next_item_size as f64 - post_residual as f64;
        if gap < 20.0 {
            score += 40.0 + gap;
        } else {
            score += 15.0; // small dead space, mild penalty
        }
    }

    // Compare against mean residual: bins with residual below average are
    // "tight" bins — prefer packing into them to consolidate space.
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.8;
    } else {
        score += (residual_f - mean_residual) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Late in the stream, consolidate aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 25.0;

    // Mild penalty when many bins are open — encourage closing them out.
    score += open_bins_count as f64 * 1.5;

    // Slight bias toward using fuller bins (smaller bin_residual) overall.
    score += residual_f * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0 + 0.15 * next_item_size as f64;
    }
    // If next item nearly fits (within 10), mild reward.
    else if next_item_size > 0 && post_residual as f64 + 10.0 >= next_item_size as f64 {
        score -= 3.0;
    }

    // New-bin candidate handling: only open a new bin when the item is large
    // relative to available alternatives or existing residuals are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let pressure = (open_bins_count as f64).ln() * 2.0;
        // Penalize new bins generally, less so when big items or high fragmentation.
        score += 20.0 + pressure - 0.25 * fragmentation
                 - 15.0 * (item_size as f64 / bin_capacity as f64)
                 - 10.0 * progress;
    } else {
        // Slight bonus for keeping bins balanced against mean residual.
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Mild reward for filling bins deeply as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;

    // Base: prefer small post-residual (tight fit), with non-linear sharpening.
    let norm_post = post / cap;
    let mut score = norm_post * norm_post * (1.0 + 2.0 * norm_post);

    // Smooth non-linear interaction: tight fits matter more as the stream progresses.
    let tightness = 1.0 - norm_post; // 1 = perfect fit
    score -= tightness * tightness * (0.5 + 2.5 * progress * progress);

    // Penalize bins that leave residuals that can't host typical upcoming items,
    // coupled with mean residual context.
    let dead = norm_post * (1.0 - norm_post);
    let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
    score += dead * (1.5 + 2.0 * (1.0 - mean_norm)) * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it.
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 + progress);
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = (post - nxt) / cap;
            score -= (1.0 - gap) * (1.0 - gap) * (1.5 + 2.0 * progress);
        } else {
            // Next item won't fit here: mild penalty for wasteful ordering.
            score += 0.5 * (nxt - post) / cap;
        }
    }

    // New-bin candidate (empty bin): penalize opening new bins early or when
    // alternatives exist; allow opening late when residuals are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (open_bins_count as f64 / (1.0 + mean_residual)).min(2.0);
        score += 2.0 + 3.0 * (1.0 - progress) + 1.5 * fragmentation;
        if fitting_bins_count <= 1 {
            score -= 4.0; // opening a new bin is fine if no good alternative exists
        }
    }

    // Slight preference for filling larger-residual bins first (best-fit-like).
    score += 0.3 * (res / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual;

    // Perfect fit: dominant reward, always take it.
    if pr == 0 {
        return -1000.0;
    }

    let is_new_bin = bin_residual == bin_capacity;
    let last_item = next_item_size == 0;
    // The leftover can directly host the next item (chained fill).
    let chainable = next_item_size > 0 && next_item_size <= pr;
    // A brand-new bin could host current item + next item together.
    let new_can_chain = next_item_size > 0
        && next_item_size > pr
        && next_item_size <= bin_capacity.saturating_sub(item_size);

    let mut score = pr as f64;

    // --- Harmonic class structure of the leftover (modulo / divisibility of C) ---
    if bin_capacity % pr == 0 { score -= 4.0; }        // leftover tiles capacity cleanly
    if pr % 25 == 0 { score -= 2.0; }
    if pr % 10 == 0 { score -= 1.0; }
    if pr > 1 && (pr + 1) % 25 == 0 { score += 2.0; }  // just-off-divisor dead space
    else if pr > 1 && (pr + 1) % 10 == 0 { score += 1.0; }
    if pr >= 20 && pr <= 60 { score -= 1.0; }          // sweet-spot reusable leftover
    if pr < 10 { score += 0.5; }                       // fragile sliver

    if chainable {
        // Tiling quality of leftover by the next item's size class.
        let r2 = pr % next_item_size;
        score -= 3.0 + next_item_size as f64 * 0.03 - r2 as f64 * 0.05;
        if r2 == 0 { score -= 3.0; }                   // harmonic tiling: perfect reuse
        if next_item_size == pr { score -= 5.0; }      // exact chain fit
    } else if new_can_chain {
        // This bin cannot take the next item, but a fresh bin can host both: delegate.
        score += 60.0;
    } else if last_item {
        score -= 10.0;                                 // never open a bin for the final item
    } else {
        // Next item needs its own bin no matter what: pure best-fit among open bins.
        score -= 100.0;
    }

    // Last-chance bonus: avoid spawning a bin when this is the only fitting one.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 5.0;
    }

    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 45.0 + progress * 5.0 + open_bins_count as f64 * 0.1;
        if new_can_chain { score -= 12.0; }            // chaining justifies a new bin
        if chainable { score += 40.0; }                // an open bin already chains: lose
        if last_item || (!new_can_chain && !chainable) { score += 1000.0; }
    } else if mean_residual > pr as f64 {
        // Tighter than the fleet average: mild reward, capped.
        score -= ((mean_residual - pr as f64) / bin_capacity as f64).min(0.2) * 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, heavily reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Strict dead-space avoidance: penalize unusable tiny gaps.
    // A gap is "dead" if it's smaller than the minimum plausible item size.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < 10 {
        // Tiny sliver: nearly unusable dead space.
        score += 60.0 + 4.0 * (10 - post_residual) as f64;
    } else if post_residual >= 10 && post_residual < 20 {
        // Small gap: usable only by very small items; moderate penalty.
        score += 15.0 + 1.5 * (20 - post_residual) as f64;
    }

    // Prefer residual that can still host the next item (lookahead synergy).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Room for the next item: reward proportionally.
            score -= 10.0 + 0.3 * next_item_size as f64;
        } else if post_residual > 0 {
            // Gap cannot host next item: mild penalty scaled by wasted fraction.
            let waste = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 20.0 * waste;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's residual is already tight/dead-space prone.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, modulated by open-bin pressure.
        score += 25.0 + 3.0 * open_bins_count as f64;
        // If the current bin would leave a dead gap, opening fresh is better:
        // (handled implicitly since dead gaps add penalties to open bins).
        // Reward new bin slightly if item is large relative to capacity.
        score -= 0.1 * item_size as f64;
    } else {
        // Open-bin pressure: mild penalty per open bin to encourage consolidation.
        score += 0.5 * open_bins_count as f64;
    }

    // Progress-aware tightening: later in the stream, be more conservative
    // about residual waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already tight — favor using it up.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 && bin_res_f < mean_residual {
        score -= 8.0 * (mean_residual - bin_res_f) / mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact or near-exact fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let tightness = 1.0 - (post_residual as f64 - nxt) / bin_capacity as f64;
            score -= 25.0 + 40.0 * tightness;
            // Perfect chain: next item exactly fills the bin afterwards.
            if (post_residual as f64 - nxt).abs() < 1e-9 {
                score -= 300.0;
            }
        } else {
            // Dead space that next item cannot use — penalize.
            score += (post_residual as f64 - nxt).min(50.0);
        }
    }

    // Compare against mean residual: prefer bins that are already small-residual
    // (tight packing) rather than large empty bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 0.3 * post_residual as f64;
    }

    // Penalize wasting a nearly full bin's remaining sliver on a small item
    // when a new bin could take it just as well.
    if post_residual > 0 && (post_residual as f64) < (item_size as f64) * 0.2 {
        score += 10.0;
    }

    // Early in the stream, slightly favor consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * progress * 0.5;

    // New-bin candidate: keep it neutral-ish but make it less attractive than
    // a good fit into an existing bin.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste ratio weighting (quadratic penalty on dead space).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * waste_frac * waste_frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
            // Extra reward for near-perfect chaining (post_residual ~= next item).
            let chain_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 15.0 * (1.0 - chain_gap / bin_capacity as f64);
        } else {
            // Next item won't chain here; penalize leaving a large unusable gap.
            score += 10.0 * waste_frac;
        }
    } else {
        // Last item in stream: just minimize waste directly.
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a decent fit
    // or the stream is early and future capacity is valuable.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fits = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let open_penalty = (open_bins_count as f64).ln().max(0.0);
        // Opening a new bin is penalized mildly; discount as stream progresses.
        score += 30.0 + 20.0 * open_penalty - 35.0 * poor_fits - 20.0 * progress;
        // If the current item is large, a fresh bin keeps flexibility.
        score -= 0.2 * item_size as f64;
    }

    // Prefer bins below mean residual when waste is similar (balance residuals),
    // discouraging fragmentation across many bins.
    if bin_residual != bin_capacity {
        let dev = bin_residual as f64 - mean_residual;
        score += 0.15 * dev;
    }

    // Small late-stream tie-breaker: prefer filling older (smaller-residual) bins.
    score += 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_post * (1.0 + 0.8 * progress * norm_post - 0.3 * progress * progress);

    let mut score = poly * cap;

    // Reward tight fits via smooth quadratic term on post_residual
    score -= 2.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 + progress);

    // Penalize dead space relative to mean residual (smooth cubic interaction)
    let dead = (norm_post - (mean_residual / cap)).abs();
    score += 3.0 * dead * dead * dead * cap;

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 {
        score -= 5.0 + 4.0 * progress;
    }

    // Lookahead: reward bins whose post-residual can fit next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 1.5 * (nxt / cap) * (1.0 - progress);
        } else {
            score += 1.0 * ((nxt - post) / cap) * (1.0 + progress);
        }
    }

    // Mild penalty for spreading across too many open bins
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: prefer opening fresh bin late in stream only if fit is poor
    if bin_residual == bin_capacity {
        score = cap * (0.6 + 0.5 * progress) + norm_post * 0.0;
        if item_size as f64 / cap < 0.5 && progress < 0.7 {
            score += cap; // discourage new bins for small items early
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small dead-space classes" are more valuable to fill exactly.
    let post = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Modulo-class logic: residuals congruent to small values mod common
    // item sizes (10, 20, 25, 50) are reusable by future items.
    let reusable = (post_residual % 10 == 0)
        || (post_residual % 20 == 0)
        || (post_residual % 25 == 0)
        || (post_residual % 50 == 0);
    if reusable && post_residual > 0 {
        score -= 6.0;
    }

    // Penalize awkward dead space: residual in (0,10) other than exact small
    // classes is likely unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Coupling with next item: if the next item fits exactly in the post
    // residual, this is a great chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; mild penalty if we waste a scarce bin.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Tightness ratio: prefer bins where the item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_ratio;

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large and few bins fit it.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = item_size as f64 / cap;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a bin
        } else if big_item > 0.6 && fitting_bins_count <= 2 {
            score -= 5.0 * big_item * (0.5 + progress);
        } else {
            score += 30.0; // prefer existing bins generally
        }
    }

    // Slight preference to consolidate: bins below mean residual are looser;
    // filling them keeps mean residual low.
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    // Late-stream consolidation: fewer open bins is better near the end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1..10)
    // can ever use are pure waste. Penalize tiny gaps heavily.
    if post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual < 20 {
        score += 8.0 * (20.0 - post_residual as f64);
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last chance: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer reusing existing
    // capacity over spawning new bins.
    let pressure = open_bins_count as f64 * 0.8;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins fit poorly.
        score += 15.0 + pressure;
        // Lookahead: opening a fresh bin is good if the next item is large
        // and would leave this bin awkwardly filled.
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 12.0;
        }
    } else {
        score -= pressure * 0.5;
        // Lookahead synergy: placing here is good if next item still fits
        // the resulting residual.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 6.0;
            } else if post_residual > 0 && post_residual < next_item_size {
                score += 4.0;
            }
        }
    }

    // Prefer bins tighter than the mean (best-fit style coupling).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Late in the stream, be more conservative about new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when the next item fits into the post-residual (2-step lookahead match)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use
        score += 0.3 * (post_residual as f64 - (next_item_size as f64).min(post_residual as f64));
    }

    // Compare post_residual against mean residual: prefer bins that end tighter than average
    score += 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize leaving tiny unusable fragments
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 30.0 - 0.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize unusable dead space: residual too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: reward bins whose post_residual can fit the next item exactly or well
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty
            score += 5.0;
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer filling bins that are already more depleted (larger item_size used ratio)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Time horizon: early in stream, be more willing to open new bins (penalize tight old bins less);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64; // = capacity - item_size
        // base cost of opening a new bin
        let mut new_bin_score = 100.0 + 0.3 * open_bins_count as f64;
        // if item is large relative to capacity, new bin is fine
        new_bin_score -= 0.5 * item_size as f64;
        // if many bins are open with high mean residual, opening new bins fragments capacity
        new_bin_score += 0.2 * mean_residual;
        // late in stream, discourage new bins more
        new_bin_score += 40.0 * progress;
        // if this is a last-chance situation, discourage new bin
        if fitting_bins_count >= 1 {
            new_bin_score += 25.0;
        }
        let _ = poor_fit;
        score = score.min(new_bin_score);
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / c;

    // Base: prefer small post-residual, but non-linearly (dead space penalty grows quadratically)
    let mut score = pr + 40.0 * norm_pr * norm_pr * c;

    // Tight fits rewarded more as stream progresses
    score -= 20.0 * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // Penalize leaving residual that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 15.0 * (1.0 - pr / nx.max(1.0)) * (1.0 - norm_pr);
        } else {
            score -= 10.0 * (1.0 - norm_pr) * (1.0 - nx / c);
        }
    }

    // Last-chance bin bonus: avoid opening a new bin when few fit
    if fitting_bins_count <= 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // Smooth coupling with mean residual: prefer bins below mean residual (tighter packing)
    score += 5.0 * ((bin_residual as f64) - mean_residual) / c;

    // Late stream: mild pressure to consolidate into existing bins
    score -= 10.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: post_residual 0 is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Harmonic class of post_residual: residuals that are "friendly" to
    // common item sizes (multiples of small divisors) are more reusable.
    let pr = post_residual;
    let harmonic = if pr == 0 { 0 } else {
        let mut h = 0u32;
        for d in [10u32, 20, 25, 50] {
            if pr % d == 0 { h += 1; }
        }
        h
    };
    score -= harmonic as f64 * 6.0;

    // Dead space penalty: residuals too small for the smallest item (1..10)
    // are nearly useless unless zero.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Next item still fits comfortably: mild reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Next item cannot fit: this residual will strand; penalize proportionally.
    if next_item_size > post_residual && post_residual > 0 {
        score += (next_item_size - post_residual) as f64 * 0.3;
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has full residual; make it
    // unattractive when decent open bins exist, attractive when bins are
    // fragmented (high mean residual spread with many bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        // Penalize new bin mildly; reduce penalty if open bins look fragmented.
        score += 10.0 + 8.0 * (1.0 - progress) - fragmentation.min(20.0) * 0.4;
        // If the item is large and few bins fit it, a fresh bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Mild preference to fill more-full bins first (smaller residual chosen).
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    // Slight pressure to consolidate as bins accumulate.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable dead space
    // since items are >= 1 but small gaps fragment capacity. Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit: strongly reward
    if post_residual == 0 {
        score -= 60.0;
    }
    // Reward leaving a gap exactly matching the lookahead item (or >= it comfortably)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            // gap cannot host next item: mild penalty scaled by how much is wasted
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Tightness reward: fraction of bin consumed by this placement
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 30.0;

    // Open-bin pressure: discourage scattering across many bins unless fit is good
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible (huge dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin has moderate default score.
    // Prefer it only when current bin would leave a bad gap.
    if bin_residual == bin_capacity {
        // baseline: slightly worse than a good fit, better than a bad fit
        score += 15.0;
        // early in stream, opening bins is cheap; later, prefer reusing
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // if many bins already open, opening yet another is costly
        score += open_bins_count as f64 * 0.8;
    }

    // Deviation from mean residual: bins with residual near mean are "typical";
    // prefer filling bins with small residual (close to full) more aggressively.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact match: item fills bin perfectly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual,
    // heavily reward this placement (chain of perfect fits).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item can still be placed here: moderate reward, scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 100.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize wasted space relative to next item
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize leaving dead space that is too small for typical items (below min size 1 => any residual >=1 usable, but small residuals are risky)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Prefer bins with residuals below the mean residual (tighter bins first),
    // keeping large-residual bins available for future large items.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Prefer using already-open bins over opening a new one, mildly.
    if bin_residual == bin_capacity {
        // candidate new bin: neutral base; add small penalty so open bins win on ties
        score += 10.0;
        // but if current open bins would leave big dead space, new bin becomes attractive
        if post_residual < item_size as f64 * 0.0 {
            score -= 0.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin can chain the next item too
        }
    }

    // Late in the stream, consolidate more aggressively (fewer wasted partial bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty for having many open bins: encourage filling existing ones.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Is this a brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Dead-space penalty: residual too small to ever hold anything useful
    // is worse the smaller it is, but only if it's below the smallest
    // plausible upcoming demand. Use lookahead + a fraction of capacity.
    let min_useful = if next_item_size > 0 { next_item_size.min(20) } else { 20 };
    if post_residual < min_useful {
        score += (min_useful - post_residual) as f64 * 12.0;
    }

    // Lookahead coupling: reward bins whose post-residual can host the next item,
    // penalize otherwise (chain-friendly placements).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64) * 1.5;
        } else {
            score += (next_item_size - post_residual) as f64 * 2.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    // Crowding pressure: with many open bins, prefer consolidating into
    // existing ones rather than spawning more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = (open_bins_count as f64).ln().max(0.0);
    if !is_new_bin {
        score -= crowding * (2.0 + 6.0 * progress);
    } else {
        // New bin: baseline cost grows with crowding and stream progress.
        score += 25.0 + 40.0 * progress + crowding * 4.0;
        // If the mean residual across open bins is large, opening a new bin
        // is wasteful; penalize.
        score += (mean_residual / bin_capacity as f64) * 80.0;
        // If no existing bin fits well (post_residual of this new bin is full
        // capacity minus item), that's the natural value; but if the item is
        // small, discourage spreading.
        if item_size < 30 {
            score += 30.0;
        }
    }

    // Slight preference for filling larger residual bins when many fit
    // (keeps small-residual bins available for small items).
    if fitting_bins_count > 1 && !is_new_bin {
        score += (bin_residual as f64) * 0.05;
    }

    // Mild noise-free time coupling: early in the stream, be conservative
    // with tight fits (leave room); later, pack aggressively.
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item / cap;

    // Base: prefer tight fits (small post_residual), with mild convexity.
    let mut score = norm_pr + 0.35 * norm_pr * norm_pr;

    // Smooth polynomial coupling: waste relative to mean residual, scaled by progress.
    let waste = (pr as f64 - mean_residual) / cap;
    score += 0.9 * waste * (0.5 + progress);

    // Perfect-fit reward: smooth Gaussian-like term on post_residual near zero.
    score -= 1.2 * (-norm_pr * norm_pr / 0.02).exp();

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5 * (1.0 - progress);
    }

    // Lookahead: penalize post_residual that barely fails to fit next item,
    // reward post_residual that accommodates it exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        let gap = norm_pr - nxt;
        if gap < 0.0 {
            score += 0.6 * (-gap) * (1.0 - progress);
        } else {
            score -= 0.4 * gap * gap;
        }
    }

    // New-bin candidate: penalize opening bins when good fits exist,
    // more so early in the stream; relax slightly late.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 0.8 + 0.5 * (1.0 - progress) + 0.02 * open_f;
        // But allow new bin if all fits are terrible (smooth via mean_residual).
        score -= 0.3 * (mean_residual / cap);
    }

    // Mild pressure to consolidate: many open bins -> favor filling existing ones.
    score += 0.015 * open_bins_count as f64 * norm_pr;

    // Small item into big hole late in stream: discourage dead space.
    score += 0.5 * norm_pr * norm_item * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class: dead space in small residual classes is worse.
    // Class 0 (perfect fit) gets strong reward; classes 1..=9 penalized.
    let cls = post_residual % 10;
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if cls == 0 {
        score -= 15.0; // multiple-of-10 residual stays usable
    } else if cls <= 3 {
        score += (4 - cls) as f64 * 8.0; // tiny dead space penalty
    }

    // Fractional capacity coupling: residual as fraction of capacity.
    let frac = post_residual as f64 / cap;
    if frac < 0.1 {
        score += 12.0; // near-full bin: fine, but don't over-favor
    } else {
        score -= 10.0 * (1.0 - frac); // reward leaving large usable space
    }

    // Lookahead harmonic: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: bonus scaled by how cleanly it fits after
            let next_post = post_residual - next_item_size;
            score -= 10.0 + (next_post % 10 == 0) as i32 as f64 * 8.0;
        } else {
            // next item won't fit here: penalize leaving awkward space
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins mildly unattractive
    // unless the item is large relative to capacity (avoid fragmentation).
    if bin_residual == bin_capacity {
        score += 20.0 + (item_size as f64 / cap) * 10.0;
        if item_size >= 60 {
            score -= 15.0; // big items justify fresh bins
        }
    }

    // Stream progression: early on, be conservative with open bins;
    // late, pack tightly to close out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));

    // Mean residual coupling: if this bin's residual is far below mean,
    // it's already tight — reward filling it.
    let diff = mean_residual - bin_residual as f64;
    score -= 0.05 * diff.max(-30.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible item (1..=10) are pure waste — penalize them hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 25.0;
    }
    // Reward tight fits relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Dead space that cannot host the lookahead item is extra bad.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // If the residual can host the next item, reward it (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 6.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // opening a new bin is penalized implicitly via high post_residual (== capacity),
    // but add explicit pressure proportional to open bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, increasingly penalized later
        // and when many bins are already open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + open_bins_count as f64 * 2.5 + progress * 20.0;
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it to avoid a new bin.
        score -= 18.0;
    }

    // Prefer bins with residual close to item (best-fit flavor) using mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // next item won't fit: penalize leftover dead space, worse when small
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Prefer bins tighter than mean residual (best-fit flavor)
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 100.0 + 50.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 80.0; // new bin can host both current and next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Reward tight fits nonlinearly: residual^1.5 grows fast, so small leftovers dominate.
    score = (post_residual as f64).powf(1.5) / cap.sqrt();

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0; // near-perfect fit
    }

    // Dead-space penalty: leftover that cannot fit typical next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (post_residual as f64);
    }

    // Lookahead synergy: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early in the stream
    // and when many open bins still have slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 25.0 + 0.5 * open_bins_count as f64 + 20.0 * (1.0 - progress);
        // But if the item is huge relative to capacity, a fresh bin is natural.
        penalty -= 0.3 * (item_size as f64);
        // If mean residual across bins can't fit the item comfortably, soften penalty.
        if (mean_residual - item_size as f64) < 5.0 {
            penalty -= 15.0;
        }
        score += penalty.max(0.0);
    }

    // Mild preference for bins with less residual than average (concentrate waste).
    score += 0.1 * ((bin_residual as f64) - mean_residual).abs();

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: quadratic post-residual modulated by progress
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress) * cap;

    // Cubic term penalizing very small residuals (dead space), stronger later in stream
    score += 8.0 * norm_pr.powi(3) * (progress + 0.2) * cap;

    // Interaction between item size and progress: prefer large items early
    score -= 6.0 * norm_item * (1.0 - progress) * cap;

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        score += 0.4 * gap;
        if pr >= nx {
            score -= 3.0;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - norm_pr);
    }

    // Crowd penalty: many open bins -> favor tighter fills
    score += 0.15 * open_bins_count as f64 * norm_pr;

    // Mean residual deviation coupling
    score += 0.5 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline with slight progress-dependent cost
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress) + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 2.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by common item
    // quantum (10) are more reusable; odd / prime-ish residues are dead space.
    let q = post_residual % 10;
    score += (q as f64) * 0.9;

    // Perfect fills get a strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tiny dead space (< 10) is unusable: penalize.
    if post_residual < 10 && post_residual > 0 {
        score += 35.0;
    }

    // Reward residuals in "useful" harmonic bands (multiples of 10, 20, 25, 50).
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 12.0;
    } else if post_residual % 25 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 20 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Next fits: prefer small leftover after next placement.
            let after_next = post_residual - next_item_size;
            score -= 10.0 + (after_next % 10) as f64 * 0.5;
            if after_next % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot follow in this bin: penalize proportionally.
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.35;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        // Many options: prefer tighter fits, mild penalty on large residual.
        score += (post_residual as f64) * 0.05;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline: a fresh bin costs like opening it (post_residual = capacity).
        // Penalize slightly so it only wins when open bins waste lots of space.
        score += 15.0;
        // If lookahead item is large and this bin is empty, fresh bin is good
        // for stacking big items early in the stream.
        if next_item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer bins whose residual is already below average (tighter packing).
    let res_f = post_residual as f64;
    if mean_residual > 0.0 && res_f > mean_residual {
        score += (res_f - mean_residual) * 0.15;
    } else if mean_residual > 0.0 {
        score -= (mean_residual - res_f) * 0.10;
    }

    // Integer-division threshold: residual in [1..=9] band is dead; [10..19]
    // barely useful; nudge selection toward >= 20 residual buckets.
    let band = post_residual / 20;
    score -= band as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no item (min size 1, but
    // realistically small gaps) can ever fill are heavily penalized.
    // A post_residual below 10 is "dead" unless exactly 0.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 20 {
            score += 25.0; // nearly dead space
        } else if post_residual < 35 {
            score += 8.0; // only fits very small items
        }
    } else {
        score -= 40.0; // perfect closure, reward strongly
    }

    // Reward tight fits: fraction of bin filled by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Reward using a bin whose residual is well-matched to the item
    // (post_residual small relative to item size => high packing density).
    if post_residual > 0 {
        let density = item_size as f64 / (item_size + post_residual) as f64;
        score -= 15.0 * density;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly prefer filling the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin is a fresh resource; only
    // prefer it when no open bin offers a decent fit (post_residual large
    // relative to item, i.e. bad density) or when few bins are open.
    if bin_residual == bin_capacity {
        let bad_fit_penalty = if post_residual == bin_capacity {
            // evaluating the empty bin itself: post_residual == capacity
            0.0
        } else {
            0.0
        };
        let _ = bad_fit_penalty;
        // Base cost of opening a new bin, discounted early in the stream
        // or when the current fit across open bins is poor.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 30.0 + 25.0 * progress;
        // If mean residual of open bins is large, there is room elsewhere;
        // penalize opening a new bin.
        new_bin_cost += 0.3 * mean_residual;
        // If next item is large, a fresh bin is valuable.
        if next_item_size >= 60 {
            new_bin_cost -= 15.0;
        }
        score += new_bin_cost;
    }

    // Lookahead: if the next item exactly fits the post_residual, reward
    // this placement strongly (chained packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use the leftover: leftover likely becomes dead space
        score += 12.0;
    }

    // Mild normalization: prefer bins with residual close to item size
    // (best-fit core), scaled by how many alternatives exist.
    if bin_residual >= item_size {
        let slack = (bin_residual - item_size) as f64;
        score += 0.15 * slack * (1.0 + fitting_bins_count as f64).ln().max(1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
