pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Penalize leaving dead space that no realistic item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny sliver = wasted capacity
    }
    if post_residual > 50 {
        score += (post_residual as f64 - 50.0) * 0.15; // large leftover less bad, but still track
    }

    // Lookahead: bonus if next item fits exactly in post_residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot follow here; slight penalty proportional to overflow
            score += 2.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Time horizon: early in stream, be more willing to open new bins (keep options open);
    // late in stream, consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_bias = (1.0 - progress) * 6.0 - progress * 4.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score += -new_bin_bias + progress * 5.0;
        // But if many open bins with slack, discourage another new bin.
        score += open_bins_count as f64 * 0.6;
    }

    // Prefer bins whose residual deviates from the mean in a "fillable" way:
    // a bin with residual close to mean residual keeps the pool homogeneous.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild preference for fuller bins overall (best-fit flavor).
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Encourage closing bins: if this placement nearly empties residual, reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling: post_residual shaped by stream progress.
    let norm_pr = pr / cap; // in [0,1]
    let poly = norm_pr * norm_pr * (1.0 - progress) - norm_pr * progress;
    score += 30.0 * poly;

    // Reward tight fits more strongly as stream progresses (smooth interaction).
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + progress) * 12.0;

    // Penalize dead space that cannot fit the lookahead item (smooth gate).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        let unusable = 1.0 - (gap / cap).min(1.0);
        score += unusable * unusable * next_item_size as f64 * (0.3 + 0.7 * progress);
    } else {
        // Last item: strongly favor filling existing bins tightly.
        score -= 25.0 * tightness;
    }

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit.
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild competition penalty scaled by number of alternatives.
        score += (fitting_bins_count as f64).ln() * 3.0 * (1.0 - progress);
    }

    // Encourage consolidation when many bins are open: prefer bins below mean residual.
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * (open_bins_count as f64).sqrt() * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize opening a bin unless residual is very tight elsewhere.
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 18.0 * (1.0 - scarcity) * (0.4 + 0.6 * (1.0 - progress));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting gap: small gaps are dead space, reward them away.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Classify post_residual by integer division into harmonic bands of capacity/5.
        let band = post_residual / (bin_capacity / 5).max(1); // 0..4
        score += band as f64 * 12.0;

        // Modulo-10 harmonic class: gaps that are multiples of 10 are "friendly"
        // for typical item sizes; penalize awkward residues.
        let m = post_residual % 10;
        score += match m {
            0 => -8.0,
            1 | 9 => 6.0,
            2 | 8 => 3.0,
            _ => 0.0,
        } as f64;

        // Reward if next item fits exactly into post_residual (chain packing).
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 400.0;
            } else if next_item_size <= post_residual {
                score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
            } else {
                // next item cannot fit here; slight penalty proportional to gap
                score += 5.0;
            }
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Prefer filling bins that are already relatively full (tight packing).
    score -= 20.0 * (1.0 - bin_residual as f64 / cap);

    // New-bin candidate: only attractive when current item leaves a bad gap
    // or stream is early and we want many bins for future flexibility.
    if bin_residual == bin_capacity {
        // neutral base for fresh bin; make it slightly worse than good fits
        score = cap * 0.35 + (post_residual as f64);
        if step_index * 2 < total_items {
            score -= 10.0; // early stream: allow opening bins
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // pairing next item into fresh bin
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are wasted space.
    // Penalize post_residual that is too small to hold typical items.
    if post_residual > 0 {
        let dead_threshold = 20.0;
        if (post_residual as f64) < dead_threshold {
            // Dead space: heavily penalize proportionally to how useless it is.
            score += (dead_threshold - post_residual as f64) * 6.0;
        } else {
            // Larger leftovers are reusable; mild reward scaled by size.
            score -= ((post_residual as f64) - dead_threshold) * 0.05;
        }
    }

    // Perfect fit bonus: reward tight packing strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly in the leftover,
    // this placement sets up a chain — reward it.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins already below mean residual (fill fuller bins first).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the item is large relative to remaining capacity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base penalty so open bins win unless they leave dead space.
        score += 25.0;
        // Large items are hard to place later; slightly favor new bins early-mid stream.
        if item_size >= 60 {
            score -= 15.0 * (1.0 - progress);
        }
        // If the best alternative would leave heavy dead space, new bin is fine.
        if (bin_residual - item_size) as f64 >= mean_residual {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Exact 2-chain fit: strong reward
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // Penalize leaving dead space the next item can't use
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Penalize small unusable residuals (dead space), scaled by item size
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer tight fits relative to mean residual
    let mr = if mean_residual.is_finite() { mean_residual } else { 0.0 };
    score -= (post_residual as f64 - mr) * 0.15;

    // Last-chance bin bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: mildly penalize so we only open when fits are poor
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if the current item fits perfectly into an empty bin, allow it
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // Early in stream: slightly favor consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing (min size 10) can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual as u64 >= next_item_size as u64 {
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 18.0 / (1.0 + slack);
            if slack == 0.0 {
                score -= 25.0; // perfect chain fit
            }
        } else {
            score += 8.0; // next item can't use this bin's leftover
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when fits are poor or bins are fragmented.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize opening a new bin unless mean residual is low (existing bins nearly full)
        // or this item is huge relative to typical residual.
        let mut penalty = 25.0 + 40.0 * fragmentation;
        penalty *= 0.5 + 0.5 * (1.0 - progress);
        if fitting_bins_count == 0 {
            penalty = -100.0; // must open a new bin
        }
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            penalty += 10.0; // fresh bin gives room for lookahead
        }
        score += penalty;
    }

    // Mild preference for bins with above-average residual when item is large.
    if item_size > 50 && bin_residual as f64 > mean_residual {
        score -= 5.0;
    }

    // Late in stream: consolidate, prefer tighter packing overall.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;

    // Smooth polynomial shaping of post_residual: heavily penalize large leftover space,
    // mildly reward tight fits (small post_residual) via convex coupling.
    let x = pr / cap; // normalized post residual in [0,1]
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep: rises for large waste
    let mut score = base + 25.0 * poly * cap * 0.04;

    // Stream-progress coupling: as stream advances, tolerate less waste.
    score += 15.0 * progress * x;

    // Reward bins whose residual after placement matches the next item (lookahead fit).
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs() / cap;
        score -= 8.0 * (1.0 - diff.min(1.0));
    } else {
        // Last item: prefer minimal leftover.
        score += 5.0 * x;
    }

    // Last-chance bin: strong bonus to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Slight preference for tighter bins relative to the fleet average residual.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild preference against proliferating bins early.
    if bin_residual == bin_capacity {
        score += 6.0 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Penalize dead-space classes: residuals that few future items can use.
    // Items 1..100 => residual classes by integer division thresholds.
    let class = post_residual / 10; // 0..=10 harmonic class
    let class_penalty = match class {
        0 => 40.0,           // nearly full bin, tiny dead space is fine actually
        1 => 8.0,
        2 => 14.0,
        3 => 22.0,
        4 => 30.0,
        5 => 36.0,           // ~50% residual: worst "half-dead" class
        6 => 30.0,
        7 => 22.0,
        8 => 14.0,
        9 => 8.0,
        _ => 0.0,            // empty-ish bin
    };
    score += class_penalty * (1.0 - frac * 0.5);

    // Perfect fits get strong reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward proportionally to how snug the follow-up fit is.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 + 20.0 * snug;
        } else {
            // Leftover can't host next item: penalize dead space, worse when gap is small.
            let gap = (next_item_size - post_residual) as f64;
            score += 6.0 + gap * 0.15;
        }
        // Harmonic class match: post_residual % next_item_size near zero => good chain.
        if next_item_size > 0 && post_residual % next_item_size.max(1) <= 2 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when current bin leaves an awkward class.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 25.0;
        // But if the item is large relative to capacity, fresh bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 20.0;
        }
        // If many open bins exist and mean residual is small, prefer consolidation.
        if mean_residual < item_size as f64 * 0.5 && open_bins_count > 2 {
            score += 20.0;
        }
        // Late in stream, avoid bin proliferation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Prefer tighter (fuller) bins overall: reward low bin_residual.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Small noise-free tie-break via harmonic class of item size.
    score += (item_size % 7) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are nearly useless.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 500.0; // perfect fit: best possible outcome
    } else if post_residual < 10 {
        score -= 120.0; // small dead space, still acceptable
    } else if post_residual < 25 {
        score += 60.0; // moderately wasteful gap
    } else {
        // Large residual: scale penalty by how far from capacity it is
        score += 0.8 * pr;
    }

    // Dead space is worse if the leftover can't fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0; // leftover stays usable
        } else if post_residual > 0 {
            score += 90.0; // leftover becomes pure waste
        }
    }

    // Open-bin pressure: prefer compacting when many bins are open.
    score += open_bins_count as f64 * 3.0;

    // Last-chance bin: strong bonus to use it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when no decent fit exists.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 300.0;
        } else {
            score += 250.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Slight preference to fill emptier bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * (0.15 * (1.0 - progress));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: perfect match where next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-item fill
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            // Reward close matches, decay with gap size.
            score -= 30.0 * (-gap / 15.0).exp();
        } else {
            // Next item cannot fit here; residual becomes dead space unless small.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.35 * dead;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average.
    let rel = (bin_residual as f64) - mean_residual;
    score -= 0.25 * rel;

    // Penalize leaving residual in the classic "useless zone" (1..10) for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Early in stream: be pickier (encourage diverse open bins for later flexibility).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 1.0 };
    score += (1.0 - progress) * 4.0;

    // Slight penalty for opening a brand-new bin when other bins could fit.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 30.0;

    // Penalize small dead space that nothing can use later (dead space sweet spot avoidance)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item does not fit but is close, mildly penalize wasteful exact fills
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // New-bin candidate: only attractive when current fits are poor or many bins are fragmented
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize opening new bins early, allow later when fragmentation is high
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 15.0 + 60.0 * (1.0 - progress) - fragmentation.min(40.0);
        if fitting_bins_count <= 2 {
            score -= 55.0; // few alternatives -> new bin is fine
        }
    }

    // Mild penalty when bin residual is far below mean (keeps residuals homogeneous)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Prefer filling already-open bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Slight penalty for very large open-bin counts (encourage consolidation)
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth interaction: residual squared penalty grows with stream progress
    score += 20.0 * norm_pr * norm_pr * progress;

    // Reward tight fits (small post residual) more strongly later in stream
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * fit * progress;

    // Last-chance bin: strong reward to use it rather than open new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 10.0 * progress;
    }

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 8.0 + 6.0 * (next_item_size as f64 / cap);
    }

    // Penalize bins far below mean residual (keeps balance), smooth coupling
    score += 3.0 * (mean_residual - pr).abs() / cap * (0.5 + progress);

    // New-bin candidate: penalize mildly unless current bin would leave dead space
    if bin_residual == bin_capacity {
        score += 6.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: bins are more valuable when their
    // residual stays in "reusable" classes (multiples of common item sizes).
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fill is always excellent
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr % 20 == 0 {
        -9.0
    } else if pr <= 10 {
        8.0 // tiny dead space, hard to reuse
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr && pr - next_item_size <= 10 {
            score -= 10.0;
        } else if next_item_size > pr {
            // next item cannot go here anyway; slightly prefer keeping large residual
            score += (pr as f64) * 0.05;
        }
    } else {
        // last item: only zero residual matters
        score += if pr > 0 { 5.0 } else { -10.0 };
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // unless the residual left would be a terrible dead-space class.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
        if pr > 0 && pr < 10 {
            score += 10.0; // but avoid leaving tiny unusable slivers
        }
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 35.0; // base cost of a fresh bin
        // cheaper to open a new bin early when few bins are open
        score -= (open_bins_count as f64) * 1.5;
        // if item leaves a nice harmonic residual elsewhere, discourage new bin
        if pr % 10 == 0 && pr > 0 {
            score += 5.0;
        }
    }

    // Prefer bins with below-average residual (tighter bins get filled first).
    score += (mean_residual - post_residual as f64) * 0.3;

    // Slight preference for filling bins as the stream progresses (compaction).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
