    }

    // Open-bin pressure: discourage opening new bins when many bins exist;
    // encourage consolidation when open_bins_count is large.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make empty bins moderately attractive only when
    // no open bin offers a good fit; otherwise penalize slightly so we
    // consolidate into existing bins.
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.05;
        // Late in the stream, slightly favor reusing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
    }

    // Prefer bins whose residual is close to the item (minimize waste
    // relative to alternatives).
    let waste = (bin_residual - item_size) as f64;
    score += 0.02 * (bin_capacity as f64 - waste);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact 2-step lookahead match: item fills residual,
    // and next item exactly fills the new residual.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match bonus scaled by closeness of post_residual to next_item_size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 20.0 / (1.0 + gap);
    }

    // Penalize tiny dead space (wasted capacity) non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, use it rather
    // than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins tighter than the mean residual (best-fit style).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: make it moderately attractive only when the fit
    // elsewhere is bad (large post_residual) and stream is early/mid.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64 / bin_capacity as f64).min(1.0);
        score -= 10.0 * poor_fit * (1.0 - progress);
        // Slight penalty late in the stream to consolidate into open bins.
        score += 5.0 * progress;
    }

    // Mild penalty for leaving residuals that few item sizes can use.
    if post_residual > 0 && post_residual < 20 {
        score += 0.5 * (20 - post_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 14.0 * tightness * tightness;

    // Lookahead: if the next item can fit in the post residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack_after_next / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that blocks the next item: penalize proportional to how close next item is to fitting.
        let miss = (next_item_size - post_residual) as f64;
        score += 4.0 * (1.0 - miss / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Many open bins: prefer consolidating into existing bins (avoid bin sprawl).
    score += (open_bins_count as f64).ln().max(0.0) * (post_residual as f64 / bin_capacity as f64);

    // Global state: high mean residual across bins means space is abundant; be pickier about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > 30.0 {
        score += (post_residual as f64 - mean_residual).abs() * 0.15 * progress;
    }

    // Late in stream: waste matters more since recovery time is short.
    score += post_residual as f64 * 0.3 * progress;

    // New-bin candidate: baseline slightly above a good fit, below a bad one.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with progress:
    // early in the stream, small post-residuals are fine (bins fill over time);
    // late in the stream, dead space is penalized more aggressively.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * (pr * pr) / (cap * cap) * cap * 0.1;

    // Smooth reward for near-perfect fits (post_residual close to 0)
    let fit_quality = 1.0 - (pr / cap);
    score -= fit_quality * fit_quality * fit_quality * 8.0;

    // Penalize residual that no plausible future item can use, coupled with progress
    let mean_res = mean_residual.max(0.0);
    if mean_res > 0.0 {
        let waste_risk = (pr - mean_res).max(0.0) / cap;
        score += waste_risk * waste_risk * (1.0 + progress) * 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward bins whose post-residual matches the next item size smoothly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let match_quality = 1.0 - (gap / cap).min(1.0);
        score -= match_quality * match_quality * 6.0;
    } else {
        // Final item: only care about immediate waste
        score += (pr / cap) * (pr / cap) * 12.0;
    }

    // Mild penalty on opening new bins when many are already open, smoothed by progress
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (open_bins_count as f64).sqrt() - 4.0 * progress;
    }

    // Small tie-breaker toward tighter bins
    score += (bin_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via non-linear residual penalty
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 60.0;

    // Harmonic class of post_residual: mod-10 / mod-5 buckets.
    // Residuals in "awkward" classes (e.g. 1..9, 11..14) are dead space for
    // typical item sizes; reward residuals that are multiples of 5 or 10.
    let pr = post_residual;
    let class_bonus = match pr {
        0 => 80.0,                    // perfect fit
        _ if pr % 10 == 0 => 35.0,    // highly reusable class
        _ if pr % 5 == 0 => 18.0,     // reusable class
        _ if pr < 10 => -25.0,        // tiny dead space
        _ => 0.0,
    };
    score -= class_bonus;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 70.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // harmonic penalty on leftover after next item
            let leftover = slack % 10;
            score -= 25.0 - leftover * 1.5;
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += ((next_item_size - pr) as f64) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // Penalize spreading across too many open bins when mean residual is high.
    if open_bins_count > 0 {
        score += (open_bins_count as f64) * (mean_residual / bin_capacity as f64) * 4.0;
    }

    // Integer-division threshold on post_residual: residuals >= 50 are "half
    // bins" worth keeping flexible; residuals in 20..50 are mid-class.
    if pr >= bin_capacity / 2 {
        score -= 12.0;
    } else if pr >= bin_capacity / 5 {
        score -= 5.0;
    }

    // Slight stream-progression tightening: later in stream, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 6.0;

    // Prefer filling existing bins over opening new ones (new-bin candidate
    // gets a base handicap unless it's genuinely better).
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, or below min item size)
    // are worthless; treat them as if fully wasted (no reward for them).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space penalty: this gap will likely never be used
    }

    // Perfect fit: strongly reward zero post-residual.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose post-residual can still accommodate typical items
    // (usable gap), while penalizing large-but-awkward leftovers.
    if post_residual >= 10 {
        // usable leftover: mild reward scaled by how much slack remains
        score -= 6.0;
        // if next item fits into the post-residual, big lookahead reward
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    } else if post_residual > 0 {
        // awkward gap: penalize proportionally to dead fraction
        score += (post_residual as f64) * 0.8;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading;
    // when few bins are open, opening a new bin is cheaper.
    let pressure = (open_bins_count as f64).ln() * 3.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from number of open bins.
        // Encourage new bin only when existing residuals are large and fragmented.
        score = bin_capacity as f64 * 0.55 + pressure - mean_residual * 0.35;
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    } else {
        // mild preference to fill fuller bins (best-fit flavor)
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins where the next item also fits snugly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0; // exact 2-item completion
        } else if post_residual > next_item_size {
            let chain_residual = post_residual - next_item_size;
            if chain_residual <= 10 {
                score -= 120.0; // two items nearly fill the bin
            } else {
                score -= 20.0; // next item still fits, mild reward
            }
        } else {
            // next item won't fit here: penalize proportionally to wasted lookahead
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins),
    // but avoid bins far below mean unless the fit is excellent.
    let diff = bin_residual as f64 - mean_residual;
    if diff > 0.0 {
        score += diff * 0.3;
    } else {
        score += diff * 0.1; // slight reward for tighter-than-average bins
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
        if post_residual <= 20 {
            score -= 50.0;
        }
    }

    // New-bin candidate: make an empty bin attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        score += 40.0; // default mild penalty so open bins are preferred
        if fitting_bins_count == 1 {
            score += 100.0; // strongly discourage abandoning the only fitting bin
        }
        // Early in the stream, opening bins is cheap; later, consolidation matters.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Penalize leaving large unusable fragments (dead space in [1..10] is bad,
    // but 0 is perfect; mid-range leftovers 11..40 are reusable).
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 4.0;
    }

    // Slight preference to spread across many open bins when they are numerous,
    // to avoid many half-empty bins lingering.
    if open_bins_count > 8 {
        score += open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin filled by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize small unusable dead space (post_residual hard to reuse).
    if post_residual > 0 {
        let dead = (post_residual as f64) / bin_capacity as f64;
        if post_residual < 10 {
            score += 25.0 * (1.0 - dead);
        } else {
            score += 4.0 * dead;
        }
    } else {
        // Perfect closure is excellent.
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            let reuse = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * reuse;
        } else {
            // Next item cannot reuse this residual: mild penalty proportional to leftover.
            score += 6.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into bins with small residual (below mean).
    if open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.15 * diff;
    }

    // Time horizon: early in the stream, be more willing to open new bins (less penalty);
    // late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as the stream progresses.
        score += 10.0 + 20.0 * progress;
        // But if item is large and mean residual is small, new bin is attractive.
        if (item_size as f64) > mean_residual {
            score -= 14.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial coupling
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress);

    // Reward tight fits: quadratic bonus when post_residual is tiny
    score -= (1.0 - norm_pr).powi(3) * (1.0 + fit_ratio) * 3.0;

    // Penalize dead space that no plausible next item can use
    if next_item_size > 0 {
        let nxt = next_item_size as f64 / cap;
        if pr < next_item_size as f64 {
            score += (next_item_size as f64 - pr) / cap * (1.0 + progress);
        } else {
            // reward leaving space exactly usable by next item
            score -= (1.0 - (pr - next_item_size as f64) / cap).abs() * 0.5;
        }
        let _ = nxt;
    }

    // Last-chance bin: strong penalty for opening a new bin late in the stream
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.5 * (1.0 - progress * 0.5);
    }

    // New-bin candidate: penalize mildly, more when many bins already open
    if bin_residual == bin_capacity {
        score += 1.0 + (open_bins_count as f64).ln().max(0.0) * 0.3 + progress * 0.5;
    }

    // Slight preference for bins below mean residual (balance load)
    score += (mean_residual - pr) / cap * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: harmonic class of post_residual
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    }

    // Modulo-class structure: dead space that cannot pair with typical items
    let dead = post_residual as f64;
    let dead_frac = dead / bin_capacity as f64;
    score += dead_frac * dead_frac * 120.0;

    // Harmonic class penalty: post_residual in awkward classes (11..=19, 21..=30)
    if post_residual >= 11 && post_residual <= 19 {
        score += 15.0;
    } else if post_residual >= 21 && post_residual <= 30 {
        score += 5.0;
    } else if post_residual >= 31 && post_residual <= 50 {
        score -= 8.0;
    }

    // Lookahead coupling: next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= 20.0 - (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here: slight penalty for blocking
            score += 3.0;
        }
    }

    // Last-chance bin bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: prefer existing bins unless residual is large
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 0.5;
    }

    // Progress-aware: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += mean_residual * 0.05 * (1.0 - progress);
    score -= progress * 10.0;

    // Penalize bins far from mean residual (fragmentation avoidance)
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
