pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (low post residual), with a slight convexity
    // so that leaving a little space is much better than leaving a lot.
    let mut score = post + 0.35 * post * post / cap;

    // Reward good fill ratio of the bin before placement.
    let fill_ratio = 1.0 - residual / cap;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this is a perfect chain — reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack_gap = (post - nxt).abs();
        if post >= nxt {
            score -= 8.0 * (1.0 - slack_gap / cap);
        } else {
            // next item cannot fit here; mild penalty proportional to wasted pairing potential
            score += 2.0 * (nxt / cap);
        }
        // Bonus if next item is large and this placement leaves complementary space
        if nxt >= post && nxt <= post + 10.0 {
            score -= 4.0;
        }
    }

    // Last-chance dynamics: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
        // But if post residual would be a "dead" sliver (< 10), penalize instead
        if post > 0.0 && post < 10.0 && post > 0.0 {
            score += 6.0;
        }
    }

    // Global state: many open bins with high mean residual → prefer reusing
    // existing capacity rather than spreading.
    if open_bins_count > 0 {
        let spread_pressure = mean_residual / cap;
        score += 5.0 * spread_pressure * (1.0 - fill_ratio);
    }

    // Time horizon: early in the stream, keep bins flexible (moderate residual
    // is fine); late in the stream, pack tightly and avoid new bins.
    let horizon = progress;
    score += 6.0 * horizon * (post / cap);
    score -= 4.0 * (1.0 - horizon) * fill_ratio;

    // New-bin candidate handling: an empty bin has residual == capacity.
    let is_new_bin = (bin_residual == bin_capacity);
    if is_new_bin {
        // Opening a new bin is justified when item is large or no good fit exists.
        let largeness = item / cap;
        // Penalize new bin by default; discount the penalty for large items.
        score += 18.0 - 14.0 * largeness;
        // If several bins already fit, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 10.0;
        }
        // Late in the stream, opening new bins is almost always bad.
        score += 10.0 * horizon;
        // If the next item is nearly the size of the current one, a fresh bin
        // can host a matching pair — soften penalty.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if (nxt - item).abs() <= 5.0 && nxt + item <= cap * 0.95 {
                score -= 8.0;
            }
        }
    }

    // Tiny absolute tie-breaker toward larger fill before placement.
    score -= 0.01 * item;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr - 0.35 * (1.0 - progress) * (1.0 - norm_pr));

    // Reward tight fits: quadratic dead-space penalty
    score += 1.5 * norm_pr * norm_pr * cap;

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits exactly in the post-residual, reward heavily
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt == pr {
            score -= 60.0;
        } else if nxt <= pr {
            let gap = (pr - nxt) / cap;
            score -= 25.0 * (1.0 - gap * gap);
        } else {
            // next item too large for this residual: mild penalty scaled by overshoot
            let over = (nxt - pr) / cap;
            score += 10.0 * over * over * cap;
        }
    }

    // Mild preference for bins whose residual is near the mean (balance residuals)
    score += 0.15 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish score that adapts with progress
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.4 * progress) + 0.2 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod small integers.
    // Residuals that are "friendly" (divisible by common item sizes) are less wasteful.
    let pr = post_residual;
    if pr > 0 {
        let mut friendliness = 0.0;
        for &d in &[10u32, 20, 25, 50] {
            if pr % d == 0 { friendliness += 6.0; }
        }
        if pr % 5 == 0 { friendliness += 2.0; }
        score -= friendliness;

        // Penalize awkward dead space: small unusable residues.
        if pr < 10 {
            score += 25.0; // dead space below minimum item size
        } else if pr < 20 {
            score += 8.0;
        }
        // Harmonic band: residuals in [25,50) are moderately reusable, [50,100) very reusable
        if pr >= 50 { score -= 10.0; }
        else if pr >= 25 { score -= 4.0; }
    } else {
        score -= 30.0; // perfect closure
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0;
            score += slack * 0.15; // prefer tight future fit
            if slack as u32 % 10 == 0 { score -= 4.0; }
        } else {
            score += 6.0; // next item can't use this bin's remainder
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // fit is terrible or stream is early with few bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = item_size as f64 / bin_capacity as f64;
        // Opening new bin is good when item is small relative to mean residual pool
        // or when open bins are already crowded with small residuals.
        let crowded = mean_residual < item_size as f64 * 1.2;
        score += 55.0; // base new-bin penalty
        if fit_quality < 0.4 { score -= 10.0; }
        if crowded { score -= 30.0; }
        if open_bins_count == 0 { score -= 100.0; }
        if progress < 0.1 { score -= 5.0; }
        // If next item is large and won't fit anywhere else later, fresh bin keeps big space
        if next_item_size > 0 && next_item_size > bin_capacity - item_size && next_item_size >= 60 {
            score -= 12.0;
        }
    }

    // Mild preference for tighter existing fits via integer division threshold.
    let fill_class = (bin_capacity - bin_residual) / 25; // quartile of current fill
    score -= fill_class as f64 * 1.5;

    // Slight penalty for spreading across too many bins with large mean residual.
    if open_bins_count > 3 && mean_residual > 50.0 && bin_residual >= item_size {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that is too small to be useful for future items.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 60.0 } else if post_residual < 20 { 25.0 } else if post_residual < 30 { 8.0 } else { 0.0 };
        score += dead;
    } else {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward filling a bin tightly relative to capacity.
    score -= (bin_capacity - post_residual) as f64 * 0.3;

    // Pressure from number of open bins: prefer consolidating into fewer bins,
    // but a new empty bin (bin_residual == bin_capacity) gets a mild handicap
    // so it is only chosen when fits elsewhere are bad.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
    } else {
        score -= 5.0;
        // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Penalize leaving a residual just below the next item size (unusable gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Late in the stream, tighten bins more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this a brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Lookahead term: reward when post_residual exactly matches next item (perfect 2-step chain)
    if next_item_size > 0 {
        let look = next_item_size as f64;
        if post_residual as f64 == look {
            score -= 60.0; // perfect chain: this bin will be filled again exactly
        } else if post_residual >= next_item_size {
            // next item fits here; reward closeness of the chain fit
            let chain_waste = post_residual as f64 - look;
            score -= 30.0 / (1.0 + chain_waste / 10.0);
        } else {
            // next item won't fit here; penalize leftover dead space relative to mean residual
            let dead = post_residual as f64;
            score += 0.3 * (dead - mean_residual).abs();
        }
    }

    // Tight fit reward: small post_residual is good (classic best-fit), non-linear
    if post_residual > 0 {
        score -= 20.0 * (-post_residual as f64 / 15.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 25.0 + 30.0 * scarcity + 10.0 * (1.0 - progress);
        // but if the next item is huge and current residuals are small, opening fresh is less bad
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 15.0;
        }
    }

    // Prefer bins below the mean residual (fill emptier bins keeps tight bins for big items)
    if !is_new_bin {
        score += 0.1 * (post_residual as f64 - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: normalized fill ratio of the item into the bin.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to wasted opportunity.
            score += 4.0;
        }
    } else {
        // Last item: prefer filling existing bins as fully as possible.
        score -= 10.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are fragmented / mean residual is high relative to item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize new bins early or when open bins have plenty of room.
        score += 15.0 + 30.0 * (1.0 - progress) + 25.0 * (1.0 - fragmentation);
        // But if item is large and mean residual is small, opening is less bad.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64) * fragmentation;
    } else {
        // Slight preference for bins already below mean residual (consolidate emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Encourage consolidation when many bins are open: prefer bins with small residual.
    score -= 2.0 * (1.0 - (bin_residual as f64 / bin_capacity as f64)) * (open_bins_count.min(50) as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with smooth non-linear penalty for tiny dead space
    let mut score = pr;
    let dead_penalty = 60.0 * (1.0 - norm_pr).powi(2) * norm_pr.powi(2) * 4.0;
    score += dead_penalty;

    // Polynomial coupling with stream progress: later in stream, prefer tighter fits
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * progress * tightness.powi(3);

    // Last-chance bonus: strong smooth reward when this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits post-residual, penalize near-miss
    if next_item_size > 0 {
        let fits = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        score -= 15.0 * fits * tightness;
        let gap = (next_item_size as f64 - pr).abs();
        score += 0.3 * gap * (1.0 - fits);
    }

    // Mild penalty for spreading across too many bins early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins below mean (fill emptier-ish bins less)
    score += 0.1 * (pr - mean_residual);

    // New-bin candidate: smooth bias so new bin only wins when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) + 20.0 * norm_pr * (1.0 - norm_pr) * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // --- Harmonic class of post_residual: integer-division thresholds ---
    // Classes of residual: tiny (<=10), small (<=25), medium (<=50), large (>50)
    let post_class = post_residual / 25; // 0,1,2,3+
    score += match post_class {
        0 => -18.0, // near-perfect fit: strongly reward
        1 => -4.0,  // decent fit
        2 => 6.0,   // mediocre
        _ => 14.0 + 0.15 * (post - 50.0), // wasteful
    };

    // Exact fill bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // --- Lookahead coupling: does the next item fit into post_residual? ---
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic complement: reward when next item leaves another small residue
        let next_post = post_residual - next_item_size;
        let next_class = next_post / 20; // 0..4+
        score -= 10.0 - 2.5 * next_class as f64;
        if next_post == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving a residue that is
        // "almost but not quite" usable for it (dead-ish space).
        if post_residual >= next_item_size.saturating_sub(8) {
            score += 5.0;
        }
        // If residue is large but next item can't use it, mild penalty
        if post_residual > 40 {
            score += 0.1 * (post - 40.0);
        }
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // --- Modulo arithmetic on residual: residue mod 10 measures how "clean" ---
    // Residues that are multiples of 10 (or small) are more reusable for
    // integer item sizes drawn from typical streams.
    let m = post_residual % 10;
    score -= (5 - (m as i64 - 5).abs()) as f64 * 0.3; // prefer m near 0 or 10

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin: large, so we only open when
        // existing fits are bad.
        let mut new_bin_score = 55.0;
        // Early in the stream, opening bins is cheap (spread items out).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_score -= 20.0 * (1.0 - progress);
        // If many bins are open with big mean residual, prefer using them.
        new_bin_score += 0.4 * open_bins_count as f64 + 0.15 * mean_residual;
        // If the only alternative is a very poor fit (huge post_residual in
        // fitting bins), opening a new bin becomes attractive. Approximate via
        // mean_residual being large while item is large.
        if item_size >= 60 && mean_residual < item_size as f64 {
            new_bin_score -= 10.0;
        }
        // If no open bin fits at all, new bin is the only option.
        if fitting_bins_count == 0 {
            new_bin_score = -100.0;
        }
        return new_bin_score;
    }

    // Mild tie-break: prefer bins whose residual is close to item size in a
    // harmonic (capacity-fraction) sense.
    let frac = bin_residual as f64 / cap;
    if frac > 0.9 {
        score -= 3.0; // nearly-full bin: use it now
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible future item are pure waste -> heavy penalty.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.12);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 60.0 + (dead_threshold - post_residual as f64) * 8.0;
    }

    // Reward near-perfect fits strongly (post_residual close to 0 is ideal).
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 70.0;
    }

    // Reward leaving room for the lookahead item when possible.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + post_residual as f64 - next_item_size as f64;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Pressure from number of open bins: with many bins open, prefer filling
    // existing ones rather than fragmenting capacity across more bins.
    score += (open_bins_count as f64).sqrt() * 3.0;

    // Prefer bins whose residual is below the mean (fill the emptier-tail bins
    // less; prioritize bins already tight) — mild mean-residual coupling.
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // New-bin candidate handling: only attractive when the item is large
    // relative to typical residuals or no good fit exists.
    if bin_residual == bin_capacity {
        let late = step_index as f64 / (total_items.max(1) as f64);
        score = bin_capacity as f64 * 0.5
            + post_residual as f64
            - item_size as f64 * 0.3
            + late * 20.0
            - (fitting_bins_count as f64) * 5.0;
        // If the item leaves a large awkward gap in any bin, new bin looks better.
        if post_residual > bin_capacity / 2 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack (<= 10 dead space)
    else if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 25.0;
    }
    // Next item cannot follow in this bin but bin is nearly full: good packing
    else if next_item_size > 0 && post_residual < next_item_size && post_residual <= 15 {
        score -= 15.0;
    }

    // Penalize large unusable dead space (nothing can fit later)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny dead space is wasted capacity
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize slightly so we only open when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 12.0;
        // But if mean residual across open bins is very low (all nearly full),
        // opening a fresh bin is attractive: reduce penalty
        if mean_residual < 20.0 {
            score -= 25.0;
        }
        // Late in stream with many open bins, prefer consolidating
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 && open_bins_count > 3 {
            score += 15.0;
        }
    }

    // Prefer bins with residual below mean (tighter bins get used first)
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively as stream progresses.
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tight = (post_residual as f64 / bin_capacity as f64).powf(2.0);
    score -= (1.0 - tight) * item_size as f64 * (0.5 + 0.5 * progress);

    // Dead-space penalty: post_residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Lookahead: strongly reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot fit here: mild penalty proportional to overflow.
            let over = (next_item_size - post_residual) as f64;
            score += 0.1 * over;
        }
    }

    // Last-chance bin: this is the only fitting bin; strongly favor using it
    // rather than opening a new bin, especially late in the stream.
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Encourage packing into bins with residuals below the mean (consolidate waste),
    // penalize dipping into bins with large residuals that may serve bigger items.
    if bin_residual as f64 > mean_residual {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - bin_residual as f64);
    }

    // Many open bins: prefer filling existing ones to limit bin count.
    score -= 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate (empty bin): only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, decaying if the current item is large
        // (fewer future placements wasted) and few bins are open.
        let mut new_bin_cost = 30.0;
        if item_size >= 60 { new_bin_cost -= 10.0; }
        if open_bins_count == 0 { new_bin_cost = 0.0; }
        if fitting_bins_count == 0 { new_bin_cost -= 50.0; }
        score += new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap;

    // Base: dead space, penalized super-linearly
    let mut score = x * x * (2.0 + progress) * cap;

    // Smooth coupling: small post-residuals are valuable, more so later in the stream
    let tightness = (1.0 - x).powi(3);
    score -= 30.0 * tightness * (0.5 + progress);

    // Reward when post-residual aligns with the next item (smooth kernel)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = (pr - n) / cap;
        score -= 25.0 * (-8.0 * diff * diff).exp();
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Crowding penalty: many open bins with large mean residual -> prefer consolidation
    let crowd = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 10.0 * crowd * (x - mean_residual / cap).abs();

    // Mild preference for keeping near-empty bins flexible
    score += 5.0 * (x * (1.0 - x)) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class analysis on post_residual ---
    // Items 1..100; capacity fractions partition residuals into useful classes.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of residual: classify by capacity fractions.
    // Residuals in (0, 25] are "dead zone" (only tiny items fit) -> penalize.
    // Residuals in (25, 50] fit half-class items -> moderate.
    // Residuals in (50, 75] and (75, 100) are roomy.
    let quarter = cap / 4.0;
    let half = cap / 2.0;
    let three_quarter = 3.0 * cap / 4.0;

    if post > 0.0 && post <= quarter {
        // Dead space penalty, scaled by how dead.
        score += (quarter - post) * 1.5 + 30.0;
    } else if post <= half {
        score += 8.0;
    } else if post <= three_quarter {
        score -= 4.0;
    }

    // Integer division thresholds: residual bucket via /10 creates fine
    // granularity; reward low buckets (tight packing) non-linearly.
    let bucket = post_residual / 10;
    score -= match bucket {
        0 => 40.0,
        1 => 25.0,
        2 => 12.0,
        3 => 5.0,
        4 => 0.0,
        5 => -3.0,
        6 => -5.0,
        7 => -6.0,
        8 => -6.5,
        _ => -7.0,
    };

    // Modulo arithmetic: residuals that are multiples of common item classes
    // (10, 20, 25, 50) are more likely to be filled by future items.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 25 == 0 { score -= 4.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strong reward (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            // Reward if the chain leaves a small, useful residual.
            if nxt_post <= 10 {
                score -= 30.0;
            } else if nxt_post <= 25 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here; residual likely wasted -> mild penalty
            // proportional to leftover.
            score += post * 0.1;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: recognize empty bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin.
        score += 60.0;
        // Prefer new bin when few alternatives exist or when current fit is
        // terrible (leaves dead space <= quarter).
        if fitting_bins_count == 0 {
            score -= 200.0; // no open bin fits: must open.
        }
        if post > 0.0 && post <= quarter && fitting_bins_count <= 2 {
            score -= 100.0; // avoid creating dead space if alternatives scarce.
        }
        // Later in the stream, consolidation matters more: penalize new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
        // Many open bins with high mean residual: prefer reusing.
        if open_bins_count > 3 && mean_residual > item_size as f64 {
            score += 25.0;
        }
    } else {
        // Reward reusing existing bins, especially crowded states.
        score -= (open_bins_count.min(20) as f64) * 0.5;
        // Reward placing into bins whose residual is close to mean (balance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 10.0 / (1.0 + dev * 0.05);
    }

    // Small tie-break noise-free deterministic nudge using step parity class.
    if (step_index + post_residual as usize) % 3 == 0 {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the smallest
    // plausible item are pure waste. Penalize them heavily.
    let min_item = 1u32;
    let dead_threshold = 10u32.max(min_item);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 25.0 * (dead_threshold - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 30.0;
    } else {
        // Smooth tightness reward: smaller post_residual relative to capacity wins.
        score -= 0.15 * (bin_capacity - post_residual) as f64;
    }

    // Penalize gaps that cannot fit the lookahead item but could have:
    // creates a stranded bin.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that remain usable for the next item.
        score -= 4.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bins pressure: with many open bins, discourage opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bin count.
        score = bin_capacity as f64 + 6.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // Late in the stream, new bins are even less attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    } else {
        // Mild preference to spread load when very few bins are open.
        score += 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item
    let next = next_item_size as f64;
    if next > 0.0 {
        let gap = (post_residual as f64 - next).abs();
        score -= 40.0 * (-gap / 15.0).exp(); // strong reward for exact lookahead fit
        // penalize post_residual slightly larger than next (unusable sliver)
        if post_residual as f64 > next && post_residual < 20 {
            score += 12.0;
        }
    } else {
        // last item: pure tightness
        score -= 20.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score -= 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bonus: this is the only fitting bin; avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): penalize unless current bins are hopeless
    if bin_residual == bin_capacity {
        score += 45.0;
        if next > 0.0 && post_residual as f64 >= next {
            score -= 10.0; // fresh bin still fits lookahead well
        }
    }

    // Mild tightness shaping: favor small post residuals generally
    score += 0.15 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64) * 0.35;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate logic: opening a bin is only attractive when residuals are fragmented
    // or the stream is early and future items are likely large.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 55.0;
        // Early stream or large next item: new bins are more acceptable.
        score -= 45.0 * (1.0 - progress);
        if next_item_size > item_size {
            score -= 10.0;
        }
        // Many open bins with large mean residual: prefer reusing them.
        score += 0.08 * open_bins_count as f64;
        score += mean_residual * 0.25;
    }

    // Prefer bins whose residual is close to the item (perfect packing).
    let waste_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 20.0 * waste_ratio * waste_ratio;

    // Mild penalty for spreading across many bins late in the stream.
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (small post_residual), with non-linear sharpening.
    let mut score = post * (1.0 + 0.8 * pr * pr);

    // Stream-progress coupling: later in the stream, dead space becomes more costly.
    let dead_weight = 1.0 + 2.0 * progress * progress;
    score += dead_weight * pr * pr * cap * 0.5;

    // Reward near-perfect fits more strongly as progress advances.
    score -= (1.0 - pr) * (1.0 - pr) * (5.0 + 10.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 8.0 * progress;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or the stream is early and spreading items is cheap.
    if bin_residual == bin_capacity {
        let spread_bonus = if fitting_bins_count == 0 {
            -20.0
        } else {
            (1.0 - progress) * 6.0 - fitting_bins_count as f64 * 1.5
        };
        score += 8.0 + spread_bonus;
    }

    // Lookahead: penalize leaving residual that neither wastes nor helps next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score += 0.05 * gap * gap / cap;
        // Reward residuals that exactly accommodate the next item.
        if post >= nxt {
            score -= 3.0 * (1.0 - (gap / cap).min(1.0));
        }
    } else {
        // Last item: fill as much as possible.
        score -= 10.0 * (1.0 - pr);
    }

    // Mild penalty for proliferating bins late in the stream.
    score += 0.3 * open_bins_count as f64 * progress;

    // Penalize bins far below mean residual (fragmented outliers).
    score += 0.5 * ((mean_residual - post) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins whose post-residual lands in
    // harmonic "dead classes" that are hard to fill later.
    // Harmonic classes of post_residual mod 10: small residuals are gold.
    let class = post_residual % 10;
    let class_bonus: f64 = match class {
        0 => -18.0, // exact multiple of 10: very reusable
        5 => -12.0,
        2 | 4 | 6 | 8 => -8.0,
        1 | 9 => -3.0,
        _ => 0.0,   // odd primes 3,7 leave awkward gaps
    };
    score += class_bonus;

    // Integer-division thresholds on post_residual: classify leftover size.
    let tier = post_residual / 10;
    if tier == 0 {
        score -= 25.0; // near-perfect fit
    } else if tier <= 2 {
        score -= 6.0;  // still compact
    } else if post_residual == bin_capacity {
        // New-bin candidate: only attractive when no open bin fits well
        // or the item would leave a huge hole elsewhere.
        let pressure = if fitting_bins_count <= 1 { 30.0 } else { 0.0 };
        let mean_gap = mean_residual - item_size as f64;
        let poor_fit_everywhere = mean_gap > 40.0 && fitting_bins_count <= 2;
        score += 45.0 - pressure - if poor_fit_everywhere { 35.0 } else { 0.0 };
        // Late in stream, opening fresh bins is cheaper than fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 12.0 * progress;
    } else {
        score += 2.0;
    }

    // Lookahead coupling: if next item exactly fills post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Harmonic divisibility check: does next item divide cleanly into gap?
            if post_residual % next_item_size == 0 {
                score -= 14.0;
            }
            score -= (post_residual - next_item_size).min(20) as f64 * 0.4;
        } else {
            // Next item won't fit here; penalize large wasted gaps less if
            // they belong to a reusable class (multiple of 5/10).
            if post_residual % 5 != 0 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that can fit, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Congestion term: many open bins with high mean residual -> consolidate.
    if open_bins_count > 4 && mean_residual > 30.0 {
        score += (mean_residual - post_residual as f64) * 0.15;
    }

    // Prefer filling existing bins proportionally to their fullness.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for any item (1..=10) are pure waste.
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    } else if post_residual > 10 && post_residual < 20 {
        // Risky gap: only small items can use it later.
        score += 12.0 - (post_residual as f64 - 10.0);
    } else if post_residual == 0 {
        // Perfect fill: strong reward.
        score -= 80.0;
    }

    // Reward tight fits relative to residual (small waste fraction).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln().max(0.0) * 6.0 * (0.5 + 0.5 * progress);

    // Mean residual coupling: if this bin's residual is far below mean, it's a laggard bin — use it.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= 0.15 * diff;
    } else {
        score += 0.10 * (-diff);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / bin_capacity as f64);
    }
    // If next item would leave a near-dead gap, discourage.
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) <= 10 {
        score += 15.0;
    }

    // New-bin candidate (empty bin): baseline attractiveness so it's chosen only when
    // existing fits are poor. Penalize moderately, scaled by how many bins could fit.
    if bin_residual == bin_capacity {
        let base = 40.0 + 8.0 * (fitting_bins_count as f64).min(10.0);
        // Early in the stream or huge item: new bin is more acceptable.
        score += base * (1.0 - 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 60.0 / post_residual as f64;
    }

    // 2-step lookahead: reward bins whose post residual matches the next item well.
    if next_item_size > 0 {
        let diff = if post_residual as i64 - next_item_size as i64 >= 0 {
            (post_residual as i64 - next_item_size as i64) as f64
        } else {
            1000.0 // next item won't fit here; mild penalty for wasting residual
        };
        score += 0.35 * diff;
        if diff == 0.0 {
            score -= 120.0; // perfect chain: this bin then next item
        }
    } else {
        // Last item: closing bins tightly is all that matters.
        score -= 200.0;
    }

    // Penalize leaving dead space relative to mean residual.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < mean_residual * 0.5 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: make it attractive only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 25.0; // fresh bin can chain large items
        }
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
    }

    // Late in stream: prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 30.0 * progress;
    }

    // Mild pressure to spread load when many bins are open.
    score += 0.01 * open_bins_count as f64 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 1.0 };
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving small unusable slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 20.0; // perfect fill is excellent
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement; if it would be wasted, penalize slightly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            // dead end for next item relative to this bin — mild penalty scaled by waste
            score += 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            // next item still fits: mild bonus proportional to how well it fills remainder
            let nf = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * nf;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 40.0;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 30.0 * (fitting_bins_count as f64).min(5.0);
        }
        // If the current item is large relative to capacity, a fresh bin is more attractive.
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
        // If mean residual across open bins is small, open bins are crowded: new bin less bad.
        score -= 15.0 * (mean_residual / bin_capacity as f64).max(0.0);
        // Late in the stream, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * progress;
        // If the item would leave a large residual in an existing bin while the next
        // item is small, opening a new bin may be better.
        if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count <= 2 {
            score -= 20.0;
        }
    }

    // Global pressure: when many bins are open, encourage tighter packing
    // (larger deviation between this bin's residual and mean residual matters).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (open_bins_count as f64).ln().max(1.0);

    // Mild preference for bins with larger residuals when item is small
    // (keep small bins for small items): use residual relative to item.
    score -= 0.1 * (bin_residual as f64 / (item_size as f64 + 1.0)).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let is_new_bin = (bin_residual == bin_capacity) as f64;

    // Base: quadratic dead-space penalty with progress-dependent curvature
    let curvature = 1.0 + 2.5 * progress * progress;
    let mut score = norm_pr + curvature * norm_pr * norm_pr;

    // Smooth cubic coupling: small residuals are fine early, costly late
    score += 0.8 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (post residual near zero) more strongly later in stream
    let tightness = (1.0 - norm_pr).clamp(0.0, 1.0);
    score -= 1.5 * tightness * tightness * (0.3 + 0.7 * progress);

    // Last-chance bonus: strongly prefer this bin when it is the only fitting one
    if fitting_bins_count == 1 {
        score -= 2.0 + 1.5 * progress;
    }

    // Mild bonus for scarcity of fitting bins
    score -= 0.3 / (fitting_bins_count as f64 + 1.0);

    // Lookahead: penalize residual too small for next item, reward exact match
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = (pr - nxt) / cap;
            score += 0.6 * gap * gap; // leftover after next item
            score -= 0.4 * (1.0 - gap); // reward next item fitting well
        } else {
            let miss = (nxt - pr) / cap;
            score += 0.9 * miss;
        }
    }

    // New-bin candidate: penalize mildly early, more when open bins are sparse
    score += is_new_bin * (1.0 + 2.0 * (1.0 - progress)) * (1.0 / (open_bins_count as f64 + 2.0));

    // Mean residual coupling: prefer bins near mean residual (balanced usage)
    let dev = (pr - mean_residual) / cap;
    score += 0.4 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" classes (multiples of common small item sizes) are preferred.
    let pr = post_residual;
    if pr > 0 {
        // Reward residuals that are exactly reusable by common item classes.
        if pr % 10 == 0 { score -= 6.0; }
        else if pr % 5 == 0 { score -= 2.5; }
        else { score += 3.0; } // awkward leftover class

        // Dead-space penalty: leftover too small for the smallest plausible item.
        if pr < 10 { score += 25.0; }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this is a harmonic pairing — reward heavily.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // Next item won't fit here regardless; slight penalty scaled by overshoot class.
            score += ((next_item_size - pr) / 10) as f64 * 1.5;
        }
    } else {
        // Last item: prefer perfect fill.
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when open bins are bad.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.1 * open_bins_count as f64;
        // But if current item is large relative to mean residual of open bins,
        // opening fresh is attractive: reduce the penalty.
        let mean_r = mean_residual.max(0.0);
        if (item_size as f64) > mean_r + 20.0 {
            score -= 25.0;
        }
    }

    // Tightness reward: bins that become nearly full are good placements.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Stream progression: late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (post_residual as f64 / bin_capacity as f64) * 5.0;

    // Many open bins: favor placements that shrink mean residual dispersion.
    if open_bins_count > 4 && (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never host even the
    // smallest future item (1..=10) are pure waste -> heavy penalty.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 45.0; // unusable sliver of dead space
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward bins whose residual is "consumable" by the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0; // sets up a perfect follow-up fit
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 12.0; // good two-step chain without slivers
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0; // blocks the lookahead item
        }
    }

    // Reward tightness relative to bin residual (best-fit flavor).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Pressure from number of open bins: when many bins are open, prefer
    // filling existing ones; when few, opening a new bin is cheap.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.5 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, avoid forcing a
    // new bin unless the dead space created is truly unusable.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin should only win when placing
    // into open bins would strand a large residual while the bin is nearly
    // full anyway. Penalize the fresh bin mildly by default.
    if bin_residual == bin_capacity {
        score += 30.0 + 4.0 * open_bins_count as f64;
        // But if mean residual of open bins is small (they are nearly full),
        // opening a new bin becomes attractive: reduce the penalty.
        score -= 0.6 * mean_residual;
        // If the next item is large, a fresh bin keeps flexibility.
        if next_item_size >= 60 {
            score -= 20.0;
        }
    }

    // Mild pull toward bins with residuals near the mean (spread filling).
    score += 0.08 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the leftover space exactly
    // matches the next item's size (perfect chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect 2-step match
        } else if post_residual >= next_item_size {
            // partial reward proportional to how close the next item fits
            let gap = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // leftover too small for the next item: penalize dead space,
            // more harshly the smaller (more wasted) the remainder is.
            let waste = next_item_size - post_residual;
            score += 0.6 * waste as f64;
        }
    }

    // Reward tight fits relative to the fleet mean residual.
    score -= 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize the brand-new empty bin candidate mildly, unless it would
    // otherwise be forced (no fitting open bins).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // forced opening
        } else {
            score += 12.0 + 0.5 * open_bins_count as f64;
        }
    }

    // Late in the stream, be more conservative: prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual relative to capacity, the better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize creating dead space that no plausible future item can use.
    // Items are 1..100, but small residuals (< next item) are only useful if a
    // small item arrives; weight by lookahead fit.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can also host the next item: chain bonus.
            score -= 8.0 + (next_item_size as f64 / bin_capacity as f64) * 10.0;
        } else {
            // Dead space relative to the lookahead item.
            score += 0.4 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the item
    // is huge relative to available residuals or when few bins fit the item.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Big items justify a fresh bin; small items should go into open bins.
        score += 25.0 - 30.0 * fill_ratio;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            score += 15.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
    }

    // Global fragmentation pressure: if mean residual across open bins is low,
    // space is scarce — avoid wasting the roomiest bins on small items.
    let scarcity = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += scarcity * (item_size as f64) * 0.3;

    // Slight preference for balancing load across bins when many are open.
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Core: quadratic penalty on leftover space (tight fits preferred),
    // smoothed by stream progress so late in the stream we punish waste harder.
    let mut score = post * (1.0 + 0.8 * progress) + norm_post * norm_post * 40.0;

    // Penalize unusable "dead" residual: too small for the smallest plausible item.
    let dead_threshold = 0.1 * cap;
    if post > 0.0 && post < dead_threshold {
        let deadness = (dead_threshold - post) / dead_threshold;
        score += 35.0 * deadness * (1.0 + progress);
    }

    // Reward if the lookahead item fits into the post residual (chain packing).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let snug = 1.0 - (post - nxt) / cap;
            score -= 18.0 * snug * (1.0 + 0.5 * progress);
        } else {
            // Next item won't fit here; mildly penalize residual that is close-but-insufficient.
            let gap = (nxt - post) / cap;
            if gap < 0.2 {
                score += 12.0 * (1.0 - gap / 0.2);
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Coupling with mean residual: prefer bins whose residual deviates from the mean
    // (fill down outliers, keep balanced bins for future flexibility).
    let dev = (post - mean_residual).abs();
    score += 0.15 * dev;

    // New empty bin candidate: penalize mildly so it's chosen only when open bins fit badly,
    // but relax the penalty as the stream progresses / many bins are open.
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln_1p();
        score += 30.0 * (1.0 - 0.4 * progress) + 2.0 * openness;
    }

    // Mild congestion bonus: many open bins -> encourage consolidation into existing bins.
    score -= 1.5 * (open_bins_count as f64).ln_1p() * (1.0 - norm_post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 classes group dead space.
    let pr = post_residual;
    let class = pr % 10;
    // Penalize residuals in awkward classes (small but unusable slivers).
    if class >= 1 && class <= 9 {
        // sliver class: post residual too small for typical items
        score += (10 - class) as f64 * 0.8;
    } else if class == 0 && pr > 0 {
        // perfectly divisible residual is a good harmonic state
        score -= 3.0;
    }

    // Integer-division thresholds: can a future item of the common small sizes fit?
    let fits_10 = pr / 10;
    let fits_20 = pr / 20;
    let fits_50 = pr / 50;
    score -= 2.0 * fits_10 as f64;
    score -= 3.0 * fits_20 as f64;
    score -= 6.0 * fits_50 as f64;

    // Lookahead harmonic coupling: does next item divide into post_residual?
    if next_item_size > 0 && next_item_size <= pr {
        let rem = pr % next_item_size;
        score -= 4.0 + (rem as f64) * 0.1;
        if rem == 0 {
            score -= 6.0; // perfect harmonic pair with lookahead
        }
    } else if next_item_size > pr {
        // next item can't use leftover: dead space penalty scaled by proximity
        score += (next_item_size - pr) as f64 * 0.3;
    }

    // Last-chance bonus: only fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should be chosen only when no open bin fits well.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score = bin_capacity as f64 * 0.9;
        if fitting_bins_count == 0 {
            score -= 40.0; // forced open
        } else if fitting_bins_count == 1 {
            score -= 10.0; // mild pressure to open when only one fit
        }
        if next_item_size > 0 && next_item_size >= bin_capacity - 20 {
            score -= 15.0; // big lookahead item benefits from fresh bin
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer filling bins that are already relatively full (low residual before placement).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Mean residual coupling: if this bin's residual is far below mean, it's a good closer.
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= (open_bins_count.min(20) as f64) * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..100) are wasted.
    // A residual of 0 is perfect (exact fill) — heavily reward it.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 4 {
        // Tiny unusable sliver: treat as near-total waste.
        score += 120.0;
    } else {
        // Usable residual: reward proportionally to how "valuable" it stays.
        // Residuals that can still host mid/large items are good; small-but-usable
        // residuals are fragile — mild penalty ramp below 25.
        let r = post_residual as f64;
        if r < 25.0 {
            score += (25.0 - r) * 2.5;
        } else {
            score -= (r - 25.0) * 0.3;
        }
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 40.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another one
    // (the empty-bin candidate has max residual); encourage consolidating items.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 25.0 + pressure * 3.0;
    } else {
        // Existing bin: small bonus that grows with open-bin count.
        score -= pressure * 0.5;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            // Next item still fits: mild reward proportional to slack match.
            score -= (post_residual - next_item_size) as f64 * 0.4;
        } else {
            // Next item won't fit here: penalize leaving a residual just below it
            // (near-miss dead space).
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 10.0 {
                score += (10.0 - miss) * 3.0;
            }
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it's already "dense" — finishing it is good.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.6;
    } else {
        score += (-dev) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post_residual is very valuable).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // 2-step lookahead: if the next item fits the leftover, big reward.
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap == 0 {
            score -= 400.0;
        } else if gap > 0 && gap <= 10 {
            score -= 120.0;
        } else if gap > 0 {
            score -= 30.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space
            score += (-gap) as f64 * 0.5;
        }
    }

    // Compare post_residual against mean residual: creating below-average
    // leftover is good (bin is well used), above-average is wasteful.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr).min(50.0) * 0.4;
    } else {
        score += (pr - mean_residual).min(50.0) * 0.2;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when decent alternatives exist, but allow it
    // when current bins would leave large dead space.
    if bin_residual == bin_capacity {
        let waste_if_forced = if fitting_bins_count == 0 {
            0.0
        } else {
            (bin_residual as f64 - item_size as f64).max(0.0)
        };
        score += 25.0 + open_bins_count as f64 * 2.0;
        // If using this new bin yields a perfect slot for the next item, soften.
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 60.0;
        }
        let _ = waste_if_forced;
    }

    // Late in the stream, consolidate harder (fewer bins matter more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness reward: quadratic penalty on large post-residual.
    let post = post_residual as f64;
    score += 0.35 * post * post / bin_capacity as f64;

    // Perfect-ish fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 3 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits in the post-residual, this bin is
    // doubly valuable (chaining). If post-residual is just below next item,
    // it is dead space — penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 12.0 + 0.25 * nxt;
        } else if nxt - post_residual as f64 <= 10.0 {
            score += 8.0 + (nxt - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate: penalize opening a new bin, more so when good
    // fitting options exist or early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 45.0 + 40.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // If item nearly fills a fresh bin, opening is fine.
        if item_size as f64 >= 0.8 * bin_capacity as f64 {
            score -= 60.0;
        }
    }

    // Prefer bins whose residual is already below average (consolidate
    // fullness); avoid fragmenting high-residual bins early.
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Mild preference for larger items into larger residuals.
    score -= 0.05 * (bin_residual as f64 - item_size as f64);

    // Late-stream pressure: consolidate as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - post / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Normalize post-residual as fraction of capacity
    let pr_frac = pr / cap;

    // Non-linear polynomial coupling: dead-space penalty grows quadratically for small residuals
    let dead = pr_frac * pr_frac;
    score += dead * cap * 0.6;

    // Tight fits (small post_residual) rewarded strongly via smooth decay
    score -= (1.0 - pr_frac).powi(3) * cap * 0.5;

    // Stream progress coupling: as stream advances, prefer filling existing bins more aggressively
    let prog_coupling = progress * progress;
    score -= prog_coupling * pr_frac * cap * 0.4;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= cap * 0.8;
    }

    // New-bin candidate: penalize opening a new bin unless residuals elsewhere are poor
    if bin_residual == bin_capacity {
        score += cap * (0.5 + 0.5 * progress);
        // If mean residual is small (bins nearly full), new bin is more acceptable
        score -= (mean_residual / cap).min(1.0) * cap * 0.3;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size as f64 == pr {
        score -= cap * 1.2;
    } else if next_item_size > 0 {
        // Penalize leaving residual that next item barely misses
        let miss = (pr - next_item_size as f64) / cap;
        if miss > 0.0 {
            score += miss * cap * 0.3;
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes of the capacity
    // define "good" leftover zones (multiples of common item sizes).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Reward post residuals that fall into usable harmonic classes:
    // multiples of 10 (common item granularity) are highly reusable.
    let class = post_residual % 10;
    if post_residual > 0 {
        if class == 0 {
            score -= 30.0; // perfect harmonic leftover
        } else if class <= 3 {
            score -= 8.0;
        } else if class >= 7 {
            score += 6.0; // awkward leftover, close to next class boundary
        }
    } else {
        score -= 60.0; // perfect fill
    }

    // Dead-space penalty: tiny residuals (< 10) are unusable for any item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly
    // or nearly, strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) % 10;
        score -= 20.0;
        if slack == 0 {
            score -= 10.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use the leftover; leftover becomes dead weight
        score += pr * 0.15;
    }

    // Tight-fit reward: item occupies most of the bin.
    let tightness = item_size as f64 / bin_residual as f64;
    if tightness > 0.9 {
        score -= 15.0;
    } else if tightness > 0.7 {
        score -= 7.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): penalize unless open bins are mostly
    // full or the current item leaves a bad harmonic class everywhere.
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - (mean_residual / cap);
        score = cap * 0.6 + mean_fill * 40.0;
        if fitting_bins_count == 1 {
            score += 80.0; // never open when a sole fitting bin exists
        }
        if frac_ok_all_ignored() {
            // unreachable guard placeholder, keeps structure
        }
        // open early when stream is young and mean residual is small
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // Mild pressure against hoarding many open bins with large residuals.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= mean_residual * 0.05;
    }

    score
}

#[inline]
fn frac_ok_all_ignored() -> bool { false }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space: residuals too small for the smallest item (1..=10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Mid-range dead space (10..20) is only usable by small items; penalize moderately.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (post_residual near zero but not wasteful).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // If this is the last bin that can fit the item, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins have poor residuals
    // relative to the item, or the next item would benefit from a fresh bin.
    if bin_residual == bin_capacity {
        score += 12.0; // mild baseline penalty for opening a new bin
        if fitting_bins_count > 0 && (bin_residual as f64) > mean_residual + item_size as f64 {
            score += 25.0; // existing bins are roomy enough; avoid sprawl
        }
        if next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 20.0; // fresh bin helps the lookahead item
        }
        score += 0.5 * open_bins_count as f64; // pressure against too many open bins
    } else {
        // Reusing an open bin reduces open-bin pressure.
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Late in the stream, consolidation matters more: extra penalty for leftovers.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step chain: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Partial lookahead reward: next item fits in the post residual.
    else if next_item_size > 0 && post_residual >= next_item_size {
        // Closer match (small slack after next item) gets bigger reward.
        let slack_after_next = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack_after_next * 0.35;
    }
    // Penalize residuals that cannot host the next item at all.
    else if next_item_size > 0 {
        score += 10.0;
    }

    // Reward tight fits relative to bin capacity (small post residual waste).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 15.0;

    // Penalize when this bin is much tighter than average (dead-space avoidance
    // for other bins is handled elsewhere; here favor bins near mean residual).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.05;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Early in stream: be slightly more conservative, keep bins flexible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0;

    // Penalize opening a new bin when other bins fit, unless residual is tiny.
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square-root dampening of post residual so near-perfect
    // placements dominate, but exact fits get an extra hard bonus.
    score = (post_residual as f64).sqrt() * 10.0;
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily;
    // if the next item fits at all, mild reward; otherwise penalize leaving a
    // residual that is too small to be useful (dead space).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            // dead-space penalty scaled by how far below next item the residual falls
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.5;
        }
    }

    // Prefer filling bins with below-average residual (consolidate emptier bins usage),
    // penalize drawing from bins that are already tighter than average.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.3;

    // Time horizon: early in the stream, be more conservative (favor new bins to
    // preserve flexibility); late in the stream, squeeze every open bin.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure to open bins when many are
        // already open or the stream is late.
        let base = 60.0;
        let pressure = open_bins_count as f64 * 1.5 + progress * 40.0;
        // If the current bin would leave a small-but-usable residual, opening a new
        // bin is unattractive; if post residual is awkward dead space, new bin wins.
        score = base + pressure - (post_residual as f64).sqrt() * 5.0;
        if fitting_bins_count == 1 {
            score += 80.0; // never open a new bin when it's the last fitting bin
        }
    } else {
        // Late-stream urgency: reduce score of using existing bins as stream ends.
        score -= progress * 15.0;
    }

    // Mild penalty for very large items consuming almost the whole bin when the
    // residual left would be under the minimum item size (1..100 interface => avoid
    // residuals < ~10 which are hard to fill).
    if post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p = progress;
    let coupling = norm_pr * norm_pr * (1.0 + p) + norm_pr * (2.0 - 3.0 * p);
    score += 15.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 20.0 * tightness * tightness * (0.5 + p);

    // Lookahead: penalize leaving residual that can't fit next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            let slack = (pr - ni) / cap;
            score += 8.0 * slack * slack;
        } else {
            score += 12.0 * (1.0 - pr / ni.max(1.0));
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Penalize opening new bins late in the stream when open bins exist
    if bin_residual == bin_capacity {
        score += 5.0 + 25.0 * p + 2.0 * open_bins_count as f64;
    }

    // Diverge from mean residual: prefer bins near mean residual
    let dev = (pr as f64 - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: capacity split into eighths.
    let eighth = bin_capacity / 8;
    let item_class = (item_size + eighth - 1) / eighth; // 1..=8
    let post_class = (post_residual + eighth - 1) / eighth;

    // Reward perfect / near-perfect fits (post_residual in lowest harmonic class).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_class <= 1 {
        score -= 25.0;
    } else if post_class == 2 {
        score -= 8.0;
    }

    // Penalize dead space: post_residual too small to ever fit a plausible item.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 40.0;
    }
    // Small-but-nonzero post_residual that can't fit the lookahead item is dead
    // unless it could still fit a small future item; penalize moderately.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Reward bins whose residual can host the next item (chaining fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 15.0 * (slack as f64 / bin_capacity as f64).min(1.0);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits via class competition.
        score += 2.0 * post_class as f64;
    }

    // Modulo-4 harmonic penalty: post_residual just under a quarter/half boundary
    // wastes capacity; snap preference toward boundary-aligned residuals.
    let quarter = bin_capacity / 4;
    let r = post_residual % quarter;
    if post_residual > 0 {
        score -= 6.0 * (r as f64 / quarter as f64); // prefer residuals just above boundaries
    }

    // New-bin candidate handling: an empty bin gets a mild baseline penalty so it
    // is only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.0 * open_bins_count as f64;
        // But if the current item is huge and would leave a bad residual anywhere,
        // opening fresh is fine: cancel penalty.
        if item_class >= 7 {
            score -= 22.0;
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 10.0; // item can't chain anyway; new bin is acceptable
        }
    }

    // Late in the stream, consolidate: prefer existing bins more strongly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    // Mild preference to spread load when many bins are open with high mean residual.
    if bin_residual != bin_capacity && mean_residual > 0.0 {
        score += 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest future item (1..=100 unknown, assume >= ~10) are
    // nearly worthless -> penalize heavily.
    let dead_threshold: f64 = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Superlinear penalty on residual waste, stronger for very tight fits
    // that leave awkward gaps (post_residual small but nonzero).
    if post_residual > 0 {
        score += 40.0 / (post_residual as f64 + 1.0);
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Reward filling bins that are nearly full (low residual relative to capacity).
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 30.0;

    // Open-bin pressure: when many bins are open, favor consolidating into
    // existing bins; when few bins are open, opening new bins is cheaper.
    let open_pressure = (open_bins_count as f64).sqrt() * 6.0;
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, modulated by open-bin pressure.
        score += 55.0 + open_pressure;
        // Late in the stream, opening new bins is less attractive (fewer
        // future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 40.0;
    } else {
        // Reward using existing bins, especially when many are open.
        score -= open_pressure * 0.8;
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer it over opening a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward
    // this placement (creates a perfect pairing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 50.0;
        } else if (gap as f64) < dead_threshold {
            score -= 15.0;
        }
    }
    // If next item cannot fit here regardless, slightly prefer bins that
    // leave larger usable residual for it elsewhere — penalize tight fits.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0;
    }

    // Mild tie-break toward bins whose residual is close to the mean
    // residual (balanced packing).
    score += ((post_residual as f64 - mean_residual) / (bin_capacity as f64)).abs() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fits (dead space eliminated).
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if post_residual as f64 == nr {
            score -= 500.0; // next item fills this bin exactly
        } else if (post_residual as f64 - nr).abs() <= 5.0 {
            score -= 200.0; // near-exact match for the follow-up item
        } else if post_residual >= next_item_size {
            score -= 50.0; // next item can also fit here
        } else {
            score += 30.0; // dead space relative to lookahead item
        }
    }

    // Prefer tighter bins relative to the mean residual of open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize opening a new bin when decent fits exist, especially early/mid stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 + 100.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate across many open bins.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills: squash residual advantage when post_residual is tiny.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 10 {
        score -= 5.0;
    }

    // Penalize dead space relative to the smallest useful item size.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += waste * waste * 40.0;

    // Lookahead: if the next item fits exactly (or well) after this placement, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 - slack.min(8.0) * 0.5;
    }
    // Lookahead: penalize placements that strand the next item (post_residual too small to matter).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin, especially late in the stream or
    // when plenty of open bins already fit the item.
    if bin_residual == bin_capacity {
        let mut open_penalty = 30.0;
        if fitting_bins_count > 0 {
            open_penalty += 10.0 * (fitting_bins_count as f64).min(5.0);
        }
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            open_penalty += 10.0 * progress;
        }
        // Large items justify fresh bins more than small ones.
        open_penalty -= (item_size as f64 - 50.0).max(0.0) * 0.3;
        score += open_penalty;
    }

    // Mildly favor bins whose residual is above the mean (consolidate emptier bins),
    // keeping tighter bins available for future small items.
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Slight preference for filling bins with less residual overall.
    score += bin_residual as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;
    // normalized post-residual, non-linear shaping
    let prn = pr / cap;
    // polynomial coupling of post-residual with stream progress:
    // early on, prefer filling bins tightly (penalize large post_residual less as stream progresses)
    let poly = prn * prn * (1.0 - progress) + prn * progress;
    // reward tight fits: item_size relative to bin_residual
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let tight_reward = -(fit_ratio * fit_ratio) * cap * (0.5 + progress);
    // penalty for creating dead space unusable by likely next item
    let dead = if next_item_size > 0 && pr > 0.0 && (pr < next_item_size as f64) {
        (pr * pr) / cap * (1.0 + progress)
    } else {
        0.0
    };
    // lookahead synergy: reward residual that fits next item
    let synergy = if next_item_size > 0 && pr >= next_item_size as f64 {
        -(next_item_size as f64 / cap) * (1.0 - progress)
    } else {
        0.0
    };
    // last-chance bin: strong reward to use it before opening new bin
    let last_chance = if fitting_bins_count == 1 { -2.0 * cap * (0.3 + progress) } else { 0.0 };
    // mild penalty for spreading across many bins relative to mean residual
    let spread = if open_bins_count > 0 { (pr - mean_residual).abs() * 0.05 * progress } else { 0.0 };
    // new-bin candidate: neutral-high baseline so it only wins when fits are terrible
    let new_bin_bias = if bin_residual == bin_capacity {
        cap * (0.6 + 0.4 * progress)
    } else {
        0.0
    };
    base + poly * cap * 0.5 + tight_reward + dead + synergy + last_chance + spread + new_bin_bias
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward small post_residual strongly (tight fit)
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left over
    // Dead-space penalty grows super-linearly for small but nonzero residuals
    if post_residual > 0 {
        score += 12.0 / (1.0 + pr).ln().max(0.5) * frac.sqrt();
    } else {
        score -= 20.0; // perfect fill
    }

    // Modulo-10 harmonic class: residual divisible by 10 pairs well with typical sizes
    if post_residual % 10 == 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 {
        score -= 2.0;
    } else {
        score += 3.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            let nfrac = (post_residual - next_item_size) as f64 / cap;
            score += 6.0 * nfrac; // penalize leaving awkward gap for next item
        } else {
            // next item won't fit here anyway; slight reward for large usable residual
            score -= 2.0 * frac;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residual is tiny/awkward
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if the only fitting bin would leave huge dead space, allow new bin
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 25.0;
        }
        // early in stream, opening bins is cheap-ish
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 5.0;
        }
    }

    // Prefer bins already below mean residual (consolidate fullness)
    score += (mean_residual - bin_residual as f64).max(-20.0).min(20.0) * 0.3;

    // Many open bins: discourage spreading, favor tight fits more
    score += (open_bins_count as f64).ln().max(0.0) * (pr / cap) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to host typical
    // future items are unusable -> heavy quadratic penalty.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if post_residual < 10 {
            score += 6.0 * (10.0 - dead) * (10.0 - dead);
        } else if post_residual < 20 {
            score += 1.5 * (20.0 - dead);
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room exactly for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
        score -= 10.0;
    }

    // Open-bins pressure: prefer consolidating into existing bins
    // (the new-bin candidate has bin_residual == bin_capacity and pays this tax).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_tax = 30.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += new_bin_tax;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer bins tighter than the average residual (good packing density).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Mild preference for filling larger residuals first when many bins open.
    score += 0.1 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Next item fits into post residual: mild reward scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Dead space: post_residual too small for next item (or nothing next) is wasted.
    if next_item_size == 0 || post_residual < next_item_size {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 12.0 * waste * waste;
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // and when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 10.0 * progress + 0.5 * open_bins_count as f64;
    }

    // Mild preference for tighter fits overall (small post residual).
    score += 0.05 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that likely can't fit future items (items >= 1).
    if post_residual > 0 {
        let dead = post_residual as f64;
        score += 12.0 * (1.0 - dead / bin_capacity as f64).powi(3);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, reward; if it would be
    // blocked by a tiny remainder, penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // New-bin candidate: only attractive when current open bins are crowded
    // (high mean residual utilization) or few bins fit the item.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score = bin_capacity as f64
            - 30.0 * crowding
            - (if fitting_bins_count <= 1 { 20.0 } else { 0.0 })
            + 5.0 * (open_bins_count as f64).sqrt();
    }

    // Early in the stream, be slightly more willing to spread items (cheap bins later).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: non-linear polynomial in normalized post_residual
    let x = post / cap; // 0..1
    let mut score = post;
    // cubic coupling: dead space penalized super-linearly
    score += 40.0 * x * x * x * cap * 0.01;
    // smooth interaction with stream progress: late in stream, dead space matters more
    score += 25.0 * x * x * (0.5 + progress);

    // Reward tight fits (small post residual) with a smooth bonus
    score -= 15.0 * (1.0 - x) * (1.0 - x);

    // Lookahead: reward if next item fits into post_residual, penalize near-miss waste
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 12.0 * (1.0 - nxt / cap);
        } else {
            // penalize residuals that are just barely too small (unusable slivers)
            let gap = (post - nxt).abs();
            score += 8.0 * (1.0 - gap / cap).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Mild penalty proportional to open bins to encourage consolidation early
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Deviation from mean residual: prefer bins close to mean (balanced packing)
    score += 0.3 * (post - mean_residual).abs();

    // New-bin candidate (empty bin): post_residual == cap - item; make it less attractive
    // unless open bins are scarce or item is large relative to residuals
    if bin_residual == bin_capacity {
        score += 20.0 + 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which "slot" of capacity it falls into.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter; // 0..=4 harmonic class

    // Reward small post-residuals (tight fits), strongest for exact fit.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= quarter / 4 {
        score -= 30.0;
    } else {
        score += class as f64 * 6.0;
    }

    // Modulo coupling: residual divisible by common item sizes is reusable.
    if post_residual > 0 {
        let mut reusable = 0.0;
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                reusable += 8.0;
            }
        }
        score -= reusable;
    } else {
        score -= 10.0;
    }

    // Lookahead: if the next item fits the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            score -= 15.0;
        } else {
            // next item won't fit here: penalize wasted potential
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish score so it wins only when
    // all open bins are poor fits.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.15 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 20.0;
        }
    }

    // Late in the stream, prefer closing bins out (consolidation pressure).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 12.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Dead space: gaps too small for the smallest plausible item (1..100 interface).
        // Treat gaps below ~12 as near-dead, ramping penalty as gap shrinks.
        if gap < 12.0 {
            score += (12.0 - gap) * 3.0;
        }
        // Non-linear coupling: penalize gaps that can't fit the lookahead item
        // but are still nonzero (wasted potential for next_item_size).
        if next_item_size > 0 && (post_residual as u32) < next_item_size {
            score += 4.0 + 0.05 * (next_item_size as f64 - gap);
        }
    } else {
        // Perfect fit: strong reward.
        score -= 15.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_frac * fill_frac;

    // Open bins pressure: when many bins are open, favor consolidating into
    // existing bins (penalize opening new ones); when few bins, be lenient.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = (open_bins_count as f64).ln().max(0.0);
        score += 6.0 + 4.0 * pressure;
        // Last-chance fitting: if this is the only fitting bin, strongly avoid new bin.
        if fitting_bins_count == 1 {
            score += 25.0;
        }
        // Late in the stream, opening new bins is more acceptable (fewer future
        // items to consolidate), soften the penalty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * progress;
    } else {
        // Reward using an existing bin, especially when it fits the lookahead.
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 5.0;
        }
    }

    // Mean-residual coupling: if this bin's post_residual deviates favorably
    // from the mean (smaller gap), reward it.
    score += 0.15 * (mean_residual - post_residual as f64).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits: zero post residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits exactly or nearly: strong reward.
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to wasted lookahead.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.6 * miss;
        }
    }

    // Penalize small unusable residuals (dead space below minimum item size ~1).
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.35 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: make it mildly unattractive unless residuals are fragmented.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // If next item is large and current bins are tight, new bin is fine.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 20.0;
        }
    }

    // Late in stream: prefer closing bins tightly (consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving tiny dead space that few future items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size > post_residual {
            score += 8.0; // post residual becomes dead-ish space
        } else {
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 10.0 * next_fit;
        }
    } else {
        // Last item: prefer filling a bin completely.
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Time horizon: early in the stream, be conservative (keep residuals large);
    // late in the stream, pack aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state: when many bins are open with large mean residual, prefer
    // consolidating into bins below mean residual (reduce fragmentation).
    if open_bins_count > 2 && mean_residual > 0.0 {
        let dev = (bin_residual as f64 - mean_residual) / mean_residual;
        score += 12.0 * dev;
    }

    // New-bin candidate handling: an empty bin is a fallback; make it mildly
    // attractive only when this placement would waste a lot of space.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64;
        score = 55.0 + waste * 0.6 - 20.0 * fit_ratio;
        if fitting_bins_count == 1 {
            score += 50.0; // don't open a new bin when this is the only fit
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear reward for tight fits: quadratic coupling of post_residual with progress
    let tight = pr / cap;
    score -= 24.0 * (1.0 - tight * tight) * (0.5 + progress);

    // Penalize residual that no plausible next item can use (dead space), smooth coupling
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (pr - nxt).abs();
        let gap_norm = gap / cap;
        score += 14.0 * gap_norm * gap_norm * (1.0 + progress);
        // Reward lookahead exactly filling the remaining space
        if nxt <= pr {
            score -= 10.0 * (1.0 - gap_norm) * (1.0 - gap_norm);
        }
    } else {
        // Last item: strongly prefer minimizing final residual
        score += 0.5 * pr * pr / cap;
    }

    // Last-chance bin: reward strongly if this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - tight * tight);
    } else if fitting_bins_count > 1 {
        // Slight penalty when many alternatives, prefer the tightest anyway
        score += 2.0 * (fitting_bins_count as f64).ln() * tight;
    }

    // New empty bin candidate: penalize unless residuals across bins are large
    if bin_residual == bin_capacity {
        let mean_tight = mean_residual / cap;
        score += 18.0 + 25.0 * (1.0 - mean_tight) * (1.0 - progress);
    }

    // Mild penalty for bin proliferation late in the stream
    score += (open_bins_count as f64).ln() * tight * 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "nice" the leftover is.
    // Residuals divisible by 10 are highly reusable (classic sizes); penalize odd leftovers.
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,                     // perfect fit - best outcome
        x if x % 20 == 0 => 1.0,      // excellent reusable class
        x if x % 10 == 0 => 2.0,      // good reusable class
        x if x % 5 == 0 => 3.0,       // moderate
        _ => 4.0,                     // awkward dead space
    };
    score += class * 4.0;

    // Strong reward for exact fit.
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead: does the leftover admit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Check harmonic compatibility of leftover with next item (mod 10 alignment)
            let compat = if (pr - next_item_size) % 10 == 0 { 0.0 } else { 8.0 };
            score -= 12.0 + compat;
        } else {
            // Leftover too small for next item: penalize proportionally to waste
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when current fit is bad
    // (large awkward post_residual) or stream is early and bins are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let badness = (post_residual as f64 / cap) * 30.0;
        score = 35.0 + badness - progress * 10.0 - (open_bins_count as f64).min(10.0) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can hold anything
        }
    }

    // Mild preference for tighter bins (small residual before placement).
    score += (bin_residual as f64 / cap) * 3.0;

    // Prefer bins whose residual is close to the item (snug fit).
    let snug = (bin_residual as f64 - item_size as f64) / cap;
    score += snug * 10.0;

    // Mean residual coupling: when open bins are generally full, conserve space.
    if mean_residual < 15.0 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically below next item or typical min) are pure waste.
    let dead_threshold = 10u32; // smallest realistic item footprint
    if post_residual < dead_threshold {
        score -= 60.0; // perfect fill bonus: gap unusable anyway
    } else if post_residual < item_size.min(20) {
        score += 25.0; // near-dead gap: penalize hard
    }

    // Penalize gaps that the NEXT item cannot use (lookahead dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.3 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving a gap exactly consumable by next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Open-bin pressure: discourage proliferation of bins late in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Prefer bins tighter than the average residual (good consolidation).
    score -= 0.2 * (mean_residual - post_residual as f64);

    // New-bin candidate: make it mildly attractive only when all fits are bad.
    if bin_residual == bin_capacity {
        // Opening new bin is neutral-ish; fitting bins get big discounts above,
        // so new bin only wins when existing bins score poorly (dead gaps).
        score += 8.0 + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 - slack.min(40.0) * 0.5;
        } else {
            // Wasted opportunity: leftover too small for the lookahead item.
            let waste = (next_item_size - post_residual) as f64;
            score += waste.min(60.0) * 0.6;
        }
    }

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 25.0;

    // Penalize bins far from the mean residual (prefer balanced usage),
    // unless this is a last-chance bin.
    let dev = ((post_residual as f64) - mean_residual).abs();
    if fitting_bins_count > 1 {
        score += dev * 0.15;
    }

    // Last-chance bin: heavily favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: only attractive when few/no fitting bins exist
    // or the current fit is very poor.
    if bin_residual == bin_capacity {
        let good_alternative = fitting_bins_count > 0
            && (next_item_size == 0 || post_residual >= next_item_size);
        if good_alternative {
            score += 80.0; // discourage opening a new bin when fits exist
        } else {
            score -= 10.0; // encourage fresh bin when fits are poor
        }
    }

    // Late in the stream: consolidate, avoid leaving many small open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual more strongly.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Penalize dead space that is too small to be useful for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
