    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when fit is poor.
    if bin_residual == bin_capacity {
        score += 8.0 + mean_residual * 0.05;
        // Early in stream, keep bins open; late, be more willing to open new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 6.0;
    }

    // Prefer filling bins that are already relatively full (small residual).
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if open_bins_count > 2 && mean_residual > 30.0 {
        score += 4.0;
    }

    score
