pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * (0.5 + 0.5 * progress);

    let mut score = post * (1.0 + 0.35 * poly);

    // Reward tight fits smoothly
    let fit_frac = item_size as f64 / cap;
    score -= 12.0 * fit_frac * (1.0 - norm_post) * (0.6 + 0.4 * progress);

    // Penalize last-chance bins less when they fit well
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_post);
    }

    // New-bin candidate handling: penalize early, reward late smoothly
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64 / (1.0 + open_bins_count as f64)).sqrt();
        score += 6.0 * openness * (1.0 - progress) - 10.0 * progress * (1.0 - openness);
    }

    // Lookahead coupling: smooth interaction with next item size
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        score += 5.0 * nx * norm_post * (1.0 - nx * norm_post);
    }

    // Mean residual drift penalty (smooth)
    score += 0.05 * (mean_residual - post).abs() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space, amplified near full bins.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste * waste;

    // Harmonic classes: bins whose residual falls into "useful" small classes are precious.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, ideal
    } else if pr <= 10 {
        score -= 25.0; // nearly perfect, dead space negligible
    } else if pr <= 20 {
        score -= 10.0;
    } else {
        // Dead-space penalty grows for awkward residuals: those in (20, 30] or (50, 60]
        // rarely fit future items of common sizes.
        if (pr > 20 && pr <= 30) || (pr > 50 && pr <= 60) {
            score += 18.0;
        }
        // Modulo-10 classes: residual divisible by 10 tends to combine with typical items.
        if pr % 10 == 0 {
            score -= 6.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            score -= 20.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit here; residual is likely final -> penalize leftover.
            score += 0.15 * pr as f64;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, force usage.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity; only attractive
    // when all open bins would create large dead space or bins are scarce.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin relative to stream progress.
        score = 55.0 + 30.0 * (step_index as f64 / (total_items.max(1) as f64));
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // fresh bin useful for a larger upcoming item
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If open bins have large mean residual, prefer reusing them.
        score += 0.5 * mean_residual;
        if open_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // Favor reusing bins with smaller residuals (best-fit flavor) mildly.
        score += 0.05 * mean_residual;
    }

    // Early stream: be slightly more willing to open bins to build flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 10.0;
    }

    score
}

