pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later on, prefer reusing existing bins more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 25.0;

    // Penalize dead space that is too small for the next item (unusable gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving space exactly usable by the next item.
        score -= 6.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    if open_bins_count > 4 {
        score -= (open_bins_count as f64).ln() * 4.0;
    }

    // Coupling with mean residual: bins far below mean residual have room; prefer
    // filling bins whose residual is close to the item (avoid fragmenting large gaps).
    let residual_gap = (bin_residual as f64 - mean_residual).abs();
    score += residual_gap * 0.15;

    // New empty bin candidate: keep it unattractive unless the fit elsewhere is hopeless.
    if bin_residual == bin_capacity {
        score += bin_capacity as f64 * 0.9 + open_bins_count as f64 * 2.0;
        // If item is large relative to capacity, opening a fresh bin is more acceptable.
        if item_size as f64 > bin_capacity as f64 * 0.7 {
            score -= 30.0;
        }
        // Early in the stream, new bins are cheaper.
        score -= (1.0 - progress) * 15.0;
    }

    // Slight preference for bins with larger residual when item is big.
    if item_size > 50 {
        score += (bin_capacity - bin_residual) as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits (small post_residual) matter more.
    let w = 1.0 + 2.0 * progress * progress;
    score = score * w - (cap - post) * (cap - post) / cap * (0.5 + progress);

    // Reward filling a bin nearly exactly, stronger as stream advances.
    score -= (1.0 - post / cap).powi(4) * cap * (0.3 + 0.7 * progress);

    // Penalize creating tiny dead space that likely wastes capacity.
    let dead = post / cap;
    score += dead * (1.0 - dead) * cap * 0.4 * (1.0 - progress);

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= (1.0 - (post - nxt) / cap) * 10.0;
        } else {
            score += 8.0;
        }
    }

    // Mild penalty for spreading across many open bins with large mean residual.
    score += 0.02 * open_bins_count as f64;
    score += 0.05 * (mean_residual - post).abs();

    // New-bin candidate: neutral-ish baseline with slight progress-dependent bias.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity remaining

    // Reward tight fits: post_residual small relative to capacity
    if post_residual == 0 {
        score -= 60.0; // perfect fit, huge reward
    } else if frac <= 0.10 {
        score -= 40.0;
    } else if frac <= 0.25 {
        score -= 20.0;
    } else if frac <= 0.50 {
        score -= 5.0;
    } else {
        score += 10.0; // wasteful placement, leaves more than half
    }

    // Dead-space penalty: leftover that is too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // chainable: reward, scaled by how well it chains
            let chain_tightness = (post_residual - next_item_size) as f64;
            score -= 15.0 - (chain_tightness / cap) * 10.0;
        } else {
            // next item won't chain here; mild penalty proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / cap) * 12.0;
        }
    }

    // Last-chance bin logic: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline opening cost,
    // reduced when many bins are open or stream is early (consolidation later).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 35.0 - 20.0 * progress + (open_bins_count as f64).sqrt() * 2.0;
        // If no open bin fits well, opening a new bin is more acceptable
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Harmonic modulo classes on post_residual: bins whose residual is a
    // multiple of common item sizes (10,20,25,50) are more reusable.
    if post_residual > 0 && post_residual < bin_capacity {
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual % 25 == 0 {
            score -= 4.0;
        }
        if post_residual % 50 == 0 {
            score -= 4.0;
        }
        // awkward odd residuals are less reusable
        if post_residual % 2 == 1 {
            score += 2.0;
        }
    }

    // Prefer filling bins with larger residuals when mean residual is high (consolidation)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

