    // or the bin pool is empty.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        // Base cost of a new bin grows with stream progress (sunk bins matter more later).
        let mut new_bin_cost = 30.0 + 40.0 * progress;
        // If many open bins with slack mean residual, opening more is wasteful.
        new_bin_cost += 0.5 * open_bins_count as f64;
        // If mean residual is small (bins nearly full), a new bin is more acceptable.
        new_bin_cost -= 0.3 * mean_residual;
        // If no existing bin fits, the new bin cost should vanish.
        score += new_bin_cost * scarcity;
    }

    // Mild preference for bins with residuals near mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling: reward tight fits more strongly as stream progresses
    let tightness = 1.0 - fit_ratio;
    let poly = tightness * tightness * (1.0 + 2.0 * progress);
    score -= 30.0 * poly;

    // Penalize post-residual that is small but unusable (dead space) via smooth valley
    let dead = (1.0 - fit_ratio) * fit_ratio * 4.0; // peaks at fit_ratio = 0.5
    score += 12.0 * dead * (0.5 + progress);

    // Last-chance bonus: strongly prefer this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if n <= pr {
            score -= 10.0 * (1.0 - (n / cap)) * (1.0 + progress);
        } else {
            score += 8.0 * (1.0 - fit_ratio);
        }
    }

    // Mild pressure toward consolidating bins when many are open
    score += 0.3 * open_bins_count as f64 * fit_ratio;

    // Slight preference for bins below mean residual (fill emptier bins first)
    score += 0.1 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but dead space below the
    // smallest useful class is worthless — penalize it harder.
    if post_residual > 0 {
        // Harmonic class of post_residual: which capacity fraction does it land in?
        let quarter = (bin_capacity / 4).max(1);
        let eighth = (bin_capacity / 8).max(1);
        if post_residual <= eighth {
            score -= 30.0; // tiny dead space, essentially a perfect fit
        } else if post_residual <= quarter {
            score -= 12.0;
        } else if post_residual >= bin_capacity / 2 {
            score += 15.0; // half-empty bin wasted on a small item
        }
    } else {
        score -= 40.0; // exact fill — ideal
    }

    // Modulo class logic on post_residual: residuals that are "friendly"
    // (divisible by common item sizes) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let friendly = pr % 10 == 0 || pr % 20 == 0 || pr % 25 == 0 || pr % 50 == 0;
        if friendly { score -= 8.0; }
        // Odd residuals unlikely to be refilled exactly.
        if pr % 2 == 1 { score += 4.0; }
        // Small awkward leftovers in (0,10) can never be reused (items >= 1... but tiny).
        if pr < 5 { score += 6.0; }
    }

    // Lookahead coupling: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward if next item fits well (harmonic class match via integer division)
            let fits_classes = pr / next_item_size.max(1);
            if fits_classes >= 2 {
                score -= 10.0; // room for multiple future items
            } else {
                score -= 5.0;
            }
            // Exact harmony: post_residual is a multiple of next item
            if pr % next_item_size == 0 { score -= 12.0; }
        } else {
            // Next item won't fit here; if this was the last fitting bin,
            // a new bin is unavoidable anyway — soften penalty.
            if fitting_bins_count == 1 {
                score += 3.0;
            } else {
                score += 10.0;
            }
        }
    }

    // Last-chance bin logic: if this is the ONLY bin that fits, strongly favor
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it is only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.1;
        // Late in the stream, avoid leaving many half-full bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
        return score;
    }

    // Fragmentation pressure: if mean residual across bins is high, we are
    // scattering items — prefer bins below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Slight preference for keeping fewer open bins when stream is long.
    score += (open_bins_count as f64).sqrt() * 0.5;

    // Harmonic threshold: integer division classes of residual vs capacity.
    let k = bin_residual / (bin_capacity / 10).max(1); // decile class
    match k {
        0 | 1 => score -= 10.0, // nearly full bin, use it up
        9 | 10 => score += 8.0, // nearly empty bin, wasteful
        _ => {}
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (min size 1,
    // but practically < 10 is near-dead) are heavily penalized.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 20.0;
    }

    // Reward tight fits (small post residual) non-linearly.
    score -= 40.0 * (-post_residual as f64 / 15.0).exp();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Pressure from number of open bins: when many bins are open, prefer
    // packing into existing ones over spreading out.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate: only attractive when the item is large (would leave
    // little dead space anyway) or no existing bin fits well.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        score += 45.0;                 // base cost of opening a new bin
        score -= 50.0 * fill;          // large items justify a fresh bin
        if fitting_bins_count <= 1 {
            score -= 40.0;             // no real alternative
        }
        // If the next item could use the residual of this fresh bin, soften cost.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 12.0;
        }
    } else {
        // Existing bin: mild bonus if lookahead item also fits the post residual.
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 8.0;
        }
    }

    // Late in the stream, consolidate aggressively into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 15.0 * progress;
    }

    // Prefer bins whose residual is close to the mean (avoid fragmenting outliers).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a 2-step perfect chain: item now, next item fills post_residual exactly.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 40.0; // exact chain match
        }
    }

    // Penalize dead space relative to the mean residual of open bins.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Penalize large post residuals (wasted capacity) nonlinearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.3 * (pr / cap) * (pr / cap) * cap;

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Early in the stream, prefer opening new bins to build a diverse pool.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    } else {
        score += 8.0 * (1.0 - progress);
    }

    // Late in the stream, consolidate into existing bins.
    score += 5.0 * progress * (open_bins_count as f64).ln();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste ratio penalty).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that nothing (>=10) can use later.
    if post_residual < 10 {
        score -= 25.0; // perfect fill is great
    } else if post_residual < item_size {
        score += 8.0; // dead wedge smaller than typical items
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            // residual too small for next item: penalize proportionally
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when existing residuals are tight.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_tightness = 1.0 - mean_residual / bin_capacity as f64;
        // penalty shrinks when open bins are crowded or stream is late
        let mut open_penalty = 60.0 - 40.0 * avg_tightness - 20.0 * progress;
        if open_bins_count == 0 {
            open_penalty = -100.0; // must take a bin
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            open_penalty -= 10.0; // fresh bin guarantees fit for lookahead
        }
        score += open_penalty.max(-100.0);
    } else {
        // Prefer bins with larger residuals among open bins (keep small-residual bins for small items).
        score -= 0.05 * bin_residual as f64;
        // Encourage consolidation when many bins are open.
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: penalize wasted space, quadratically (dead space is super-linearly bad)
    let mut score = norm_pr * norm_pr * cap;

    // Smooth coupling: waste matters more as stream progresses (fewer chances to reuse)
    let urgency = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += urgency * norm_pr * cap * 0.8;

    // Reward tight fits: item_size relative to residual, smooth saturation
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= tightness * tightness * 12.0;

    // Lookahead: if next item fits into post_residual, big reward (smooth)
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        let next_norm = next_item_size as f64 / cap;
        score -= fits_next * (1.0 - next_norm) * (1.0 - next_norm) * 15.0;
        // penalize leaving a residual that almost-but-not-quite fits next item
        let gap = (pr - next_item_size as f64).abs();
        score += fits_next * (gap / cap) * 3.0;
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + urgency * 10.0;
    }

    // Mild penalty when many bins open and this placement is wasteful
    score += (open_bins_count as f64).ln().max(0.0) * norm_pr * 2.0;

    // Slight bias toward using existing bins vs new bin (new bin has norm_pr == 1)
    score -= 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the post residual modulo capacity quarters.
    let quarter = bin_capacity / 4; // 25
    let class = post_residual % quarter;
    // Residuals in the "dead zone" (1..=10) are nearly unusable waste.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Residuals just above half are valuable (fit most items) - reward.
    if post_residual >= bin_capacity / 2 {
        score -= 15.0;
    }
    // Modulo-class bonus: residual that is a clean multiple of quarter is harmonious.
    if class == 0 && post_residual > 0 {
        score -= 8.0;
    } else if class <= 5 && post_residual > 10 {
        score += 5.0; // awkward small remainder
    }

    // Lookahead coupling: if next item fits into post_residual, this bin stays useful.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (post_residual - next_item_size) as f64 * 0.2;
    } else if next_item_size > 0 && post_residual > 0 {
        // post residual can't hold next item: dead space risk, penalize more when small.
        score += (post_residual as f64).min(30.0) * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty full-capacity bin gets baseline treatment.
    if bin_residual == bin_capacity {
        // Prefer reusing open bins when they fit reasonably well; make new bin costly
        // unless the current item is large and mean residual across bins is fragmented.
        let reuse_pressure = (open_bins_count as f64) * 0.4 + mean_residual * 0.1;
        score += 20.0 + reuse_pressure;
        // Late in stream, opening new bins is fine since leftovers won't be reused much.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 18.0;
    }

    // Slight preference for bins whose residual is close to item size (tight packing),
    // measured via relative slack.
    let slack_ratio = post_residual as f64 / bin_capacity as f64;
    score += slack_ratio * slack_ratio * 20.0;

    // Mild tie-break by bin index proxy: fewer open bins preferred (keep packing compact).
    score += (open_bins_count as f64).ln() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are pure waste.
    let min_item = 1u32;
    let dead = post_residual < min_item && post_residual > 0;
    if dead {
        score += 50.0; // tiny but nonzero dead gap is worst possible
    }
    // Penalize gaps below the next item's needs harder (they become dead for lookahead too).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.8 * (next_item_size - post_residual) as f64;
    }

    // Reward near-perfect fits nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, mild encouragement to fill.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += 0.15 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: prefer it only when this bin would leave a large unusable residue
    // or when the bin is already near-empty relative to mean residual.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with number of open bins.
        score = 0.55 * bin_capacity as f64 + 1.2 * open_bins_count as f64;
        // Lookahead: if next item fits comfortably in a fresh bin, opening is more attractive.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 0.5 * next_item_size as f64;
        }
        // Late in the stream, avoid proliferating bins.
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: residual consumed by next item
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving residual that likely becomes dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste.min(50.0);
        }
    }

    // Relative to mean residual: bins with less residual than average are more precious.
    let diff = mean_residual - post_residual as f64;
    score += 0.15 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize tiny unusable residuals (dead space) unless they match lookahead.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Progress-based caution: late in stream, avoid opening new bins unnecessarily.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when no good fit exists elsewhere.
        score += 40.0 - 20.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Many open bins: favor filling existing ones to consolidate.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity && bin_capacity >= item_size;

    if is_new_bin {
        // Opening a new bin is only attractive when the item is large
        // (poor fit elsewhere) or very late in the stream.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score = bin_capacity as f64 * 0.6
            - fill_ratio * 40.0
            + progress * 10.0
            + (open_bins_count as f64).powf(1.2) * 2.0;
        // If the next item could also fit a fresh bin after this one, mildly favor opening.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 8.0;
        }
        return score;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= tightness * tightness * 20.0;

    // Lookahead: strong reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 - slack.min(15.0) * 0.5;
        } else {
            // Penalize leaving a residual just barely too small for the next item.
            let miss = (next_item_size - post_residual) as f64;
            if miss <= 20.0 {
                score += miss * 0.6;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // With many fitting bins, prefer the emptiest-ish bins to consolidate.
        if bin_residual as f64 > mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    // Early in the stream, be slightly more willing to leave room (future flexibility);
    // late in the stream, just fill things up.
    score += (1.0 - progress) * (post_residual as f64) * 0.15;

    // Penalize creating very small dead space that is hard to reuse.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Mild penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic penalty on post residual (dead space), modulated by progress
    let base = norm_pr * (1.0 + 0.6 * progress) + 0.5 * norm_pr * norm_pr;

    // Smooth coupling: large post residual is worse late in the stream
    let progress_coupling = -0.3 * progress * norm_pr * (1.0 - norm_pr);

    // Reward tight fits (small post residual) with smooth exponential term
    let tight_fit = -0.4 * (-(pr / (cap * 0.5))).exp();

    // Lookahead: penalize if post residual can't fit next item, reward if it can
    let lookahead = if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fits = (norm_pr - nx).max(0.0);
        -0.5 * fits + 0.4 * (nx - norm_pr).max(0.0)
    } else {
        0.0
    };

    // Last-chance bin: strong reward to use it rather than open a new bin
    let last_chance = if fitting_bins_count == 1 { -0.8 } else { 0.0 };

    // New-bin candidate: mildly penalize opening new bins early, less late
    let new_bin_bias = if bin_residual == bin_capacity {
        0.6 - 0.4 * progress
    } else {
        0.0
    };

    // Slight preference for bins with residual near mean (balance)
    let mean_align = 0.15 * (norm_pr - mean_residual / cap).abs();

    let score = (base + progress_coupling + tight_fit + lookahead + last_chance + new_bin_bias + mean_align) * cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "useful" classes
    // (multiples of small divisors leave room for common item sizes).
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -50.0 // perfect fit, best possible
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else if pr % 2 == 0 {
        -2.0
    } else {
        3.0 // odd residual = awkward dead space
    };
    score += class_bonus;

    // Lookahead coupling: if next item exactly fills post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            let npr = pr - next_item_size;
            // harmonic class of the double-fit residual
            if npr % 10 == 0 {
                score -= 6.0;
            } else if npr % 5 == 0 {
                score -= 3.0;
            }
            score += npr as f64 * 0.15;
        } else {
            // next item won't fit here: penalize by how much slack is wasted
            score += (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Tightness reward: fraction of bin consumed by this item.
    let fill = item_size as f64 / cap;
    score -= fill * 10.0;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + (item_size as f64 / bin_residual as f64) * 10.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the fit here
    // is bad (large post_residual relative to capacity) and there are many bins.
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: penalize so we only open when fits are poor
        score = cap * 0.55 + mean_residual * 0.1;
        if fitting_bins_count == 0 {
            score -= 20.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 5.0; // big next item benefits from a fresh bin
        }
    }

    // Late-stream consolidation: prefer packing into existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 / cap) * (1.0 - progress) * 2.0;
    score -= progress * 3.0;

    // Mild pressure against bin sprawl.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 60.0 * (10.0 - dead) / 10.0; // tiny slivers are worst
        }
        // Mid-range gaps (10..=20) are risky too, since items >= 10.
        if dead >= 10.0 && dead < 20.0 {
            score += 15.0;
        }
    }

    // Reward tight fits (post_residual small relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new bins
    // (the new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 6.0;
        score += 30.0 + pressure;
        // Late in the stream, opening new bins is even less attractive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If the next item fits nicely in the fresh residual, soften the penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            let wasted = bin_capacity - next_item_size;
            if wasted <= 30 {
                score -= 15.0;
            }
        }
    } else {
        // Favor bins whose residual is close to the mean (balance load),
        // mildly, to avoid fragmenting one bin while others stay full.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Lookahead: if the next item exactly fits the post residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    }
    // Penalize leaving a gap that the next item cannot use but that is too
    // small for typical items.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual can still fit the next item: mild reward, stronger when snug
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - 0.15 * slack;
    }

    // Post residual too small for next item: dead space penalty, scaled by how close we were
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let miss = (next_item_size - post_residual) as f64;
        score += 5.0 + 0.5 * miss;
    }

    // Relative to mean residual: prefer bins whose post residual is below average
    // (consolidating space), penalize leaving above-average residual.
    let pr = post_residual as f64;
    score += 0.3 * (pr - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists or stream is early
    if bin_residual == bin_capacity {
        let early = (step_index as f64) / (total_items.max(1) as f64);
        let penalty = 35.0 - 20.0 * early;
        score += penalty;
        // A new bin is better if the item would leave a large unusable residual elsewhere
        if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Slight preference for tighter fits overall
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squash post_residual so near-exact fits dominate.
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64).powi(3);
    score -= 45.0 * fit_quality;

    // Perfect fill is a jackpot.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize dead space that is too small for typical items (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // sliver waste
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remainder; penalize proportionally
            score += 0.25 * (next_item_size.saturating_sub(post_residual)) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin wastes capacity = post_residual (full 100 here).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer new bin only when current fit is bad and many bins are open.
        let fit_badness = post_residual as f64 / item_size as f64; // large if item barely fits
        let pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (step_index as f64 / (total_items.max(1) as f64 + 1.0));
        score += 25.0 - 30.0 * fit_badness.min(1.0) - 20.0 * pressure;
    }

    // Global state: when mean residual is high, prefer consolidating into bins with low residual.
    let rel = if mean_residual > 0.0 { bin_residual as f64 / mean_residual } else { 1.0 };
    score += 6.0 * (rel - 1.0).clamp(-1.5, 1.5);

    // Mild preference for fuller bins late in the stream (encourage closing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 8.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    // Slight penalty on bin count explosion: favor bins already open.
    score += 0.15 * open_bins_count as f64 * (1.0 - fit_quality);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr * norm_pr);

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= (cap - pr) * 0.35 * (1.0 + progress);

    // Penalize dead space that is too small to be useful: smooth quadratic term
    score += 0.5 * norm_pr * (1.0 - norm_pr) * cap * 0.2;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        let fit_ratio = next_item_size as f64 / pr.max(1.0);
        score -= 8.0 * fit_ratio * (1.0 + progress);
    } else if next_item_size > 0 {
        // next item won't fit here; mild penalty grows with progress
        score += 4.0 * progress;
    }

    // Discourage spreading across many bins when mean residual is high
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - pr).abs() * 0.1;

    // New-bin candidate handling: empty bin gets neutral-ish score unless current fits are poor
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.1 * progress) - 0.5 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which capacity fraction band it falls into
    let item_class = (item_size * 4) / bin_capacity; // 0..=3 (quarters)
    let post_class = (post_residual * 4) / bin_capacity;

    // Reward placements whose post-residual class matches a "useful" harmonic band.
    // Small post-residuals are excellent (tight fit); mid residuals are dead space.
    match post_class {
        0 => score -= 18.0,                       // residual < 25: near-perfect fill
        1 => score -= 6.0,                        // residual 25..50: still usable
        2 => score += 8.0,                        // residual 50..75: awkward dead zone
        _ => score += 2.0,                        // residual >= 75: large but wasteful use
    }

    // Modulo-arithmetic coupling: if post_residual is a multiple of a common
    // item granularity (10/20/25), future items can land cleanly.
    if post_residual > 0 {
        let clean = (post_residual % 10 == 0) as i32
            + (post_residual % 20 == 0) as i32
            + (post_residual % 25 == 0) as i32;
        score -= 4.0 * clean as f64;
    } else {
        score -= 25.0; // exact fill: perfect
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match between post_residual and next item
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot follow here; penalize more if leftover is a
            // "dead" mid-band size that nothing typical fits into.
            if post_residual < 10 {
                score += 15.0; // sliver: nearly useless
            } else if post_residual < 30 {
                score += 6.0;
            }
        }
    } else {
        // Last item: only tightness matters
        score = post_residual as f64 - 5.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening for a mediocre fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
    }

    // New-bin candidate handling: prefer new bin only when the item fits
    // badly everywhere (large item, no harmonic synergy).
    if bin_residual == bin_capacity {
        // Base penalty so new bins aren't opened casually.
        score += 30.0;
        // But if item is large (>= half capacity), a fresh bin is harmonically sound.
        if item_size * 2 >= bin_capacity {
            score -= 20.0;
        }
        // If many bins are open with high mean residual, consolidating is better.
        score += (mean_residual / bin_capacity as f64) * 10.0;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
    }

    // Slight preference for bins whose residual is harmonically aligned
    // with the item itself (item divides residual class structure).
    if bin_residual >= item_size {
        let r = bin_residual % item_size.max(1);
        if r == 0 {
            score -= 5.0; // item exactly tiles remaining space over repeats
        } else if r < 10 {
            score += 3.0; // leaves a sliver on repeat
        }
    }

    // Mild crowding pressure: with many open bins, favor tight fills.
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_capacity - post_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item if it fits in the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + next_item_size as f64 * 0.1;
    }
    // Penalize if the leftover is just barely too small for the next item (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer packing into existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or residual is high elsewhere.
        score += 15.0 + pressure * 4.0 + mean_residual * 0.2;
    } else {
        score -= pressure;
    }

    // Slight preference for bins tighter than average (less wasted space).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Late in the stream, be more conservative about opening new bins.
    if total_items > 0 && step_index * 2 >= total_items && bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small dead space relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness).powi(3);

    // Aggressive 2-step lookahead: perfect chain match (item + next item fills bin).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Partial lookahead reward: next item still fits after this placement.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit in the post-residual: penalize wasted lookahead.
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Compare post_residual against mean residual of open bins.
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when alternatives exist.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 1 {
            score += 120.0;
        } else if fitting_bins_count == 1 {
            score += 70.0;
        } else {
            score -= 10.0; // no alternative: opening is fine
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    score += 0.05 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let last_chance = fitting_bins_count == 1 && !is_new_bin;

    // Reward tight fits: heavily discount bins whose post-residual is small.
    if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 25 {
        score -= 12.0;
    } else {
        // Superlinear penalty for wasted space, softened late in the stream.
        score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 40.0 * (1.0 - 0.3 * progress);
    }

    // Lookahead: if next item fits perfectly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 15.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Dead space that next item cannot use.
            score += 8.0;
        }
    }

    // Penalize opening a new bin when a decent fit already exists,
    // unless the item is large and the fit would be very tight elsewhere.
    if is_new_bin {
        let fit_quality = bin_residual.saturating_sub(item_size);
        let spread = open_bins_count as f64;
        let open_penalty = 20.0 + 2.0 * spread.min(20.0);
        if fit_quality == 0 {
            score -= 40.0; // perfect fit in existing bin beats new bin
        } else {
            score += open_penalty * (1.0 - 0.4 * progress);
            // If mean residual is high, existing bins are roomy; new bin less needed.
            score += (mean_residual / 20.0).min(15.0);
        }
    }

    // Last-chance bonus: strongly favor the only bin that can fit the item.
    if last_chance {
        score -= 18.0;
        if post_residual <= next_item_size.max(1) {
            score -= 10.0;
        }
    }

    // Mild preference for consolidating among many open bins.
    score -= (bin_residual as f64 - mean_residual).clamp(-30.0, 30.0) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: mild preference for tight fits; Late: strong penalty on dead space.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score += 40.0 * poly * (1.0 - 0.5 * progress);

    // Reward using an existing bin instead of opening a new one (empty-bin candidate).
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress;
    } else {
        score -= 8.0;
    }

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr as f64 >= n {
            score -= 10.0 * (1.0 - ((pr - n) / cap).min(1.0));
        } else {
            score += 6.0 * (n - pr) / cap;
        }
    }

    // Coupling with mean residual: prefer bins near the mean (balanced packing).
    let dev = (pr - mean_residual).abs() / cap;
    score += 12.0 * dev * dev;

    // Slight preference for bins with smaller residuals among fitting bins.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quarter classes of capacity
    let q = post_residual / (bin_capacity / 4).max(1);
    let class_bonus: f64 = match q {
        0 => -40.0,                       // perfect/near-perfect fill
        1 => -18.0,                       // still very usable
        2 => 0.0,                         // half-cap residual
        3 => 12.0,                        // small sliver, likely dead
        _ => 20.0,
    };
    score += class_bonus;

    // Fine-grained: reward exact tight fits via integer division residue
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Modulo-arithmetic class: post_residual divisible by common item sizes (5,10,20,25)
    if post_residual > 0 {
        let pr = post_residual;
        if pr % 10 == 0 { score -= 10.0; }
        else if pr % 5 == 0 { score -= 5.0; }
        if pr % 25 == 0 { score -= 6.0; }
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 22.0;
            // extra reward for exact harmonic match
            if post_residual - next_item_size <= 3 { score -= 15.0; }
        } else {
            score += 8.0;
        }
        // penalize leaving a residual that only fits tiny items
        if post_residual >= next_item_size && post_residual - next_item_size < 10 && post_residual - next_item_size > 0 {
            score += 6.0;
        }
    } else {
        // last item: prefer tightest fit anywhere
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Crowd effect: many open bins -> prefer consolidation into existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.35 + 0.5 * progress);

    // Mean residual anchor: bins far from mean residual are less attractive
    score += (post_residual as f64 - mean_residual).abs() * 0.15;

    // New-bin candidate handling: empty bin should only win when existing fits are bad
    if bin_residual == bin_capacity {
        let badness = if fitting_bins_count == 0 { 0.0 } else {
            (mean_residual - item_size as f64).max(0.0)
        };
        // base cost of opening a new bin, reduced late in stream or when no fit exists
        let mut newbin = 120.0 - badness * 0.6 - progress * 30.0;
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 - item_size.min(bin_capacity) {
            newbin -= 10.0; // next item is large, fresh bin useful
        }
        if fitting_bins_count == 0 { newbin -= 90.0; }
        score += newbin;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Treat tiny unusable gaps (< 10) as fully dead: they are worthless space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward placements that still leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Leaving a gap that cannot fit the next item: penalize proportionally.
        score += (next_item_size as f64 - post_residual as f64) * 0.35;
    }

    // Dead-space pressure grows as the stream progresses (conservation matters more later).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (post_residual as f64) * 0.25 * progress;

    // Open-bin pressure: when many bins are open, prefer filling existing ones;
    // a new-bin candidate (residual == capacity) gets a penalty scaled by bin count.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.5 * (open_bins_count as f64);
    } else {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Slight bonus for bins tighter than average (better utilization so far).
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // 2-step lookahead: if the next item exactly fills the leftover space,
        // strongly favor this bin (chained perfect fit).
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size > 0 && post_residual > next_item_size {
            // Next item fits too: mild reward proportional to how tight the chain is.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 12.0 * tightness;
        } else if next_item_size > 0 && post_residual < next_item_size {
            // Dead space the next item cannot use: penalize unless residual is tiny.
            let dead = post_residual as f64;
            let waste = (next_item_size - post_residual) as f64;
            score += 0.4 * waste - 0.15 * dead;
        }
    }

    // Prefer bins whose residual is already below average (consolidate small spaces).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: make it unattractive unless few bins are open
    // or residuals across bins are badly fragmented.
    if bin_residual == bin_capacity {
        score += 40.0;
        if open_bins_count <= 2 {
            score -= 20.0;
        }
        if mean_residual > 0.5 * bin_capacity as f64 && next_item_size > 0 {
            score += 10.0;
        }
    }

    // Late in the stream, tighten packing (avoid opening bins near the end).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress > 0.8 {
        score += 30.0 * (progress - 0.8);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scaled by how well item fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize leaving small dead space (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: only attractive when item fits poorly everywhere
    // or lookahead suggests a large item needs fresh space.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit_penalty = 30.0 * (1.0 - fit_ratio);
        score += poor_fit_penalty;
        // Lookahead: if next item is large and this new bin would stay roomy, favor it.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0 + 0.2 * next_item_size as f64 * (1.0 - progress);
        }
        // Fewer open bins relative to progress -> opening is cheaper early.
        score -= 5.0 * (1.0 - progress);
    }

    // Prefer bins with residuals below the mean (consolidate waste).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Prefer larger open bins when many bins are open (reduce fragmentation).
    score -= 0.05 * open_bins_count as f64 * fit_ratio;

    // Lookahead synergy: bonus if post residual accommodates next item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1)
    let progress = if total_items > 0 {
        (step_index as f64 / total_items as f64).clamp(0.0, 1.0)
    } else {
        0.0
    };

    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap; // normalized post residual

    // Smooth polynomial coupling: post-residual shaped by progress
    // Early stream: prefer tight fits (low post_residual); late stream: tolerate slack
    let progress_weight = 0.5 + 0.5 * progress;
    score += progress_weight * (norm_pr * norm_pr) * cap * 0.6;

    // Smooth interaction: post_residual vs next item size
    let nis = next_item_size as f64;
    if nis > 0.0 {
        let norm_nis = nis / cap;
        // Reward when next item fits into post_residual (smooth quadratic gain)
        let fit_gap = norm_nis - norm_pr;
        if fit_gap <= 0.0 {
            // next item fits: reward proportional to how well it fills leftover
            let fill = norm_nis / norm_pr.max(1e-6);
            score -= 8.0 * fill * (1.0 - fill) * 4.0;
        } else {
            // next item doesn't fit: penalize wasted space smoothly
            score += 6.0 * fit_gap * fit_gap * cap;
        }
    }

    // Penalty when this is the last fitting bin — strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 2 {
        // many alternatives: mild penalty to keep flexibility
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(3.0);
    }

    // Coupling with mean residual: prefer bins whose residual deviates below mean
    // (i.e., nearly full bins), smoothly via squared deviation
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Slight preference for consolidating into fewer bins when many are open
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 4.0 * open_norm * norm_pr;

    // New-bin candidate: smooth penalty scaled by how much slack a fresh bin wastes
    if bin_residual == bin_capacity {
        // Opening a new bin: base penalty that grows with progress (late = consolidate)
        score += 10.0 + 20.0 * progress;
        // But if item is large relative to capacity, new bin is fine
        score -= 8.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), but weight by item size
    // so that packing large items tightly matters more than small ones.
    score += 0.55 * (item_size as f64 / bin_capacity as f64) * (post_residual as f64);

    // Harmonic class of post_residual: dead space is worse when it cannot
    // plausibly host a future item. Classify residual into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.8 {
        // Almost-empty bin: excellent, keep it roomy.
        score -= 30.0;
    } else if frac > 0.5 {
        // Half-full: still very usable.
        score -= 8.0;
    } else if frac > 0.3 {
        // Awkward zone: penalize moderately.
        score += 10.0;
    } else if frac > 0.1 {
        // Small slot: only good if next item fits it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        } else {
            score += 18.0;
        }
    } else if post_residual > 0 {
        // Near-dead space: heavy penalty unless exactly consumed next.
        if next_item_size == post_residual {
            score -= 40.0; // perfect lookahead fill
        } else {
            score += 35.0;
        }
    }

    // Lookahead coupling: reward bins whose post_residual accommodates the
    // next item with little slack left over.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover: penalize proportionally.
        score += 0.25 * (next_item_size as f64);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless post_residual is huge waste).
    if fitting_bins_count == 1 {
        score -= 25.0;
        if post_residual > bin_capacity / 2 {
            score += 20.0; // but avoid burning a fresh large bin wastefully
        }
    }

    // New-bin candidate detection (bin_residual == bin_capacity): make it
    // attractive only when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // New bin keeps full residual = capacity - item_size as post_residual.
        // Slight penalty so a genuinely tight existing fit wins.
        score += 5.0;
        // But if no existing bin fits well (many bins, high mean residual
        // spread), opening fresh is fine.
        if mean_residual < (bin_capacity as f64) * 0.25 {
            score -= 10.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    }

    // Mild pressure against accumulating many open bins with scattered space.
    if !is_new_bin && open_bins_count > 4 {
        score += 0.15 * (open_bins_count as f64);
    }

    // Small noise-free tie-breaker: prefer bins whose residual is close to
    // the mean (keeps residuals homogeneous, easier future packing).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the minimum item (1..=9 generic,
    // but scale with typical item size) are wasted forever.
    if post_residual > 0 && post_residual <= 12 {
        score += 40.0 + 3.0 * (13.0 - post_residual as f64);
    }

    // Perfect or near-perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward leaving room for the lookahead item if it fits exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // blocks the known next item
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln() * (2.0 + 3.0 * progress);

    // New-bin candidate: prefer it only when this bin would leave big dead space
    // or residuals across bins are already large (nothing tight available).
    if bin_residual == bin_capacity {
        let dead_here = (post_residual > 0 && post_residual <= 12) as f64;
        if dead_here > 0.0 {
            score += 30.0; // new bin also creates dead space? then it's neutral-ish
        } else {
            score -= 10.0;
        }
        if mean_residual < item_size as f64 * 1.5 {
            score -= 12.0; // existing bins are tight; opening fresh is fine
        }
    }

    // Mild bonus for bins tighter than the average residual.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
