pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Reward bins whose residual is fully consumed (perfect fill).
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: penalize leaving a residual too small for the next item
    // (creates dead space), but reward residuals that fit the next item well.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Dead space for the lookahead item; scale by how close it is to useless.
            let deadness = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 30.0 * deadness;
        } else {
            // Residual still usable by next item: reward proportionally.
            let usability = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 * (1.0 - usability);
        }
    } else {
        // Last item: strongly prefer zero-waste completions.
        score -= 50.0 * (1.0 - waste_frac);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if post_residual <= 10 {
            score -= 15.0; // near-perfect squeeze
        }
    }

    // New-bin candidate handling: empty bin starts at post_residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is fine when all existing fits are poor:
        // compare against mean residual fragmentation of open bins.
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        // Penalize opening a new bin when open bins are spacious and usable.
        score += 10.0 + 25.0 * fragmentation;
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    } else {
        // Mild global pressure: many open bins with low mean residual -> consolidate.
        let pressure = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64) * (1.0 - (open_bins_count as f64).recip())
        } else { 0.0 };
        score -= 12.0 * pressure;
    }

    // Small coupling: prefer placing large items into bins with large residuals.
    let size_frac = item_size as f64 / bin_capacity as f64;
    let resid_frac = bin_residual as f64 / bin_capacity as f64;
    score -= 8.0 * size_frac * resid_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: polynomial terms in normalized post_residual scaled by progress
    let quad = norm_pr * norm_pr;
    let cubic = quad * norm_pr;

    // Early stream: tolerate small residuals less; late stream: penalize dead space more
    score -= (1.0 - progress) * 12.0 * cubic;
    score += progress * 8.0 * quad;

    // Reward tight fits smoothly (small post_residual relative to capacity)
    score -= 6.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it, scaled smoothly by progress
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (1.0 - progress);
    }

    // Penalize divergence from mean residual smoothly
    score += 0.05 * (pr - mean_residual).abs();

    // Mild penalty for many open bins to discourage bin proliferation
    score += 0.1 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small integers
    // classify dead space into "reusable" vs "wasted" buckets.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space severity: tiny residuals are nearly worthless.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else if post_residual <= 5 {
        score -= 25.0; // near-perfect, residual hard to reuse but small waste
    } else if post_residual < 10 {
        score += 10.0; // small but unusable for typical items -> dead space
    }

    // Modulo-classes on post_residual: residuals that are multiples of
    // common small sizes (10, 20, 25, 50) are more likely reusable.
    let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0);
    if reusable && post_residual > 0 {
        score -= 12.0;
    }
    // Odd/harsh residues are dead space.
    if post_residual % 2 == 1 && post_residual > 5 {
        score += 6.0;
    }

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // How snugly the next item would fit: prefer exact/near-exact.
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 45.0;
            } else if gap <= 5 {
                score -= 30.0;
            } else {
                score -= 15.0 * (1.0 - gap / cap);
            }
        } else {
            // Next item cannot use this residual: residual likely wasted.
            score += 8.0 + 0.05 * post;
        }
    } else {
        // Last item: only waste matters.
        score += 0.5 * post;
    }

    // Fraction-of-capacity classes: residual below half capacity is
    // increasingly hard to fill.
    if post < 0.25 * cap {
        score += 18.0;
    } else if post < 0.5 * cap {
        score += 6.0;
    } else if post >= 0.5 * cap {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
        // But penalize if it creates a bad residue class.
        if post_residual > 0 && post_residual < 10 {
            score += 10.0;
        }
    }

    // New empty bin candidate: prefer it only when few bins are open or
    // stream is early, or when it enables clean packing classes.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = open_bins_count as f64;
        score -= 5.0 + 10.0 * (1.0 - progress) - 0.4 * open_pressure;
        // If many bins are open, discourage proliferation.
        if open_bins_count > 8 {
            score += 0.8 * (open_bins_count as f64 - 8.0);
        }
    }

    // Coupling with mean residual: placing into a bin far below mean
    // residual balances the bin pool.
    let dev = mean_residual - post;
    score += 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Penalize gaps too small to fit the lookahead item if it wouldn't fit anyway.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 * 0.9 {
        score += 12.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + progress * 10.0 - mean_residual * 0.05;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild preference for tighter bins overall.
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: big reward; smooth decay otherwise.
        score -= 60.0 * (-diff / 12.0).exp();
        // Extra bonus for exact 2-step completion (bin closed after next item).
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize post_residual that is too small for next item (dead space risk)
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: strongly prefer tightest fit
        score -= 50.0;
    }

    // Relative residual context: prefer bins with residuals near mean (balanced packing)
    let rel = (post_residual as f64 - mean_residual).abs();
    score += 0.10 * rel;

    // Last-chance bin: reward strongly to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so it only wins when open bins are bad fits,
    // but allow it when post_residual of this fresh bin is large and useful.
    if bin_residual == bin_capacity {
        score += 25.0;
        // If next item exactly fits a fresh bin residual after this placement, soften penalty
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Prefer filling fuller bins early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * tightness * tightness;

    // Penalize leaving awkward dead space that few future items (>=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0 * (20.0 - post_residual as f64) / 10.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            let nfit = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * nfit;
        } else {
            // next item won't fit here; slightly prefer leaving flexible space
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: base penalty so it's only chosen when open bins fit poorly.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 25.0
            - 8.0 * (mean_residual / bin_capacity as f64)
            + 5.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper; late, avoid it.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If item is large, a fresh bin is attractive.
        score -= (item_size as f64 / 100.0) * 15.0;
    }

    // Mild preference to spread load when many bins are open.
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with non-linear penalty on wasted space
    let mut score = pr + 18.0 * pr_norm * pr_norm * cap;

    // Perfect fit reward (smooth bump near zero residual)
    score -= 25.0 * (-pr / 8.0).exp();

    // Tight-fit coupling with stream progress: early on, tolerate slack; late, punish it
    score += 15.0 * t * pr_norm * (1.0 - pr_norm);

    // Last-chance bin: strong reward if this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * t;
    }

    // Many open bins: mild penalty to avoid fragmentation, scaled by mean residual gap
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap);

    // Lookahead: reward if the next item can use the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - t * 0.5);
        } else {
            score += 6.0 * ((nxt - pr) / cap);
        }
    } else {
        // Last item: strongly prefer filling an existing bin
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless residuals are all tight
    if bin_residual == bin_capacity {
        let avg_tightness = 1.0 - (mean_residual / cap);
        score += 20.0 * avg_tightness + 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    if is_new_bin {
        // Opening a new bin: only attractive if no (or exactly one) existing bin fits,
        // i.e. this is effectively a forced open.
        if fitting_bins_count <= 1 {
            score -= 1000.0;
        } else {
            // penalize spreading items across many bins when alternatives exist
            score += 60.0 + 5.0 * fitting_bins_count as f64 + 2.0 * open_bins_count as f64;
            // lookahead: if the next item is large, having fresh capacity is less bad
            if next_item_size as f64 > 0.6 * bin_capacity as f64 {
                score -= 30.0;
            }
        }
        return score;
    }

    let r = post_residual;
    let harmonic_class = r % 10;

    // Perfect fill: ideal outcome, strong reward.
    if r == 0 {
        score -= 200.0;
    }
    // Dead space: residual too small for any plausible future item.
    else if r < 10 {
        score += 80.0;
    } else {
        // Harmonic classes: residuals that are multiples of 10 are reusable
        // by a wider range of item sizes -> reward them.
        if harmonic_class == 0 {
            score -= 15.0;
        }
        // Last-chance bin: if this is the only open bin that fits, use it
        // rather than opening a new bin.
        if fitting_bins_count == 1 {
            score -= 120.0;
        }
    }

    // Prefer bins where the item fills a large fraction of the current residual.
    score -= (bin_residual - item_size) as f64 * 0.1;

    // Lookahead: if post_residual can no longer hold the next item, mild penalty
    // for creating a stranded state.
    if next_item_size > 0 && r > 0 && r < next_item_size {
        score += 10.0;
    }

    // Late in the stream, consolidation matters more: reward tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity as f64 - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item are pure waste — penalize them super-linearly.
    let dead_threshold = 10.0f64;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Zero residual is a perfect fit — strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small usable residuals (1..=10) are near-dead: mild extra penalty
    // unless the post residual exactly matches the lookahead item.
    if post_residual >= 1 && post_residual <= 9 {
        if (post_residual as u32) == next_item_size {
            score -= 15.0; // lookahead exactly fills the gap
        } else {
            score += 6.0;
        }
    }

    // If the lookahead item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next == 0 {
            score -= 20.0; // two-item perfect chain
        } else if (after_next as f64) < dead_threshold {
            score += 8.0; // chain leaves dead space
        } else {
            score -= 5.0; // chain keeps bin usable
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins over opening new ones.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more heavily as open bins grow,
        // unless this bin would otherwise be a bad fit (high post residual
        // penalty already applies via base score).
        score += 10.0 + pressure * 2.5;
        // Exception: if no other bin fits well, opening fresh is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Existing bin: reward using it, scaled by how "full" the fleet is.
        score -= pressure.min(10.0) * 0.8;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mean-residual coupling: if fleet mean residual is high, bins are
    // loose — penalize leaving yet another loose residual; if tight,
    // reward tight packing.
    let dev = (post_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Slight progression term: late in the stream, tighten packing further.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward a residual that exactly fits the next item.
    let next = next_item_size as f64;
    if next > 0.0 {
        let diff = (post_residual as f64 - next).abs();
        score -= 300.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Exact 2-step match: chain placement, extremely desirable.
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Penalize residuals too small for the next item (dead space risk),
        // scaled by how close post_residual is to being useless.
        if (post_residual as u32) < next_item_size {
            score += 50.0 + 2.0 * (next - post_residual as f64);
        }
    }

    // Relative-to-mean coupling: bins with residuals near the mean are "normal";
    // leaving a post_residual far below mean wastes capacity relative to fleet.
    let cap = bin_capacity as f64;
    let mean_frac = (mean_residual / cap).clamp(0.0, 1.0);
    let post_frac = post_residual as f64 / cap;
    score += 40.0 * (mean_frac - post_frac).abs();

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 {
        score -= 250.0;
    }

    // Penalize tiny unusable residuals (fragmentation), non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Mild pressure toward consolidating into fewer bins early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for very tight fits (best-fit core).
    let tightness = (bin_residual as f64 - item_size as f64).max(0.0) / bin_capacity as f64;
    score -= 8.0 * (1.0 - tightness) * (1.0 - tightness);

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
        // Extra reward if next item then fits snugly too.
        let next_tight = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 3.0 * (1.0 - next_tight);
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that the next item cannot use is penalized,
        // more so when it is small-but-unusable.
        let waste = post_residual.min(next_item_size - 1) as f64;
        score += 0.5 * waste;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when
    // existing residuals are large (poor fits everywhere) or few bins fit.
    if bin_residual == bin_capacity {
        let avg_pressure = mean_residual / bin_capacity as f64;
        // Penalize opening new bins when open bins are already tight.
        score += 12.0 * (1.0 - avg_pressure);
        if fitting_bins_count == 0 {
            score -= 10.0; // no alternative anyway
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 5.0 * progress;
        // Many open bins: discourage adding more.
        score += 0.15 * open_bins_count as f64;
    }

    // Mild global pressure: when mean residual across bins is low,
    // squeezing into existing bins is valuable.
    score += 0.05 * (mean_residual - post_residual as f64);

    // Progress-aware tightness bonus: as stream advances, favor tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 2.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling: post_residual weighted by stream progress
    let coupling = norm_pr * norm_pr * (0.5 + progress) + norm_pr * progress * progress;
    score += 40.0 * coupling;

    // Penalize wasted space relative to mean residual across open bins
    let waste = (pr as f64 - mean_residual) / cap;
    score += 15.0 * waste * waste.abs();

    // Reward tight fits with a smooth saturating term
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness * tightness;

    // Lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_gap = (post_residual - next_item_size) as f64 / cap;
        score -= 20.0 * (1.0 - fit_gap) * (1.0 - fit_gap);
    } else if next_item_size > post_residual {
        score += 10.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin pressure
    if fitting_bins_count == 1 {
        score -= 18.0 * (1.0 - progress);
    }

    // Mild penalty for scattering across many bins late in the stream
    score += 0.5 * open_bins_count as f64 * progress * progress;

    // New-bin candidate: penalize slightly unless residuals elsewhere are tight
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - progress) - 6.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead-space severity via modulo classes.
    // Class 0: residual is "harmonically clean" (divides nicely into common small sizes)
    let clean = |r: u32| -> f64 {
        if r == 0 { return 0.0; }
        // residuals that are multiples of 10 or 25 are reusable
        if r % 10 == 0 { 0.0 } else if r % 25 == 0 { 2.0 } else { 6.0 }
    };
    score -= 4.0 * clean(post_residual);

    // Penalize small unusable residuals (dead space) non-linearly
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 2.5;
    }

    // Reward tight fits strongly
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, big reward (harmonic chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else {
            // penalize leaving a residual that wastes most of the space for the known next item
            let waste = post_residual as f64 - (bin_capacity as f64 - next_item_size as f64).max(0.0);
            if waste > 0.0 { score += waste * 0.15; }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open fits are poor
    if bin_residual == bin_capacity {
        // base penalty so new bins are used only when justified
        score += 25.0;
        // if many open bins exist with slack, opening new bin is wasteful
        score += mean_residual * 0.3 + open_bins_count as f64 * 1.0;
        // late in stream, opening bins is more acceptable
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
    }

    // Slight preference for bins whose residual is close to mean (balance load)
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 3.0;

    // Fractional capacity preference: bins with residual in "large-item friendly" zones
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.2 {
        score += 8.0 * (0.2 - frac) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        score -= 30.0; // perfect fit is ideal
    }

    // Reward filling bins tightly relative to capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Open-bin pressure: discourage spreading across many bins.
    if open_bins_count > 0 {
        score += (open_bins_count as f64).ln() * 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
        score += 8.0; // dead space that blocks the known next item
    }

    // New empty bin candidate: penalize opening a new bin unless residuals are badly fragmented.
    if bin_residual == bin_capacity {
        score += 18.0;
        if mean_residual > 0.0 && mean_residual < item_size as f64 {
            score -= 20.0; // existing bins can't help; opening is justified
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative at all
        }
    }

    score
}

