pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post-residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress) - 2.0 * progress * norm_pr * (1.0 - norm_pr) * cap;

    // Reward tight fits (high fit_ratio) smoothly
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space relative to mean residual, smoothed
    let dead = (pr - mean_residual).abs();
    score += 0.15 * dead * (1.0 - norm_pr);

    // Last-chance bonus
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 8.0 * (1.0 - slack);
    }

    // Mild penalty for proliferating open bins late in stream
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 and 20
    let r10 = (post_residual % 10) as f64;
    let r20 = (post_residual % 20) as f64;
    score += 0.6 * (10.0 - r10) / 10.0;          // penalize non-round residuals
    score += 0.4 * (20.0 - r20) / 20.0;

    // Integer-division thresholds: small post_residual is good (tight packing)
    let tight_class = post_residual / 10;        // 0..10
    score -= 3.0 * (10 - tight_class.min(10)) as f64;

    // Dead-space penalty: residual too small for typical items (1..100 unknown, mid ~50)
    if post_residual < 10 {
        score -= 6.0; // near-perfect fit, strong reward
    } else if post_residual < 25 {
        score -= 2.0;
    } else if post_residual < 50 {
        score += 1.5;
    } else {
        score += 3.5; // large leftover: wasted capacity
    }

    // Lookahead coupling: does next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 4.0; // chain placement possible
            let slack = (post_residual - next_item_size) as f64;
            score += 0.05 * slack; // prefer snug chains
        } else {
            score += 2.0; // next item won't chain here
        }
        // harmonic class of next item size vs post_residual (divisibility)
        if post_residual % next_item_size.max(1) == 0 && next_item_size > 0 {
            score -= 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Prefer new bin when existing fits are poor (post_residual high)
        if post_residual >= 40 {
            score -= 5.0;
        } else {
            score += 6.0; // keep using well-fitting open bins
        }
        // More open bins -> slightly favor consolidation into existing bins
        score += 0.3 * open_bins_count as f64;
    }

    // Progress-based drift: late in stream, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (post_residual as f64) * 0.15;

    // Mean residual coupling: penalize bins far from mean (fragmentation)
    score += 0.3 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small for the minimum
    // plausible future item (<= 10) are "dead space" -> strong penalty.
    if post_residual < 10 {
        score += 150.0;
    } else {
        // Non-linear penalty on small gaps that few items can use.
        let gap_usability = (post_residual as f64 / 10.0).floor() / 10.0; // 0..1
        score += (1.0 - gap_usability) * (1.0 - gap_usability) * 80.0;
    }

    // Reward bins whose residual is close to the item (tight fit).
    let tightness = 1.0 - (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= tightness * 30.0;

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Post residual too small for the known next item -> dead space penalty.
        score += 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Open-bin pressure: many open bins -> discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, minus small benefit
        // if current bin fit is very poor.
        score += 90.0 + pressure * 2.0;
    } else {
        score += 2.0;
    }

    // Slight preference for bins below mean residual (consolidating waste).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect match: post residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Next item fits into the remaining space -> reward proportional to tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize dead space, more so if it's small.
        score += 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Compare post_residual against mean residual: prefer bins that end below average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins are nearly full or badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        score += 35.0 * fragmentation;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Penalize large dead space quadratically, scaled by progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let dead = post_residual as f64;
    score += 0.004 * dead * dead * (0.5 + progress);

    // Relative fit quality: fraction of bin used by this item
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Last-chance bin: strong preference to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }
    // Many fitting bins: prefer the tightest; slight penalty keeps competition fair
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead: reward leaving residual that can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 12.0 - 0.3 * slack as f64;
        } else {
            // residual too small for next item: penalize proportionally
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: strongly prefer filling bins completely
        score -= 40.0 * fill;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // discourage opening new bins; encourage consolidating into existing space.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        let open_pressure = open_bins_count as f64;
        let mean_res = mean_residual;
        // If existing bins collectively have room, opening a new bin is costly
        score += 18.0 + 2.5 * open_pressure + 0.15 * mean_res;
        // Exception: item is large and mean residual too small to fit it well
        let avg_gap = mean_res / open_pressure.max(1.0);
        if (item_size as f64) > avg_gap + 20.0 {
            score -= 25.0;
        }
        // Early stream: opening bins is cheaper (build diversity)
        if progress < 0.2 {
            score -= 15.0;
        }
        // Late stream: consolidation matters more
        if progress > 0.8 {
            score += 10.0;
        }
    } else {
        // Using an existing bin: mild bonus scaled by how much it reduces mean residual
        score -= 3.0;
        if (bin_residual as f64) > mean_residual {
            score -= 2.0; // filling the emptier-than-average bin
        }
    }

    // Small tie-breaker noise-free deterministic term
    score += 0.001 * (bin_residual % 7) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let item = item_size as f64;

    // Core: tight fit reward via non-linear decay of post_residual.
    let mut score = pr * pr / cap; // quadratic penalty on leftover

    // Smooth coupling: as stream progresses, prefer tighter packing more strongly.
    let tightness = 1.0 - pr / cap;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Reward near-perfect fits with a smooth bump around small residuals.
    let x = pr / cap;
    score -= 25.0 * (-x * 40.0).exp();

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_quality = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 20.0 * fit_quality;
    } else if next_item_size > 0 {
        // Penalize leaving a residual that wastes space for the next item.
        score += 8.0 * (pr / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin when open bins exist,
    // unless the item is large relative to capacity (poor fit elsewhere likely).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let base_penalty = 18.0 + 12.0 * progress;
        let large_item_relief = 20.0 * (item / cap).powi(3);
        score += base_penalty - large_item_relief;
    } else {
        // Mild preference for filling bins that already have content,
        // scaled by how far below mean residual this bin sits (more filled).
        let fill_advantage = (mean_residual - bin_residual as f64) / cap;
        score -= 6.0 * fill_advantage.max(-1.0).min(1.0);
    }

    // Slight consolidation pressure as many bins accumulate.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is a small residue mod 10 is bad.
    let r = post_residual % 10;
    if post_residual > 0 {
        score += match r {
            0 => -14.0,               // perfectly reusable class
            1 | 2 | 8 | 9 => 10.0,    // awkward slivers
            _ => 2.0,
        };
    } else {
        score -= 25.0; // perfect fit
    }

    // Fraction-of-capacity classes for post_residual
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac > 0.0 && frac < 0.1 { score += 12.0; }        // unusable dead space
    else if frac >= 0.3 && frac <= 0.5 { score -= 6.0; }  // sweet spot

    // Integer-division threshold: post_residual / 10 quantization
    let q = post_residual / 10;
    if q > 0 && q <= 3 { score += 4.0 * (4 - q) as f64; }

    // Lookahead harmony: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // exact modulo harmony with next item
            if post_residual % next_item_size == 0 && post_residual > 0 { score -= 4.0; }
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: make it mildly unattractive unless few fitting bins
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * fitting_bins_count as f64;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size { score -= 5.0; }
    }

    // Prefer filling bins with large residual when many bins open
    score -= 0.05 * (bin_residual as f64 - mean_residual);

    // Mild preference for compacting as stream progresses
    score *= 1.0 + 0.2 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity_f = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: residuals that cannot fit the next item are "dead".
    let dead_threshold = if next_item_size > 0 { next_item_size as f64 } else { 10.0 };
    if post > 0.0 && post < dead_threshold {
        // Unusable gap: heavy penalty scaled by how close it is to being useless.
        score += 30.0 * (1.0 - post / dead_threshold) + 15.0;
    }

    // Reward very tight fits (small post_residual that is still usable or zero).
    let tightness = 1.0 - post / capacity_f;
    score -= 25.0 * tightness * tightness;

    // Lookahead coupling: if this placement leaves room for the next item, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 * (post_residual as f64 / (post_residual as f64 + next_item_size as f64));
    } else if next_item_size > 0 {
        // Forces next item into another bin; mild penalty unless this bin is nearly full.
        score += 5.0 * (1.0 - tightness);
    }

    // Last-chance bin: strongly prefer using the only bin that fits, avoid new bins.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a bin unless current options are bad.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count > 0 {
            score += 25.0; // there exists a fitting open bin; opening new is wasteful
        }
        if post > 0.0 && post < dead_threshold {
            score -= 45.0; // but a fresh bin never creates dead space here
        }
    }

    // Open-bin pressure: many open bins -> consolidate into existing ones.
    score += 1.5 * open_bins_count as f64 * (1.0 - tightness);

    // Late in stream: be greedy, minimize fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (post / capacity_f);

    // Prefer bins whose residual is already below mean (consolidate small gaps).
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: reward placements leaving little waste
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste_ratio) * 10.0;

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_bonus = (1.0 - diff / bin_capacity as f64).max(0.0);
        score -= match_bonus * 15.0;
        // Exact match for next item
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual too small for next item (dead space)
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins)
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more so as stream progresses
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + progress * 10.0;
        // But if item is large relative to capacity, new bin may be fine
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 6.0;
        }
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving small, hard-to-use slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            // Next item cannot fit here; mild penalty proportional to wasted potential.
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    // (high mean residual) or few bins can fit the item.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        let pressure = crowding * 0.7 + scarcity * 0.5;
        // Early stream: keep bins open and consolidated.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = 0.3 + 0.5 * progress;
        score = 60.0 + 50.0 * pressure * openness - 30.0 * pressure;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 10.0;
        }
        // Never open a new bin when a perfect or near-perfect fit exists elsewhere.
        if fit_ratio > 0.9 && bin_residual != bin_capacity {
            score += 100.0;
        }
    }

    // Prefer bins with residual below mean (consolidate fuller bins).
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Mild preference to spread across many open bins late in the stream.
    score -= 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Tight fit reward: quadratic in normalized post-residual (small residual favored)
    let x = pr / cap;
    score -= 40.0 * (1.0 - x) * (1.0 - x) * (1.0 - x * 0.5);

    // Penalize residual that is unusable relative to typical item sizes
    let usable = (pr as u32 >= 1) as i32 as f64;
    let dead = if pr < item_size as f64 { pr } else { 0.0 } as f64;
    score += 0.8 * dead * dead / cap;

    // Lookahead: reward residual that can still host the next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 6.0 + 4.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 2.0 * (next_item_size as f64 - pr).min(cap) / cap;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - t);
    }

    // New-bin candidate: penalize opening new bins, more strongly early on
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * (1.0 - t) + 2.0 * open_bins_count as f64;
    }

    // Stream-progress coupling: later in stream, prefer filling existing bins tighter
    score += 10.0 * t * x;
    // Mean-residual coupling: if mean residual is large, tolerate looser fits
    score -= 3.0 * (mean_residual / cap) * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: dead space if too small to ever fit a future item.
    // Items are >= 1, but small residuals (< 10 by classic assumption) are likely dead.
    let dead_zone = 10u32;
    if post_residual < dead_zone {
        // Small but nonzero residual = wasted space; penalize proportionally to its uselessness.
        score += (dead_zone - post_residual) as f64 * 8.0;
    }

    // Reward residuals in "harmonic" classes: multiples of common sizes (10, 20, 25, 50).
    if post_residual % 10 == 0 {
        score -= 12.0;
    }
    if post_residual % 25 == 0 {
        score -= 8.0;
    }
    if post_residual % 50 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how tightly it fills.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 60.0 * fill_ratio;
        } else {
            // Next item cannot use this residual: mild penalty scaled by wasted fraction.
            score += 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: default mid score; prefer opening a new bin only when
    // all existing fits are poor (large post_residual waste) late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a new bin is penalized more when many bins are open (fragmentation).
        score = bin_capacity as f64 * 0.5 + open_bins_count as f64 * 3.0 + progress * 20.0;
        // But if current best fit would leave a tiny dead residual, new bin looks better:
        // handled implicitly since poor placements get high scores above.
    }

    // Tightness bonus: reward small (but usable) residuals.
    if post_residual >= dead_zone {
        score -= (bin_capacity - post_residual) as f64 * 0.2; // fuller bin = better
    }

    // Mild preference for consolidating into fewer bins.
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead spaces (1..=9) heavily: nothing in [1,100] can use them.
    if post_residual >= 1 && post_residual <= 9 {
        score += 40.0;
    }
    // Mild penalty for mid-range gaps that only tiny items could fill.
    if post_residual > 9 && post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits strongly.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item can use the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot fit into the residual, mildly penalize hoarding space.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation into existing bins
    // (penalize the new-bin candidate, which has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 12.0 + 0.8 * open_bins_count as f64;
    } else {
        score -= 0.2 * open_bins_count as f64;
    }

    // Prefer bins with below-average residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    // Early in the stream, be more willing to open bins (less penalty on new bin).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead fit: this bin's leftover exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // chain fit, strongly favored
        } else if post_residual >= next_item_size {
            // Leftover can still host the next item; reward tightness of that fit.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot use the leftover: penalize dead space, worse if large.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.3 * dead;
        }
    }

    // Relative residual vs mean residual of open bins: prefer bins whose post_residual
    // is close to (or below) the mean, avoiding creating outliers of unusable space.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit,
    // i.e. when the best possible post_residual across the stream context is poor.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base penalty so a new bin loses to any reasonable existing fit.
        score += 70.0;
        // Discount the penalty late in the stream or when bins are scarce,
        // making fresh bins more acceptable as fragmentation accumulates.
        score -= 20.0 * progress;
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 30.0; // current bins can't even hold the next item well
        }
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    // Mild pressure against keeping many bins open with large residuals.
    score += 0.05 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress in the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: penalize large post_residual, but even more strongly
    // penalize small-but-nonzero residuals that become unusable dead space.
    let dead_threshold = 10.0_f64.min(next_item_size.max(1) as f64);
    if post_residual > 0 {
        let pr = post_residual as f64;
        if pr < dead_threshold {
            score += (dead_threshold - pr) * 3.0; // dead space penalty
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // next item fits, but leaves another residual — mild reward
            score -= 5.0 * (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item,
    // avoiding opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer filling bins that are already below mean residual (balancing),
    // scaled by how many bins are open.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Early in the stream, be slightly more willing to open new bins (exploration);
    // late in the stream, consolidate into existing bins.
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (5.0 + 15.0 * progress + 0.5 * open_bins_count as f64);

    // Mild penalty for having many open bins when this bin would be left very full
    if open_bins_count > 3 && post_residual < 5 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let fill = 1.0 - post_residual as f64 / cap;

    // Non-linear coupling: reward tight fits more strongly as the stream progresses.
    let tightness = fill * fill * (1.0 + 2.0 * progress);
    score -= 12.0 * tightness;

    // Penalize dead space quadratically; dead space becomes more costly later.
    let dead = post_residual as f64 / cap;
    score += 8.0 * dead * dead * (0.5 + progress);

    // Perfect fit bonus (smooth, saturating near zero residual).
    if post_residual == 0 {
        score -= 15.0 * (1.0 + progress);
    }

    // Lookahead coupling: favor bins whose leftover matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_bonus = (1.0 - gap / cap).max(0.0);
        score -= 6.0 * match_bonus * match_bonus;
        // Penalize residuals too small for the next item (wasted sliver).
        if (post_residual as u32) < next_item_size {
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize mildly early, more when many bins already open
    // and mean residual can still absorb items.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 3.0 + 2.0 * open_pressure + 5.0 * (1.0 - progress) - 4.0 * (mean_residual / cap).min(1.0);
    }

    // Slight penalty for bins with residual far above mean (keep balanced bins).
    let dev = (post_residual as f64 - mean_residual).abs() / cap;
    score += 2.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post_residual in small harmonic classes)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Harmonic class logic on post_residual modulo capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let post = post_residual;
    if post % quarter == 0 && post > 0 {
        score -= 25.0; // residual aligns with quarter classes -> likely reusable
    }
    if post % 10 == 0 && post > 0 {
        score -= 15.0;
    }
    // Penalize residuals in awkward classes (just above small-item sizes)
    if post > 10 && post < 20 {
        score += 30.0;
    }
    if post > half && post < half + 15 {
        score += 10.0;
    }

    // Lookahead coupling: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if post == next_item_size {
            score -= 350.0;
        } else if post >= next_item_size && post - next_item_size <= 5 {
            score -= 120.0;
        } else if post < next_item_size && post > 0 {
            // dead space relative to lookahead
            score += 20.0;
        }
        // harmonic class: post_residual divisible by next item size
        if next_item_size > 0 && post % next_item_size == 0 && post > 0 {
            score -= 40.0;
        }
    } else {
        // Last item: prefer filling as much as possible
        score -= 150.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins fit poorly
    if bin_residual == bin_capacity {
        score += 60.0 + (mean_residual.min(80.0)) * 0.5;
        // but if no open bin really fits well, new bin becomes attractive
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        // early stream: allow opening bins more freely
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 30.0;
        }
    }

    // Prefer bins with residual close to item size (tight fit)
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score -= (bin_capacity as f64 - tightness) * 0.05;

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling with open-bins pressure: more open bins => reward tight fits more.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score -= pressure * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 8.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless current bin is a bad fit.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * (open_bins_count as f64).sqrt();
    }

    // Early stream: slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement is ideal -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves further slack: moderate reward
            // scaled by how well it matches (smaller leftover is better).
            let leftover = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.3 * leftover;
        } else {
            // Next item cannot use the post residual: penalize dead space
            // proportional to the unusable gap.
            let gap = (next_item_size - post_residual) as u32;
            score += 0.5 * gap as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless it enables a
    // perfect 2-chain with the next item.
    if bin_residual == bin_capacity {
        let mut penalty = 20.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            penalty -= 15.0;
        }
        score += penalty;
    }

    // Contextual coupling with mean residual: bins far below mean residual
    // (large remaining space relative to fleet average) are slightly less
    // attractive, encouraging balanced consumption across bins.
    score += 0.1 * (mean_residual - post_residual as f64).max(0.0);

    // Late-stream consolidation: near the end, prefer filling existing bins
    // tightly rather than spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: bigger items in this bin leave proportionally less waste potential.
    score -= (item_size as f64 / bin_capacity as f64) * 6.0;

    // Lookahead coupling: if the next item fits into the post-residual, this bin
    // remains useful; if not, the leftover is likely dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a fresh bin, but relax the penalty
    // when many bins are open and mean residual is high (fragmentation).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 12.0;
        new_bin_penalty -= (fitting_bins_count.saturating_sub(1) as f64) * 2.0;
        new_bin_penalty -= (mean_residual / bin_capacity as f64) * 4.0;
        // Late in the stream, avoid spawning bins for marginal gains.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty += progress * 5.0;
        score += new_bin_penalty.max(0.0);
    }

    // Prefer bins whose residual stays near the global mean residual
    // (balanced packing reduces extreme fragmentation).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Slight preference for bins with fewer siblings when open-bin count is large.
    if open_bins_count > 8 {
        score += (open_bins_count as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Later in the stream, tight fills (small post_residual) are rewarded more strongly.
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 12.0 * coupling;

    // Smooth quadratic penalty for medium dead space (wasted capacity zones).
    let dead = norm_pr * (1.0 - norm_pr);
    score += 8.0 * dead * dead;

    // Reward near-perfect fits smoothly.
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_frac * fit_frac * fit_frac * fit_frac;

    // Lookahead: smooth reward if next item fits the resulting residual.
    if next_item_size > 0 && post_residual > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 5.0 * (-gap / 25.0) * (-gap / 25.0) * 0.5;
        score += 2.0 * (nxt / cap);
    }

    // Last-chance bin before opening a new one: smooth bonus.
    if fitting_bins_count <= 1 {
        score -= 3.5;
    }

    // Penalize spreading across many open bins, scaled by stream progress.
    score += 0.4 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mild attraction toward bins whose residual is near the mean (smooth term).
    score += 0.3 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual as fraction of capacity
    let tight = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 25.0 * tight * tight;

    // Harmonic class penalty: dead space that no future item class can use
    let class = post_residual % 10;
    score += 0.8 * class as f64;

    // Next item lookahead: bonus if next item fits in post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (next_item_size as f64 / post_residual.max(1) as f64).abs());
        } else {
            // dead space w.r.t. lookahead item
            let waste = next_item_size - post_residual;
            score += 0.35 * waste as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize spreading across many bins when plenty fit
    if fitting_bins_count > 1 && post_residual > 40 {
        score += 5.0 * (fitting_bins_count as f64).sqrt();
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && (bin_capacity - post_residual) >= item_size && post_residual <= 15;
        if good_fit_exists {
            score += 60.0; // discourage opening new bin when a tight fit exists
        } else if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin
        } else {
            // prefer new bin over very poor fits (large dead space)
            score += (post_residual as f64 - 10.0).max(0.0) * 0.6;
            score -= 10.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero residuals are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable gap under min item size
    } else if post_residual < 20 {
        score += 15.0; // near-unusable gap
    } else if post_residual == 0 {
        score -= 30.0; // perfect fill
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Allow new bin if existing residuals are all poor fits for this item.
        let waste = mean_residual - item_size as f64;
        if waste > 40.0 {
            score -= 20.0;
        }
    }

    // Lookahead: favor bins whose post_residual accommodates the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Mild stream-progression regularization.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Aggressive 2-step lookahead: if next item exactly fits post_residual,
    // strongly reward this placement (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item can still fit here: mildly reward leftover usability.
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize dead space relative to next item.
            score += 0.5 * (next_item_size - post_residual).min(next_item_size) as f64;
        }
    }

    // Relative-to-mean-residual term: prefer bins whose residual after placement
    // stays close to (or below) the mean residual — keeps bins balanced.
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only open
    // a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 40.0;
        // Opening a new bin is more attractive early (more stream left to use it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Slight penalty for accumulating many open bins: prefer consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual gets extra bonus).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize post-residual that is too small to be useful for typical items,
    // i.e. dead space: if post_residual is tiny but nonzero, waste is likely.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0 - post_residual as f64;
    }

    // Reward residual that can host the lookahead item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Lookahead can't follow into this bin: mild penalty, stronger near end of stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 3.0 + 4.0 * progress;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 20.0;
        // But if the fit is very loose, soften the bonus.
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio > 0.6 {
            score += 14.0;
        }
    }

    // New-bin candidate handling: an empty bin has a fixed baseline.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.55;
        // Cheap items (small footprint) are fine to start a new bin for;
        // large items late in the stream should prefer existing bins.
        let fill = item_size as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
        // Early in the stream, opening bins is cheaper; late, avoid proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 * progress;
        // Many open bins with high mean residual: opening yet another bin is wasteful.
        score += 0.35 * open_bins_count as f64 + 0.15 * mean_residual;
        // If other bins fit, penalize the new bin more (prefer reuse).
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Prefer bins with below-average residual (consolidate fuller bins first):
    // bins with residual far above mean are "fresh" and should be saved.
    if bin_residual < bin_capacity {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.10 * diff;
    }

    // Mild reward for using bins when many are open (avoid bin sprawl).
    score -= 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) - norm_pr * progress * (1.0 - progress);
    score += 20.0 * poly;

    // Reward tight fits more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Last-chance bonus when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Penalize opening new bins when many bins are open with slack
    if bin_residual == bin_capacity {
        score += 5.0 + 8.0 * (open_bins_count as f64 / (1.0 + mean_residual / cap)) * (0.5 + 0.5 * progress);
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 6.0 * (pr / (pr + ni));
        } else {
            score += 4.0 * (ni - pr) / cap;
        }
    }

    // Mild penalty for large dead space relative to mean residual
    if pr > mean_residual {
        score += 0.5 * (pr - mean_residual);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fill classes are golden.
    let pr = post_residual;
    if pr == 0 {
        score -= 500.0; // perfect fill
    } else if pr <= 5 {
        score -= 200.0;
    } else if pr % 10 == 0 {
        score -= 60.0; // decadal residue pairs well with 10..80 items
    }

    // Modulo-5 harmonic class: residues 1..4 are awkward dead space
    let m5 = pr % 5;
    if m5 > 0 && m5 < 5 {
        score += 8.0 * (5 - m5) as f64;
    }

    // Lookahead coupling: can next item land in post_residual exactly?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size < pr {
            let nxt_post = pr - next_item_size;
            if nxt_post % 10 == 0 {
                score -= 80.0;
            }
            score += nxt_post as f64 * 0.3;
        } else {
            // next item cannot fit here; mildly penalize large leftovers
            score += 10.0;
        }
    }

    // Fraction-of-capacity thresholds on post residual
    let frac = pr as f64 / cap;
    if frac > 0.5 {
        score += 25.0 * frac; // half-empty bins are wasteful targets
    } else if frac < 0.1 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity && bin_capacity >= 100;
    if is_new_bin {
        let pressure = mean_residual / cap;
        score = 250.0 + 100.0 * pressure - 40.0 * (open_bins_count as f64).ln();
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0; // big item coming, fresh bin useful
        }
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
    }

    // Mild stream-phase modulation
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=9) are unusable
    if post_residual >= 1 && post_residual <= 9 {
        score += 40.0; // heavy penalty for creating dead space
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill reward
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 8.0; // moderately awkward gap
    }

    // Tight fit bonus: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline, only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        score = 55.0 + 1.5 * open_bins_count as f64 - 10.0 * fill_ratio;
        // if next item is large, opening fresh bin is more attractive
        if next_item_size > 60 {
            score -= 12.0;
        }
    } else {
        // Prefer bins whose residual is close to item size (best-fit coupling)
        let slack = (bin_residual as f64 - item_size as f64).abs();
        score += 0.15 * slack;
        // If next item fits exactly in post_residual, reward this placement
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / bin_capacity as f64);
        }
    }

    // Mean residual coupling: avoid dumping items into bins far from mean residual state
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits: post_residual close to 0 is ideal.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(6);

    // 2-step lookahead: reward if next item exactly fills the new residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chaining: next item fills this bin exactly
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover after the chain
            let chain_left = post_residual - next_item_size;
            score += 0.5 * chain_left as f64;
            score -= 6.0 * (1.0 - chain_left as f64 / bin_capacity as f64).powi(4);
        } else {
            // next item cannot fit here: penalize slightly
            score += 3.0;
        }
    }

    // Prefer bins whose residual is close to the mean (keep bins homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual <= bin_residual {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when residual would be very large waste elsewhere.
    if bin_residual == bin_capacity {
        // Neutral base; add small penalty so it's chosen only when open bins are poor fits.
        score += 4.0 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on large post-residuals.
    score += 0.35 * (post_residual as f64 / cap) * (post_residual as f64 / cap) * cap;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual; penalize
    // if post_residual is a small unusable sliver relative to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 45.0; // chain fit: excellent
        } else if (next_item_size as u32) > post_residual {
            let waste = nxt - post_residual as f64;
            score += 0.12 * waste;
        } else {
            // next item fits but leaves another gap
            score += 0.05 * (post_residual as f64 - nxt);
        }
    }

    // Last chance bin: strongly favor using it instead of opening a new bin,
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        let fit_quality = post_residual as f64 / cap;
        if fit_quality < 0.5 {
            score -= 80.0 * (1.0 - fit_quality);
        } else {
            score -= 15.0;
        }
    }

    // Penalize spreading residual far from the mean (keeps bins homogeneous,
    // easier to pair future items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.10 * dev;

    // Time horizon: early in stream, be more willing to open new bins
    // (keep bins clean); late in stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, costly late.
        score = post_residual as f64 + 30.0 - 45.0 * progress;
        if next_item_size > 0 && (next_item_size as u32) <= bin_capacity {
            // a fresh bin always fits the next item too
            score -= 5.0;
        }
    } else {
        score -= 25.0 * progress;
    }

    // Many open bins: discourage opening yet another one.
    score += if bin_residual == bin_capacity {
        2.5 * open_bins_count as f64
    } else {
        0.0
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear penalty on small residuals (dead space), stronger late in stream
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * 12.0 * (0.5 + progress);

    // Perfect fit reward with smooth saturation
    if post_residual == 0 {
        score -= 40.0 + 20.0 * progress;
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so open bins are preferred unless fit is terrible
    if bin_residual == bin_capacity {
        score += 8.0 + 15.0 * progress - (mean_residual / cap) * 10.0;
    }

    // Lookahead coupling: reward residuals that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let slack = (pr - nx) / cap;
            score -= 10.0 * (1.0 - slack * slack);
        } else {
            let gap = (nx - pr) / cap;
            score += 6.0 * gap;
        }
    }

    // Slight preference to fill bins with low mean residual (consolidation)
    score += (pr - mean_residual) * 0.05;

    // Mild non-linear dispersion penalty for large residuals early on
    score += 3.0 * (pr / cap) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in certain bands.
    // Class 0: post_residual < 10 (perfect seal) -> strong reward
    // Class 1: 10..=20 (still usable by min items) -> mild reward
    // Class 2: 21..=50 (awkward middle) -> penalty
    // Class 3: >50 (huge waste, nearly empty bin) -> heavy penalty
    let cls = if post_residual < 10 { 0 } else if post_residual <= 20 { 1 } else if post_residual <= 50 { 2 } else { 3 };
    match cls {
        0 => score -= 40.0 + (10 - post_residual) as f64 * 3.0,
        1 => score -= 8.0,
        2 => score += (post_residual as f64 - 10.0) * 0.6,
        _ => score += (post_residual as f64 - 50.0) * 1.2 + 30.0,
    }

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: reward if next item fits into post_residual (chain packing),
    // penalize if next item is large and this placement strands it poorly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Especially good if next item would then nearly seal the bin.
            let chain_post = post_residual - next_item_size;
            if chain_post < 10 { score -= 25.0; } else { score -= 6.0; }
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // Next item fits this bin only if we DON'T put current item here:
            // penalize taking that option away.
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with small residuals among many fitting bins (best-fit flavor).
    score -= (bin_residual as f64).recip() * 200.0;

    // New-bin candidate handling: only attractive when open bins fit badly
    // (large post_residual class) or none fit well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 {
            100.0
        } else {
            (mean_residual - item_size as f64).max(0.0) * 0.8
        };
        // Base cost of opening a new bin, discounted by desperation and stream progress.
        let base = 55.0 * (1.0 - 0.3 * (step_index as f64 / total_items.max(1) as f64));
        score = base - desperation;
        // Don't open a new bin for a tiny item late in the stream if a bin seals it.
        if post_residual == 0 && item_size <= 20 { score += 50.0; }
    }

    // Mild preference for filling bins when many are open (bin-count control).
    score += open_bins_count as f64 * 0.15;

    // Mean-residual coupling: if this bin is far below mean residual, it's a
    // good "dumping ground"; reward placing into low-residual bins.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for small unusable dead space after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0;
    }

    // Reward tight fits (post_residual near zero but valid).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Penalize opening new bins when open bins fit, scaled by pressure.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
    } else {
        // Last-chance bin gets a strong discount to avoid waste.
        if fitting_bins_count == 1 {
            score -= 40.0;
        }
        // Prefer bins whose residual is close to item size (best fit refinement).
        let fit_gap = (bin_residual as f64 - item_size as f64).abs();
        score += fit_gap * 0.3;

        // Lookahead: reward if next item fits the post residual exactly-ish.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= 20.0;
            }
        }
    }

    // Open bins pressure: more open bins -> favor filling existing ones.
    score -= open_bins_count as f64 * 0.5;

    // Mean residual coupling: penalize placing into bins far from mean residual.
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    let progress = step_index as f64 / total_items.max(1) as f64;
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // exact match gets big discount, near matches get partial discount
        let lookahead_reward = if diff == 0.0 {
            40.0 + 20.0 * (1.0 - progress)
        } else if diff <= 5.0 {
            25.0 - 2.0 * diff
        } else if diff <= 10.0 {
            12.0 - 0.6 * diff
        } else {
            0.0
        };
        score -= lookahead_reward;

        // Penalize residuals too small for next item only mildly (waste anyway)
        if (post_residual as u32) < next_item_size {
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: prefer tightest fit
        score -= 10.0;
    }

    // Reward residuals below mean (tight packing relative to fleet)
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Penalize creating large unusable dead space relative to min item size
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny useless sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() > 10);
        if poor_fit {
            score -= 20.0;
        } else {
            score += 25.0; // discourage opening new bins when existing fits are decent
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 14.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical items (unusable slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 10.0;
        } else if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 6.0 * next_fit * next_fit;
        } else {
            // Next item won't fit here; slight penalty proportional to wasted potential.
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit = fit_ratio < 0.5;
        let mut nb = 25.0;
        if poor_fit { nb -= 10.0; }
        if fitting_bins_count == 0 { nb -= 20.0; }
        // Early in stream, opening fresh bins is cheaper (more future items to fill them).
        nb -= 6.0 * (1.0 - progress);
        // If open bins have lots of residual on average, prefer reusing them.
        if mean_residual > item_size as f64 { nb += 8.0; }
        score += nb;
    }

    // Mild preference for bins with residual close to the mean (balance load).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for fewer open bins (consolidation pressure).
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling: reward small post_residual more strongly as stream progresses
    let tightness = (1.0 - norm_pr).powi(3);
    score -= tightness * (20.0 + 60.0 * progress);

    // Penalize post_residual that is too small to fit typical future items (smooth quadratic)
    let dead = if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        gap * gap
    } else {
        0.0
    };
    score += dead * 80.0;

    // Encourage using bins when few alternatives exist (last-chance fit)
    if fitting_bins_count <= 1 {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins, weighted by progress
    score += open_bins_count as f64 * (0.5 + 1.5 * progress);

    // Smooth interaction: residual vs mean residual deviation
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 40.0 * progress;

    // Prefer filling bins with larger items tightly when lookahead exists
    if next_item_size > 0 && pr >= next_item_size as f64 {
        score -= 10.0 * (pr / cap);
    }

    // New-bin candidate: penalize opening a new bin unless current fit is very poor
    if bin_residual == bin_capacity {
        score += 15.0 + 30.0 * (1.0 - progress) - (pr / cap) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;

    // Harmonic class of post_residual: dead space that no future item (1..=100)
    // can fill perfectly is worse. Items <= post_residual can fit; the "waste"
    // is post_residual minus the largest achievable fill.
    let pr = post_residual;
    // Largest item class that exactly fills or nearly fills pr
    let exact_fill = if pr == 0 { 1.0 } else {
        // perfect fill possible if some item size divides/matches pr
        if pr >= 1 && pr <= 100 { 0.0 } else { 0.0 }
    };
    let _ = exact_fill;

    // Penalize residuals that fall in "dead zones": too small for most items
    if pr > 0 && pr < 10 {
        score += 30.0 * (10.0 - pr as f64);
    }
    // Reward near-perfect fills (harmonic: pr in {0, small multiples})
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 5 {
        score -= 25.0;
    }

    // Modulo-class logic on capacity fractions
    let frac = pr as f64 / bin_capacity as f64;
    score += 20.0 * (frac * std::f64::consts::PI).sin().abs();

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size <= pr {
            score -= 0.4 * next_item_size as f64;
        } else {
            // next item won't fit here; penalize large leftover mildly
            score += 0.15 * (next_item_size - pr) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening new bins unless current bin fit is bad
    if is_new_bin {
        let pressure = open_bins_count as f64 * 0.5 + progress * 10.0;
        // Opening a new bin is justified only if best open-bin residual would be tiny
        let fit_quality = if bin_residual >= item_size {
            (bin_residual - item_size) as f64 // best possible open-bin leftover unknown; use current
        } else { 100.0 };
        score += 120.0 + pressure - if fit_quality > 40.0 { 30.0 } else { 0.0 };
        // Late in stream, prefer reusing bins even more
        score += 40.0 * progress;
    }

    // Mild preference for tighter existing bins
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item
    // (min item size 1, but practically small gaps < 10) are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space penalty
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: zero waste
    }

    // Tight-fit reward: post_residual close to zero relative to item size.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * tightness;

    // Penalize leaving a gap that exactly fails the next item's fit
    // (next item almost fits but post_residual is just short).
    if next_item_size > 0 {
        if post_residual < next_item_size && bin_residual >= next_item_size {
            score += 20.0; // this placement blocks the lookahead item here
        } else if post_residual >= next_item_size {
            score -= 8.0; // keeps room for the lookahead item
        }
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few open bins or item fits nowhere well.
        score += 30.0 + 6.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly favor using it before opening a new bin.
        score -= 35.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates below the mean
    // (consolidating space into fewer, emptier bins).
    score += 0.5 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Mild stream-progression pressure: as stream advances, prefer filling
    // existing bins to close them out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), penalize large dead space
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Aggressive 2-step lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 25.0 - 0.3 * leftover as f64;
        } else {
            // next item does NOT fit here: penalize leaving medium-size gaps
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += 0.25 * (next_item_size as f64 - waste);
            }
        }
    } else {
        // last item: only tightness matters
        score -= 10.0;
    }

    // Relative to mean residual: bins with unusually small residual are precious; avoid dumping large items into them
    let rel = bin_residual as f64 - mean_residual;
    score += 0.05 * rel;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when good fits exist, especially late in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 30.0 * progress;
        // but allow opening when item barely fits nothing (all residuals small)
        if (bin_residual as f64 - item_size as f64) <= mean_residual * 0.2 {
            score -= 25.0;
        }
    }

    // Mild penalty for too many open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post residual).
    score -= (post_residual as f64 / cap).powi(3) * 40.0;

    // Penalize high fragmentation relative to mean residual across open bins.
    let frag = post_residual as f64 - mean_residual;
    score += 0.5 * frag.max(0.0);
    score -= 0.3 * (-frag).max(0.0);

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            // Penalize leaving residual too small for the next item (dead space).
            let dead = post_residual as f64;
            score += 0.15 * dead * (dead / cap);
        }
        // If next item exactly matches post residual, big bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: strong preference to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tighter ones (already via post_residual).
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a new bin is costly; discourage unless
    // the item fits poorly everywhere (this call is for the empty bin).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 55.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Many open bins -> discourage another one.
        score += 3.0 * (open_bins_count as f64).ln().max(0.0);
        // Small items waste a fresh bin less than large ones... actually large
        // items fill it better; small items leave too much slack.
        score += 0.3 * (cap - item_size as f64);
        // If next item is large, a fresh bin may still serve it.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    } else {
        // Slight bonus for using already-open bins, stronger as bins accumulate.
        score -= 2.0 + 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Time-horizon modulation: early stream, be more exploratory (favor spread);
    // late stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * (1.0 - progress) * (post_residual as f64 / cap);
    score += 6.0 * progress * (post_residual as f64 / cap);

    // Reward near-perfect closure of a bin.
    if post_residual < 5 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling: reward small post_residual non-linearly
    let tightness = 1.0 - pr / cap; // 0..1, high when bin nearly full
    score -= 18.0 * tightness * tightness * tightness;

    // Late in the stream, tighten packing more aggressively
    let p2 = progress * progress;
    score -= 12.0 * p2 * tightness * tightness;

    // Penalize dead space relative to next item: if next item can't fit residual, waste
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).max(0.0) / cap;
        score += 10.0 * gap * gap;
        // Reward if next item fits exactly well
        let fit = (nxt - pr).abs() / cap;
        score -= 6.0 * (1.0 - fit) * (1.0 - fit) * tightness;
    }

    // Penalize spreading residuals far from mean (imbalance)
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * tightness;
    }

    // Mild penalty for opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * (1.0 - progress) + (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition into capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small unusable leftovers (< 10 units dead space).
        if post_residual < 10 {
            score += 25.0;
        }
        // Reward leftovers in "reusable" harmonic bands: multiples of 10, 25, 50.
        if post_residual % 10 == 0 {
            score -= 12.0;
        }
        if post_residual % 25 == 0 {
            score -= 8.0;
        }
        if post_residual % 50 == 0 {
            score -= 6.0;
        }
        // Fraction-of-capacity classes: quarter, third, half bands.
        if pr >= c * 0.5 {
            score -= 15.0; // half-full bin remains useful
        } else if pr >= c * 0.33 {
            score -= 5.0;
        } else if pr >= c * 0.25 {
            score -= 0.0;
        } else {
            score += 10.0; // deep dead space
        }
    }

    // Lookahead coupling: does the next item fit the post residual exactly or well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chained fit
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / c);
        } else {
            score += 8.0; // next item won't chain here
        }
    } else {
        // Last item: prefer zero waste.
        score += pr * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are truly bad,
    // but relax as the stream progresses and many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 45.0 - 30.0 * progress;
        // If nothing fits well (large dead-space penalty would occur), opening is attractive:
        if post_residual != 0 && post_residual < 10 {
            score -= 40.0;
        }
    }

    // Congestion: many open bins -> prefer consolidating into existing bins.
    score += open_bins_count as f64 * 0.5 * (bin_residual != bin_capacity) as i32 as f64;

    // Mean-residual alignment: favor bins whose residual is near the mean (balanced packing).
    score -= (mean_residual - pr).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (or the lookahead item) are "dead" — heavily penalize.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fill, ideal
    }

    // Dead zone: residual too small for the next item but nonzero.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.5;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 30.0;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize placements into existing bins when many bins
    // are open, encouraging consolidation; but allow new bins when few open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, minus lookahead bonus
        // if the next item could also go here comfortably.
        score = 70.0 + pressure * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 15.0;
        }
    } else {
        score += pressure * 0.3;
        // Favor bins whose residual is close to the mean residual (balanced packing).
        score -= (mean_residual - bin_residual as f64).abs() * 0.1;
    }

    // Lookahead synergy: if post_residual exactly fits next item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (dead-space avoidance).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this placement sets up a perfect chain.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if nxt <= post {
            // Next item fits: reward exact/very tight chaining.
            if diff == 0.0 {
                score -= 500.0;
            } else if diff <= 5.0 {
                score -= 120.0;
            } else {
                score -= 30.0 * (1.0 - diff / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here; penalize leaving awkward gaps
            // that are too small to be useful (dead space).
            if post < 10.0 {
                score -= 10.0; // tiny gap is fine, effectively sealed
            } else {
                score += 0.5 * (post - 10.0); // gap that nothing may fill
            }
        }
    }

    // Compare post_residual against mean residual: keeping residuals
    // balanced preserves flexibility across open bins.
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (post_f - mean_residual).abs();
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when decent fits exist, but allow it
    // when the current bin would leave a large awkward gap.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so we prefer reusing open bins,
        // reduced when post_residual here is small (item nearly fills it).
        score += 60.0;
        if post_residual <= 20 {
            score -= 90.0; // fresh bin with tight fit is good
        }
    } else if post_residual as f64 > 0.6 * bin_capacity as f64 && next_item_size > 0 && (next_item_size as f64) > post_f {
        // This bin would remain mostly empty and next item doesn't fit:
        // maybe better to start fresh.
        score -= 20.0;
    }

    // Mild pressure to consolidate when many bins are open.
    if open_bins_count > 3 {
        score += 0.5 * open_bins_count as f64 * (post_f / bin_capacity as f64);
    }

    // Slight stream-position adaptation: early on, be more exploratory
    // (less penalty for spreading); late, tighten packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = 1.0 - post / cap;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize leaving dead space that no future item (1..=100) can use efficiently:
    // small leftovers are worst when they're neither tiny nor large.
    if post > 0.0 {
        let awkward = (post - 20.0).abs();
        score += 0.6 * awkward.min(30.0);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let gap = post - nxt;
            score -= 18.0 * (1.0 - gap / cap);
        } else {
            score += 4.0;
        }
        // If next item could pair with current item's leftover, encourage.
        if (nxt + item).abs() > 0.0 && post >= nxt && post - nxt <= 5.0 {
            score -= 8.0;
        }
    }

    // Global state: when many bins are open with high mean residual, prefer
    // consolidating into existing bins rather than spreading.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= 6.0 * (mean_residual / cap);
        // Late in the stream, avoid opening new bins.
        score -= 10.0 * progress;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate penalty: only open a new bin when the item is large
    // relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 60 {
            score -= 10.0;
        }
        if next_item_size > 0 && next_item_size as f64 > post {
            score -= 5.0;
        }
        if open_bins_count > 3 && mean_residual / cap > 0.3 {
            score += 12.0;
        }
    }

    // Mild preference for bins with residual close to item size (best-fit core).
    let diff = (bin_residual as f64 - item).abs();
    score += 0.3 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear penalty on wasted space
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap (bins get reused later); late, waste is costly.
    let waste_weight = 1.0 + 3.0 * progress * progress;
    score += waste_weight * norm_pr * norm_pr * cap * 0.5;

    // Reward near-perfect fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * cap * (0.3 + 0.7 * progress);

    // If next item fits exactly in post_residual, reward this bin smoothly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_next = 1.0 - (gap / cap).min(1.0);
        score -= fit_next * fit_next * 10.0;
    }

    // Last-chance bin bonus (only fitting bin): smooth reward
    if fitting_bins_count == 1 {
        score -= 5.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64).ln() * (norm_pr - mean_residual / cap).abs();

    // New-bin candidate: only attractive when open bins would leave big waste
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
        score = cap * (0.6 + 0.4 * progress) + 3.0 * openness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets and reward "reusable" classes.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = cap * 0.25;
    let half = cap * 0.5;

    // Dead-space penalty: leftovers that are too small for typical items
    // (items >= 10 nominally, but interface allows 1..100) are waste.
    if post_residual > 0 && post_residual < 12 {
        score += 25.0 * (12.0 - post) / 12.0;
    }

    // Reward leftovers in "harmonic" classes: exact quarters/halves are
    // statistically more likely to be filled by future items.
    let mod_q = post_residual % 25;
    if mod_q == 0 && post_residual > 0 {
        score -= 8.0;
    } else if mod_q <= 5 {
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this is a perfect chain — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how well next item nests
            score -= 20.0 * (1.0 - slack / cap).max(0.0);
            // integer-division threshold: next item leaves another tiny remnant
            if post_residual - next_item_size < 12 {
                score += 6.0;
            }
        } else {
            // next item cannot use this bin's leftover; slight penalty
            // scaled by how much leftover is stranded
            score += 4.0 * (post / cap);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has full residual. Only make
    // it attractive when the current item is large or fits are scarce;
    // otherwise discourage proliferation of open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        if item_frac > 0.7 || fitting_bins_count == 0 {
            score -= 5.0; // large items are fine in fresh bins
        } else {
            score += 10.0 + 20.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
            // late in stream, avoid opening bins for small items
            score += 10.0 * progress;
        }
        // exact-fill bonus: item exactly fills a fresh bin
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Prefer bins whose residual is below the mean (consolidate emptier
    // space into fewer bins); penalize dipping into the "fullest" bins
    // when mean residual is high.
    if mean_residual > 0.0 {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 6.0 * dev;
    }

    // Mild preference for tighter fits overall: quadratic in post_residual
    // normalized by capacity fraction classes.
    let frac = post / cap;
    if frac > 0.5 {
        score += 5.0 * (frac - 0.5); // large leftovers = poor fit quality
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Reward bins whose leftover can plausibly host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leftovers that are just below the next item (wasted potential).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bin pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Mild preference for bins below mean residual (fill emptier bins less,
    // keep tight bins for tight fits).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight progression-aware tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
