pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    let exact = post_residual == 0;
    let last_chance = fitting_bins_count == 1 && !is_new_bin;

    // Reward perfect fits heavily
    if exact {
        score -= 1000.0;
    }

    // Penalize creating dead space that no plausible item can use
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0 + 0.5 * next_item_size as f64;
        } else {
            // penalty scaled by how much the next item overshoots
            let over = (next_item_size - post_residual) as f64;
            score += 0.3 * over;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if last_chance {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening new bins when decent fits exist
    if is_new_bin {
        let pressure = open_bins_count as f64;
        score += 60.0 + 5.0 * pressure;
        // late in stream, prefer closing out open bins
        score += 40.0 * progress;
        // if many bins fit the item, opening a new bin is wasteful
        if fitting_bins_count > 1 {
            score += 30.0 * (fitting_bins_count as f64 - 1.0);
        }
        // if item nearly fills a new bin, opening is fine
        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 90.0;
        }
    } else {
        // Prefer bins whose residual is close to the item (tight fit)
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += 20.0 * tightness;
        // Favor bins below mean residual (using up emptier bins consolidates)
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

    // Mild preference for bins with small residual overall
    score += 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Base waste penalty: quadratic in normalized post-residual
    let pr_norm = pr / cap;
    score += 6.0 * pr_norm * pr_norm * cap;

    // Perfect-fit reward (smooth, non-piecewise)
    score -= 8.0 * (-pr_norm * 12.0).exp();

    // Lookahead coupling: penalize if next item cannot use the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = nxt - pr;
        if gap > 0.0 {
            let g = gap / cap;
            score += (2.0 + 4.0 * progress) * g * cap * (1.0 + g);
        } else {
            // Reward residual that exactly accommodates the next item
            score -= 3.0 * (-(-gap / cap) * 10.0).exp();
        }
    }

    // Smooth interaction: waste hurts more as stream progresses (less time to recover)
    score *= 1.0 + 0.6 * progress * pr_norm;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    } else if fitting_bins_count > 1 {
        // Mild dispersion penalty: prefer bins when alternatives exist
        score += 1.5 * (fitting_bins_count.min(8) as f64 - 1.0);
    }

    // New-bin candidate: attractive when open bins fit poorly relative to mean residual
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = (bin_capacity as f64 - item_size as f64) / cap;
        score -= 4.0 * fit_quality * fit_quality;
        // Deter opening new bins when a good fit exists elsewhere
        let mean_fit = if mean_residual > item_size as f64 { 1.0 } else { 0.0 };
        score += 6.0 * mean_fit * (1.0 - fit_quality);
        score += 0.5 * open_bins_count as f64;
    } else {
        // Prefer filling bins below the mean residual (tighter bins first)
        score += 0.8 * (mean_residual - pr) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction bands.
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= quarter {
        score -= 300.0;
    } else if post_residual <= third {
        score -= 150.0;
    } else if post_residual <= half {
        score -= 50.0;
    } else {
        // Large leftover: penalize, it's likely dead space unless a big next item fits.
        score += 40.0;
    }

    // Modulo arithmetic on post_residual: leftovers that are multiples of common
    // item sizes (10..=20 range granularity) are reusable; reward them.
    let reusable = (post_residual % 10 == 0 && post_residual >= 10)
        || (post_residual % 20 == 0 && post_residual >= 20);
    if reusable {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly or well into post_residual,
    // this placement chains nicely.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            if gap <= quarter {
                score -= 120.0;
            } else if gap > half {
                score += 30.0;
            }
        } else {
            // Next item won't fit here; leftover becomes harder to use.
            score += 25.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate (empty bin): penalize opening a new bin when open bins exist,
    // unless it enables a perfect split of capacity by the item (harmonic class).
    if bin_residual == bin_capacity {
        let base_penalty = 250.0 + open_bins_count as f64 * 30.0;
        // Opening a bin is fine if item is a harmonic divisor of capacity (perfect fill).
        if bin_capacity % item_size == 0 && item_size >= third {
            score = base_penalty - 350.0;
        } else {
            score = base_penalty;
        }
    }

    // Mild stream-progression pressure: later in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (quarter as f64);

    // Slight preference toward bins with below-mean residual (consolidate fuller bins).
    score += (post_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving room for the lookahead item if it fits exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Lookahead cannot use the leftover: mild penalty scaled by tightness.
        score += 6.0 * (next_item_size as f64 / (post_residual as f64 + 1.0)).min(3.0);
    }

    // Open-bin pressure: discourage opening new bins when plenty are open.
    if bin_residual == bin_capacity {
        score += 18.0 + 2.5 * open_bins_count as f64;
        // If only this candidate fits, opening a new bin is better than spilling.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it.
        score -= 30.0;
    }

    // Prefer bins with residuals close to the item (tight packing).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 10.0 * tightness;

    // Mild mean-residual coupling: favor bins below mean residual (already tight).
    score += 0.3 * (mean_residual - post_residual as f64);

    // Slight time pressure: later in stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are good: reward small post_residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit: post_residual == 0 -> strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly matches the post
    // residual, this is a perfect chain placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // Next item fits here: reward proportionally to how well it fills.
            let fill_after = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - fill_after / (bin_capacity as f64));
        } else {
            // Next item cannot use the post residual: penalize wasted space
            // relative to the next item's demand.
            let waste = (post_residual as f64) / (next_item_size as f64);
            score += 10.0 * waste.min(3.0);
        }
    }

    // Compare post_residual against mean residual across open bins.
    // Leaving a residual far below the mean creates a hard-to-use bin.
    let mean_ref = if mean_residual.is_finite() && mean_residual > 0.0 {
        mean_residual
    } else {
        bin_capacity as f64
    };
    let rel = (post_residual as f64) / mean_ref;
    if rel < 0.35 {
        score += 18.0 * (0.35 - rel); // dead-space penalty
    } else if rel > 1.0 {
        score -= 6.0 * (rel - 1.0).min(1.5); // keeping larger room is fine
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well,
    // unless the item is large and the fit would be terrible.
    if bin_residual == bin_capacity {
        let fit_ratio = (item_size as f64) / (bin_capacity as f64);
        if fitting_bins_count > 0 {
            score += 35.0;
            if fit_ratio > 0.7 {
                score -= 20.0; // big items justify new bins more
            }
        }
        // Early stream: allow more bins to spread load.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
