    if bin_residual == bin_capacity {
        // base cost of opening a new bin, modulated by global state
        score += 15.0;
        score -= (open_bins_count as f64).min(10.0) * 0.5;
        // early in stream, new bins are cheap; late, prefer consolidation
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * progress;
        // if mean residual across open bins is large, opening a new bin wastes potential
        score += (mean_residual / bin_capacity as f64).max(0.0) * 15.0;
    } else {
        // Favor placing into bins whose residual is close to the item (good fit)
        let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
        score -= 10.0 * fit_ratio;
        // Slight preference for bins below mean residual (balancing open bins)
        score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 5.0;
    }

    // Mild diversity pressure: many open bins -> prefer filling existing ones.
    if open_bins_count > 4 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap; // in [0,1]
    let t = progress;
    let poly = norm_pr * norm_pr * (1.0 - t) + norm_pr * t * t;
    score += 30.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 40.0 * t);

    // Penalize creating residual that fails to fit the lookahead item
    if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
        score += 8.0 + 12.0 * t;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 4.0;
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild pressure to consolidate when many bins are open
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - tightness);

    // Discourage opening a new bin unless it is genuinely needed
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - t);
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    // Small nudge toward bins with residuals near the current item size
    let diff = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * diff * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that form "fillable" classes
    // (small residuals 1..=5 are dead space; residuals that are near-multiples of common
    // item sizes are reusable). Use integer division thresholds on post_residual.
    let pr = post_residual;
    let class = pr / 10; // decade class of residual
    match class {
        0 => score += 30.0,                       // 0..9: dead space penalty (except exact 0)
        1 => score -= 5.0,                        // 10..19: still fillable by small items
        2 => score -= 10.0,                       // 20..29: good
        3 => score -= 12.0,                       // 30..39: very good
        4 => score -= 14.0,                       // 40..49: excellent
        5 => score -= 15.0,                       // 50..59: best class
        6 => score -= 13.0,                       // 60..69
        7 => score -= 10.0,                       // 70..79
        8 => score -= 6.0,                        // 80..89
        _ => score -= 2.0,                        // 90..100: nearly empty
    }

    // Exact-fill reward
    if pr == 0 {
        score -= 100.0;
    }

    // Modulo harmony: residual divisible by common sizes is reusable
    if pr > 0 {
        let mut harmony = 0.0;
        for m in [10u32, 20, 25, 50] {
            if pr % m == 0 {
                harmony += 4.0;
            }
        }
        score -= harmony;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            // softer reward scaled by how snug the fit is
            let snug = 1.0 - (pr - next_item_size) as f64 / bin_capacity as f64;
            score -= 20.0 * snug;
        } else {
            // next item cannot use this residual: penalize leaving residual in a
            // narrow band the next item overshoots
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no open bin
    // fits well. Penalize fresh bins moderately; scale with stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 + 20.0 * progress;
        // if mean residual across open bins is large, opening new bins is wasteful
        score += 0.3 * mean_residual;
    }

    // Mild penalty for proliferating open bins
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // for any future item (min item size 1..100, but small gaps < ~15 are
    // nearly dead) get a heavy nonlinear penalty.
    let pr = post_residual as f64;
    if pr > 0.0 {
        if pr < 15.0 {
            score += (15.0 - pr) * 8.0; // tiny gap => strong penalty
        } else if pr < 30.0 {
            score += (30.0 - pr) * 1.5; // moderate dead-space penalty
        } else {
            score -= 2.0; // large residual is reusable, slight reward
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 40.0;
    }

    // Reward fit tightness relative to item size (ratio-based).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize increasingly when many bins are open
        // and early in the stream; relax slightly near the end.
        score += 25.0 + pressure * 6.0 - progress * 10.0;
    } else {
        // Existing bin: reward slightly more as pressure grows.
        score -= pressure * 1.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 3.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // packing here reduces fragmentation spread.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item well.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= n {
            // Perfect match: next item exactly fills this bin afterwards
            let gap = pr - n;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            // bonus if next item fills bin completely
            if gap == 0.0 { score -= 40.0; }
        } else {
            // post residual smaller than next item: dead space unless tiny
            score += 0.5 * (n - pr);
        }
    }

    // Reward tight fits now
    score -= 8.0 * (1.0 - post_residual as f64 / bin_residual.max(1) as f64);

    // Penalize deviation from mean residual (prefer typical bins / balance)
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strong bonus to use it rather than open new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current open bins are all poor fits
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 45.0 };
        score += pressure + 10.0;
        // late in stream, opening new bins is fine
        score -= 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Slight preference for fuller bins as stream progresses
    score -= 6.0 * (1.0 - bin_residual as f64 / bin_capacity as f64) * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: dynamic time horizon
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight fit reward: penalize (subtract) when post_residual is small but nonzero
    let tight_fit = 12.0 * (-post_residual as f64 / 4.0).exp();
    score -= tight_fit;

    // Penalize large dead space (waste) super-linearly
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = (post_residual - next_item_size) as f64;
        score -= 8.0 * (-chain_fit / 6.0).exp();
    }
    // If next item cannot use post_residual, mild penalty scaled by progress
    if next_item_size > post_residual && post_residual > 0 {
        score += 3.0 + 4.0 * progress;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // Prefer bins with less residual among many candidates (best-fit bias)
        score += (bin_residual as f64) * 0.05;
    }

    // Fragmentation penalty: bin residual much larger than typical item creates waste
    let mean_res = if !mean_residual.is_finite() { bin_capacity as f64 } else { mean_residual };
    if bin_residual as f64 > mean_res + 15.0 {
        score += (bin_residual as f64 - mean_res) * 0.1;
    }

    // New-bin candidate logic: empty bin is penalized early (prefer filling open bins),
    // but allowed when item is large relative to capacity or open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_res / 10.0);
        let late_bonus = 6.0 * progress;
        let large_item = if item_size > bin_capacity / 2 { 8.0 } else { 0.0 };
        score += 25.0 - late_bonus - large_item + crowding;
    }

    // Mild reward for consolidating into bins with low residual overall
    score -= (bin_capacity as f64 - bin_residual as f64) * 0.03;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let pr_norm = post / cap;

    // Base: post-residual with non-linear polynomial shaping (favor tight fits).
    let mut score = post
        + 30.0 * pr_norm * pr_norm
        - 20.0 * pr_norm * pr_norm * pr_norm;

    // Perfect-fit reward via smooth interaction of post_residual with progress.
    let tightness = 1.0 - pr_norm;
    score -= 12.0 * tightness * tightness * (1.0 - progress);

    // Penalize dead space that can't fit the next item (smooth coupling).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let waste = (post - nxt).max(0.0) / cap;
        score += 25.0 * waste * waste * (0.5 + progress);
        // Reward leaving exactly enough room for next item.
        let gap = (post - nxt).abs() / cap;
        score -= 10.0 * (1.0 - gap) * (1.0 - gap) * gap;
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 - progress);
    }

    // Penalize opening new bins when existing bins are underutilized.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        score += 15.0 + 5.0 * (mean_residual / cap) * (mean_residual / cap) + crowding.min(10.0);
        if fitting_bins_count > 0 {
            score += 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: buckets by integer division thresholds.
    let post = post_residual as f64;
    let class = (post_residual / 10) as f64; // 0..10 harmonic class
    score += class * 2.0;

    // Strongly reward near-perfect fits (post_residual in smallest classes).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Penalize dead space that no plausible item (1..=100) can use:
    // dead space < 10 is unusable for typical min sizes; also unusable if < next_item_size.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward if the lookahead item fits exactly in the post residual (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 50.0 - slack * 0.5;
    }

    // Fraction of capacity wasted relative to item size.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 30.0;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: base penalty so we only open when existing fits are bad.
    if bin_residual == bin_capacity {
        score += 150.0;
        // But if existing bins would leave huge unusable residuals, opening is fine:
        // compare against mean residual tightness.
        score -= (mean_residual / cap) * 100.0;
        // Late in the stream, consolidation matters more; discourage new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 60.0;
        if open_bins_count == 0 {
            score -= 1000.0; // must open the first bin
        }
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    // Modulo coupling: post_residual mod 20 == 0 means clean divisible leftover.
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit — best possible
    } else {
        // Penalize "unusable" small gaps: post_residual smaller than the next item
        // (or smaller than a typical item) is likely dead space.
        let dead_threshold = if next_item_size > 0 { next_item_size } else { 10 };
        if post_residual < dead_threshold {
            score += (dead_threshold - post_residual) as f64 * 4.0;
        }
        // Reward leaving room for the lookahead item exactly.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 2.0 + (post_residual - next_item_size) as f64 * 0.05;
        }
    }

    // Reward tight fits relative to residual (small waste ratio).
    if bin_residual > 0 {
        score += (item_size as f64 / bin_residual as f64) * -10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins,
    // favor closing out nearly-full bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins pressure,
        // but relax late in the stream when residual mean is low.
        score += 30.0 + pressure * 2.0 - mean_residual * 0.3;
    } else {
        // Favor bins with below-mean residual (consolidate emptier bins' usage).
        score += (mean_residual - bin_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly favored.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness;

    // Exact fit gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward when next item fits the post residual exactly,
    // penalize when it nearly fits but not quite (dead space risk).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_tight = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 25.0 * next_tight;
        } else if post_residual > 0 && next_item_size > bin_residual {
            // next item can't fit anywhere here anyway; slight bonus for compact bin
            score -= 5.0;
        } else {
            // next item would leave this bin's remainder stranded
            score += 15.0 * (post_residual as f64) / 100.0;
        }
    }

    // Relative to mean residual: prefer bins with less residual than average
    // (fill the fullest bins first) unless it's the last-chance bin.
    if fitting_bins_count > 1 {
        score += 0.3 * (mean_residual - bin_residual as f64);
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately attractive only when current bins
    // fit poorly (large post_residual) and stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) / (bin_capacity as f64);
        score = 100.0 - 20.0 * poor_fit - 10.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score = 0.0;
        }
    }

    // Small penalty per open bin to discourage bin proliferation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize large dead space that can never be reused by typical items.
    if post_residual > 0 {
        if post_residual < 10 {
            score -= 15.0; // near-perfect fill, strongly reward
        } else if post_residual < 20 {
            score -= 5.0;
        } else {
            score += (post_residual as f64 - 20.0) * 0.6; // dead-space penalty
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Crowding pressure: when many bins are open, prefer consolidating into
    // bins below mean residual (filling emptier bins first).
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 8.0 * dev;

    // Time horizon: early in the stream be conservative with new bins,
    // late in the stream allow more flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: empty bin gets a base handicap that shrinks
    // as the stream progresses and when no good fits exist.
    if bin_residual == bin_capacity {
        let mut handicap = 20.0 - 12.0 * progress;
        // If current item leaves terrible residual in any bin, opening a new
        // bin is more attractive.
        if post_residual == 0 {
            handicap += 30.0; // perfect fit somewhere else? still prefer it
        }
        if item_size >= 60 {
            handicap -= 10.0; // big items are hard to place later; fresh bin ok
        }
        if open_bins_count > 8 {
            handicap -= 5.0 * (open_bins_count.min(20) as f64 - 8.0) * 0.2;
        }
        score += handicap.max(-15.0);
    }

    // Mild bonus for using bins that are already partially filled relative
    // to average, encouraging fewer total bins.
    if bin_residual < bin_capacity {
        score -= 3.0 + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: waste after placement, weighted by stream progress (later = more waste-averse)
    let mut score = pr * (0.8 + 1.2 * progress);

    // Non-linear penalty for awkward residuals (too small to be useful later)
    let awkward = (norm_pr * (1.0 - norm_pr)).powi(2); // low at both ends
    score += 30.0 * awkward;

    // Reward tight fits (small post_residual) with smooth coupling to progress
    score -= 20.0 * (1.0 - norm_pr).powi(3) * (1.0 + progress);

    // Lookahead: bonus if next item fits the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 5.0 * (1.0 - next_item_size as f64 / cap) * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize spreading across many open bins; encourage filling fuller bins
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);
    score -= 8.0 * (bin_residual as f64 / cap) * (1.0 - progress);

    // Compare against mean residual: prefer bins deviating favorably
    score += 0.3 * (pr - mean_residual);

    // New-bin candidate: mildly penalize so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor small post_residual, superlinearly.
    let pr = post_residual as f64;
    score += (pr * pr) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class logic: classify residual into capacity-fraction bands.
    // Residuals that are "waste classes" (small unusable slivers) are penalized.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual > 0 {
        if post_residual < 10 {
            // Dead sliver: nearly unusable for typical items -> heavy penalty.
            score += 60.0;
        } else if post_residual < quarter {
            // Small class: only fits tiny items (1..=9 are rare-ish); mild penalty.
            score += 25.0;
        } else if post_residual < half {
            // Medium class: usable for many items; slight bonus.
            score -= 5.0;
        } else {
            // Large class: plenty of room left; bonus scaled to size.
            score -= 12.0;
        }
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // Extra reward if next item then leaves a good residual too.
        let next_post = post_residual - next_item_size;
        score -= (next_post as f64) / 10.0;
        if next_post == 0 {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here: slight penalty for chaining badly.
        score += 8.0;
    }

    // Last-chance logic: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // is large relative to residuals or existing bins are poor fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 70.0;
        // Cheaper to open a new bin when many bins are already open and crowded.
        score -= (open_bins_count as f64) * 1.5;
        // If the item is large, a fresh bin is more attractive.
        score -= (item_size as f64) * 0.4;
        // If mean residual can't hold the item comfortably, new bin is fine.
        if (mean_residual < item_size as f64) {
            score -= 30.0;
        }
        // Late in the stream, prefer consolidating rather than opening bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Modulo harmonic touch: residuals congruent to typical item sizes (multiples of 5/10)
    // are more likely reusable; give a small discount.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual is "dead" if it is too small to hold even the smallest plausible item.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 40.0 + (dead_threshold - post_residual as f64) * 3.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize post_residual that cannot fit the lookahead item (wasted pair opportunity),
    // but reward when it still can.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new/partial bins.
    let bin_pressure = open_bins_count as f64 / (1.0 + total_items as f64).sqrt();
    score += bin_pressure * post_residual as f64 * 0.05;

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * 5.0;

    // Slight early-stream preference to consolidate (keep residuals large and reusable).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * post_residual as f64 * 0.03;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, mitigated when many bins are open
        // and mean residual is small (existing bins are fragmented).
        score += 12.0 - (mean_residual / bin_capacity as f64) * 6.0;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: leave exactly enough room for the next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.9;
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize residuals too small for the next item (dead space).
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // Last item: prefer tightest fit.
        score += post_residual as f64 * 0.2;
    }

    // Penalize small unusable residuals relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive if all open bins fit poorly.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 1.0 };
        // Opening a new bin is penalized when open bins have plenty of room.
        score += 20.0 * open_pressure;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= (bin_capacity - next_item_size) as f64 * 0.1;
        }
    }

    // Mild preference for fuller bins relative to the mean residual.
    score += (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: relative waste ratio penalty.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_ratio * waste_ratio;

    // Perfect or near-perfect fit gets strong reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 60.0;
        } else if gap <= 10 {
            score -= 25.0;
        } else {
            score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; slight penalty for leaving awkward small residual.
        if post_residual < 10 {
            score -= 8.0; // tiny dead space is fine, it's effectively closed
        } else if post_residual < next_item_size {
            score += 6.0; // medium dead space that blocks the next item
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 + 25.0 * progress;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Penalize bins whose residual deviates from the mean (keep residuals homogeneous
    // so future items fit predictably).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Early in the stream, opening new bins is cheap (more future items to fill them);
    // late in the stream, strongly prefer existing bins.
    let new_bin_penalty = 20.0 + 60.0 * progress;
    if bin_residual == bin_capacity {
        // New empty bin candidate: score = waste of placing item alone + penalty.
        score = (bin_capacity - item_size) as f64 + new_bin_penalty;
        // If item is large relative to capacity, a fresh bin is more attractive.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // If next item is large and nothing would hold both, fresh bin looks better.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 15.0;
        }
    }

    // Small noise-free tiebreak: prefer bins with slightly larger residual among equals.
    score -= 0.001 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: tolerate moderate residuals; late: penalize dead space quadratically.
    let progress_weight = 0.5 + 1.5 * progress;
    score += progress_weight * pr_norm * pr_norm * cap * 0.35;

    // Reward tight fits: small post_residual gets a smooth bonus (cubic decay).
    let tightness = (cap - pr) / cap; // fraction filled after placement
    score -= 6.0 * tightness * tightness * tightness;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let fill_next = nxt / cap;
            score -= 8.0 * fill_next * (1.0 - pr_norm) * (0.4 + 0.6 * progress);
        } else {
            // Next item won't fit here: penalize large residuals that strand space.
            score += 2.0 * pr_norm * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 4.0 + 3.0 * (1.0 - pr_norm);
    }

    // Many open bins: prefer consolidating into bins with below-mean residual
    // (i.e., tighter bins) to keep other bins flexible.
    let mean_norm = mean_residual / cap;
    let bin_norm = bin_residual as f64 / cap;
    score += 1.5 * (bin_norm - mean_norm) * (open_bins_count as f64).ln().max(1.0);

    // Mild penalty for opening a new bin when open bins exist and fit well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 3.0 + 4.0 * progress;
        // But allow new bin if all fitting options are very poor.
        let best_possible = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score -= 4.0 * best_possible * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual mod capacity in coarse classes.
    let pr = post_residual;
    let cap = bin_capacity as f64;
    let frac = pr as f64 / cap;

    // Dead-space penalty: residuals that are unusably small relative to the
    // minimum plausible item size. Classify via integer division thresholds.
    if pr == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    } else if pr < 10 {
        // Tiny dead space, nearly perfect: reward scaled by how close to 0.
        score -= 40.0 * (1.0 - pr as f64 / 10.0);
    } else {
        // Harmonic class buckets: residuals in [10,20) are prime real estate
        // for small items; penalize keeping them unless a fitting small item
        // is coming next.
        let class = pr / 10; // integer division: 1..=10 harmonic classes
        match class {
            1 => score += 8.0,   // 10..19: very tight leftover, risky
            2 => score += 3.0,   // 20..29
            3 => score += 1.0,   // 30..39
            4 | 5 => score -= 2.0, // 40..59: flexible mid-range, mild reward
            6 | 7 => score += 1.0, // 60..79: large leftover, mild penalty
            _ => score += 4.0,   // 80..99: nearly empty, wasteful to use
        }
    }

    // Lookahead coupling: reward if next item fits the post residual exactly
    // or closely (harmonic chaining).
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            let slack = (pr - n) as f64;
            if slack == 0.0 {
                score -= 30.0; // perfect chain
            } else if slack < 10.0 {
                score -= 20.0 * (1.0 - slack / 10.0);
            } else {
                // partial reward proportional to how much of the residual is used
                score -= 6.0 * (n as f64 / pr as f64);
            }
        } else {
            // Next item cannot fit here; penalize slightly if we leave a
            // residual in a "hard to fill" class.
            if pr >= 10 && pr < 30 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tighter fits; small bonus to keep competition
        score += 0.5 * (fitting_bins_count as f64).min(5.0);
    }

    // New-bin candidate handling: brand-new empty bin.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when the item is large (would leave
        // a big unusable residual elsewhere) or when mean residual is very low
        // (existing bins are nearly full).
        let large_item_bonus = (item_size as f64 / cap) * 30.0;
        let mean_pull = (mean_residual / cap) * 15.0;
        score = cap as f64 * 0.55 + large_item_bonus + mean_pull;
        // Never open a new bin if it's the last-chance fit or a perfect fit exists.
        if fitting_bins_count <= 1 {
            score += 100.0;
        }
        // Late in the stream, slightly discourage opening new bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Mild global pressure: many open bins -> favor filling existing ones.
    score += 0.15 * open_bins_count as f64;

    // Progress-aware dead-space weighting: early on, be pickier about residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Dead space that cannot fit the lookahead item is worse.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 * (next_item_size - post_residual) as f64 / 80.0;
    }
    // Reward tight fits (near-perfect packing).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin should only win when all open fits are bad.
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 0.5;
    }

    // Mean-residual coupling: prefer bins close to the mean residual (balanced packing).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Early-stream: be slightly more conservative (keep bins open for future items).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead: perfect chain (item + next_item fills bin exactly)
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 40.0; // perfect 2-item closure
        } else if post_residual > next_item_size {
            // next item fits here: reward tightness of the two-step fit
            let two_step_waste = post_residual - next_item_size;
            score -= 25.0 - (two_step_waste as f64) * 0.5;
        } else {
            // next item cannot follow into this bin: penalize stranded residual
            let stranded = post_residual as f64;
            score += stranded * 0.35;
            // extra penalty if stranded space is too small for typical items
            if post_residual < 10 {
                score += 15.0;
            }
        }
    }

    // Tightness: reward small post_residual relative to bin capacity
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= tightness * 10.0;

    // Relative-to-mean coupling: bins with residual far below mean are precious;
    // placing here when post_residual is small relative to mean is good.
    if mean_residual > 0.0 {
        let rel = post_residual as f64 / mean_residual;
        if rel < 0.5 {
            score -= 8.0 * (1.0 - rel);
        } else if rel > 1.5 {
            score += 5.0 * (rel - 1.5);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bin attractive only when no open bin
    // gives a good fit (post_residual large relative to capacity on open bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // baseline cost of opening a bin; cheaper early, expensive late
        let mut open_cost = 30.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        // if next item is large and current item leaves big residual, new bin is fine
        if next_item_size > 0 && post_residual < next_item_size && post_residual > bin_capacity / 2 {
            open_cost -= 15.0;
        }
        // if many open bins already have large mean residual, opening is wasteful
        if mean_residual > 40.0 {
            open_cost += 20.0;
        }
        score = open_cost + post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Penalize dead space that cannot hold the next item (wasted capacity).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (post_residual as f64);
    }

    // Reward leaving room for the next item (chain-friendly placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 12.0 * (1.0 - (slack as f64) / (bin_capacity as f64)).abs();
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins
    // are open or the stream is late (packing phase matters more).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).ln().max(1.0);
        score += 55.0 + 10.0 * pressure + 20.0 * progress;
        // But if existing fit is terrible (huge post_residual elsewhere),
        // a fresh bin becomes relatively attractive: reduce penalty slightly
        // when the item is small relative to capacity.
        let small_item = item_size as f64 / bin_capacity as f64;
        score -= 30.0 * (1.0 - small_item);
    }

    // Mild preference for bins whose residual is close to the mean
    // (keeps the bin population homogeneous, easier future pairing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Discourage leaving exactly awkward small residuals (11..20) that
    // rarely fit future items drawn from a broad range.
    if post_residual >= 11 && post_residual <= 20 {
        score += 15.0;
    }

    // Reward residuals that are multiples of common small sizes.
    if post_residual > 0 && (post_residual % 10 == 0) {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let t = progress * std::f64::consts::PI;
    let wave = 0.5 * (1.0 - t.cos()); // smooth 0->1 envelope

    // Dead-space penalty grows non-linearly with post_residual and progress.
    score += 40.0 * norm_pr * norm_pr * (0.5 + wave);

    // Reward tight fits more aggressively as stream progresses.
    score -= 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.3 + 0.7 * wave);

    // Penalize last-chance bins only mildly early on, strongly later.
    if fitting_bins_count == 1 {
        score -= 30.0 * (0.2 + 0.8 * wave);
    }

    // Lookahead coupling: if next item fits in post_residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (pr - next_item_size as f64) / cap) * (0.4 + 0.6 * wave);
    } else if next_item_size > 0 {
        score += 8.0 * norm_pr * wave;
    }

    // New-bin candidate: discourage unless residuals are tight or stream is late.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - (mean_residual / cap);
        score += 60.0 - 45.0 * tightness * (0.3 + 0.7 * wave) - 20.0 * wave;
    }

    // Mild preference for spreading load when many bins are open.
    score += 3.0 * ((open_bins_count as f64).ln() + 1.0) * norm_pr;

    // Mean-residual alignment bonus.
    let align = (pr - mean_residual).abs() / cap;
    score += 10.0 * align * align;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (divisible by common size granularities) are rewarded.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        if pr % 10 == 0 { harmony += 6.0; }
        if pr % 20 == 0 { harmony += 4.0; }
        if pr % 25 == 0 { harmony += 3.0; }
        if pr % 50 == 0 { harmony += 2.0; }
        // small leftovers are near-perfect fits
        if pr <= 5 { harmony += 20.0; }
        else if pr <= 10 { harmony += 10.0; }
        score -= harmony;
    } else {
        score -= 30.0; // perfect fill
    }

    // Penalize large awkward leftovers (dead space) super-linearly.
    let frac = post_residual as f64 / cap_f;
    if frac > 0.5 {
        score += (frac - 0.5) * 40.0;
    }

    // Coupling with lookahead: if the next item fits exactly into the
    // post-residual (harmonic match), strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack <= 10 { score -= 12.0; }
            else { score += slack as f64 * 0.15; }
        } else {
            // next item cannot follow here; mild penalty scaled by overshoot
            score += (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin fits well (post_residual would be tiny) or many bins are open.
    if bin_residual == bin_capacity {
        // base cost of consuming fresh capacity
        score += cap_f * 0.5;
        // if this bin is the only fitting option, new bin competes fairly
        if fitting_bins_count == 0 {
            score -= cap_f * 0.5;
        } else if fitting_bins_count == 1 {
            // keep last-chance advantage for the existing bin
            score += 10.0;
        }
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // many open bins: discourage spreading further
        score += open_bins_count as f64 * 0.5;
        // if mean residual across open bins is large, definitely reuse
        if mean_residual > item_size as f64 + 10.0 {
            score += 12.0;
        }
    }

    // Tightness reward: how much of the bin's current residual the item consumes.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Mild pressure to keep number of open bins low early on
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 45.0 * (1.0 - (post_residual as f64) / 10.0) + 15.0;
    }

    // Medium gaps (11..=25) moderately penalized, scaled by how much of the bin is wasted.
    if post_residual > 10 && post_residual <= 25 {
        score += 12.0 * (post_residual as f64 / 25.0);
    }

    // Reward placements leaving gaps that likely fit the next item (lookahead synergy).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Gap too small for the next item: mild penalty.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, consolidate; when few, allow spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // New-bin candidate: only attractive when current bin fit is bad (large post_residual
    // or dead-space penalty applied) or no fitting bins exist besides this one.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a fresh bin.
        let mut new_bin_score = 55.0 + 2.0 * open_bins_count as f64;
        // If the current bin would leave a big unusable remainder, opening new is better.
        if post_residual > 25 || (post_residual > 0 && post_residual <= 10) {
            new_bin_score -= 40.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            new_bin_score += 20.0; // staying is fine, make new bin less attractive
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 60.0;
        }
        score = new_bin_score;
    }

    // Mild tie-breaking toward bins whose residual deviates favorably from the mean.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.96;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0; // next item can chain into this bin
        } else {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many bins when a near-perfect fit exists.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0);

    // Reward bins whose residual is near the mean (balanced usage).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // New-bin candidate: only attractive when existing bins would waste a lot
    // or when the item barely fits nothing well.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = 40.0 + waste * 0.3;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // a fresh bin can host the next item too
        }
        if fitting_bins_count <= 1 {
            score -= 35.0; // no good alternative: open a new bin
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 * progress;
    }

    // Mild bonus for filling bins completely over time.
    score -= 0.05 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual (waste minimization), non-linearly scaled by stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Quadratic penalty for small-but-nonzero dead space (unusable slivers)
    score += 12.0 * norm_pr * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Reward tight fits: smooth coupling of post_residual with item size
    let tightness = 1.0 - pr / cap;
    score -= (item_size as f64 / cap) * 8.0 * tightness * tightness;

    // Lookahead: penalize if next item can't use the post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = ((pr - nx) / cap).max(0.0);
        score -= 6.0 * usable * (1.0 - progress);
        if pr < nx {
            score += 5.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + 0.5 * progress);
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean residual coupling: prefer bins deviating favorably from mean
    score += 0.15 * (mean_residual - pr).abs();

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * progress;
    }

    // Mild penalty for spreading across many open bins late in stream
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tight * tight;

    // Harmonic class of post_residual: residues near 0 mod 10 are "usable slots"
    // (items are often multiples of 10); residues just below 10 are dead space.
    let r = post_residual % 10;
    let r_f = r as f64;
    if r == 0 {
        score -= 8.0;
    } else if r >= 8 {
        score += 10.0 * (r_f - 7.0); // 9 residue is worst: nearly unusable
    } else {
        score += 2.0 * r_f;
    }

    // Lookahead synergy: does next item fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            // fraction of slot consumed by next item
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * frac;
        } else {
            // next item cannot fit here: leftover is likely dead
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
        // harmonic class of next item: multiples of 10 chain well
        if next_item_size % 10 == 0 {
            score -= 3.0;
        }
    }

    // Integer-division thresholds on post_residual (capacity = 100):
    // quarters of the bin as usability classes.
    let quarter = post_residual / (bin_capacity / 4).max(1);
    match quarter {
        0 => score += 20.0,            // 0..24: nearly dead space
        1 => score += 5.0,             // 25..49
        2 => score -= 5.0,             // 50..74: good half-slot
        _ => score -= 10.0,            // 75..99: large slot, keep open
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, scaled by how many
    // existing bins could fit and how much mean capacity is still free.
    if bin_residual == bin_capacity {
        score += 45.0 + 3.0 * open_bins_count as f64;
        if mean_residual > 0.5 * cap {
            score += 10.0; // plenty of room elsewhere; don't open
        }
    }

    // Mild pressure to consolidate as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible item are "dead". Penalize them superlinearly.
    let dead_threshold = 9.0; // smallest realistic item footprint
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Tight fits are excellent: reward small post_residual strongly.
    score -= (bin_capacity as f64 - post_residual as f64).sqrt() * 2.0;

    // Penalize leaving a gap that is unusable by the lookahead item but
    // could have fit it exactly: prefer bins whose post_residual can host
    // next_item_size when such a chain is possible.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0; // enables chaining
        } else {
            score += 4.0; // breaks the chain, creates stranded gap
        }
        // Exact lookahead match is gold.
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing ones; few open bins -> opening a new bin is cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.35 + 0.65 * progress);

    // Last-chance bin: if this is the only fitting bin, avoid forcing a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 0 {
        score -= 5.0 + 0.05 * post_residual as f64;
    }

    // Deviation from mean residual: prefer bins whose residual is below
    // mean (denser bins), keeping loose bins for future large items.
    let res = post_residual as f64;
    if res > mean_residual {
        score += (res - mean_residual) * 0.5;
    } else {
        score -= (mean_residual - res) * 0.25;
    }

    // New-bin candidate: acceptable early or when nothing fits well,
    // but discouraged when open bins are few and stream is long.
    if bin_residual == bin_capacity {
        let scarcity_bonus = if fitting_bins_count == 0 { 20.0 } else { 0.0 };
        score += 30.0 + open_bins_count as f64 * 3.0 - scarcity_bonus
                 - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / (bin_capacity as f64)) * (post_residual as f64 / bin_capacity as f64);
        if post_residual == next_item_size {
            score -= 500.0;
        }
        // Penalize leaving residual too small for next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 40.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Tightness reward: smaller post_residual relative to capacity is better
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: bins with more space than average are better targets
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless few alternatives or big item
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let penalty = 150.0 + 100.0 * (1.0 - progress) + 20.0 * open_bins_count as f64;
        if fitting_bins_count > 1 {
            score += penalty;
        } else {
            score += penalty * 0.3;
        }
    }

    // Small penalty for very low utilization placements
    if item_size < bin_residual / 2 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Lookahead: if the next item fits exactly/comfortably in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; penalize leaving large residuals that trap nothing.
            score += 4.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a bin is discouraged unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Base cost of a new bin grows with how many bins are already open.
        let mut new_bin_score = 55.0 + 6.0 * (open_bins_count as f64).sqrt();
        // Late in the stream, prefer consolidating into existing bins.
        new_bin_score += 20.0 * progress;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        new_bin_score += (mean_residual - item_size as f64).max(0.0) * 0.5;
        score = new_bin_score;
    } else {
        // Slight preference for bins with residuals close to the item (perfect fits).
        let diff = (bin_residual as f64 - item_size as f64).abs();
        score += diff * 0.3;
        // Mild bonus for picking bins below average residual (consolidate emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
    }

    // Time-horizon modulation: early stream, be a bit more tolerant of slack.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit = fitting_bins_count as f64;
    let open_c = open_bins_count as f64;

    // Base: prefer small post-residual, with non-linear sharpening
    let mut score = pr as f64;
    score += 40.0 * norm_pr * norm_pr;
    score += 25.0 * norm_pr * norm_pr * norm_pr * (1.0 + t);

    // Tight-fit reward: post-residual close to zero gets extra subtraction
    let tightness = (1.0 - norm_pr).max(0.0);
    score -= 20.0 * tightness * tightness * tightness;

    // Penalize residual that cannot fit the next item (dead space), smooth coupling
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 30.0 * gap * gap;
        // Bonus if post-residual still fits the lookahead item
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 12.0 * fits_next * (pr / cap);
    }

    // Last-chance bin: strongly reward using it
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * t;
    } else {
        // mild penalty for crowding an already-popular bin
        score += 3.0 * (fit - 1.0).min(5.0) * norm_pr;
    }

    // New-bin candidate: empty bin gets a smooth opening cost that shrinks
    // as the stream progresses or when open bins are badly fragmented
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        let fragmentation = ((mean_residual / cap) - 0.5).abs();
        score = cap as f64 * (1.0 + norm_pr)  // worst possible base
            + 60.0 * (1.0 - t)
            - 40.0 * fragmentation * (1.0 - t)
            - 20.0 * t * t;
        // opening a bin is fine if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    // Mild preference to balance residuals toward mean early in the stream
    score += (1.0 - t) * 4.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Core best-fit: reward tight fits strongly (harmonic in post_residual)
    if post_residual > 0 {
        score -= 40.0 / (post_residual as f64).powf(0.5);
    } else {
        score -= 60.0; // perfect fill
    }

    // Harmonic class of post_residual: residuals in small classes are "dead space"
    // Class boundaries via integer division thresholds on capacity fractions
    let pr = post_residual as f64;
    if pr > 0.0 {
        let class = (pr / cap * 8.0).floor() as u32; // 0..7 harmonic classes
        let class_penalty = match class {
            0 => 0.0,   // near-perfect
            1 => 2.0,   // only tiny items fit later
            2 => 5.0,
            3 => 8.0,
            4 => 11.0,
            5 => 13.0,
            6 => 14.5,
            _ => 15.0,
        };
        score += class_penalty;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // modular harmony: next item leaves another useful residue
            let nr = post_residual - next_item_size;
            let harmony = ((nr + item_size) % 10) as f64;
            score -= 15.0 - harmony * 0.8;
        } else {
            // next item cannot use this residual: penalize large residuals less
            score += (post_residual as f64 - (next_item_size as f64 - post_residual as f64).max(0.0)) * 0.05;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make fresh bins moderately attractive only
    // when current fit is poor and many bins are open
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) / cap; // = 1 - item/cap for new bin
        score = 55.0 + poor_fit * 10.0 - progress * 5.0
            - (open_bins_count as f64).min(20.0) * 0.5;
        // opening a bin for a big item (>50% of capacity) is fine
        if item_size as f64 > 0.5 * cap {
            score -= 12.0;
        }
    }

    // Mild preference to fill older/busier bins to consolidate state
    score -= (open_bins_count as f64).min(30.0) * 0.05;

    // Mean-residual alignment: placing into bins below mean residual tightens spread
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Modular threshold on post_residual: multiples of 5/10 are more reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are worthless.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 1000.0 * (dead_threshold - post_residual) as f64; // unusable gap -> heavy penalty
    } else if post_residual == 0 {
        score -= 500.0; // perfect fill, reward strongly
    }

    // Reward tight fits: fraction of bin consumed by this item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Penalize leaving a gap that barely misses the next item's size (blocks useful future fit).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0; // next item still fits here, keep this bin attractive
        } else if post_residual > 0 {
            score += 5.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    }

    // Open-bins pressure: discourage spreading across many bins when not needed.
    score += 2.0 * open_bins_count as f64 * (1.0 - tightness);

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Prefer bins with residual below the mean (consolidate into emptier-relative bins).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; relax late in stream or when many bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_cost = 150.0 - 80.0 * progress;
        if post_residual < dead_threshold {
            new_bin_cost += 500.0; // a fresh bin leaves a full 100 residual, never "dead"
        }
        if next_item_size > 0 && next_item_size > bin_residual && next_item_size <= bin_capacity {
            new_bin_cost -= 60.0; // next item won't fit in any current bin anyway
        }
        score = post_residual as f64 + new_bin_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Near match: reward closeness of post_residual to next item
        let diff = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
        score -= 40.0 * (-diff * 30.0).exp();
    }

    // Penalize dead space that no plausible item (1..=80) can ever use well
    if post_residual < 10 {
        score += 25.0; // tiny sliver is wasted capacity
    } else if post_residual <= 20 {
        score -= 10.0; // small but usable residual is decent
    }

    // Reward tightening bins below the mean residual (compact packing)
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Early stream: prefer opening fresh bins less; late stream: pack tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins
        score += 15.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
    }

    // Slight preference for filling larger items into tighter bins
    score += 0.05 * item_size as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let fit_ratio = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual that is too small to be useful later.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 15.0;
        } else if (next_item_size as f64) > post_residual as f64
            && (next_item_size as f64) <= mean_residual.max(0.0) + 1.0
        {
            // Next item won't fit here; slight penalty for wasting a good bin.
            score += 5.0;
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into fuller bins rather than spreading load.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowded = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
    score += 0.3 * crowded * (1.0 - progress);

    // Penalize placing into near-empty bins when alternatives exist (fragmentation).
    if bin_residual == bin_capacity {
        score += 8.0 + 20.0 * (1.0 - progress);
    }

    // Mild bonus for balancing residual against mean residual.
    score += 0.1 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_n = pr / capacity;
    let fit_n = (item_size as f64) / capacity;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr_n * (1.0 + 0.8 * progress * progress);

    // Smooth interaction: penalize residual that is too small to be useful
    let deadness = 1.0 - pr_n;
    score += 0.35 * deadness * deadness * (1.0 - progress);

    // Reward tight fits (small post_residual relative to item)
    let tightness = fit_n / (fit_n + pr_n + 0.05);
    score -= 0.6 * tightness * tightness;

    // Lookahead coupling: reward leaving room for the next item
    let nx = next_item_size as f64 / capacity;
    if nx > 0.0 {
        let gap = (pr_n - nx).abs();
        score += 0.25 * gap * gap - 0.4 * nx * (1.0 - pr_n);
    }

    // Last-chance bin pressure: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 1.5;
    }

    // Mild preference for consolidating into fewer bins as stream matures
    score += 0.05 * (open_bins_count as f64).ln() * (1.0 - progress);

    // New-bin candidate: make it slightly unattractive unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 0.4 + 0.3 * (mean_residual / capacity);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // 0.0 .. 1.0
    let class = (frac * 10.0).floor() as i64; // 0..9 harmonic class

    // Dead-space penalty: small nonzero residuals are worst (unusable for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Reward tight fits with a non-linear bonus.
    score -= (item_size as f64 / bin_residual as f64).powi(2) * 15.0;

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chain two items in this bin.
            let combo = item_size + next_item_size;
            score -= (combo as f64 / cap) * 25.0;
            // Harmonic bonus when post residual exactly absorbs next item.
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else {
            // Next item won't fit: penalize proportionally to wasted pairing potential.
            let miss = (next_item_size - post_residual) as f64;
            score += miss * 0.35;
        }
    }

    // Modulo-arithmetic class logic on post_residual (harmonic residue classes mod 10).
    match class {
        0 => score -= 20.0, // perfect fit
        1 => score += 12.0, // tiny dead space
        2 | 3 => score += 6.0,
        4 | 5 | 6 => score -= 5.0, // mid residuals still useful
        _ => score -= 10.0, // large residuals stay flexible
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Prefer filling bins when many are open; penalize spreading too thin.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    // New-bin candidate (empty bin): make it attractive only when residuals are poor.
    if bin_residual == bin_capacity {
        let open_penalty = open_bins_count as f64 * 3.0;
        let mean_quality = mean_residual / cap;
        // Opening a new bin costs something; cheaper if open bins are cluttered.
        score = 15.0 + open_penalty - mean_quality * 20.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing else fits: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical future items are "dead space". Penalize super-linearly.
    let dead_threshold = 20.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight fits relative to bin size.
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 8.0 * tightness * tightness;
    }

    // Lookahead coupling: if next item fits exactly in the post-residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size > post_residual {
            // Next item can't use this residual: residual more likely wasted.
            score += (post_residual as f64) * 0.5;
        } else {
            score -= 5.0;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when mean
    // residual is already high; encourage filling existing bins.
    if open_bins_count > 2 {
        score += open_bins_count as f64 * 1.5;
        if (bin_residual as f64) > mean_residual {
            score -= 4.0; // prefer bins with above-average remaining space
        } else {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when the
    // item is large or no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        if fit_ratio > 0.8 {
            score -= 20.0; // large items deserve a fresh bin
        } else {
            score += 15.0 + 20.0 * (1.0 - fit_ratio); // penalize wasteful new bins
        }
    }

    // Mild stream-progression modulation: early on, be conservative about
    // opening bins; late in the stream, close out bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
