        score += (next_item_size as f64) * 0.5;
    }

    // Penalize residuals far from mean (outlier dead space)
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when good open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        score += 20.0 + 0.3 * mean_residual;
    }

    // Late-stream tightness: prefer tighter fits as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score quadratically as post_residual -> 0.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly-ish,
    // strongly favor this bin (chaining placements).
    if next_item_size > 0 {
        let nd = post_residual as i64 - next_item_size as i64;
        if nd == 0 {
            score -= 14.0;
        } else if nd > 0 && nd <= 10 {
            score -= 7.0;
        } else if nd < 0 && (nd as f64).abs() < 12.0 {
            // Next item nearly fits but misses: mild penalty for near-miss space.
            score += 3.0;
        }
        // If next item is large, prefer conserving big-residual bins.
        if next_item_size >= 60 && post_residual < next_item_size {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when the
    // item fits poorly everywhere else (large post_residual on open bins)
    // or when open-bin residuals are already large on average.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin, modulated by global state.
        score = (bin_capacity - item_size) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // If open bins are crowded (low mean residual), new bin is more acceptable.
        score -= 20.0 * (1.0 - pressure);
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
        // Many open bins: discourage yet another one.
        score += 0.6 * open_bins_count as f64;
    } else {
        // Slight preference for filling already-open bins as stream progresses.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * progress;
        // Prefer bins whose residual is close to the mean (balanced packing),
        // penalize outliers.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
        // Prefer bins with smaller residual (better fill) among fitting bins.
        score += 0.08 * bin_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress - 0.4 * progress * progress);

    // Penalize large unusable dead space quadratically
    score += 40.0 * norm_pr * norm_pr;

    // Reward tight fits (small post_residual) with smooth decay
    score -= 30.0 * (1.0 - norm_pr).powi(3);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer bins with residuals close to the item (smooth Gaussian-ish coupling)
    let diff = (bin_residual as f64 - item_size as f64) / cap;
    score += 25.0 * diff * diff;

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score += 0.3 * gap;
        if pr >= nxt {
            score -= 8.0 * (pr / cap) * (nxt / cap);
        }
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer near-mean bins
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
