    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Tight fit reward: near-perfect packing
    let tight = (post_residual as f64 / bin_capacity as f64).powi(2);
    score -= (1.0 - tight) * 5.0;

    // Progress: as stream advances, be greedier about filling bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    // Penalize bins far below mean residual (fragmentation risk)
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
