    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (best-fit style, superlinear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, avoid spreading; consolidate.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 0.8 * pressure;

    // New-bin candidate: only attractive if current fit is terrible
    // or no bins fit well; penalize opening otherwise.
    if bin_residual == bin_capacity {
        score += 55.0 - 45.0 * fit_ratio;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Lookahead coupling: if the next item fits the post_residual,
    // reward leaving that gap; otherwise penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 20.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Slight early-stream preference for consolidation (fewer bins early).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 40.0;

    // 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining: item + next item fill bin completely
        } else if next_item_size <= post_residual {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= next_fit * 25.0; // next item fits well into leftover
        } else {
            // next item cannot use the leftover: penalize large dead space
            let waste = post_residual as f64;
            score += waste * 0.3;
        }
    }

    // Relative to mean residual: prefer bins with residual below average (tighter bins)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are poor
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if next item is large and current fit is bad, opening a fresh bin is attractive
        if next_item_size > post_residual && post_residual < bin_capacity / 4 {
            score -= 45.0;
        }
    }

    // Early in stream: be slightly more willing to open bins for flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    // Many open bins: prefer consolidating into existing bins
    if open_bins_count > 4 {
        score += 0.5 * open_bins_count as f64 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item nearly fills the residual.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness * tightness);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize dead space that no plausible future item can use.
    let progress = step_index as f64 / total_items as f64;
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // small residual often wasted; but small is good for tightness — keep mild
    }
    if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0 * (1.0 - progress); // early on, mid residuals are reusable
    }

    // Lookahead coupling: reward if next item fits into the post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0;
        } else {
            // penalize leaving a residual that just barely fails the next item
            let gap = (next_item_size - post_residual) as f64;
            if gap < 15.0 {
                score += 10.0 * (1.0 - gap / 15.0);
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate logic: opening a new bin is attractive only when many bins
    // fit the item (fragmentation elsewhere) or this bin would leave bad residual.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mut nb = 40.0;
        // Cheaper to open when item is large relative to capacity (fills new bin well).
        nb -= 30.0 * (item_size as f64 / bin_capacity as f64);
        // If several bins fit, prefer reusing one of them instead.
        if fitting_bins_count > 1 {
            nb += 25.0;
        }
        // Late in stream, opening fresh bins is safer.
        nb -= 15.0 * progress;
        // Many open bins with high mean residual: avoid spreading.
        if mean_residual > 40.0 && open_bins_count > 3 {
            nb += 20.0;
        }
        score += nb;
    }

    // Mild preference for fuller bins among open ones.
    score += 0.1 * (bin_capacity as f64 - bin_residual as f64) * 0.0;
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    // Base: prefer tight fits (small post_residual), with a mild convexity
    // that punishes leaving awkward mid-sized gaps.
    let mut score = post * (1.0 + 0.35 * (post / cap) * (1.0 - post / cap));

    // Non-linear stream-progress coupling: early on, waste is cheap (more
    // items coming to fill gaps); late, waste is costly. Smooth polynomial
    // ramp on progress.
    let urgency = 0.25 + 0.9 * progress * progress * (3.0 - 2.0 * progress);
    score += urgency * post;

    // Dead-space penalty: gaps too small for the smallest plausible item
    // (smooth sigmoid-ish term instead of a hard cutoff).
    let dead = ((cap * 0.15 - post) / (cap * 0.05)).tanh(); // ~1 when gap is usable, ~-1 when dead
    score -= 6.0 * dead;

    // Lookahead coupling: reward if next item fits the post-residual
    // (smooth compatibility kernel).
    if next > 0.0 {
        let compat = (1.0 - (post - next) / cap).max(0.0);
        let compat = compat * compat * (3.0 - 2.0 * compat);
        score -= 8.0 * compat * (1.0 - progress * 0.5);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin should generally lose to
    // decent fits, but win when open bins are crowded (low mean residual).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        let crowding = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 10.0 - 18.0 * crowding * crowding - 4.0 * progress;
    }

    // Slight preference to consolidate across many open bins.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (class 0) heavily rewarded.
    let pr = post_residual as u32;
    let class = pr / 10; // harmonic class of leftover
    match class {
        0 => score -= 25.0,                       // near-perfect fit
        1 => score -= 8.0,                        // small leftover, still usable for tiny items
        2 => score -= 2.0,                        // medium leftover
        3 => score += 4.0,                        // awkward zone (30-39)
        4 => score += 8.0,                        // bad zone (40-49): dead space
        _ => score += 12.0,                       // large leftover: bin underused
    }

    // Exact fit: maximal reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: leftover should ideally host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // leftover can host next item -> reward, more so if tight
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // leftover cannot host next item -> penalty scaled by gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits
        score += 1.5 * (fitting_bins_count as f64).min(10.0);
    }

    // New-bin candidate handling: penalize opening a new bin unless it's
    // genuinely better than reusing a poorly-fitting open bin.
    if bin_residual == bin_capacity {
        // fresh bin: baseline = item leaves residual item_size
        score = item_size as f64;
        // opening a new bin is fine early when few bins are open
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
        // discourage opening when a last-chance bin exists
        if fitting_bins_count == 1 {
            score += 30.0;
        }
        // if next item is small, fresh bin's big residual is valuable
        if next_item_size > 0 && next_item_size <= 30 {
            score -= 6.0;
        }
    }

    // Progress pressure: late in the stream, avoid stranding residual capacity.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 6.0 * progress * (post_residual as f64 / cap);

    // Slight bias toward bins with below-mean residual (consolidating waste).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot accommodate even a small future item (<= 10)
    // is pure waste; residual just above that threshold is fragile.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 12.0 + 0.4 * (20 - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to bin_residual).
    let fit_ratio = post_residual as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * (1.0 - fit_ratio);

    // Pressure from number of open bins: prefer filling existing bins
    // when many are open; allow new bins when few are open.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily; penalize if post residual is awkward relative to it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
    }

    // Prefer bins with residuals near the mean (harmonized gaps).
    score += 0.3 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: penalize mildly so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if no existing bin fits well, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Early in the stream, allow more bins to keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small post_residual is already the base score).
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item well.
    if next_item_size > 0 {
        let gap = if post_residual >= next_item_size {
            (post_residual - next_item_size) as f64
        } else {
            (next_item_size - post_residual) as f64 * 1.5 // unusable space penalty if next item can't fit
        };
        score += gap * 0.35;

        // Perfect chain: next item exactly fills this bin after current item.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Penalize bins whose residual deviates strongly from the mean residual
    // (prefer balanced usage across open bins).
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev.abs();

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it unattractive unless all open bins fit poorly.
    if bin_residual == bin_capacity {
        let mut base = 40.0;
        if fitting_bins_count == 0 {
            base = -10.0; // no open bin fits: opening a new bin is correct
        } else if fitting_bins_count == 1 {
            base = 10.0; // one last-chance bin exists, prefer it
        }
        // Slightly less penalty late in the stream when many bins are open.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += base - progress * 3.0;
    }

    // Mild penalty for leaving large dead space relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // small leftovers often pair with small items
    }

    // Tie-break: prefer bins with larger residual among similar fits
    // (keeps tight bins available for small items).
    score -= (bin_residual as f64) * 0.02;

    // Slight preference to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor the last-chance bin: if this is the only bin that fits,
    // using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 500.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.25 * next_item_size as f64;
        } else {
            // Penalize residual the next item cannot use (potential dead space).
            score += 0.3 * (post_residual as f64 - (next_item_size as f64 - 1.0)).max(0.0);
        }
    }

    // Tight fits are valuable: reward small post-residual relative to item size.
    if item_size > 0 {
        let tightness = post_residual as f64 / (bin_capacity as f64);
        score -= 40.0 * (1.0 - tightness).powi(3);
    }

    // Time horizon: early in the stream, keep bins flexible (penalize tiny residuals);
    // late in the stream, prioritize compacting (reward near-full bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.15 * post_residual as f64;
    score -= progress * 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global state coupling: many open bins with high mean residual -> prefer
    // filling existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when open bins are underutilized.
        score += 60.0 + 2.0 * open_bins_count as f64 + 0.5 * mean_residual;
        if progress > 0.9 {
            score -= 40.0; // late stream: a fresh bin may still pay off
        }
    } else {
        score -= 0.2 * mean_residual.min(post_residual as f64);
    }

    // Mild penalty for leaving residuals in the awkward 1..=9 band.
    if post_residual >= 1 && post_residual <= 9 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = post / cap;

    // Base: waste after placement, weighted by stream progress (waste matters more later).
    let mut score = post * (0.5 + 1.5 * progress * progress);

    // Non-linear polynomial coupling: penalize residual near the "dead zone"
    // (small, unusable leftovers) using a smooth bump centered around ~item_size/2.
    let dead_center = item_size as f64 * 0.5;
    let dead_width = 15.0 + 20.0 * (1.0 - progress);
    let d = (post - dead_center) / dead_width;
    score += 30.0 * (d * d - 1.0).max(-1.0) * (1.0 - d * d).max(0.0) * 10.0;

    // Reward tight fits (small post_residual) superlinearly.
    score -= 40.0 * (1.0 - pr_norm).powi(3);

    // Penalize leaving space for the next item if this bin could host it instead.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 8.0 * progress;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: mild penalty so open bins are preferred unless fit is terrible.
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress * (mean_residual / cap);
    }

    // Discourage accumulating many open bins with large residuals.
    score += 0.5 * open_bins_count as f64 * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic bonus as post_residual -> 0
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Harmonic residue classes: dead space that is small and "class-aligned"
    // with future items is more usable; penalize unusable slivers.
    let r = post_residual;
    if r > 0 {
        // Sliver penalty: residuals < 10 are almost certainly dead space
        if r < 10 {
            score += 40.0;
        } else {
            // Class-based usability: residual divisible by common item sizes
            // (10, 20, 25, 50) is more likely to be exactly filled later.
            let mut class_bonus = 0.0;
            if r % 10 == 0 { class_bonus += 6.0; }
            if r % 20 == 0 { class_bonus += 4.0; }
            if r % 25 == 0 { class_bonus += 4.0; }
            if r % 50 == 0 { class_bonus += 5.0; }
            score -= class_bonus;

            // Lookahead coupling: if next item fits exactly into post_residual,
            // strongly reward; if next item fits, mild reward.
            if next_item_size > 0 {
                if next_item_size == r {
                    score -= 30.0;
                } else if next_item_size <= r {
                    score -= 8.0;
                } else {
                    // next item cannot use this residual: mild penalty scaled by waste
                    score += 3.0 * (r as f64 / bin_capacity as f64);
                }
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should be chosen only when
    // the item fits poorly everywhere. New bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score += 20.0;
        // Cheaper to open new bins early in the stream (more items to fill it)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
        // If many bins are open and mean residual is high, prefer reusing
        if open_bins_count > 0 && mean_residual > item_size as f64 + 15.0 {
            score += 10.0;
        }
        // If next item is large, a fresh bin is valuable
        if next_item_size > 60 {
            score -= 8.0;
        }
    }

    // Mild pressure to consolidate: prefer bins with below-mean residual
    // (filling emptier bins keeps big-residual bins flexible)
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Integer-division threshold: post_residual in [10,20) is a decent
    // "small item" pocket; slight reward.
    if (10..20).contains(&r) {
        score -= 5.0;
    }
    // Large-but-awkward residual band [30,40): often wasted
    if (30..40).contains(&r) {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
