pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Extra bonus for exact match (item + next item fills bin perfectly)
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize post_residual too small to fit next item if it's wasteful dead space
        if (post_residual as u32) < next_item_size {
            score += 0.15 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: reward tight fills
        score -= 20.0 / (1.0 + post_residual as f64);
    }

    // Reward being below mean residual (tighter bin than average)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strong bonus to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins fit decently
    if bin_residual == bin_capacity {
        score += 12.0;
        // But allow new bin if it would fit next item perfectly too
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 30.0;
        }
        // Late in stream, prefer filling existing bins more strongly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strong reward for tight fits: small post_residual is good.
    // Non-linear: heavily penalize medium dead space, reward near-zero residual.
    let pr = post_residual as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    } else if post_residual <= 20 {
        score -= 5.0;
    } else {
        // dead space that is hard to reuse later: penalize more over time
        score += 0.15 * (pr - 20.0) * (1.0 + progress);
    }

    // Lookahead coupling: if the next item fits into the resulting residual,
    // this placement chains nicely -> reward proportionally to how well it fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - 0.4 * slack;
    } else if next_item_size > post_residual {
        // residual too small for the next item: mild penalty, stronger late in stream
        score += 4.0 + 6.0 * progress;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // New-bin candidate handling: empty bin has bin_residual == bin_capacity.
    // Its raw post_residual is large, so it already looks bad; add an explicit
    // opening cost that shrinks when many bins are open or stream is late
    // (consolidation pressure), and shrink when the item is large (big items
    // deserve fresh space).
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let open_cost = 22.0 - 10.0 * item_frac - 4.0 * progress
            - (open_bins_count.min(12) as f64) * 0.8;
        score += open_cost.max(0.0);
        // But if NO open bin fits at all, opening is mandatory: remove the cost.
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Global state: prefer bins with residual close to the mean (balanced usage),
    // slightly discourage dumping into already-large-residual bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Mild preference for filling fuller bins earlier (best-fit flavor)
    score -= 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early in the stream, tolerate larger residuals (bins stay flexible);
    // late in the stream, aggressively minimize post_residual.
    let progress_weight = 0.35 * progress * progress + 0.15 * progress;
    score += progress_weight * norm_pr * (pr * 0.05);

    // Reward tight fits (small post_residual) with a smooth quadratic discount.
    let tightness = 1.0 - norm_pr;
    score -= 12.0 * tightness * tightness;

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Next item cannot follow: mildly penalize creating dead space.
        score += 4.0 * norm_pr * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Penalize bins whose residual is far from the mean residual (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate (pristine empty bin): penalize opening new bins unless
    // the item is large relative to capacity and the stream is early/mid.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        let openness = 1.0 - progress;
        score += 10.0 - 14.0 * fill * openness;
    }

    // Mild reward for consolidating into fewer bins when many are open.
    score -= 2.0 / (1.0 + open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
