pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for any plausible item are wasted.
    // Items in [1,100], so any residual > 0 can technically fit something, but small
    // residuals (< ~15) are statistically near-unusable dead space.
    if post_residual > 0 && post_residual < 15 {
        score += 60.0 + (15 - post_residual) as f64 * 4.0;
    }
    // Perfect or near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Reward bins whose residual tightly matches the item (good fit quality).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 40.0;

    // Lookahead coupling: if the post-residual can host the next item, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // If post-residual is a near-miss for the next item (gap of <= 10), mildly penalize.
    if next_item_size > post_residual && next_item_size - post_residual <= 10 && post_residual > 0 {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins when few fit options exist.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64).max(1.0);
    score += pressure * 2.0;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: default moderate score; only attractive when no open bin
    // offers a decent fit (high mean residual spread / many dead gaps).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 55.0;
        // If existing bins are fragmented (mean residual small relative to item), opening
        // a fresh bin becomes more attractive.
        let fragmentation = (mean_residual - item_size as f64).abs();
        score -= fragmentation * 0.5;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += progress * 30.0;
        // If the only fitting bin is this new-bin slot, make it viable.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the leftover exactly hosts the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            score -= 60.0; // perfect chain: next item fills this bin exactly
        } else if post >= nxt {
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // dead space the next item cannot use
            score += 0.35 * diff;
        }
    }

    // Reward tight fits relative to mean residual of open bins.
    let post_f = post_residual as f64;
    if post_f < mean_residual {
        score -= 8.0 * (mean_residual - post_f) / bin_capacity as f64;
    } else {
        score += 0.5 * (post_f - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize leaving tiny unusable slivers (dead space < smallest item).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Prefer fuller bins overall (waste minimization).
    score -= 10.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // New-bin candidate: accept only when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        let good_fit_exists = next_item_size == 0 || post_residual >= next_item_size;
        if fitting_bins_count > 0 && (post_f > 0.45 * bin_capacity as f64 || !good_fit_exists) {
            score += 55.0; // discourage opening new bin when decent fits exist
        } else if fitting_bins_count == 0 {
            score -= 20.0; // nothing fits elsewhere: new bin is fine
        }
    }

    // Late in the stream, consolidate harder.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (1.0 - post_f / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fits super-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness * tightness;

    // Dead-space penalty: residual too small to host a plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly into the post residual,
    // penalize if it just barely fails (creating likely waste).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / (bin_capacity as f64));
        } else if next_item_size > bin_residual {
            // next item won't fit here anyway; residual value is lower
            score += 4.0;
        } else {
            // next item fits now but not after this placement: strong penalty
            score += 15.0;
        }
    }

    // Last-chance bonus: this is the only bin that can take the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global fragmentation pressure: when mean residual is high, spreading
    // items is fine; when low, prefer consolidating into tighter bins.
    score += 0.15 * (mean_residual - post_residual as f64);

    // Time horizon: early in the stream, keep bins flexible (mild penalty
    // for very tight fills); late in the stream, prioritize closure.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.08 * post_residual as f64;
    score -= progress * 10.0 * tightness;

    // Load balancing: with many open bins, discourage opening more bins
    // unless the fit is excellent.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening unless item is large relative
        // to capacity or existing bins are nearly full.
        let avg_fill = 1.0 - mean_residual / (bin_capacity as f64).max(1.0);
        score += 18.0 + 0.3 * open_bins_count as f64 - 25.0 * avg_fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer minimal post_residual (tight packing), non-linearly coupled
    let mut score = post * (1.0 + 0.5 * norm_post * norm_post);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; late, demand tight fits.
    let coupling = 1.0 - progress * progress;
    score += coupling * post * 0.6;

    // Penalize dead space relative to mean residual across open bins
    score += 0.3 * (post - mean_residual).abs();

    // Lookahead: reward if next item fits in the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 2.0 * (1.0 - nxt / cap);
        } else {
            // penalize leaving residual too small for the next item (waste)
            score += 0.5 * (nxt - post) / cap * cap / 10.0;
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly when open bins exist and fit is decent,
    // so new bins are opened only for genuinely poor fits.
    if bin_residual == bin_capacity {
        if open_bins_count > 0 && fitting_bins_count > 0 {
            score += 8.0 + 4.0 * (1.0 - progress);
        } else if open_bins_count > 0 {
            // no existing bin fits well enough; opening a new bin is reasonable
            score += 2.0 * (1.0 - progress);
        }
    }

    // Slight reward for using more open bins when many are open (balance)
    score += 0.02 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Perfect fits are strongly rewarded.
    if pr == 0 {
        score -= 3.0 * cap;
    } else if pr <= eighth {
        score -= 1.5 * cap;
    } else if pr <= quarter {
        score -= 0.5 * cap;
    }

    // Penalize dead space that no plausible item (1..=80) can fill: post_residual < 10
    // is unusable, and post_residual in small ranges wastes capacity.
    if pr > 0 && pr < 10 {
        score += 2.0 * cap;
    }

    // Harmonic modulo classes: leftovers that are common item sizes (multiples of 5/10)
    // are more likely to be filled later, so reward them.
    if pr % 10 == 0 && pr > 0 {
        score -= 0.6 * cap;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 0.3 * cap;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 2.5 * cap;
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            if gap <= eighth {
                score -= 1.0 * cap;
            }
            score -= (gap as f64) * 0.01;
        } else {
            // next item cannot follow here: mild penalty proportional to overflow.
            score += ((next_item_size - pr) as f64) * 0.05;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.2 * cap;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += cap; // base cost of a fresh bin
        if fitting_bins_count == 0 {
            score -= 2.0 * cap; // no alternative, must open
        } else if post_residual > quarter {
            // item leaves a large usable hole in an existing bin anyway -> new bin worse
            score += 0.3 * cap;
        } else {
            score -= 0.2 * cap; // tight fit exists; avoid bin proliferation
        }
    }

    // Prefer fuller bins: reward small post_residual relative to mean residual.
    score -= (cap - (post_residual as f64)) * 0.05;
    if mean_residual > 0.0 {
        score += (post_residual as f64 - mean_residual) * 0.1;
    }

    // Late in stream: consolidate aggressively to avoid extra bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 0.5 * cap * (fitting_bins_count as f64).recip().max(0.02);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized,
    // with a cliff at 10 (the minimum item size under the original regime, kept as a
    // conservative dead-space threshold for the 1..100 interface).
    if post_residual >= 1 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else {
        // Usable leftover: mild reward proportional to how well it could host mid-size items.
        score -= 0.15 * post_residual as f64;
    }

    // Reward tight fits relative to residual (low waste ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Open-bin pressure: when many bins are open, discourage spreading; encourage closing
    // bins by favoring placements that reduce per-bin residual toward zero.
    score += 2.0 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Last-chance bin: strongly prefer using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // big reward; if next item cannot use post_residual, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        } else {
            score -= 0.3 * (post_residual - next_item_size) as f64;
        }
    }

    // Mean-residual coupling: placing into a bin with above-mean residual is mildly good
    // (balances residuals), below-mean residual is mildly penalized.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive late in the stream or when the item
    // is huge relative to capacity and no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 / bin_capacity as f64;
        score = 30.0 + 40.0 * progress - 30.0 * big_item;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        if post_residual <= 10 {
            score += 60.0 * (11.0 - post_residual as f64); // dead space in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0; // perfect 2-step chain
        } else if post_residual >= next_item_size {
            // next item still fits here, but leftover remains; mild reward scaled by fit quality
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover; penalize dead space creation
            let wasted = post_residual as f64;
            score += 0.5 * wasted;
        }
    } else {
        // last item: prefer tightest fit
        score -= 20.0;
    }

    // Reward tight fits relative to current residual.
    score -= 10.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize bins far from the mean residual (avoid fragmenting outlier bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Late in the stream, prefer closing bins down (smaller post residual weighted more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post_residual as f64 * 0.3;

    // Slight preference for reusing existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

