        if fitting_bins_count > 0 {
            score += 18.0; // discourage opening new bin when alternatives exist
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: post-residual with mild convexity (dead space penalized super-linearly)
    let mut score = pr + 12.0 * fit_norm * fit_norm * cap;

    // Stream progress: late in the stream, waste matters more
    score += 30.0 * progress * fit_norm * fit_norm;

    // Reward tight fits (small post_residual) more strongly as stream advances
    score -= 25.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * (0.3 + 0.7 * progress);

    // Coupling with mean residual: prefer bins whose residual differs favorably from mean
    score += 0.15 * (pr - mean_residual).abs();

    // Lookahead: if next item fits into post_residual, reward; otherwise penalize
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 8.0 * (1.0 - nx / cap);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - progress);
        score -= 15.0 * progress;
    }

    // Mild penalty for many open bins relative to progress (bin count control)
    score += 2.0 * open_bins_count as f64 / (1.0 + 50.0 * progress);

    // New-bin candidate: only attractive when fits are poor or stream is early
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        score += 18.0 * (1.0 - fit_norm) * (1.0 - progress) - 10.0 * fit_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (post_residual % (bin_capacity / 10).max(1)) as f64;
    let quot = (post_residual / (bin_capacity / 10).max(1)) as f64;

    // Reward small post_residual (best fit)
    score -= 8.0 * (1.0 - pr / cap);

    // Penalize unusable dead space: residual too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Harmonic reward: post_residual divisible into useful chunks
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 5.0;
    }
    if post_residual % 25 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: next item fits exactly -> strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; prefer leaving larger residual
            score += 0.05 * (next_item_size as f64 - pr).max(0.0);
        }
    }

    // Last-chance bin: strong preference to use it rather than open new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer new bin only when current bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual < 0.35 * cap && open_bins_count > 2;
        if crowded && next_item_size > 0 && next_item_size > mean_residual {
            score -= 12.0 * progress;
        } else {
            score += 18.0;
        }
    } else {
        // Reward bins with residual above mean (keep spread balanced)
        let dev = pr - mean_residual;
        score += 0.08 * dev;
    }

    // Mild penalty for many fitting bins (prefer tighter bins via base term anyway)
    if fitting_bins_count > 3 {
        score += 1.5;
    }

    // Integer-division threshold: quads of residual class
    score += 0.5 * quot;

    // Progress-scaled tiny jitter on class to break ties deterministically
    score += 0.01 * class;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.16;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward exact match of post_residual with next item ---
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if post >= next {
            // Reward tight coupling: the next item exactly fills this bin
            let gap = post - next;
            if gap == 0.0 {
                score -= 60.0 + 40.0 * (1.0 - progress); // perfect chain fill
            } else {
                // Reward proportionally to how small the leftover-after-next is
                score -= 40.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item cannot use this bin's leftover: penalize dead space
            score += 15.0 + 10.0 * (1.0 - post / bin_capacity as f64);
        }
    } else {
        // Last item: just prefer the fullest bin
        score -= 30.0;
    }

    // --- Relative-to-mean residual coupling ---
    let mean_gap = post_residual as f64 - mean_residual;
    // Prefer leaving residuals near the mean (keeps fleet balanced),
    // but strongly prefer residuals *below* the mean (tighter packing)
    if mean_gap > 0.0 {
        score += 0.35 * mean_gap;
    } else {
        score -= 0.25 * (-mean_gap);
    }

    // --- Last-chance bonus: if this is the only bin that fits, use it ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly,
        // i.e. when post_residual of this fresh bin is large and no tight match exists.
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (post_residual as f64) < mean_residual * 0.5;
        if poor_fit_elsewhere {
            score -= 25.0; // allow opening a fresh bin
        } else {
            score += 45.0; // discourage opening bins when good fits exist
        }
    }

    // --- Slight pressure to consolidate into fewer bins as stream progresses ---
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize wasted space quadratically relative to capacity.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste * waste;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how well it uses leftover.
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: slight penalty for leaving awkward space.
            score += 5.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep bins flexible); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    // New-bin candidate handling: opening a new bin should only win when the item
    // fits poorly in existing bins. Penalize the fresh bin moderately, scaled by
    // how many bins can already fit the item and by mean residual availability.
    if bin_residual == bin_capacity {
        score += 20.0 + 8.0 * (fitting_bins_count as f64);
        // If mean residual across open bins is large, existing bins likely suffice.
        score += 0.15 * mean_residual;
        // Late in the stream, opening new bins is even less attractive.
        score += 15.0 * progress;
    } else {
        // Favor bins whose residual is below mean (denser bins) slightly.
        score += 0.05 * (mean_residual - bin_residual as f64);
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer filling bins loosely (waste tolerated); later, punish residual waste quadratically.
    let progress_weight = 0.5 + progress * progress * 1.5;
    score += progress_weight * (pr / cap) * pr * 0.1;

    // Reward tight fits: small post_residual gets a smooth cubic bonus.
    let tightness = 1.0 - pr / cap;
    score -= 3.0 * tightness * tightness * tightness * (pr / cap);

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack = pr - nxt;
            score -= 2.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; mildly penalize leaving a gap that matches nothing.
            score += 0.5 * (pr / cap) * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: prefer it only when residuals across open bins are already small
    // (i.e., open bins are well-packed and this item would create large dead space).
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / cap;
        let waste_here = pr / cap;
        score = cap * 0.6 + mean_frac * 20.0 - waste_here * 10.0;
        // As stream progresses, opening new bins becomes slightly less attractive.
        score += progress * 5.0;
    }

    // Mild penalty for proliferation of open bins with large mean residual.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice" multiples
    // (highly divisible residuals are more reusable by future items).
    let pr = post_residual;
    let nice = if pr == 0 { 3.0 }
        else if pr % 10 == 0 { 2.0 }
        else if pr % 5 == 0 { 1.0 }
        else if pr % 2 == 0 { 0.5 }
        else { 0.0 };
    score -= nice * 4.0;

    // Dead-space penalty: small nonzero residuals are nearly unusable (items >= 1..100).
    if pr > 0 && pr < 10 {
        score += 30.0;
    } else if pr > 0 && pr < 20 {
        score += 10.0;
    }

    // Perfect fit is a jackpot.
    if pr == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            score -= 8.0 + (pr - next_item_size) as f64 * -0.2;
        } else {
            // next item cannot use this residual: slight penalty scaled by wasted fraction
            score += 0.1 * (next_item_size as f64 - pr as f64).min(60.0);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin should be discouraged unless the
    // item is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        // baseline cost of a fresh bin
        score = (bin_capacity - item_size) as f64 + 15.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin can also host the next item
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 6.0;
    }

    // Mild pressure to keep number of open bins low.
    score += 0.3 * open_bins_count as f64;

    // Tie-breaker toward bins tighter than average (better fills).
    score += 0.2 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100)
    // are pure waste. Penalize gaps that are unusable for the known next item.
    if post_residual > 0 {
        // Perfect fit bonus
        if post_residual == 0 {
            score -= 1000.0;
        }
        // Dead space: gap smaller than the smallest possible item (1) can't happen,
        // but gaps smaller than the next item are likely wasted.
        if next_item_size > 0 && post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 3.0;
        }
        // Harsh penalty for tiny unusable slivers (very likely dead space)
        if post_residual <= 10 {
            score += 40.0 + (10 - post_residual) as f64 * 5.0;
        }
    }

    // Reward tight fits (small post_residual relative to residual)
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: discourage scattering across many bins when few bins fit
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 15.0; // last-chance / scarce fit: strongly prefer using this bin
    }
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin offers a good fit (i.e., this bin would be left with a bad gap)
    if bin_residual == bin_capacity {
        // Slight handicap so we prefer reusing bins with decent fits
        score += 30.0;
        // But if the item is large and fits almost perfectly in a fresh bin,
        // opening is fine (keep base low via post_residual already small).
        if item_size as f64 / bin_capacity as f64 > 0.7 {
            score -= 20.0;
        }
        // Late in the stream, avoid opening extra bins unnecessarily
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mean residual coupling: when open bins are mostly empty, prefer filling them
    if bin_residual != bin_capacity && (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item fits the post-residual exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow in this bin: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += 25.0 * (gap / bin_capacity as f64);
        }
    } else {
        // Last item: prefer tightest fit.
        score += 10.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Tight fit reward relative to current residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill * fill;

    // Compare post_residual against mean residual: avoid creating outliers of dead space.
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Penalize opening a new bin when decent existing bins exist.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score += 30.0 + 2.0 * pressure;
        // Allow new bin if next item is large and would waste this bin.
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
            score -= 35.0;
        }
    }

    // Slight late-stream tightening: consolidate as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Lookahead: reward if the next item fits in post_residual (chaining)
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        score -= 25.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        if leftover == 0 {
            score -= 20.0; // perfect two-item chain
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: next item cannot use what remains
        score += 0.3 * post_residual as f64;
    }

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Many open bins: encourage consolidation into existing bins
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    if bin_residual < bin_capacity {
        score -= 5.0 * pressure.min(10.0);
    }

    // New-bin candidate handling: only attractive when fits are poor or none exist
    if bin_residual == bin_capacity {
        let best_possible_waste = if fitting_bins_count > 0 {
            // estimate waste if forced into an existing bin: unknown, use mean residual
            (mean_residual - item_size as f64).max(0.0)
        } else {
            100.0
        };
        let new_bin_waste = (bin_capacity - item_size) as f64;
        if new_bin_waste < best_possible_waste - 15.0 {
            score -= 60.0; // opening fresh bin wastes less
        } else {
            score += 35.0; // prefer existing bins
        }
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Early stream: slightly favor filling existing bins to build dense packing
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.5 {
        score -= 5.0 * (1.0 - 2.0 * progress);
    }

    // Mild penalty for very large leftover gaps that nothing (min size 1) can fill well
    if post_residual > 50 {
        score += 0.2 * (post_residual as f64 - 50.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear tightness reward: strongly favor small post-residuals.
    let tight = (pr / cap).powi(3);
    score += tight * 30.0;

    // Quadratic coupling of tightness with stream progress: early on, waste is cheaper;
    // later, compactness matters more.
    score += tight * (1.0 + progress * 60.0);

    // Penalize residuals that no plausible next item can use (dead space).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let usable = (ns - pr).abs();
        let mismatch = (usable / cap).powi(2);
        score += mismatch * 25.0 * (0.5 + progress);
        // Reward exact pairing: post_residual fits next item nicely.
        if ns <= pr {
            score -= 20.0 * (1.0 - (pr - ns) / cap);
        }
    }

    // Mean-residual deviation coupling: bins far below mean residual are "odd" bins;
    // prefer filling them (reduce dispersion).
    let dev = (pr - mean_residual) / cap;
    score += dev.abs() * 10.0 - dev * 15.0;

    // Last-chance bin: heavy reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // New-bin candidate: only attractive when existing fit is very poor.
    if bin_residual == bin_capacity {
        let poor_fit = pr / cap; // = 1 - item/cap
        let base = cap * 0.35;
        score += base - poor_fit * 40.0 + progress * 10.0;
        if fitting_bins_count <= 2 {
            score -= 15.0;
        }
    }

    // Mild penalty for spreading across many open bins.
    score += (open_bins_count as f64).ln() * 2.0;

    // Smooth sigmoid pressure toward compaction as stream progresses.
    let sig = 1.0 / (1.0 + (-(progress * 8.0 - 4.0)).exp());
    score -= sig * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful"
    // sizes (multiples of small integers, or large enough to host typical items).
    let pr = post_residual;
    if pr > 0 {
        // Dead-space penalty grows superlinearly for tiny unusable residuals.
        if pr < 10 {
            score += (10 - pr) as f64 * 6.0;
        }
        // Reward residuals in harmonic classes 1/3, 1/2, 2/3 of capacity.
        let thirds = bin_capacity / 3;
        let half = bin_capacity / 2;
        let two_thirds = 2 * bin_capacity / 3;
        if pr == thirds || pr == half || pr == two_thirds {
            score -= 12.0;
        }
        // Reward residuals that can exactly host the next item.
        if next_item_size > 0 && pr == next_item_size {
            score -= 25.0;
        }
        // Penalize residuals that cannot fit the next item (wasted capacity ahead).
        if next_item_size > 0 && pr < next_item_size {
            score += (next_item_size - pr) as f64 * 0.8;
        }
        // Reward residuals that can host the next item with room to spare.
        if next_item_size > 0 && pr >= next_item_size {
            score -= (pr - next_item_size) as f64 * 0.15;
        }
        // Integer-division threshold: residuals divisible by 4 are more flexible.
        if pr % 4 == 0 {
            score -= 3.0;
        }
        // Modulo-10 class: residuals near multiples of 10 align with size range.
        let m = pr % 10;
        if m == 0 {
            score -= 2.0;
        } else if m >= 7 {
            score += 2.0;
        }
    }

    // Tight-fit reward: small post_residual relative to item size is good.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Early in stream, new bins are cheaper; late, prefer consolidation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 10.0;
        // If many open bins with slack, avoid a new one.
        if open_bins_count > 3 && mean_residual > item_size as f64 {
            score += 15.0;
        }
        // If next item is large and no open bin likely fits both, new bin is fine.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 20.0;
        }
    }

    // Slight preference for filling bins with below-average residual (larger holes).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item
    // (1..10) are "dead space". Penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    }

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // If post_residual can still host the next item, reward the useful gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (next_item_size as f64) * 0.8;
    } else if next_item_size > 0 {
        // Gap will be unusable for the lookahead item: mild penalty.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins unless the fit is excellent.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins open or fit is near-perfect.
        score += open_bins_count as f64 * 5.0 - progress * 10.0;
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 20.0;
        }
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Slight preference for bins below mean residual (consolidating fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strong reward for perfect 2-step lookahead match: post_residual equals next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Perfect match: big subtraction; near match: graded reward
        if diff == 0.0 {
            score -= 60.0 + 20.0 * progress;
        } else {
            score -= 30.0 * (-diff / 20.0).exp();
        }

        // Penalize leaving residual that is too small for next item (dead space trap)
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit, no future to consider
        score -= 10.0;
    }

    // Reward tight fits relative to mean residual of open bins
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening new bins when there are already many open bins
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
        // But if nothing fits well elsewhere (large residual mismatch), new bin is ok
        if next_item_size > 0 && post_residual == bin_capacity - item_size {
            score -= 10.0;
        }
    }

    // Mild penalty for wasting large residual capacity late in the stream
    score += 0.1 * (post_residual as f64 / bin_capacity as f64) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: reward tight fits (small post_residual), with a mild convexity so
    // leaving ~0 residual is strongly preferred.
    score = post_residual as f64 + 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Penalize bins whose residual is far above what the item leaves behind
    // (wasting a large residual on a small item).
    let waste = bin_residual as f64 - item_size as f64;
    score += 0.15 * waste.max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Many fitting bins: prefer the tightest; add mild penalty scaled by choice abundance.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Lookahead: if the next item would fit in post_residual, reward keeping
    // this bin compatible with the future item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: next item exactly fills post_residual is ideal.
            let slack = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here after placement: slight penalty, worse
            // if post_residual is a "useless" sliver.
            if post_residual < 10 {
                score += 6.0;
            }
            score += 1.0;
        }
        // If next item is large, avoid squandering big residuals on small items.
        if next_item_size > 60 && item_size < 30 && post_residual > 40 {
            score += 10.0;
        }
    }

    // Global state: when many bins are open with high mean residual, encourage
    // consolidation into existing bins rather than opening new ones.
    if mean_residual > 0.0 {
        let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).sqrt();
        score += 3.0 * consolidation;
    }

    // New-bin candidate handling: an empty bin must score HIGH (bad) unless
    // existing fits are terrible. Penalize the fresh bin, but relax the penalty
    // late in the stream when consolidation pressure is high.
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 30.0;
        // If no open bin fits well (this call only happens alongside others),
        // reduce penalty when the item is large relative to capacity.
        new_bin_penalty -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // Late stream: keep closing out bins; opening new ones is less costly.
        new_bin_penalty *= 1.0 - 0.4 * progress;
        score += new_bin_penalty.max(5.0);
    }

    // Small dynamic time-horizon term: early on, prefer exploring (slightly
    // favor new bins / loose fits); later, demand tightness.
    score *= 1.0 - 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: penalize leftover residual, modulated by stream progress
    let mut score = pr as f64;

    // Smooth non-linear coupling of residual with progress
    let poly = x * x * (1.0 - x) * 4.0; // peaks at x=0.5, zero at edges
    score += poly * cap * (0.4 + 0.6 * progress);

    // Reward tight fits: subtract when post_residual is small relative to item
    let tightness = 1.0 - x;
    score -= tightness * item_size as f64 * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 20.0 * progress;
    }

    // Penalize wasting a nearly-full bin when many bins can fit the item
    if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0) * (1.0 - progress);
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 6.0 * (1.0 - pr / cap);
    }

    // New-bin candidate: prefer it only when it creates a fresh large residual late in stream
    if bin_residual == bin_capacity {
        score = cap - 0.5 * pr + 10.0 * (1.0 - progress) - 8.0 * (open_bins_count as f64).ln();
        // discourage opening new bin if a decent fit exists
        if fitting_bins_count > 0 && x >= item_size as f64 / cap {
            score += 15.0;
        }
    }

    // Mean residual alignment: favor bins whose residual is near the mean (balanced packing)
    score += 0.3 * (mean_residual - pr).abs() * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: prefer residuals in "usable" classes
    // (multiples of common item sizes) over dead space.
    let pr = post_residual as i64;
    let mut usable_bonus = 0.0;
    if pr > 0 {
        for m in [5u64, 10, 20, 25, 50].iter() {
            if (pr as u64) % m == 0 {
                usable_bonus += 6.0;
            }
        }
        // small residuals are nearly dead space; penalize gently
        if pr <= 5 {
            usable_bonus -= 4.0;
        }
    } else {
        // perfect fit: strong reward
        usable_bonus -= 25.0;
    }
    score -= usable_bonus;

    // Fractional capacity classes: reward tight fills (post_residual small fraction of capacity)
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * frac * frac;

    // Integer-division threshold on post_residual: residuals in [1..10] are wasteful
    if post_residual > 0 && post_residual <= 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
            // harmonic class match between next item and residual
            if post_residual % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot use this residual; penalize large leftover more
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // opening a new bin wastes nothing now but defers packing; make it
        // competitive only if existing bins would leave large dead space
        let waste_if_here = post_residual as f64;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin anyway
        } else {
            score += 12.0 + 0.2 * open_bins_count as f64;
            if waste_if_here > 40.0 {
                score -= 10.0; // poor fits exist; fresh bin may be better
            }
        }
    }

    // Mean residual context: if this bin's residual is far below mean, it's a good squeeze
    let dev = mean_residual - bin_residual as f64;
    score += 0.05 * dev;

    // Slight preference to keep few bins open early in the stream
    score += 0.01 * (open_bins_count as f64) * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item
    // (or even the lookahead item) are wasted space -> heavy penalty.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 500.0; // perfect fit, ideal
    } else if post_residual < 10 {
        score += 120.0; // unusable sliver
    } else if post_residual < 20 {
        score += 40.0;
    }

    // If the lookahead item could exactly fill this bin's post_residual,
    // strongly reward (chained perfect fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Penalize if post_residual is just barely too small for the next item
    // (near-miss dead space).
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        let gap = (next_item_size - post_residual) as f64;
        if gap <= 10.0 {
            score += 25.0 * (1.0 - gap / 10.0);
        }
    }

    // Reward tight fits proportionally.
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness;

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // new/empty bins unless the fit is excellent.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost grows with open bins and stream progress.
        score += 45.0 + 8.0 * open_bins_count as f64 + 30.0 * progress;
        // Allow a new bin if the item is huge relative to typical residuals.
        if item_size as f64 > mean_residual + 25.0 {
            score -= 50.0;
        }
    } else {
        // Mild reward for using bins below mean residual (consolidation).
        if (bin_residual as f64) > mean_residual {
            score -= 5.0;
        }
        score += 2.0 * open_bins_count as f64 * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let lookahead_tight = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 12.0 * lookahead_tight * lookahead_tight;
        } else {
            // Next item cannot use post_residual: penalize dead space relative to mean residual.
            let dead = post_residual as f64;
            let mean_dead = if mean_residual > 0.0 { dead / mean_residual } else { 1.0 };
            score += 6.0 * mean_dead.min(4.0);
        }
    }

    // Compare against mean residual: bins with smaller residual than mean are more valuable to fill.
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        score += 3.0 * (rel - 1.0);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild pressure to close out bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * tightness;

    // Penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0; // fresh bin perfectly prepped for next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it, otherwise the item forces a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.1 * next_item_size as f64;
        } else {
            // Penalize leaving residuals that are too small for the next item (dead space).
            score += 0.15 * (post_residual as f64).min(next_item_size as f64);
        }
    }

    // Penalize dumping small items into large-residual bins (save big space for big items).
    let size_ratio = item_size as f64 / bin_capacity as f64;
    let res_ratio = bin_residual as f64 / bin_capacity as f64;
    if size_ratio < res_ratio * 0.5 {
        score += 8.0 * (res_ratio - size_ratio);
    }

    // Prefer bins whose residual is close to the item (relative tightness).
    score += 0.3 * ((bin_residual as f64 - item_size as f64) / bin_capacity as f64).abs();

    // Global state coupling: with many open bins, prefer filling existing ones;
    // when few bins are open, opening new bins is cheaper.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when stream is late or many bins open.
        score += 20.0 + 15.0 * t + 0.5 * open_pressure;
        // But if no open bin fits well (large post residual everywhere), new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    } else {
        // Existing bin: reward filling it, more so late in the stream.
        score -= 5.0 + 5.0 * t - 0.1 * open_bins_count as f64;
    }

    // Prefer bins below mean residual (keep residual distribution balanced).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic waste penalty, sharpened as stream progresses
    let mut score = pr * (1.0 + progress * norm_pr * 2.0);

    // Strong reward for tight fits (post_residual near zero)
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * cap * (0.5 + progress);

    // Penalize post_residual that cannot fit the next item (dead space)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx && pr > 0.0 {
            score += nx * (1.0 - pr / nx) * (0.5 + progress);
        } else if pr >= nx {
            // reward leaving space usable by the lookahead item
            score -= (pr - nx) / cap * 10.0 * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= cap as f64 * (0.6 + 0.4 * progress);
    }

    // When many bins fit the item, prefer the one with least residual waste
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64).ln() * 2.0;
        score -= mean_residual / cap * 5.0;
    }

    // New-bin candidate: mild default penalty, relaxed early when few bins open
    if bin_residual == bin_capacity {
        let open_bonus = (open_bins_count as f64).ln().max(0.0);
        score = cap * (0.35 + 0.35 * progress) + open_bonus * 8.0;
        // Opening a bin early is cheap; late opening is expensive unless waste is high
        if progress < 0.3 && open_bins_count < 4 {
            score -= 15.0;
        }
    }

    // Smooth coupling: penalize bins whose residual deviates from mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * 20.0 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= bin_capacity as f64 * 10.0;
    }

    // Harmonic class of post_residual: prefer residuals that stay "usable"
    let capacity = bin_capacity as f64;
    let half = capacity / 2.0;
    let third = capacity / 3.0;
    let quarter = capacity / 4.0;

    // Dead-space penalty for residuals below smallest plausible item (1..100 range)
    if post_residual > 0 && post_residual < 10 {
        score += capacity as f64 * 3.0;
    }

    // Classify post_residual into harmonic bands: (0, (0,10), [10,25), [25,33), [33,50), [50,100])
    let post_f = post_residual as f64;
    if post_f >= half {
        score -= 15.0; // still very usable
    } else if post_f >= third {
        score -= 8.0;
    } else if post_f >= quarter {
        score -= 3.0;
    } else if post_f > 0.0 {
        score += 5.0; // narrow sliver
    }

    // Lookahead: strongly favor bins whose post_residual matches next item size class
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_f - next).abs() < 1.0 {
            score -= 40.0;
        } else if post_f >= next && post_f - next <= 10.0 {
            score -= 20.0; // next item fits snugly
        } else if post_f < next {
            // next item won't fit here; penalize proportionally to wasted potential
            score += (next - post_f).min(capacity) * 0.3;
        }
        // harmonic class match: post_residual and next_item in same quarter-band
        let band = |x: f64| (x / quarter).floor();
        if band(post_f) == band(next) && post_f >= next {
            score -= 6.0;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fitting one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: mildly discourage unless current bins are fragmented
    if bin_residual == bin_capacity {
        score += 12.0
            - (mean_residual / capacity) * 10.0
            - (open_bins_count as f64).min(20.0) * 0.3;
    } else {
        // prefer tighter bins: reward small bin_residual relative to item
        score += (bin_residual as f64 - item_size as f64) * 0.05;
    }

    // Progress-aware: later in stream, be greedier about perfect fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (0 < post_residual < 10)
    // are the worst outcome; make them maximally unattractive.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * fill_ratio;

    // Penalize wasting a bin on an item much smaller than the residual
    // (large leftover that is still usable is mild; medium leftover worse).
    let leftover_ratio = post_residual as f64 / bin_capacity as f64;
    if leftover_ratio > 0.0 && leftover_ratio < 0.5 {
        score += 20.0 * (0.5 - leftover_ratio);
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // next item cannot use the leftover: dead space penalty
            score += 8.0;
        }
    }

    // Open-bin pressure: discourage opening new bins when good fits exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 2.0 * open_bins_count as f64;
        // But if this bin is the only one that fits the item elsewhere is scarce,
        // relieve pressure slightly.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
        // Late in stream, opening a fresh bin is less costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    } else {
        // Existing bin usage mildly rewarded, more so under many open bins.
        score -= 3.0 + open_bins_count as f64;
        // Last-chance bin: strongly favor using it to avoid opening a new one.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers that create fragmented capacity.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        let diff = (pr - ni).abs();
        if diff < 0.5 {
            score -= 30.0; // exact fit for the lookahead item
        } else if pr >= ni && pr - ni <= 10.0 {
            score -= 15.0; // near-perfect match
        } else if pr < ni {
            // lookahead item won't fit here; residual becomes dead space risk
            score += 5.0 + (ni - pr) * 0.1;
        }
    } else {
        // last item: minimize wasted residual aggressively
        score += (post_residual as f64) * 0.5;
    }

    // Reward bins tighter than the mean residual (compact packing).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Slight preference for early stream to keep bins open (flexibility),
    // late stream to consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 2.0 - progress * 2.0;

    // Discard tiny unusable residuals.
    if post_residual < 5 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: near-exact fills are highly desirable.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * (1.0 - tight * 4.0).max(0.0); // strong reward when post_residual < 25% of capacity

    // Lookahead: reward bins whose leftover can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 4.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // leftover dead for the next item: penalize proportionally to how badly it fails
            score += 3.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Prefer bins with below-average residual (concentrate emptiness, keep flexible bins open).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.15 * dev;

    // Mild penalty for wasting a very large residual on a small item.
    if (item_size as f64) < 0.35 * (bin_residual as f64) {
        score += 4.0;
    }

    // New-bin candidate: make it attractive only when the item is large relative to capacity
    // (poor fit anywhere) or very late in the stream when opening fresh bins is cheap.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let largeness = item_size as f64 / bin_capacity as f64;
        score -= 5.0 * largeness + 3.0 * progress;
    }

    // Slight preference for fewer open bins early on.
    score += 0.02 * open_bins_count as f64 * (1.0 - step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: dead space that cannot fit typical items is worse.
    let unusable = (post / cap).powi(3);
    score += 40.0 * unusable;

    // Reward tight fits (small post_residual) with smooth saturating term.
    score -= (cap / (1.0 + post)) * 0.5;

    // Lookahead coupling: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let snug = 1.0 - ((post - nxt) / cap).powi(2);
            score -= 8.0 * snug.max(0.0);
        } else {
            // Penalize blocking the next item slightly, scaled by overflow size.
            score += 3.0 * ((nxt - post) / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Stream-progress polynomial coupling: late in stream, consolidate more aggressively.
    let p = progress * progress;
    score -= 10.0 * p * (1.0 - post / cap);
    score += 6.0 * p * (post / cap);

    // Prefer filling bins with residual close to mean residual (balance open bins).
    score += 0.15 * (post - mean_residual).abs();

    // Mild penalty for opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 5.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let pr = post_residual;
    let class_weight = match pr {
        0 => -60.0,                                  // perfect fit
        1..=5 => -35.0,                              // near-perfect
        6..=15 => -12.0,                             // small dead space
        16..=30 => 6.0,                              // medium waste
        31..=50 => 14.0,                             // large waste
        _ => 20.0,                                   // mostly empty bin used badly
    };
    score += class_weight;

    // Integer-division harmonic classes on post_residual (buckets of 10).
    let bucket = pr / 10;
    score += (bucket as f64) * 2.5;

    // Reward tight fits: fraction of capacity consumed by this item.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // Lookahead coupling: penalize leaving residual too small for next item,
    // reward residual that can host next_item_size.
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 8.0;                            // chain placement possible
            let slack = (pr - next_item_size) as f64;
            score += 0.15 * slack;                   // prefer just-enough residual
        } else {
            score += 5.0;                            // next item won't fit here
        }
        // Harmonic check: next_item divisible-fit classes
        if next_item_size % 10 == 0 && pr >= next_item_size {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin is good.
    if bin_residual == bin_capacity {
        score += 45.0;                               // default penalty for new bin
        if fitting_bins_count == 0 {
            score -= 100.0;                          // forced new bin
        } else if next_item_size > 0 && next_item_size > bin_residual - item_size {
            // poor fit ahead: opening fresh bin can be fine
            score -= 20.0;
        }
        // Late in stream, fewer open bins: slight new-bin discount
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress * (1.0 - (open_bins_count as f64 / 10.0).min(1.0));
    }

    // Mild pressure to prefer bins with less residual among equals.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual below the minimum item size (1..100
    // interface, but small gaps < ~10 are almost always unusable) are heavily penalized.
    let dead_threshold = 12.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        score += (dead_threshold - pr) * 8.0; // unusable sliver penalty
    }

    // Reward tight fits: small post_residual relative to item size.
    let tightness = pr / (item_size as f64 + 1.0);
    score -= 30.0 * (1.0 - tightness.min(1.0));

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another one.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (open_bins_count as f64 * 6.0 + 20.0 * progress);

    // Lookahead coupling: if next item fits into this bin's post_residual,
    // reward placing here (chains items efficiently).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // dead space w.r.t. the known next item
        score += 10.0;
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidate space).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward small post-residual (tight fit) quadratically.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward if next item fits exactly in post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain: this bin will be filled exactly by next item
        } else if next_item_size <= post_residual {
            // partial match: proportional reward for closeness
            let match_ratio = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * match_ratio;
        } else {
            // next item cannot use this residual: penalize dead space relative to next item
            score += 0.15 * ((post_residual as f64 - next_item_size as f64).abs());
        }
    }

    // Relative to mean residual: prefer bins whose post-residual sits below the mean
    // (concentrating slack into few bins keeps other bins usable for large items).
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.1 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when nothing else fits well
    // or residual would be wasted anyway.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64 / bin_capacity as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        } else if next_item_size > 0 && post_residual >= next_item_size && post_residual >= 50 {
            score -= 10.0; // fresh bin has great 2-step potential
        } else {
            score += 30.0 + 50.0 * waste; // discourage opening when decent fits exist
        }
    }

    // Late in stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill of this bin after placement
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Reward tight fits: subtract proportionally to how full the bin becomes
    score -= fill * 25.0;

    // Perfect or near-perfect fit gets a strong bonus
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize dead space that cannot plausibly fit a future item
    // (smallest items are >= 1, but typical granularity ~10)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    // Lookahead coupling: reward if the next item fits exactly in the post residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize proportionally to leftover waste
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.4;
        }
    } else {
        // Last item: waste matters most
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // current fits are poor. Give the empty bin a moderate baseline penalty
    // that shrinks as the stream progresses (late stream: consolidation matters).
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * (1.0 - t);
        // But if no existing bin fits well (post_residual large relative to item),
        // the empty bin becomes attractive: reduce its penalty.
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        if waste_ratio > 0.5 {
            score -= 25.0 * (waste_ratio - 0.5) * 2.0;
        }
        // If many bins are open with slack, discourage yet another bin
        score += open_bins_count as f64 * 1.5;
    } else {
        // Prefer bins with less residual relative to the mean (denser bins first)
        let dev = mean_residual - bin_residual as f64;
        score += dev * 0.3;
        // Slight preference for consolidating into fewer bins late in the stream
        score -= t * 3.0;
    }

    // Mild global pressure: when many bins are open, favor tight placements more
    score -= fill * (open_bins_count as f64).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap;
    let mut score = pr as f64;
    // Smooth polynomial coupling: reward tight fits non-linearly
    score -= 30.0 * (1.0 - x) * (1.0 - x) * (1.0 + progress);
    // Penalize residuals too small to ever be useful again (dead space), smoothly
    let dead = (1.0 - x).max(0.0);
    score += 8.0 * dead * dead * dead;
    // Lookahead: reward residuals that can host the next item, coupled with progress
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 10.0 * (ni / cap) * (1.0 + progress);
        } else {
            score += 5.0 * (1.0 - pr / ni.max(1.0)) * (1.0 - progress);
        }
    }
    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }
    // Mild pressure toward consolidating into fewer bins as stream progresses
    score += 0.05 * (open_bins_count as f64) * progress;
    // New-bin candidate: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - (1.0 - x)) + 10.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Harmonic classes: 0 (perfect), (0,0.1], (0.1,0.2], ... penalized progressively.
    let class = (frac * 10.0).floor() as f64;
    score += class * 4.5;

    // Exact fit is gold.
    if post_residual == 0 {
        score -= 120.0;
    }

    // Small post-residuals create near-perfect packs; reward them super-linearly.
    if post_residual > 0 && post_residual <= 10 {
        score -= 30.0;
    }

    // Penalize residuals that no plausible future item (1..=100) can use well:
    // residual in (50, 80) is "dead-ish" unless it shrinks later.
    if post_residual > 50 && post_residual < 80 {
        score += 18.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
            // Harmonic class of the pair's leftover.
            score += ((slack / bin_capacity as f64 * 10.0).floor()) * 2.0;
        } else {
            // Next item won't fit here; penalize by how much it overshoots modulo classes.
            let over = (next_item_size - post_residual) as f64;
            score += (over / 20.0).floor() * 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 55.0;
    }

    // New-bin candidate handling: opening a new bin wastes mean_residual across open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, scaled by how much space is stranded in open bins.
        score += 35.0 + mean_residual * (open_bins_count as f64) * 0.25;
        // But if no open bin fits at all, opening is inevitable: soften cost.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    } else {
        // Mild reward for keeping bins consolidated when many bins are open.
        score -= (open_bins_count.min(20) as f64) * 0.8;
    }

    // Mean-residual attraction: prefer bins with residual close to item need
    // (tight bins first), i.e. small bin_residual relative to mean is good.
    let tightness = (bin_residual as f64 - mean_residual).abs();
    score += tightness * 0.15;

    // Modulo-style harmonic penalty on post_residual classes (odd classes slightly worse).
    if post_residual % 20 >= 10 && post_residual > 0 {
        score += 2.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any plausible item are wasted.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item {
        score += 1000.0;
    }
    // Penalize small unusable gaps (< 10, the historic minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + 2.0 * (10 - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Penalize if post_residual cannot accommodate the next item (lookahead)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage scattering across many bins
    score += 1.5 * open_bins_count as f64;

    // New-bin candidate handling: mildly discourage opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    // Progress-based mild scaling of dead-space penalty
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but weight relative to mean residual.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // 2-step lookahead: reward if the next item fits exactly in the leftover.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            // leftover after hypothetical next placement: tighter is better
            let second_left = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - second_left / bin_capacity as f64);
        } else {
            // next item won't fit: penalize dead space proportional to gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is very poor
    // (large post_residual waste) or no good chain exists.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        // A fresh bin's "waste" is the whole empty remainder; discourage unless
        // item is large (good long-term use) or many bins are already open.
        score = waste * 0.9 + 10.0 - 0.1 * item_size as f64;
        if open_bins_count > 6 {
            score -= 8.0;
        }
        // If next item is small, fresh bin can absorb it too
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Progression: slightly more conservative (tighter packing) later in stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward low post_residual non-linearly.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Reward near-perfect fills.
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 25.0;
    }

    // Penalize residual that is unlikely to be usable by typical items (1..100).
    // Residuals just below common item sizes create dead space.
    if post_residual >= 1 && post_residual < 10 {
        score += 30.0; // very small residual is dead space unless it closes the bin
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Compare against mean residual: bins with above-mean residual are better
    // candidates for this item (preserve tight bins).
    if bin_residual as f64 > mean_residual {
        score -= 8.0;
    } else {
        score += 5.0;
    }

    // Dynamic time horizon: early in the stream, be more conservative about
    // fragmenting bins (long stream ahead needs flexible residuals); later,
    // prioritize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0 * tightness;
    score -= progress * 15.0 * (1.0 - tightness);

    // Many open bins: encourage consolidation into existing bins.
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate: penalize opening a new bin unless item is large relative
    // to capacity or no good existing option (handled via fitting_bins_count==0
    // context where open bins that fit don't exist and this call wins naturally).
    if bin_residual == bin_capacity {
        let base_penalty = 35.0;
        // If the item is small, opening a new bin wastes capacity.
        let size_ratio = item_size as f64 / bin_capacity as f64;
        score += base_penalty * (1.0 - size_ratio * 0.7);
        // But if the item is huge and nothing fits well, new bin is fine.
        if item_size >= 70 {
            score -= 20.0;
        }
        // Late in stream, opening new bins is more acceptable.
        score -= progress * 20.0;
        // If next item is large and won't fit anywhere soon, fresh bin is useful.
        if next_item_size > 60 && next_item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += (1.0 + 2.0 * progress + 3.0 * p2 + 1.5 * p3) * norm_pr * 12.0;

    // Penalize large dead space relative to mean residual (smooth quadratic)
    let d = norm_pr - mean_residual / cap;
    score += 8.0 * d * d * cap * (0.5 + progress);

    // Reward tight fits with smooth inverse term
    let fit_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_frac * fit_frac * (1.0 + progress);

    // Lookahead: reward leaving room for the next item (smooth coupling)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 6.0 * (gap / cap) * (1.0 + 2.0 * p2);
        } else {
            score += 4.0 * (-gap / cap) * (1.0 + progress);
        }
    }

    // Last-chance bin: strong smooth reward
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + 3.0 * progress);
    }

    // Mild penalty for opening a new bin late in the stream
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 + 4.0 * p2 + 2.0 * p3);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit classes are highly desirable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 10.0;
    } else if pr <= 20 {
        score += 5.0;
    } else {
        score += (pr as f64) * 0.35;
    }

    // Modulo classes: residuals in multiples of 10 are more reusable
    // (items are coarse-grained), reward them.
    let m = pr % 10;
    if m == 0 && pr > 0 {
        score -= 8.0;
    } else if m >= 7 {
        score += 6.0; // awkward sliver class
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Reward proportional to how tightly the next item fits.
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // Penalize leaving residual that wastes the lookahead item.
            score += 4.0 + 0.05 * (next_item_size as f64);
        }
    } else {
        // Last item: prefer tight fits anywhere.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: neutral-ish score so it wins only
    // when open bins all look bad.
    if bin_residual == bin_capacity {
        score = 45.0 + 0.1 * (open_bins_count as f64);
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 / 2 {
            score -= 10.0; // big next item: fresh bin is valuable
        }
    }

    // Late-stream tightening: as stream progresses, prefer compacting.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are pure waste; penalize heavily.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    } else {
        // Large, reusable residuals are valuable: reward them.
        score -= 0.10 * (post_residual as f64 - 30.0);
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: strongly favor bins whose post_residual matches the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            let gap = post_residual as f64 - nxt;
            if gap < 10.0 {
                score -= 15.0; // next item can seal this bin almost perfectly
            } else {
                score -= 5.0 * (1.0 - gap / 80.0);
            }
        } else {
            // post_residual cannot host the next item: mild penalty scaled
            // by how much space is stranded.
            score += 0.08 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is truly terrible (large dead space).
    if fitting_bins_count == 1 && post_residual >= 0 {
        score -= 18.0;
        if post_residual < 10 {
            score -= 5.0; // still fine, seals the bin
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones rather than spawning more; also compare against mean.
    score += 0.6 * open_bins_count as f64;
    if (post_residual as f64) > mean_residual {
        score += 0.15 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.15 * (mean_residual - post_residual as f64);
    }

    // New-bin candidate (pristine empty bin): only attractive when the item
    // would leave a large, versatile residual AND few bins are open; otherwise
    // discourage spreading.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if open_bins_count <= 2 && post_residual >= 60 {
            score -= 10.0 - 5.0 * progress;
        } else {
            score += 20.0 + 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Strong reward for tight match to the next item (post_residual == next_item_size).
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64)).powi(8);
        // Extra bonus for an exact match.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize residuals slightly below the next item (dead space next step).
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size.max(1) as f64);
        }
    } else {
        // Last item: just minimize wasted space.
        score -= 20.0;
    }

    // Compare post_residual against the mean residual of open bins:
    // leaving more than average slack is wasteful; leaving less is efficient.
    let pr = post_residual as f64;
    if pr > mean_residual {
        score += 0.8 * (pr - mean_residual);
    } else {
        score -= 0.4 * (mean_residual - pr);
    }

    // Tight fit reward: small post_residual relative to capacity.
    score -= 30.0 * (1.0 - pr / bin_capacity as f64).powi(3);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // If next item fits perfectly into this new bin's future residual, opening is attractive.
        let newbin_bonus = if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64) == 0 {
            -50.0
        } else {
            0.0
        };
        score = 55.0 + 20.0 * (1.0 - progress) + newbin_bonus;
        // Discourage new bins when many open bins already fit the item.
        score += 10.0 * fitting_bins_count as f64;
    }

    // Mild penalty for too many open bins (fragmentation control).
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect packing.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Lookahead: if the next item exactly fills the post residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 300.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mildly reward, scaled by how well it fills.
        let fill = next_item_size as f64 / post_residual as f64;
        score -= 60.0 * fill;
    } else if next_item_size > post_residual {
        // Next item cannot use the residual: penalize dead space proportionally.
        score += 0.5 * (post_residual as f64 - mean_residual).abs();
    }

    // Last chance: only this bin fits the item — strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 500.0;
    }

    // Penalize bins whose residual is much larger than mean (poor consolidation),
    // reward bins tighter than the mean residual.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Discourage opening a new bin when good fitting bins exist, unless
    // the item is large and residual fragmentation is high.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New-bin candidate: penalize early, allow later when bins are crowded.
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 150.0 - 100.0 * progress - 5.0 * crowding;
        // If item is big relative to capacity, fresh bin is more attractive.
        score -= 0.5 * item_size as f64;
    }

    // Small global pressure: prefer using existing bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress;

    // Mild nonlinearity on post residual to prefer mid-range leftovers
    // (residuals around 10-30 can host future mid-size items).
    let pr = post_residual as f64;
    score += 0.02 * (pr - 20.0) * (pr - 20.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_it = it / cap;

    // Smooth polynomial core: reward small post_residual, quadratically.
    let mut score = norm_pr * norm_pr * 40.0 + norm_pr * 10.0;

    // Non-linear coupling of post_residual with stream progress:
    // late in the stream, dead space matters more.
    score += norm_pr * norm_pr * (progress * progress) * 60.0;
    score -= progress * 5.0;

    // Reward good fit relative to mean residual state.
    score -= (norm_pr - mean_residual / cap).abs() * 4.0;

    // Next-item lookahead coupling: bonus if this post_residual can host next item.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 + (next_item_size as f64 / cap) * 8.0;
    } else if next_item_size > 0 {
        score += norm_pr * 3.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Mild penalty for proliferating bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // New-bin candidate: penalize slightly unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 3.0 + norm_it * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (harmonic residual classes: 0, 5, 10, 20)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    } else {
        // Penalize large dead space quadratically
        score += (post_residual as f64 - 20.0) * 0.35;
    }

    // Harmonic class: post_residual divisible by small moduli tends to stay usable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits the post_residual exactly, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post <= 10 {
                score -= 18.0;
            }
        } else {
            // next item cannot use this residual; penalize wasting a good bin
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Last-resort bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 30 && fitting_bins_count <= 1;
        if poor_fit {
            score -= 55.0; // better to open fresh bin than cram
        } else {
            score += 40.0 + 2.0 * open_bins_count as f64; // prefer reusing open bins
        }
    }

    // Mild preference for filling bins with low mean residual (tight packing state)
    score -= (mean_residual / bin_capacity as f64) * 4.0;

    // Slight late-stream conservatism: reuse bins more aggressively as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space penalty: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    } else if post_residual < 30 {
        score += 3.0;
    } else {
        // Larger usable residuals are mildly rewarded relative to raw value.
        score -= 2.0;
    }

    // Reward tight fits (post_residual close to zero but not a dead gap).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize opening a new bin when existing bins fit, unless it's a last-chance fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 10.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening extra bins.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // Open bins pressure: more open bins -> penalize spreading, favor consolidation.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0;
        if post_residual as u32 == next_item_size {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual as u32 {
        // Next item won't fit here; penalize leaving residual that blocks it.
        score += 4.0;
    }

    // Progress coupling: later in stream, be slightly more conservative with residuals.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mean residual alignment: prefer bins whose residual is near the mean (balanced use).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Leftover can hold the next item with slack; reward proportionally to tightness.
        let tightness = next_item_size as f64 / post_residual as f64;
        score -= 40.0 * tightness;
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space: leftover too small for the next item — penalize hard.
        score += 35.0 * (1.0 - post_residual as f64 / (next_item_size as f64).max(1.0));
    }

    // Bonus when this bin is the last chance to fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer placing into bins whose residual is already below mean (consolidating waste).
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Penalize creating tiny unusable residuals (< 10% capacity).
    if post_residual > 0 && post_residual < bin_capacity / 10 {
        score += 20.0;
    }

    // Early in the stream, be more willing to open/keep bins flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no open bin gives a good fit.
        score += 10.0 + 15.0 * progress;
        if post_residual - item_size as u32 == 0 {
            score -= 5.0;
        }
    }

    // Mild penalty for over-using many open bins late in stream.
    score += 0.3 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tight fit reward: quadratic decay of dead space
    let tightness = 1.0 - (post / cap);
    score -= 2.5 * tightness * tightness * cap;

    // Penalize small-but-unusable residuals (< 10 typical min item)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post >= ni {
            // next item fits here afterwards -> chain bonus scaled by match quality
            let gap = (post - ni) / cap;
            score -= 3.0 * (1.0 - gap);
        } else {
            // next item won't fit in residual -> mild penalty, worse if residual tiny
            score += 1.5 * (1.0 - post / cap);
        }
    }

    // Global state coupling: many open bins with high mean residual -> prefer consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    if mean_residual > 0.0 {
        let spread = (bin_residual as f64 - mean_residual).abs() / cap;
        score += 1.0 * spread * (1.0 + progress);
        if open_bins_count > 4 && bin_residual as f64 > mean_residual {
            score += 0.5 * (open_bins_count as f64).ln();
        }
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // and when other bins fit; allow it early or when nothing else fits well.
    if bin_residual == bin_capacity {
        let base = 8.0 + 6.0 * progress;
        let escape = if fitting_bins_count == 0 { -10.0 } else { 0.0 };
        score += base + escape;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let cap = bin_capacity as f64;

    let mut score = pr;

    // Tightness reward: smooth non-linear coupling of fit quality with progress.
    let tightness = 1.0 - pr / cap;
    score -= tightness * tightness * (1.0 + progress) * 12.0;

    // Penalize residual that is small but not zero (dead space), smooth quartic term.
    if pr > 0.0 {
        let dead = pr / cap;
        score += dead * (1.0 - dead) * (1.0 - dead) * 8.0;
    }

    // Lookahead: reward residual that can host the next item.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            let gap = pr - ns;
            score -= (1.0 - gap / cap) * 10.0 * (1.0 - progress * 0.5);
        } else {
            score += (ns - pr) / cap * 6.0;
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize opening a new bin, more so as stream progresses
    // and when alternatives exist; soften slightly early when bins are few.
    if bin_residual == bin_capacity {
        let alternative_pressure = if fitting_bins_count > 0 { 1.0 } else { 0.0 };
        score += 30.0 + 40.0 * progress + 10.0 * alternative_pressure
                 - 5.0 * (1.0 / (1.0 + open_bins_count as f64));
    } else {
        // Mild dispersion penalty: prefer bins with residual below mean (denser bins).
        score += (br - mean_residual) * 0.05;
        // Slight preference to fill existing bins rather than spreading.
        score += 0.02 * open_bins_count as f64 * (1.0 - tightness);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward small, well-structured leftovers.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Integer-division harmonic classes on post_residual (capacity fractions).
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    if post_residual == 0 {
        score -= 40.0; // perfect fit
    } else if post_residual <= eighth {
        score -= 18.0;
    } else if post_residual <= quarter {
        score -= 8.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 2.0;
    } else {
        score += 6.0; // large dead space
    }

    // Modulo-based dead-zone penalty: residuals that no common item class (1..100)
    // can use well. Penalize residuals in awkward bands (e.g. 51..59 style gaps).
    let m = post_residual % 10;
    if post_residual > 0 && m > 0 && m < 5 {
        score += (5 - m) as f64 * 1.5; // ragged low-class remainder
    }

    // Lookahead: if next item can still fit in post_residual, reward; if next item
    // is blocked by this placement, penalize (unless post_residual is tiny anyway).
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 10.0;
        } else if pr > 0.0 && (next_item_size as u32) > post_residual && post_residual < eighth {
            // blocking a usable residual is fine since it was tiny
            score += 0.0;
        } else if pr > 0.0 && (next_item_size as u32) > post_residual {
            score += 4.0; // this placement strands the next item
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when all open bins fit poorly.
    if bin_residual == bin_capacity {
        let mut penalty = 12.0;
        if fitting_bins_count == 0 {
            penalty = -30.0;
        } else if fitting_bins_count == 1 {
            penalty = 0.0;
        }
        // Few open bins => prefer filling existing ones first.
        penalty += (open_bins_count as f64).sqrt() * 2.0;
        score += penalty;
    }

    // Mild pressure to pack tighter as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first).
    score -= (mean_residual - bin_residual as f64).max(-10.0).min(10.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small for the smallest plausible future item.
    let min_item = 1u32;
    if post_residual < min_item.max(next_item_size.min(10)) {
        // gap below next item's need (or tiny gap): strong penalty
        score += 60.0;
    }
    // Dead zone: residuals in (0, 10) can never fit any item -> treat as wasted
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Reward tight fits (small post_residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // If this bin can fit the next item too, reward the chain.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 {
        // would force next item elsewhere: mild penalty
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above mean residual usage;
        // penalize more when many bins are open or late in the stream.
        score += 20.0 + 3.0 * open_bins_count as f64 + 25.0 * progress;
        // Opening a new bin is acceptable if all fits are terrible
        // (i.e., would leave large dead space) - handled by comparisons elsewhere.
        if post_residual as f64 > mean_residual + 30.0 {
            score -= 10.0;
        }
    } else {
        // Existing bin: mild bonus when open_bins_count is high.
        score -= 0.5 * open_bins_count as f64;
    }

    // Coupling: prefer bins whose residual is near mean (balanced packing)
    // when many bins are open.
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.1 * dev * (open_bins_count.min(20) as f64) / 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when the post-residual exactly matches
    // the next item, or when the next item can still fit afterwards.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 30.0; // perfect chain: this bin will be exactly consumed next step
        } else if post_residual >= next_item_size {
            score -= 8.0; // chainable placement
            let chain_waste = post_residual as f64 - nxt;
            score -= 6.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // next item cannot follow: dead space unless residual is tiny
            score += 5.0;
        }
    }

    // Penalize creating small unusable slivers (dead space 1..=9).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Reward placements below mean residual pressure (bin is already loose).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when no open bin
    // fits well (post_residual would be large relative to capacity) or bins are scarce.
    if bin_residual == bin_capacity {
        let good_alternative_exists = fitting_bins_count > 0 && (mean_residual - item_size as f64).abs() < 15.0;
        if good_alternative_exists {
            score += 25.0; // keep using existing bins
        } else {
            score -= 10.0; // poor fits everywhere: fresh bin is fine
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        score += 2.0 * open_bins_count as f64;
    }

    // Mild preference for bins with more slack overall (keeps tight bins for tight items).
    score += 0.05 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = fitting_bins_count as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tight = item_size as f64 / cap;
    let mut score = post;

    // Reward tight fits: post_residual small relative to capacity
    score -= 0.9 * cap * (1.0 - post / cap).powi(6);

    // Penalize large dead space that nothing typical can use
    if post > 0.0 && post < 10.0 {
        score -= 15.0; // near-perfect fill bonus
    }
    if post > 0.0 && post < 20.0 {
        score += (20.0 - post) * 0.05; // slight gradient toward fuller
    }

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 * (1.0 + tight);
    }

    // New-bin candidate: penalize opening a bin unless no good alternative
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { (fit - 1.0).max(0.0) };
        score += 55.0 * (1.0 - scarcity.max(0.0)) + 10.0 * scarcity.min(1.0);
        // allow opening when residual space in open bins is fragmented/high
        score -= 0.2 * mean_residual.min(cap);
    }

    // Lookahead: if next item fits the post-residual, reward leaving that gap
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            score -= 12.0 * (1.0 - (nx / cap).abs() - post / cap * 0.5).abs();
        } else if post > 0.0 && nx > post && nx - post <= 15.0 {
            score += 8.0; // near-miss gap is wasted for next item
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap - post / cap).abs();

    // Time horizon: early on, be conservative; late, squeeze harder
    score -= (1.0 - progress) * 3.0 + progress * post * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic penalty on leftover space, modulated by stream progress.
    let mut score = pr as f64;
    score += 0.5 * cap * x * x * (0.5 + 0.5 * progress);

    // Reward tight fits: post residual near zero gets a strong subtraction.
    score -= 2.0 * cap * (1.0 - x) * (1.0 - x) * (1.0 - x) * (0.3 + 0.7 * progress);

    // Penalize leaving residual close to small upcoming items (dead space coupling).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs();
        score -= 1.5 * (n / cap) * (1.0 - gap / cap).max(0.0);
        // If next item exactly fits remaining space, strongly favor this bin.
        if gap < 1.0 {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 4.0 + 2.0 * progress;
    }

    // Mild penalty when many bins are open and this placement is wasteful.
    let waste = (pr as i64 - mean_residual as i64) as f64;
    score += 0.05 * (open_bins_count as f64).sqrt() * waste.max(0.0);

    // New-bin candidate: neutral baseline with slight progress-dependent cost.
    if bin_residual == bin_capacity {
        score = cap * (0.35 + 0.25 * progress) - 0.1 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
