pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum item (1..=100, min item 1)
    // become "dead" unless they can host the lookahead item. Penalize hard.
    let dead = post_residual > 0 && post_residual < item_size.min(100);
    if dead {
        let useless_for_next = next_item_size == 0 || post_residual < next_item_size;
        if useless_for_next {
            score += 40.0 + (post_residual as f64) * 0.5;
        } else {
            score += 8.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit reward: post_residual small but usable
    if post_residual > 0 && post_residual <= 20 {
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual as i64 - next_item_size as i64).abs();
        if gap <= 5 {
            score -= 15.0;
        }
        score -= gap as f64 * 0.05;
    } else if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open,
    // encourage consolidation when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if new_bin {
        score += 12.0 + open_bins_count as f64 * 2.0 + progress * 10.0;
        // But allow new bin if no open bin fits well
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && !new_bin {
        score -= 20.0;
    }

    // Deviation from mean residual: prefer bins whose residual is close to item need
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual matches next item exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (-diff / 20.0).exp();          // strong reward for perfect follow-up fit
        if post_residual == next_item_size {
            score -= 50.0;                              // exact match bonus
        }
        // Penalize leaving a gap that neither the next item nor small items can use
        if post_residual < next_item_size {
            score += 0.4 * (next_item_size - post_residual) as f64;
        }
    } else {
        score -= 10.0; // last item: just fill anything
    }

    // Penalize dead space relative to the mean residual of open bins
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current fit is poor (large post_residual)
    if bin_residual == bin_capacity {
        score = 55.0 + 0.6 * post_residual as f64;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0; // fresh bin can host the next item too
        }
        if fitting_bins_count <= 1 {
            score -= 70.0; // no good existing option -> open new bin
        }
    }

    // Slight preference to keep fewer open bins as stream progresses
    score += 0.02 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
