    score -= 14.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward heavily; if next item cannot fit in post residual but could fit
    // elsewhere, mild penalty for blocking.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 22.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            score += 0.02 * (next_item_size - post_residual) as f64;
        }
    }

    // Global state: many open bins with high mean residual -> discourage
    // spreading; prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let spread_pressure = (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
    score += 4.0 * spread_pressure * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize opening a new bin unless residuals across
    // open bins are nearly exhausted or the fit here is terrible.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        let avg_usable = mean_residual / bin_capacity as f64;
        score += 20.0 - 10.0 * fit_quality;
        if avg_usable < 0.15 {
            score -= 15.0; // open bins nearly full -> new bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 25.0; // nothing else fits, new bin mandatory
        }
    }

    // Slight time-decay preference for consolidation early, exploration late.
    score -= (1.0 - progress) * 2.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Non-linear coupling: penalize large post_residual more strongly as stream progresses
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    score += progress * pr_norm * pr_norm * cap * 0.8;

    // Reward tight fits (small post_residual) smoothly via cubic decay
    score -= (1.0 - pr_norm).powi(3) * 6.0;

    // Dead-space penalty if post_residual can't fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (0.6 + 0.8 * progress);
        } else {
            // smooth reward for bins that can also host the next item
            score -= (1.0 - pr / cap) * 2.0;
        }
    }

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Slight preference for bins below mean residual (consolidation)
    score += (pr - mean_residual) * 0.15 * (0.5 + progress);

    // New-bin candidate: penalize opening new bins mildly, more early, less late
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: group residuals into capacity-fraction classes.
    // Classes: [0..=10] near-perfect, (10..=25] small, (25..=50] half-class, (50..] large waste.
    let pr = post_residual;
    if pr == 0 {
        score -= 200.0; // perfect fit, ideal
    } else if pr <= 10 {
        score -= 120.0; // near-perfect: dead space unusable by any item (min size 1..10)
    } else if pr <= 25 {
        score -= 60.0;
    } else if pr <= 50 {
        score -= 20.0;
    } else {
        score += 15.0; // large residual: bin still very reusable, but wasteful now
    }

    // Integer-division harmonic classes of post_residual by 10 (item granularity hint)
    let class = pr / 10;
    score -= match class {
        0 => 40.0,
        1 => 25.0,
        2 => 10.0,
        3 => 0.0,
        4 => -5.0,
        _ => -10.0,
    } as f64;

    // Modulo coupling: residual divisible by small sizes is more reusable
    if pr > 0 && (pr % 10 == 0 || pr % 5 == 0) {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 150.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this residual: mild penalty proportional to overshoot
            score += ((next_item_size - pr) as f64) * 0.3;
        }
    }

    // Last-chance bin: only one open bin fits -> avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // and there are already many open bins with scattered residuals.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) > mean_residual.max(1.0) * 0.5;
        if poor_fit && open_bins_count > 2 {
            score -= 30.0 + 40.0 * progress;
        } else {
            score += 120.0; // prefer filling existing bins early
        }
    }

    // Prefer bins whose residual is close to item_size (tight packing)
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.1;

    // Slight preference for bins below mean residual (fill emptier-of-space bins first)
    score += ((mean_residual - bin_residual as f64) * 0.05).max(-20.0).min(20.0);

    // Late in stream: consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 30.0 * progress * (pr <= 20) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Penalize residuals that no known item size (1..=100) can ever use well.
    if post_residual > 0 && post_residual < 5 {
        score += 40.0;
    }

    // Reward tight fits: exact or near-exact fills.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 8.0;
    }

    // Lookahead coupling: if the next item fits into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
        // Bonus if next item exactly fills the remaining gap.
        if post_residual == next_item_size {
            score -= 6.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot use the gap: mild penalty for wasted space.
        score += 4.0;
    }

    // Open bins pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins fit poorly.
    if bin_residual == bin_capacity {
        score += 12.0 + open_bins_count as f64 * 0.5;
        // If a large item is coming and residuals are tight, opening new bin is less bad.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 8.0;
        }
    } else {
        // Slight preference for bins with residual close to mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Stream progression: late in the stream, avoid opening new bins even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Base waste term: prefer tight fits (small post_residual).
    score += 0.5 * (post / cap) * (post / cap) * cap;

    // 2-step lookahead: reward post_residual that exactly matches next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            // Perfect chain bonus when next item fits exactly.
            score -= 12.0 * (1.0 - gap / cap);
            if gap < 1.0 {
                score -= 25.0;
            }
        } else {
            // Next item cannot follow into this bin: mild penalty scaled by shortfall.
            score += 0.3 * (nxt - post);
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious;
    // dumping into them wastes scarce small residual space.
    let dev = post - mean_residual;
    if dev > 0.0 {
        score += 0.15 * dev;
    } else {
        score += 0.05 * dev; // slight reward for leaving less than average
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Late in the stream, consolidate aggressively to avoid leftover bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post / cap);

    // Prefer filling nearly-full bins over fragmenting fresh ones.
    let fill_ratio = 1.0 - (bin_residual as f64) / cap;
    score -= 4.0 * fill_ratio * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize leaving residuals that no plausible future item can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead space: too small for any item (min size 1 handled below)
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        // residual smaller than current item: hard to reuse
        score += 6.0;
    }

    // Lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else if next_item_size > bin_residual {
            // next item won't fit anywhere in this bin anyway; residual value is lower
            score -= 3.0;
        } else {
            score += 8.0; // blocking the next item is costly
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let poor_fit = (item_size as f64 / bin_capacity as f64).powf(2.0);
        let horizon = step_index as f64 / (total_items.max(1) as f64);
        // Early on, open bins cheaply; late, consolidate
        let new_bin_cost = 100.0 - 40.0 * horizon;
        score = new_bin_cost - pressure * 60.0 - poor_fit * 20.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // fresh bin pairs well with lookahead
        }
        if fitting_bins_count > 0 && mean_residual >= item_size as f64 + 15.0 {
            score += 30.0; // an open bin has comfortable room; don't open new
        }
    }

    // Mild consolidation pressure when many bins are open
    score += 0.02 * open_bins_count as f64;

    // Slight preference to fill bins below mean residual (balance toward fullness)
    score += 0.1 * (mean_residual - post_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr_norm = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post-residual with stream progress
    let poly = pr_norm * pr_norm * (1.0 - pr_norm);
    score += 30.0 * poly * (0.5 + progress);

    // Penalize large residuals late in the stream (wasted capacity)
    score += 20.0 * pr_norm * pr_norm * progress;

    // Reward tight fits (small post-residual) more strongly as stream advances
    score -= 15.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.3 + 0.7 * progress);

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let snug = 1.0 - (pr - nx) / cap;
            score -= 12.0 * snug * snug;
        } else {
            score += 8.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins near the mean (balance)
    score += 3.0 * (pr - mean_residual).abs() / cap;

    // New-bin candidate: penalize slightly so we prefer good fits into open bins
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction bucket does the leftover fall in?
    // Classes: (0..10], (10..25], (25..50], (50..75], (75..100]
    let class = match post_residual {
        0 => 0u32,
        1..=10 => 1,
        11..=25 => 2,
        26..=50 => 3,
        51..=75 => 4,
        _ => 5,
    };

    // Reward tight fits strongly (low classes), penalize mid-range dead space.
    let class_penalty: f64 = match class {
        0 => -30.0,
        1 => -18.0,
        2 => -6.0,
        3 => 6.0,
        4 => 14.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division harmonic: post_residual / 10 gives a coarse "harmonic index".
    // Perfect fits (divisible classes) are more reusable.
    let h_idx = post_residual / 10;
    score -= (h_idx % 3) as f64 * 2.0;

    // Lookahead coupling: does next_item_size fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: future item can use leftover -> big reward.
            score -= 20.0;
            // Extra reward if next item nearly fills the bin completely.
            let after_next = post_residual - next_item_size;
            if after_next <= 10 {
                score -= 10.0;
            } else {
                // Fractional coupling: leftover fraction after next item.
                score += (after_next as f64 / cap) * 15.0;
            }
        } else {
            // Next item cannot use this leftover: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Many options: mild penalty to prefer the tightest via other terms.
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Prefer bins with residual close to item_size (best-fit coupling).
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += tightness * 25.0;

    // Discourage opening new bins when decent open bins exist and stream is mid-flow.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 12.0 + progress * 8.0;
        // If no open bin fits well (post_residual small means great fit elsewhere), new bin is bad.
        if item_size <= post_residual.max(item_size) && post_residual < item_size {
            new_bin_penalty += 10.0;
        }
        // Early stream with few bins: opening new bins is fine.
        if open_bins_count <= 2 && progress < 0.1 {
            new_bin_penalty *= 0.4;
        }
        score += new_bin_penalty;
    }

    // Mild global pressure: keep mean residual low.
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

