    }

    // Lookahead: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins when fit is loose.
    let pressure = (open_bins_count as f64) * 0.15;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits.
    if bin_residual == bin_capacity {
