    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits after this placement: good chaining
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.25 * (next_item_size as f64);
    }
    // Dead space: post residual too small for typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Tight fit reward relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Deviation from mean residual: prefer bins that bring residual toward balance
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize moderately so it's only chosen on poor fits
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    // Late in stream: be more conservative, prefer filling existing bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

