}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize leaving dead space that no plausible item can fill.
    if post_residual > 0 {
        let min_item = 1.0;
        let usable = (post_residual as f64) >= min_item;
        if !usable {
            score += 100.0;
        }
        // Penalize residuals that are awkwardly large but too small for typical items.
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += (10.0 - pr) * 1.5; // dead space under min item size
        }
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 / (1.0 + gap);
        } else {
            // Penalize if next item cannot use the leftover.
            let overflow = (next_item_size - post_residual.min(next_item_size)) as f64;
            score += 0.02 * overflow;
        }
        // Perfect pairing bonus.
        if post_residual == next_item_size {
            score -= 10.0;
        }
        let _ = nxt;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early
    // in the stream and when many bins are open; relax when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let spread = (mean_residual - post_residual as f64).abs();
        score += 15.0 + 10.0 * (1.0 - progress) + 0.3 * open_bins_count as f64;
        score -= poor_fits * 0.0; // base penalty stands; tight-fit terms dominate
        let _ = spread;
        // Opening a bin is more attractive if mean residual across open bins is small
        // (existing bins are nearly full anyway).
        score -= (100.0 - mean_residual).max(0.0) * 0.05;
    } else {
        // Reward using existing bins proportionally to how full they already are.
        let fill = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 3.0 * fill;
    }

    // Mild global pressure: when many bins are open, prefer consolidating into them.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, squeeze remaining bins harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: strongly prefer small post_residual, with non-linear sharpening.
    let x = post / cap;
    let mut score = 100.0 * x + 250.0 * x * x + 400.0 * x * x * x;

    // Smooth stream-progress coupling: later in the stream, waste matters more.
    let urgency = 1.0 + 1.5 * progress * progress;
    score *= urgency;

    // Last-chance bonus: if this is the only bin that fits, strongly reward using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0 + 80.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more when good fits exist
    // and many bins are already open.
    if bin_residual == bin_capacity {
        let fit_pressure = if fitting_bins_count > 1 { 1.0 } else { 0.35 };
        score += 60.0 * fit_pressure + 8.0 * open_bins_count as f64;
    }

    // Lookahead: reward leaving room for the next item via smooth interaction.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let compat = (post - nxt).max(0.0) / cap;
        score -= 60.0 * compat * (1.0 - compat);
        // Penalize leaving residual that is just barely too small for next item (dead space).
        if nxt > post && post > 0.0 {
            score += 30.0 * (nxt - post) / cap;
        }
    }

    // Mild alignment with mean residual: avoid bins deviating far from fleet average.
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual bucketed by capacity fractions.
    let post = post_residual as f64;
    let class = (post / cap * 8.0).floor(); // 0..8 harmonic class of dead space

    // Penalize dead space non-linearly; small leftovers (< 10) are nearly unusable.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 10.0;
    }

    // Reward exact tight fits (harmonic completion).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modulo-10 class coupling: if next item's class matches leftover class, big reward.
    if next_item_size > 0 {
        let next = next_item_size;
        if next <= post_residual {
            // Next item fits: strong reward, scaled by how well classes align.
            score -= 20.0 + 0.5 * (next as f64);
            if post_residual - next < 10 { score -= 15.0; } // would leave near-zero after next
        } else {
            score += 8.0; // leftover can't host the next item
        }
        // Integer division threshold: leftover divisible into next item's harmonic slot
        if post_residual / (next.max(1)) >= 2 {
            score -= 6.0;
        }
    }

    // Prefer bins with low residual (best-fit flavor) among many fitting bins.
    score -= (bin_residual as f64) * 0.15;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate: empty bin. Only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when stream is young or bins are few.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 30.0 + 40.0 * progress;
        if open_bins_count > 8 { open_cost += 20.0; }
        // If mean residual is large, existing bins likely fine; penalize opening.
        if mean_residual > item_size as f64 * 1.5 { open_cost += 15.0; }
        score = open_cost + (item_size as f64); // leftover after placing = cap - item
    }

    // Mild tie-break by harmonic class of post_residual (lower class = less waste).
    score += class * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead_zone: f64 = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 6.0;
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward fits that leave a gap usable by the next item (lookahead coupling).
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 8.0;
    }
    // Penalize if the leftover gap cannot fit the next item but is still sizable.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Open-bin pressure: prefer filling existing bins over opening new ones,
    // stronger pressure when many bins are already open.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if no good existing fit exists.
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 25.0 + 3.0 * (open_bins_count as f64).max(0.0);
        }
    } else if fitting_bins_count == 1 {
        // Last chance: strongly prefer using the only fitting bin.
        score -= 15.0;
    }

    // Slight preference for bins with residual far below mean (filling emptier bins first
    // keeps large residuals concentrated for future large items).
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Mild stream progression: later in stream, be more conservative about opening bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += progress * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-match: next item fits with small waste afterwards
    if next_item_size > 0 && post_residual >= next_item_size {
        let after = post_residual - next_item_size;
        score -= 60.0 - (after as f64).min(60.0);
        score -= 0.5 * (post_residual as f64 - next_item_size as f64).min(20.0);
    }
    // Penalize dead space that next item cannot use
    if next_item_size > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += 0.8 * gap;
    }

    // Prefer bins whose residual is close to the mean (keep residuals balanced)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when item fits poorly everywhere
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual < next_item_size { 1.0 } else { 0.0 };
        score += 250.0 - 300.0 * poor_fit;
        score += 2.0 * open_bins_count as f64;
    }

    // Slight preference to fill bins tighter as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Reward small absolute waste relative to capacity.
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize leaving residuals that are hard to reuse (small leftovers).
    if post_residual > 0 {
        let r = post_residual as f64;
        let awkward = (r < 10.0) as f64 * 15.0
            + (r >= 10.0 && r < 20.0) as f64 * 8.0
            + (r >= 50.0 && r < 60.0) as f64 * 3.0;
        score += awkward;
    }

    // Lookahead: if next item fits the post residual, big reward.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let seq_bonus = 25.0 * (next_item_size as f64 / bin_capacity as f64);
        score -= seq_bonus;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        // Dead-end for the lookahead item: mild penalty.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Many open bins with high mean residual: encourage consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if mean_residual > item_size as f64 * 1.5 && open_bins_count > 2 {
        score -= 5.0 * (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln();
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let base_open = 55.0
            + 20.0 * (open_bins_count as f64).ln().max(0.0)
            + 15.0 * (1.0 - progress);
        // Opening is attractive only if no open bin fits well.
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fit_ratio < 0.85 {
            score -= 10.0;
        }
        score += base_open;
    }

    // Slight time-horizon damping: later in stream, prefer tighter packing.
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = pr;

    // Non-linear penalty on wasted residual (quartic-ish growth for large dead space)
    let norm_pr = pr / cap;
    score += 8.0 * norm_pr * norm_pr * (1.0 + norm_pr * norm_pr);

    // Reward tight fits: small post_residual relative to item size
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Lookahead: reward if next item fits in the post residual (perfect chaining)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            // next item cannot use leftover; penalize proportionally to overshoot
            let over = (nx - pr) / cap;
            score += 5.0 * over;
        }
    }

    // Stream progress coupling: later in stream, be more aggressive about filling bins tightly
    score *= 1.0 - 0.3 * progress * progress;
    // ...but late in the stream, penalize opening/keeping sparse bins more strongly
    score += 4.0 * progress * norm_pr;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, more when many bins are open or residual is high
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64 + 10.0 * (mean_residual / cap);
    }

    // Prefer bins with residuals below mean (compact bins get filled first)
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score += 3.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Harmonic classes: classify post_residual into residue classes mod 10.
    // Small residues in {1..9} are hard to fill later; penalize odd "dead" zones.
    let cls = post_residual % 10;
    match cls {
        0 => score -= 8.0,           // clean decade residual, reusable
        1 | 2 | 3 => score += 6.0,   // nearly unusable sliver
        4 | 5 | 6 => score += 2.0,   // marginal
        7 | 8 | 9 => score += 4.0,   // awkward zone
        _ => {}
    }

    // Lookahead: reward if next item fits the post residual well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_left = post_residual - next_item_size;
        score -= (next_left as f64) * 0.5 + 5.0;
        if next_left == 0 {
            score -= 40.0; // perfect pair with lookahead
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; residual becomes dead space for lookahead.
        score += (next_item_size as f64) * 0.3;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Prefer bins with already-low residual (tight packing among open bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // New-bin candidate (empty bin): only attractive when it beats stuffing a tight bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decays late in stream when many bins open anyway.
        score = (bin_capacity as f64) * (1.0 - 0.2 * progress) + 20.0;
        if fitting_bins_count <= 1 && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // Pairing next item into a fresh bin can be good.
            score -= 30.0;
        }
        if mean_residual > (item_size as f64) * 1.5 {
            score -= 15.0; // open bins are too loose anyway
        }
    }

    // Slight penalty for opening bins when few items remain.
    if bin_residual == bin_capacity && total_items.saturating_sub(step_index) < 3 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (1..=10) are almost surely unusable.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 15.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward leaving room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Open-bin pressure: with many bins open, prefer filling existing ones;
    // but when this is the last fitting bin, strong bonus to use it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }
    score += (open_bins_count as f64) * 1.5;

    // Penalize bins far below mean residual (poor consolidation choice).
    score += 0.3 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score = 250.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 || (fitting_bins_count == 1 && post_residual <= 10) {
            score = 5.0;
        }
    }

    // Late in stream, tighten packing.
    score *= 1.0 + 0.5 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Partial lookahead: next item fits well into post residual
    if next_item_size > 0 {
        let slack = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + slack / 10.0);
        // penalize leaving a gap that next item cannot use
        if (post_residual as i64 - next_item_size as i64) < 0 {
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Tight fit now is good: small post_residual relative to item size
    score -= 2.0 * (item_size as f64 / bin_capacity as f64) * (bin_capacity as f64 - post_residual as f64);

    // Compare against mean residual across open bins
    score -= 0.5 * (post_residual as f64 - mean_residual);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New empty bin candidate: penalize unless it offers better long-term structure
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && next_item_size >= 50 {
            score -= 55.0; // big items pair well in a fresh bin
        }
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual < bin_capacity {
        score -= 20.0 * progress;
    } else {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly reward tight fits: post_residual near zero is ideal.
    score += 0.35 * (post_residual as f64 / cap) * (post_residual as f64 / cap) * cap;

    // Reward using an existing bin instead of opening a new one.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.05 * open_bins_count as f64;
    } else {
        score -= 2.0;
    }

    // Last-chance bin: strongly favor filling it to avoid waste.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead: if next item fits in the post residual, bonus for this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 3.0 + 0.05 * next_item_size as f64;
        } else {
            score += 0.05 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Prefer bins whose residual is below the mean (filling the emptiest first
    // keeps other bins flexible), but only mildly.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= 0.5;
    } else {
        score += 0.5 * (res_f - mean_residual) / cap;
    }

    // Time horizon: early in the stream, be more conservative about opening bins;
    // late in the stream, prioritize exact packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (1.0 - post_residual as f64 / cap);

    // Penalize leaving residuals that are too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits mildly; Late: strongly punish residual waste.
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    let waste_weight = 0.5 + 2.5 * prog2 + 1.5 * prog3;
    score += waste_weight * (pr / cap) * (pr / cap) * cap * 0.1;

    // Reward exact / near-perfect fits smoothly (smooth bump around pr=0).
    let tightness = (-pr / (cap * 0.15)).exp();
    score -= 6.0 * tightness;

    // Penalize dead space that cannot fit the lookahead item (smooth logistic).
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        let unusable = gap / (gap + 5.0);
        score += 4.0 * unusable * (0.5 + progress);
        // Reward leaving room exactly for the next item (smooth).
        let match_fit = (-(next_item_size as f64 - pr).abs() / 8.0).exp();
        score -= 3.0 * match_fit;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count <= 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // Coupling with mean residual: bins far below mean residual are better targets
    // (keeps residual distribution balanced, smooth quadratic term).
    let dev = (mean_residual - pr) / cap;
    score += 2.0 * dev * dev * cap * 0.05;

    // Mild penalty for spreading across too many open bins late in stream.
    score += 0.02 * open_bins_count as f64 * (0.3 + 0.7 * progress);

    // New-bin candidate: make empty bins moderately attractive only when
    // post_residual of open bins would be very wasteful (smooth interaction).
    if bin_residual == bin_capacity {
        let waste_elsewhere = (pr / cap) * (pr / cap);
        score = cap as f64 - 8.0 * waste_elsewhere * (0.4 + 0.6 * progress) - 4.0 * (1.0 - tightness);
        if fitting_bins_count <= 1 {
            score += 10.0; // discourage new bin when a fitting bin exists uniquely
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: leftover that no typical item (>=1) can use is worst;
    // leftover in "harmonic" classes (divisible into common fractions of capacity) is usable.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let usable = post_residual % 10 == 0 || post_residual >= 10;
    if !usable {
        score += 60.0;
    }

    // Harmonic class bonus: post_residual that is an integer divisor-multiple of capacity fractions
    let harmonic = if post_residual == half { 3.0 }
        else if post_residual == quarter || post_residual == 3 * quarter { 2.0 }
        else if post_residual % 25 == 0 { 1.5 }
        else if post_residual % 10 == 0 { 1.0 }
        else { 0.0 };
    score -= harmonic * 15.0;

    // Reward tight fill: fraction of bin consumed by this item.
    let fill_frac = item_size as f64 / cap;
    score -= 40.0 * fill_frac;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are all poor.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are opened only when justified.
        score += 45.0;
        // If the next item is large and this item leaves a bad remainder, new bin is attractive.
        let bad_remainder = post_residual > 0 && post_residual < 10;
        if next_item_size > 0 && next_item_size > post_residual && bad_remainder {
            score -= 70.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        // Few open bins: opening is cheap.
        if open_bins_count < 3 {
            score -= 25.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 120.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits: mildly good, scaled by how well it uses the leftover.
        score -= 20.0 * (next_item_size as f64 / post_f.max(1.0));
    } else if next_item_size > 0 {
        // Next item cannot use this leftover: penalize large wasted residuals.
        score += 0.3 * post_f;
    }

    // Prefer bins with residual below mean (tighter bins first), keeping big residuals for big items.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Modulo threshold on post_residual: values in [1,9] are near-dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps harshly (dead space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }
    // Reward leaving gaps that can plausibly fit typical items.
    if post_residual >= 10 {
        score -= 10.0;
    }

    // Last-chance pressure: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open bins pressure: with many open bins, avoid spreading; prefer filling existing bins.
    let open_pressure = open_bins_count as f64 * 0.5;
    if bin_residual != bin_capacity {
        score -= open_pressure;
    } else {
        // New bin candidate: add baseline penalty so it's chosen only when fits are bad.
        score += 15.0 + open_pressure;
        // If lookahead item could use a fresh bin's residual, slightly favor new bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    // Mean residual coupling: prefer bins whose residual is below average (tighter bins first).
    score += ((bin_residual as f64) - mean_residual) * 0.1;

    // Slight progression term: later in stream, be more conservative about new bins.
    if step_index as f64 / total_items as f64 > 0.8 && bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward if next item exactly matches post_residual,
    // penalize if next item cannot use the leftover space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            // next item fits here afterwards: reward closeness of match
            score -= 40.0 * (1.0 - (post - nxt).abs() / bin_capacity as f64);
        } else {
            // next item cannot fit into leftover: penalize dead space
            score += 15.0 + 0.3 * (post - (post % nxt)) as f64;
        }
    }

    // Penalize tiny unusable residuals (dead space below minimum item size 1 is fine,
    // but residuals much smaller than mean are wasteful).
    if post_residual > 0 && (post_residual as f64) < mean_residual * 0.35 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Prefer bins whose residual is close to the item (tight fits).
    score += 0.5 * (bin_residual as f64 - item_size as f64).abs();

    // Mild pressure to close out bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer more-filled bins among many open bins.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
