pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    let mut score = post;

    // Non-linear coupling of post residual with stream progress:
    // late in the stream, compact fills (small post residual) matter more.
    let progress_weight = 0.6 + 2.4 * t * t;
    score += progress_weight * (x * (1.0 - x)) * cap * 0.5;

    // Reward tight fits via smooth cubic shaping of x
    score -= 8.0 * (1.0 - x) * (1.0 - x) * (1.0 - x) * (1.0 + t);

    // Penalize dead space that no typical next item can use (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = ((nxt - post) / cap).max(0.0);
        score += 12.0 * unusable * unusable * (1.0 + t);
    } else {
        // last item: strongly favor minimal post residual
        score -= 10.0 * (1.0 - x);
    }

    // Last-chance bin bonus (smooth, based on fitting scarcity)
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 - x) * (1.0 + 0.5 * t);
    }

    // Mild penalty when bin is far from current mean residual (imbalance)
    let dev = (mean_residual - post).abs() / cap;
    score += 3.0 * dev * dev;

    // New-bin candidate: penalize slightly unless open bins are poor fits,
    // with smooth decay over stream progress
    if bin_residual == bin_capacity {
        let openness = (open_bins_count as f64).ln().max(0.0);
        score += 5.0 + 2.0 * openness * (1.0 - t);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: capacity / 8 buckets
    let class = post_residual / (bin_capacity / 8).max(1);
    // Perfect-fit harmonic classes (multiples of capacity/8) are dead-space friendly
    if post_residual % (bin_capacity / 8).max(1) == 0 {
        score -= 8.0;
    }
    // Penalize odd/small residual classes that are hard to fill (item sizes >= 10 typically)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0; // unusable sliver
    }
    if class == 0 {
        score -= 20.0; // exact fit
    }

    // Modulo coupling with next item size: reward residuals that can host the lookahead
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // harmonic match: post_residual % next_item_size small => chain fits
            if next_item_size > 0 && post_residual % next_item_size <= 3 {
                score -= 4.0;
            }
        } else {
            score += 5.0; // lookahead won't fit here
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        // opening a new bin wastes the item's footprint relative to mean residual
        score = 60.0 - mean_residual * 0.3 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big lookahead pairs well with fresh bin
        }
    }

    // Progression: later in stream, prefer tightening existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * (mean_residual / bin_capacity.max(1) as f64);

    // Penalize bins far from mean residual (fragmentation control)
    score += ((post_residual as f64 - mean_residual).abs()) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

