    }

    // Reward fitting into nearly-full bins (tight fit consolidation).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * tightness;

    // Open-bin pressure: prefer existing bins when many are open.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: strong bonus to use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_after_next = post_residual - next_item_size;
        if gap_after_next == 0 {
            score -= 18.0;
        } else if gap_after_next < 10 {
            score += 10.0; // would create dead space for next item
        } else {
            score -= 4.0;
        }
    }

    // New-bin candidate: only attractive when current bins would leave bad gaps.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        if post_residual - item_size as u32 > 0 && item_size > 50 {
            score += 5.0;
        }
    }

    // Mild stream-progression scaling: consolidate more as stream advances.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

