    }

    // Many open bins: discourage spreading; prefer filling existing ones.
    score -= 0.3 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New empty bin candidate: penalize slightly so it's only chosen when
    // open bins are genuinely bad fits (post_residual high there).
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if next item is large and no open bin chains well, allow new bin
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 10.0;
        }
    }

    // Late in the stream: prefer tighter packing overall.
    let progress = step_index as f64 / total_items as f64;
    score += 10.0 * progress * post_residual as f64 / bin_capacity as f64;

