}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: exact fill gets a strong bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space quadratically (unusable slivers).
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += (10.0 - dead) * 12.0;
        }
        // Reward leaving space that could still fit typical future items.
        let t = step_index as f64 / total_items.max(1) as f64;
        let usable_threshold = 20.0 + 20.0 * t;
        if dead >= usable_threshold {
            score -= 15.0;
        }
    }

    // Lookahead: bonus if post_residual can exactly fit the next item,
    // penalty if post_residual is just barely too small for it (near-miss waste).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 1.0 {
            score -= 60.0;
        } else if post_residual > 0 && (post_residual as u32) < next_item_size && (post_residual as u32) + 10 > next_item_size {
            score += 25.0; // dead space just below next item size
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): penalize unless current bins are quite full
    // or the fit into this empty bin is perfect relative to lookahead.
    if bin_residual == bin_capacity {
        let avg_fill = bin_capacity as f64 - mean_residual;
        let pressure = (open_bins_count as f64) * (avg_fill / bin_capacity as f64);
        // Opening a fresh bin is only attractive when existing bins are heavily loaded
        // and the item is large (little fragmentation risk).
        let largeness = item_size as f64 / bin_capacity as f64;
        score += 120.0 - 90.0 * pressure.max(0.0).min(1.5) - 40.0 * largeness;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 30.0; // fresh bin can host a perfect pair
        }
    } else {
        // Slight preference for fuller bins (best-fit style) beyond raw post_residual.
        let fullness = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
        score -= 20.0 * fullness;
    }

    // Early stream: be conservative, keep bins flexible; late stream: consolidate aggressively.
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * t * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    // Mild penalty when many bins are open and this bin is below average fullness.
    if open_bins_count > 3 && (bin_residual as f64) > mean_residual {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
