    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 18.0 * poly;

    // Penalize dead space more as stream advances (smooth cubic in progress)
    score += 10.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits, weighted by how many bins could fit the item
    let tightness = 1.0 - norm_pr;
    score -= 14.0 * tightness * tightness / (fitting_bins_count as f64).max(1.0);

    // Lookahead: reward residual that can host next item smoothly
    let fits_next = if next_item_size > 0 && post_residual >= next_item_size { 1.0 } else { 0.0 };
    score -= 8.0 * fits_next * (1.0 - (norm_next - norm_pr).abs());

    // Last-chance bonus: smooth interaction with progress
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual, smoothly damped
    score += 0.5 * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits and near-perfect fits are golden.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: zero residual is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Small-dead-space classes: post_residual in [1..=10] is highly usable by future small items.
    if post_residual >= 1 && post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 25.0;
    } else if post_residual <= 35 {
        score -= 8.0;
    }

    // Dead-zone class: residuals in (40..=60) are awkward — too big to ignore, too small for common items.
    if post_residual > 40 && post_residual <= 60 {
        score += 20.0;
    }

    // Harmonic modulo structure: residuals that are multiples of common item sizes (10, 20, 25, 50)
    // are reusable "harmonic" slots.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 10.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            // Reward proportionally to how snugly the next item nests.
            if gap <= 5 {
                score -= 120.0;
            } else if gap <= 15 {
                score -= 40.0;
            } else {
                score -= 10.0;
            }
            // Harmonic bonus: next item divides residual evenly (class match).
            if gap == 0 || post_residual % next_item_size == 0 {
                score -= 30.0;
            }
        } else {
            // Next item cannot fit here; residual becomes dead space unless others can use it.
            score += 12.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin should only win when it offers real long-term value.
    if bin_residual == bin_capacity {
        // Penalize opening a new bin mildly; it must beat genuinely bad fits.
        score += 55.0;
        // But if the item is large (harmonic half/whole classes), a fresh bin is natural.
        if item_size >= bin_capacity / 2 {
            score -= 70.0;
        }
        // Early in the stream, having few bins, a new bin gives flexibility.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 && open_bins_count < 4 {
            score -= 25.0;
        }
    }

    // Tightness coupling: filling a tight bin (small residual before placement) is efficient.
    let tightness = 1.0 - (bin_residual as f64) / cap;
    score -= tightness * 20.0;

    // Keep open-bin count in check: many open bins with large mean residual suggests fragmentation.
    if open_bins_count > 6 && mean_residual > 45.0 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that cannot fit even the smallest plausible item (1) is perfect;
    // a residual in the awkward 1..20 band wastes capacity.
    if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    } else if post_residual < 20 {
        score += (20 - post_residual) as f64 * 1.5; // dead space penalty gradient
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 15.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits the post-residual, this placement is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item would be blocked by the post-residual and gap is small, penalize.
    if next_item_size > post_residual && post_residual < 20 {
        score += 8.0;
    }

    // New-bin candidate: neutral baseline with mild bias toward using existing bins.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    // Mean residual coupling: if this bin is far below average residual, prefer it.
    score -= (mean_residual - bin_residual as f64).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty for wasted space relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    if next_item_size > 0 {
        // Perfect 2-step match: next item exactly fills post_residual -> big reward.
        if post_residual == next_item_size {
            score -= 120.0;
        }
        // Next item fits into post_residual: reward proportional to tightness.
        else if next_item_size <= post_residual {
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 40.0 + 60.0 * tight;
        }
        // Next item cannot use this bin's leftover: penalize dead space, more so for tiny leftovers.
        else {
            let waste = next_item_size - post_residual;
            score += 20.0 + waste as f64 * 0.8;
            // Very small leftovers are near-dead space.
            if post_residual < 10 {
                score += 60.0;
            }
        }
    } else {
        // Last item: just minimize leftover.
        score += 10.0;
    }

    // Compare against mean residual: bins with residual far below mean are "tight" and
    // should be filled first (avoid scattering small items across many bins).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= dev * 1.5;
    } else {
        score += (-dev) * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Early in the stream: encourage consolidation, discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when few bins are open or early on.
        score += 50.0 + 40.0 * (1.0 - progress);
        if open_bins_count > 0 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste dominates).
    let fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit * fit;

    // Penalize creating small unusable dead space (< 10).
    if post_residual < 10 {
        score -= 12.0; // perfect closure is great
    } else if post_residual < 20 {
        score += 4.0; // awkward sliver
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // next item won't fit here; slight penalty for leaving medium gaps
            score += 3.0;
        }
    }

    // New-bin candidate handling: opening a bin is expensive; make the empty
    // bin score unattractive unless the item is large relative to capacity
    // or existing residuals are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let load = item_size as f64 / bin_capacity as f64;
        let mut new_bin_score = 45.0 - 40.0 * load;
        // Late in the stream, avoid proliferating bins.
        new_bin_score += 20.0 * progress;
        // If many bins are open with slack, discourage new bins.
        new_bin_score += 0.05 * open_bins_count as f64;
        // If mean residual is small, opening a bin is more justified.
        new_bin_score -= (mean_residual / bin_capacity as f64) * 15.0;
        // Large items (>= 70) fit nowhere else well: soften penalty.
        if item_size >= 70 {
            new_bin_score -= 20.0;
        }
        score = new_bin_score.max(score.min(f64::MAX));
    }

    // Mild preference for fuller bins among open ones.
    score += 0.02 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let tightness = 1.0 - pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score += (prog2 * 18.0 + prog3 * 24.0) * (pr / cap) * (pr / cap);

    // Reward tight fits more strongly as stream progresses (smooth quadratic coupling)
    score -= tightness * tightness * (10.0 + 30.0 * progress);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).max(0.0);
        score += gap * gap / cap * (1.0 + progress);
        // Reward leaving space exactly usable by next item
        let usable = 1.0 - (pr - nx).abs() / cap;
        score -= usable * usable * (4.0 + 8.0 * progress);
    }

    // Last-chance bonus: smooth exponential-like reward via polynomial
    if fitting_bins_count <= 1 {
        score -= 6.0 + 12.0 * progress;
    }

    // Mild penalty for spreading across many open bins, scaled by mean residual dispersion
    let disp = (mean_residual - bin_residual as f64).abs() / cap;
    score += disp * disp * (3.0 + 5.0 * (open_bins_count as f64).ln().max(1.0));

    // Prefer filling already-opened bins as stream progresses
    score += (open_bins_count as f64) * (0.5 + 1.5 * progress) * (pr / cap);

    // New-bin candidate: penalize unless residual is large relative to remaining demand
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress - (post_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: waste measured relative to capacity fractions.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 60.0;

    // Harmonic class of post_residual: perfect zero waste is golden.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Modulo classes: residuals that are multiples of small item sizes
        // (likely future items) are more reusable than odd dead space.
        let r = post_residual;
        let divisible_bonus = if r % 10 == 0 { 25.0 }
            else if r % 5 == 0 { 15.0 }
            else if r % 2 == 0 { 8.0 }
            else { 0.0 };
        score -= divisible_bonus;

        // Dead-space penalty: residual too small for the smallest plausible item (1..100 unknown,
        // but penalize very tiny residuals that can never fit typical items).
        if r < 10 {
            score += 45.0;
        } else if r < 20 {
            score += 20.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // Next item fits: leftover after next placement drives preference.
            let after_next = post_residual - next_item_size;
            score -= 40.0 - (after_next as f64) * 0.3;
        } else {
            // Next item won't fit here; slight penalty if this bin would be nearly emptied.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer filling bins with small residuals relative to the mean (balance avoidance of
    // many half-empty bins): bins below mean residual get a bonus.
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Stream progression: late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize unless residual of this item placement would be tiny
        // or item is large (better to pack big items fresh).
        score += 30.0 - (item_size as f64) * 0.35 + progress * 40.0;
        if item_size >= 50 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize large waste relative to capacity.
    let waste_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += waste_ratio * 30.0;

    // Open-bin pressure: prefer filling existing bins when many are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    }
    // If next item would not fit but could fit the current residual, slight penalty.
    if next_item_size > post_residual && next_item_size > 0 && (bin_residual as f64) >= next_item_size as f64 {
        score += 6.0;
    }

    // Deviation from mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // New-bin candidate: make opening a new bin moderately expensive unless it is clearly better.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly (or nearly)
    // matches the next item size, leaving a perfect fit for the following item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Perfect two-item closure: bin becomes exactly full after next item.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize dead space the next item cannot use.
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 20.0;
    }

    // Relative-to-mean coupling: bins with small residual (tight bins) are precious;
    // discourage wasting them unless the lookahead match is excellent.
    let tightness = (bin_residual as f64) / (bin_capacity as f64);
    score += 10.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight preference for keeping many open bins consolidated when mean residual is high.
    if mean_residual > (bin_capacity as f64) * 0.5 {
        score -= 5.0;
    }

    // Prefer filling bins early in the stream; later, tolerate opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress);

    // Discourage leaving very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Penalize small dead space after placement (waste minimization).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // near-perfect fit
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 4.0; // awkward leftover zone
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 0.1 * next_item_size as f64;
        } else {
            // Penalize blocking the next item into a large unusable gap.
            let gap = post_residual as f64;
            score += 0.15 * gap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when good fits exist
    // or when many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let base_penalty = 18.0 + 10.0 * progress;
        let fragmentation = open_bins_count as f64 * 0.5;
        let mean_res_gap = (mean_residual - item_size as f64).abs();
        score += base_penalty + fragmentation - 0.2 * mean_res_gap;
        // Opening a new bin is fine if no open bin fits well (item nearly fills capacity).
        if item_size as f64 > 0.9 * bin_capacity as f64 {
            score -= 25.0;
        }
    }

    // Mild preference for bins below mean residual (balance residuals across bins).
    if bin_residual as f64 > mean_residual {
        score += 2.0;
    } else {
        score -= 2.0;
    }

    // Late in the stream, prioritize exactness over consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Smooth non-linear coupling of post_residual with stream progress
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let coupling = norm_post * norm_post * (0.5 + 2.0 * progress * (1.0 - progress) * 4.0);
    score += coupling * 20.0;

    // Penalize large dead space more as stream progresses (fewer future items to fill gaps)
    score += (post_residual as f64).powi(3) / (bin_capacity as f64).powi(2) * (0.25 + progress);

    // Reward tight fits, amplified mid-stream
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * tightness * 10.0 * (1.0 + progress);

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: reward residual that can host the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 6.0 * (1.0 - progress);
    }

    // Prefer filling bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * norm_post * 3.0;

    // New-bin candidate: mild penalty so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 8.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: capacity split into 8 octave classes.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let class = (post_f / cap_f * 8.0).floor().min(7.0); // 0 = tightest fit

    // Reward tight fits non-linearly (quadratic in class).
    score -= 0.9 * (7.0 - class) * (7.0 - class) * 0.5;

    // Dead-space penalty: residuals too small for any plausible item (1..=9).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Harmonic coupling: does next_item_size land in the same residue class band?
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if next_f <= post_f {
            // Next item fits: reward proportionally to how well it fills.
            let fill_ratio = next_f / post_f;
            score -= 12.0 * fill_ratio;
            // Exact harmonic match (next divides residual nicely, modulo 10 classes).
            let r = post_residual % 10;
            let nr = next_item_size % 10;
            if r == nr { score -= 4.0; }
        } else {
            // Next item does NOT fit here: penalize wasting capacity this bin locks up.
            score += 0.35 * post_f;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral baseline, slightly above good fits.
    if bin_residual == bin_capacity {
        score = cap_f * 0.75;
        // Open a new bin early in stream or when existing bins are fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count == 0 { score -= 40.0; }
        if mean_residual < 15.0 && fitting_bins_count > 0 { score -= 8.0; }
        if progress > 0.9 { score += 5.0; } // late stream: consolidate instead
    }

    // Mild tie-break: prefer bins with below-mean residual (consolidate fragmentation).
    score += 0.1 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host any
    // plausible future item (<= 10, or <= half of next item) are pure waste.
    let dead_threshold = 10u32.max(next_item_size / 2);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 3.0;
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward snug fits: small positive post_residual that is still usable.
    if post_residual > 0 && post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack.min(25.0);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use this leftover: penalize proportionally.
        score += 8.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading into new bins,
    // but only mildly so tight fits elsewhere still win.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64 - mean_residual / 10.0) * 0.6 * (0.5 + progress);

    // New-bin candidate: only attractive when the current item is huge or no
    // open bin offers a decent fit (large mean residual spread).
    if bin_residual == bin_capacity {
        let big_item_bonus = if item_size > 50 { 30.0 } else { 0.0 };
        score += 45.0 - big_item_bonus - (mean_residual - item_size as f64).max(0.0) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Dead-space penalty: very small post_residual that is still nonzero is
    // likely unusable for future items (min size 1), but a post_residual of 0
    // is a perfect close — reward it.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0; // next item will close this bin perfectly
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= (15.0 * (1.0 - slack / bin_capacity as f64)).max(0.0);
        } else {
            // next item cannot fit here; penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.15 * gap;
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are worth filling.
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let rel = resid_f / mean_residual;
        if rel < 1.0 {
            score -= 6.0 * (1.0 - rel); // tighter-than-average bin: fill it
        } else {
            score += 3.0 * (rel - 1.0).min(2.0); // looser-than-average: deprioritize
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent fit. Penalize the fresh bin, more so late in the stream
    // or when many bins are already open.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 30.0 + 20.0 * progress;
        if open_bins_count > 0 {
            new_bin_penalty += 10.0;
        }
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size >= 50 {
            new_bin_penalty -= 15.0;
        }
        score += new_bin_penalty.max(0.0);
    }

    // Mild preference for keeping the number of open bins from exploding.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space: post_residual too small to ever be useful again.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item,
    // penalize bins that would leave a residual incompatible with it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.8;
        }
    }

    // Mildly discourage opening new bins when many bins are already open
    // and mean residual is high (fragmented state).
    if bin_residual == bin_capacity {
        // New-bin candidate: base preference plus penalty scaled by open bins.
        score += 30.0 + (open_bins_count as f64).sqrt() * 4.0;
        // But if mean residual is low (open bins nearly full), new bin is fine.
        score -= mean_residual * 0.5;
        // Early in the stream, opening bins is cheaper.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - t) * 20.0;
    }

    // Slight preference for bins with residual far below mean (consolidate small leftovers).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Time-horizon term: later in the stream, be greedier about tight fits.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (post_residual as f64 / bin_capacity as f64) * t * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear waste penalty: dead space below typical item sizes is costly.
    let waste = pr / cap;
    score += 40.0 * waste * waste * (0.5 + progress);

    // Reward tight fits (small post_residual) with smooth quadratic discount.
    let tight = 1.0 - (pr / cap);
    score -= 25.0 * tight * tight * tight;

    // Lookahead coupling: penalize if the next item cannot use this post-residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 12.0 * (nxt - pr) / cap;
        } else {
            let usable = 1.0 - ((pr - nxt) / cap);
            score -= 10.0 * usable * usable;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 + 20.0 * progress;
    }

    // Mild pressure toward consolidating into fewer bins as stream progresses.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * (0.3 + progress);

    // Deviation from mean residual: prefer bins whose residual differs favorably.
    score += 0.15 * (pr - mean_residual) * (0.5 + progress);

    // New-bin candidate: make empty bins moderately attractive only for large items.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / cap;
        score += 8.0 * (1.0 - large) * (1.0 - large) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are "nice" multiples
    // of common small item sizes (they remain reusable), penalize awkward ones.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -30.0 // perfect fit
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else if pr % 20 == 0 {
        -10.0
    } else {
        // awkward dead space: residuals < 10 are nearly unusable
        if pr < 10 { 12.0 } else { 0.0 }
    };
    score += harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (harmonic chain).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if pr >= next_item_size && (pr - next_item_size) % 10 == 0 {
            score -= 10.0;
        } else if pr < next_item_size {
            score += 3.0; // next item won't fit here; slight penalty
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: opening a bin should be discouraged unless the item
    // is large relative to typical residuals or many bins already fit the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0
            - 10.0 * progress
            - 2.0 * (fitting_bins_count as f64).min(6.0)
            + if item_size as f64 > mean_residual { -5.0 } else { 5.0 };
    }

    // Mild tie-break toward tighter (smaller-residual) bins.
    score += 0.05 * (bin_residual as f64 - post_residual as f64) * 0.0;

    // Penalize bins far from the mean residual (fragmentation signal).
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are dead space.
    // Penalize them heavily; reward exact/near-exact fits.
    if post_residual == 0 {
        score -= 500.0; // perfect fit
    } else if post_residual < 10 {
        score += 200.0; // unusable dead space
    } else if post_residual < 25 {
        score += 60.0; // small, hard-to-fill gap
    } else {
        // Usable gap: mild reward proportional to tightness
        score -= (post_residual as f64).log2() * 4.0;
    }

    // Reward bins whose residual exactly matches what the next item would consume
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual < next_item_size {
            score += 30.0; // blocks the lookahead item
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bin pressure: when many bins are open, prefer reusing existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.5;

    // New-bin candidate (empty bin): only attractive when current fit is poor
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly; strong penalty when many bins are open
        score += 150.0 + open_bins_count as f64 * 2.0;
        // But if the mean residual is small (all bins nearly full), new bin is fine
        if mean_residual < 15.0 {
            score -= 120.0;
        }
        if progress > 0.8 {
            score -= 10.0;
        }
    }

    // Slight preference for bins tighter than the average residual (compactness)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: minimize leftover space.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly into post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual > next_item_size {
            // Next item fits but leaves more slack; mild penalty proportional to new slack.
            score += 0.15 * (post_residual - next_item_size) as f64;
        }
        // Penalize bins whose post-residual is too small for the next item (dead space).
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.35 * post_residual as f64;
        }
    }

    // Compare post-residual against mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins already fit the item.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 25.0;
        // New bin more acceptable early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Mild penalty on very small dead space (fragmentation) relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize exact-tight fits only when they waste the bin on a small item;
    // otherwise reward near-perfect packing.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual < 10 {
        score += 8.0; // dead space below min item size is unusable
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let chain_fit = next_item_size as f64 / (post_residual as f64 + 1.0);
        score -= 20.0 * chain_fit;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size {
        // Next item cannot use leftover; penalize leaving awkward residue.
        score += 6.0;
    }

    // Prefer filling already-open bins when many are open; encourage new bins
    // when few are open and the current fit is loose.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    let open_pressure = open_bins_count as f64 / (1.0 + progress * 5.0);
    score += open_pressure * 0.8;

    // Compare residual against global mean residual: bins with residual close to
    // the item (leaving mean-like residue) pack better statistically.
    let dev = (bin_residual as f64 - item_size as f64 - mean_residual).abs();
    score += dev * 0.15;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_alternatives = fitting_bins_count == 0
            || (item_size as f64 / bin_capacity as f64) < 0.35 && mean_residual < item_size as f64;
        if poor_alternatives {
            score -= 30.0;
        } else {
            score += 20.0;
        }
    }

    // Slight late-stream conservatism: keep bins tight near the end.
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress) - 0.35 * (norm_pr * (1.0 - norm_pr)) * cap;

    // Reward tight fits (small post_residual) more strongly later in the stream
    score -= 30.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Penalize dead space that cannot fit the average remaining need
    let avg_need = if next_item_size > 0 { next_item_size as f64 } else { 0.0 };
    if pr < avg_need && pr > 0.0 {
        score += 12.0 * (1.0 - pr / avg_need.max(1.0));
    }

    // Last-chance bin bonus: strongly prefer the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild penalty for spreading across many open bins when residuals are large
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // Encourage matching bin residual to mean residual (balance)
    score += 0.1 * (pr - mean_residual).abs();

    // New-bin candidate: keep it competitive only when fits are poor
    if bin_residual == bin_capacity {
        score = pr + 18.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that divide capacity evenly
    // (residual in {0, 25, 50, 75, 100} are "perfect" classes).
    let capacity_frac = (post_residual as f64) / (bin_capacity as f64);
    let class_key = (post_residual * 4) % bin_capacity; // harmonic residue mod capacity
    let perfect = post_residual == 0 || post_residual * 4 == bin_capacity
        || post_residual * 2 == bin_capacity || post_residual * 4 == 3 * bin_capacity;
    if perfect {
        score -= 8.0; // strong reward for landing on a harmonic class
    } else if class_key % 4 == 0 {
        score -= 2.0;
    }

    // Penalize dead space: small-but-nonzero post_residual is wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead coupling: if the next item exactly fills post_residual, big reward.
    if next_item_size == post_residual && post_residual > 0 {
        score -= 10.0;
    }
    // Next item fits in post_residual but leaves a bad remainder -> mild penalty.
    if next_item_size > 0 && next_item_size < post_residual {
        let next_post = post_residual - next_item_size;
        if next_post > 0 && next_post < 10 {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        score += 30.0 - 10.0 * pressure;
        if item_size > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // Tight fits (near-full bins) are always good.
    if post_residual <= bin_capacity / 10 {
        score -= 3.0;
    }

    // Late in the stream, prefer closing bins out (favor fuller bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..100)
    // can usefully fill are heavily penalized.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual < 25 {
            score += 25.0; // only tiny items can fit
        } else if post_residual < 50 {
            score += 8.0;  // moderately awkward
        }
    }

    // Reward tight fits (waste below 10% of capacity).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste_ratio) * 30.0;

    // Exact or near-exact fill is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it moderately attractive only when existing
    // residuals are large or item is big; otherwise discourage proliferation.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64 * 4.0;
        if item_size >= 50 {
            score -= 15.0; // big items start fresh bins more readily
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // lookahead: another big item may join this fresh bin
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidation.
    score += open_bins_count as f64 * 1.5;

    // If the next item could exactly fill this bin's post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64 / 100.0) * 10.0;
    }

    // Mean-residual coupling: bins far below mean residual are better targets.
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Slight late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += waste_ratio * 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // --- 2-step lookahead: reward when next item exactly fills post_residual ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let gap = (post - nxt).abs();
        if nxt <= post {
            // Next item fits: reward tightness (perfect match -> big reward)
            let tightness = 1.0 - gap / (bin_capacity as f64);
            score -= 30.0 * tightness * tightness;
            // Extra reward for exact match
            if gap == 0.0 {
                score -= 40.0;
            }
        } else {
            // Next item cannot use the leftover: penalize dead space proportionally
            let dead = post / (bin_capacity as f64);
            score += 25.0 * dead * dead;
        }
    } else {
        // Last item: just prefer tightest packing
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // --- Penalize creating unusable slivers (post_residual too small for typical items) ---
    let min_item = 1.0;
    if (post_residual as f64) < min_item {
        score += 100.0;
    }

    // --- Relative to mean residual: prefer bins that are already more filled than average ---
    let mean_gap = mean_residual - post_residual as f64;
    score -= 0.5 * mean_gap;

    // --- Last-chance bin: if this is the only fitting bin, strongly favor using it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // --- New-bin candidate handling: penalize opening a new bin, more so early on ---
    if bin_residual == bin_capacity {
        // Opening a new bin wastes residual capacity of existing bins
        let openness = open_bins_count as f64;
        score += 20.0 + 3.0 * openness * (1.0 - progress);
        // But if no existing bin fits well (large dead space everywhere), allow it
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // If next item is large and would need a fresh bin anyway, mild bonus
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 10.0;
        }
    }

    // --- Prefer bins whose residual is close to item size (good fill) ---
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space: residuals too small for likely future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 4.0;
        }
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate logic: only attractive when open bins have large residuals
    // (fragmented state) or few bins open.
    if bin_residual == bin_capacity {
        let fragmentation = if mean_residual > 0.0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        score += 15.0 - 20.0 * fragmentation - 8.0 * (1.0 - pressure);
        // Early in stream, opening new bins is cheap.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // If next item is large, a fresh bin is valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Waste-avoidance: penalize leaving residual far from any typical item size.
    let mut best_gap = f64::INFINITY;
    for k in [10u32, 20, 30, 40, 50, 60, 70, 80, 90, 100] {
        if k <= post_residual {
            let gap = (post_residual - k) as f64;
            if gap < best_gap { best_gap = gap; }
        }
    }
    if best_gap.is_finite() {
        score -= 6.0 * (1.0 - best_gap / bin_capacity as f64);
    } else if post_residual > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual polynomial coupling with stream progress
    let x = pr / cap;
    score += 40.0 * x * x * (0.5 + 0.5 * progress);
    score -= 30.0 * x * (1.0 - progress) * (1.0 - progress);

    // Tight fit reward: small post-residual is valuable, more so late in stream
    score -= (1.0 - x) * (1.0 - x) * 25.0 * (0.3 + 0.7 * progress);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 20.0 * (1.0 - pr / nx) * (0.5 + 0.5 * progress);
        } else {
            score -= 10.0 * (1.0 - ((pr - nx) / cap).abs()) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize slightly unless open bins are congested
    if bin_residual == bin_capacity {
        let congestion = (mean_residual / cap).abs();
        score += 15.0 + 20.0 * congestion * (1.0 - progress);
    }

    // Smooth coupling with mean residual: prefer bins deviating favorably
    score += 0.3 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // Small penalty on many open bins to discourage fragmentation
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: bins whose leftover falls into
    // "usable" classes (large enough for typical small items) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class penalty: residuals that are dead space (too small to fit anything
    // meaningful, i.e. < 10 in classic regime, scaled to unknown distribution)
    let dead_threshold = cap * 0.10;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 25.0; // near-full bin is fine actually; but tiny un-usable gap is wasted
        // Actually a tiny gap means bin was almost perfectly filled -> reward instead
        score -= 40.0;
    }

    // Perfect fill reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic (modulo) class of post_residual against next_item_size:
    // if the next item fits exactly into the post residual, strongly favor.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 20.0 - (slack.min(20) as f64) * 0.5;
        if slack == 0 {
            score -= 25.0; // chain of perfect fits
        }
    } else if next_item_size > 0 {
        // next item won't fit here; residual becomes a waiting class
        score += 8.0;
        // modulo harmony: residual divisible by common item granularities is reusable
        let r = post_residual;
        if r % 5 == 0 { score -= 3.0; }
        if r % 10 == 0 { score -= 4.0; }
        if r % 20 == 0 { score -= 3.0; }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer filling bins with below-mean residual (tighten loose bins)
    let dev = mean_residual - pr;
    if dev > 0.0 {
        score -= dev * 0.3;
    } else {
        score += (-dev) * 0.15;
    }

    // New-bin candidate: penalize mildly so it only wins when open bins are bad,
    // but allow it early in the stream or when open bins are numerous and loose.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = (open_bins_count as f64) * mean_residual / cap;
        score = cap * 0.35 + openness * 0.4 - progress * 10.0;
        if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
            // next item may want a fresh bin
            score -= 5.0;
        }
    }

    // Mild normalization of base residual term
    score *= 0.5;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are unusable waste.
    if post_residual < 10 {
        score += 60.0; // penalize tiny dead space
    } else if post_residual <= 20 {
        // mid-small gap: mildly penalized unless it can host the next item
        if (next_item_size as u32) <= post_residual && next_item_size > 0 {
            score -= 25.0; // gap is reusable by lookahead item -> reward
        } else {
            score += 15.0;
        }
    } else {
        // large gap: reward, especially if it fits the next item
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 20.0;
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 3.0;

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make it moderately attractive only when current bin fit is poor
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: its post_residual is large, so subtract to normalize
        score -= 35.0;
        if fitting_bins_count > 0 && post_residual >= 10 {
            // opening a new bin when an open bin leaves usable space is wasteful
            score += 30.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins) when pressure is high
    if (bin_residual as f64) < mean_residual {
        score -= 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
    }

    // Slight progression term: late in stream, be more conservative about new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Penalize leftover space that next item only partially uses
        score += 0.35 * ((post_residual - next_item_size) as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space the next item cannot use at all
        score += 0.6 * (next_item_size - post_residual) as f64;
    }

    // Penalize large dead space relative to capacity
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 15.0 * dead_frac * dead_frac;

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        score -= 8.0 * (1.0 - (post_residual as f64 / (item_size + post_residual) as f64));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin when good fitting bins exist
    if bin_residual == bin_capacity {
        score += 30.0;
        if fitting_bins_count > 0 && post_residual as f64 >= mean_residual {
            score += 10.0;
        }
    }

    // Compare against mean residual: prefer bins below mean residual (tighter bins)
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // Early in stream: be slightly more open to new bins; late: consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * (open_bins_count as f64).recip().min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear)
    score -= 40.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(3);

    // Penalize large dead space quadratically
    if post_residual > 0 {
        score += 0.004 * (post_residual as f64).powi(2);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: bonus if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty for leaving awkward residue
            score += 0.02 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: discourage spreading; few bins: encourage consolidation
    let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.15 * open_pressure;

    // Favor bins with below-mean residual (consolidate fuller bins)
    score += 0.3 * ((mean_residual - bin_residual as f64) / bin_capacity as f64).max(-2.0).min(2.0);

    // New-bin candidate handling: only attractive when item is large relative to
    // capacity or stream is early and mean residual is low
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        let attractiveness = 55.0 * item_frac * (1.0 - progress) + 20.0 * (1.0 - mean_residual / bin_capacity as f64);
        score += 45.0 - attractiveness;
    }

    // Late in stream: be greedy, minimize waste now
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, larger leftover space is fine; later, waste is penalized super-linearly.
    let waste_weight = 1.0 + 2.5 * progress * progress;
    score -= (1.0 - norm_post).powi(3) * item_size as f64 * waste_weight * 0.5;

    // Penalize dead space (small unusable post_residual) with a smooth bump around 0..15
    let dead = (norm_post * 6.0).exp() - 1.0;
    score += dead * 12.0 * (0.3 + 0.7 * progress);

    // Reward tight fits (post_residual near zero) smoothly
    score -= (1.0 - norm_post).powi(2) * 8.0;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Smoothly discourage spreading across many bins when residuals are already small
    let mean_norm = mean_residual / cap;
    score += (open_bins_count as f64).ln().max(0.0) * mean_norm * 4.0;

    // Lookahead: reward leaving space compatible with the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let compat = 1.0 - ((pr - n) / cap).abs();
        score -= compat.max(0.0) * 6.0 * (1.0 - progress * 0.5);
        // penalize leaving exactly a sliver that next item cannot use
        if pr < n {
            score += (n - pr) * 0.3;
        }
    }

    // Mild preference to keep new bins closed early in the stream
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + (open_bins_count as f64) * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues divisible by large classes are more reusable
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reusability bonus: post_residual divisible by common item sizes (harmonic classes)
    for class in [10u32, 20, 25, 50].iter() {
        if post_residual % class == 0 {
            score -= 12.0;
        }
    }

    // Penalize dead space: post_residual too small for any plausible item (min size 10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // "Awkward zone": residuals just below common item sizes are dead space
    for threshold in [11u32, 21, 26, 51].iter() {
        if post_residual > 0 && post_residual < *threshold && post_residual >= threshold - 1 {
            score += 25.0;
        }
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= 30.0;
            // extra reward if post_residual - next_item_size lands on harmonic class
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 || gap % 25 == 0 {
                score -= 40.0;
            }
        } else {
            // next item won't fit here: mild penalty scaled by how much it overshoots
            let over = (next_item_size - post_residual) as f64;
            score += (over / cap) * 80.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Prefer filling fuller bins (relative fill fraction)
    score -= (1.0 - pr / cap) * 20.0;

    // Prefer bins below mean residual (tighter bins first)
    score += (pr - mean_residual) * 0.3;

    // New-bin candidate: penalize opening a new bin unless current bin would be badly fragmented
    if bin_residual == bin_capacity {
        score += 55.0;
        // but allow new bin if item is huge and mean residual is small
        score -= (item_size as f64 / cap) * 40.0;
        if mean_residual < item_size as f64 {
            score -= 70.0;
        }
    }

    // Late in stream: consolidate, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    } else {
        score -= progress * 10.0;
    }

    // Mild penalty per open bin count to discourage bin proliferation
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 {
        let dead = post_residual < 10;
        let tight = post_residual < 20;
        if dead {
            score += 40.0;
        } else if tight {
            score += 12.0;
        } else {
            // Larger gaps are more reusable; mild reward proportional to size.
            score -= (post_residual as f64) * 0.15;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Lookahead coupling: bonus if post_residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            // Would create a new dead space for the next item: penalize.
            score += 10.0;
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (penalize new-bin candidate more strongly).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.4 * progress);
    if bin_residual == bin_capacity {
        score += pressure;
    } else {
        score -= pressure * 0.2;
    }

    // Mean-residual coupling: prefer bins deviating below mean residual
    // (i.e., fuller bins) when mean residual is small.
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post-residual.
    if next_item_size > 0 {
        let next_fits = (post_residual as i64 - next_item_size as i64) >= 0;
        if next_fits {
            let slack_after_next = post_residual as f64 - next_item_size as f64;
            score -= 120.0 - slack_after_next * 0.5;
        } else {
            // Penalize placements that strand space the next item cannot use.
            let waste = post_residual as f64 - (post_residual as f64 % next_item_size.max(1) as f64);
            score += waste * 0.3;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let good_fit_exists = post_residual as f64 <= mean_residual * 0.5;
        if good_fit_exists && open_bins_count > 0 && fitting_bins_count > 1 {
            score += 500.0;
        } else {
            score += 150.0 + 100.0 * (1.0 - progress);
        }
    }

    // Mild penalty for leaving large dead space.
    if post_residual > 0 && post_residual < 10 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space quadratically (wasted capacity).
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Reward tight fits: small post_residual strongly favored.
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // Partial reward proportional to how well next item fills leftover.
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use the leftover: mild penalty for large leftovers.
            score += 0.05 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64).abs());
        }
    }

    // Prefer bins below mean residual (keep residual distribution balanced).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Early in the stream, prefer opening new bins to build flexibility;
    // late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized later.
        score -= 30.0 * (1.0 - progress);
        score += 60.0 * progress;
        // Penalize opening new bins when many bins are already open.
        score += 2.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        score -= 15.0 * progress;
    }

    // Mild penalty for many fitting bins competing (encourage spreading load
    // to the bin that needs it most, handled via residual comparison above).
    if fitting_bins_count > 3 {
        score += 1.5 * (fitting_bins_count as f64 - 3.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let x = pr / cap;
    let t = progress;
    // Dead-space penalty grows super-linearly in residual as stream advances.
    score += 40.0 * x * x * (0.4 + 0.6 * t);
    score -= 25.0 * x * (1.0 - t);

    // Reward tight fits (small post_residual) with smooth quadratic term.
    score -= 12.0 * (1.0 - x) * (1.0 - x);

    // Last-chance bin bonus (smooth, not piecewise).
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 18.0 * last_chance * (1.0 - x);

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        let fits_next = if (post_residual as u32) >= next_item_size { 1.0 } else { 0.0 };
        score -= 10.0 * fits_next * (1.0 - t);
        // Penalize leaving residual that is too small for the next item (dead space).
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 20.0 * gap * gap;
    }

    // Prefer bins with below-mean residual slightly (balance load), smoothly.
    score += 5.0 * ((pr - mean_residual) / cap);

    // Mild penalty for proliferating bins early.
    score += 2.0 * (open_bins_count as f64) * t / (total_items.max(1) as f64).sqrt();

    // Discourage opening a new bin when a good fit exists in an open bin.
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - t) + 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into coarse buckets
    // using integer division on a 20-unit grid (capacity / 5).
    let class = post_residual / 20;
    score += match class {
        0 => 0.0,          // tight fit, near-perfect packing: reward
        1 => 3.0,          // small leftover: mildly penalize
        2 => 6.0,          // medium leftover: worse
        3 => 9.0,          // large leftover
        _ => 12.0,         // nearly empty bin used for a small item: wasteful
    };

    // Exact-fit bonus: post_residual in harmonic residue 0 mod 10 is ideal dead space.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Dead-space penalty: leftover too small for the smallest plausible item (<=5).
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // this placement chains perfectly; reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size < post_residual {
            let nxt_class = (post_residual - next_item_size) / 20;
            score += 2.0 * nxt_class as f64;
        } else {
            // next item cannot use this leftover: leftover is more likely dead
            score += 4.0;
        }
    }

    // Last-chance logic: if this is the only bin that fits, prefer using it
    // over opening a new bin (penalize the alternative implicitly by rewarding this).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 6.0;
    }

    // New-bin candidate handling: an empty bin (residual == capacity) should only
    // win when no open bin offers a reasonable fit. Penalize it proportionally
    // to how many bins already fit the item, and to stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 14.0 + 4.0 * fitting_bins_count as f64 + 6.0 * progress;
        // Exception: huge items relative to capacity benefit from a fresh bin
        if item_size * 2 >= bin_capacity && fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "waste candidate" already; placing here preserves big spaces elsewhere.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= 0.05 * residual_gap;
    } else {
        score += 0.05 * (-residual_gap);
    }

    // Mild pressure to consolidate when many bins are open.
    score -= 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Post-residual that can't fit the smallest plausible item is dead space.
    if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    score -= 0.35 * ((bin_capacity - post_residual) as f64);

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, discourage opening yet another.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).sqrt() * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        score += 12.0 + pressure;
    } else {
        score -= 2.0;
    }

    // Lookahead: if next item can use the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot fit into post residual but could fit a fresh bin,
    // penalize wasting this bin's space.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Prefer bins whose residual deviates from mean (better consolidation).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (post_residual small).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit: penalize dead space proportional to post_residual
            score += 0.5 * post_residual as f64;
        }
    }

    // Compare post_residual against mean residual: prefer bins that keep
    // residual distribution tight (avoid fragmenting).
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.3 * mean_gap;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
    }

    // Penalize opening a new bin when the item would leave a large residual
    // in an existing bin (waste potential).
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty so good fits in open bins win.
        score += 30.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // New bin is attractive if item is large (little residual created).
            score -= (item_size as f64 / bin_capacity as f64) * 40.0;
        }
    }

    // Late in the stream: consolidate more aggressively into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty per open bin to discourage proliferation.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving residual that wastes space relative to next item.
            score += 4.0 * (next_item_size as f64 - post_residual as f64).min(20.0) / 20.0;
        }
    }

    // New-bin candidate handling: make an empty bin attractive only when fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we prefer existing bins with good fits.
        score += 15.0;
        // If the item fits very poorly anywhere (large post residual everywhere),
        // opening a new bin becomes attractive: reward new bin when item is large.
        let fill_fraction = item_size as f64 / bin_capacity as f64;
        score -= 20.0 * fill_fraction;
        // If many bins are open and mean residual is low, opening fresh bins helps.
        if mean_residual < item_size as f64 + 5.0 {
            score -= 10.0;
        }
    } else {
        // Slight preference for bins with residual close to mean (balance load).
        score += 0.05 * ((bin_residual as f64 - mean_residual).abs());
        // Penalize scattering across too many open bins when item is small.
        if item_size < 30 && open_bins_count > 5 {
            score += 2.0;
        }
    }

    // Time horizon: late in the stream, be more conservative (prefer tight packing,
    // avoid opening new bins), early on allow exploration.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress > 0.8 {
        if is_new_bin { score += 20.0 * (progress - 0.8) * 5.0; }
        if fitting_bins_count == 1 { score -= 10.0 * (progress - 0.8) * 5.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;
    let mut score = r;
    // smooth polynomial coupling of residual with stream progress
    let coupling = (norm_r * norm_r) * (1.0 + progress) * 12.0
                 - norm_r * (1.0 - progress) * 8.0;
    score += coupling;
    // reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_r;
    score -= tightness * tightness * (4.0 + 6.0 * progress);
    // last-chance bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }
    // penalize new bin opening when open bins fit, more so late in stream
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 6.0 + 10.0 * (1.0 - progress);
    }
    // lookahead: reward residual matching next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let d = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 5.0 * (1.0 - d);
    }
    // mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05 * norm_r;
    score += (mean_residual - r) * 0.1;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Small post residuals are dead space; large residuals can host future items.
    let pr = post_residual as i64;
    let cap = bin_capacity as f64;

    // Class thresholds via integer division (harmonic classes of capacity fractions)
    let class = pr / 10; // classes 0..=10
    match class {
        0 => score += 60.0,             // 0..9: near-perfect fit, strongly reward
        1 => score -= 25.0,             // 10..19: excellent
        2 => score -= 12.0,             // 20..29: good
        3 => score -= 5.0,              // 30..39: decent
        4 => score += 3.0,              // 40..49: neutral-ish
        5 => score += 8.0,              // 50..59: half-empty, mild penalty
        6 => score += 14.0,
        7 => score += 20.0,
        _ => {}                          // mostly empty: base residual already dominates
    }

    // Modulo coupling: residuals that are "awkward" (prime-ish gaps like 1,2,3 mod small moduli)
    // are hard to fill with typical items; penalize tiny awkward leftovers extra.
    if pr > 0 && pr < 10 {
        let awkward = pr % 7 == 1 || pr % 7 == 2 || pr % 5 == 3;
        if awkward { score += 15.0; }
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size as i64 == pr {
            score -= 40.0;
        } else if (next_item_size as i64) < pr && (pr - next_item_size as i64) <= 10 {
            score -= 20.0;
        } else if (next_item_size as i64) < pr && (pr - next_item_size as i64) <= 25 {
            score -= 8.0;
        } else if next_item_size as i64 > pr {
            // next item won't fit here; residual risks becoming dead space
            let waste = pr as f64;
            score += 0.25 * waste;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate: opening a new bin is wasteful if any open bin fits; penalize,
    // but relax when open bins are very full (mean residual small) or late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        let mut nb = 70.0 + 10.0 * open_pressure;
        // if mean residual of open bins is tiny, a fresh bin is actually reasonable
        nb -= 1.2 * mean_residual.max(0.0);
        nb -= 20.0 * progress;
        score += nb.max(0.0);
    }

    // Mild preference to pack into fuller bins overall (tighten packing as stream progresses).
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= 6.0 * fill;

    // Tie-break: slight noise-free deterministic jitter based on step to break symmetry
    score -= ((step_index % 13) as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small for the
    // minimum plausible future item (>= 1..=10) are pure waste.
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            (10 - post_residual) as f64 * 8.0
        } else if post_residual < 20 {
            (20 - post_residual) as f64 * 3.0
        } else {
            0.0
        };
        score += dead;
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins are
    // crowded or the fit here would leave a nasty gap.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = open_bins_count as f64 * 2.5;
        let gap_penalty = if post_residual < 10 { 30.0 } else { 0.0 };
        score += 15.0 + pressure - gap_penalty;
        // Lookahead: if the next item fits the residual of this fresh bin
        // alongside the current one, opening a new bin is fine.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
        }
    } else {
        // Existing bin whose residual can host the next item too: reward.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 6.0;
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 10.0; // this bin becomes dead space for the lookahead
        }
    }

    // Mild preference to keep many open bins consolidated when mean
    // residual is low (bins are nearly full).
    if mean_residual < 15.0 && !is_new_bin {
        score -= 8.0;
    }

    // Slight time decay: early on, be a bit more conservative about
    // filling bins tightly (future items unknown).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: reward exact match of post_residual with next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            // perfect 2-step fit: consume bin completely over two items
            score -= 60.0;
        } else if post_residual as f64 >= nxt {
            // next item still fits here: mild reward proportional to tightness
            let tight = 1.0 - ((post_residual as f64 - nxt) / bin_capacity as f64);
            score -= 25.0 * tight;
        } else {
            // next item won't fit: penalize proportionally to leftover dead space
            let waste = (nxt - post_residual as f64) / bin_capacity as f64;
            score += 15.0 * waste;
        }
    } else {
        // last item: strongly prefer tightest residual
        score -= 40.0;
    }

    // --- relative-to-mean coupling: prefer bins with residuals below mean (already tight) ---
    let dev = (post_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 20.0 * dev;

    // --- last-chance bin: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // --- many open bins: encourage consolidation into existing bins ---
    if open_bins_count > 2 {
        score -= 5.0 * ((open_bins_count as f64).ln());
    }

    // --- stream progression: later in the stream, be greedier about tight fits ---
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // --- new-bin candidate: penalize opening a new bin unless current fit is terrible ---
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        // empty bin leaves residual = capacity - item; only attractive if item is huge
        score += 35.0 * (1.0 - item_size as f64 / bin_capacity as f64);
        if poor_fit < 0.2 {
            score -= 20.0; // near-perfect fill of a fresh bin
        }
    }

    // --- tiny dead space bonus: residuals of 0..=3 are ideal closures ---
    if post_residual <= 3 {
        score -= 45.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post-residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - tightness * tightness);

    // Exact fill is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead synergy: if next item fits the post-residual, strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 15.0 * (1.0 - (slack_after_next as f64) / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Penalize creating residual smaller than the next item (dead space risk),
        // scaled by how far below the next item the residual falls.
        let gap = (next_item_size - post_residual) as f64;
        score += 0.25 * gap;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins have poor average fit
    // or the item is large relative to typical residuals.
    if bin_residual == bin_capacity {
        let mean_fit = if item_size as f64 <= mean_residual { 1.0 } else { 0.0 };
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        // Base cost of a new bin; reduced when open bins are nearly full on average.
        let mut nb = 30.0 - 25.0 * pressure;
        if next_item_size > 0 && next_item_size > mean_residual {
            nb -= 10.0; // next item likely won't fit open bins anyway
        }
        if mean_fit < 1.0 {
            nb -= 8.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        nb += 10.0 * progress;
        score += nb;
    }

    // Mild preference for bins below mean residual (rebalance residuals),
    // avoiding fragmentation concentration.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight penalty for very small unusable leftovers (1..10 dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let next = next_item_size as f64;

    let mut score = post;

    // Non-linear waste term: squared normalized residual scaled by progress
    let norm_post = post / cap;
    score += 30.0 * norm_post * norm_post * (0.5 + progress);

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= 40.0 * (1.0 - norm_post) * (1.0 - norm_post) * (0.3 + 0.7 * progress);

    // Penalize if post residual cannot hold the next item (dead space risk)
    if next > 0.0 {
        if post < next {
            score += 12.0 * (next - post) / cap;
        } else {
            // Reward bins that can still accommodate the lookahead item
            score -= 8.0 * (post - next) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Many open bins: prefer consolidating into existing bins (avoid bin sprawl)
    score += 3.0 * open_bins_count as f64 * norm_post;

    // Bin far from mean residual: slight penalty to keep residuals homogeneous
    let dev = (post - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // New empty bin candidate: penalize unless item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - item / cap) * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions
    let cap: u32 = bin_capacity;
    let half = cap / 2;   // 50
    let third = cap / 3;  // 33
    let quarter = cap / 4; // 25

    // Reward near-perfect fills (post_residual in low harmonic classes)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= quarter {
        score -= 25.0;
    } else if post_residual <= third {
        score -= 10.0;
    } else if post_residual <= half {
        score -= 3.0;
    }

    // Penalize dead space: post_residual that no plausible item (1..100) can fill well
    // Items in awkward band (post_residual < 10 but > 0) are pure waste
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Modulo classes: residuals that are multiples of common item sizes are reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 40.0;
        } else if slack <= quarter {
            score -= 15.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > post_residual {
        // Next item cannot use this residual: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.25;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline, penalize when open bins have tight fits
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the mean residual spread across open bins
        score += 15.0 + mean_residual * 0.35;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // Late in stream, prefer closing out open bins rather than opening new ones
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // Crowding pressure: many open bins -> prefer filling existing ones
    score += open_bins_count as f64 * 0.05;

    // Distance from mean residual: prefer bins tighter than average
    score += ((post_residual as f64) - mean_residual).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 60.0; // tiny gap = wasted capacity
        } else if post_residual <= 20 {
            score += 25.0;
        } else if post_residual <= 35 {
            score += 8.0;
        } else {
            score -= 10.0; // large residual is reusable
        }
    } else {
        score -= 80.0; // perfect fit, strongly favored
    }

    // Reward tight fits relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Open-bin pressure: prefer consolidating when many bins are open.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive if it enables a good pairing
    // with the lookahead item (next item fills ~half or more of fresh bin).
    if bin_residual == bin_capacity {
        if next_item_size > 0 {
            let pair = item_size as f64 + next_item_size as f64;
            if pair >= bin_capacity as f64 * 0.85 {
                score -= 55.0; // pair likely fills a new bin well
            } else {
                score += 40.0; // avoid scattering into new bins
            }
        } else {
            score += 70.0; // last item: never open a new bin
        }
    }

    // Lookahead: if this bin's post_residual exactly fits next item, big bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0; // keep room for the next item
    } else if next_item_size > 0 && post_residual > 0 {
        score += 15.0; // residual too small for lookahead: dead space risk
    }

    // Late in the stream, be more conservative about spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize any residual that is small but nonzero (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit: post_residual exactly matches the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into the post-residual space (2-step chain placement).
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // Next item does NOT fit into this bin after placement: penalize,
    // scaled by how much the next item overshoots the residual.
    else if next_item_size > 0 {
        let overshoot = (next_item_size - post_residual) as f64;
        score += 10.0 + overshoot * 0.4;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Compare residual against the mean residual across open bins:
    // prefer bins whose residual is below average (tighter bins get filled first).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: neutral baseline, slightly above well-matched open bins,
    // but attractive when the current item would leave a very poor fit elsewhere.
    if bin_residual == bin_capacity {
        score = 45.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Early in the stream, be slightly more willing to keep bins tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins whose post residual is small.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Exact / near-exact fill bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 30.0;
    } else if post_residual <= 8 {
        score -= 12.0;
    }

    // Penalize dead space that no future item (sizes >= 1) can realistically use:
    // small residuals are fine, mid residuals (awkward gaps) are worse than large ones.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver: nearly dead space, but exact fills handled above
    }

    // Lookahead: if the next item fits in the post residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0 + 0.25 * next_item_size as f64;
        } else {
            score += 8.0;
            // Extra penalty if this bin was the ONLY fitting option (forced choice,
            // better to think about a new bin when the next item won't chain).
            if fitting_bins_count == 1 {
                score += 10.0;
            }
        }
    }

    // Last-chance bonus: if this is the only open bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Spread reward: prefer placing into bins whose residual is above the mean
    // (keeps the residual distribution balanced, preserving flexibility).
    score -= 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Time horizon: early in the stream, be conservative with new bins
    // (many items remain, so keep open bins usable); late in the stream,
    // waste matters more than bin count.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.15 * progress;

    // New-bin candidate handling: opening a new bin is attractive when open bins
    // are crowded (many bins, low mean residual) or the fit is poor.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let poor_fit = item_size as f64 / bin_capacity as f64;
        // Base cost of a fresh bin, discounted when the item is small relative
        // to capacity (small items leave a very usable residual).
        score = 45.0 - 20.0 * crowding - 15.0 * (1.0 - poor_fit);
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // fresh bin can chain the next item too
        }
        if fitting_bins_count == 1 {
            score += 25.0; // don't abandon the last fitting bin trivially
        }
    } else {
        // Mild bonus for using an already-open bin (avoid bin proliferation).
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in the stream, tight packing matters more.
    score *= 1.0 + 0.5 * progress * (1.0 - norm_pr);

    // Lookahead: reward bins whose post_residual can host the next item (chained fits),
    // with a smooth decay as post_residual grows beyond the next item's need.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = (pr - nxt) / cap;
            score -= 12.0 * (1.0 - slack * slack) * (1.0 + 0.5 * progress);
        } else {
            // Post-residual too small for next item: penalize dead space smoothly.
            let dead = (nxt - pr) / cap;
            score += 8.0 * dead * (1.0 + progress);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for spreading across many bins when mean residual is already low
    // (avoid fragmenting); smooth coupling with mean residual.
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap).max(0.0);

    // New-bin candidate: neutral-ish baseline; only win when fits are poor.
    if bin_residual == bin_capacity {
        score += pr * 0.8 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into "useful" bands.
    // Small leftovers (<= 10) are dead space; medium bands pair with common item sizes.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Penalty for unusable dead space (post_residual < 10 means nothing fits).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Harmonic classes via integer division thresholds on post_residual.
    // Classes: [0,10) dead, [10,30) poor, [30,50) fair, [50,100) good.
    let class = post_residual / 20; // 0..5
    score -= match class {
        0 => 0.0,
        1 => 3.0,
        2 => 8.0,
        _ => 15.0,
    };

    // Reward perfect/near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: reward residuals that exactly accommodate the next item (harmonic pairing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 12.0;
            }
        } else {
            // Next item cannot fit here; slight penalty if this bin is the only option.
            if fitting_bins_count == 1 {
                score += 15.0;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying with stream progress.
        score = bin_capacity as f64 - 25.0 * (1.0 - progress);
        // More willing to open new bins late in the stream when many bins exist.
        score -= 5.0 * (open_bins_count as f64).ln().max(0.0) * 0.1;
        // If mean residual across open bins is large, opening a new bin is wasteful.
        score += (mean_residual / 10.0).min(20.0);
        // If current item is large and would leave a bad residual anywhere, new bin is fine.
        if item_size > bin_capacity * 3 / 4 {
            score -= 10.0;
        }
    }

    // Mild tie-breaking: prefer bins whose residual deviates favorably from the mean.
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Small nudge toward tighter bins as the stream progresses (best-fit reinforcement).
    score += 0.1 * (post_residual as f64) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: any leftover gap too small for the minimum
    // item is unusable dead space — penalize it heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement chains nicely — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.5 + 8.0;
    }
    // If next item cannot ever fit the leftover gap (dead space for lookahead),
    // penalize proportionally to wasted space.
    if next_item_size > post_residual && post_residual > 0 {
        score += post_residual as f64 * 0.6;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than fragmenting space further.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins below the mean residual (tighter bins) to consolidate space.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate (empty bin): make it attractive only when the current
    // fit is poor (large post residual) or few bins are open.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score = 20.0 + poor_fit * 80.0 - open_bins_count as f64 * 2.0;
        // Late in the stream, opening new bins is less useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 120.0;
        }
        // Penalize leaving a residual that is too small for the next item
        // (likely dead space) unless it was already near-exact.
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare residual against the mean residual of open bins:
    // prefer bins whose residual is below mean (tighter bins get filled first),
    // keeping looser bins available for future large items.
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.2;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize the brand-new empty bin candidate mildly, but allow it when
    // the item is large and no tight fit is available.
    if bin_residual == bin_capacity {
        score += 50.0;
        if item_size > bin_capacity / 2 && post_residual < item_size / 2 {
            score -= 80.0;
        }
    }

    // Late in the stream, be more conservative with new bins and more
    // aggressive about filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (fitting_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 12.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits the post residual exactly-ish, reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to overshoot.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer zero waste strongly.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in stream, opening new bins is cheaper (more future to amortize).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 18.0 * (1.0 - progress);
        // If many bins already open and mean residual is high, avoid spreading.
        score += 0.05 * open_bins_count as f64;
        if mean_residual > (bin_capacity as f64 - item_size as f64) {
            score += 10.0;
        }
    }

    // Prefer bins whose residual deviates from the mean in a useful way.
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    // Mild preference for filling bins with larger current residual when many bins fit.
    if fitting_bins_count > 2 {
        score += 0.03 * (fitting_bins_count as f64) * (bin_residual as f64 - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let size = item_size as f64;

    // Base: reward tight fits (low post_residual), with a non-linear polynomial
    // coupling of post_residual against stream progress.
    let norm_post = post / cap;
    let mut score = post * (1.0 + 0.8 * progress * norm_post * norm_post);

    // Quadratic dead-space penalty: small post_residual is exponentially valuable.
    score -= 25.0 * (1.0 - norm_post) * (1.0 - norm_post) * (1.0 + progress);

    // Penalize bins whose residual is much larger than the mean (don't burn big bins early).
    score += 0.35 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0 + 30.0 * progress;
    }

    // Lookahead: if the next item fits the post-residual exactly well, reward;
    // if post_residual is too small for the next item (dead space), penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let nx_post = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - nx_post / cap) * (1.0 - nx_post / cap);
        } else {
            score += 8.0 * (nx - post) / cap * (1.0 + progress);
        }
    }

    // Mild pressure to prefer open bins over opening new ones as stream progresses.
    score -= 3.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - progress);

    // Smooth non-linear interaction between item size and residual fill ratio.
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= 10.0 * fill * fill * (size / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on a "nice"
    // residue class (divisible by common small item sizes) are more reusable.
    let pr = post_residual;
    let mut harmony = 0.0f64;
    for &m in &[10u32, 20, 25, 50] {
        if pr >= m && pr % m == 0 {
            harmony += 4.0;
        }
    }
    if pr % 5 == 0 {
        harmony += 1.5;
    }
    score -= harmony;

    // Dead space penalty: tiny leftovers that few item sizes can use.
    if pr > 0 && pr < 10 {
        score += 12.0;
    } else if pr < 20 {
        score += 4.0;
    }

    // Perfect fit is heavily rewarded.
    if pr == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward strongly; if it nearly fits, mild reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            score -= 3.0 + (pr - next_item_size) as f64 * 0.05;
        } else {
            // next item cannot use this bin's leftover: leftover is dead weight
            score += (next_item_size - pr) as f64 * 0.08;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer fuller bins (tight packing) via residual fraction.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 6.0;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else {
            // penalize opening a new bin when open bins exist that fit
            20.0 + mean_residual * 0.1
        };
        // Scale desperation down late in the stream when bins may be abandoned
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += desperation * (1.0 - 0.3 * progress);
        // base cost of a fresh bin
        score += 8.0;
    }

    // Mild stream-phase modulation: pack tighter early, allow slack later.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) strongly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 20.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward leaving room for the next item if it fits exactly in the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + (next_item_size as f64) * 0.1;
    }
    // Penalize if post_residual is too small for the next item but nonzero.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Pressure from number of open bins: prefer filling existing bins when many are open.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize slightly so it is chosen only when fits are bad,
    // but allow it when all open bins would create dead space.
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 0.5;
        if post_residual > 0 && post_residual < 10 {
            score += 0.0; // new bin has full residual, dead-space penalty above already avoided
        }
    }

    // Prefer bins with below-mean residual (tighter bins) slightly.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual exactly
    // matches the next item (perfect chaining), penalize near-misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nxt {
            let diff = pr - nxt;
            if diff == 0.0 {
                score -= 30.0; // perfect chain: next item fills this bin exactly
            } else {
                // penalize leftover that next item can't use well
                score += diff * 0.5;
                if diff < 10.0 {
                    score += 8.0; // tiny dead space unusable for min-size items
                }
            }
        } else {
            // next item cannot fit here; the post residual becomes dead space
            score += (nxt - pr) * 0.3;
        }
    } else {
        // last item: prefer tightest fit
        score -= 20.0;
    }

    // Relative-to-mean coupling: prefer bins with below-average residual
    // (denser bins), i.e. tight fits get priority over airy bins.
    let dev = mean_residual - post_residual as f64;
    score -= dev * 0.4;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating very small unusable residuals (dead space < 10)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Slight preference for reusing bins when many are open (consolidation)
    score += open_bins_count as f64 * 0.05;

    // Late in the stream, be more conservative about opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if it enables a great chain
        if next_item_size > 0 && (bin_capacity as f64 - item_size as f64 - next_item_size as f64).abs() < 1.0 {
            score -= 10.0;
        } else {
            score += 10.0 + 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Penalize dead space that cannot fit a typical next item.
    if post_residual > 0 && (next_item_size == 0 || post_residual < next_item_size) {
        score += 4.0 + 0.15 * post_residual as f64;
    }

    // Lookahead: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_quality = next_item_size as f64 / post_residual as f64;
        score -= 10.0 * chain_quality.min(1.0);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't chain here; slight penalty for wasting the residual.
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Global pressure: many open bins -> consolidate; few -> new bins are cheap.
    let pressure = open_bins_count as f64 / (total_items as f64).max(1.0).sqrt();
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when consolidation is desirable.
        score += 8.0 + 5.0 * pressure;
        // But if mean residual is fragmented and item is large, allow escape.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 10.0;
        }
    } else {
        score += 2.0 * pressure;
    }

    // Time horizon: early on, be flexible; late, pack greedily.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * fit_ratio;
    score += 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins near the mean (balanced packing).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Tight-fit reward: smooth quadratic coupling of post_residual with capacity.
    let tightness = 1.0 - pr / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize large dead space relative to mean residual of open bins.
    let dead = (pr - mean_residual).max(0.0);
    score += 0.15 * dead * dead / cap;

    // Lookahead coupling: reward if next item fits remaining space (smooth term).
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 / cap - pr / cap).max(0.0);
        score += 8.0 * fits_next * fits_next;
    } else {
        // Last item: strongly prefer filling existing space.
        score -= 5.0 * tightness;
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize so it is chosen only when residual is genuinely small
    // (i.e., item nearly fills a fresh bin) or no good alternative exists.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 20.0 - 18.0 * fill * fill;
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Mild pressure to prefer bins with less residual overall as stream progresses.
    score += progress * (pr / cap) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual)
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * waste * waste; // quadratic penalty on relative waste

    // Reward near-perfect fills
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Harmonic classes on post_residual: residues that commonly pair with
    // typical item sizes (multiples of 10) are more reusable.
    let residue_class = post_residual % 10;
    if post_residual > 0 {
        match residue_class {
            0 => score -= 6.0,               // multiples of 10 are highly reusable
            1 | 9 => score -= 4.0,           // nearly-round residuals still flexible
            2 | 3 | 7 | 8 => score += 2.0,   // awkward residues
            _ => score += 4.0,               // mid-class residues (4,5,6) least flexible
        }
    }

    // Integer-division thresholds: residual usable by common small items
    if post_residual >= 50 {
        score -= 5.0; // still half-full, plenty of future use
    } else if post_residual >= 30 {
        score -= 2.0;
    } else if post_residual < 10 && post_residual > 0 {
        score += 8.0; // dead space risk
    }

    // Last chance: only bin that fits -> strong preference to use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
        // exact pairing bonus
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here anyway; slight penalty for wasting residual
        score += 3.0;
    }

    // Prefer filling bins when many bins are open (bin consolidation)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 3 {
        score -= 2.0 * (open_bins_count as f64).ln() * (0.5 + 0.5 * progress);
    }

    // Mean-residual coupling: if this bin's residual is far below mean,
    // it is an outlier worth filling up.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= 0.15 * diff.min(50.0);
    }

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin
        score += 45.0;
        // But if existing fitting options are poor (large min waste implied),
        // new bin becomes competitive: small items into fresh bin is fine.
        if item_size <= 30 {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a bin
        } else if next_item_size > 0 && next_item_size > mean_residual {
            // next item won't fit typical open bins; opening fresh bin helps
            score -= 20.0;
        }
        // Early stream: opening bins is cheaper
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual <= 9 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward keeping residual large enough to be reusable (>= next item size or 10).
    let reusable_threshold = if next_item_size > 0 { next_item_size.min(bin_capacity) } else { 10 };
    if post_residual >= reusable_threshold {
        score -= 8.0;
    }

    // Penalize wasting a large residual on a tiny item (poor utilization).
    if bin_residual > 2 * item_size && bin_residual >= 50 {
        score += (bin_residual - 2 * item_size) as f64 * 0.15;
    }

    // Open-bin pressure: with many open bins, prefer existing bins over new ones.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing else works well.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64) * 0.2;
    }

    // Lookahead: if next item fits in post-residual, reward chaining.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits (tiny post_residual).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this placement chains perfectly -> heavily favor.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 100.0 - (chain_waste as f64) * 3.0;
        } else {
            // next item cannot follow here; penalize leaving awkward gaps
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0 + (item_size as f64) * 0.3;
    }

    // Penalize opening a brand-new bin when decent open bins exist,
    // but allow it when open bins would leave large dead space.
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 { (post_residual as f64).abs() } else { 0.0 };
        score += 150.0
            + (open_bins_count as f64) * 10.0
            - best_possible * 0.5;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 80.0;
    }

    // Relative-to-mean coupling: bins with residual far below mean are tight;
    // placing there is efficient, while bins above mean risk waste.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.4;
    } else {
        score += (res - mean_residual) * 0.2;
    }

    // Discardable small dead space (<10) is nearly worthless; mildly reward
    // creating it rather than leaving medium gaps (15..40) that block items.
    if post_residual >= 15 && post_residual <= 40 {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post residual), scaled non-linearly
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powf(3.0) * 40.0;

    // Penalize dead space: post residual too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 60.0;
    } else {
        // mild penalty when many alternatives exist to encourage spreading
        score += (fitting_bins_count as f64).ln().max(0.0) * 4.0;
    }

    // Lookahead: if next item fits into post_residual, reward heavily
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > post_residual {
        // next item won't fit here anyway; slight penalty if we waste big residual
        score += 0.1 * post_residual as f64;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 100.0;
    }

    // Time horizon: early in stream, be more conservative (prefer filling existing bins);
    // later, tolerate opening bins slightly more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (bin_residual as f64 / bin_capacity as f64);

    // Global state coupling: when mean residual is high, prefer bins below mean
    // (fill the emptiest-feeling bins first to consolidate)
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Many open bins: encourage closing out partially-filled bins
    if open_bins_count > 4 {
        score -= 0.15 * open_bins_count as f64 * (1.0 - fit_ratio);
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 55.0;
        // cheaper to open new bin late in stream or when item is huge
        score -= progress * 20.0;
        if item_size >= 70 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big items coming, fresh bin useful
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress * 1.5) - norm_pr * progress;

    // Reward tight fits, more strongly as stream progresses
    let tight_bonus = -(1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 + 2.0 * progress);

    // Penalize dead space that cannot fit the lookahead item
    let dead = if next_item_size > 0 && pr < next_item_size as f64 {
        (next_item_size as f64 - pr) / cap
    } else {
        0.0
    };

    // Last-chance bonus: strongly prefer the only fitting bin
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -3.0
    } else {
        0.0
    };

    // Slight penalty when bin residual diverges from mean residual
    let div = (bin_residual as f64 - mean_residual).abs() / cap;

    pr + 4.0 * poly + tight_bonus + 2.0 * dead + last_chance + 0.5 * div
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    let mut score = post;

    // Harmonic class of post_residual (decile classes)
    let cls = post_residual % 10;
    score += match cls {
        0 => -8.0,          // perfectly rounded residual: excellent state
        1 | 2 | 3 => 2.0,   // awkward slivers, hard to fill
        4 | 5 | 6 | 7 => 0.0,
        _ => 1.0,
    };

    // Near-perfect fills are heavily rewarded
    if post_residual <= 4 {
        score -= 12.0;
    }
    if post_residual == 0 {
        score -= 10.0;
    }

    // Dead-space band: residual too small for typical items but not zero
    if post_residual > 0 && post_residual < 10 {
        score += 3.0;
    }

    // Harmonic check on next item: exact complement is a gift
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward if next is a "round" size
            if next_item_size % 10 == 0 {
                score -= 4.0;
            }
            // quarter-class complementarity
            let q = (post_residual / 25) * 25;
            if next_item_size as f64 >= q as f64 {
                score -= 2.0;
            }
        } else {
            // next item won't fit here; penalize leaving mid-range residual
            score += 1.5;
        }
    }

    // Last-chance bin among open bins
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 7.0;
    }

    // New-bin candidate handling
    if is_new_bin {
        score += 18.0; // default: prefer existing bins
        // Large items justify fresh bins
        if item_size as f64 > 0.6 * cap {
            score -= 22.0;
        }
        // No open bin can fit: must open
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        // Late in stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
        // Many open bins with high mean residual: reuse them
        if open_bins_count > 3 && mean_residual > 25.0 {
            score += 6.0;
        }
    }

    // Coupling with mean residual: prefer bins tighter than average
    score += (mean_residual - post) * 0.06;

    // Integer-division threshold: post_residual in [10,20) is a good "small item zone"
    if post_residual / 10 == 1 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to be useful are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable gap
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit is ideal
    } else if post_residual < 20 {
        score += 12.0; // marginal gap, likely waste
    }

    // Reward tight fits relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_ratio;

    // Lookahead: favor bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 6.0; // next item can't use this leftover
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage proliferation of bins when residuals are plentiful.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if open bins are fragmented or don't fit well.
        score += 30.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits, must open new bin
        }
        if mean_residual > item_size as f64 * 1.5 {
            score += 20.0; // existing bins have room; opening new bin is wasteful
        }
    } else {
        // Mild preference to fill bins with larger residuals when many bins are open.
        score += 0.05 * open_bins_count as f64;
    }

    // Slight stream-progression tilt: later in the stream, be greedier about perfect fits.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if post_residual == 0 {
            score -= 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // reward proportionally to how well next item fits the leftover
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * next_fit;
        } else {
            // next item cannot use the leftover: penalize dead space
            let waste = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 15.0 * waste;
        }
        // Perfect pairing: item + next item exactly fills the bin
        if item_size + next_item_size == bin_residual {
            score -= 20.0;
        }
    }

    // Penalize bins far from the mean residual (keeps bin profile uniform),
    // unless this bin is a tight fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (1.0 - tightness);

    // Last-chance bonus: if this is the only bin that can fit the item, prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when item is large (little leftover waste)
    // and few bins are open; otherwise discourage spreading.
    if bin_residual == bin_capacity {
        let waste_frac = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * waste_frac;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
        score += open_bins_count as f64 * 2.0;
    }

    // Late in the stream: consolidate into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual already does most of this; sharpen it.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 10.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it, otherwise we open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item also fits in the leftover space, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            // chain fit quality: leftover after hypothetical next placement
            let chain_left = post_residual as f64 - next_item_size as f64;
            score -= 4.0 * (chain_left / bin_capacity as f64);
        } else if next_item_size <= bin_residual {
            // next item fits this bin only if we place current item elsewhere -> mild penalty
            score += 3.0;
        }
    }

    // Penalize creating dead space that nothing (min size 1..10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate: default penalty (it has large post_residual anyway),
    // but relax it when no open bin fits well.
    if bin_residual == bin_capacity {
        let mut penalty = 30.0;
        if fitting_bins_count == 1 {
            penalty = 5.0;
        }
        if fitting_bins_count == 0 {
            penalty = -5.0;
        }
        // Late in the stream, prefer closing out open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        penalty += 15.0 * progress;
        score += penalty;
    }

    // Mild pressure to spread load across open bins when they are full-ish.
    score += 0.03 * open_bins_count as f64;
    score -= 0.02 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;

    let mut score = pr + 12.0 * poly * cap;

    // Reward tight fits, more strongly late in the stream.
    score -= (1.0 - norm_pr) * (1.0 + progress) * 6.0;

    // Penalize dead space relative to mean residual.
    score += 0.15 * (pr - mean_residual) * (1.0 - progress);

    // Lookahead: favor bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 8.0 * (1.0 - pr / cap) * (nx / cap);
        } else {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bonus: avoid opening new bins when only one fits.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Mild preference for consolidating across many open bins.
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residues modulo 10 create dead-space classes
    let pr = post_residual;
    let class = (pr % 10) as f64;
    score += class * 0.8;

    // Small unusable leftovers (dead space) penalized super-linearly
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 2.0;
    }

    // Lookahead coupling: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: reward proportionally to tightness
            let tight = 1.0 - (pr - next_item_size) as f64 / cap;
            score -= 20.0 + 15.0 * tight;
        } else {
            // next item would need another bin: mild penalty
            score += 8.0;
        }
        // harmonic class match: next_item_size class equals post_residual class
        if pr > 0 && (next_item_size % 10) == (pr % 10) && next_item_size <= pr {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer filling bins with small residual relative to mean residual
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Fraction of capacity filled: reward high fill ratio
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= 25.0 * fill * fill;

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - fill);

    // Many open bins: prefer closing them out (favor low post_residual harder)
    if open_bins_count > 4 {
        score += 0.3 * (open_bins_count as f64 - 4.0) * (post_residual as f64 / cap);
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are terrible
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // new bin can host next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space harshly (gaps that fit almost nothing).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Dead space in (10, 20) is also fairly useless for typical item sizes.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current bin fit is poor or open bins are few.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * 0.5;
        score += 20.0 + pressure;
        if post_residual as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Open-bin pressure: fewer open bins -> prefer consolidating into existing bins.
    score += open_bins_count as f64 * 0.3;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
    }
    // If next item would leave this bin's leftover even tighter, mild penalty.
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 10 {
        score += 5.0;
    }

    // Slight preference to fill bins earlier in the stream (keep bins tighter).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: small post_residual relative to bin capacity.
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness;

    // 2-step lookahead: reward if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain fill
        } else if next_item_size < post_residual {
            // next item fits: penalize leftover after the chain placement
            let chain_left = post_residual - next_item_size;
            score += 0.35 * chain_left as f64;
            if chain_left <= 5 {
                score -= 25.0; // near-perfect two-item chain
            }
        } else {
            // next item won't fit here: penalize large dead space
            let gap = next_item_size - post_residual;
            score += 0.25 * gap as f64;
        }
    }

    // Penalize bins deviating above mean residual (fragmented bins).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);
    // Slight reward for bins below mean residual (consolidating fuller bins).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: make empty bin costly unless open bins are crowded.
    if bin_residual == bin_capacity {
        score += 30.0;
        // If many open bins but few fit, opening a new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
        // Late in the stream, prefer reusing open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Mild penalty for opening many bins overall.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 60.0;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // next item won't fit here; penalize leaving very small residuals (dead space)
            if post_residual < 10 && post_residual > 0 {
                score += 25.0;
            }
        }
    } else {
        // Last item: prefer exact fill
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when decent alternatives exist
    if bin_residual == bin_capacity {
        score += 45.0;
        if fitting_bins_count > 0 {
            score += (fitting_bins_count as f64) * 5.0;
        }
        // Early in the stream, opening new bins is cheaper (more future items to fill it)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 30.0;
        // If mean residual of open bins is large, opening new bin is wasteful
        score += mean_residual * 0.3;
    } else {
        // Prefer bins with residual close to mean (balanced usage), slight effect
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Prefer fuller bins slightly
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Penalize extremely large open-bin count (encourage consolidation)
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * (1.0 - pr_norm);
    score += 30.0 * poly;

    // Reward tight fits, more strongly early in the stream
    score -= (1.0 - pr_norm) * (1.0 - progress) * 12.0;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 8.0 + 10.0 * progress;
    } else if next_item_size > 0 {
        let slack = pr - next_item_size as f64;
        score += 0.05 * slack * slack / cap;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - pr_norm);
    }

    // Mild preference for bins below mean residual (balance)
    score += 0.02 * (mean_residual - pr) * (1.0 - progress);

    // New-bin candidate: penalize mildly unless post residual is large
    if bin_residual == bin_capacity {
        score += 5.0 - 20.0 * (1.0 - pr_norm) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small unusable" classes are rewarded (dead space minimized).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Classify post_residual via integer division thresholds.
    if post_residual == 0 {
        score -= 60.0; // perfect fit, ideal
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect, dead space negligible
    } else if post_residual <= 20 {
        score -= 10.0; // still potentially fillable by small items
    } else if post_residual <= 40 {
        score += 5.0; // awkward mid-class leftover
    }

    // Modulo arithmetic: residuals divisible by common item granularities
    // (multiples of 10, 5) are more reusable.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic match: next item's class aligns with leftover
            let gap = post_residual - next_item_size;
            score -= 12.0 - (gap as f64).min(12.0) * 0.5;
        } else {
            score += 6.0; // lookahead breaks this bin's usefulness
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize spreading across many open bins mildly; encourage consolidation.
    score += open_bins_count as f64 * 0.3;

    // Late in the stream, tighten packing (avoid new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0;

    // New-bin candidate handling: empty bin should only win when the fit
    // into existing bins is poor (large post_residual) or few options exist.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 35.0;
        // Less penalty late in stream if open bins are crowded.
        score -= progress * 5.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative: new bin is necessary
        }
        if mean_residual > 0.0 && frac > mean_residual / cap {
            score += 10.0; // would create a worse-than-average residual
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 5.0; // empty bin can't help next item either
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space strongly (non-linear).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Penalize opening a new bin when other bins fit, unless the fit is bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        if fitting_bins_count > 0 && post_residual >= 20 {
            score += 45.0 + open_bins_count as f64 * 2.0;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bonus: prefer using the only bin that fits.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > post_residual && next_item_size > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open bins pressure: mild penalty scaling with number of open bins to encourage consolidation.
    score += open_bins_count as f64 * 0.8;

    // Slight preference for filling bins with larger residuals early in stream.
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // next item can also fit here; mild reward scaled by slack
            score -= 5.0 + (post_residual - next_item_size) as f64 * 0.05;
        } else {
            // next item won't fit; penalize wasted residual relative to next item
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.3;
        }
    }

    // Compare post_residual to mean residual: avoid creating outlier dead space
    score += (post_residual as f64 - mean_residual).abs() * 0.1;

    // Last-chance bin bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins fit well
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost plus escalation with number of open bins
        score += 25.0 + open_bins_count as f64 * 2.0;
        // but if next item is large and no bin would chain, allow new bin
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 10.0;
        }
    }

    // Late-stream tightening: prefer compact fits as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tight * tight;

    // Penalize wasting a large residual on a small item (dead space creation).
    let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 6.0 * waste * waste;

    // Lookahead: if the next item CANNOT fit in the post-residual, this placement
    // is safe (bin is dead anyway) -> reward. If the next item fits exactly well,
    // slight penalty to keep room for it unless this is a near-perfect fit.
    if next_item_size > 0 {
        if (next_item_size as u64) > (post_residual as u64) {
            score -= 3.0;
        } else {
            let next_tight = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score += 2.5 * (1.0 - next_tight);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the item is large relative to capacity or existing bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / bin_capacity as f64 } else { 0.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 / bin_capacity as f64;
        // Reward new bin when fragmentation is high or item is large.
        score -= 14.0 * large_item * large_item + 10.0 * fragmentation * fragmentation;
        // Early in the stream, slightly discourage hoarding open bins.
        score += 5.0 * (1.0 - progress) * (open_bins_count as f64 / 20.0).min(1.0);
    } else {
        // Mild bonus for consolidating into already-open bins when many are open.
        score -= (open_bins_count as f64).ln().max(0.0) * 0.4;
    }

    // Prefer bins whose residual deviates favorably from the mean (use the outliers).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear coupling of post-residual with stream progress
    score -= 12.0 * (norm_pr * (1.0 - norm_pr)) * (1.0 + progress);

    // Reward tight fits more as stream progresses
    score -= 20.0 * (1.0 - norm_pr).powi(2) * (0.5 + progress);

    // Penalize large dead space quadratically, scaled by open bins pressure
    score += 0.05 * norm_pr * norm_pr * (open_bins_count as f64).sqrt();

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead coupling: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_next = if pr as f64 >= next_item_size as f64 { 1.0 - (nx / (norm_pr + 1e-9)).powi(2) } else { -1.0 };
        score += 8.0 * (1.0 - progress) * fit_next;
    }

    // Mean residual alignment term (smooth deviation penalty)
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // New-bin candidate handling: make empty bins attractive only for large items / late stream
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - fit) * (1.2 - progress) + 5.0 * (open_bins_count as f64 / (1.0 + progress));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongest reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space analysis against the lookahead item (harmonic threshold logic).
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            // Residual is unusable by the next item -> penalize dead space.
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.2;
        } else {
            // Residual can still host the next item -> mild reward scaled by slack.
            score -= (post_residual - next_item_size) as f64 * 0.1;
        }
    }

    // Harmonic classes on post_residual: residuals divisible by coarse
    // granularity (25) or fine granularity (10) are more reusable.
    if post_residual > 0 {
        if post_residual % 25 == 0 {
            score -= 8.0;
        } else if post_residual % 10 == 0 {
            score -= 4.0;
        } else if post_residual % 5 == 0 {
            score -= 2.0;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a bin is expensive when other
    // bins fit, but mandatory when none do.
    if bin_residual == bin_capacity {
        score += 60.0 + 0.3 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Prefer filling fuller-than-average bins (larger residual => higher score).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // Stream progression: early on, tolerate opening bins slightly more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold even the
    // smallest plausible future item are pure waste; punish them hard.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += dead * (bin_capacity as f64) * 2.5;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) * (bin_capacity as f64 - post_residual as f64) / (bin_capacity as f64);
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this placement (perfect chain).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            // next item cannot use this residual: mild penalty proportional to gap
            score += (next_item_size as f64 - post_residual as f64) * 0.3;
        }
    }

    // Open-bin pressure: prefer consolidating into existing bins when many
    // bins are already open; makes new-bin candidate less attractive.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Mean residual coupling: if this bin's residual is well below the mean,
    // it is a "tight" bin worth using up.
    score -= (mean_residual - bin_residual as f64).max(0.0) * 0.5;

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Make the empty bin moderately expensive.
    if bin_residual == bin_capacity {
        score += 55.0 + open_bins_count as f64 * 2.0;
        // Late in the stream, keep consolidating even more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (non-linear).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0 - (post_residual as f64) * 10.0;
    }

    // Aggressive 2-step lookahead: if the next item exactly fills the post
    // residual, this is a chain fit -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            // Next item fits here afterwards: mild reward proportional to
            // how tight the two-step packing is.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item will NOT fit after this placement: penalize, but
            // less if the post residual is still generally useful.
            score += 0.3 * ((next_item_size - post_residual) as f64);
        }
    }

    // Relative-to-mean coupling: bins with residual well below mean are
    // "nearly full" -> prefer using them up (avoid many half-empty bins).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.5 * (mean_residual - res);
    } else {
        score += 0.3 * (res - mean_residual);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when the current item is
    // large relative to capacity (poor fits elsewhere would waste space).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty: opening bins is costly.
        score += 70.0;
        // Reward opening when item is big (little room would remain anyway)
        // and few bins fit the item (fragmentation risk elsewhere).
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score -= 80.0 * fill_frac * fill_frac;
        if fitting_bins_count <= 2 && item_size > bin_capacity / 2 {
            score -= 50.0;
        }
        // Late in the stream, avoid spawning bins for small leftovers.
        let progress = step_index as f64 / total_items as f64;
        if progress > 0.9 && item_size < 30 {
            score += 60.0;
        }
    }

    // Mild preference to consolidate into fewer bins as stream progresses.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual, especially in mid-range dead zones.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score -= 8.0; // tiny leftovers are almost perfect fits
    } else if pr >= 10.0 && pr <= 30.0 {
        score += 6.0; // classic dead zone: residual too small for typical items
    }

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + next_item_size as f64 * 0.05;
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        // next item won't fit here anyway; slight penalty if we leave a big hole
        score += pr * 0.05;
    }

    // New-bin candidate handling: empty bin gets a moderate default score so it's
    // chosen only when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score = 55.0
            - 0.1 * open_bins_count as f64
            + 0.05 * (100.0 - item_size as f64);
        // late in the stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 4.0;
        }
        return score;
    }

    // Prefer bins below mean residual (consolidating space) when many bins are open.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: as stream progresses, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - pr / bin_capacity as f64);

    // Crowding: with many open bins, discourage spreading into loose fits.
    if open_bins_count > 4 {
        score += 0.02 * (open_bins_count as f64 - 4.0) * pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Base preference: tighter fit (small post_residual), non-linearly sharpened over time.
    let tightness = 1.0 - (post / cap);
    score -= tightness * tightness * cap * (0.5 + 0.8 * progress);

    // Penalize dead space that is small but unusable by the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt && post > 0.0 {
            let waste_ratio = post / nxt;
            score += 12.0 * (1.0 - waste_ratio) * (1.0 - waste_ratio) * (1.0 + progress);
        }
        // Reward leaving exactly the room the next item needs (chain fit).
        if (post - nxt).abs() < 1.0 {
            score -= 8.0;
        }
    } else {
        // Last item: pure tightness matters most.
        score -= tightness * cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty when many bins are open and this bin is already fragmented.
    let frag = (bin_residual as f64 / cap - mean_residual / cap.max(1.0)).abs();
    score += 3.0 * frag * (open_bins_count as f64).sqrt() * (0.3 + 0.7 * progress);

    // New-bin candidate: acceptable early or when item barely fits anything;
    // otherwise discourage opening new bins when a decent fit exists.
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        let poor_fit = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
        score = cap * (0.35 * early + 0.55) - 30.0 * poor_fit * early;
        // Late in stream, opening a new bin is costly unless item is large.
        score += (item_size as f64 / cap) * 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual (integer division buckets) ----
    // Small classes are "dead space" classes; large classes remain reusable.
    let cls = post_residual / 10; // 0..=10 harmonic classes
    score += match cls {
        0 => 0.0,                          // near-perfect fit
        1 => 4.0,                          // 10..19: fits only tiny items
        2 => 8.0,                          // 20..29
        3 => 10.0,
        4 => 9.0,                          // 40..49: still broadly reusable
        5 => 7.0,                          // ~half bin
        6 => 6.0,
        7 => 5.0,
        8 => 4.0,
        9 => 3.0,
        _ => 0.0,                          // empty-ish bin
    };

    // ---- Lookahead: does next_item_size fit into post_residual? ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward: this bin chains with the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 + 0.05 * slack;
            // Harmonic pairing bonus: next item lands in a clean class.
            let ncls = (post_residual - next_item_size) / 10;
            if ncls <= 1 { score -= 3.0; }
        } else {
            // Penalize leaving a residual that the lookahead cannot use.
            let miss = (next_item_size - post_residual) as f64;
            score += 0.08 * miss.min(40.0);
        }
    }

    // ---- Last-chance bin: if this is the only fitting bin, use it ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin wastes the residual of existing bins.
        // Only attractive when item leaves a large reusable remainder
        // or when existing bins are badly fragmented.
        score += 18.0;
        score -= 0.10 * post_residual as f64;
        if open_bins_count == 0 { score -= 30.0; }
        if mean_residual > 45.0 { score -= 8.0; } // plenty of slack elsewhere? no—slack elsewhere means no need for new bin
        if mean_residual < 15.0 && post_residual >= 30 { score -= 10.0; }
    }

    // ---- Tightness reward: prefer bins where item fills most of residual ----
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill;

    // ---- Exact / near-exact fit bonus ----
    if post_residual == 0 { score -= 25.0; }
    else if post_residual <= 5 { score -= 12.0; }

    // ---- Fragmentation guard: avoid leaving 1..9 dead space unless exact ----
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // ---- Mild phase scaling: early stream, be pickier about new bins ----
    let phase = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - phase);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest item (1) don't exist,
    // but residuals below a "useful threshold" (e.g. < 20) are likely unusable dead space.
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        // heavily penalize near-full bins only if the gap is truly wasted;
        // actually a very small post_residual means a good fit, so reward instead.
        score -= 30.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Penalize large leftover gaps that no plausible item can fill tightly:
    // if post_residual is large but next_item_size doesn't fit well into it.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        let nxt = next_item_size as f64;
        if nxt <= gap {
            // slack after placing next item into this bin's residual
            let slack = gap - nxt;
            score += 0.5 * slack;
        } else {
            // next item cannot fit here at all -> this residual will be dead
            score += 0.3 * gap;
        }
    }

    // Prefer bins that are already fairly full (small residual before placement)
    score += 0.2 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    // Last chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, gets this penalty).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 20.0 * (open_bins_count as f64 / 10.0).min(2.0) + 10.0 * progress;
    } else {
        score -= 2.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean (fuller bins)
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches next item size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Reward tight two-item fits (post_residual close to next_item_size)
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Penalize dead space unusable by the next item
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: minimize leftover as usual
        score += 0.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: mildly discourage opening new bins unless residual is very poor
    if bin_residual == bin_capacity {
        score += 18.0 + 0.1 * item_size as f64;
        // Late in the stream, opening new bins is more costly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Penalize creating tiny unusable residuals (< 10, minimum item size)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize dead space that becomes unusable for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post residual, reward; else penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 10.0;
        } else if next_item_size > post_residual as u32 && post_residual > 0 {
            score += 6.0;
        }
        // Perfect pairing: item + next item exactly fills bin.
        if item_size + next_item_size == bin_residual {
            score -= 30.0;
        }
    }

    // New-bin candidate logic: opening a new bin is fine early or when open bins are crowded.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base new-bin score: slightly worse than a decent fit.
        score = bin_capacity as f64 * 0.55 + 10.0 * (1.0 - progress);
        // If mean residual is small (bins nearly full), new bin is attractive.
        score -= mean_residual * 0.35;
        // If many bins can fit, discourage new bin.
        score += 8.0 * (fitting_bins_count as f64).min(5.0);
        // Late in stream, prefer closing out existing bins.
        score += 25.0 * progress;
    }

    // Prefer bins with below-mean residual (concentrate waste in few bins).
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Mild pressure to keep number of open bins low.
    score += 0.4 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // waste is penalized more as the stream advances.
    let poly = norm_pr * norm_pr * (0.5 + progress) + norm_pr * progress * progress;
    score += 40.0 * poly;

    // Perfect fit reward.
    if pr == 0.0 {
        score -= 100.0;
    } else {
        // Reward small post-residuals that could still hold a plausible item.
        let lookahead_bonus = if next_item_size > 0 && next_item_size as f64 <= pr {
            25.0 * (1.0 - pr / (next_item_size as f64 + pr))
        } else if next_item_size == 0 {
            15.0
        } else {
            // Dead space relative to lookahead item.
            10.0 * ((next_item_size as f64 - pr) / cap).min(1.0)
        };
        score -= lookahead_bonus;
    }

    // Last chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress * 0.5);
    }

    // Prefer bins tighter than average; mildly penalize opening new bins late.
    score -= 0.3 * (mean_residual - pr);
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: dead space that is a "nice" fraction
    // of capacity is more reusable than awkward remainders.
    let pr = post_residual as u32;
    let class_bonus = if pr == 0 {
        -30.0
    } else if pr % 10 == 0 {
        -6.0
    } else if pr % 5 == 0 {
        -3.0
    } else {
        4.0
    };
    score += class_bonus;

    // Integer-division thresholds: reward placements leaving room for common
    // small-item classes (<= post_residual via division buckets).
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead fits: reward proportionally to how well it fills
            let fill = next_item_size as f64 / (pr as f64 + 1.0);
            score -= 8.0 * fill;
            // harmonic bonus if next item leaves another round-class residual
            let next_pr = pr - next_item_size;
            if next_pr % 10 == 0 { score -= 4.0; }
        } else {
            score += 6.0;
        }
    } else {
        // last item: strongly prefer zero-waste
        score -= 10.0 * (pr as f64 / cap);
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // and many bins are already open with fragmented residuals.
    if bin_residual == bin_capacity {
        let fragmentation = if mean_residual > 0.0 { mean_residual / cap } else { 0.0 };
        score = 55.0 + 25.0 * (1.0 - fragmentation) - 20.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0));
        if fitting_bins_count == 0 { score -= 40.0; }
    }

    // Mild phase-aware pressure: early stream, consolidate aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / cap);

    // Penalize awkward residuals relative to mean residual of open bins.
    if post_residual as f64 > mean_residual && mean_residual > 0.0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly unusable for items >= 10.
    let dead_zone = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_zone {
        score += 40.0 * (dead_zone - post_residual as f64) / dead_zone;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fit reward
    }

    // Reward residual that can host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && next_item_size > bin_residual {
        // next item won't fit anywhere in this bin anyway; filling it is good
        score -= 3.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.8 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Deviation from mean residual: prefer bins whose residual is close to item need.
    let fit_tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * fit_tightness;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when no decent fit exists among open bins.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            // penalize new bins, more so when an open bin fits well (post_residual small)
            let best_gap_bonus = if post_residual > 0 && (post_residual as f64) < dead_zone { 0.0 } else { 10.0 };
            score += 15.0 + best_gap_bonus + 0.5 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly matches post_residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next == post {
            score -= 25.0; // perfect chain: next item fills this bin completely
        } else if next <= post {
            // reward tighter matches; residual after the hypothetical next placement
            let chain_residual = post - next;
            score -= 12.0 * (1.0 - chain_residual / bin_capacity as f64);
            // penalize leaving a chain residual that is awkward (small but nonzero)
            if chain_residual > 0.0 && chain_residual < 10.0 {
                score += 6.0;
            }
        } else {
            // next item cannot fit here: penalize proportionally to mismatch
            score += 3.0 + (next - post) * 0.05;
        }
    }

    // Penalize post_residual being large relative to mean residual (wasteful bin)
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Reward using a bin whose residual was already small (tight fit)
    score -= 0.4 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 5.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Prefer reusing existing bins over opening new ones as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress; // new-bin candidate penalty grows over time
    } else {
        score -= 2.0 * progress;
    }

    // Slight bonus for packing into bins with many open bins (consolidation)
    score -= 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space that next item cannot use.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0; // dead space for lookahead
        } else if post_residual >= next_item_size {
            score -= 4.0; // lookahead fits in leftover
        }
    }

    // Last-chance bin: strongly favor using it to avoid fragmentation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin, more when open bins fit well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 18.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            new_bin_penalty += 8.0 * (fitting_bins_count as f64).sqrt();
        }
        // Open a new bin if mean residual of open bins is very small (all poor fits).
        if mean_residual < item_size as f64 * 0.35 && fitting_bins_count > 0 {
            new_bin_penalty -= 14.0;
        }
        score += new_bin_penalty;
    } else {
        // Mild preference for fuller bins over emptier ones.
        score += 0.05 * (mean_residual - bin_residual as f64);
        // Slight penalty for spreading across too many bins.
        score += 0.02 * open_bins_count as f64;
    }

    // Late in stream: consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    // Base: penalize leftover space, with non-linear coupling to stream progress.
    // Early on, prefer leaving room (lower penalty for moderate residual);
    // later, prefer tight fits (residual penalized more strongly).
    let mut score = r * (1.0 + 0.8 * progress) + 12.0 * rn * rn * (1.0 - progress);

    // Reward tight fits more aggressively as the stream progresses.
    score -= 10.0 * (1.0 - rn) * (1.0 - rn) * (0.5 + progress);

    // Exact fit bonus (post_residual == 0), amplified late in the stream.
    if post_residual == 0 {
        score -= 15.0 + 10.0 * progress;
    }

    // Last-chance bin: strong reward to use it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 9.0;
    }
    // If next item would not fit here, mildly penalize wasting residual early.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0 * rn * (1.0 - progress);
    }

    // Prefer bins with below-average residual (tighter bins) via smooth coupling.
    score += 0.15 * (mean_residual - r);

    // Mild penalty for accumulating many open bins.
    score += 0.02 * open_bins_count as f64;

    // New-bin candidate: keep it competitive only when residuals are messy.
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * progress * rn;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact-fill classes are gold.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else if pr <= 10 {
        score -= 60.0;   // near-perfect dead space is tiny
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of
    // common small item sizes are reusable "harmonic" slots.
    let harmonic = ((pr % 10 == 0) as i32) * 2 + ((pr % 5 == 0) as i32) + ((pr % 20 == 0) as i32);
    score -= harmonic as f64 * 8.0;

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size < pr {
            let after = pr - next_item_size;
            score -= 20.0 - (after as f64).min(20.0);
        } else {
            // next item cannot use this residual: penalize wasting space the
            // lookahead could have consumed elsewhere
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Many open bins with high mean residual: discourage fragmenting further.
    if open_bins_count > 3 && (post_residual as f64) < mean_residual * 0.5 {
        score += 25.0;
    }

    // New-bin candidate: make empty bins unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if the item is huge relative to capacity, opening fresh is fine.
        if item_size * 5 >= bin_capacity * 4 {
            score -= 100.0;
        }
    }

    // Early stream: slightly prefer compacting into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any plausible
    // future item (sizes >= 1, but practically small gaps are waste) are
    // heavily penalized, super-linearly as the gap shrinks.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // unusable-zone penalty: strongest for tiny gaps, fades to 0 at gap >= 30
        let unusable = ((30.0 - gap.min(30.0)) / 30.0).powi(3);
        score += 60.0 * unusable;
        // exact-fit bonus
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect slot for next item
        } else if post_residual >= next_item_size {
            score -= 8.0;  // next item still fits here
        } else {
            score += 5.0;  // next item won't fit in this bin
        }
    }

    // Open-bin pressure: discourage scattering across many bins;
    // prefer filling existing bins when several are open.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 4.0 * pressure * (bin_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate (bin_residual == bin_capacity): make it unattractive
    // unless the item barely fits anywhere else / residual context says so.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * (open_bins_count as f64).max(1.0);
        // if mean residual across open bins is small, opening fresh is fine
        score -= (mean_residual / 10.0).min(15.0);
    }

    // Mild late-stream tightening: waste matters more as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step match: residual equals next item exactly.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff * diff);
        if post_residual == next_item_size {
            score -= 25.0; // exact 2-step closure bonus
        }
        // Penalize residuals too small to ever be useful (dead space)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 50.0;
    }

    // Reward bins whose residual is large relative to mean (keeps big bins flexible)
    score -= 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize so we only open when fits are poor
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * item_size as f64;
        // But if no existing bin fits well (many dead-space bins), opening is fine
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight pressure to close bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post_residual.
    let pr = post_residual as f64;
    score -= 40.0 * (1.0 - pr / bin_capacity as f64).powi(3);

    // Exact or near-exact fit is gold.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if next_item_size > bin_residual && bin_residual >= item_size {
            // This bin cannot host the next item anyway; using it is safe.
            score -= 10.0;
        } else {
            score += 8.0;
        }
    }

    // Last chance bin: strongly favor using the only fitting bin to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize spreading across many open bins when mean residual is high.
    score += open_bins_count as f64 * 0.5;
    score += (mean_residual - pr).abs() * 0.2;

    // Time horizon: early on, be more willing to open new bins (favor tight packing later).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    // New-bin candidate: only attractive when no good fit exists (post_residual large elsewhere).
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, offset if this bin is the only option.
        score = bin_capacity as f64 + 20.0;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, small residuals are acceptable; late, they become dead space.
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * 3.0;
    score += poly * cap * 0.35;

    // Reward tight fits (small post_residual) increasingly over the stream.
    score -= (1.0 - norm_post) * (1.0 - norm_post) * (0.5 + progress) * 4.0;

    // Last-chance bin: strongly favor using it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + 10.0 * progress;
    }

    // Penalize opening new bins when many bins already exist, scaled by stream progress.
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64).ln().max(1.0);
        score += cap * (0.25 + 0.35 * progress) * crowd * 0.3;
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 * (1.0 - post / (next_item_size as f64 + post));
    } else if next_item_size > 0 {
        // Next item won't fit here: slight penalty proportional to leftover.
        score += 2.0 * norm_post * (1.0 + progress);
    }

    // Mean residual alignment: prefer bins whose residual stays near the mean.
    let dev = (post - mean_residual).abs();
    score += dev * 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits (0) heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 50.0 - post_residual as f64;
    }

    // Modulo-class logic on post_residual: dead space in [1..10] is worst,
    // residues divisible by small harmonics (25/50) remain reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 50 == 0 {
            score -= 20.0;
        } else if pr % 25 == 0 {
            score -= 10.0;
        } else if pr < 10 {
            score += 30.0; // tiny unusable sliver
        }
    }

    // Integer-division thresholds: does post_residual fit next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // harmonic pairing: post_residual exactly equals next item
            if post_residual == next_item_size {
                score -= 60.0;
            } else {
                // leftover after hypothetical next placement
                let l = post_residual - next_item_size;
                if l == 0 {
                    score -= 40.0;
                } else if l <= 10 {
                    score += 10.0;
                }
            }
        } else {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly prefer using it rather than opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly unless current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 40.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        }
    }

    // Capacity-fraction coupling: reward filling toward harmonic fractions.
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    let frac = (fill * 4.0).round() / 4.0; // nearest quarter of capacity
    score -= frac * 8.0;

    // Stream progression: later in stream, tighten packing (prefer tight fits).
    let t = step_index as f64 / (total_items.max(1) as f64);
    score += t * (post_residual as f64) * 0.5;

    // Prefer bins below mean residual (more full bins first).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a future item (min item size 1, but practically < ~12) are waste.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0 + (12 - post_residual) as f64 * 8.0;
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Prefer bins whose residual tightly matches the item (good fit shape).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
        } else if post_residual > 0 {
            score += 12.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Pressure from many open bins: discourage spreading across bins,
    // favor filling existing bins when open_bins_count is high.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (open_bins_count as f64).ln() * (2.0 + 4.0 * progress);

    // New-bin candidate: baseline so it is only chosen when existing bins
    // are poor fits (their dead-space penalties push them above this).
    if bin_residual == bin_capacity {
        score = 55.0 + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 8.0; // pairing potential makes a fresh bin attractive
        }
        if fitting_bins_count == 1 {
            score += 40.0; // never open a new bin when a last-chance bin exists
        }
    }

    // Mean-residual coupling: if mean residual is small, conserve space harder.
    score += (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits into post_residual exactly or well
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual as f64 - next_item_size as f64;
        score -= 50.0 * (1.0 - gap / bin_capacity as f64);
        if gap == 0.0 {
            score -= 500.0; // chain perfect fit
        }
    } else if next_item_size > post_residual {
        // dead space relative to lookahead: penalize leftover that next item can't use
        score += 0.5 * post_residual as f64;
    }

    // Tight-fit reward: small post_residual relative to item size
    score -= 2.0 * (item_size as f64 / bin_capacity as f64) * (bin_capacity as f64 - post_residual as f64);

    // Last-chance bin: strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large or fits are bad
    if bin_residual == bin_capacity {
        score += 80.0;
        if item_size >= 50 {
            score -= 60.0; // big items okay in fresh bin
        }
        if next_item_size > 0 && next_item_size > bin_residual - item_size.min(bin_residual) {
            score -= 30.0;
        }
    }

    // Relative to mean residual: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference to fill older/more-filled bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly prefer bins whose residual is exactly consumed.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tightness: reward small post-residuals non-linearly (dead-space penalty).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * tightness * tightness;

    // Lookahead: if the next item fits in the post-residual, this bin remains useful.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.5 * next_item_size as f64;
        } else {
            // Post-residual too small for the known next item: dead space risk.
            score += 15.0;
        }
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 400.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer reusing open bins in general; opening a new bin must earn it.
        score += 80.0 + 2.0 * open_bins_count as f64;
        // Open a new bin only when the item fits nowhere well (large item, few fits)
        // or when open bins are nearly full on average.
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        if mean_residual < 25.0 {
            score -= 60.0;
        }
        // Late in the stream, consolidation matters more; avoid spreading.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    } else {
        // Reusing a bin with residual close to mean residual keeps balance.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.3 * dev;
    }

    // Early stream: allow more bins open (future flexibility), reward reuse mildly later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    // Smooth non-linear coupling: quadratic post-residual modulated by progress
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);
    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * progress;
    // Penalize residual that is unusable for the next item (smooth logistic-style term)
    if next_item_size > 0 && next_item_size <= bin_capacity {
        let fit_gap = (next_item_size as f64 - pr).abs();
        let unusable = 1.0 - (1.0 + (-fit_gap / 15.0)).recip();
        score += 10.0 * unusable * (0.3 + 0.7 * progress);
    }
    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - norm_pr);
    }
    // Mild penalty for spreading across many open bins when residuals are large
    let mean_norm = mean_residual / cap;
    score += 2.0 * mean_norm * (open_bins_count as f64).sqrt() * (1.0 - progress);
    // Prefer bins with residual close to mean (balance), smooth Gaussian coupling
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual by integer division thresholds
    let pr = post_residual;
    if pr == 0 {
        score -= 50.0; // perfect fit is excellent
    } else {
        // dead space penalty grows quadratically for small unusable residuals
        if pr < 10 {
            score += (10 - pr) as f64 * 2.5;
        }
        // harmonic class of the residual (mod-10 classes)
        let class = pr / 10;
        score += class as f64 * 1.5;

        // Lookahead: does next item fit into post_residual?
        if next_item_size > 0 && next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            // reward exact or near-exact lookahead fit
            score -= 12.0 * (1.0 - slack / cap);
            if slack == 0.0 {
                score -= 20.0;
            }
        } else if next_item_size > 0 {
            // next item won't fit here; penalize proportionally to wasted space
            score += 6.0;
        }
    }

    // Tight fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: empty bin should only win when it's genuinely better
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 30.0;
        // cheaper to open new bin when few open bins or late in stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * progress;
        if open_bins_count == 0 {
            score -= 30.0; // must open a bin
        }
        // opening a new bin is attractive if item is large relative to capacity
        score -= 10.0 * (item_size as f64 / cap);
        // large item leaves harmonic-friendly residual? prefer new bin then
        if pr % 10 == 0 && pr > 0 {
            score -= 6.0;
        }
    } else {
        // prefer bins with residuals in harmonic alignment with item size
        let r = bin_residual - item_size;
        if r > 0 && item_size > 0 && r % item_size == 0 {
            score -= 8.0; // residual divisible by item: future items may nest
        }
        // mild preference for bins below mean residual (denser bins)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 1.5;
        }
    }

    // penalize leaving residual that no typical small item (1..10) can use
    if pr > 0 && pr < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below the minimum plausible item size) are heavily penalized.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0;
    } else if (post_residual as f64) < 20.0 {
        score += 25.0;
    } else if (post_residual as f64) < 35.0 {
        score += 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Coupling with lookahead: if the next item fits exactly into the post
    // residual, this placement chains nicely — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit into post residual but this bin could have
    // held it after placement, mild penalty for breaking a chain.
    if next_item_size > post_residual && next_item_size > bin_residual {
        score += 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are terrible (item barely fits nowhere well) or the item
    // is large and would leave a big residual anyway.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, scaled by open-bin pressure.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // Large items fit perfectly in a fresh bin; encourage that.
        if item_size >= 70 {
            score -= 25.0;
        } else if item_size >= 50 {
            score -= 10.0;
        }
        // If the next item pairs well with this one (sums near capacity),
        // opening a fresh bin is good.
        if next_item_size > 0 && item_size + next_item_size >= 90 {
            score -= 15.0;
        }
        // Late in the stream, avoid spreading across too many bins.
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress;
    } else {
        // Mild reward for filling existing bins deeper (less residual left
        // relative to mean residual of open bins).
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.1;
        // Open-bin pressure: with many open bins, favor consolidation.
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward near-perfect fits: penalize small post_residual more strongly (non-linear).
    let post_f = post_residual as f64;
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else {
        score += (post_f * post_f) / cap; // quadratic dead-space penalty
    }

    // 2-step lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item fills the leftover
            let fill_ratio = next_f / post_f.max(1.0);
            score -= 10.0 * fill_ratio;
        } else {
            // next item cannot use this leftover; penalize leftovers smaller than any plausible item
            let gap = next_f - post_f;
            score += gap.min(50.0) * 0.3;
        }
        // If next item fits current residual but not post residual, prefer keeping more space
        if next_item_size > post_residual && next_item_size <= bin_residual {
            score += 8.0;
        }
    }

    // Compare post_residual against mean residual across open bins: leaving residual far below
    // mean wastes capacity; staying near mean is balanced.
    let dev = post_f - mean_residual;
    score += 0.15 * dev.abs();

    // Last-chance bin: strongly prefer using the only bin that fits, avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // New-bin candidate: penalize opening a new bin unless no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        } else if item_size as f64 / cap > 0.7 {
            score -= 10.0; // big item: fresh bin acceptable
        }
    }

    // Early in the stream, be slightly more willing to open bins for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Many open bins: discourage spreading, favor tight packing of existing bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 3.0 * tight * tight;

    // Penalize dead space: residuals too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: bonus if next item fits in post_residual (chaining)
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 8.0 + 0.1 * next_item_size as f64;
    }
    // Penalize if next item cannot use the leftover space
    if next_item_size > 0 && (next_item_size as u32) > post_residual && post_residual > 0 {
        score += 0.05 * post_residual as f64;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless no good fit exists
    if bin_residual == bin_capacity {
        let mut base = 30.0;
        if fitting_bins_count > 0 {
            // discourage new bin more when existing fits are decent
            base += 10.0 * (1.0 - (bin_residual - item_size) as f64 / cap);
        }
        // late in stream, prefer consolidating
        let progress = step_index as f64 / total_items.max(1) as f64;
        base *= 1.0 + progress;
        score += base;
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing
    let residual_gap = mean_residual - post_residual as f64;
    score += 0.3 * residual_gap;
    score += 0.1 * open_bins_count as f64 * (1.0 - tight);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fills (minimize post_residual aggressively);
    // later, tolerate moderate residuals but punish large dead space more.
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * (1.0 - progress);
    score += 40.0 * poly;

    // Reward near-perfect fits, stronger as the stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * tightness.powi(3) * (0.5 + progress);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0 + 20.0 * progress;
    }

    // Penalize opening a new bin when open bins fit reasonably well.
    if bin_residual == bin_capacity {
        let new_bin_penalty = 30.0 + 50.0 * progress + 3.0 * open_bins_count as f64;
        let fit_quality = if fitting_bins_count > 0 {
            let best_like = (mean_residual - item_size as f64).abs();
            best_like / cap
        } else {
            1.0
        };
        score += new_bin_penalty * (1.0 - 0.5 * fit_quality);
    }

    // Lookahead coupling: if next item fits the resulting residual, reward it smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = (pr - nx) / cap;
            score -= 15.0 * (1.0 - slack).powi(2) * (0.4 + 0.6 * progress);
        } else {
            score += 5.0 * ((nx - pr) / cap);
        }
    }

    // Mild preference for bins with residuals near the mean (balanced packing).
    score += 0.05 * ((bin_residual as f64 - mean_residual) / cap).powi(2) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quantization.
    // Residuals in (0..=10) are "prime dead space" - excellent packing.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr <= 10 {
        score -= 35.0;
    } else if pr <= 20 {
        score -= 15.0;
    } else {
        // Larger residuals: penalize by how far they are from a "useful" class
        // (residuals divisible by small harmonics 10/20 are reusable).
        let reusable = (pr % 10 == 0) as f64 * 8.0 + (pr % 20 == 0) as f64 * 6.0;
        score -= reusable;
        // Fractional waste penalty: quadratic in residual beyond 40
        if pr > 40 {
            score += 0.35 * (pr as f64 - 40.0);
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size <= pr {
            // Harmonic compatibility: next item leaves again small residue
            let pr2 = pr - next_item_size;
            if pr2 <= 10 { score -= 20.0; }
            else if pr2 <= 25 { score -= 8.0; }
        } else {
            // Next item cannot use this residual: mild penalty proportional to wasted harmony
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a bin should only win when no open bin
    // offers a decent fit, or when the item is large and open bins would leave bad residue.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = cap * 0.55; // 55
        // Late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
        // Many open bins: discourage opening another
        score += 2.0 * (open_bins_count as f64).sqrt() * 3.0;
        // If the current bin is the only fitting bin, opening a new bin is wasteful
        if fitting_bins_count == 1 {
            score += 40.0;
        }
        // If mean residual across open bins comfortably fits the item, don't open new
        if mean_residual >= item_size as f64 + 5.0 {
            score += 20.0;
        }
        // Large items early: opening a fresh bin can be fine
        if item_size >= 70 && progress < 0.5 {
            score -= 15.0;
        }
    }

    // Small global tie-breaker toward bins with residual close to item size
    score += 0.05 * ((bin_residual as f64 - item_size as f64).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to be useful later are heavily penalized.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
