    }

    // Squared tightness reward: filling a bin almost completely is strongly favored.
    score -= 0.15 * (post_residual as f64).powi(2);

    // Open-bin pressure: discourage spreading across too many bins.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
