    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 8.0;
    }
    // If next item would NOT fit in post residual, mild penalty unless post residual is tiny anyway.
    if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 && post_residual >= 10 {
        score += 6.0;
    }

    // New-bin candidate handling: prefer existing bins unless current fit is very poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // If no existing bin fits well, opening a new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, opening bins is less costly (fewer future items to place).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it's a good consolidation target.
    score -= 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + 25.0 * (1.0 - progress);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits: reward proportionally to how tight the match is.
        let tightness = next_item_size as f64 / post_residual as f64;
        score -= 40.0 * tightness;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that cannot host the next item: penalize.
        score += 20.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Compare post_residual against mean residual: leaving more than average is wasteful.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let open_penalty = if open_bins_count > 0 { 55.0 + 10.0 * (open_bins_count as f64).ln() } else { -20.0 };
        score += open_penalty * (0.5 + 0.5 * progress);
        // But if item leaves a large hole in an existing bin, new bin becomes attractive.
        let hole = bin_residual - item_size;
        if hole > 0 {
            score -= 0.4 * hole as f64;
        }
    }

    // Slight reward for tight fits overall.
    score -= 0.3 * item_size as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit: reward small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 50.0;

    // Penalize wasting a large bin residual on a small item
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        // Extra reward if next item fills the bin nearly perfectly afterwards
        let after = post_residual - next_item_size;
        if after <= 10 {
            score -= 60.0;
        }
    }
    // Penalize if next item is slightly larger than post_residual (dead space trap)
    else if next_item_size > post_residual && next_item_size > 0 {
        score += 25.0;
    }

    // Time horizon: early in stream, be more selective (penalize loose fits more)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += tightness * (1.0 - progress) * 40.0;

    // Global state: many open bins with high mean residual -> encourage consolidation
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if no existing bin fits well, allow new bin
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Mild penalty for very large dead space left behind
    if post_residual > 0 && post_residual < 10 {
        score -= 20.0; // small unusable sliver is fine, actually reward it
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Smooth polynomial coupling with stream progress: waste matters more early (many items left),
    // small residuals are acceptable late
    let early = (1.0 - progress) * (1.0 - progress);
    score += early * pr_norm * 30.0;
    score -= progress * 5.0 * pr_norm * (1.0 - pr_norm);

    // Penalize dead space that no future item can plausibly use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += 4.0 * (nx - pr) / cap * (1.0 + early);
        } else {
            // reward bins that also fit the next item snugly
            score -= 3.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Prefer bins with residuals near the mean (keeps bin pool homogeneous),
    // penalize outliers via smooth quadratic divergence
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Mild penalty for spreading across too many open bins early
    score += 0.3 * open_bins_count as f64 * early;

    // New-bin candidate: only attractive when it truly helps (big item, few fitting bins)
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - item_size as f64 / cap) - 8.0 * (fitting_bins_count == 0) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is "useful" for future items.
    // Items in 1..100; small residuals (< 10) are nearly dead, mid residuals reusable.
    if post_residual == 0 {
        score -= 40.0; // perfect fit is best
    } else if post_residual < 10 {
        score += 25.0; // tiny dead space penalty
    } else {
        // reward residuals that are harmonic with common item sizes (multiples of 10, 20, 25, 50)
        let pr = post_residual;
        let harmonic = (pr % 10 == 0) as f64 * 8.0
            + (pr % 25 == 0) as f64 * 6.0
            + (pr % 50 == 0) as f64 * 4.0;
        score -= harmonic;
    }

    // Lookahead: bonus if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // reward tight coupling: next item leaves small second-order residual
            let r2 = post_residual - next_item_size;
            score -= 20.0 - (r2 as f64) * 0.15;
        } else {
            // next item won't fit here: slight penalty scaled by overshoot
            score += ((next_item_size - post_residual) as f64) * 0.08;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening new bin, less so early in stream or when many bins open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fit_quality = if fitting_bins_count > 0 {
            (mean_residual - item_size as f64).abs()
        } else {
            100.0
        };
        score += 35.0 - 20.0 * (1.0 - progress) - fit_quality.min(60.0) * 0.3;
    } else {
        // favor bins tighter than average
        score -= (mean_residual - bin_residual as f64) * 0.25;
    }

    // mild preference for fuller bins overall
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small for the smallest item (1)
    // are pure waste; penalize tiny gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Gap that exactly fits the lookahead item is very valuable.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 150.0;
    }
    // Gap that can still hold the next item is moderately good.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when existing
    // fits are truly bad; the penalty grows with open-bin pressure relief.
    if bin_residual == bin_capacity {
        score += 120.0 - (open_bins_count as f64).min(20.0) * 2.0;
        // Opening is more attractive early in the stream (room to consolidate later).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
    }

    // Mild pressure: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 0.5;

    // Slight preference for bins tighter than the average residual.
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact chaining with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack.min(30.0);
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(40.0);
        }
    }

    // Tight fits are valuable: reward small post_residual relative to item size
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 20.0;

    // Penalize dead space relative to mean residual of open bins
    if post_residual as f64 > mean_residual + 15.0 {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly so it is only chosen when fits are poor
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.1;
    }

    // Late in stream, prefer filling existing bins more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly reward near-perfect fits (small dead space, non-linear)
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(6);

    // Reward exact fits completely
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: reward bins whose leftover pairs well with the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect pairing for lookahead item
        } else if post_residual >= next_item_size {
            // leftover can still host the next item: mild reward scaled by slack
            score -= 10.0 * (post_residual as f64 / bin_capacity as f64);
        } else {
            // leftover too small for next item: penalize dead space unless tiny
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += 0.4 * (next_item_size as f64 - waste);
            }
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 50.0;
    } else if fitting_bins_count > 1 {
        // competition exists: mildly prefer tighter bins via residual tiebreak
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Penalize spreading across too many open bins when mean residual is low
    score += 0.15 * mean_residual * (1.0 - t);

    // Late in the stream: consolidate, prefer filling existing bins harder
    score += 20.0 * t * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when:
        //  - no existing bin fits well (post_residual here equals capacity - item),
        //  - or many bins already open and this item would leave bad waste elsewhere.
        let base_new = 60.0 + 0.5 * item_size as f64;
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        let congestion = if open_bins_count > 4 { 10.0 } else { 0.0 };
        score = base_new + pressure + congestion - 25.0 * t;
        // A new bin is great if the item nearly fills it (large item in fresh bin)
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = post * (1.0 + 0.8 * norm_post * norm_post);

    // Stream progress coupling: later in the stream, penalize wasted space more strongly
    let progress_weight = 0.5 + 1.5 * t * t;
    score += norm_post * progress_weight * 20.0;

    // Perfect-fit reward (smooth bump near zero residual)
    let perfect = (-norm_post * 12.0).exp();
    score -= 15.0 * perfect;

    // Lookahead coupling: reward if post_residual accommodates next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 10.0 * (1.0 - slack) * (1.0 - t);
        } else {
            let gap = (nxt - post) / cap;
            score += 8.0 * gap * gap;
        }
    } else {
        // last item: strongly prefer any fit
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 - 0.5 * t);
    }

    // Mean residual interaction: penalize bins far from mean residual (fragmentation)
    let dev = (post - mean_residual) / cap;
    score += 6.0 * dev * dev * (0.5 + t);

    // New-bin candidate: make it costly unless post_residual is large enough to be useful
    if bin_residual == bin_capacity {
        let usable = (norm_post - 0.2) * 30.0;
        score += 18.0 - usable.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the post residual: classify leftover space by
    // integer-division thresholds relative to capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Class A: leftover <= 10 (nearly perfect) -> strong reward.
    if post_residual <= 10 {
        score -= 60.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Class B: leftover in (10, 20] -> moderate reward.
    else if post_residual <= 20 {
        score -= 25.0 + (20 - post_residual) as f64 * 2.0;
    }
    // Class C: leftover in (20, 30] -> small reward.
    else if post_residual <= 30 {
        score -= 8.0;
    }
    // Class D: large leftover (dead space) -> penalty scaled by capacity fraction.
    else {
        score += (post / cap) * 30.0;
    }

    // Modulo arithmetic on residual: residuals congruent to small values mod 10
    // pair well with typical item sizes; reward low-residue classes.
    let rmod = post_residual % 10;
    score -= (5 - ((rmod as i32) - 5).abs()) as f64 * 1.5;

    // Lookahead coupling: if next item fits exactly into post_residual,
    // this bin becomes a two-item chain -> big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            let chain_post = post_residual - next_item_size;
            if chain_post <= 10 {
                score -= 45.0;
            } else if chain_post <= 25 {
                score -= 18.0;
            } else {
                score += chain_post as f64 * 0.3;
            }
        } else {
            // Next item cannot follow here: mild penalty proportional to gap.
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer denser bins (below-mean residual) slightly.
    score += (post - mean_residual) * 0.15;

    // New-bin candidate: neutral-ish baseline, slightly above a good fit,
    // so a new bin is opened only when no open bin fits reasonably.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=12)
    // are "perfect", moderate gaps are penalized heavily if unusable by the next item.
    if post_residual == 0 {
        score -= 50.0; // perfect fit
    } else if post_residual < 10 {
        score -= 20.0; // near-perfect, dead space is tiny
    } else if next_item_size > 0 && post_residual < next_item_size {
        // gap too small for the lookahead item => true dead space
        score += 15.0 + 0.5 * post_residual as f64;
    }

    // Reward tight fits relative to item size
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Lookahead synergy: if the post residual exactly accommodates the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 12.0; // sets up a near-perfect follow-up placement
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer filling existing.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score += 5.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when current bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation > 0.5 {
            score -= 30.0 * (fragmentation - 0.5); // open fresh bin when open bins are half-empty
        } else {
            score += 40.0; // discourage needless new bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward chains: next item exactly filling post_residual is ideal.
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_gap = (post_residual - next_item_size) as f64;
        score -= 60.0 - 2.0 * fit_gap.min(30.0);
        // Perfect chain: post_residual == next_item_size
        if post_residual == next_item_size {
            score -= 40.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here: penalize, more so for large dead space.
        score += 15.0 + 0.3 * post_residual as f64;
    }

    // Penalize high fragmentation relative to mean residual of open bins.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Discourage spreading across many bins when a tight fit exists.
    score += 0.5 * open_bins_count as f64;

    // Slight bias to fill bins later in the stream (consolidate).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small unusable leftovers relative to typical item scale
        let small_item = next_item_size.min(item_size).max(1) as f64;
        if (post_residual as f64) < small_item {
            score += 50.0;
        }
        // Reward tight fits: fraction of bin used by this item
        let tightness = item_size as f64 / bin_capacity as f64;
        score -= 30.0 * tightness * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 80.0;
            // Extra reward if next item also nearly fills the remainder
            let rem = post_residual - next_item_size;
            if rem <= 10 {
                score -= 60.0;
            }
        } else {
            // Next item won't fit here; penalize wasting large residual
            score += 10.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer filling bins as much as possible
        score -= 20.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0;
    }

    // Crowding: many open bins -> prefer consolidating into bins with low residual
    if open_bins_count > 2 {
        let crowding = open_bins_count as f64;
        score -= 5.0 * (post_residual as f64 / bin_capacity as f64) * (crowding / (crowding + 5.0));
    }

    // Time horizon: early in stream, allow new bins freely; late, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below mean, it's a good target
    let diff = mean_residual - post_residual as f64;
    score -= 8.0 * diff / bin_capacity as f64;

    // New-bin candidate handling: only attractive when current fit is terrible
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        // Base penalty for opening a new bin
        let mut new_bin_score = 40.0 + waste * 0.3;
        // If no open bin fits (this is the only option), it's forced
        if fitting_bins_count == 0 {
            new_bin_score -= 1000.0;
        }
        // Early stream: new bins are cheaper; late stream: expensive
        new_bin_score += 20.0 * (1.0 - progress);
        // If lookahead item is large and would need its own bin anyway
        if next_item_size > post_residual && next_item_size > 0 {
            new_bin_score -= 30.0;
        }
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Tight fits rewarded: penalize residual quadratically, amplified by progress.
    score += 12.0 * pr_norm * pr_norm * (0.5 + progress);

    // Perfect/near-perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead coupling: reward if next item fits the post-residual smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let coupling = (pr - nxt) / cap;
            score -= 18.0 * (1.0 - coupling) * (1.0 - progress);
        } else {
            // Dead space relative to next item penalized.
            let gap = (nxt - pr) / cap;
            score += 10.0 * gap * gap;
        }
    }

    // Last-chance bin: strong reward to use it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    } else {
        // Crowding: prefer bins in a moderately filled fleet.
        score += 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Prefer bins with residual close to item size relative to fleet mean.
    let fit_ratio = (bin_residual as f64 - item_size as f64) / cap;
    score += 6.0 * (fit_ratio - mean_residual / cap).abs();

    // Mild preference early on for keeping large residuals, later for filling.
    score += 8.0 * pr_norm * (1.0 - progress);

    // New-bin candidate: penalize opening a fresh bin unless item is large
    // or no good fit exists.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        score += 35.0 - 30.0 * large_item * large_item - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals grouped by modular classes
    // (0 = perfect fit, small = highly usable, large = dead space).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 0: perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        // Tiny leftover, nearly perfect: strong reward.
        score -= 15.0;
    } else if post_residual % 10 == 0 {
        // Harmonic class: residual divisible by 10 aligns with common item sizes.
        score -= 6.0;
    }

    // Penalize residuals in "dead zones" that few item sizes can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // unusable sliver
    }

    // Fraction of bin wasted by this placement.
    let waste_frac = pr / cap;
    score += 20.0 * waste_frac * waste_frac;

    // Last-chance bin: if this is the only bin that fits, reward using it
    // heavily to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: empty bin gets a penalty unless the current bin
    // leaves a large unusable residual or no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual > 40 || (fitting_bins_count == 0);
        if poor_fit {
            score -= 12.0; // allow opening a new bin
        } else {
            score += 20.0; // discourage opening new bins when a decent fit exists
        }
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // reward strongly (chaining perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 10.0 {
                score -= 8.0;
            }
        } else {
            // Next item cannot fit here; leaving large residual is fine,
            // but leaving residual slightly below next item is wasted.
            if post_residual > 0 && post_residual < next_item_size {
                score += 5.0;
            }
        }
    }

    // Stream progression: early on, be conservative with bins; later,
    // tolerate more open bins and prioritize tight fits more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress;

    // Prefer bins with residual close to the mean (balance loads) mildly.
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // Mild penalty for accumulating many open bins when a fit exists.
    if bin_residual != bin_capacity && open_bins_count > 4 {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small for typical items are "dead space": penalize quadratically.
    if post_residual > 0 {
        // Treat gaps below ~20% of capacity as nearly unusable dead space.
        let dead_threshold = (bin_capacity as f64 * 0.2).max(20.0);
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64).powi(2) * 0.15;
        }
        // Perfect fit: strong reward.
        if post_residual == 0 {
            score -= 30.0;
        }
    }

    // --- Reward tight fits relative to item size ---
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 10.0;

    // --- Last-chance bonus: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // --- Lookahead coupling: if the next item fits the post-residual, reward this placement ---
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the lookahead item: penalize.
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // --- Open-bin pressure: discourage spreading across many open bins ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // --- Mean residual coupling: prefer bins whose residual is below average (more filled) ---
    if (bin_residual as f64) < mean_residual {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    } else {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when current bins fit poorly.
        // Base penalty so a fresh bin is chosen only for genuinely bad fits.
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        }
        // Late in the stream, opening new bins is less costly than dead space.
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 1000.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = post - nxt;
            // penalize leftover slack after chaining; small slack is good
            score += slack * 0.5;
            // bonus proportional to how much of the residual the next item consumes
            score -= (nxt / post.max(1.0)) * 20.0;
        } else {
            // next item cannot use this bin's residual: mild penalty scaled by gap
            score += (nxt - post).min(50.0) * 0.3;
        }
    }

    // Prefer bins whose residual is below the mean (denser bins) for tight packing.
    score += (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize tiny unusable dead space (< 10) unless it's a near-perfect fit.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Early in the stream, be slightly more willing to keep bins tight;
    // late in the stream, favor consolidating into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 10.0;
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Non-linear dead-space penalty: small residuals that no future item can fill are costly
        let r = post_residual as f64;
        score += (r / 10.0).powi(2) * 0.6;
    }

    // Lookahead: reward leaving space for the next item exactly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // residual too small for next item: penalize proportionally to wasted fraction
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.25;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when item fits poorly everywhere else
    if bin_residual == bin_capacity {
        let tight = post_residual == 0 || (next_item_size > 0 && post_residual == next_item_size);
        if tight {
            score -= 10.0; // opening fresh for a perfect-fill pattern is fine
        } else {
            score += 45.0 + (open_bins_count as f64) * 2.0;
            // early in stream, opening new bins is cheaper
            let progress = step_index as f64 / total_items.max(1) as f64;
            score -= 30.0 * (1.0 - progress);
        }
    }

    // Prefer bins tighter than average (best-fit flavor)
    let diff = bin_residual as f64 - mean_residual;
    score += diff * 0.15;

    // Slight preference for reusing existing bins over proliferation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Base: penalize leftover space (quadratic waste coupling)
    let mut score = post * post / cap;

    // Smooth progress coupling: later in stream, waste matters more
    score *= 0.5 + progress;

    // Reward tight fits (small post_residual relative to item)
    score -= (1.0 - post / cap) * fit_frac * cap * 0.5;

    // Lookahead: reward if next item fits in the post residual
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let lookahead_fit = next_item_size as f64 / cap;
        score -= lookahead_fit * cap * 0.35 * (1.0 + progress);
    }

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 0.6;
    }

    // Penalize bins far from mean residual (fragmentation avoidance)
    score += ((bin_residual as f64 - mean_residual) / cap).abs() * cap * 0.2;

    // New-bin candidate: penalize opening a new bin, but less late in stream
    // and less when the item is large (poor fit elsewhere likely)
    if bin_residual == bin_capacity {
        score += cap * (1.2 - 0.5 * progress) * (1.0 - fit_frac * 0.7);
    }

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.15 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals that are "nice" fractions of
    // capacity (0, 10, 20, 25, 50) are reusable; odd tiny residuals are dead space.
    let r = post_residual;
    if r == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else {
        let class_bonus = match r {
            1..=5 => -2.0,        // nearly dead, but tiny
            6..=9 => 8.0,         // awkward dead space
            10..=19 => -6.0,      // harmonic tenth-class, reusable
            20..=24 => -8.0,      // fifth-class
            25..=29 => -9.0,      // quarter-class
            30..=49 => -3.0,
            50..=74 => -10.0,     // half-class, very reusable
            _ => -4.0,
        };
        score += class_bonus;

        // Penalize non-harmonic residuals via modulo arithmetic on capacity.
        let m = r % 10;
        if m != 0 && m < 5 {
            score += 5.0; // ragged remainder, poor future fit probability
        }
    }

    // Lookahead coupling: reward bins whose post_residual can host next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * (next_item_size as f64);
        // Extra reward if post_residual exactly matches a harmonic bucket >= next item.
        if post_residual % 10 == 0 {
            score -= 4.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_capacity {
        // Next item won't fit here; penalize proportionally to wasted lookahead.
        score += 4.0 + 0.05 * (next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Scarcity pressure: many open bins -> prefer tightening existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let scarcity = open_bins_count as f64 / 8.0;
    score -= scarcity * (1.0 + progress);

    // Prefer bins tighter than the mean (best-fit flavor).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin is a decent fit (this call has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin: large, but reduced when current item
        // is large and would leave a harmonic residual anyway.
        let mut new_bin = 70.0;
        let pr = post_residual;
        if pr % 25 == 0 || pr % 10 == 0 {
            new_bin -= 12.0;
        }
        if fitting_bins_count == 0 {
            new_bin -= 40.0; // nothing else fits, must open
        }
        score += new_bin;
    }

    // Mild jitter-free tiebreak by residual itself.
    score += 0.01 * post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item (<= 10) are pure waste — penalize them heavily.
    if post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual <= 20 {
        // Small gap: risky, only useful for tiny future items.
        score += 6.0;
    } else if post_residual >= 50 {
        // Large remaining space is a flexible asset — reward it.
        score -= 8.0;
    }

    // Reward tight fits (low waste fraction of the bin).
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 10.0 * fill_ratio * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            // Next item cannot use this residual: dead space more likely.
            score += 2.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing
    // ones rather than spreading; a new empty bin candidate gets penalized when
    // open_bins_count is already high.
    let ob = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins are open or the item
        // fits poorly everywhere (this call sees fitting_bins_count).
        score += 12.0 + ob * 1.5;
        if fitting_bins_count <= 1 {
            score -= 15.0; // last-chance / poor fits elsewhere -> open new bin
        }
    } else if fitting_bins_count == 1 {
        // This is the only existing bin that fits — avoid opening a new bin.
        score -= 12.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already "cramped"; using it keeps other bins flexible.
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 0.05 * (mean_residual - res);
    } else {
        score += 0.05 * (res - mean_residual);
    }

    // Early-stream mild preference for keeping bins open (future flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 2.0 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match of post_residual with next item is gold.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        score -= 60.0 / (1.0 + diff as f64);
        // Exact lookahead match: massive reward.
        if post_residual == next_item_size {
            score -= 80.0;
        }
        // If the next item cannot fit into post_residual, penalize mildly
        // (dead space), scaled by how badly it misses.
        if next_item_size > post_residual {
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize waste.
        score -= 20.0;
    }

    // Reward tight fits relative to capacity (small post_residual is good).
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize post_residual that is small but not zero (unusable sliver),
    // especially if it is below the minimum item size.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative to mean residual: bins already more filled than average are
    // better targets (fill them first, keep emptier bins flexible).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): penalize so it is only chosen when all
    // fits are poor; the penalty shrinks late in the stream.
    if bin_residual == bin_capacity {
        score += 70.0 * (1.0 - 0.3 * progress);
        // If lookahead fits perfectly in a fresh bin, soften the penalty.
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0;
        }
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strong fit reward: quadratic bonus for tight packing
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Perfect fit gets a big discount
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: heavily reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (post_residual as f64 - next_item_size as f64 + 1.0).ln().max(0.0);
        } else {
            // penalize leaving a residual that barely fails the next item (dead space)
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < item_size as f64 {
                score += 8.0 * gap;
            }
        }
    }

    // Penalize wasting large bins on tiny items early; encourage consolidation
    if post_residual > 0 && post_residual < 10 {
        score += 10.0; // unusable sliver
    }

    // New-bin candidate logic: opening a new bin is only attractive when existing
    // residuals are poor fits or too many bins are already open
    if bin_residual == bin_capacity {
        let poor_fits = if fitting_bins_count >= 1 {
            let best_alt = if post_residual >= item_size { item_size as f64 } else { 0.0 };
            (bin_capacity as f64 - item_size as f64) - best_alt
        } else {
            0.0
        };
        let openness = mean_residual / bin_capacity as f64;
        // prefer new bin when mean residual is low (existing bins nearly full)
        score = score * 0.5 + 20.0 * (1.0 - openness) + 5.0 * poor_fits / bin_capacity as f64;
        // late in stream, be more conservative about opening bins
        score += 10.0 * progress;
    } else {
        // mild penalty scaled by how "average" this residual is vs mean
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Slight preference to fill bins with more residual when many bins open (bin count control)
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;
    // smooth polynomial coupling of post_residual with stream progress
    let prn = pr / cap;
    score += 18.0 * prn * prn * (0.5 + 0.5 * t);
    score -= 6.0 * prn * (1.0 - t) * (1.0 - t);
    // reward tight fits
    score -= 8.0 * (1.0 - prn) * (1.0 - prn);
    // lookahead: prefer leaving room for the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr + 0.5 >= nxt {
            score -= 5.0;
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }
    // discourage spreading across many bins when mean residual is small
    score += 0.4 * (open_bins_count as f64) * (mean_residual / cap).powi(2);
    // new-bin candidate: neutral-ish baseline with slight progress penalty
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * t;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space usefulness by modulo classes
    let pr = post_residual as f64;
    let small_dead = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += small_dead * 25.0;

    // Modulo-10 class: residuals that are multiples of 10 are more reusable
    let mod10 = post_residual % 10;
    score += (mod10 as f64) * 1.5;
    let mod5 = post_residual % 5;
    score += (mod5 as f64) * 0.8;

    // Lookahead: if next item fits in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 60.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item can't use this residual: penalize large wasted space
            score += 0.3 * pr;
        }
        // exact pairing reward
        if next_item_size == post_residual {
            score -= 150.0;
        }
    }

    // Last chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Prefer filling fuller bins relative to capacity fraction
    let fill_frac = (bin_residual as f64) / cap;
    score += fill_frac * 10.0;

    // New-bin candidate: make it moderately attractive only when current bin fit is bad
    if bin_residual == bin_capacity {
        // base penalty so it's not chosen over decent fits
        score = 55.0 + 0.4 * (item_size as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 30.0;
        }
        if open_bins_count == 0 {
            score -= 200.0;
        }
        // if no open bin fits well, opening new bin is fine
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Progression: tighten packing later in the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 5.0 * (pr / cap);

    // Mean residual coupling: penalize creating residual far below mean (fragmentation)
    if mean_residual > 0.0 {
        let dev = (pr - mean_residual).abs();
        score += 0.1 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 3.0 * (10 - post_residual) as f64;
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving a gap that the lookahead item can use.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap just barely below the next item (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Prefer bins with tighter residuals among fitting bins (best-fit sharpening).
    score += 0.15 * (bin_residual as f64 - item_size as f64);

    // Open-bins pressure: with many open bins, discourage opening yet another bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 2.5 * open_bins_count as f64 - 10.0 * progress;
        // Last-chance bin: strongly prefer using it over a new bin.
        if fitting_bins_count == 1 {
            score += 30.0;
        }
    } else if fitting_bins_count == 1 {
        // This open bin is the only one that fits: reward using it.
        score -= 15.0;
    }

    // Mild preference for bins below mean residual (consolidating fuller bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 100.0; // perfect two-item closure
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // penalize leftover after the lookahead item, super-linear in slack
            score += slack * slack * 0.05;
            // mild bonus if the lookahead item still fits at all
            score -= 3.0;
        } else {
            // next item won't fit here: penalize proportionally to the gap
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than the mean.
    let dev = mean_residual - post_residual as f64;
    score += dev * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is huge and no good fit exists.
    if bin_residual == bin_capacity {
        score += 15.0;
        if item_size >= 60 && (fitting_bins_count == 0 || next_item_size > post_residual) {
            score -= 20.0;
        }
    }

    // Slight preference for filling bins more completely as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_capacity - post_residual) as f64 * 0.1 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual), with mild nonlinearity.
    let tight = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tight * tight;

    // Penalize dead space that cannot fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: reward leaving space for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // placing here would strand the next item elsewhere; mild penalty
            score += 4.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln() * (mean_residual / bin_capacity as f64);
    score -= pressure * (1.5 + progress);

    // Late in the stream, consolidate aggressively.
    score -= 10.0 * progress * (1.0 - tight);

    // New-bin candidate: only attractive when no bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let best_possible = if item_size <= bin_capacity { item_size as f64 } else { 0.0 };
        let waste = bin_capacity as f64 - best_possible;
        score += 30.0 + waste * 0.3;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing big items together in fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    let mut score = post;

    // Non-linear waste penalty: dead space hurts quadratically, more as stream progresses.
    let waste = post / cap;
    score += 12.0 * waste * waste * (0.5 + progress);

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item / (item + post + 1.0)).powi(3);
    score -= 20.0 * tightness;

    // Coupling with mean residual: prefer bins whose residual is below mean (better packing).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev.abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: penalize leaving residual that barely misses the next item.
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).max(0.0);
        score += 4.0 * (gap / cap) * (1.0 - (gap / cap));
    }

    // Penalize opening a new bin when open bins could fit (encourage consolidation).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 8.0 + 2.0 * (open_bins_count as f64).sqrt() + 10.0 * (1.0 - progress);
        // But allow new bin if residual would be very small anyway (large item).
        score -= 6.0 * (item / cap);
    }

    // Mild consolidation pressure as stream progresses.
    score += progress * (post / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space classes: small residuals are unusable (item sizes >= 1).
        if post_residual < 10 {
            score += 30.0;
        } else if post_residual < 25 {
            score += 12.0;
        } else if post_residual < 50 {
            score += 4.0;
        } else {
            score -= 6.0;
        }
    }

    // Modulo arithmetic on post_residual: values divisible by common item
    // granularities (5, 10, 20) are more likely reusable.
    if post_residual % 10 == 0 {
        score -= 5.0;
    } else if post_residual % 5 == 0 {
        score -= 2.5;
    } else {
        score += 1.5;
    }

    // Integer-division thresholds: residual bucket via post_residual/25.
    let bucket = post_residual / 25; // 0..4
    score += bucket as f64 * -1.5;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
            // Harmonic coupling: next item leaves a divisible residual too.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 4.0;
            }
        } else {
            // Next item cannot use this bin's remainder: penalize small leftovers.
            if post_residual < next_item_size && post_residual < 20 {
                score += 8.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: neutral-ish, penalize when decent fits exist.
    if bin_residual == bin_capacity {
        score += 55.0;
        if fitting_bins_count <= 1 {
            score -= 70.0;
        }
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 25.0;
        }
    }

    // Tight-fit reward: item fills most of the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= fill * 10.0;

    // Late-stream consolidation: prefer compacting into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual - post_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are pure waste.
    let dead_threshold = 10u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 200.0 + (dead_threshold - post_residual) as f64 * 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 150.0;
    }

    // Reward residual that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Lookahead won't fit here: mild penalty, stronger if gap becomes dead space.
            score += 10.0;
            if post_residual < dead_threshold {
                score += 50.0;
            }
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 40.0;

    // Open-bin pressure: with many open bins, discourage opening new ones implicitly
    // by penalizing high residual spread relative to mean.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins already open and mean residual is large.
        score += 60.0 + open_bins_count as f64 * 8.0 + mean_residual * 0.5;
    } else {
        // Existing bin: slight reward when open_bins_count is high (consolidate).
        score -= open_bins_count as f64 * 1.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Early-stream: allow slight exploration; late-stream: tighten consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: squash tiny post-residuals hard.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        let pr = post_residual as f64;
        score += (pr / bin_capacity as f64) * 20.0;
        // Penalize residuals too small for the minimum item size (dead space).
        if post_residual < 10 {
            score += 15.0;
        }
    }

    // 2-step lookahead: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
            if next_item_size == post_residual {
                score -= 20.0; // exact 2-item chain fill
            }
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.15;
        }
        // Discourage wasting a large residual when next item is small.
        let _ = nxt;
    } else {
        // Last item: strongly prefer tightest fit.
        score -= 10.0;
    }

    // Relative-to-mean residual coupling: prefer bins below mean residual
    // (larger residual bins) so we keep small-residual bins for small items.
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = (bin_capacity - item_size) as f64;
        score = 60.0 + poor_fit * 0.5;
        // Allow new bin if no open bin fits well (post_residual large relative to item).
        if next_item_size > 0 && post_residual > 0 {
            score -= 5.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

