    // creating small post-residuals (long future), later accept them.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual > 0 && post_residual < 20 {
        score += (1.0 - progress) * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early in the stream, prefer tight fills less aggressively; later, demand tight fits.
    let tightness_weight = 0.4 + 1.6 * progress * progress;
    score += tightness_weight * norm_post * norm_post * cap * 0.5;

    // Penalize dead space relative to mean residual across open bins (smooth quadratic coupling).
    let dead = post - mean_residual;
    score += 0.05 * dead * dead / cap;

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more when good existing fits exist.
    if bin_residual == bin_capacity {
        let existing_fit = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        score += 8.0 + 4.0 * existing_fit + 10.0 * (1.0 - progress);
    } else {
        // Reward bins that fit among many candidates slightly less crowded choice.
        if fitting_bins_count > 1 {
            score += 0.5 * (fitting_bins_count as f64 - 1.0).ln();
        }
    }

    // Lookahead coupling: favor post_residual that still accommodates the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = post - nxt;
            score -= 3.0 * (1.0 - slack / cap);
        } else {
            // Next item won't fit here; penalize proportionally to the shortfall.
            score += 2.0 * (nxt - post) / cap * 10.0;
        }
    }

    // Mild penalty for too many open bins with large residuals (fragmentation pressure).
    score += 0.02 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of post_residual: residuals that are "usable" sizes
        // (divisible into capacity cleanly) are less wasteful.
        let pr = post_residual;
        // Dead-space penalty grows when residual is small but nonzero
        // (unusable sliver) unless it matches a plausible next item size.
        if pr < 10 {
            score += 200.0; // sliver: nearly dead space
        }
        // Harmonic classes: residuals that divide capacity (20,25,50,etc.)
        // are more likely reusable.
        let harmonic = (bin_capacity % pr == 0) as f64 * 60.0;
        score -= harmonic;

        // Next-item compatibility: if the next item fits in post_residual,
        // reward; if it fits but barely (leaving another sliver), dampen.
        if next_item_size > 0 {
            if next_item_size <= pr {
                let next_post = pr - next_item_size;
                let compat = if next_post == 0 { 400.0 }
                             else if next_post < 10 { 40.0 }
                             else { 150.0 };
                score -= compat;
            } else {
                // next item won't fit here; residual becomes holding space
                score += 30.0;
            }
        }

        // Last-chance bin: strongly prefer using it to avoid opening a bin.
        if fitting_bins_count == 1 && bin_residual < bin_capacity {
            score -= 250.0;
        }

        // Prefer bins with residuals near the item size (tight fit).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 50.0;

        // Many open bins: discourage spreading into low-fill bins.
        if open_bins_count > 4 {
            let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
            score -= fill_ratio * 40.0;
        }

        // New-bin candidate: only attractive when no open bin is a decent fit
        // (i.e., this call has full residual and open bins are fragmented).
        if bin_residual == bin_capacity {
            if mean_residual < item_size as f64 * 0.5 {
                score -= 120.0; // fragmentation: fresh bin better
            } else {
                score += 80.0; // prefer reusing open bins
            }
        }

        // Late in the stream: consolidate, avoid opening new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if bin_residual < bin_capacity {
            score -= progress * 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalize residuals that cannot fit the smallest plausible item
    if post_residual > 0 && post_residual < item_size.min(10) {
        score += 25.0;
    }

    // Reward tight fits
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: reward if post_residual can hold next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if post_residual is small but nonzero and cannot hold next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: strong reward to use the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }
    // Many fitting bins: mild penalty to prefer best fit discrimination
    if fitting_bins_count > 1 {
        score += 5.0;
    }

    // New-bin candidate: penalize unless current bins are crowded or fit is terrible
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * mean_residual < bin_capacity as f64 * 0.5;
        let poor_fit = bin_residual < item_size;
        if !(crowded || poor_fit || fitting_bins_count == 0) {
            score += 35.0;
        }
    }

    // Progress-based tightening: later in stream, prefer conserving space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * (0.3 + progress * 0.7);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect matches (small gap that next item can't fill but is close).
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 10.0 {
            score -= 40.0 - gap * 3.0;
        }
    }

    // Penalize if next item cannot fit in post_residual (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Compare against mean residual across open bins: prefer leaving residuals
    // near the mean (balanced packing), penalize extremes.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Tight fit reward: small post_residual is generally good.
    if post_residual <= 5 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current residuals are all poor fits (large waste if we place here).
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: waste of a full capacity slot.
        score += 45.0;
        // If many bins are open and mean residual is large, opening a new bin
        // is relatively more attractive (better isolation of large future items).
        score -= (mean_residual / 10.0) * 0.5 + open_bins_count as f64 * 0.3;
        // Perfect lookahead fit in a fresh bin for the next item.
        if next_item_size > 0 && bin_capacity as f64 - next_item_size as f64 >= post_residual as f64 {
            score += 5.0;
        }
    }

    // Late in the stream, consolidate harder (fewer bins matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}
